{
  "name": "工安耗材管理系統 (Safety Inventory Pro)",
  "description": "這是一個專業的工安設備與耗材管理系統，提供資料庫管理、庫存統計及自動化領用單功能，協助企業即時監控工安資源。"
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Category {
  PROTECTION = '個人防護 (PPE)',
  FIRE_SAFETY = '消防安全',
  FIRST_AID = '急救耗材',
  SIGNAGE = '標誌警告',
  TOOL = '工具設備',
  OTHER = '其他'
}

export interface InventoryItem {
  id: string;
  name: string;
  category: Category;
  unit: string;
  quantity: number;
  minStock: number;
  description: string;
  lastUpdated: number;
}

export type TransactionType = 'IN' | 'OUT';

export interface Transaction {
  id: string;
  itemId: string;
  itemName: string;
  type: TransactionType;
  quantity: number;
  person: string;
  reason: string;
  timestamp: number;
}

export interface DashboardStats {
  totalItems: number;
  lowStockItems: number;
  monthlyOutbound: number;
}

import { GoogleGenAI } from "@google/genai";
import { InventoryItem } from "../types";

export const getInventoryInsights = async (items: InventoryItem[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const lowStock = items.filter(i => i.quantity <= i.minStock);

  const prompt = `
    這是一個工安耗材管理系統。
    當前庫存清單: ${JSON.stringify(items.map(i => ({ name: i.name, qty: i.quantity, min: i.minStock })))}
    庫存不足的項目: ${JSON.stringify(lowStock.map(i => i.name))}

    請以專業工安管理員的身份，提供 3 點具體的採購或管理建議。請用繁體中文回答，語氣要簡潔專業。
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "無法獲取建議";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "AI 助理暫時無法提供建議，請檢查您的庫存警示。";
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  AlertTriangle,
  ArrowDownCircle,
  ArrowUpCircle,
  Sparkles,
  Search,
  CheckCircle2,
  X
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  Cell
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_items';
const STORAGE_KEY_LOGS = 'safeman_logs';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'issuance' | 'history'>('dashboard');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [aiAdvice, setAiAdvice] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Persistence
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedLogs) setLogs(JSON.parse(savedLogs));
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
    localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
  }, [items, logs]);

  // Inventory Handlers
  const addItem = (newItem: Omit<InventoryItem, 'id' | 'lastUpdated'>) => {
    const item: InventoryItem = {
      ...newItem,
      id: crypto.randomUUID(),
      lastUpdated: Date.now(),
    };
    setItems(prev => [...prev, item]);
  };

  const deleteItem = (id: string) => {
    if (confirm('確定要刪除此項目嗎？')) {
      setItems(prev => prev.filter(i => i.id !== id));
      setLogs(prev => prev.filter(l => l.itemId !== id));
    }
  };

  const createTransaction = (
    itemId: string, 
    type: TransactionType, 
    qty: number, 
    person: string, 
    reason: string
  ) => {
    const targetItem = items.find(i => i.id === itemId);
    if (!targetItem) return;

    if (type === 'OUT' && targetItem.quantity < qty) {
      alert('庫存不足！');
      return;
    }

    const updatedItems = items.map(i => {
      if (i.id === itemId) {
        return {
          ...i,
          quantity: type === 'IN' ? i.quantity + qty : i.quantity - qty,
          lastUpdated: Date.now()
        };
      }
      return i;
    });

    const newLog: Transaction = {
      id: crypto.randomUUID(),
      itemId,
      itemName: targetItem.name,
      type,
      quantity: qty,
      person,
      reason,
      timestamp: Date.now()
    };

    setItems(updatedItems);
    setLogs(prev => [newLog, ...prev]);
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    const advice = await getInventoryInsights(items);
    setAiAdvice(advice);
    setIsAiLoading(false);
  };

  // Views
  const DashboardView = () => {
    const lowStockCount = items.filter(i => i.quantity <= i.minStock).length;
    const chartData = items.slice(0, 8).map(i => ({ name: i.name, 庫存: i.quantity, 安全線: i.minStock }));

    return (
      <div className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <div className="flex items-center justify-between mb-2">
              <span className="text-gray-500 text-sm font-medium">總項目數</span>
              <Package className="text-blue-500" size={20} />
            </div>
            <p className="text-3xl font-bold text-gray-800">{items.length}</p>
          </div>
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <div className="flex items-center justify-between mb-2">
              <span className="text-gray-500 text-sm font-medium">低庫存警示</span>
              <AlertTriangle className="text-amber-500" size={20} />
            </div>
            <p className="text-3xl font-bold text-gray-800">{lowStockCount}</p>
          </div>
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <div className="flex items-center justify-between mb-2">
              <span className="text-gray-500 text-sm font-medium">本月異動紀錄</span>
              <History className="text-indigo-500" size={20} />
            </div>
            <p className="text-3xl font-bold text-gray-800">{logs.length}</p>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <h3 className="text-lg font-semibold mb-6">庫存分佈概況</h3>
            <div className="h-64">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={chartData}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} />
                  <XAxis dataKey="name" />
                  <YAxis />
                  <Tooltip />
                  <Bar dataKey="庫存" fill="#3b82f6" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          <div className="bg-gradient-to-br from-indigo-50 to-blue-50 p-6 rounded-xl shadow-sm border border-blue-100 relative overflow-hidden">
            <div className="relative z-10">
              <div className="flex items-center gap-2 mb-4">
                <Sparkles className="text-indigo-600" size={22} />
                <h3 className="text-lg font-bold text-indigo-900">AI 庫存管理分析</h3>
              </div>
              {aiAdvice ? (
                <div className="prose prose-sm text-indigo-800">
                  <p className="whitespace-pre-line leading-relaxed">{aiAdvice}</p>
                  <button 
                    onClick={fetchAiInsights}
                    disabled={isAiLoading}
                    className="mt-4 text-xs font-semibold text-indigo-600 hover:text-indigo-800 transition-colors"
                  >
                    更新建議
                  </button>
                </div>
              ) : (
                <div className="flex flex-col items-center justify-center py-8 text-center">
                  <p className="text-indigo-600/70 mb-4">讓 Gemini 分析您的庫存狀況並提供優化建議</p>
                  <button 
                    onClick={fetchAiInsights}
                    disabled={isAiLoading}
                    className="px-6 py-2 bg-indigo-600 text-white rounded-full font-medium hover:bg-indigo-700 transition-all flex items-center gap-2"
                  >
                    {isAiLoading ? '分析中...' : '開始分析'}
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  };

  const InventoryView = () => {
    const [isAdding, setIsAdding] = useState(false);
    const [search, setSearch] = useState('');
    const [form, setForm] = useState({
      name: '',
      category: Category.PROTECTION,
      unit: '個',
      quantity: 0,
      minStock: 5,
      description: ''
    });

    const filteredItems = items.filter(i => i.name.toLowerCase().includes(search.toLowerCase()));

    return (
      <div className="space-y-4">
        <div className="flex flex-col md:flex-row justify-between gap-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="搜尋耗材名稱..."
              className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
          <button 
            onClick={() => setIsAdding(true)}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg flex items-center gap-2 hover:bg-blue-700 transition-colors"
          >
            <Plus size={18} /> 新增項目
          </button>
        </div>

        {isAdding && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl w-full max-w-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
              <div className="p-6 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                <h3 className="text-xl font-bold text-gray-800">新增耗材設備</h3>
                <button onClick={() => setIsAdding(false)} className="text-gray-400 hover:text-gray-600">
                  <X size={24} />
                </button>
              </div>
              <div className="p-6 space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-2">
                    <label className="block text-sm font-medium text-gray-700 mb-1">名稱</label>
                    <input 
                      type="text" 
                      className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
                      value={form.name}
                      onChange={e => setForm({...form, name: e.target.value})}
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">分類</label>
                    <select 
                      className="w-full px-3 py-2 border rounded-lg"
                      value={form.category}
                      onChange={e => setForm({...form, category: e.target.value as Category})}
                    >
                      {Object.values(Category).map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">單位</label>
                    <input 
                      type="text" 
                      className="w-full px-3 py-2 border rounded-lg"
                      placeholder="個, 雙, 組..."
                      value={form.unit}
                      onChange={e => setForm({...form, unit: e.target.value})}
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">初始數量</label>
                    <input 
                      type="number" 
                      className="w-full px-3 py-2 border rounded-lg"
                      value={form.quantity}
                      onChange={e => setForm({...form, quantity: Number(e.target.value)})}
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">安全存量警示值</label>
                    <input 
                      type="number" 
                      className="w-full px-3 py-2 border rounded-lg"
                      value={form.minStock}
                      onChange={e => setForm({...form, minStock: Number(e.target.value)})}
                    />
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">描述/備註</label>
                  <textarea 
                    className="w-full px-3 py-2 border rounded-lg"
                    rows={2}
                    value={form.description}
                    onChange={e => setForm({...form, description: e.target.value})}
                  />
                </div>
              </div>
              <div className="p-6 bg-gray-50 border-t flex justify-end gap-3">
                <button onClick={() => setIsAdding(false)} className="px-4 py-2 text-gray-600 font-medium">取消</button>
                <button 
                  onClick={() => {
                    if(!form.name) return alert('請輸入名稱');
                    addItem(form);
                    setIsAdding(false);
                    setForm({ name: '', category: Category.PROTECTION, unit: '個', quantity: 0, minStock: 5, description: '' });
                  }}
                  className="px-6 py-2 bg-blue-600 text-white rounded-lg font-medium hover:bg-blue-700"
                >
                  確認新增
                </button>
              </div>
            </div>
          </div>
        )}

        <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-gray-50 border-b border-gray-100">
              <tr>
                <th className="px-6 py-4 text-sm font-semibold text-gray-600">耗材名稱</th>
                <th className="px-6 py-4 text-sm font-semibold text-gray-600">分類</th>
                <th className="px-6 py-4 text-sm font-semibold text-gray-600">當前庫存</th>
                <th className="px-6 py-4 text-sm font-semibold text-gray-600">狀態</th>
                <th className="px-6 py-4 text-sm font-semibold text-gray-600 text-right">操作</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredItems.map(item => (
                <tr key={item.id} className="hover:bg-gray-50 transition-colors">
                  <td className="px-6 py-4">
                    <div className="font-medium text-gray-800">{item.name}</div>
                    <div className="text-xs text-gray-400">{item.description || '無描述'}</div>
                  </td>
                  <td className="px-6 py-4">
                    <span className="px-2 py-1 bg-blue-50 text-blue-600 text-xs rounded-full font-medium">
                      {item.category}
                    </span>
                  </td>
                  <td className="px-6 py-4 font-semibold text-gray-700">
                    {item.quantity} {item.unit}
                  </td>
                  <td className="px-6 py-4">
                    {item.quantity <= item.minStock ? (
                      <span className="flex items-center gap-1 text-amber-600 text-sm font-medium">
                        <AlertTriangle size={14} /> 庫存不足
                      </span>
                    ) : (
                      <span className="flex items-center gap-1 text-green-600 text-sm font-medium">
                        <CheckCircle2 size={14} /> 正常
                      </span>
                    )}
                  </td>
                  <td className="px-6 py-4 text-right">
                    <button 
                      onClick={() => deleteItem(item.id)}
                      className="p-2 text-gray-400 hover:text-red-500 transition-colors"
                    >
                      <Trash2 size={18} />
                    </button>
                  </td>
                </tr>
              ))}
              {filteredItems.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center text-gray-400">
                    目前沒有相關耗材資料。
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    );
  };

  const IssuanceView = () => {
    const [issuanceForm, setIssuanceForm] = useState({
      itemId: '',
      type: 'OUT' as TransactionType,
      qty: 1,
      person: '',
      reason: ''
    });

    const selectedItem = items.find(i => i.id === issuanceForm.itemId);

    return (
      <div className="max-w-2xl mx-auto bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-2xl font-bold text-gray-800 mb-6 flex items-center gap-2">
          <FileText className="text-blue-600" /> 物料領用 / 入庫登記單
        </h2>
        <div className="space-y-6">
          <div className="grid grid-cols-2 gap-6">
            <div className="col-span-2 md:col-span-1">
              <label className="block text-sm font-semibold text-gray-700 mb-2">選擇項目</label>
              <select 
                className="w-full px-4 py-2.5 border border-gray-200 rounded-xl bg-gray-50 focus:bg-white focus:ring-2 focus:ring-blue-500 transition-all"
                value={issuanceForm.itemId}
                onChange={e => setIssuanceForm({...issuanceForm, itemId: e.target.value})}
              >
                <option value="">請選擇...</option>
                {items.map(item => (
                  <option key={item.id} value={item.id}>
                    {item.name} (剩餘 {item.quantity} {item.unit})
                  </option>
                ))}
              </select>
            </div>
            <div className="col-span-2 md:col-span-1">
              <label className="block text-sm font-semibold text-gray-700 mb-2">單據類型</label>
              <div className="flex bg-gray-50 p-1 rounded-xl border border-gray-200">
                <button 
                  className={`flex-1 py-1.5 rounded-lg text-sm font-medium transition-all ${issuanceForm.type === 'OUT' ? 'bg-white shadow text-red-600' : 'text-gray-500 hover:bg-gray-100'}`}
                  onClick={() => setIssuanceForm({...issuanceForm, type: 'OUT'})}
                >
                  領用 (出庫)
                </button>
                <button 
                  className={`flex-1 py-1.5 rounded-lg text-sm font-medium transition-all ${issuanceForm.type === 'IN' ? 'bg-white shadow text-green-600' : 'text-gray-500 hover:bg-gray-100'}`}
                  onClick={() => setIssuanceForm({...issuanceForm, type: 'IN'})}
                >
                  補貨 (入庫)
                </button>
              </div>
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">數量</label>
              <input 
                type="number" 
                min="1"
                className="w-full px-4 py-2.5 border border-gray-200 rounded-xl bg-gray-50 focus:bg-white focus:ring-2 focus:ring-blue-500 transition-all"
                value={issuanceForm.qty}
                onChange={e => setIssuanceForm({...issuanceForm, qty: Number(e.target.value)})}
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">{issuanceForm.type === 'OUT' ? '領用人' : '經辦人'}</label>
              <input 
                type="text" 
                className="w-full px-4 py-2.5 border border-gray-200 rounded-xl bg-gray-50 focus:bg-white focus:ring-2 focus:ring-blue-500 transition-all"
                placeholder="姓名"
                value={issuanceForm.person}
                onChange={e => setIssuanceForm({...issuanceForm, person: e.target.value})}
              />
            </div>
          </div>
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">{issuanceForm.type === 'OUT' ? '領用原因/工程代碼' : '備註'}</label>
            <textarea 
              className="w-full px-4 py-2.5 border border-gray-200 rounded-xl bg-gray-50 focus:bg-white focus:ring-2 focus:ring-blue-500 transition-all"
              rows={3}
              value={issuanceForm.reason}
              onChange={e => setIssuanceForm({...issuanceForm, reason: e.target.value})}
            />
          </div>
          <button 
            onClick={() => {
              if(!issuanceForm.itemId || !issuanceForm.person || issuanceForm.qty <= 0) {
                return alert('請完整填寫表單');
              }
              createTransaction(
                issuanceForm.itemId,
                issuanceForm.type,
                issuanceForm.qty,
                issuanceForm.person,
                issuanceForm.reason
              );
              alert('登記成功！系統已自動更新庫存。');
              setIssuanceForm({ itemId: '', type: 'OUT', qty: 1, person: '', reason: '' });
            }}
            className={`w-full py-4 rounded-xl text-white font-bold text-lg shadow-lg transform active:scale-95 transition-all ${issuanceForm.type === 'OUT' ? 'bg-red-500 hover:bg-red-600 shadow-red-200' : 'bg-green-500 hover:bg-green-600 shadow-green-200'}`}
          >
            確認登記並更新庫存
          </button>
        </div>
      </div>
    );
  };

  const HistoryView = () => (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
      <div className="p-6 border-b border-gray-100 flex justify-between items-center">
        <h3 className="text-lg font-bold">歷史異動日誌</h3>
        <button 
          onClick={() => { if(confirm('確定清除所有紀錄？')) setLogs([]); }}
          className="text-sm text-red-500 hover:underline"
        >
          清除日誌
        </button>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-left">
          <thead className="bg-gray-50 border-b border-gray-100">
            <tr>
              <th className="px-6 py-4 text-sm font-semibold text-gray-600">時間</th>
              <th className="px-6 py-4 text-sm font-semibold text-gray-600">項目名稱</th>
              <th className="px-6 py-4 text-sm font-semibold text-gray-600">類型</th>
              <th className="px-6 py-4 text-sm font-semibold text-gray-600">數量</th>
              <th className="px-6 py-4 text-sm font-semibold text-gray-600">經手/領用人</th>
              <th className="px-6 py-4 text-sm font-semibold text-gray-600">事由</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100 text-sm">
            {logs.map(log => (
              <tr key={log.id} className="hover:bg-gray-50 transition-colors">
                <td className="px-6 py-4 text-gray-500">
                  {new Date(log.timestamp).toLocaleString()}
                </td>
                <td className="px-6 py-4 font-medium text-gray-800">{log.itemName}</td>
                <td className="px-6 py-4">
                  {log.type === 'IN' ? (
                    <span className="flex items-center gap-1 text-green-600">
                      <ArrowUpCircle size={14} /> 入庫
                    </span>
                  ) : (
                    <span className="flex items-center gap-1 text-red-600">
                      <ArrowDownCircle size={14} /> 出庫
                    </span>
                  )}
                </td>
                <td className="px-6 py-4 font-bold">{log.quantity}</td>
                <td className="px-6 py-4">{log.person}</td>
                <td className="px-6 py-4 text-gray-500 max-w-xs truncate">{log.reason}</td>
              </tr>
            ))}
            {logs.length === 0 && (
              <tr>
                <td colSpan={6} className="px-6 py-12 text-center text-gray-400 italic">
                  暫無任何紀錄。
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen flex flex-col md:flex-row">
      {/* Sidebar */}
      <aside className="w-full md:w-64 bg-slate-900 text-white p-6 md:sticky md:top-0 md:h-screen flex flex-col">
        <div className="flex items-center gap-3 mb-10 px-2">
          <div className="p-2 bg-blue-600 rounded-lg">
            <Package size={24} />
          </div>
          <div>
            <h1 className="font-bold text-lg leading-tight">工安管理系統</h1>
            <p className="text-[10px] text-slate-400 tracking-widest uppercase">Inventory Pro v1.0</p>
          </div>
        </div>

        <nav className="flex-1 space-y-2">
          <button 
            onClick={() => setActiveTab('dashboard')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'dashboard' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:bg-slate-800'}`}
          >
            <LayoutDashboard size={20} />
            <span className="font-medium">總覽儀表板</span>
          </button>
          <button 
            onClick={() => setActiveTab('inventory')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'inventory' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:bg-slate-800'}`}
          >
            <Package size={20} />
            <span className="font-medium">耗材清單</span>
          </button>
          <button 
            onClick={() => setActiveTab('issuance')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'issuance' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:bg-slate-800'}`}
          >
            <FileText size={20} />
            <span className="font-medium">領用入庫登記</span>
          </button>
          <button 
            onClick={() => setActiveTab('history')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'history' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:bg-slate-800'}`}
          >
            <History size={20} />
            <span className="font-medium">異動紀錄</span>
          </button>
        </nav>

        <div className="mt-auto pt-6 border-t border-slate-800">
          <p className="text-xs text-slate-500 mb-1">系統開發：Senior Frontend Eng.</p>
          <p className="text-[10px] text-slate-600">Powered by Gemini AI</p>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-4 md:p-8 lg:p-12 overflow-y-auto">
        <header className="mb-8 flex justify-between items-end">
          <div>
            <h2 className="text-2xl font-bold text-gray-800">
              {activeTab === 'dashboard' && '數據總覽'}
              {activeTab === 'inventory' && '耗材設備資料庫'}
              {activeTab === 'issuance' && '自動化領用登記'}
              {activeTab === 'history' && '庫存日誌'}
            </h2>
            <p className="text-gray-500 text-sm">歡迎回來，今天是 {new Date().toLocaleDateString('zh-TW', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
          </div>
          <div className="hidden md:flex items-center gap-2 px-3 py-1.5 bg-green-50 text-green-700 rounded-full text-xs font-semibold">
            <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
            系統連線正常
          </div>
        </header>

        {activeTab === 'dashboard' && <DashboardView />}
        {activeTab === 'inventory' && <InventoryView />}
        {activeTab === 'issuance' && <IssuanceView />}
        {activeTab === 'history' && <HistoryView />}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  AlertTriangle,
  ArrowDownCircle,
  ArrowUpCircle,
  Sparkles,
  Search,
  CheckCircle2,
  X
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  Cell
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_items';
const STORAGE_KEY_LOGS = 'safeman_logs';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'issuance' | 'history'>('dashboard');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [aiAdvice, setAiAdvice] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Persistence
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedLogs) setLogs(JSON.parse(savedLogs));
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
    localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
  }, [items, logs]);

  // Inventory Handlers
  const addItem = (newItem: Omit<InventoryItem, 'id' | 'lastUpdated'>) => {
    const item: InventoryItem = {
      ...newItem,
      id: crypto.randomUUID(),
      lastUpdated: Date.now(),
    };
    setItems(prev => [...prev, item]);
  };

  const deleteItem = (id: string) => {
    if (confirm('確定要刪除此項目嗎？')) {
      setItems(prev => prev.filter(i => i.id !== id));
      setLogs(prev => prev.filter(l => l.itemId !== id));
    }
  };

  const createTransaction = (
    itemId: string, 
    type: TransactionType, 
    qty: number, 
    person: string, 
    reason: string
  ) => {
    const targetItem = items.find(i => i.id === itemId);
    if (!targetItem) return;

    if (type === 'OUT' && targetItem.quantity < qty) {
      alert('庫存不足！');
      return;
    }

    const updatedItems = items.map(i => {
      if (i.id === itemId) {
        return {
          ...i,
          quantity: type === 'IN' ? i.quantity + qty : i.quantity - qty,
          lastUpdated: Date.now()
        };
      }
      return i;
    });

    const newLog: Transaction = {
      id: crypto.randomUUID(),
      itemId,
      itemName: targetItem.name,
      type,
      quantity: qty,
      person,
      reason,
      timestamp: Date.now()
    };

    setItems(updatedItems);
    setLogs(prev => [newLog, ...prev]);
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    const advice = await getInventoryInsights(items);
    setAiAdvice(advice);
    setIsAiLoading(false);
  };

  // Views
  const DashboardView = () => {
    const lowStockCount = items.filter(i => i.quantity <= i.minStock).length;
    const chartData = items.slice(0, 8).map(i => ({ name: i.name, 庫存: i.quantity, 安全線: i.minStock }));

    return (
      <div className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <div className="flex items-center justify-between mb-2">
              <span className="text-gray-500 text-sm font-medium">總項目數</span>
              <Package className="text-blue-500" size={20} />
            </div>
            <p className="text-3xl font-bold text-gray-800">{items.length}</p>
          </div>
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <div className="flex items-center justify-between mb-2">
              <span className="text-gray-500 text-sm font-medium">低庫存警示</span>
              <AlertTriangle className="text-amber-500" size={20} />
            </div>
            <p className="text-3xl font-bold text-gray-800">{lowStockCount}</p>
          </div>
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <div className="flex items-center justify-between mb-2">
              <span className="text-gray-500 text-sm font-medium">本月異動紀錄</span>
              <History className="text-indigo-500" size={20} />
            </div>
            <p className="text-3xl font-bold text-gray-800">{logs.length}</p>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <h3 className="text-lg font-semibold mb-6">庫存分佈概況</h3>
            <div className="h-64">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={chartData}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} />
                  <XAxis dataKey="name" />
                  <YAxis />
                  <Tooltip />
                  <Bar dataKey="庫存" fill="#3b82f6" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          <div className="bg-gradient-to-br from-indigo-50 to-blue-50 p-6 rounded-xl shadow-sm border border-blue-100 relative overflow-hidden">
            <div className="relative z-10">
              <div className="flex items-center gap-2 mb-4">
                <Sparkles className="text-indigo-600" size={22} />
                <h3 className="text-lg font-bold text-indigo-900">AI 庫存管理分析</h3>
              </div>
              {aiAdvice ? (
                <div className="prose prose-sm text-indigo-800">
                  <p className="whitespace-pre-line leading-relaxed">{aiAdvice}</p>
                  <button 
                    onClick={fetchAiInsights}
                    disabled={isAiLoading}
                    className="mt-4 text-xs font-semibold text-indigo-600 hover:text-indigo-800 transition-colors"
                  >
                    更新建議
                  </button>
                </div>
              ) : (
                <div className="flex flex-col items-center justify-center py-8 text-center">
                  <p className="text-indigo-600/70 mb-4">讓 Gemini 分析您的庫存狀況並提供優化建議</p>
                  <button 
                    onClick={fetchAiInsights}
                    disabled={isAiLoading}
                    className="px-6 py-2 bg-indigo-600 text-white rounded-full font-medium hover:bg-indigo-700 transition-all flex items-center gap-2"
                  >
                    {isAiLoading ? '分析中...' : '開始分析'}
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  };

  const InventoryView = () => {
    const [isAdding, setIsAdding] = useState(false);
    const [search, setSearch] = useState('');
    const [form, setForm] = useState({
      name: '',
      category: Category.PROTECTION,
      unit: '個',
      quantity: 0,
      minStock: 5,
      description: ''
    });

    const filteredItems = items.filter(i => i.name.toLowerCase().includes(search.toLowerCase()));

    return (
      <div className="space-y-4">
        <div className="flex flex-col md:flex-row justify-between gap-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="搜尋耗材名稱..."
              className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-gray-900"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
          <button 
            onClick={() => setIsAdding(true)}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg flex items-center gap-2 hover:bg-blue-700 transition-colors"
          >
            <Plus size={18} /> 新增項目
          </button>
        </div>

        {isAdding && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl w-full max-w-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
              <div className="p-6 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                <h3 className="text-xl font-bold text-gray-800">新增耗材設備</h3>
                <button onClick={() => setIsAdding(false)} className="text-gray-400 hover:text-gray-600">
                  <X size={24} />
                </button>
              </div>
              <div className="p-6 space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-2">
                    <label className="block text-sm font-medium text-gray-700 mb-1">名稱</label>
                    <input 
                      type="text" 
                      className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 text-gray-900"
                      value={form.name}
                      onChange={e => setForm({...form, name: e.target.value})}
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">分類</label>
                    <select 
                      className="w-full px-3 py-2 border rounded-lg text-gray-900"
                      value={form.category}
                      onChange={e => setForm({...form, category: e.target.value as Category})}
                    >
                      {Object.values(Category).map(c => <option key={c} value={c} className="text-gray-900">{c}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">單位</label>
                    <input 
                      type="text" 
                      className="w-full px-3 py-2 border rounded-lg text-gray-900"
                      placeholder="個, 雙, 組..."
                      value={form.unit}
                      onChange={e => setForm({...form, unit: e.target.value})}
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">初始數量</label>
                    <input 
                      type="number" 
                      className="w-full px-3 py-2 border rounded-lg text-gray-900"
                      value={form.quantity}
                      onChange={e => setForm({...form, quantity: Number(e.target.value)})}
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">安全存量警示值</label>
                    <input 
                      type="number" 
                      className="w-full px-3 py-2 border rounded-lg text-gray-900"
                      value={form.minStock}
                      onChange={e => setForm({...form, minStock: Number(e.target.value)})}
                    />
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">描述/備註</label>
                  <textarea 
                    className="w-full px-3 py-2 border rounded-lg text-gray-900"
                    rows={2}
                    value={form.description}
                    onChange={e => setForm({...form, description: e.target.value})}
                  />
                </div>
              </div>
              <div className="p-6 bg-gray-50 border-t flex justify-end gap-3">
                <button onClick={() => setIsAdding(false)} className="px-4 py-2 text-gray-600 font-medium">取消</button>
                <button 
                  onClick={() => {
                    if(!form.name) return alert('請輸入名稱');
                    addItem(form);
                    setIsAdding(false);
                    setForm({ name: '', category: Category.PROTECTION, unit: '個', quantity: 0, minStock: 5, description: '' });
                  }}
                  className="px-6 py-2 bg-blue-600 text-white rounded-lg font-medium hover:bg-blue-700"
                >
                  確認新增
                </button>
              </div>
            </div>
          </div>
        )}

        <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-gray-50 border-b border-gray-100">
              <tr>
                <th className="px-6 py-4 text-sm font-semibold text-gray-600">耗材名稱</th>
                <th className="px-6 py-4 text-sm font-semibold text-gray-600">分類</th>
                <th className="px-6 py-4 text-sm font-semibold text-gray-600">當前庫存</th>
                <th className="px-6 py-4 text-sm font-semibold text-gray-600">狀態</th>
                <th className="px-6 py-4 text-sm font-semibold text-gray-600 text-right">操作</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredItems.map(item => (
                <tr key={item.id} className="hover:bg-gray-50 transition-colors">
                  <td className="px-6 py-4">
                    <div className="font-medium text-gray-800">{item.name}</div>
                    <div className="text-xs text-gray-400">{item.description || '無描述'}</div>
                  </td>
                  <td className="px-6 py-4">
                    <span className="px-2 py-1 bg-blue-50 text-blue-600 text-xs rounded-full font-medium">
                      {item.category}
                    </span>
                  </td>
                  <td className="px-6 py-4 font-semibold text-gray-700">
                    {item.quantity} {item.unit}
                  </td>
                  <td className="px-6 py-4">
                    {item.quantity <= item.minStock ? (
                      <span className="flex items-center gap-1 text-amber-600 text-sm font-medium">
                        <AlertTriangle size={14} /> 庫存不足
                      </span>
                    ) : (
                      <span className="flex items-center gap-1 text-green-600 text-sm font-medium">
                        <CheckCircle2 size={14} /> 正常
                      </span>
                    )}
                  </td>
                  <td className="px-6 py-4 text-right">
                    <button 
                      onClick={() => deleteItem(item.id)}
                      className="p-2 text-gray-400 hover:text-red-500 transition-colors"
                    >
                      <Trash2 size={18} />
                    </button>
                  </td>
                </tr>
              ))}
              {filteredItems.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center text-gray-400">
                    目前沒有相關耗材資料。
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    );
  };

  const IssuanceView = () => {
    const [issuanceForm, setIssuanceForm] = useState({
      itemId: '',
      type: 'OUT' as TransactionType,
      qty: 1,
      person: '',
      reason: ''
    });

    const selectedItem = items.find(i => i.id === issuanceForm.itemId);

    return (
      <div className="max-w-2xl mx-auto bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-2xl font-bold text-gray-800 mb-6 flex items-center gap-2">
          <FileText className="text-blue-600" /> 物料領用 / 入庫登記單
        </h2>
        <div className="space-y-6">
          <div className="grid grid-cols-2 gap-6">
            <div className="col-span-2 md:col-span-1">
              <label className="block text-sm font-semibold text-gray-700 mb-2">選擇項目</label>
              <select 
                className="w-full px-4 py-2.5 border-2 border-gray-200 rounded-xl bg-gray-50 focus:bg-white focus:border-blue-500 focus:ring-2 focus:ring-blue-200 transition-all text-gray-900 font-medium"
                value={issuanceForm.itemId}
                onChange={e => setIssuanceForm({...issuanceForm, itemId: e.target.value})}
              >
                <option value="" className="text-gray-400">點擊此處選擇項目...</option>
                {items.map(item => (
                  <option key={item.id} value={item.id} className="text-gray-900 bg-white">
                    {item.name} (剩餘 {item.quantity} {item.unit})
                  </option>
                ))}
              </select>
              {selectedItem && (
                <p className="mt-1 text-xs text-blue-600 font-medium">目前選擇: {selectedItem.name}</p>
              )}
            </div>
            <div className="col-span-2 md:col-span-1">
              <label className="block text-sm font-semibold text-gray-700 mb-2">單據類型</label>
              <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200">
                <button 
                  className={`flex-1 py-1.5 rounded-lg text-sm font-bold transition-all ${issuanceForm.type === 'OUT' ? 'bg-white shadow-sm text-red-600' : 'text-gray-500 hover:bg-gray-200'}`}
                  onClick={() => setIssuanceForm({...issuanceForm, type: 'OUT'})}
                >
                  領用 (出庫)
                </button>
                <button 
                  className={`flex-1 py-1.5 rounded-lg text-sm font-bold transition-all ${issuanceForm.type === 'IN' ? 'bg-white shadow-sm text-green-600' : 'text-gray-500 hover:bg-gray-200'}`}
                  onClick={() => setIssuanceForm({...issuanceForm, type: 'IN'})}
                >
                  補貨 (入庫)
                </button>
              </div>
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">數量</label>
              <input 
                type="number" 
                min="1"
                className="w-full px-4 py-2.5 border-2 border-gray-200 rounded-xl bg-gray-50 focus:bg-white focus:border-blue-500 focus:ring-2 focus:ring-blue-200 transition-all text-gray-900 font-bold"
                value={issuanceForm.qty}
                onChange={e => setIssuanceForm({...issuanceForm, qty: Number(e.target.value)})}
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">{issuanceForm.type === 'OUT' ? '領用人' : '經辦人'}</label>
              <input 
                type="text" 
                className="w-full px-4 py-2.5 border-2 border-gray-200 rounded-xl bg-gray-50 focus:bg-white focus:border-blue-500 focus:ring-2 focus:ring-blue-200 transition-all text-gray-900"
                placeholder="請輸入姓名"
                value={issuanceForm.person}
                onChange={e => setIssuanceForm({...issuanceForm, person: e.target.value})}
              />
            </div>
          </div>
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">{issuanceForm.type === 'OUT' ? '領用原因/工程代碼' : '備註'}</label>
            <textarea 
              className="w-full px-4 py-2.5 border-2 border-gray-200 rounded-xl bg-gray-50 focus:bg-white focus:border-blue-500 focus:ring-2 focus:ring-blue-200 transition-all text-gray-900"
              rows={3}
              placeholder="請填寫具體用途或備註資訊"
              value={issuanceForm.reason}
              onChange={e => setIssuanceForm({...issuanceForm, reason: e.target.value})}
            />
          </div>
          <button 
            onClick={() => {
              if(!issuanceForm.itemId || !issuanceForm.person || issuanceForm.qty <= 0) {
                return alert('請完整填寫所有必填欄位');
              }
              createTransaction(
                issuanceForm.itemId,
                issuanceForm.type,
                issuanceForm.qty,
                issuanceForm.person,
                issuanceForm.reason
              );
              alert('登記成功！系統已自動更新庫存。');
              setIssuanceForm({ itemId: '', type: 'OUT', qty: 1, person: '', reason: '' });
            }}
