                    if(!form.name) return alert('請輸入項目名稱');
                    addItem(form);
                    setIsAdding(false);
                    setForm({ name: '', category: Category.PROTECTION, unit: '個', quantity: 0, minStock: 5, description: '' });
                  }}
                  className="px-10 py-2.5 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 transition-all transform active:scale-95"
                >
                  存入資料庫
                </button>
              </div>
            </div>
          </div>
        )}

        <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
