                <th className="px-6 py-4 text-sm font-bold text-gray-600">耗材名稱</th>
                <th className="px-6 py-4 text-sm font-bold text-gray-600">分類</th>
                <th className="px-6 py-4 text-sm font-bold text-gray-600">當前庫存</th>
