                    </span>
                  )}
                </td>
                <td className="px-6 py-4 font-black text-gray-900 text-base">{log.quantity}</td>
                <td className="px-6 py-4 text-gray-800 font-semibold">{log.person}</td>
                <td className="px-6 py-4 text-right">
                  <button 
                    onClick={() => { setLastTransaction(log); setShowPrintModal(true); }}
                    className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                    title="重新產出單據"
                  >
                    <Printer size={18} />
                  </button>
                </td>
              </tr>
            ))}
            {logs.length === 0 && (
              <tr>
                <td colSpan={6} className="px-6 py-12 text-center text-gray-400 italic">
                  目前尚無任何異動紀錄。
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50">
      {/* Sidebar */}
      <aside className="w-full md:w-64 bg-slate-900 text-white p-6 md:sticky md:top-0 md:h-screen flex flex-col shadow-2xl z-40">
        <div className="flex items-center gap-3 mb-12 px-2">
          <div className="p-2.5 bg-blue-600 rounded-xl shadow-lg shadow-blue-500/30">
            <Package size={26} />
          </div>
          <div>
            <h1 className="font-black text-xl leading-tight tracking-tight">工安管理</h1>
            <p className="text-[10px] text-slate-400 tracking-widest uppercase font-bold">Maintenance Pro</p>
          </div>
        </div>

        <nav className="flex-1 space-y-3">
          {[
            { id: 'dashboard', icon: LayoutDashboard, label: '儀表板' },
            { id: 'inventory', icon: Package, label: '耗材清單' },
            { id: 'issuance', icon: FileText, label: '登記作業' },
            { id: 'history', icon: History, label: '紀錄查詢' },
          ].map((tab) => (
            <button 
              key={tab.id}
