export default App;

import React, { useState, useEffect, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  AlertTriangle,
  ArrowDownCircle,
  ArrowUpCircle,
  Sparkles,
  Search,
  CheckCircle2,
  X,
  Printer,
  Calendar
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_items';
const STORAGE_KEY_LOGS = 'safeman_logs';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'issuance' | 'history'>('dashboard');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [aiAdvice, setAiAdvice] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);

  // Persistence
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedLogs) setLogs(JSON.parse(savedLogs));
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
    localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
  }, [items, logs]);

  // Inventory Handlers
  const addItem = (newItem: Omit<InventoryItem, 'id' | 'lastUpdated'>) => {
    const item: InventoryItem = {
      ...newItem,
      id: crypto.randomUUID(),
      lastUpdated: Date.now(),
    };
    setItems(prev => [...prev, item]);
  };

  const deleteItem = (id: string) => {
    if (confirm('確定要刪除此項目嗎？')) {
      setItems(prev => prev.filter(i => i.id !== id));
      setLogs(prev => prev.filter(l => l.itemId !== id));
    }
  };

  const createTransaction = (
    itemId: string, 
    type: TransactionType, 
    qty: number, 
    person: string, 
    reason: string
  ) => {
    const targetItem = items.find(i => i.id === itemId);
    if (!targetItem) return;

    if (type === 'OUT' && targetItem.quantity < qty) {
      alert('庫存不足！');
      return;
    }

    const updatedItems = items.map(i => {
      if (i.id === itemId) {
        return {
          ...i,
          quantity: type === 'IN' ? i.quantity + qty : i.quantity - qty,
          lastUpdated: Date.now()
        };
      }
      return i;
    });

    const newLog: Transaction = {
      id: crypto.randomUUID(),
      itemId,
      itemName: targetItem.name,
      type,
      quantity: qty,
      person,
      reason,
      timestamp: Date.now()
    };

    setItems(updatedItems);
    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    // 只有領用(出庫)才產出表單
    if (type === 'OUT') {
      setShowPrintModal(true);
    } else {
      alert('入庫登記成功！庫存已更新。');
    }
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    const advice = await getInventoryInsights(items);
    setAiAdvice(advice);
    setIsAiLoading(false);
  };

  // --- Components ---

  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const now = new Date(transaction.timestamp);
    const year = now.getFullYear() - 1911; // 民國年
    const month = now.getMonth() + 1;
    const day = now.getDate();

    return (
      <div className="bg-white p-8 max-w-[210mm] mx-auto text-black font-serif border-2 border-black shadow-lg" id="print-area">
        <style dangerouslySetInnerHTML={{ __html: `
          @media print {
            body * { visibility: hidden; }
            #print-area, #print-area * { visibility: visible; }
            #print-area { position: absolute; left: 0; top: 0; width: 100%; border: none; box-shadow: none; }
          }
        `}} />

        <div className="text-center mb-6">
          <h1 className="text-2xl font-bold tracking-widest border-b-2 border-black inline-block pb-1 text-black">
            台灣電力公司電力修護處南部分處
          </h1>
          <div className="flex justify-center gap-12 mt-6 text-lg text-black font-bold">
            <label className="flex items-center gap-2">
              <div className={`w-5 h-5 border-2 border-black flex items-center justify-center`}>
                {transaction.type === 'OUT' && targetItem?.category.includes('設備') ? '✓' : ''}
              </div>
              安全衛生設備借用單
            </label>
            <label className="flex items-center gap-2">
              <div className={`w-5 h-5 border-2 border-black flex items-center justify-center`}>
                {transaction.type === 'OUT' && !targetItem?.category.includes('設備') ? '✓' : ''}
              </div>
              安全衛生類消耗品領用單
            </label>
          </div>
        </div>

        <div className="flex justify-between mb-4 text-base font-bold text-black px-1">
          <div>部門：<span className="underline px-2">{transaction.person}</span></div>
          <div>中華民國 {year} 年 {month} 月 {day} 日</div>
        </div>

        <table className="w-full border-collapse border-2 border-black text-center mb-6">
          <thead>
