import React, { useState, useEffect, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  AlertTriangle,
  ArrowDownCircle,
  ArrowUpCircle,
  Sparkles,
  Search,
  CheckCircle2,
  X,
  Printer,
  Calendar,
  Download,
  Upload,
  Database
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_items';
const STORAGE_KEY_LOGS = 'safeman_logs';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'issuance' | 'history'>('dashboard');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [aiAdvice, setAiAdvice] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Persistence
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedLogs) setLogs(JSON.parse(savedLogs));
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
    localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
  }, [items, logs]);

  // Data Exchange Handlers
  const exportDatabase = () => {
    const data = {
      items,
      logs,
      exportDate: new Date().toISOString(),
      version: "1.0.4"
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `工安管理資料庫備份_${new Date().toLocaleDateString().replace(/\//g, '-')}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const importDatabase = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = JSON.parse(e.target?.result as string);
        if (data.items && Array.isArray(data.items)) {
          if (confirm('匯入將會覆蓋目前的「所有資料」，確定要繼續嗎？建議先下載目前的備份再進行此操作。')) {
            setItems(data.items);
            setLogs(data.logs || []);
            alert('資料庫匯入成功！系統已更新。');
          }
        } else {
          alert('無效的資料格式！');
        }
      } catch (err) {
        alert('檔案讀取失敗，請確認是否為正確的 JSON 檔案。');
      }
    };
    reader.readAsText(file);
    // 重置 input 以利下次選擇相同檔案
    event.target.value = '';
  };

  // Inventory Handlers
  const addItem = (newItem: Omit<InventoryItem, 'id' | 'lastUpdated'>) => {
    const item: InventoryItem = {
      ...newItem,
      id: crypto.randomUUID(),
      lastUpdated: Date.now(),
    };
    setItems(prev => [...prev, item]);
  };

  const deleteItem = (id: string) => {
    if (confirm('確定要刪除此項目嗎？')) {
      setItems(prev => prev.filter(i => i.id !== id));
      setLogs(prev => prev.filter(l => l.itemId !== id));
    }
  };

  const createTransaction = (
    itemId: string, 
    type: TransactionType, 
    qty: number, 
    person: string, 
    reason: string
  ) => {
    const targetItem = items.find(i => i.id === itemId);
    if (!targetItem) return;

    if (type === 'OUT' && targetItem.quantity < qty) {
      alert('庫存不足！無法領用。');
      return;
    }

    const updatedItems = items.map(i => {
      if (i.id === itemId) {
        return {
          ...i,
          quantity: type === 'IN' ? i.quantity + qty : i.quantity - qty,
          lastUpdated: Date.now()
        };
      }
      return i;
    });

    const newLog: Transaction = {
      id: crypto.randomUUID(),
      itemId,
      itemName: targetItem.name,
      type,
      quantity: qty,
      person,
      reason,
      timestamp: Date.now()
    };

    setItems(updatedItems);
    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    if (type === 'OUT') {
      setShowPrintModal(true);
    } else {
      alert('庫存補貨登記成功。');
    }
  };

