              <td className="border-2 border-black py-4 px-2 font-black text-xl text-black">{transaction.quantity}</td>
              <td className="border-2 border-black py-4 px-2 text-sm text-black font-medium">{transaction.reason}</td>
            </tr>
            {[...Array(13)].map((_, i) => (
              <tr key={i}>
                <td className="border-2 border-black py-5"></td>
                <td className="border-2 border-black py-5"></td>
                <td className="border-2 border-black py-5"></td>
                <td className="border-2 border-black py-5"></td>
                <td className="border-2 border-black py-5"></td>
              </tr>
            ))}
          </tbody>
