import React, { useState, useEffect, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  AlertTriangle,
  ArrowDownCircle,
  ArrowUpCircle,
  Sparkles,
  Search,
  CheckCircle2,
  X,
  Printer,
  Calendar,
  Download,
  Upload,
  Database,
  Copy,
  ClipboardCheck
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_items';
const STORAGE_KEY_LOGS = 'safeman_logs';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'issuance' | 'history'>('dashboard');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [aiAdvice, setAiAdvice] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [copyStatus, setCopyStatus] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Persistence
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedLogs) setLogs(JSON.parse(savedLogs));
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
    localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
  }, [items, logs]);

  // Data Exchange Handlers
  const exportDatabaseText = () => {
    const data = { items, logs, timestamp: Date.now() };
    const encoded = btoa(encodeURIComponent(JSON.stringify(data)));
    navigator.clipboard.writeText(encoded);
    setCopyStatus(true);
    setTimeout(() => setCopyStatus(false), 2000);
  };

  const importDatabaseText = () => {
    const code = prompt('請貼上同事分享的「同步代碼」：');
    if (!code) return;
    try {
      const decoded = JSON.parse(decodeURIComponent(atob(code)));
      if (decoded.items && Array.isArray(decoded.items)) {
        if (confirm('確定要同步資料？這將會覆蓋您目前的數據。')) {
          setItems(decoded.items);
          setLogs(decoded.logs || []);
          alert('資料同步成功！');
        }
      }
    } catch (err) {
      alert('無效的同步代碼。');
    }
  };

  const exportFile = () => {
    const data = { items, logs, version: "1.0.5" };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `工安資料庫_${new Date().toLocaleDateString().replace(/\//g, '-')}.json`;
    a.click();
  };

  // Inventory Handlers
  const createTransaction = (
    itemId: string, 
    type: TransactionType, 
    qty: number, 
    person: string, 
    reason: string
  ) => {
    const targetItem = items.find(i => i.id === itemId);
    if (!targetItem) return;

    if (type === 'OUT' && targetItem.quantity < qty) {
      alert('目前庫存量不足以支應領用。');
      return;
    }

    const updatedItems = items.map(i => {
      if (i.id === itemId) {
        return {
          ...i,
          quantity: type === 'IN' ? i.quantity + qty : i.quantity - qty,
          lastUpdated: Date.now()
        };
      }
      return i;
    });

    const newLog: Transaction = {
      id: crypto.randomUUID(),
      itemId,
      itemName: targetItem.name,
      type,
      quantity: qty,
      person, // 此欄位在 OUT 時存領用人，IN 時存入庫日期
      reason,
      timestamp: Date.now()
    };

    setItems(updatedItems);
    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    // 關鍵變更：僅在領用時產出單據
    if (type === 'OUT') {
      setShowPrintModal(true);
    } else {
      alert(`補貨登記完成！${targetItem.name} 目前庫存：${targetItem.quantity + qty} ${targetItem.unit}`);
    }
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    const advice = await getInventoryInsights(items);
    setAiAdvice(advice);
    setIsAiLoading(false);
  };

  // --- Components ---

  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const now = new Date(transaction.timestamp);
    const year = now.getFullYear() - 1911; 
    const month = now.getMonth() + 1;
    const day = now.getDate();

    return (
      <div className="bg-white p-8 max-w-[210mm] mx-auto text-black font-serif border-[3px] border-black shadow-lg" id="print-area">
        <style dangerouslySetInnerHTML={{ __html: `
          @media print {
            body * { visibility: hidden; }
            #print-area, #print-area * { visibility: visible; }
            #print-area { position: absolute; left: 0; top: 0; width: 100%; border: none; box-shadow: none; }
          }
        `}} />

        <div className="text-center mb-8">
          <h1 className="text-3xl font-black tracking-widest border-b-[3px] border-black inline-block pb-1 text-black mb-6">
            台灣電力公司電力修護處南部分處
          </h1>
          <div className="flex justify-center gap-16 text-xl text-black font-black">
            <label className="flex items-center gap-3">
              <div className={`w-6 h-6 border-[3px] border-black flex items-center justify-center`}>
                {targetItem?.category.includes('設備') ? '✓' : ''}
              </div>
              安全衛生設備借用單
            </label>
            <label className="flex items-center gap-3">
              <div className={`w-6 h-6 border-[3px] border-black flex items-center justify-center`}>
                {!targetItem?.category.includes('設備') ? '✓' : ''}
              </div>
              安全衛生類消耗品領用單
            </label>
          </div>
        </div>

        <div className="flex justify-between mb-4 text-lg font-black text-black px-2">
          <div>部門：<span className="underline decoration-[2px] underline-offset-4 px-4">{transaction.person}</span></div>
          <div>中華民國 {year} 年 {month} 月 {day} 日</div>
        </div>

        <table className="w-full border-collapse border-[3px] border-black text-center mb-6">
          <thead>
            <tr className="bg-gray-100">
              <th className="border-[3px] border-black py-4 px-2 w-1/3 text-black font-black text-xl">名 稱</th>
              <th className="border-[3px] border-black py-4 px-2 w-1/4 text-black font-black text-xl">規 格 (序 號)</th>
              <th className="border-[3px] border-black py-4 px-2 text-black font-black text-xl">單 位</th>
              <th className="border-[3px] border-black py-4 px-2 text-black font-black text-xl">數 量</th>
