      if (decoded.items && Array.isArray(decoded.items)) {
        if (confirm('確定要同步資料？這將會覆蓋您目前的數據。')) {
          setItems(decoded.items);
          setLogs(decoded.logs || []);
          alert('資料同步成功！');
