    const unit = prompt('請輸入單位 (如：個, 雙, 卷)：', '個') || '個';
    const minStock = Number(prompt('請輸入最低庫存警示量：', '5')) || 5;
    const categoryName = prompt('請輸入分類 (1:防護, 2:消防, 3:急救, 4:標誌, 5:工具, 其他請留空)：', '1');

    let category = Category.OTHER;
    if (categoryName === '1') category = Category.PROTECTION;
    else if (categoryName === '2') category = Category.FIRE_SAFETY;
    else if (categoryName === '3') category = Category.FIRST_AID;
    else if (categoryName === '4') category = Category.SIGNAGE;
    else if (categoryName === '5') category = Category.TOOL;

    const newItem: InventoryItem = {
      id: crypto.randomUUID(),
      name,
      category,
      unit,
      quantity: 0,
      minStock,
      description: '',
      lastUpdated: Date.now()
    };
    setItems(prev => [...prev, newItem]);
