        {activeTab === 'issuance' && <IssuanceView />}

        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden animate-in fade-in duration-500">
            <div className="p-8 border-b bg-slate-50/50 flex justify-between items-center">
               <h3 className="font-black text-2xl text-slate-800">庫存流水帳 (異動紀錄)</h3>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50 text-slate-500 font-black text-xs uppercase tracking-widest border-b">
                  <tr>
                    <th className="px-8 py-5">日期時間</th>
                    <th className="px-8 py-5">項目</th>
                    <th className="px-8 py-5">類型</th>
                    <th className="px-8 py-5">數量</th>
                    <th className="px-8 py-5">部門/領用人/日期</th>
                    <th className="px-8 py-5 text-right">單據</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {logs.map(log => (
                    <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                      <td className="px-8 py-5 font-mono font-bold text-slate-500">{new Date(log.timestamp).toLocaleString()}</td>
                      <td className="px-8 py-5 font-black text-slate-900 text-lg">{log.itemName}</td>
                      <td className="px-8 py-5">
                        {log.type === 'OUT' ? <span className="text-rose-600 font-black">領用</span> : <span className="text-emerald-600 font-black">補貨</span>}
                      </td>
                      <td className="px-8 py-5 font-black text-slate-900">{log.quantity}</td>
                      <td className="px-8 py-5 font-bold text-slate-700">{log.person}</td>
                      <td className="px-8 py-5 text-right">
                         {log.type === 'OUT' && (
                           <button onClick={() => { setLastTransaction(log); setShowPrintModal(true); }} className="p-2 bg-blue-50 text-blue-600 rounded-xl hover:bg-blue-100 transition-all">
                             <Printer size={18} />
                           </button>
                         )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </main>

      {/* 單據預覽彈窗 */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex flex-col items-center justify-start p-4 overflow-y-auto backdrop-blur-2xl animate-in fade-in duration-300">
          <div className="w-full max-w-5xl bg-white rounded-[3rem] shadow-2xl relative my-10 overflow-hidden">
            <div className="p-8 border-b bg-white flex justify-between items-center sticky top-0 z-10 shadow-md">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg shadow-indigo-200"><Printer size={26} /></div>
                <h3 className="font-black text-slate-900 text-2xl tracking-tighter">台電工安領用單 - 正式格式預覽</h3>
              </div>
              <div className="flex gap-4">
                <button 
                  onClick={() => window.print()} 
                  className="px-12 py-4 bg-indigo-600 text-white rounded-2xl font-black text-lg flex items-center gap-3 hover:bg-indigo-700 shadow-xl shadow-indigo-100 transition-all active:scale-95"
                >
                  <Printer size={22} /> 確認並列印單據
                </button>
                <button onClick={() => setShowPrintModal(false)} className="p-4 text-gray-300 hover:text-black hover:bg-gray-100 rounded-full transition-all">
                  <X size={32} />
                </button>
              </div>
            </div>
            <div className="p-10 md:p-20 bg-slate-200/50 flex justify-center">
              <div className="shadow-[0_0_100px_-20px_rgba(0,0,0,0.3)] bg-white origin-top scale-90 md:scale-100">
                <PrintableForm transaction={lastTransaction} />
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

payload.text:
您說得完全正確。**「手動同步」永遠會有遺漏的風險**，而「雲端資料庫」才是解決多人協作、資料一致性的唯一終極方案。

採用 **Google Sheets (試算表)** 作為後端的好處是：
1.  **免費且視覺化**：主管不開網頁也能直接在 Excel/Google Sheets 看到總表。
2.  **低門檻**：不需要購買專業伺服器。
3.  **多人即時**：A 登記完，B 重新整理網頁就會看到最新庫存。

### 實現方法：Google Apps Script (GAS) 橋樑
我們需要建立一個 Google 試算表，並在裡面寫一段簡單的腳本（GAS），讓網頁可以透過這個腳本把資料寫進試算表。

---

### 第一步：準備您的雲端資料庫 (Google 試算表設定)

請按照以下步驟操作：
1.  建立一個新的 **Google 試算表**。
2.  點擊選單的 **「延伸功能」 > 「Apps Script」**。
3.  將原本的內容清空，貼上以下代碼：

```javascript
// Google Apps Script 程式碼
function doGet() {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  var data = sheet.getRange(1, 1).getValue();
  return ContentService.createTextOutput(data).setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  var data = e.postData.contents;
  sheet.getRange(1, 1).setValue(data);
  return ContentService.createTextOutput("Success");
}
```

4.  點擊右上角 **「部署」 > 「新部署」**。
5.  種類選擇 **「網頁應用程式」**。
    *   描述：工安系統同步
    *   執行身分：**我 (您的帳號)**
    *   誰有權限存取：**任何人** (這很重要，否則網頁無法連線)
6.  部署後，**複製產生的「網頁應用程式 URL」**，這就是您的雲端 API 地址。

---

### 第二步：更新網頁系統程式碼
我現在為系統加入 **「Google Sheets 即時同步模式」**。您只需要在系統設定中貼上剛才得到的 URL，系統就會從「本地儲存」切換到「雲端同步」。

#### 更新重點：
1.  **雲端連線設定**：側邊欄新增「Google 試算表連線」設定。
2.  **自動同步邏輯**：當您完成領用、入庫、新增項目時，系統會自動將整份資料庫推送到 Google 試算表。
3.  **手動重新整理**：新增「從雲端抓取」按鈕，確保讀取到同事最新的操作。

