import React, { useState, useEffect, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  AlertTriangle,
  ArrowDownCircle,
  ArrowUpCircle,
  Sparkles,
  Search,
  CheckCircle2,
  X,
  Printer,
  Calendar,
  Download,
  Upload,
  Database,
  Cloud,
  RefreshCw,
  Settings,
  Link2
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_items';
const STORAGE_KEY_LOGS = 'safeman_logs';
const STORAGE_KEY_CLOUD_URL = 'safeman_cloud_url';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'issuance' | 'history'>('dashboard');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [cloudUrl, setCloudUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_CLOUD_URL) || '');
  const [isSyncing, setIsSyncing] = useState(false);
  const [aiAdvice, setAiAdvice] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  // 初始化讀取
  useEffect(() => {
    const initLoad = async () => {
      if (cloudUrl) {
        await fetchFromCloud();
      } else {
        const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
        const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
        if (savedItems) setItems(JSON.parse(savedItems));
        if (savedLogs) setLogs(JSON.parse(savedLogs));
      }
    };
    initLoad();
  }, []);

  // 雲端同步：抓取
  const fetchFromCloud = async () => {
    if (!cloudUrl) return;
    setIsSyncing(true);
    try {
      const response = await fetch(cloudUrl);
      const data = await response.json();
      if (data.items) {
        setItems(data.items);
        setLogs(data.logs || []);
        // 同步更新本地備份
        localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(data.items));
        localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(data.logs));
      }
    } catch (err) {
      console.error('雲端抓取失敗', err);
      alert('無法連線至 Google 試算表，請檢查 URL 是否正確或已部署為「任何人」。');
    } finally {
      setIsSyncing(false);
    }
  };

  // 雲端同步：儲存
  const saveToCloud = async (newItems: InventoryItem[], newLogs: Transaction[]) => {
    // 先存本地
    localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(newItems));
    localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(newLogs));

    if (!cloudUrl) return;
    setIsSyncing(true);
    try {
      await fetch(cloudUrl, {
        method: 'POST',
        mode: 'no-cors', // GAS postData 限制
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items: newItems, logs: newLogs, lastUpdate: Date.now() })
      });
      console.log('雲端儲存指令已送出');
    } catch (err) {
      console.error('雲端儲存失敗', err);
    } finally {
      setIsSyncing(false);
    }
  };

  // Inventory Handlers
  const deleteItem = async (id: string) => {
    if (window.confirm('確定要刪除此耗材項目嗎？')) {
      const updated = items.filter(item => item.id !== id);
      setItems(updated);
      await saveToCloud(updated, logs);
    }
  };

  const addItem = async () => {
    const name = prompt('請輸入耗材名稱：');
    if (!name) return;
    const unit = prompt('計量單位 (個/卷/雙)：', '個') || '個';
    const min = Number(prompt('安全庫存量：', '5')) || 5;

    const newItem: InventoryItem = {
      id: crypto.randomUUID(),
      name,
      category: Category.PROTECTION,
      unit,
      quantity: 0,
      minStock: min,
      description: '',
      lastUpdated: Date.now()
    };
    const updated = [...items, newItem];
    setItems(updated);
    await saveToCloud(updated, logs);
  };

  const createTransaction = async (itemId: string, type: TransactionType, qty: number, person: string, reason: string) => {
    const targetItem = items.find(i => i.id === itemId);
    if (!targetItem) return;

    if (type === 'OUT' && targetItem.quantity < qty) {
      alert('庫存不足！');
      return;
    }

    const updatedItems = items.map(i => {
      if (i.id === itemId) {
        return { ...i, quantity: type === 'IN' ? i.quantity + qty : i.quantity - qty, lastUpdated: Date.now() };
      }
      return i;
    });

    const newLog: Transaction = {
      id: crypto.randomUUID(),
      itemId,
      itemName: targetItem.name,
      type,
      quantity: qty,
      person,
      reason,
      timestamp: Date.now()
    };

    const updatedLogs = [newLog, ...logs];
    setItems(updatedItems);
    setLogs(updatedLogs);
    setLastTransaction(newLog);

    await saveToCloud(updatedItems, updatedLogs);

    if (type === 'OUT') setShowPrintModal(true);
    else alert('補貨成功且雲端已同步！');
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    const advice = await getInventoryInsights(items);
    setAiAdvice(advice);
    setIsAiLoading(false);
  };

  // --- UI Components (簡化版示意) ---

  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
