      <div className="bg-white p-8 max-w-[210mm] mx-auto text-black font-serif border-[3px] border-black" id="print-area">
        <h1 className="text-2xl font-black text-center mb-6 border-b-2 border-black pb-2">台灣電力公司電力修護處南部分處領用單</h1>
        <div className="flex justify-between mb-4 font-bold">
          <p>部門：{transaction.person}</p>
          <p>日期：{now.toLocaleDateString()}</p>
        </div>
        <table className="w-full border-collapse border-2 border-black text-center">
          <thead>
            <tr className="bg-gray-100">
              <th className="border-2 border-black p-3">名稱</th>
              <th className="border-2 border-black p-3">單位</th>
              <th className="border-2 border-black p-3">數量</th>
              <th className="border-2 border-black p-3">備註</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td className="border-2 border-black p-4 font-black">{transaction.itemName}</td>
              <td className="border-2 border-black p-4">{targetItem?.unit}</td>
              <td className="border-2 border-black p-4 font-black text-xl">{transaction.quantity}</td>
              <td className="border-2 border-black p-4">{transaction.reason}</td>
            </tr>
          </tbody>
        </table>
        <div className="mt-12 grid grid-cols-3 text-center font-bold">
          <p>經辦：__________</p>
          <p>課長：__________</p>
          <p>經理：__________</p>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-slate-50">
      {/* Sidebar */}
      <aside className="w-72 bg-slate-900 text-white p-8 flex flex-col shadow-2xl">
        <div className="flex items-center gap-4 mb-14">
          <div className="p-3 bg-blue-600 rounded-2xl shadow-lg"><Package size={28} /></div>
          <h1 className="font-black text-xl">工安雲端管理</h1>
        </div>

        <nav className="flex-1 space-y-4">
          {[
            { id: 'dashboard', icon: LayoutDashboard, label: '數據總覽' },
            { id: 'inventory', icon: Package, label: '資料庫' },
            { id: 'issuance', icon: FileText, label: '領用登記' },
            { id: 'history', icon: History, label: '歷史紀錄' },
          ].map((tab) => (
            <button 
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl font-black ${activeTab === tab.id ? 'bg-blue-600 shadow-xl' : 'text-slate-400 hover:bg-slate-800'}`}
            >
              <tab.icon size={22} /> {tab.label}
            </button>
          ))}
        </nav>

        {/* 雲端狀態與設定 */}
        <div className="mt-auto pt-6 border-t border-slate-800 space-y-3">
          <div className={`p-4 rounded-2xl border ${cloudUrl ? 'bg-emerald-500/10 border-emerald-500/50' : 'bg-slate-800 border-slate-700'}`}>
            <div className="flex items-center justify-between mb-2">
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-1">
                <Cloud size={12} /> {cloudUrl ? '雲端連線中' : '僅限本地'}
              </span>
              <button onClick={() => setShowSettings(true)} className="text-slate-400 hover:text-white"><Settings size={14} /></button>
            </div>
            {cloudUrl && (
              <button 
                onClick={fetchFromCloud}
                disabled={isSyncing}
                className="w-full py-2 bg-emerald-600 hover:bg-emerald-500 rounded-xl text-[10px] font-black flex items-center justify-center gap-2 transition-all"
              >
                <RefreshCw size={12} className={isSyncing ? 'animate-spin' : ''} />
                {isSyncing ? '同步中' : '手動重新整理雲端'}
              </button>
            )}
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-12 overflow-y-auto">
        <header className="mb-12 flex justify-between items-end border-b pb-10">
