        {activeTab === 'inventory' && (
          <div className="bg-white rounded-3xl shadow-sm border p-8">
            <div className="flex justify-between mb-8">
              <h3 className="font-black text-xl">資產清冊</h3>
              <button onClick={addItem} className="bg-blue-600 text-white px-6 py-2 rounded-xl font-black flex items-center gap-2 hover:bg-blue-700">
