          <div className="bg-white rounded-3xl shadow-sm border overflow-hidden">
             <table className="w-full text-left">
               <thead className="bg-slate-50 text-slate-500 font-black text-xs border-b">
                 <tr><th className="p-5">日期</th><th className="p-5">項目</th><th className="p-5">類型</th><th className="p-5">人員</th><th className="p-5 text-right">單據</th></tr>
               </thead>
               <tbody className="divide-y">
                 {logs.map(log => (
                   <tr key={log.id}>
                     <td className="p-5 text-xs text-slate-500">{new Date(log.timestamp).toLocaleString()}</td>
                     <td className="p-5 font-black">{log.itemName}</td>
                     <td className={`p-5 font-black ${log.type === 'OUT' ? 'text-rose-500' : 'text-emerald-500'}`}>{log.type === 'OUT' ? '領用' : '補貨'}</td>
                     <td className="p-5 font-bold">{log.person}</td>
                     <td className="p-5 text-right">{log.type === 'OUT' && <button onClick={() => {setLastTransaction(log); setShowPrintModal(true);}}><Printer size={18} /></button>}</td>
                   </tr>
                 ))}
               </tbody>
             </table>
          </div>
        )}
      </main>

      {/* 設定彈窗 */}
      {showSettings && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-md shadow-2xl overflow-hidden">
            <div className="p-8 border-b bg-slate-50 flex justify-between items-center">
              <h3 className="font-black text-xl flex items-center gap-2"><Cloud className="text-blue-600" /> 雲端同步設定</h3>
              <button onClick={() => setShowSettings(false)}><X /></button>
            </div>
            <div className="p-8 space-y-6">
              <div>
                <label className="block text-xs font-black text-slate-400 uppercase mb-2">Google Apps Script Web App URL</label>
                <div className="relative">
                  <Link2 className="absolute left-4 top-4 text-slate-300" size={18} />
                  <input 
                    type="text" 
                    className="w-full pl-12 pr-4 py-4 bg-slate-50 border-2 border-slate-200 rounded-2xl font-bold focus:border-blue-500 outline-none"
                    placeholder="https://script.google.com/macros/s/.../exec"
                    value={cloudUrl}
                    onChange={(e) => setCloudUrl(e.target.value)}
                  />
                </div>
                <p className="mt-4 text-[11px] text-slate-500 leading-relaxed font-medium bg-blue-50 p-4 rounded-xl border border-blue-100">
                  ⚠️ 貼上 URL 並點擊儲存後，系統將自動從 Google 試算表讀取資料。若此處留空，則資料僅會儲存在您的瀏覽器中。
                </p>
              </div>
              <button 
                onClick={() => {
                  localStorage.setItem(STORAGE_KEY_CLOUD_URL, cloudUrl);
                  setShowSettings(false);
                  if(cloudUrl) fetchFromCloud();
                }}
                className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black shadow-lg"
              >
                儲存連線設定
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 單據彈窗 */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-black/90 z-[110] flex flex-col items-center justify-start p-4 overflow-y-auto">
          <div className="w-full max-w-4xl bg-white rounded-3xl my-10 relative shadow-2xl overflow-hidden">
            <div className="p-6 border-b flex justify-between items-center sticky top-0 bg-white z-10">
              <h3 className="font-black text-xl">預覽領用單據</h3>
              <div className="flex gap-4">
                <button onClick={() => window.print()} className="px-8 py-3 bg-blue-600 text-white rounded-xl font-black">列印</button>
                <button onClick={() => setShowPrintModal(false)} className="p-3 text-slate-400"><X /></button>
              </div>
            </div>
            <div className="p-10 bg-slate-100 flex justify-center">
              <PrintableForm transaction={lastTransaction} />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  AlertTriangle,
  RefreshCw,
  Sparkles,
  Search,
  CheckCircle2,
  X,
  Printer,
  Cloud,
  Settings,
  Link2,
  Database,
  Info
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_items';
const STORAGE_KEY_LOGS = 'safeman_logs';
const STORAGE_KEY_CLOUD_URL = 'safeman_cloud_url';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'issuance' | 'history'>('dashboard');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [cloudUrl, setCloudUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_CLOUD_URL) || '');
  const [isSyncing, setIsSyncing] = useState(false);
  const [aiAdvice, setAiAdvice] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // 初始化讀取：優先從雲端，失敗或無 URL 則讀本地
  useEffect(() => {
    const initLoad = async () => {
      if (cloudUrl) {
        await fetchFromCloud();
      } else {
        const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
        const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
        setItems(savedItems ? JSON.parse(savedItems) : []);
        setLogs(savedLogs ? JSON.parse(savedLogs) : []);
      }
    };
    initLoad();
  }, []);

  const fetchFromCloud = async () => {
    if (!cloudUrl) return;
    setIsSyncing(true);
    try {
      const response = await fetch(cloudUrl);
      const text = await response.text();
      // 如果試算表是空的，text 會是空的，JSON.parse 會報錯
      if (!text || text.trim() === "") {
        console.log("雲端資料庫尚無資料，初始化中...");
        setItems([]);
        setLogs([]);
        return;
      }
      const data = JSON.parse(text);
      setItems(data.items || []);
      setLogs(data.logs || []);
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(data.items || []));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(data.logs || []));
    } catch (err) {
      console.error('雲端抓取失敗', err);
      // 失敗時讀取本地作為備案
      const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
      const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
      setItems(savedItems ? JSON.parse(savedItems) : []);
      setLogs(savedLogs ? JSON.parse(savedLogs) : []);
    } finally {
      setIsSyncing(false);
    }
  };

  const saveToCloud = async (newItems: InventoryItem[], newLogs: Transaction[]) => {
    // 永遠先同步更新本地儲存
    localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(newItems));
    localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(newLogs));

    if (!cloudUrl) return;
    setIsSyncing(true);
    try {
      await fetch(cloudUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items: newItems, logs: newLogs, lastUpdate: Date.now() })
      });
    } catch (err) {
      console.error('雲端儲存失敗', err);
    } finally {
      setIsSyncing(false);
    }
  };

  const deleteItem = async (id: string) => {
    if (window.confirm('確定要永久刪除此耗材項目？')) {
      const updated = items.filter(item => item.id !== id);
      setItems(updated);
      await saveToCloud(updated, logs);
    }
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    unit: '個',
    minStock: 5,
    description: ''
  });

  const handleAddItem = async () => {
    if (!newForm.name) return alert('請輸入項目名稱');
    const newItem: InventoryItem = {
      ...newForm,
      id: crypto.randomUUID(),
      quantity: 0,
      lastUpdated: Date.now()
    };
    const updated = [...items, newItem];
    setItems(updated);
    await saveToCloud(updated, logs);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, unit: '個', minStock: 5, description: '' });
  };

  const createTransaction = async (itemId: string, type: TransactionType, qty: number, person: string, reason: string) => {
    const targetItem = items.find(i => i.id === itemId);
    if (!targetItem) return;
    if (type === 'OUT' && targetItem.quantity < qty) return alert('庫存不足！');

    const updatedItems = items.map(i => {
      if (i.id === itemId) {
        return { ...i, quantity: type === 'IN' ? i.quantity + qty : i.quantity - qty, lastUpdated: Date.now() };
      }
      return i;
    });

    const newLog: Transaction = {
      id: crypto.randomUUID(),
      itemId,
      itemName: targetItem.name,
      type,
      quantity: qty,
      person,
      reason,
      timestamp: Date.now()
    };

    const updatedLogs = [newLog, ...logs];
    setItems(updatedItems);
    setLogs(updatedLogs);
    setLastTransaction(newLog);
    await saveToCloud(updatedItems, updatedLogs);

    if (type === 'OUT') setShowPrintModal(true);
    else alert('補貨登記成功。');
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    const advice = await getInventoryInsights(items);
    setAiAdvice(advice);
    setIsAiLoading(false);
  };

  // --- Components ---

  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const now = new Date(transaction.timestamp);
    const year = now.getFullYear() - 1911;
    return (
      <div className="bg-white p-10 max-w-[210mm] mx-auto text-black font-serif border-[4px] border-black" id="print-area">
        <style>{`@media print { body * { visibility: hidden; } #print-area, #print-area * { visibility: visible; } #print-area { position: absolute; left:0; top:0; width:100%; border:none; } }`}</style>
        <h1 className="text-3xl font-black text-center mb-10 border-b-[4px] border-black pb-4">台灣電力公司電力修護處南部分處領用單</h1>
        <div className="flex justify-between mb-6 text-xl font-black px-2">
          <p>部門：<span className="underline underline-offset-8 px-4">{transaction.person}</span></p>
          <p>中華民國 {year} 年 {now.getMonth()+1} 月 {now.getDate()} 日</p>
        </div>
        <table className="w-full border-collapse border-[4px] border-black text-center">
          <thead>
            <tr className="bg-gray-100 border-b-[4px] border-black">
              <th className="border-r-[4px] border-black p-4 text-xl font-black">耗材名稱</th>
              <th className="border-r-[4px] border-black p-4 text-xl font-black">單位</th>
              <th className="border-r-[4px] border-black p-4 text-xl font-black">數量</th>
              <th className="p-4 text-xl font-black">備註</th>
            </tr>
          </thead>
          <tbody>
            <tr className="border-b-[4px] border-black">
              <td className="border-r-[4px] border-black p-8 text-2xl font-black">{transaction.itemName}</td>
              <td className="border-r-[4px] border-black p-8 text-xl font-black">{targetItem?.unit}</td>
              <td className="border-r-[4px] border-black p-8 text-4xl font-black">{transaction.quantity}</td>
              <td className="p-8 text-lg font-bold">{transaction.reason}</td>
            </tr>
            {[...Array(8)].map((_, i) => (
              <tr key={i} className="border-b-[4px] border-black h-16"><td className="border-r-[4px] border-black"></td><td className="border-r-[4px] border-black"></td><td className="border-r-[4px] border-black"></td><td></td></tr>
            ))}
          </tbody>
        </table>
        <div className="mt-16 grid grid-cols-3 gap-8 text-xl font-black text-center">
          <p>經辦：__________</p><p>課長：__________</p><p>經理：__________</p>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-[#F0F2F5]">
      {/* Sidebar */}
      <aside className="w-80 bg-[#0F172A] text-white p-8 sticky top-0 h-screen flex flex-col shadow-2xl">
        <div className="flex items-center gap-4 mb-14 px-2">
          <div className="p-3.5 bg-blue-600 rounded-2xl shadow-xl shadow-blue-500/30 rotate-3"><Package size={30} /></div>
          <div>
            <h1 className="font-black text-2xl tracking-tighter">工安管理系統</h1>
            <p className="text-[10px] text-blue-400 font-black tracking-widest uppercase">Cloud Sync Pro</p>
          </div>
        </div>

        <nav className="flex-1 space-y-4">
          {[
            { id: 'dashboard', icon: LayoutDashboard, label: '儀表板分析' },
            { id: 'inventory', icon: Package, label: '耗材資料庫' },
            { id: 'issuance', icon: FileText, label: '領用登記作業' },
            { id: 'history', icon: History, label: '異動歷史日誌' },
          ].map((tab) => (
            <button 
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl font-black transition-all ${activeTab === tab.id ? 'bg-blue-600 shadow-xl shadow-blue-600/30' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
            >
              <tab.icon size={22} /> {tab.label}
            </button>
          ))}
        </nav>

        <div className="mt-auto space-y-4">
          <div className={`p-5 rounded-3xl border transition-all ${cloudUrl ? 'bg-emerald-500/10 border-emerald-500/30' : 'bg-slate-800 border-slate-700'}`}>
            <div className="flex items-center justify-between mb-3">
              <span className={`text-[10px] font-black uppercase tracking-widest flex items-center gap-1.5 ${cloudUrl ? 'text-emerald-400' : 'text-slate-500'}`}>
                <Cloud size={14} /> {cloudUrl ? '雲端同步啟動' : '離線模式'}
              </span>
              <button onClick={() => setShowSettings(true)} className="p-1 hover:bg-white/10 rounded-lg"><Settings size={14} /></button>
            </div>
            {cloudUrl && (
              <button 
                onClick={fetchFromCloud}
                disabled={isSyncing}
                className="w-full py-3 bg-emerald-600 hover:bg-emerald-500 rounded-xl text-xs font-black flex items-center justify-center gap-2 shadow-lg shadow-emerald-900/20 disabled:opacity-50"
              >
                <RefreshCw size={14} className={isSyncing ? 'animate-spin' : ''} />
                {isSyncing ? '同步中...' : '立即重新整理資料'}
              </button>
            )}
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-12 overflow-y-auto">
        <header className="mb-14 flex justify-between items-end border-b-2 border-slate-200 pb-12">
          <div>
            <h2 className="text-5xl font-black text-slate-900 tracking-tighter">
              {activeTab === 'dashboard' && '數據決策中心'}
              {activeTab === 'inventory' && '設備資產清冊'}
              {activeTab === 'issuance' && '自動化登記作業'}
              {activeTab === 'history' && '全紀錄日誌'}
            </h2>
            <p className="mt-3 text-slate-500 font-bold flex items-center gap-2">
              <span className="w-2 h-2 bg-green-500 rounded-full"></span> 
              系統狀態：正常連線中 • 最後更新：{new Date().toLocaleTimeString()}
            </p>
          </div>
        </header>

        {activeTab === 'dashboard' && (
          <div className="space-y-10 animate-in fade-in duration-700">
            <div className="grid grid-cols-3 gap-10">
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100">
                <p className="text-slate-400 font-black text-xs uppercase tracking-widest mb-2">總資產項目</p>
                <p className="text-6xl font-black text-slate-900">{items.length}</p>
              </div>
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100">
                <p className="text-rose-500 font-black text-xs uppercase tracking-widest mb-2">低庫存警示項目</p>
                <p className="text-6xl font-black text-rose-600">{items.filter(i => i.quantity <= i.minStock).length}</p>
              </div>
              <div className="bg-slate-900 p-10 rounded-[2.5rem] shadow-2xl text-white relative overflow-hidden group">
                <div className="relative z-10">
                  <h3 className="text-xl font-black mb-4 flex items-center gap-3"><Sparkles className="text-blue-400" /> AI 管理建議</h3>
                  <div className="bg-white/10 backdrop-blur-md p-5 rounded-2xl border border-white/10 text-sm leading-relaxed text-slate-200 font-medium italic">
                    {aiAdvice || "讓 AI 分析您的庫存數據，點擊按鈕獲取建議。"}
                  </div>
                  <button onClick={fetchAiInsights} className="mt-6 px-8 py-3 bg-blue-600 rounded-xl font-black text-xs hover:bg-blue-500 transition-all">
                    {isAiLoading ? '分析中...' : '立即分析'}
                  </button>
                </div>
                <Package className="absolute right-[-20px] bottom-[-20px] w-48 h-48 text-white/5 -rotate-12 group-hover:rotate-0 transition-all duration-700" />
              </div>
            </div>
          </div>
        )}

        {activeTab === 'inventory' && (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4">
            <div className="flex justify-between items-center bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
              <div className="relative w-96">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  type="text" 
                  placeholder="搜尋耗材項目名稱..." 
                  className="w-full pl-12 pr-4 py-3 bg-slate-50 border-2 border-slate-100 rounded-2xl font-bold focus:border-blue-500 focus:bg-white outline-none"
                  value={searchTerm}
                  onChange={e => setSearchTerm(e.target.value)}
                />
              </div>
              <button onClick={() => setShowAddModal(true)} className="px-8 py-3.5 bg-blue-600 text-white rounded-2xl font-black flex items-center gap-3 shadow-lg shadow-blue-100 hover:scale-105 active:scale-95 transition-all">
                <Plus size={20} /> 新增耗材項目
              </button>
            </div>

            <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
              <table className="w-full text-left">
                <thead className="bg-slate-50 border-b-2 border-slate-100">
                  <tr>
                    <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-widest">耗材名稱 / 規格</th>
                    <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-widest">當前庫存量</th>
                    <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-widest">安全警戒值</th>
                    <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-widest text-right">操作項目</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {items.filter(i => i.name.includes(searchTerm)).map(item => (
                    <tr key={item.id} className="hover:bg-slate-50 transition-colors group">
                      <td className="px-10 py-8">
                        <div className="font-black text-xl text-slate-900">{item.name}</div>
                        <div className="text-xs text-slate-400 font-bold mt-1">{item.description || '無詳細規格備註'}</div>
                      </td>
                      <td className="px-10 py-8">
                        <span className={`px-5 py-2 rounded-xl font-black text-lg ${item.quantity <= item.minStock ? 'bg-rose-50 text-rose-600 border border-rose-100' : 'bg-emerald-50 text-emerald-600 border border-emerald-100'}`}>
