                    <select id="iss-id" className="w-full px-6 py-5 bg-slate-50 border-4 border-slate-100 rounded-3xl font-black text-2xl outline-none focus:border-blue-500 focus:bg-white transition-all">
                      <option value="">點擊選擇耗材...</option>
