                  <input 
                    type="text" 
                    className="w-full pl-14 pr-6 py-5 bg-slate-50 border-4 border-slate-100 rounded-3xl font-bold focus:border-blue-500 outline-none text-blue-600"
                    placeholder="https://script.google.com/macros/s/.../exec"
                    value={cloudUrl}
                    onChange={(e) => setCloudUrl(e.target.value)}
                  />
