                  <Info className="shrink-0" size={20} />
                  貼上 URL 後，點擊儲存系統將自動抓取雲端資料。若欄位留空，則僅會使用本地暫存。
                </p>
              </div>
              <button 
                onClick={() => {
                  localStorage.setItem(STORAGE_KEY_CLOUD_URL, cloudUrl);
