      )}

      {/* 單據預覽彈窗 */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-black/95 z-[150] flex flex-col items-center justify-start p-4 overflow-y-auto backdrop-blur-md">
          <div className="w-full max-w-5xl bg-white rounded-[4rem] my-10 relative shadow-2xl overflow-hidden border border-white/20 animate-in slide-in-from-bottom-10">
