};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  AlertTriangle,
  RefreshCw,
  Sparkles,
  Search,
  CheckCircle2,
  X,
  Printer,
  Cloud,
  Settings,
  Link2,
  Database,
  Info,
  ArrowRightCircle
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_items';
const STORAGE_KEY_LOGS = 'safeman_logs';
const STORAGE_KEY_CLOUD_URL = 'safeman_cloud_url';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'issuance' | 'history'>('dashboard');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [cloudUrl, setCloudUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_CLOUD_URL) || '');
  const [isSyncing, setIsSyncing] = useState(false);
  const [aiAdvice, setAiAdvice] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // 登記表單狀態
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState(1);
  const [inputPerson, setInputPerson] = useState('');
  const [inputReason, setInputReason] = useState('');

  // 初始化讀取
  useEffect(() => {
    const initLoad = async () => {
      if (cloudUrl) {
        await fetchFromCloud();
      } else {
        const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
        const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
        setItems(savedItems ? JSON.parse(savedItems) : []);
        setLogs(savedLogs ? JSON.parse(savedLogs) : []);
      }
    };
    initLoad();
  }, []);

  const fetchFromCloud = async () => {
    if (!cloudUrl) return;
    setIsSyncing(true);
    try {
      const response = await fetch(cloudUrl);
      const text = await response.text();
      if (!text || text.trim() === "") {
        setItems([]);
        setLogs([]);
        return;
      }
      const data = JSON.parse(text);
      setItems(data.items || []);
      setLogs(data.logs || []);
    } catch (err) {
      console.error('雲端抓取失敗', err);
    } finally {
      setIsSyncing(false);
    }
  };

  const saveToCloud = async (newItems: InventoryItem[], newLogs: Transaction[]) => {
    localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(newItems));
    localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(newLogs));

    if (!cloudUrl) return;
    setIsSyncing(true);
    try {
      await fetch(cloudUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items: newItems, logs: newLogs, lastUpdate: Date.now() })
      });
    } catch (err) {
      console.error('雲端儲存失敗', err);
    } finally {
      setIsSyncing(false);
    }
  };

  const deleteItem = async (id: string) => {
    if (window.confirm('確定要永久刪除此耗材項目？刪除後無法復原。')) {
      const updated = items.filter(item => item.id !== id);
      setItems(updated);
      await saveToCloud(updated, logs);
    }
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    unit: '個',
    minStock: 5,
    description: ''
  });

  const handleAddItem = async () => {
    if (!newForm.name) return alert('請輸入項目名稱');
    const newItem: InventoryItem = {
      ...newForm,
      id: crypto.randomUUID(),
      quantity: 0,
      lastUpdated: Date.now()
    };
    const updated = [...items, newItem];
    setItems(updated);
    await saveToCloud(updated, logs);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, unit: '個', minStock: 5, description: '' });
  };

  const handleTransaction = async () => {
    if (!selectedItemId || !inputPerson || inputQty <= 0) {
      return alert('請完整填寫：項目、人員/日期、以及正確數量。');
    }

    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    if (issuanceMode === 'OUT' && targetItem.quantity < inputQty) {
      return alert('庫存不足，無法領用！');
    }

    const updatedItems = items.map(i => {
      if (i.id === selectedItemId) {
        return { 
          ...i, 
          quantity: issuanceMode === 'IN' ? i.quantity + inputQty : i.quantity - inputQty, 
          lastUpdated: Date.now() 
        };
      }
      return i;
    });

    const newLog: Transaction = {
      id: crypto.randomUUID(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: inputQty,
      person: inputPerson,
      reason: inputReason,
      timestamp: Date.now()
    };

    const updatedLogs = [newLog, ...logs];
    setItems(updatedItems);
    setLogs(updatedLogs);
    setLastTransaction(newLog);
    await saveToCloud(updatedItems, updatedLogs);

    // 重置表單
    setSelectedItemId('');
    setInputQty(1);
    setInputPerson('');
    setInputReason('');

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      alert('補貨登記已完成且已同步雲端。');
    }
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    const advice = await getInventoryInsights(items);
    setAiAdvice(advice);
    setIsAiLoading(false);
  };

  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const now = new Date(transaction.timestamp);
    const year = now.getFullYear() - 1911;
    return (
      <div className="bg-white p-12 w-[210mm] mx-auto text-black font-serif border-[4px] border-black" id="print-area">
        <h1 className="text-3xl font-black text-center mb-10 border-b-[4px] border-black pb-4">台灣電力公司電力修護處南部分處領用單</h1>
        <div className="flex justify-between mb-6 text-xl font-black px-2">
          <p>部門：<span className="underline underline-offset-8 px-4">{transaction.person}</span></p>
          <p>中華民國 {year} 年 {now.getMonth()+1} 月 {now.getDate()} 日</p>
        </div>
        <table className="w-full border-collapse border-[4px] border-black text-center">
          <thead>
            <tr className="bg-gray-100 border-b-[4px] border-black">
              <th className="border-r-[4px] border-black p-4 text-xl font-black">耗材名稱 / 規格</th>
              <th className="border-r-[4px] border-black p-4 text-xl font-black">單位</th>
              <th className="border-r-[4px] border-black p-4 text-xl font-black">數量</th>
              <th className="p-4 text-xl font-black">備註</th>
            </tr>
          </thead>
          <tbody>
            <tr className="border-b-[4px] border-black">
              <td className="border-r-[4px] border-black p-8 text-2xl font-black">{transaction.itemName}</td>
              <td className="border-r-[4px] border-black p-8 text-xl font-black">{targetItem?.unit}</td>
              <td className="border-r-[4px] border-black p-8 text-4xl font-black">{transaction.quantity}</td>
              <td className="p-8 text-lg font-bold">{transaction.reason}</td>
            </tr>
            {[...Array(6)].map((_, i) => (
              <tr key={i} className="border-b-[4px] border-black h-16">
                <td className="border-r-[4px] border-black"></td><td className="border-r-[4px] border-black"></td><td className="border-r-[4px] border-black"></td><td></td>
              </tr>
            ))}
          </tbody>
        </table>
        <div className="mt-16 grid grid-cols-3 gap-8 text-xl font-black text-center">
          <p>經辦：__________</p><p>課長：__________</p><p>經理：__________</p>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-[#F8FAFC]">
      {/* Sidebar */}
      <aside className="w-80 bg-[#0F172A] text-white p-8 sticky top-0 h-screen flex flex-col shadow-2xl">
        <div className="flex items-center gap-4 mb-14">
          <div className="p-3.5 bg-blue-600 rounded-2xl shadow-xl shadow-blue-500/30"><Package size={30} /></div>
          <div>
            <h1 className="font-black text-2xl tracking-tighter">工安管理系統</h1>
            <p className="text-[10px] text-blue-400 font-black tracking-widest uppercase">Cloud Sync Pro</p>
          </div>
        </div>

        <nav className="flex-1 space-y-4">
          {[
            { id: 'dashboard', icon: LayoutDashboard, label: '儀表板' },
            { id: 'inventory', icon: Package, label: '耗材資料庫' },
            { id: 'issuance', icon: FileText, label: '登記作業' },
            { id: 'history', icon: History, label: '紀錄日誌' },
          ].map((tab) => (
            <button 
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl font-black transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}
            >
              <tab.icon size={22} /> {tab.label}
            </button>
          ))}
        </nav>

        <div className="mt-auto space-y-4">
          <div className={`p-5 rounded-3xl border transition-all ${cloudUrl ? 'bg-emerald-500/10 border-emerald-500/30' : 'bg-slate-800 border-slate-700'}`}>
            <div className="flex items-center justify-between mb-3">
              <span className={`text-[10px] font-black uppercase tracking-widest flex items-center gap-1.5 ${cloudUrl ? 'text-emerald-400' : 'text-slate-500'}`}>
                <Cloud size={14} /> {cloudUrl ? '雲端同步中' : '離線模式'}
              </span>
              <button onClick={() => setShowSettings(true)} className="p-1 hover:bg-white/10 rounded-lg text-slate-400 hover:text-white transition-colors"><Settings size={16} /></button>
            </div>
            {cloudUrl && (
              <button onClick={fetchFromCloud} disabled={isSyncing} className="w-full py-3 bg-emerald-600 hover:bg-emerald-500 rounded-xl text-xs font-black flex items-center justify-center gap-2 shadow-lg disabled:opacity-50 transition-all">
                <RefreshCw size={14} className={isSyncing ? 'animate-spin' : ''} />
                {isSyncing ? '同步中' : '手動同步'}
              </button>
            )}
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-12 overflow-y-auto">
        <header className="mb-14 flex justify-between items-end border-b-2 border-slate-200 pb-12">
          <div>
            <h2 className="text-5xl font-black text-slate-900 tracking-tighter capitalize">
              {activeTab === 'dashboard' && '數據總覽'}
              {activeTab === 'inventory' && '耗材資料庫'}
              {activeTab === 'issuance' && '物料登記'}
              {activeTab === 'history' && '異動紀錄'}
            </h2>
            <p className="mt-3 text-slate-500 font-bold flex items-center gap-2">
              <span className={`w-3 h-3 rounded-full animate-pulse ${cloudUrl ? 'bg-emerald-500' : 'bg-amber-500'}`}></span>
              連線狀態：{cloudUrl ? '雲端同步已開啟' : '本地儲存模式'}
            </p>
          </div>
        </header>

        {activeTab === 'dashboard' && (
          <div className="space-y-10 animate-in fade-in duration-500">
            <div className="grid grid-cols-3 gap-10">
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100">
                <p className="text-slate-400 font-black text-xs uppercase tracking-widest mb-2">總資產項目</p>
                <p className="text-6xl font-black text-slate-900">{items.length}</p>
              </div>
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100">
                <p className="text-rose-500 font-black text-xs uppercase tracking-widest mb-2">庫存不足項目</p>
                <p className="text-6xl font-black text-rose-600">{items.filter(i => i.quantity <= i.minStock).length}</p>
              </div>
              <div className="bg-slate-900 p-10 rounded-[2.5rem] shadow-2xl text-white relative overflow-hidden">
                <div className="relative z-10">
