                  ))}
                  {items.length === 0 && (
                    <tr><td colSpan={4} className="py-20 text-center text-slate-400 font-black">目前無任何資料，請點擊上方按鈕新增。</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'issuance' && (
          <div className="max-w-4xl mx-auto animate-in fade-in">
             <div className="bg-white p-12 rounded-[3.5rem] shadow-2xl border border-slate-100">
                <div className="flex justify-center mb-10">
                  <div className="bg-slate-100 p-2 rounded-[2rem] flex gap-2 w-full max-w-md">
                    <button 
