        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden animate-in fade-in">
             <table className="w-full text-left">
               <thead className="bg-slate-50 text-slate-500 font-black text-xs border-b-2">
                 <tr>
                   <th className="px-8 py-6 uppercase tracking-widest">日期時間</th>
