                 </tr>
               </thead>
               <tbody className="divide-y divide-slate-100">
                 {logs.map(log => (
                   <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                     <td className="px-8 py-6 font-mono text-slate-400 font-bold">{new Date(log.timestamp).toLocaleString()}</td>
                     <td className="px-8 py-6 font-black text-slate-900">{log.itemName} <span className="text-slate-400 ml-2">x{log.quantity}</span></td>
                     <td className="px-8 py-6">
                       {log.type === 'OUT' ? <span className="text-rose-600 font-black">領用出庫</span> : <span className="text-emerald-600 font-black">補貨入庫</span>}
                     </td>
                     <td className="px-8 py-6 font-bold text-slate-700">{log.person}</td>
                     <td className="px-8 py-6 text-right">
                        {log.type === 'OUT' && (
                          <button onClick={() => {setLastTransaction(log); setShowPrintModal(true);}} className="p-2.5 bg-blue-50 text-blue-600 rounded-xl hover:bg-blue-600 hover:text-white transition-all">
                            <Printer size={18} />
