        )}
      </main>

      {/* 新增耗材 Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-xl shadow-2xl overflow-hidden">
            <div className="p-8 border-b-2 bg-slate-50 flex justify-between items-center">
              <h3 className="font-black text-2xl text-slate-900">新增耗材至資料庫</h3>
              <button onClick={() => setShowAddModal(false)} className="p-2 hover:bg-slate-200 rounded-full text-slate-400"><X size={24} /></button>
            </div>
            <div className="p-10 space-y-6">
              <div>
                <label className="block text-xs font-black text-slate-400 uppercase mb-2 ml-1">項目名稱</label>
                <input type="text" className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-200 rounded-2xl font-black text-xl text-slate-900 outline-none focus:border-blue-500" value={newForm.name} onChange={e => setNewForm({...newForm, name: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-black text-slate-400 uppercase mb-2 ml-1">單位 (個/卷/雙)</label>
                  <input type="text" className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-200 rounded-2xl font-black text-slate-900 outline-none focus:border-blue-500" value={newForm.unit} onChange={e => setNewForm({...newForm, unit: e.target.value})} />
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-400 uppercase mb-2 ml-1">安全庫存量</label>
                  <input type="number" className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-200 rounded-2xl font-black text-slate-900 outline-none focus:border-blue-500" value={newForm.minStock} onChange={e => setNewForm({...newForm, minStock: Number(e.target.value)})} />
                </div>
              </div>
              <div>
                <label className="block text-xs font-black text-slate-400 uppercase mb-2 ml-1">規格/備註</label>
                <textarea className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-200 rounded-2xl font-bold text-slate-900 outline-none focus:border-blue-500" value={newForm.description} onChange={e => setNewForm({...newForm, description: e.target.value})} />
              </div>
              <button onClick={handleAddItem} className="w-full py-5 bg-slate-900 text-white rounded-3xl font-black text-xl shadow-xl hover:bg-slate-800 transition-all">儲存至資料庫</button>
            </div>
          </div>
        </div>
      )}

      {/* 設定 Modal */}
      {showSettings && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-xl z-[120] flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden">
            <div className="p-8 border-b-2 bg-slate-50 flex justify-between items-center">
              <h3 className="font-black text-2xl flex items-center gap-3 text-slate-900"><Cloud className="text-blue-600" /> 雲端同步設定</h3>
              <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-slate-200 rounded-full text-slate-400"><X size={24} /></button>
            </div>
            <div className="p-10 space-y-6">
              <div>
                <label className="block text-xs font-black text-slate-400 uppercase mb-3">Google Apps Script URL</label>
                <div className="relative">
                  <Link2 className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                  <input 
                    type="text" 
                    className="w-full pl-14 pr-6 py-5 bg-slate-50 border-2 border-slate-200 rounded-3xl font-bold text-blue-600 focus:border-blue-500 outline-none"
                    placeholder="貼上您的執行 URL..."
                    value={cloudUrl}
                    onChange={(e) => setCloudUrl(e.target.value)}
                  />
                </div>
              </div>
              <div className="bg-blue-50 p-6 rounded-3xl border border-blue-100 text-sm font-bold text-blue-800 flex items-start gap-3">
                <Info size={20} className="shrink-0" />
                貼上 URL 後點擊儲存，系統將會與雲端試算表進行雙向同步。
              </div>
              <button 
                onClick={() => {
                  localStorage.setItem(STORAGE_KEY_CLOUD_URL, cloudUrl);
                  setShowSettings(false);
                  if (cloudUrl) fetchFromCloud();
                }}
                className="w-full py-5 bg-slate-900 text-white rounded-3xl font-black text-xl shadow-xl hover:bg-slate-800 transition-all"
              >儲存設定並同步</button>
