        </div>
      )}

      {/* 單據預覽 Modal */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-black/95 z-[150] flex flex-col items-center justify-start p-4 overflow-y-auto">
          <div className="w-full max-w-5xl bg-white rounded-[4rem] my-10 relative shadow-2xl overflow-hidden animate-in slide-in-from-bottom-10">
            <div className="p-10 border-b-2 flex justify-between items-center sticky top-0 bg-white z-10">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-indigo-600 text-white rounded-2xl"><Printer size={28} /></div>
                <h3 className="font-black text-3xl text-slate-900">單據預覽</h3>
              </div>
              <div className="flex gap-4">
                <button onClick={() => window.print()} className="px-14 py-4 bg-indigo-600 text-white rounded-2xl font-black text-xl shadow-xl hover:bg-indigo-700 transition-all">立即列印</button>
                <button onClick={() => setShowPrintModal(false)} className="p-4 text-slate-300 hover:text-black hover:bg-slate-100 rounded-full transition-all"><X size={32} /></button>
              </div>
            </div>
            <div className="p-16 bg-slate-50 flex justify-center">
              <div className="shadow-2xl bg-white border border-slate-200">
                <PrintableForm transaction={lastTransaction} />
              </div>
