  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // 登記表單狀態
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState(1);
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputDate, setInputDate] = useState(new Date().toISOString().split('T')[0]); 
  const [inputReason, setInputReason] = useState('');

  // 初始化
  useEffect(() => {
    const initLoad = async () => {
      const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
      const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
      if (savedItems) setItems(JSON.parse(savedItems));
      if (savedLogs) setLogs(JSON.parse(savedLogs));

      if (cloudUrl) {
        await fetchFromCloud();
      }
    };
    initLoad();
  }, []);

  const fetchFromCloud = async () => {
    if (!cloudUrl) return;
    setIsSyncing(true);
    try {
      const response = await fetch(cloudUrl);
      const text = await response.text();
      if (!text || text.trim() === "") return;
      const data = JSON.parse(text);
      if (data.items) setItems(data.items);
      if (data.logs) setLogs(data.logs);
    } catch (err) {
      console.error('雲端抓取失敗', err);
    } finally {
      setIsSyncing(false);
    }
  };

  const saveToCloud = async (newItems: InventoryItem[], newLogs: Transaction[]) => {
    // 優先更新本地儲存，確保操作不延遲
    localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(newItems));
    localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(newLogs));

    if (!cloudUrl) return;
    setIsSyncing(true);
    try {
      await fetch(cloudUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items: newItems, logs: newLogs, lastUpdate: Date.now() })
      });
    } catch (err) {
      console.error('雲端儲存同步失敗', err);
    } finally {
      setIsSyncing(false);
    }
  };

  const deleteItem = async (id: string) => {
    if (window.confirm('確定要永久刪除此耗材項目？刪除後將同步更新雲端資料庫。')) {
      const updated = items.filter(item => item.id !== id);
      setItems(updated); // 立即更新介面
      await saveToCloud(updated, logs); // 同步到雲端
    }
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    unit: '個',
    minStock: 5,
    quantity: 0,
    description: ''
  });

  const handleAddItem = async () => {
    if (!newForm.name) return alert('請輸入項目名稱');
    const newItem: InventoryItem = {
      ...newForm,
      id: crypto.randomUUID(),
      lastUpdated: Date.now()
    };
    const updated = [...items, newItem];
    setItems(updated);
    await saveToCloud(updated, logs);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, unit: '個', minStock: 5, quantity: 0, description: '' });
  };

  const handleTransaction = async () => {
    if (!selectedItemId || inputQty <= 0) return alert('請完整填寫項目與數量');
    if (issuanceMode === 'OUT' && !inputPerson) return alert('請輸入領用部門或人員');

    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    if (issuanceMode === 'OUT' && targetItem.quantity < inputQty) return alert('當前庫存不足以領用！');

    const updatedItems = items.map(i => {
      if (i.id === selectedItemId) {
        return { 
          ...i, 
          quantity: issuanceMode === 'IN' ? i.quantity + inputQty : i.quantity - inputQty, 
          lastUpdated: Date.now() 
        };
      }
      return i;
    });

    const newLog: Transaction = {
      id: crypto.randomUUID(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: inputQty,
      person: issuanceMode === 'OUT' ? inputPerson : inputDate,
      reason: inputReason,
      timestamp: Date.now()
    };

    const updatedLogs = [newLog, ...logs];
    setItems(updatedItems);
    setLogs(updatedLogs);
    setLastTransaction(newLog);
    await saveToCloud(updatedItems, updatedLogs);

    // 重置欄位
    setSelectedItemId(''); setInputQty(1); setInputPerson(''); setInputReason('');

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      alert('補貨資料已更新並同步雲端。');
    }
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    const advice = await getInventoryInsights(items);
    setAiAdvice(advice);
    setIsAiLoading(false);
  };

  // 單據組件
  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const now = new Date(transaction.timestamp);
    const year = now.getFullYear() - 1911;
    return (
      <div className="bg-white p-12 w-[210mm] mx-auto text-black border-[4px] border-black" id="print-area">
        <style>{`
          @media print { 
            body * { visibility: hidden; } 
            #print-area, #print-area * { visibility: visible; } 
            #print-area { position: absolute; left: 0; top: 0; width: 100%; border: none; } 
          }
          #print-area h1, #print-area p, #print-area td, #print-area th { color: black !important; font-weight: 900 !important; }
        `}</style>
        <h1 className="text-4xl font-black text-center mb-12 border-b-[6px] border-black pb-6">台灣電力公司電力修護處南部分處領用單</h1>
        <div className="flex justify-between mb-8 text-2xl font-black px-2">
          <p>部門：<span className="underline underline-offset-8 px-6">{transaction.person}</span></p>
          <p>中華民國 {year} 年 {now.getMonth()+1} 月 {now.getDate()} 日</p>
        </div>
        <table className="w-full border-collapse border-[4px] border-black text-center text-black">
          <thead>
            <tr className="bg-gray-100 border-b-[4px] border-black">
              <th className="border-r-[4px] border-black p-4 text-2xl font-black">耗材項目 / 規格描述</th>
              <th className="border-r-[4px] border-black p-4 text-2xl font-black">單位</th>
              <th className="border-r-[4px] border-black p-4 text-2xl font-black">數量</th>
              <th className="p-4 text-2xl font-black">備註</th>
            </tr>
          </thead>
          <tbody>
            <tr className="border-b-[4px] border-black h-32">
              <td className="border-r-[4px] border-black p-6 text-3xl font-black">{transaction.itemName}</td>
              <td className="border-r-[4px] border-black p-6 text-2xl font-black">{targetItem?.unit}</td>
              <td className="border-r-[4px] border-black p-6 text-5xl font-black">{transaction.quantity}</td>
              <td className="p-6 text-xl font-bold">{transaction.reason}</td>
            </tr>
            {[...Array(6)].map((_, i) => (
              <tr key={i} className="border-b-[4px] border-black h-16">
                <td className="border-r-[4px] border-black"></td><td className="border-r-[4px] border-black"></td><td className="border-r-[4px] border-black"></td><td></td>
              </tr>
            ))}
          </tbody>
        </table>
        <div className="mt-20 grid grid-cols-3 gap-12 text-2xl font-black text-center">
          <p>經辦：__________</p><p>課長：__________</p><p>經理：__________</p>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-slate-100 text-slate-900">
      {/* Sidebar */}
      <aside className="w-80 bg-[#0F172A] text-white p-8 sticky top-0 h-screen flex flex-col shadow-2xl z-20">
        <div className="flex items-center gap-4 mb-14">
          <div className="p-3 bg-blue-600 rounded-2xl shadow-lg shadow-blue-500/30"><Package size={30} /></div>
          <div>
            <h1 className="font-black text-2xl tracking-tighter">工安管理系統</h1>
            <p className="text-[10px] text-blue-400 font-black tracking-widest uppercase">Cloud Sync Pro</p>
          </div>
        </div>

        <nav className="flex-1 space-y-4">
          {[
            { id: 'dashboard', icon: LayoutDashboard, label: '儀表板分析' },
            { id: 'inventory', icon: Package, label: '耗材資料庫' },
            { id: 'issuance', icon: FileText, label: '登記作業' },
            { id: 'history', icon: History, label: '異動日誌' },
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl font-black transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-xl' : 'text-slate-400 hover:bg-slate-800'}`}>
              <tab.icon size={22} /> {tab.label}
            </button>
          ))}
        </nav>

        <div className="mt-auto pt-6 border-t border-slate-800 space-y-4">
          <div className={`p-5 rounded-3xl border transition-all ${cloudUrl ? 'bg-emerald-500/10 border-emerald-500/30' : 'bg-slate-800 border-slate-700'}`}>
            <div className="flex items-center justify-between mb-3">
              <span className={`text-[10px] font-black uppercase tracking-widest flex items-center gap-1.5 ${cloudUrl ? 'text-emerald-400' : 'text-slate-500'}`}>
                <Cloud size={14} /> {cloudUrl ? '雲端連線' : '本地儲存'}
              </span>
              <button onClick={() => setShowSettings(true)} className="p-1 hover:bg-white/10 rounded-lg text-slate-400 hover:text-white transition-colors"><Settings size={18} /></button>
            </div>
            {cloudUrl && (
              <button onClick={fetchFromCloud} disabled={isSyncing} className="w-full py-3 bg-emerald-600 hover:bg-emerald-500 rounded-xl text-xs font-black flex items-center justify-center gap-2 shadow-lg disabled:opacity-50 transition-all text-white">
                <RefreshCw size={14} className={isSyncing ? 'animate-spin' : ''} />
                {isSyncing ? '同步中' : '刷新數據'}
              </button>
            )}
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-12 overflow-y-auto">
        <header className="mb-14 flex justify-between items-end border-b-2 border-slate-300 pb-12">
          <div>
            <h2 className="text-5xl font-black text-slate-900 tracking-tighter">
              {activeTab === 'dashboard' && '數據決策中心'}
              {activeTab === 'inventory' && '設備資產清冊'}
              {activeTab === 'issuance' && '自動化登記作業'}
              {activeTab === 'history' && '全紀錄日誌'}
            </h2>
            <p className="mt-3 text-slate-600 font-bold flex items-center gap-2">
              <span className={`w-3 h-3 rounded-full ${cloudUrl ? 'bg-emerald-500' : 'bg-amber-500'}`}></span>
              系統狀態：{cloudUrl ? '雲端同步啟動' : '離線暫存模式'}
            </p>
          </div>
        </header>

        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-3 gap-10 animate-in fade-in duration-500">
            <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-200">
              <p className="text-slate-400 font-black text-xs uppercase tracking-widest mb-2">總資產項目</p>
              <p className="text-6xl font-black text-slate-900">{items.length}</p>
            </div>
            <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-200">
              <p className="text-rose-500 font-black text-xs uppercase tracking-widest mb-2">庫存不足項目</p>
              <p className="text-6xl font-black text-rose-600">{items.filter(i => i.quantity <= i.minStock).length}</p>
            </div>
            <div className="bg-slate-900 p-10 rounded-[2.5rem] shadow-2xl text-white">
               <h3 className="text-xl font-black mb-4 flex items-center gap-3"><Sparkles className="text-blue-400" /> AI 管理助理</h3>
               <div className="bg-white/10 backdrop-blur-md p-5 rounded-2xl border border-white/10 text-sm italic text-slate-200 mb-6">
                 {aiAdvice || "讓 AI 分析您的數據趨勢。"}
               </div>
               <button onClick={fetchAiInsights} disabled={isAiLoading} className="px-8 py-3 bg-blue-600 rounded-xl font-black text-xs hover:bg-blue-500 transition-all text-white flex items-center gap-2">
                 {isAiLoading && <RefreshCw size={14} className="animate-spin" />} 分析庫存
               </button>
            </div>
          </div>
        )}

        {activeTab === 'inventory' && (
          <div className="space-y-6 animate-in fade-in">
            <div className="flex justify-between items-center bg-white p-6 rounded-3xl shadow-sm border border-slate-200">
              <div className="relative w-96">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input type="text" placeholder="搜尋項目..." className="w-full pl-12 pr-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-2xl font-black text-slate-900 focus:border-blue-500 outline-none" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
              </div>
              <button onClick={() => setShowAddModal(true)} className="px-8 py-4 bg-blue-600 text-white rounded-2xl font-black flex items-center gap-3 shadow-lg hover:scale-[1.02] transition-all">
                <Plus size={20} /> 新增耗材項目
              </button>
            </div>
            <div className="bg-white rounded-[2rem] shadow-sm border border-slate-200 overflow-hidden">
              <table className="w-full text-left">
                <thead className="bg-slate-50 border-b-2 border-slate-200 text-slate-500 text-xs font-black uppercase">
                  <tr>
                    <th className="px-10 py-6 tracking-widest">耗材名稱 / 類別</th>
                    <th className="px-10 py-6 tracking-widest">現有數量</th>
                    <th className="px-10 py-6 tracking-widest">警戒線</th>
                    <th className="px-10 py-6 tracking-widest text-right">管理</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-slate-900">
                  {items.filter(i => i.name.includes(searchTerm)).map(item => (
                    <tr key={item.id} className="hover:bg-slate-50 transition-colors group">
                      <td className="px-10 py-8">
                        <div className="font-black text-2xl text-slate-900">{item.name}</div>
                        <div className="text-[10px] text-blue-600 font-black mt-1 uppercase">{item.category}</div>
                      </td>
                      <td className="px-10 py-8">
                        <span className={`px-6 py-3 rounded-xl font-black text-xl ${item.quantity <= item.minStock ? 'bg-rose-50 text-rose-600 border border-rose-100' : 'bg-emerald-50 text-emerald-600 border border-emerald-100'}`}>
                          {item.quantity} {item.unit}
                        </span>
                      </td>
                      <td className="px-10 py-8 font-black text-slate-400 text-lg">{item.minStock} {item.unit}</td>
                      <td className="px-10 py-8 text-right">
                        <button onClick={() => deleteItem(item.id)} className="p-4 text-rose-500 hover:text-white hover:bg-rose-600 rounded-2xl transition-all shadow-sm">
                          <Trash2 size={24} />
                        </button>
                      </td>
                    </tr>
                  ))}
                  {items.length === 0 && (<tr><td colSpan={4} className="py-24 text-center text-slate-400 font-black">清冊目前為空。</td></tr>)}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'issuance' && (
          <div className="max-w-4xl mx-auto animate-in fade-in">
             <div className="bg-white p-12 rounded-[3.5rem] shadow-2xl border border-slate-200">
                <div className="flex justify-center mb-12">
                  <div className="bg-slate-100 p-2 rounded-[2rem] flex gap-2 w-full max-w-md">
                    <button onClick={() => setIssuanceMode('OUT')} className={`flex-1 py-4 rounded-[1.5rem] font-black text-lg transition-all ${issuanceMode === 'OUT' ? 'bg-white shadow-lg text-rose-600' : 'text-slate-400'}`}>領用出庫</button>
                    <button onClick={() => setIssuanceMode('IN')} className={`flex-1 py-4 rounded-[1.5rem] font-black text-lg transition-all ${issuanceMode === 'IN' ? 'bg-white shadow-lg text-emerald-600' : 'text-slate-400'}`}>補貨入庫</button>
                  </div>
                </div>
                <div className="space-y-10">
                  <div>
                    <label className="block text-sm font-black text-slate-400 uppercase tracking-widest mb-4 ml-1">1. 選擇資產項目</label>
                    <select className="w-full px-6 py-5 bg-slate-50 border-4 border-slate-200 rounded-3xl font-black text-2xl text-slate-900 outline-none focus:border-blue-500" value={selectedItemId} onChange={e => setSelectedItemId(e.target.value)}>
                      <option value="">-- 請點擊選擇 --</option>
                      {items.map(i => <option key={i.id} value={i.id}>{i.name} (剩餘 {i.quantity} {i.unit})</option>)}
                    </select>
                  </div>
                  <div className="grid grid-cols-2 gap-8">
                    <div>
                      <label className="block text-sm font-black text-slate-400 uppercase tracking-widest mb-4 ml-1">2. 數量</label>
                      <input type="number" className="w-full px-6 py-5 bg-slate-50 border-4 border-slate-200 rounded-3xl font-black text-2xl text-slate-900 outline-none focus:border-blue-500" value={inputQty} onChange={e => setInputQty(Number(e.target.value))} />
                    </div>
                    <div>
                      <label className="block text-sm font-black text-slate-400 uppercase tracking-widest mb-4 ml-1">
                        3. {issuanceMode === 'OUT' ? '領用部門 / 人員' : '入庫日期'}
                      </label>
                      {issuanceMode === 'OUT' ? (
                        <input type="text" placeholder="例：變電組 蔡先生" className="w-full px-6 py-5 bg-slate-50 border-4 border-slate-200 rounded-3xl font-black text-2xl text-slate-900 outline-none focus:border-blue-500" value={inputPerson} onChange={e => setInputPerson(e.target.value)} />
                      ) : (
                        <input type="date" className="w-full px-6 py-5 bg-slate-50 border-4 border-slate-200 rounded-3xl font-black text-2xl text-slate-900 outline-none focus:border-blue-500" value={inputDate} onChange={e => setInputDate(e.target.value)} />
                      )}
                    </div>
                  </div>
                  <button onClick={handleTransaction} className={`w-full py-8 rounded-[2.5rem] font-black text-3xl shadow-2xl transform active:scale-95 transition-all flex items-center justify-center gap-4 text-white ${issuanceMode === 'OUT' ? 'bg-rose-600 hover:bg-rose-700 shadow-rose-200' : 'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-200'}`}>
                    {issuanceMode === 'OUT' ? <Printer size={32} /> : <CheckCircle2 size={32} />}
                    {issuanceMode === 'OUT' ? '確認領用並開單' : '確認入庫更新'}
                  </button>
                </div>
             </div>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-[2rem] shadow-sm border border-slate-200 overflow-hidden animate-in fade-in">
             <table className="w-full text-left">
               <thead className="bg-slate-50 text-slate-500 font-black text-xs border-b-2 border-slate-200">
                 <tr>
                   <th className="px-8 py-6 uppercase tracking-widest">異動時間</th>
                   <th className="px-8 py-6 uppercase tracking-widest">項目名稱</th>
                   <th className="px-8 py-6 uppercase tracking-widest">動作類型</th>
                   <th className="px-8 py-6 uppercase tracking-widest">對象/日期</th>
                   <th className="px-8 py-6 uppercase tracking-widest text-right">補印</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-slate-100 text-slate-900">
                 {logs.map(log => (
                   <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                     <td className="px-8 py-6 font-mono text-slate-400 font-bold">{new Date(log.timestamp).toLocaleString()}</td>
                     <td className="px-8 py-6 font-black text-slate-900 text-xl">{log.itemName} <span className="text-slate-400 text-sm ml-2">x{log.quantity}</span></td>
                     <td className="px-8 py-6">
                       {log.type === 'OUT' ? <span className="text-rose-600 font-black">領用出庫</span> : <span className="text-emerald-600 font-black">補貨入庫</span>}
                     </td>
                     <td className="px-8 py-6 font-bold text-slate-700">{log.person}</td>
                     <td className="px-8 py-6 text-right">
                        {log.type === 'OUT' && (
                          <button onClick={() => {setLastTransaction(log); setShowPrintModal(true);}} className="p-3 bg-blue-50 text-blue-600 rounded-xl hover:bg-blue-600 hover:text-white transition-all"><Printer size={20} /></button>
                        )}
                     </td>
                   </tr>
                 ))}
               </tbody>
             </table>
          </div>
        )}
      </main>

      {/* 新增耗材 Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-2xl shadow-2xl overflow-hidden border border-white/20">
            <div className="p-8 border-b-2 bg-slate-50 flex justify-between items-center">
              <h3 className="font-black text-3xl text-black">新增耗材至清冊</h3>
              <button onClick={() => setShowAddModal(false)} className="p-3 hover:bg-slate-200 rounded-full text-slate-500"><X size={28} /></button>
            </div>
            <div className="p-10 space-y-8 text-black">
              <div className="grid grid-cols-2 gap-8">
                <div className="col-span-2">
                  <label className="block text-xs font-black text-slate-500 uppercase mb-2">耗材名稱</label>
                  <input type="text" className="w-full px-6 py-5 bg-slate-50 border-4 border-slate-200 rounded-2xl font-black text-2xl text-black focus:border-blue-500 outline-none" value={newForm.name} onChange={e => setNewForm({...newForm, name: e.target.value})} />
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-500 uppercase mb-2">類別</label>
                  <select className="w-full px-6 py-5 bg-slate-50 border-4 border-slate-200 rounded-2xl font-black text-black outline-none focus:border-blue-500" value={newForm.category} onChange={e => setNewForm({...newForm, category: e.target.value as Category})}>
                    {Object.values(Category).map(cat => <option key={cat} value={cat}>{cat}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-500 uppercase mb-2">單位 (如：個)</label>
                  <input type="text" className="w-full px-6 py-5 bg-slate-50 border-4 border-slate-200 rounded-2xl font-black text-black outline-none focus:border-blue-500" value={newForm.unit} onChange={e => setNewForm({...newForm, unit: e.target.value})} />
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-500 uppercase mb-2">初始現有數量</label>
                  <input type="number" className="w-full px-6 py-5 bg-slate-50 border-4 border-slate-200 rounded-2xl font-black text-black outline-none focus:border-blue-500" value={newForm.quantity} onChange={e => setNewForm({...newForm, quantity: Number(e.target.value)})} />
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-500 uppercase mb-2">安全警戒線</label>
                  <input type="number" className="w-full px-6 py-5 bg-slate-50 border-4 border-slate-200 rounded-2xl font-black text-black outline-none focus:border-blue-500" value={newForm.minStock} onChange={e => setNewForm({...newForm, minStock: Number(e.target.value)})} />
                </div>
              </div>
              <button onClick={handleAddItem} className="w-full py-6 bg-slate-900 text-white rounded-3xl font-black text-2xl shadow-xl hover:bg-black transition-all">確認儲存並更新</button>
            </div>
          </div>
        </div>
      )}

      {/* 單據預覽 Modal */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-black/90 z-[150] flex flex-col items-center justify-start p-4 overflow-y-auto">
          <div className="w-full max-w-5xl bg-white rounded-[3rem] my-8 relative shadow-2xl flex flex-col min-h-[90vh]">
            <div className="p-10 border-b-4 border-slate-100 flex justify-between items-center sticky top-0 bg-white z-20">
              <div className="flex items-center gap-5">
                <div className="p-4 bg-indigo-600 text-white rounded-3xl"><Printer size={36} /></div>
                <h3 className="font-black text-4xl text-black tracking-tighter">領用單預覽</h3>
              </div>
              <div className="flex gap-6">
                <button onClick={() => window.print()} className="px-16 py-5 bg-indigo-600 text-white rounded-3xl font-black text-2xl shadow-xl hover:bg-indigo-700 transition-all">立即列印</button>
                <button onClick={() => setShowPrintModal(false)} className="p-5 text-slate-400 hover:text-black hover:bg-slate-100 rounded-full transition-all"><X size={48} /></button>
              </div>
            </div>
            <div className="flex-1 p-16 bg-slate-100 flex justify-center overflow-auto">
              <div className="shadow-2xl bg-white p-4">
                <PrintableForm transaction={lastTransaction} />
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 設定 Modal */}
      {showSettings && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-xl z-[120] flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden text-black">
            <div className="p-8 border-b-2 bg-slate-50 flex justify-between items-center">
              <h3 className="font-black text-2xl flex items-center gap-3"><Cloud className="text-blue-600" /> 雲端同步連結</h3>
              <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-slate-200 rounded-full text-slate-400"><X size={24} /></button>
            </div>
            <div className="p-10 space-y-6">
              <label className="block text-xs font-black text-slate-400 uppercase mb-2 tracking-widest">Google Apps Script URL</label>
              <input type="text" className="w-full px-6 py-5 bg-slate-50 border-4 border-slate-100 rounded-3xl font-bold text-blue-600 outline-none" placeholder="貼上您的 Apps Script 執行 URL..." value={cloudUrl} onChange={(e) => setCloudUrl(e.target.value)} />
              <button onClick={() => { localStorage.setItem(STORAGE_KEY_CLOUD_URL, cloudUrl); setShowSettings(false); if(cloudUrl) fetchFromCloud(); }} className="w-full py-6 bg-slate-900 text-white rounded-3xl font-black text-xl shadow-xl hover:bg-black transition-all">儲存並立即連線</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  RefreshCw,
  Sparkles,
  Search,
  CheckCircle2,
  X,
  Printer,
  Cloud,
  Settings,
  Link2,
  Info
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_items';
const STORAGE_KEY_LOGS = 'safeman_logs';
const STORAGE_KEY_CLOUD_URL = 'safeman_cloud_url';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'issuance' | 'history'>('dashboard');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [cloudUrl, setCloudUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_CLOUD_URL) || '');
  const [isSyncing, setIsSyncing] = useState(false);
  const [aiAdvice, setAiAdvice] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // 登記表單狀態
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState(1);
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputDate, setInputDate] = useState(new Date().toISOString().split('T')[0]); 
  const [inputReason, setInputReason] = useState('');

  // 初始化載入
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedLogs) setLogs(JSON.parse(savedLogs));

    if (cloudUrl) {
      fetchFromCloud();
    }
  }, []);

  const fetchFromCloud = async () => {
    if (!cloudUrl) return;
    setIsSyncing(true);
    try {
      const response = await fetch(cloudUrl);
      const text = await response.text();
      if (!text || text.trim() === "") return;
      const data = JSON.parse(text);
      if (data.items) {
        setItems(data.items);
        localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(data.items));
      }
      if (data.logs) {
        setLogs(data.logs);
        localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(data.logs));
      }
    } catch (err) {
      console.error('雲端同步抓取失敗', err);
    } finally {
      setIsSyncing(false);
    }
  };

  const syncData = async (newItems: InventoryItem[], newLogs: Transaction[]) => {
    // 1. 先存本地，確保 UI 絕對會變動
    localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(newItems));
    localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(newLogs));

    // 2. 如果有設定 URL 則同步雲端
    if (!cloudUrl) return;
    setIsSyncing(true);
    try {
      await fetch(cloudUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items: newItems, logs: newLogs, lastUpdate: Date.now() })
      });
    } catch (err) {
      console.error('雲端寫入失敗', err);
    } finally {
      setIsSyncing(false);
    }
  };

  const deleteItem = (id: string) => {
    if (window.confirm('警告：確定要刪除此耗材項目嗎？刪除後無法復原。')) {
      const updatedItems = items.filter(item => item.id !== id);
      setItems(updatedItems);
      syncData(updatedItems, logs);
    }
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    unit: '個',
    minStock: 5,
    quantity: 0,
    description: ''
  });

  const handleAddItem = () => {
    if (!newForm.name) return alert('請輸入耗材名稱');
    const newItem: InventoryItem = {
      ...newForm,
      id: crypto.randomUUID(),
      lastUpdated: Date.now()
    };
    const updatedItems = [...items, newItem];
    setItems(updatedItems);
    syncData(updatedItems, logs);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, unit: '個', minStock: 5, quantity: 0, description: '' });
  };

  const handleTransaction = () => {
    if (!selectedItemId || inputQty <= 0) return alert('請選擇項目並輸入數量');
    if (issuanceMode === 'OUT' && !inputPerson) return alert('請輸入領用部門或領用人');

    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    if (issuanceMode === 'OUT' && targetItem.quantity < inputQty) return alert('錯誤：庫存量不足！');

    const updatedItems = items.map(i => {
      if (i.id === selectedItemId) {
        return { 
          ...i, 
          quantity: issuanceMode === 'IN' ? i.quantity + inputQty : i.quantity - inputQty, 
          lastUpdated: Date.now() 
        };
      }
      return i;
    });

    const newLog: Transaction = {
      id: crypto.randomUUID(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: inputQty,
      person: issuanceMode === 'OUT' ? inputPerson : `入庫日期: ${inputDate}`,
      reason: inputReason,
      timestamp: Date.now()
    };

    const updatedLogs = [newLog, ...logs];
    setItems(updatedItems);
    setLogs(updatedLogs);
    setLastTransaction(newLog);
    syncData(updatedItems, updatedLogs);

    // 重置
    setSelectedItemId(''); setInputQty(1); setInputPerson(''); setInputReason('');

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      alert('入庫登記已完成');
    }
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    const advice = await getInventoryInsights(items);
    setAiAdvice(advice);
    setIsAiLoading(false);
  };

  // 標準台電格式領用單
  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const now = new Date(transaction.timestamp);
    const minguoYear = now.getFullYear() - 1911;

    return (
      <div className="bg-white p-12 w-[210mm] mx-auto text-black border-[3px] border-black" id="print-area">
        <style>{`
          @media print { 
            body * { visibility: hidden; } 
            #print-area, #print-area * { visibility: visible; } 
            #print-area { position: absolute; left: 0; top: 0; width: 100%; border: none; } 
          }
          #print-area h1 { color: black !important; font-size: 32px !important; font-weight: 900 !important; }
          #print-area p, #print-area td, #print-area th { color: black !important; font-weight: 800 !important; }
        `}</style>

        <h1 className="text-center mb-10 border-b-[4px] border-black pb-6 tracking-widest">台灣電力公司電力修護處南部分處領用單</h1>

        <div className="flex justify-between mb-6 px-2 text-xl font-black">
          <p>部門：<span className="underline underline-offset-8 px-6 decoration-2">{transaction.person}</span></p>
          <p>中華民國 {minguoYear} 年 {now.getMonth() + 1} 月 {now.getDate()} 日</p>
        </div>

        <table className="w-full border-collapse border-[3px] border-black text-center mb-8">
          <thead>
            <tr className="bg-gray-100 border-b-[3px] border-black">
              <th className="border-r-[3px] border-black p-4 text-xl">耗材名稱 / 規格</th>
              <th className="border-r-[3px] border-black p-4 text-xl">單位</th>
              <th className="border-r-[3px] border-black p-4 text-xl">數量</th>
              <th className="p-4 text-xl">備註 (工程代號)</th>
            </tr>
          </thead>
          <tbody>
            <tr className="border-b-[3px] border-black h-32">
              <td className="border-r-[3px] border-black p-4 text-2xl font-black">{transaction.itemName}</td>
              <td className="border-r-[3px] border-black p-4 text-xl">{targetItem?.unit || '個'}</td>
              <td className="border-r-[3px] border-black p-4 text-4xl font-black">{transaction.quantity}</td>
              <td className="p-4 text-lg">{transaction.reason}</td>
            </tr>
            {/* 空白欄位供填寫 */}
            {[...Array(5)].map((_, i) => (
              <tr key={i} className="border-b-[3px] border-black h-14">
                <td className="border-r-[3px] border-black"></td><td className="border-r-[3px] border-black"></td><td className="border-r-[3px] border-black"></td><td></td>
              </tr>
            ))}
          </tbody>
        </table>

        <div className="mt-16 grid grid-cols-3 gap-8 text-xl font-black text-center pt-8">
          <p>經辦：__________</p>
          <p>課長：__________</p>
          <p>經理：__________</p>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900 font-sans">
      {/* 側邊欄 */}
      <aside className="w-72 bg-[#1E293B] text-white p-6 sticky top-0 h-screen flex flex-col shadow-2xl z-30">
        <div className="flex items-center gap-4 mb-10">
          <div className="p-3 bg-blue-500 rounded-xl shadow-lg"><Package size={26} /></div>
          <div>
            <h1 className="font-black text-xl tracking-tight">工安管理系統</h1>
            <p className="text-[10px] text-blue-300 font-bold tracking-widest uppercase">Southern Division</p>
          </div>
        </div>

        <nav className="flex-1 space-y-2">
          {[
            { id: 'dashboard', icon: LayoutDashboard, label: '儀表板總覽' },
            { id: 'inventory', icon: Package, label: '耗材資料庫' },
            { id: 'issuance', icon: FileText, label: '物料登記' },
            { id: 'history', icon: History, label: '異動紀錄' },
          ].map((tab) => (
            <button 
              key={tab.id} 
              onClick={() => setActiveTab(tab.id as any)} 
              className={`w-full flex items-center gap-4 px-5 py-3.5 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 shadow-lg text-white' : 'text-slate-400 hover:bg-slate-800'}`}
            >
              <tab.icon size={20} /> {tab.label}
            </button>
          ))}
        </nav>

        <div className="mt-auto pt-6 border-t border-slate-700 space-y-4">
          <div className={`p-4 rounded-2xl border transition-all ${cloudUrl ? 'bg-emerald-500/10 border-emerald-500/30' : 'bg-slate-800 border-slate-700'}`}>
            <div className="flex items-center justify-between mb-2">
              <span className={`text-[10px] font-black uppercase tracking-widest flex items-center gap-1.5 ${cloudUrl ? 'text-emerald-400' : 'text-slate-500'}`}>
                <Cloud size={14} /> {cloudUrl ? '雲端連線中' : '離線模式'}
              </span>
              <button onClick={() => setShowSettings(true)} className="p-1 hover:bg-white/10 rounded-lg text-slate-400 hover:text-white transition-colors"><Settings size={16} /></button>
            </div>
            {cloudUrl && (
              <button onClick={fetchFromCloud} disabled={isSyncing} className="w-full py-2 bg-emerald-600 hover:bg-emerald-500 rounded-xl text-[10px] font-black flex items-center justify-center gap-2 shadow-lg disabled:opacity-50 text-white">
                <RefreshCw size={12} className={isSyncing ? 'animate-spin' : ''} />
                {isSyncing ? '正在同步' : '更新數據'}
              </button>
            )}
          </div>
        </div>
      </aside>

      {/* 主內容區 */}
      <main className="flex-1 p-10 overflow-y-auto">
        <header className="mb-10 flex justify-between items-end border-b-2 border-slate-200 pb-8">
          <div>
            <h2 className="text-4xl font-black text-slate-800">
              {activeTab === 'dashboard' && '數據決策儀表板'}
              {activeTab === 'inventory' && '耗材設備清冊'}
              {activeTab === 'issuance' && '物料登記作業'}
              {activeTab === 'history' && '全異動日誌'}
            </h2>
            <p className="mt-2 text-slate-500 font-semibold flex items-center gap-2">
              <span className={`w-2.5 h-2.5 rounded-full ${cloudUrl ? 'bg-emerald-500' : 'bg-amber-500'}`}></span>
              系統環境：{cloudUrl ? '雲端同步模式' : '本地緩存模式'}
            </p>
          </div>
        </header>

        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-3 gap-8">
            <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
              <p className="text-slate-400 font-black text-[10px] uppercase tracking-widest mb-1">資產總項</p>
              <p className="text-5xl font-black text-slate-900">{items.length}</p>
            </div>
            <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
              <p className="text-rose-500 font-black text-[10px] uppercase tracking-widest mb-1">庫存警示</p>
              <p className="text-5xl font-black text-rose-600">{items.filter(i => i.quantity <= i.minStock).length}</p>
            </div>
            <div className="bg-slate-900 p-8 rounded-3xl shadow-xl text-white">
              <h3 className="text-lg font-black mb-3 flex items-center gap-2 text-blue-400"><Sparkles size={18} /> AI 庫存分析</h3>
              <div className="bg-white/5 p-4 rounded-xl border border-white/10 text-sm italic text-slate-300 min-h-[60px] mb-4">
                {aiAdvice || "點擊按鈕獲取專業管理建議。"}
              </div>
              <button onClick={fetchAiInsights} disabled={isAiLoading} className="px-6 py-2 bg-blue-600 rounded-xl font-black text-[10px] hover:bg-blue-500 transition-all flex items-center gap-2">
                {isAiLoading && <RefreshCw size={12} className="animate-spin" />} 開始分析
              </button>
            </div>
          </div>
        )}

        {activeTab === 'inventory' && (
          <div className="space-y-6">
            <div className="flex justify-between items-center bg-white p-5 rounded-2xl shadow-sm border border-slate-200">
              <div className="relative w-80">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                <input type="text" placeholder="搜尋關鍵字..." className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border-2 border-slate-200 rounded-xl font-bold text-slate-900 focus:border-blue-500 outline-none" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
              </div>
              <button onClick={() => setShowAddModal(true)} className="px-6 py-3 bg-blue-600 text-white rounded-xl font-black flex items-center gap-2 shadow-lg hover:bg-blue-700 transition-all">
                <Plus size={18} /> 新增資產項目
              </button>
            </div>
            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
              <table className="w-full text-left">
                <thead className="bg-slate-100 border-b border-slate-200 text-slate-500 text-[10px] font-black uppercase tracking-wider">
                  <tr>
                    <th className="px-8 py-4">耗材名稱 / 分類</th>
                    <th className="px-8 py-4">現有數量</th>
                    <th className="px-8 py-4">安全庫存</th>
                    <th className="px-8 py-4 text-right">操作管理</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {items.filter(i => i.name.includes(searchTerm)).map(item => (
                    <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                      <td className="px-8 py-6">
                        <div className="font-black text-lg text-slate-900">{item.name}</div>
                        <div className="text-[10px] text-blue-500 font-black mt-0.5">{item.category}</div>
                      </td>
                      <td className="px-8 py-6">
                        <span className={`px-4 py-1.5 rounded-lg font-black text-base ${item.quantity <= item.minStock ? 'bg-rose-100 text-rose-700' : 'bg-emerald-100 text-emerald-700'}`}>
                          {item.quantity} {item.unit}
                        </span>
                      </td>
                      <td className="px-8 py-6 font-bold text-slate-400">{item.minStock} {item.unit}</td>
                      <td className="px-8 py-6 text-right">
                        <button 
                          onClick={() => deleteItem(item.id)} 
                          className="p-3 text-rose-400 hover:text-white hover:bg-rose-600 rounded-xl transition-all shadow-sm bg-rose-50 border border-rose-100"
                        >
                          <Trash2 size={20} />
                        </button>
                      </td>
                    </tr>
                  ))}
                  {items.length === 0 && (<tr><td colSpan={4} className="py-20 text-center text-slate-400 font-bold">目前資料庫尚無任何耗材。</td></tr>)}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'issuance' && (
          <div className="max-w-3xl mx-auto">
             <div className="bg-white p-10 rounded-[2.5rem] shadow-xl border border-slate-200">
                <div className="flex justify-center mb-10">
                  <div className="bg-slate-100 p-1.5 rounded-2xl flex gap-1.5 w-full max-w-sm">
                    <button onClick={() => setIssuanceMode('OUT')} className={`flex-1 py-3 rounded-xl font-black transition-all ${issuanceMode === 'OUT' ? 'bg-white shadow text-rose-600' : 'text-slate-400'}`}>領用出庫</button>
                    <button onClick={() => setIssuanceMode('IN')} className={`flex-1 py-3 rounded-xl font-black transition-all ${issuanceMode === 'IN' ? 'bg-white shadow text-emerald-600' : 'text-slate-400'}`}>補貨入庫</button>
                  </div>
                </div>
                <div className="space-y-8">
                  <div>
                    <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-3 ml-1">1. 選擇資產項目</label>
                    <select className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-200 rounded-2xl font-black text-xl text-black focus:border-blue-500 outline-none" value={selectedItemId} onChange={e => setSelectedItemId(e.target.value)}>
                      <option value="">請點擊下拉選擇項目...</option>
                      {items.map(i => <option key={i.id} value={i.id}>{i.name} (剩餘 {i.quantity} {i.unit})</option>)}
                    </select>
                  </div>
                  <div className="grid grid-cols-2 gap-6">
                    <div>
                      <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-3 ml-1">2. 數量</label>
                      <input type="number" className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-200 rounded-2xl font-black text-xl text-black outline-none focus:border-blue-500" value={inputQty} onChange={e => setInputQty(Number(e.target.value))} />
                    </div>
                    <div>
                      <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-3 ml-1">
                        3. {issuanceMode === 'OUT' ? '領用部門 / 領用人' : '入庫日期'}
                      </label>
                      {issuanceMode === 'OUT' ? (
                        <input type="text" placeholder="例如：機電組 陳大文" className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-200 rounded-2xl font-black text-xl text-black outline-none focus:border-blue-500" value={inputPerson} onChange={e => setInputPerson(e.target.value)} />
                      ) : (
                        <input type="date" className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-200 rounded-2xl font-black text-xl text-black outline-none focus:border-blue-500" value={inputDate} onChange={e => setInputDate(e.target.value)} />
