        {activeTab === 'history' && (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
             <table className="w-full text-left">
               <thead className="bg-slate-50 text-slate-500 font-black text-[10px] uppercase tracking-wider border-b border-slate-200">
                 <tr>
                   <th className="px-8 py-5">異動時間</th>
                   <th className="px-8 py-5">耗材名稱</th>
                   <th className="px-8 py-5">動作</th>
                   <th className="px-8 py-5">對象/日期</th>
                   <th className="px-8 py-5 text-right">列印</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-slate-100 text-slate-900">
                 {logs.map(log => (
                   <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                     <td className="px-8 py-5 font-mono text-slate-400 text-xs font-bold">{new Date(log.timestamp).toLocaleString()}</td>
                     <td className="px-8 py-5 font-black text-slate-900">{log.itemName} <span className="text-slate-400 text-xs ml-1">x{log.quantity}</span></td>
                     <td className="px-8 py-5">
                       {log.type === 'OUT' ? <span className="text-rose-600 font-black text-sm">領用出庫</span> : <span className="text-emerald-600 font-black text-sm">補貨入庫</span>}
                     </td>
                     <td className="px-8 py-5 font-bold text-slate-700 text-sm">{log.person}</td>
                     <td className="px-8 py-5 text-right">
                        {log.type === 'OUT' && (
                          <button onClick={() => {setLastTransaction(log); setShowPrintModal(true);}} className="p-2.5 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-600 hover:text-white transition-all"><Printer size={18} /></button>
