          <div className="bg-white rounded-[2rem] w-full max-w-xl shadow-2xl overflow-hidden border border-slate-300">
            <div className="p-6 border-b-2 bg-slate-50 flex justify-between items-center">
              <h3 className="font-black text-2xl text-black">新增項目至資料庫</h3>
              <button onClick={() => setShowAddModal(false)} className="p-2 hover:bg-slate-200 rounded-full text-slate-500"><X size={24} /></button>
            </div>
            <div className="p-8 space-y-6">
              <div className="grid grid-cols-2 gap-6">
                <div className="col-span-2">
                  <label className="block text-xs font-black text-slate-500 uppercase mb-2">耗材名稱</label>
                  <input type="text" className="w-full px-5 py-3.5 bg-slate-50 border-2 border-slate-200 rounded-xl font-black text-xl text-black focus:border-blue-500 outline-none" value={newForm.name} onChange={e => setNewForm({...newForm, name: e.target.value})} />
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-500 uppercase mb-2">類別</label>
                  <select className="w-full px-5 py-3.5 bg-slate-50 border-2 border-slate-200 rounded-xl font-black text-black outline-none focus:border-blue-500" value={newForm.category} onChange={e => setNewForm({...newForm, category: e.target.value as Category})}>
                    {Object.values(Category).map(cat => <option key={cat} value={cat}>{cat}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-500 uppercase mb-2">單位 (個/雙/卷)</label>
                  <input type="text" className="w-full px-5 py-3.5 bg-slate-50 border-2 border-slate-200 rounded-xl font-black text-black outline-none focus:border-blue-500" value={newForm.unit} onChange={e => setNewForm({...newForm, unit: e.target.value})} />
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-500 uppercase mb-2">初始庫存量</label>
                  <input type="number" className="w-full px-5 py-3.5 bg-slate-50 border-2 border-slate-200 rounded-xl font-black text-black outline-none focus:border-blue-500" value={newForm.quantity} onChange={e => setNewForm({...newForm, quantity: Number(e.target.value)})} />
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-500 uppercase mb-2">警戒庫存</label>
                  <input type="number" className="w-full px-5 py-3.5 bg-slate-50 border-2 border-slate-200 rounded-xl font-black text-black outline-none focus:border-blue-500" value={newForm.minStock} onChange={e => setNewForm({...newForm, minStock: Number(e.target.value)})} />
                </div>
              </div>
              <button onClick={handleAddItem} className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black text-xl hover:bg-black transition-all shadow-xl">完成並儲存資產項目</button>
            </div>
          </div>
        </div>
      )}

      {/* 設定 Modal */}
      {showSettings && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-md z-[110] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2rem] w-full max-w-md shadow-2xl overflow-hidden text-black border border-slate-300">
            <div className="p-6 border-b-2 bg-slate-50 flex justify-between items-center">
              <h3 className="font-black text-xl flex items-center gap-2"><Cloud className="text-blue-500" /> 雲端同步連結</h3>
              <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-slate-200 rounded-full text-slate-400"><X size={20} /></button>
            </div>
            <div className="p-8 space-y-6">
              <div>
                <label className="block text-xs font-black text-slate-400 mb-3 tracking-widest uppercase">Apps Script URL</label>
                <div className="relative">
                  <Link2 className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                  <input type="text" className="w-full pl-10 pr-4 py-4 bg-slate-50 border-2 border-slate-200 rounded-2xl font-bold text-blue-600 outline-none" placeholder="貼上執行網址..." value={cloudUrl} onChange={(e) => setCloudUrl(e.target.value)} />
                </div>
              </div>
              <button onClick={() => { localStorage.setItem(STORAGE_KEY_CLOUD_URL, cloudUrl); setShowSettings(false); if(cloudUrl) fetchFromCloud(); }} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black text-lg shadow-xl hover:bg-black transition-all">儲存並立即連線同步</button>
            </div>
          </div>
        </div>
      )}

      {/* 領用單預覽 Modal */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-black/95 z-[200] flex flex-col items-center justify-start p-4 overflow-y-auto">
          <div className="w-full max-w-5xl bg-white rounded-[2.5rem] my-6 relative shadow-2xl flex flex-col min-h-[90vh] border border-slate-300 overflow-hidden">
            <div className="p-8 border-b-4 border-slate-100 flex justify-between items-center sticky top-0 bg-white z-20">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg shadow-indigo-200"><Printer size={32} /></div>
                <h3 className="font-black text-3xl text-black">領用單據預覽</h3>
              </div>
              <div className="flex gap-4">
                <button onClick={() => window.print()} className="px-12 py-4 bg-indigo-600 text-white rounded-2xl font-black text-xl shadow-xl hover:bg-indigo-700 transition-all">列印單據</button>
                <button onClick={() => setShowPrintModal(false)} className="p-4 text-slate-300 hover:text-black hover:bg-slate-100 rounded-full transition-all"><X size={40} /></button>
              </div>
            </div>
            <div className="flex-1 p-12 bg-slate-100 flex justify-center overflow-auto">
              <div className="shadow-2xl bg-white p-4">
                <PrintableForm transaction={lastTransaction} />
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  RefreshCw,
  Sparkles,
  Search,
  CheckCircle2,
  X,
  Printer,
  Cloud,
  Settings,
  Link2
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType } from './types';
import { getInventoryInsights } from './services/geminiService';

/** 
 * [重要] 請將您的 Google Apps Script URL 貼在下方的引號內 
 * 例如: const DEFAULT_FIXED_URL = "https://script.google.com/macros/s/xxxx/exec";
 */
const DEFAULT_FIXED_URL = ""; 

const STORAGE_KEY_ITEMS = 'safeman_items';
const STORAGE_KEY_LOGS = 'safeman_logs';
const STORAGE_KEY_CLOUD_URL = 'safeman_cloud_url';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'issuance' | 'history'>('dashboard');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [cloudUrl, setCloudUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_CLOUD_URL) || DEFAULT_FIXED_URL);
  const [isSyncing, setIsSyncing] = useState(false);
  const [aiAdvice, setAiAdvice] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // 登記表單狀態
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState(1);
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputDate, setInputDate] = useState(new Date().toISOString().split('T')[0]); 
  const [inputReason, setInputReason] = useState('');

  // 初始化載入：先拿本地，再拿雲端
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedLogs) setLogs(JSON.parse(savedLogs));

    // 如果有固定 URL 且本地沒存過 URL，則自動存入
    if (cloudUrl) {
      localStorage.setItem(STORAGE_KEY_CLOUD_URL, cloudUrl);
      fetchFromCloud(cloudUrl);
    }
  }, []);

  const fetchFromCloud = async (targetUrl: string) => {
    if (!targetUrl) return;
    setIsSyncing(true);
    try {
      const response = await fetch(targetUrl);
      const text = await response.text();
      if (!text || text.trim() === "") return;
      const data = JSON.parse(text);
      if (data.items) {
        setItems(data.items);
        localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(data.items));
      }
      if (data.logs) {
        setLogs(data.logs);
        localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(data.logs));
      }
    } catch (err) {
      console.error('從雲端抓取資料失敗', err);
    } finally {
      setIsSyncing(false);
    }
  };

  const syncToCloud = async (newItems: InventoryItem[], newLogs: Transaction[]) => {
    if (!cloudUrl) return;
    setIsSyncing(true);
    try {
      await fetch(cloudUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items: newItems, logs: newLogs, lastUpdate: Date.now() })
      });
    } catch (err) {
      console.error('同步至雲端失敗', err);
    } finally {
      setIsSyncing(false);
    }
  };

  // 核心修復：徹底解決無法刪除問題
  const deleteItem = (id: string) => {
    if (window.confirm('確定要永久刪除此項目？這將同步更新至雲端資料庫。')) {
      // 1. 計算新陣列
      const updatedItems = items.filter(item => item.id !== id);

      // 2. 立即更新 UI
      setItems(updatedItems);

      // 3. 立即強制寫入本地儲存，確保刷新也不會回來
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(updatedItems));

      // 4. 背景同步至雲端
      syncToCloud(updatedItems, logs);
    }
  };

  const handleAddItem = () => {
    if (!newForm.name) return alert('請填寫名稱');
    const newItem: InventoryItem = {
      ...newForm,
      id: crypto.randomUUID(),
      lastUpdated: Date.now()
    };
    const updatedItems = [...items, newItem];
    setItems(updatedItems);
    localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(updatedItems));
    syncToCloud(updatedItems, logs);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, unit: '個', minStock: 5, quantity: 0, description: '' });
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    unit: '個',
    minStock: 5,
    quantity: 0,
    description: ''
  });

  const handleTransaction = () => {
    if (!selectedItemId || inputQty <= 0) return alert('請選擇項目與數量');
    if (issuanceMode === 'OUT' && !inputPerson) return alert('請輸入領用部門/人員');

    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    if (issuanceMode === 'OUT' && targetItem.quantity < inputQty) return alert('庫存不足！');

    const updatedItems = items.map(i => {
      if (i.id === selectedItemId) {
        return { 
          ...i, 
          quantity: issuanceMode === 'IN' ? i.quantity + inputQty : i.quantity - inputQty, 
          lastUpdated: Date.now() 
        };
      }
      return i;
    });

    const newLog: Transaction = {
      id: crypto.randomUUID(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: inputQty,
      person: issuanceMode === 'OUT' ? inputPerson : `入庫日期: ${inputDate}`,
      reason: inputReason,
      timestamp: Date.now()
    };

    const updatedLogs = [newLog, ...logs];
    setItems(updatedItems);
    setLogs(updatedLogs);
    setLastTransaction(newLog);

    localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(updatedItems));
    localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(updatedLogs));
    syncToCloud(updatedItems, updatedLogs);

    setSelectedItemId(''); setInputQty(1); setInputPerson(''); setInputReason('');

    if (issuanceMode === 'OUT') setShowPrintModal(true);
    else alert('入庫登記完成。');
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    const advice = await getInventoryInsights(items);
    setAiAdvice(advice);
    setIsAiLoading(false);
  };

  // 正式台電格式領用單 (精確還原)
  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const now = new Date(transaction.timestamp);
    const minguoYear = now.getFullYear() - 1911;

    return (
      <div className="bg-white p-16 w-[210mm] mx-auto text-black border-[4px] border-black print:m-0" id="print-area">
        <style>{`
          @media print { 
            body * { visibility: hidden; } 
            #print-area, #print-area * { visibility: visible; } 
            #print-area { position: absolute; left: 0; top: 0; width: 100%; border: none; } 
          }
          #print-area h1 { color: black !important; font-size: 34px !important; font-weight: 900 !important; margin-bottom: 2rem; }
          #print-area p, #print-area td, #print-area th { color: black !important; font-weight: 800 !important; border-color: black !important; }
        `}</style>

        <h1 className="text-center font-black tracking-tighter">台灣電力公司電力修護處南部分處 領用單</h1>

        <div className="flex justify-between mb-8 px-4 text-2xl font-black">
          <p>領用部門：<span className="underline underline-offset-8 px-4">{transaction.person}</span></p>
          <p>中華民國 {minguoYear} 年 {now.getMonth() + 1} 月 {now.getDate()} 日</p>
        </div>

        <table className="w-full border-collapse border-[4px] border-black text-center text-xl">
          <thead>
            <tr className="bg-gray-100 border-b-[4px] border-black">
              <th className="border-r-[4px] border-black p-5">項目名稱 / 規格</th>
              <th className="border-r-[4px] border-black p-5 w-24">單位</th>
              <th className="border-r-[4px] border-black p-5 w-32">數量</th>
              <th className="p-5">備註 (工程代號)</th>
            </tr>
          </thead>
          <tbody>
            <tr className="border-b-[4px] border-black h-40">
              <td className="border-r-[4px] border-black p-5 text-3xl font-black">{transaction.itemName}</td>
              <td className="border-r-[4px] border-black p-5">{targetItem?.unit || '個'}</td>
              <td className="border-r-[4px] border-black p-5 text-6xl font-black">{transaction.quantity}</td>
              <td className="p-5 text-xl">{transaction.reason}</td>
            </tr>
            {/* 補足空白行以符合正式單據感 */}
            {[...Array(4)].map((_, i) => (
              <tr key={i} className="border-b-[4px] border-black h-20">
                <td className="border-r-[4px] border-black"></td><td className="border-r-[4px] border-black"></td><td className="border-r-[4px] border-black"></td><td></td>
              </tr>
            ))}
          </tbody>
        </table>

        <div className="mt-24 grid grid-cols-3 gap-12 text-2xl font-black text-center">
          <p>經辦：__________</p>
          <p>課長：__________</p>
          <p>經理：__________</p>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-[#F8FAFC] text-slate-900 overflow-hidden">
      {/* 側邊欄 */}
      <aside className="w-72 bg-[#0F172A] text-white p-8 flex flex-col shadow-2xl z-50">
        <div className="flex items-center gap-4 mb-14">
          <div className="p-3 bg-blue-600 rounded-2xl shadow-lg shadow-blue-500/20"><Package size={28} /></div>
          <h1 className="font-black text-2xl tracking-tighter">工安管理系統</h1>
        </div>

        <nav className="flex-1 space-y-3">
          {[
            { id: 'dashboard', icon: LayoutDashboard, label: '儀表板總覽' },
            { id: 'inventory', icon: Package, label: '耗材資料庫' },
            { id: 'issuance', icon: FileText, label: '領用登記' },
            { id: 'history', icon: History, label: '異動日誌' },
          ].map((tab) => (
            <button 
              key={tab.id} 
              onClick={() => setActiveTab(tab.id as any)} 
              className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl font-black transition-all ${activeTab === tab.id ? 'bg-blue-600 shadow-xl text-white scale-105' : 'text-slate-400 hover:bg-slate-800'}`}
            >
              <tab.icon size={22} /> {tab.label}
            </button>
          ))}
        </nav>

        <div className="mt-auto pt-8 border-t border-slate-800 space-y-4">
          <div className={`p-5 rounded-3xl border transition-all ${cloudUrl ? 'bg-emerald-500/10 border-emerald-500/30' : 'bg-slate-800 border-slate-700'}`}>
            <div className="flex items-center justify-between mb-4">
              <span className={`text-[10px] font-black uppercase tracking-widest flex items-center gap-2 ${cloudUrl ? 'text-emerald-400' : 'text-slate-500'}`}>
                <Cloud size={16} /> {cloudUrl ? '雲端模式' : '本地儲存'}
              </span>
              <button onClick={() => setShowSettings(true)} className="p-1 hover:bg-white/10 rounded-lg text-slate-400"><Settings size={18} /></button>
            </div>
            {cloudUrl && (
              <button onClick={() => fetchFromCloud(cloudUrl)} disabled={isSyncing} className="w-full py-3 bg-emerald-600 hover:bg-emerald-500 rounded-xl text-xs font-black flex items-center justify-center gap-2 shadow-lg disabled:opacity-50 text-white">
                <RefreshCw size={14} className={isSyncing ? 'animate-spin' : ''} />
                同步雲端
              </button>
            )}
          </div>
        </div>
      </aside>

      {/* 主內容區 */}
      <main className="flex-1 p-12 overflow-y-auto">
        <header className="mb-12 flex justify-between items-end border-b-2 border-slate-200 pb-10">
          <h2 className="text-5xl font-black text-slate-900 tracking-tighter">
            {activeTab === 'dashboard' && '數據決策中心'}
            {activeTab === 'inventory' && '設備資產清冊'}
            {activeTab === 'issuance' && '領用出庫登記'}
            {activeTab === 'history' && '異動日誌紀錄'}
          </h2>
        </header>

        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-3 gap-10">
            <div className="bg-white p-10 rounded-[3rem] shadow-sm border border-slate-200">
              <p className="text-slate-400 font-black text-xs uppercase tracking-widest mb-2">總資產項目</p>
              <p className="text-7xl font-black text-slate-900">{items.length}</p>
            </div>
            <div className="bg-white p-10 rounded-[3rem] shadow-sm border border-slate-200">
