                <th className="border-r-2 border-black p-3 w-1/6">單位</th>
                <th className="border-r-2 border-black p-3 w-1/6">數量</th>
                <th className="p-3 w-1/4">備註 (工程代號)</th>
              </tr>
            </thead>
            <tbody>
              <tr className="border-b-2 border-black h-32">
                <td className="border-r-2 border-black p-3 font-bold">{transaction.itemName}</td>
                <td className="border-r-2 border-black p-3">{targetItem?.unit || '個'}</td>
                <td className="border-r-2 border-black p-3 text-2xl font-bold">{transaction.quantity}</td>
                <td className="p-3 text-sm leading-tight">{transaction.reason}</td>
              </tr>
              {/* 空白列 */}
              {[...Array(5)].map((_, i) => (
                <tr key={i} className="border-b-2 border-black h-12">
                  <td className="border-r-2 border-black"></td>
                  <td className="border-r-2 border-black"></td>
                  <td className="border-r-2 border-black"></td>
                  <td></td>
                </tr>
              ))}
            </tbody>
          </table>

          <div className="mt-12 grid grid-cols-3 gap-4 text-center font-14pt">
            <p>經辦：__________</p>
            <p>課長：__________</p>
            <p>經理：__________</p>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-gray-50 text-slate-900 font-sans">
      {/* 側邊導覽 */}
      <aside className="w-64 bg-slate-900 text-white p-6 flex flex-col shadow-xl">
        <div className="flex items-center gap-3 mb-10">
          <Package className="text-blue-400" size={28} />
          <h1 className="font-bold text-lg tracking-tight">工安管理系統</h1>
        </div>

        <nav className="flex-1 space-y-1">
          {[
            { id: 'dashboard', icon: LayoutDashboard, label: '儀表板' },
            { id: 'inventory', icon: Package, label: '耗材清冊' },
            { id: 'issuance', icon: FileText, label: '領用登記' },
            { id: 'history', icon: History, label: '異動日誌' },
          ].map((tab) => (
            <button 
              key={tab.id} 
              onClick={() => setActiveTab(tab.id as any)} 
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-medium transition-colors ${activeTab === tab.id ? 'bg-blue-600 text-white' : 'text-slate-400 hover:bg-slate-800'}`}
            >
              <tab.icon size={18} /> {tab.label}
            </button>
          ))}
        </nav>

        <div className="mt-auto border-t border-slate-800 pt-6">
          <div className="flex items-center justify-between px-2 text-[10px] text-slate-500 font-bold uppercase tracking-widest">
            <span className="flex items-center gap-1.5"><Cloud size={12} /> {FIXED_URL ? '雲端連線中' : '僅本地存儲'}</span>
            {isSyncing && <RefreshCw size={12} className="animate-spin text-blue-400" />}
          </div>
        </div>
      </aside>

      {/* 主畫面 */}
      <main className="flex-1 p-8 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-2xl font-bold text-slate-800">
            {activeTab === 'dashboard' && '數據總覽'}
            {activeTab === 'inventory' && '耗材設備管理'}
            {activeTab === 'issuance' && '領用出庫作業'}
            {activeTab === 'history' && '異動歷史紀錄'}
          </h2>
          {activeTab === 'inventory' && (
            <button onClick={() => setShowAddModal(true)} className="bg-blue-600 text-white px-5 py-2 rounded-lg font-bold flex items-center gap-2 hover:bg-blue-700 transition-shadow shadow-md">
              <Plus size={18} /> 新增項目
            </button>
