              <button onClick={() => setIssuanceMode('IN')} className={`flex-1 py-2 rounded-lg font-bold text-sm transition-all ${issuanceMode === 'IN' ? 'bg-white shadow text-emerald-600' : 'text-slate-500'}`}>補貨入庫</button>
