              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 mb-2">2. 數量</label>
                  <input type="number" className="w-full px-4 py-3 bg-slate-50 border rounded-xl font-bold outline-none" value={inputQty} onChange={e => setInputQty(Number(e.target.value))} />
