                  <label className="block text-xs font-bold text-slate-500 mb-2">3. {issuanceMode === 'OUT' ? '領用部門 / 人員' : '入庫日期'}</label>
                  {issuanceMode === 'OUT' ? (
                    <input type="text" placeholder="例：維修組 王小明" className="w-full px-4 py-3 bg-slate-50 border rounded-xl font-bold outline-none" value={inputPerson} onChange={e => setInputPerson(e.target.value)} />
                  ) : (
                    <input type="date" className="w-full px-4 py-3 bg-slate-50 border rounded-xl font-bold outline-none" value={inputDate} onChange={e => setInputDate(e.target.value)} />
