              <div>
                <label className="block text-xs font-bold text-slate-500 mb-2">4. 備註 / 工程代號</label>
                <textarea rows={2} className="w-full px-4 py-3 bg-slate-50 border rounded-xl text-sm outline-none" placeholder="說明用途..." value={inputReason} onChange={e => setInputReason(e.target.value)}></textarea>
              </div>
              <button onClick={handleTransaction} className={`w-full py-4 rounded-xl font-bold text-white shadow-lg transition-transform active:scale-[0.98] ${issuanceMode === 'OUT' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-emerald-600 hover:bg-emerald-700'}`}>
                {issuanceMode === 'OUT' ? '確認領用並列印' : '確認入庫'}
              </button>
            </div>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-xl shadow-sm border overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-slate-500 text-[10px] uppercase font-bold border-b">
                <tr>
                  <th className="px-6 py-4">時間</th>
                  <th className="px-6 py-4">項目</th>
                  <th className="px-6 py-4">類型</th>
                  <th className="px-6 py-4">對象</th>
                  <th className="px-6 py-4 text-right">單據</th>
                </tr>
              </thead>
              <tbody className="divide-y text-sm">
                {logs.map(log => (
                  <tr key={log.id} className="hover:bg-slate-50">
                    <td className="px-6 py-4 text-slate-400">{new Date(log.timestamp).toLocaleString()}</td>
                    <td className="px-6 py-4 font-bold">{log.itemName} (x{log.quantity})</td>
                    <td className="px-6 py-4">
                      {log.type === 'OUT' ? <span className="text-blue-600">領用</span> : <span className="text-emerald-600">補貨</span>}
                    </td>
                    <td className="px-6 py-4 text-slate-600">{log.person}</td>
                    <td className="px-6 py-4 text-right">
                      {log.type === 'OUT' && (
                        <button onClick={() => {setLastTransaction(log); setShowPrintModal(true);}} className="p-2 bg-slate-100 text-slate-600 rounded-lg hover:bg-blue-600 hover:text-white transition-colors"><Printer size={16} /></button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </main>

      {/* 新增項目 Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl overflow-hidden text-black">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50">
              <h3 className="font-bold text-lg">新增耗材資產</h3>
              <button onClick={() => setShowAddModal(false)} className="text-slate-400 hover:text-black"><X size={20} /></button>
            </div>
            <div className="p-8 space-y-4">
              <div>
                <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">耗材名稱</label>
                <input type="text" className="w-full px-4 py-3 bg-slate-50 border rounded-xl font-bold outline-none" value={newForm.name} onChange={e => setNewForm({...newForm, name: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">單位 (例: 個)</label>
                  <input type="text" className="w-full px-4 py-3 bg-slate-50 border rounded-xl font-bold outline-none" value={newForm.unit} onChange={e => setNewForm({...newForm, unit: e.target.value})} />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">分類</label>
                  <select className="w-full px-4 py-3 bg-slate-50 border rounded-xl font-bold outline-none" value={newForm.category} onChange={e => setNewForm({...newForm, category: e.target.value as Category})}>
                    {Object.values(Category).map(cat => <option key={cat} value={cat}>{cat}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">現有庫存</label>
                  <input type="number" className="w-full px-4 py-3 bg-slate-50 border rounded-xl font-bold outline-none" value={newForm.quantity} onChange={e => setNewForm({...newForm, quantity: Number(e.target.value)})} />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">安全警示水位</label>
                  <input type="number" className="w-full px-4 py-3 bg-slate-50 border rounded-xl font-bold outline-none" value={newForm.minStock} onChange={e => setNewForm({...newForm, minStock: Number(e.target.value)})} />
                </div>
              </div>
              <button onClick={handleAddItem} className="w-full py-4 bg-slate-900 text-white rounded-xl font-bold hover:bg-black mt-4 transition-colors">確認新增至清冊</button>
            </div>
          </div>
        </div>
      )}

      {/* 領用單預覽 */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-black/80 z-[200] flex flex-col items-center justify-center p-4">
          <div className="bg-white rounded-2xl w-full max-w-4xl shadow-2xl flex flex-col max-h-[90vh] overflow-hidden">
            <div className="p-6 border-b flex justify-between items-center text-black bg-slate-50">
              <div className="flex items-center gap-2"><Printer className="text-blue-600" /> <h3 className="font-bold">單據預覽 (標楷體 14pt)</h3></div>
              <div className="flex gap-2">
                <button onClick={() => window.print()} className="bg-blue-600 text-white px-6 py-2 rounded-lg font-bold shadow-md">立即列印</button>
                <button onClick={() => setShowPrintModal(false)} className="p-2 text-slate-400 hover:text-black hover:bg-slate-200 rounded-full transition-colors"><X size={20} /></button>
              </div>
