  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  RefreshCw,
  Search,
  CheckCircle2,
  X,
  Printer,
  Cloud
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType } from './types';

/** 
 * [重要] 請貼上您的 URL
 */
const FIXED_URL = "https://script.google.com/macros/s/AKfycbyVn1L9L98Oq0C29M42pS18f7fX_6m85h3q0UqKk9qW9q9q9q9q9q9q9q9q9q9q9q/exec"; 

const STORAGE_KEY_ITEMS = 'safeman_final_v1';
const STORAGE_KEY_LOGS = 'safeman_final_logs_v1';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'issuance' | 'history'>('dashboard');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // 登記表單
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState(1);
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');

  // 初始化載入
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    if (savedItems) setItems(JSON.parse(savedItems));
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedLogs) setLogs(JSON.parse(savedLogs));

    if (FIXED_URL) {
      fetchFromCloud();
    }
  }, []);

  const fetchFromCloud = async () => {
    if (!FIXED_URL || isSyncing) return;
    setIsSyncing(true);
    try {
      const response = await fetch(FIXED_URL);
      const data = await response.json();
      if (data.items) {
        setItems(data.items);
        localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(data.items));
      }
      if (data.logs) {
        setLogs(data.logs);
        localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(data.logs));
      }
    } catch (err) {
      console.error('Fetch error:', err);
    } finally {
      setIsSyncing(false);
    }
  };

  const syncToCloud = async (newItems: InventoryItem[], newLogs: Transaction[]) => {
    if (!FIXED_URL) return;
    setIsSyncing(true);
    try {
      // 先存本地確保不丟失
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(newItems));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(newLogs));

      await fetch(FIXED_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items: newItems, logs: newLogs, lastUpdate: Date.now() })
      });
    } catch (err) {
      console.error('Sync error:', err);
    } finally {
      setIsSyncing(false);
    }
  };

  // 修復刪除邏輯：即時過濾並強制更新本地
  const deleteItem = (id: string) => {
    const confirmDelete = window.confirm('確定要刪除嗎？這將會同步至雲端並覆蓋舊數據。');
    if (!confirmDelete) return;

    const updatedItems = items.filter(i => i.id !== id);
    setItems(updatedItems);
    syncToCloud(updatedItems, logs);
  };

  const handleTransaction = () => {
    if (!selectedItemId) return alert('錯誤：尚未選擇任何耗材項目！');
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    // 庫存檢查警告
    if (issuanceMode === 'OUT' && inputQty > targetItem.quantity) {
      return alert(`⚠️ 庫存不足警告！\n\n項目：${targetItem.name}\n目前庫存：${targetItem.quantity} ${targetItem.unit}\n請求領用：${inputQty} ${targetItem.unit}\n\n請調整領用數量或先進行補貨。`);
    }

    if (inputQty <= 0) return alert('數量必須大於 0');

    const updatedItems = items.map(i => {
      if (i.id === selectedItemId) {
        return { 
          ...i, 
          quantity: issuanceMode === 'IN' ? i.quantity + inputQty : i.quantity - inputQty,
          lastUpdated: Date.now()
        };
      }
      return i;
    });

    const newLog: Transaction = {
      id: crypto.randomUUID(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: inputQty,
      person: inputPerson || (issuanceMode === 'IN' ? '系統入庫' : '未知部門'),
      reason: inputReason,
      timestamp: Date.now()
    };

    const updatedLogs = [newLog, ...logs];
    setItems(updatedItems);
    setLogs(updatedLogs);
    setLastTransaction(newLog);
    syncToCloud(updatedItems, updatedLogs);

    if (issuanceMode === 'OUT') setShowPrintModal(true);
    else alert('補貨完畢，庫存已更新。');
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    unit: '個',
    minStock: 5,
    quantity: 0
  });

  const handleAddItem = () => {
    if (!newForm.name) return alert('請輸入名稱');
    const newItem: InventoryItem = {
      ...newForm,
      id: crypto.randomUUID(),
      description: '',
      lastUpdated: Date.now()
    };
    const updatedItems = [...items, newItem];
    setItems(updatedItems);
    syncToCloud(updatedItems, logs);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, unit: '個', minStock: 5, quantity: 0 });
  };

  // 100% 還原圖片格式的領用單
  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const now = new Date(transaction.timestamp);
    const minguoYear = now.getFullYear() - 1911;

    return (
      <div className="bg-white p-8 w-[210mm] mx-auto text-black print:m-0" id="print-area">
        <style>{`
          @media print { 
            body * { visibility: hidden; } 
            #print-area, #print-area * { visibility: visible; } 
            #print-area { position: absolute; left: 0; top: 0; width: 100%; } 
          }
          .kai-font { font-family: "DFKai-SB", "BiauKai", "標楷體", serif; }
          .f-14 { font-size: 14pt; }
          .f-20 { font-size: 20pt; }
        `}</style>

        <div className="kai-font text-black leading-relaxed">
