          </div>

          <table className="w-full border-collapse border-2 border-black f-14 text-center">
            <thead>
              <tr className="border-b-2 border-black h-12">
                <th className="border-r-2 border-black w-1/3">名　　稱</th>
                <th className="border-r-2 border-black w-1/4">規範 (序號)</th>
                <th className="border-r-2 border-black w-32">單位</th>
