              </tr>
            </thead>
            <tbody>
              <tr className="border-b-2 border-black h-20">
                <td className="border-r-2 border-black font-bold text-lg">{transaction.itemName}</td>
                <td className="border-r-2 border-black text-sm">--</td>
                <td className="border-r-2 border-black">{targetItem?.unit || '個'}</td>
                <td className="border-r-2 border-black font-bold text-xl">{transaction.quantity}</td>
                <td className="text-sm px-2">{transaction.reason}</td>
              </tr>
              {/* 補足 15 橫列以符合圖片 */}
              {[...Array(14)].map((_, i) => (
                <tr key={i} className="border-b-2 border-black h-10">
                  <td className="border-r-2 border-black"></td><td className="border-r-2 border-black"></td><td className="border-r-2 border-black"></td><td className="border-r-2 border-black"></td><td></td>
                </tr>
              ))}
            </tbody>
          </table>

          <div className="mt-8 grid grid-cols-2 f-14 gap-10">
            <div>
              <p className="mb-4 underline">申請部門：</p>
              <div className="flex justify-between px-2">
                <span>經辦：______</span><span>課長：______</span><span>經理：______</span>
              </div>
            </div>
            <div>
              <p className="mb-4 underline">經辦部門：</p>
              <div className="flex justify-between px-2">
