          <button onClick={() => setActiveTab('inventory')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg text-sm transition-all ${activeTab === 'inventory' ? 'bg-blue-600' : 'hover:bg-slate-800'}`}><Package size={18}/> 耗材清冊</button>
          <button onClick={() => setActiveTab('issuance')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg text-sm transition-all ${activeTab === 'issuance' ? 'bg-blue-600' : 'hover:bg-slate-800'}`}><FileText size={18}/> 領用登記</button>
          <button onClick={() => setActiveTab('history')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg text-sm transition-all ${activeTab === 'history' ? 'bg-blue-600' : 'hover:bg-slate-800'}`}><History size={18}/> 異動日誌</button>
        </nav>
        <div className="mt-auto pt-6 border-t border-slate-800 text-[10px] text-slate-500 font-bold uppercase tracking-widest flex items-center justify-between">
          <span className="flex items-center gap-1"><Cloud size={10}/> {FIXED_URL ? '雲端連線' : '本地'}</span>
          {isSyncing && <RefreshCw size={10} className="animate-spin text-blue-400"/>}
