              <button onClick={handleTransaction} className={`w-full py-5 rounded-xl font-bold text-white text-lg shadow-lg active:scale-95 transition-all ${issuanceMode === 'OUT' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-emerald-600 hover:bg-emerald-700'}`}>
                {issuanceMode === 'OUT' ? '確認領用並預覽單據' : '確認入庫更新'}
              </button>
            </div>
          </div>
        )}

        {/* 餘下 Dashboard 與 History 簡化呈現 */}
        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-white p-8 rounded-2xl border shadow-sm">
              <p className="text-slate-400 text-xs font-bold uppercase mb-2">資產總項</p>
              <p className="text-5xl font-bold text-black">{items.length}</p>
            </div>
            <div className="bg-white p-8 rounded-2xl border shadow-sm">
              <p className="text-rose-500 text-xs font-bold uppercase mb-2">需要補貨</p>
              <p className="text-5xl font-bold text-rose-600">{items.filter(i => i.quantity <= i.minStock).length}</p>
            </div>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-xl shadow-sm border overflow-hidden text-black">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[10px] font-bold text-slate-500 uppercase border-b">
                <tr><th className="px-6 py-4">時間</th><th className="px-6 py-4">項目</th><th className="px-6 py-4">類別</th><th className="px-6 py-4">部門</th><th className="px-6 py-4 text-right">列印</th></tr>
              </thead>
              <tbody className="divide-y">
                {logs.map(log => (
                  <tr key={log.id} className="hover:bg-slate-50">
                    <td className="px-6 py-4 text-xs text-slate-400 font-mono">{new Date(log.timestamp).toLocaleString()}</td>
                    <td className="px-6 py-4 font-bold text-black">{log.itemName} (x{log.quantity})</td>
                    <td className="px-6 py-4 text-xs font-bold">{log.type === 'OUT' ? <span className="text-blue-600">領用出庫</span> : <span className="text-emerald-600">補貨入庫</span>}</td>
                    <td className="px-6 py-4 text-slate-600 font-bold">{log.person}</td>
                    <td className="px-6 py-4 text-right">
                      {log.type === 'OUT' && <button onClick={() => {setLastTransaction(log); setShowPrintModal(true);}} className="text-blue-600 hover:bg-blue-50 p-2 rounded-lg"><Printer size={18} /></button>}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </main>

      {/* 新增耗材 Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl overflow-hidden text-black">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50">
              <h3 className="font-bold text-xl">新增資產項目</h3>
              <button onClick={() => setShowAddModal(false)}><X /></button>
            </div>
            <div className="p-8 space-y-5">
              <div><label className="block text-xs font-bold text-slate-400 mb-1">名稱</label><input type="text" className="w-full p-4 border rounded-xl font-bold bg-white" value={newForm.name} onChange={e => setNewForm({...newForm, name: e.target.value})} /></div>
              <div className="grid grid-cols-2 gap-4">
