                <div><label className="block text-xs font-bold text-slate-400 mb-1">安全警戒水位</label><input type="number" className="w-full p-4 border rounded-xl font-bold bg-white" value={newForm.minStock} onChange={e => setNewForm({...newForm, minStock: Number(e.target.value)})} /></div>
