import React, { useState, useEffect, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  RefreshCw,
  Search,
  X,
  Printer,
  Cloud,
  AlertTriangle
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType } from './types';

/** 
 * [配置] 您的 Google Apps Script URL
 * 提醒：請確保 Script 已發佈為「網頁應用程式」，且存取權限為「任何人」
 */
const FIXED_URL = "https://script.google.com/macros/s/AKfycbyVn1L9L98Oq0C29M42pS18f7fX_6m85h3q0UqKk9qW9q9q9q9q9q9q9q9q9q9q9q/exec"; 

const STORAGE_KEY_ITEMS = 'safeman_final_v3';
const STORAGE_KEY_LOGS = 'safeman_final_logs_v3';
const STORAGE_KEY_TS = 'safeman_last_update_ts';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'issuance' | 'history'>('dashboard');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // 領用登記狀態
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<number>(1);
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');

  // 用來追蹤本地最後修改時間，防止雲端舊資料回流
  const lastUpdateRef = useRef<number>(Number(localStorage.getItem(STORAGE_KEY_TS) || 0));

  // 初始化載入
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedLogs) setLogs(JSON.parse(savedLogs));

    if (FIXED_URL) {
      fetchFromCloud();
    }
  }, []);

  const fetchFromCloud = async () => {
    if (!FIXED_URL || isSyncing) return;
    setIsSyncing(true);
    try {
      const response = await fetch(FIXED_URL);
      if (!response.ok) throw new Error('連線失敗');
      const data = await response.json();

      // 核心修正：檢查雲端資料的時間戳是否比本地新
      // 或者是第一次載入才允許覆蓋
      const cloudTs = data.lastUpdate || 0;
      if (cloudTs >= lastUpdateRef.current || items.length === 0) {
        if (data.items && Array.isArray(data.items)) {
          setItems(data.items);
          localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(data.items));
        }
        if (data.logs && Array.isArray(data.logs)) {
          setLogs(data.logs);
          localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(data.logs));
        }
      } else {
        console.log("跳過同步：本地數據較新");
      }
    } catch (err) {
      console.error('Fetch error:', err);
    } finally {
      setIsSyncing(false);
    }
  };

  const syncToCloud = async (newItems: InventoryItem[], newLogs: Transaction[]) => {
    const now = Date.now();
    lastUpdateRef.current = now;
    localStorage.setItem(STORAGE_KEY_TS, now.toString());
    localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(newItems));
    localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(newLogs));

    if (!FIXED_URL) return;
    setIsSyncing(true);
    try {
      // 使用 no-cors 時無法確保傳輸成功，所以本地暫存非常重要
      await fetch(FIXED_URL, {
        method: 'POST',
        mode: 'no-cors', 
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items: newItems, logs: newLogs, lastUpdate: now })
      });
    } catch (err) {
      console.error('Sync error:', err);
    } finally {
      setIsSyncing(false);
    }
  };

  const deleteItem = (id: string) => {
    const itemToDelete = items.find(i => i.id === id);
    if (!itemToDelete) return;

    // 立即反應：在確認後馬上更新狀態，不等待網絡
    if (window.confirm(`【確認刪除】\n項目：${itemToDelete.name}\n\n注意：刪除後將會同步至雲端。`)) {
      const updatedItems = items.filter(i => i.id !== id);
      setItems(updatedItems); 
      syncToCloud(updatedItems, logs);
    }
  };

  const handleTransaction = () => {
    if (!selectedItemId) return alert('請先選擇項目');

    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    const qty = Number(inputQty);
    const currentStock = Number(targetItem.quantity);

    // 庫存檢查 (強制數值對比)
    if (issuanceMode === 'OUT' && qty > currentStock) {
      alert(`⚠️ 庫存不足！\n\n${targetItem.name} 剩餘：${currentStock}\n您要領取：${qty}\n\n請調整領用數量。`);
      return;
    }

    if (qty <= 0) return alert('數量無效');

    const updatedItems = items.map(i => {
      if (i.id === selectedItemId) {
        return { 
          ...i, 
          quantity: issuanceMode === 'IN' ? i.quantity + qty : i.quantity - qty,
          lastUpdated: Date.now()
        };
      }
      return i;
    });

    const newLog: Transaction = {
      id: crypto.randomUUID(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: qty,
      person: inputPerson || (issuanceMode === 'IN' ? '入庫' : '領用人'),
      reason: inputReason,
      timestamp: Date.now()
    };

    const updatedLogs = [newLog, ...logs];
    setItems(updatedItems);
    setLogs(updatedLogs);
    setLastTransaction(newLog);
    syncToCloud(updatedItems, updatedLogs);

    if (issuanceMode === 'OUT') setShowPrintModal(true);

    setSelectedItemId('');
    setInputQty(1);
    setInputPerson('');
    setInputReason('');
  };

  const handleAddItem = () => {
    if (!newForm.name) return alert('請輸入名稱');
    const newItem: InventoryItem = {
      ...newForm,
      id: crypto.randomUUID(),
      description: '',
      lastUpdated: Date.now()
    };
    const updatedItems = [...items, newItem];
    setItems(updatedItems);
    syncToCloud(updatedItems, logs);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, unit: '個', minStock: 5, quantity: 0 });
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    unit: '個',
    minStock: 5,
    quantity: 0
  });

  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const now = new Date(transaction.timestamp);
    const minguoYear = now.getFullYear() - 1911;

    return (
      <div className="bg-white p-8 w-[210mm] mx-auto text-black print:p-0 print:m-0" id="print-area">
        <style>{`
          @media print { 
             body { background: white !important; }
             .no-print { display: none !important; }
             #print-area { position: absolute; left: 0; top: 0; width: 100%; color: black !important; background: white !important; }
             #print-area * { color: black !important; border-color: black !important; background: transparent !important; }
          }
          .kai-font { font-family: "標楷體", "DFKai-SB", serif; }
          .f-14pt { font-size: 14pt; color: black !important; }
          .f-24pt { font-size: 24pt; font-weight: bold; color: black !important; }
          .t-border { border: 2px solid black !important; }
        `}</style>

        <div className="kai-font text-black">
          <div className="text-center f-24pt mb-4">台灣電力公司電力修護處南部分處</div>

          <div className="flex justify-center gap-10 mb-8 f-14pt">
            <div className="flex items-center gap-2"><div className="w-5 h-5 t-border"></div> <span>安全衛生設備借用單</span></div>
            <div className="flex items-center gap-2"><div className="w-5 h-5 t-border flex items-center justify-center font-bold">V</div> <span>安全衛生類消耗品領用單</span></div>
          </div>

          <div className="flex justify-between mb-2 f-14pt px-1 font-bold">
            <p>部門：<span className="underline decoration-1 underline-offset-4 px-6">{transaction.person}</span></p>
            <p>日期：{minguoYear} 年 {now.getMonth() + 1} 月 {now.getDate()} 日</p>
          </div>

          <table className="w-full border-collapse t-border f-14pt text-black">
            <thead>
              <tr className="h-14">
                <th className="t-border w-1/3">名　　稱</th>
                <th className="t-border w-1/4">規 範 ( 序 號 )</th>
                <th className="t-border w-20">單位</th>
                <th className="t-border w-20">數量</th>
                <th className="t-border">備　　註</th>
              </tr>
            </thead>
            <tbody>
              <tr className="h-24">
                <td className="t-border font-bold text-xl">{transaction.itemName}</td>
                <td className="t-border text-sm">--</td>
                <td className="t-border">{targetItem?.unit || '個'}</td>
                <td className="t-border font-bold text-2xl">{transaction.quantity}</td>
                <td className="t-border text-sm text-left align-top p-2">{transaction.reason}</td>
              </tr>
              {[...Array(14)].map((_, i) => (
                <tr key={i} className="h-10">
                  <td className="t-border"></td><td className="t-border"></td><td className="t-border"></td><td className="t-border"></td><td className="t-border"></td>
                </tr>
              ))}
            </tbody>
          </table>

          <div className="mt-10 grid grid-cols-2 f-14pt gap-12 text-black">
            <div>
              <p className="mb-4 font-bold">申請部門：__________________</p>
              <div className="flex justify-between text-sm pr-4">
                <span>經辦：______</span><span>課長：______</span><span>經理：______</span>
              </div>
            </div>
            <div>
              <p className="mb-4 font-bold">經辦部門：__________________</p>
              <div className="flex justify-between text-sm pr-4">
                <span>經辦：______</span><span>課長：______</span><span>經理：______</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900 font-sans">
      <aside className="no-print w-64 bg-slate-900 text-white p-6 flex flex-col shadow-2xl shrink-0">
        <div className="flex items-center gap-3 mb-10">
          <div className="bg-blue-600 p-2 rounded-lg"><Package size={20} /></div>
          <h1 className="font-bold text-lg tracking-tight">工安管理系統</h1>
        </div>
        <nav className="flex-1 space-y-2">
          {['dashboard', 'inventory', 'issuance', 'history'].map((id) => (
            <button 
              key={id}
              onClick={() => setActiveTab(id as any)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${activeTab === id ? 'bg-blue-600 shadow-lg text-white' : 'text-slate-400 hover:bg-slate-800'}`}
            >
              {id === 'dashboard' && <LayoutDashboard size={18} />}
              {id === 'inventory' && <Package size={18} />}
              {id === 'issuance' && <FileText size={18} />}
              {id === 'history' && <History size={18} />}
              {id === 'dashboard' ? '儀表板' : id === 'inventory' ? '耗材清冊' : id === 'issuance' ? '領用登記' : '異動日誌'}
            </button>
          ))}
        </nav>
        <div className="mt-auto pt-6 border-t border-slate-800 flex items-center justify-between text-[10px] text-slate-500 font-bold uppercase">
          <span className="flex items-center gap-2"><Cloud size={12} /> {FIXED_URL ? '雲端連線' : '本地模式'}</span>
          {isSyncing && <RefreshCw size={12} className="animate-spin text-blue-400" />}
        </div>
      </aside>

      <main className="no-print flex-1 p-8 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center text-black">
          <h2 className="text-3xl font-black">{activeTab === 'inventory' ? '耗材清冊' : activeTab === 'issuance' ? '領用登記' : activeTab === 'history' ? '異動日誌' : '儀表板'}</h2>
          {activeTab === 'inventory' && (
            <button onClick={() => setShowAddModal(true)} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold flex items-center gap-2 shadow-xl hover:bg-blue-700">
              <Plus size={18} /> 新增項目
            </button>
          )}
        </header>

        {activeTab === 'inventory' && (
          <div className="bg-white rounded-3xl shadow-xl border overflow-hidden">
            <div className="p-6 bg-slate-50 border-b flex items-center gap-4">
              <div className="relative flex-1 max-w-sm text-black">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  type="text" 
                  placeholder="搜尋項目名稱..." 
                  className="w-full pl-12 pr-4 py-4 bg-white border-2 border-slate-100 rounded-2xl font-bold outline-none focus:border-blue-500"
                  value={searchTerm}
                  onChange={e => setSearchTerm(e.target.value)}
                />
              </div>
              <button onClick={fetchFromCloud} className="p-4 text-slate-400 hover:text-blue-600 bg-white border rounded-2xl transition-all"><RefreshCw size={20} /></button>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase border-b">
                  <tr>
                    <th className="px-8 py-5 text-black">項目名稱</th>
                    <th className="px-8 py-5 text-black">現有庫存</th>
                    <th className="px-8 py-5 text-black">警戒水位</th>
                    <th className="px-8 py-5 text-right text-black">管理</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {items.filter(i => i.name.includes(searchTerm)).map(item => (
                    <tr key={item.id} className="hover:bg-slate-50">
                      <td className="px-8 py-6 font-bold text-slate-900 text-lg">{item.name}</td>
                      <td className="px-8 py-6">
                        <span className={`px-4 py-2 rounded-xl text-xs font-black ${item.quantity <= item.minStock ? 'bg-rose-100 text-rose-700' : 'bg-emerald-100 text-emerald-700'}`}>
                          {item.quantity} {item.unit}
                        </span>
                      </td>
                      <td className="px-8 py-6 text-slate-400 font-bold">{item.minStock} {item.unit}</td>
                      <td className="px-8 py-6 text-right">
                        <button onClick={() => deleteItem(item.id)} className="p-3 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded-2xl transition-all">
                          <Trash2 size={22} />
                        </button>
                      </td>
                    </tr>
                  ))}
                  {items.length === 0 && (
                    <tr><td colSpan={4} className="py-20 text-center text-slate-400">目前清冊為空。</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'issuance' && (
          <div className="max-w-xl mx-auto bg-white p-12 rounded-[3rem] shadow-2xl border text-black">
            <div className="flex bg-slate-100 p-2 rounded-2xl mb-10">
              <button onClick={() => setIssuanceMode('OUT')} className={`flex-1 py-4 rounded-xl font-black transition-all ${issuanceMode === 'OUT' ? 'bg-white shadow-lg text-blue-600' : 'text-slate-400'}`}>領用出庫</button>
              <button onClick={() => setIssuanceMode('IN')} className={`flex-1 py-4 rounded-xl font-black transition-all ${issuanceMode === 'IN' ? 'bg-white shadow-lg text-emerald-600' : 'text-slate-400'}`}>補貨入庫</button>
            </div>

            <div className="space-y-8">
              <div>
                <label className="block text-[10px] font-black text-slate-400 mb-3 uppercase tracking-widest">1. 選擇項目</label>
                <select className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black text-black" value={selectedItemId} onChange={e => setSelectedItemId(e.target.value)}>
                  <option value="">-- 請選取項目 --</option>
                  {items.map(i => <option key={i.id} value={i.id}>{i.name} (庫存: {i.quantity})</option>)}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-8">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 mb-3 uppercase tracking-widest">2. 數量</label>
                  <input type="number" className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black text-black" value={inputQty} onChange={e => setInputQty(Number(e.target.value))} />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 mb-3 uppercase tracking-widest">3. {issuanceMode === 'OUT' ? '領用部門' : '來源'}</label>
                  <input type="text" className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black text-black" value={inputPerson} onChange={e => setInputPerson(e.target.value)} />
                </div>
              </div>

              <button onClick={handleTransaction} className={`w-full py-6 rounded-3xl font-black text-white text-xl shadow-2xl transition-all active:scale-95 ${issuanceMode === 'OUT' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-emerald-600 hover:bg-emerald-700'}`}>
                {issuanceMode === 'OUT' ? '確認領用' : '完成補貨'}
              </button>
            </div>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="bg-white p-10 rounded-[2.5rem] shadow-xl border">
              <h4 className="text-slate-400 text-xs font-bold uppercase mb-4 tracking-widest">庫存總項目</h4>
              <p className="text-6xl font-black text-black">{items.length}</p>
            </div>
            <div className="bg-white p-10 rounded-[2.5rem] shadow-xl border">
              <h4 className="text-rose-500 text-xs font-bold uppercase mb-4 tracking-widest">低庫存警示</h4>
              <p className="text-6xl font-black text-rose-600">{items.filter(i => i.quantity <= i.minStock).length}</p>
            </div>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-xl border overflow-hidden">
             <table className="w-full text-left text-black">
              <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase border-b">
                <tr><th className="px-8 py-5 text-black">時間</th><th className="px-8 py-5 text-black">項目</th><th className="px-8 py-5 text-black">類別</th><th className="px-8 py-5 text-black">領用單位</th><th className="px-8 py-5 text-right text-black">單據</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {logs.map(log => (
                  <tr key={log.id} className="hover:bg-slate-50">
                    <td className="px-8 py-5 text-xs text-slate-400 font-mono">{new Date(log.timestamp).toLocaleString()}</td>
                    <td className="px-8 py-5 font-bold text-slate-900">{log.itemName} (x{log.quantity})</td>
                    <td className="px-8 py-5 text-xs font-black uppercase">
                      {log.type === 'OUT' ? <span className="text-blue-600">領用</span> : <span className="text-emerald-600">補貨</span>}
                    </td>
                    <td className="px-8 py-5 text-slate-500 font-bold">{log.person}</td>
                    <td className="px-8 py-5 text-right">
                      {log.type === 'OUT' && <button onClick={() => {setLastTransaction(log); setShowPrintModal(true);}} className="p-3 text-blue-600 hover:bg-blue-50 rounded-2xl"><Printer size={18} /></button>}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </main>

      {/* 列印預覽 (僅在預覽時顯示) */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-slate-900/95 z-[100] flex flex-col items-center justify-start p-6 overflow-y-auto no-print">
          <div className="w-full max-w-5xl bg-slate-100 rounded-[3rem] relative p-6 flex flex-col shadow-2xl">
            <div className="flex justify-between items-center mb-6 bg-white p-6 rounded-[2rem] shadow-sm text-black">
              <span className="font-black flex items-center gap-3 text-blue-600 text-lg uppercase tracking-wider"><Printer /> 單據預覽 (標楷體)</span>
              <div className="flex gap-4">
                <button onClick={() => window.print()} className="bg-blue-600 text-white px-12 py-4 rounded-2xl font-black shadow-xl hover:bg-blue-700 text-xl">列印單據</button>
                <button onClick={() => setShowPrintModal(false)} className="p-4 text-slate-400 hover:text-black bg-slate-100 rounded-full"><X size={24}/></button>
              </div>
            </div>
            <div className="flex justify-center p-4">
               <div className="bg-white shadow-2xl border">
                 <PrintableForm transaction={lastTransaction} />
               </div>
            </div>
          </div>
        </div>
      )}

      {/* 新增項目彈窗 */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-50 flex items-center justify-center p-4 no-print">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden text-black">
            <div className="p-8 border-b flex justify-between items-center">
              <h3 className="font-black text-2xl">新增工安項目</h3>
              <button onClick={() => setShowAddModal(false)}><X /></button>
            </div>
            <div className="p-10 space-y-6">
              <div><label className="block text-[10px] font-black text-slate-400 mb-1">名稱</label><input type="text" className="w-full p-5 border-2 rounded-2xl font-black bg-white text-black" value={newForm.name} onChange={e => setNewForm({...newForm, name: e.target.value})} /></div>
              <div className="grid grid-cols-2 gap-4 text-black">
                <div><label className="block text-[10px] font-black text-slate-400 mb-1">單位</label><input type="text" className="w-full p-5 border-2 rounded-2xl font-black bg-white" value={newForm.unit} onChange={e => setNewForm({...newForm, unit: e.target.value})} /></div>
                <div><label className="block text-[10px] font-black text-slate-400 mb-1">警戒水位</label><input type="number" className="w-full p-5 border-2 rounded-2xl font-black bg-white" value={newForm.minStock} onChange={e => setNewForm({...newForm, minStock: Number(e.target.value)})} /></div>
              </div>
              <button onClick={handleAddItem} className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black text-xl hover:bg-black">存檔並同步</button>
            </div>
          </div>
        </div>
      )}

      {/* 實際列印渲染區 */}
      <div className="hidden print:block absolute top-0 left-0 w-full">
         {lastTransaction && <PrintableForm transaction={lastTransaction} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  RefreshCw,
  Search,
  X,
  Printer,
  Cloud,
  Save
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType } from './types';

// 配置：您的 Google Apps Script URL
const FIXED_URL = "https://script.google.com/macros/s/AKfycbyVn1L9L98Oq0C29M42pS18f7fX_6m85h3q0UqKk9qW9q9q9q9q9q9q9q9q9q9q9q/exec"; 

const STORAGE_KEY_ITEMS = 'safeman_v4_items';
const STORAGE_KEY_LOGS = 'safeman_v4_logs';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'issuance' | 'history'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // 領用登記狀態
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<number>(1);
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');

  // 1. 初始載入：僅從本地 LocalStorage 讀取，確保「離線版」絕對可用
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) {
      setItems(JSON.parse(savedItems));
    }
    if (savedLogs) {
      setLogs(JSON.parse(savedLogs));
    }
  }, []);

  // 2. 本地保存函數：每次狀態變動都強制寫入硬碟
  const saveLocally = (newItems: InventoryItem[], newLogs: Transaction[]) => {
    localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(newItems));
    localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(newLogs));
  };

  // 3. 【核心修正】刪除功能：離線優先，不等待同步
  const deleteItem = (id: string) => {
    // 找到要刪除的項目名稱做為提示
    const target = items.find(i => i.id === id);
    if (!target) return;

    if (window.confirm(`確定要刪除「${target.name}」嗎？\n此操作將立即從本地清冊移除。`)) {
      const updatedItems = items.filter(i => i.id !== id);
      setItems(updatedItems);
      saveLocally(updatedItems, logs);
      // 提醒用戶手動同步
      console.log("項目已從本地刪除，請手動點擊雲端同步。");
    }
  };

  // 4. 【核心修正】領用警示：強制數值比對
  const handleTransaction = () => {
    if (!selectedItemId) return alert('錯誤：請先選擇一個耗材項目！');

    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    const qty = Number(inputQty);
    const currentStock = Number(targetItem.quantity);

    // 庫存檢查：如果是領用出庫，且領用量 > 現有庫存
    if (issuanceMode === 'OUT' && qty > currentStock) {
      alert(`⚠️ 庫存不足警告！\n\n項目：${targetItem.name}\n現有庫存：${currentStock}\n您要領取：${qty}\n\n無法完成領用。請先進行補貨。`);
      return; // 強制中斷
    }

    if (qty <= 0) return alert('數量必須大於 0');

    const updatedItems = items.map(i => {
      if (i.id === selectedItemId) {
        return { 
          ...i, 
          quantity: issuanceMode === 'IN' ? i.quantity + qty : i.quantity - qty,
          lastUpdated: Date.now()
        };
      }
      return i;
    });

    const newLog: Transaction = {
      id: crypto.randomUUID(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: qty,
      person: inputPerson || (issuanceMode === 'IN' ? '系統補貨' : '領用人員'),
      reason: inputReason,
      timestamp: Date.now()
    };

    const updatedLogs = [newLog, ...logs];
    setItems(updatedItems);
    setLogs(updatedLogs);
    setLastTransaction(newLog);
    saveLocally(updatedItems, updatedLogs);

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      alert('庫存已成功更新！');
    }

    // 重置表單
    setSelectedItemId('');
    setInputQty(1);
    setInputPerson('');
    setInputReason('');
  };

  // 5. 雲端同步：改為手動按鈕觸發
  const syncToCloud = async () => {
    if (!FIXED_URL) return alert('未設定雲端 URL');
    setIsSyncing(true);
    try {
      // POST 資料到雲端
      await fetch(FIXED_URL, {
        method: 'POST',
        mode: 'no-cors', 
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items, logs, lastUpdate: Date.now() })
      });
      alert('✅ 雲端同步成功！');
    } catch (err) {
      alert('❌ 同步失敗，請檢查網路或 Google Script 權限。');
    } finally {
      setIsSyncing(false);
    }
  };

  // 6. 從雲端抓取：手動按鈕觸發
  const loadFromCloud = async () => {
    if (!FIXED_URL) return alert('未設定雲端 URL');
    if (!window.confirm('警告：從雲端載入將覆蓋目前本地的所有資料，確定繼續？')) return;

    setIsSyncing(true);
    try {
      const response = await fetch(FIXED_URL);
      const data = await response.json();
      if (data.items) {
        setItems(data.items);
        setLogs(data.logs || []);
        saveLocally(data.items, data.logs || []);
        alert('✅ 資料已從雲端更新至本地！');
      }
    } catch (err) {
      alert('❌ 無法連線至雲端。');
    } finally {
      setIsSyncing(false);
    }
  };

  const handleAddItem = () => {
    if (!newForm.name) return alert('請輸入項目名稱');
    const newItem: InventoryItem = {
      ...newForm,
      id: crypto.randomUUID(),
      description: '',
      lastUpdated: Date.now()
    };
    const updatedItems = [...items, newItem];
    setItems(updatedItems);
    saveLocally(updatedItems, logs);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, unit: '個', minStock: 5, quantity: 0 });
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    unit: '個',
    minStock: 5,
    quantity: 0
  });

  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const now = new Date(transaction.timestamp);
    const minguoYear = now.getFullYear() - 1911;

    return (
      <div className="bg-white p-10 w-[210mm] mx-auto text-black print:p-0" id="print-area">
        <style>{`
          @media print { 
             body { background: white !important; }
             .no-print { display: none !important; }
             #print-area { position: absolute; left: 0; top: 0; width: 100%; }
             /* 強制所有文字黑色 */
             * { color: #000000 !important; border-color: #000000 !important; }
          }
          .kai { font-family: "標楷體", "DFKai-SB", serif; }
          .taipower-table { width: 100%; border-collapse: collapse; border: 2px solid black; }
          .taipower-table th, .taipower-table td { border: 1.5px solid black; padding: 12px; text-align: center; font-size: 14pt; }
        `}</style>

        <div className="kai text-black">
          <h1 className="text-center text-3xl font-bold mb-6">台灣電力公司電力修護處南部分處</h1>

          <div className="flex justify-center gap-10 mb-8 text-xl">
            <div className="flex items-center gap-2"><div className="w-6 h-6 border-2 border-black"></div> 安全衛生設備借用單</div>
            <div className="flex items-center gap-2"><div className="w-6 h-6 border-2 border-black flex items-center justify-center font-bold">V</div> 安全衛生類消耗品領用單</div>
          </div>

          <div className="flex justify-between mb-4 font-bold text-lg px-2">
            <p>部門：<span className="underline underline-offset-4 px-10">{transaction.person}</span></p>
            <p>日期：{minguoYear} 年 {now.getMonth() + 1} 月 {now.getDate()} 日</p>
          </div>

          <table className="taipower-table">
            <thead>
              <tr className="bg-gray-50">
                <th className="w-1/3">名　　稱</th>
                <th className="w-1/4">規 範 ( 序 號 )</th>
                <th className="w-20">單位</th>
                <th className="w-20">數量</th>
                <th>備　　註</th>
              </tr>
            </thead>
            <tbody>
              <tr className="h-24">
                <td className="font-bold text-2xl">{transaction.itemName}</td>
                <td className="text-sm">--</td>
                <td>{targetItem?.unit || '個'}</td>
                <td className="font-bold text-3xl">{transaction.quantity}</td>
                <td className="text-sm text-left align-top">{transaction.reason}</td>
              </tr>
              {[...Array(12)].map((_, i) => (
                <tr key={i} className="h-10">
                  <td></td><td></td><td></td><td></td><td></td>
                </tr>
              ))}
            </tbody>
          </table>

          <div className="mt-12 grid grid-cols-2 gap-12 text-lg">
            <div>
              <p className="mb-6 font-bold">申請部門簽章：________________</p>
              <div className="flex justify-between text-base px-2">
                <span>經辦：______</span><span>課長：______</span><span>經理：______</span>
              </div>
            </div>
            <div>
              <p className="mb-6 font-bold">經辦部門簽章：________________</p>
              <div className="flex justify-between text-base px-2">
                <span>經辦：______</span><span>課長：______</span><span>經理：______</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-gray-100 text-slate-900 font-sans">
      {/* 側邊導覽 (不列印) */}
      <aside className="no-print w-64 bg-slate-900 text-white p-6 flex flex-col shadow-xl">
        <div className="flex items-center gap-3 mb-10">
          <div className="bg-blue-600 p-2 rounded-lg shadow-lg"><Package size={20} /></div>
          <h1 className="font-bold text-lg tracking-tight">工安管理系統</h1>
        </div>
        <nav className="flex-1 space-y-2">
          {[
            { id: 'inventory', icon: Package, label: '耗材清冊' },
            { id: 'issuance', icon: FileText, label: '領用登記' },
            { id: 'history', icon: History, label: '異動日誌' },
            { id: 'dashboard', icon: LayoutDashboard, label: '儀表板' },
          ].map((tab) => (
            <button 
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}
            >
              <tab.icon size={18} /> {tab.label}
            </button>
          ))}
        </nav>
        <div className="mt-auto pt-6 border-t border-slate-800 space-y-4">
           <button onClick={syncToCloud} className="w-full flex items-center justify-center gap-2 py-2.5 bg-slate-800 border border-slate-700 rounded-xl text-xs font-bold hover:bg-slate-700 transition-all">
             {isSyncing ? <RefreshCw className="animate-spin" size={14}/> : <Save size={14}/>} 雲端同步
           </button>
           <button onClick={loadFromCloud} className="w-full text-slate-500 text-[10px] hover:text-white uppercase font-bold tracking-widest text-center">
             從雲端還原資料
           </button>
        </div>
      </aside>

      {/* 主內容區 (不列印) */}
      <main className="no-print flex-1 p-8 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-3xl font-black text-slate-800">
            {activeTab === 'inventory' ? '耗材清冊管理' : activeTab === 'issuance' ? '領用作業登記' : activeTab === 'history' ? '異動日誌查詢' : '數據儀表板'}
          </h2>
          {activeTab === 'inventory' && (
            <button onClick={() => setShowAddModal(true)} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold flex items-center gap-2 shadow-xl hover:bg-blue-700 active:scale-95 transition-all">
              <Plus size={18} /> 新增項目
            </button>
          )}
        </header>

        {activeTab === 'inventory' && (
          <div className="bg-white rounded-3xl shadow-xl border overflow-hidden">
            <div className="p-6 bg-slate-50 border-b flex items-center gap-4">
              <div className="relative flex-1 max-w-sm">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  type="text" 
                  placeholder="快速搜尋項目..." 
                  className="w-full pl-12 pr-4 py-4 bg-white border-2 border-slate-200 rounded-2xl font-bold outline-none focus:border-blue-500 transition-all"
                  value={searchTerm}
                  onChange={e => setSearchTerm(e.target.value)}
                />
              </div>
              <div className="text-xs text-slate-400 font-bold">總共 {items.length} 項資產</div>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase border-b">
                  <tr>
                    <th className="px-8 py-5">耗材名稱</th>
                    <th className="px-8 py-5">目前庫存</th>
                    <th className="px-8 py-5">警戒量</th>
                    <th className="px-8 py-5 text-right">管理</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {items.filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                    <tr key={item.id} className="hover:bg-slate-50 transition-colors group">
                      <td className="px-8 py-6">
                        <p className="font-black text-slate-900 text-lg">{item.name}</p>
                        <p className="text-xs font-bold text-slate-400">{item.unit}</p>
                      </td>
                      <td className="px-8 py-6">
                        <span className={`px-4 py-2 rounded-xl text-xs font-black ${item.quantity <= item.minStock ? 'bg-rose-100 text-rose-700' : 'bg-emerald-100 text-emerald-700'}`}>
                          {item.quantity} {item.unit}
                        </span>
                      </td>
                      <td className="px-8 py-6 font-bold text-slate-400">{item.minStock} {item.unit}</td>
                      <td className="px-8 py-6 text-right">
                        <button 
                          onClick={() => deleteItem(item.id)} 
                          className="p-3 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded-2xl transition-all"
                          title="刪除此項目"
                        >
                          <Trash2 size={22} />
                        </button>
                      </td>
                    </tr>
                  ))}
                  {items.length === 0 && (
                    <tr><td colSpan={4} className="py-24 text-center text-slate-400 italic">目前沒有任何資產項目，請點擊上方「新增項目」。</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'issuance' && (
          <div className="max-w-xl mx-auto bg-white p-12 rounded-[3rem] shadow-2xl border text-black">
            <div className="flex bg-slate-100 p-2 rounded-2xl mb-10">
              <button onClick={() => setIssuanceMode('OUT')} className={`flex-1 py-4 rounded-xl font-black transition-all ${issuanceMode === 'OUT' ? 'bg-white shadow-lg text-blue-600' : 'text-slate-400'}`}>領用出庫</button>
              <button onClick={() => setIssuanceMode('IN')} className={`flex-1 py-4 rounded-xl font-black transition-all ${issuanceMode === 'IN' ? 'bg-white shadow-lg text-emerald-600' : 'text-slate-400'}`}>補貨入庫</button>
            </div>

            <div className="space-y-8">
              <div>
                <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">1. 選取耗材</label>
                <select className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-200 rounded-2xl font-black text-black text-lg outline-none focus:border-blue-500" value={selectedItemId} onChange={e => setSelectedItemId(e.target.value)}>
                  <option value="">-- 請點擊選取 --</option>
                  {items.map(i => <option key={i.id} value={i.id}>{i.name} (庫存剩餘：{i.quantity})</option>)}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-8">
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">2. 數量</label>
                  <input type="number" className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-200 rounded-2xl font-black text-black text-lg" value={inputQty} onChange={e => setInputQty(Number(e.target.value))} />
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">3. {issuanceMode === 'OUT' ? '領用部門' : '來源'}</label>
                  <input type="text" placeholder="例：維修組" className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-200 rounded-2xl font-black text-black text-lg" value={inputPerson} onChange={e => setInputPerson(e.target.value)} />
                </div>
              </div>

              <div>
                <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">4. 備註 (工程案號/用途)</label>
                <textarea rows={2} className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-200 rounded-2xl font-black text-black text-lg" value={inputReason} onChange={e => setInputReason(e.target.value)}></textarea>
              </div>

              <button onClick={handleTransaction} className={`w-full py-6 rounded-3xl font-black text-white text-xl shadow-2xl transition-all active:scale-95 ${issuanceMode === 'OUT' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-emerald-600 hover:bg-emerald-700'}`}>
                {issuanceMode === 'OUT' ? '確認領用並生成單據' : '完成庫存補貨'}
              </button>
            </div>
          </div>
        )}

        {/* 簡單的儀表板 */}
        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            <div className="bg-white p-10 rounded-[2.5rem] shadow-xl border">
              <p className="text-slate-400 text-xs font-bold uppercase mb-4 tracking-widest">庫存總項目</p>
              <p className="text-6xl font-black">{items.length}</p>
            </div>
            <div className="bg-white p-10 rounded-[2.5rem] shadow-xl border">
              <p className="text-rose-500 text-xs font-bold uppercase mb-4 tracking-widest">低庫存項目</p>
              <p className="text-6xl font-black text-rose-600">{items.filter(i => i.quantity <= i.minStock).length}</p>
            </div>
          </div>
        )}

        {/* 歷史記錄 */}
        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-xl border overflow-hidden">
             <table className="w-full text-left text-black">
              <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase border-b">
                <tr><th className="px-8 py-5">異動時間</th><th className="px-8 py-5">耗材項目</th><th className="px-8 py-5">類別</th><th className="px-8 py-5">部門/人</th><th className="px-8 py-5 text-right">操作</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {logs.map(log => (
                  <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-8 py-5 text-xs text-slate-400 font-mono">{new Date(log.timestamp).toLocaleString()}</td>
                    <td className="px-8 py-5 font-bold text-slate-900">{log.itemName} <span className="text-blue-600 ml-2">x{log.quantity}</span></td>
                    <td className="px-8 py-5">
                      {log.type === 'OUT' ? <span className="text-xs font-black text-blue-600 bg-blue-50 px-3 py-1 rounded-lg">領用</span> : <span className="text-xs font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-lg">補貨</span>}
                    </td>
                    <td className="px-8 py-5 text-slate-500 font-bold">{log.person}</td>
                    <td className="px-8 py-5 text-right">
                      {log.type === 'OUT' && <button onClick={() => {setLastTransaction(log); setShowPrintModal(true);}} className="p-3 text-blue-600 hover:bg-blue-50 rounded-2xl transition-all"><Printer size={18}/></button>}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </main>

      {/* 列印彈窗 */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-slate-900/95 z-[100] flex flex-col items-center justify-start p-6 overflow-y-auto no-print">
          <div className="w-full max-w-5xl bg-white rounded-[3rem] relative p-8 flex flex-col shadow-2xl">
            <div className="flex justify-between items-center mb-8 pb-6 border-b">
              <span className="font-black flex items-center gap-3 text-blue-600 text-2xl uppercase tracking-widest"><Printer size={32}/> 台電標楷體單據預覽</span>
              <div className="flex gap-4">
                <button onClick={() => window.print()} className="bg-blue-600 text-white px-16 py-5 rounded-2xl font-black shadow-xl hover:bg-blue-700 active:scale-95 transition-all text-2xl">列印單據</button>
                <button onClick={() => setShowPrintModal(false)} className="p-4 text-slate-400 hover:text-black bg-slate-100 rounded-full transition-all"><X size={32}/></button>
              </div>
            </div>
            <div className="flex justify-center bg-gray-200 p-8 rounded-2xl">
               <div className="bg-white shadow-2xl overflow-hidden">
                 <PrintableForm transaction={lastTransaction} />
               </div>
            </div>
          </div>
        </div>
      )}

      {/* 新增項目彈窗 */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-50 flex items-center justify-center p-4 no-print">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden text-black scale-up">
            <div className="p-8 border-b flex justify-between items-center bg-slate-50">
              <h3 className="font-black text-2xl">新增工安耗材</h3>
              <button onClick={() => setShowAddModal(false)} className="text-slate-400 hover:text-black"><X/></button>
            </div>
            <div className="p-10 space-y-6">
              <div><label className="block text-xs font-black text-slate-400 mb-1">耗材名稱</label><input type="text" className="w-full p-5 border-2 rounded-2xl font-black bg-white text-black outline-none focus:border-blue-500" value={newForm.name} onChange={e => setNewForm({...newForm, name: e.target.value})} /></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="block text-xs font-black text-slate-400 mb-1">單位 (如：個/雙)</label><input type="text" className="w-full p-5 border-2 rounded-2xl font-black bg-white" value={newForm.unit} onChange={e => setNewForm({...newForm, unit: e.target.value})} /></div>
                <div><label className="block text-xs font-black text-slate-400 mb-1">警戒水位</label><input type="number" className="w-full p-5 border-2 rounded-2xl font-black bg-white" value={newForm.minStock} onChange={e => setNewForm({...newForm, minStock: Number(e.target.value)})} /></div>
              </div>
              <button onClick={handleAddItem} className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black text-xl hover:bg-black shadow-xl transition-all">完成新增並存檔</button>
            </div>
          </div>
        </div>
      )}

      {/* 實際列印渲染區 (僅列印時顯示) */}
      <div className="hidden print:block absolute top-0 left-0 w-full">
         {lastTransaction && <PrintableForm transaction={lastTransaction} />}
      </div>

      <style>{`
        .scale-up { animation: scaleUp 0.2s ease-out; }
        @keyframes scaleUp { from { opacity: 0; transform: scale(0.95); } to { opacity: 1; transform: scale(1); } }
      `}</style>
    </div>
  );
};

