const STORAGE_KEY_ITEMS = 'safeman_v4_items';
const STORAGE_KEY_LOGS = 'safeman_v4_logs';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'issuance' | 'history'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // 領用登記狀態
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<number>(1);
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');

  // [1] 初始化：僅載入本地資料
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) {
      try {
        setItems(JSON.parse(savedItems));
      } catch (e) {
        console.error("解析本地資料失敗", e);
      }
    }
    if (savedLogs) {
      try {
        setLogs(JSON.parse(savedLogs));
      } catch (e) {
        console.error("解析日誌失敗", e);
      }
    }
  }, []);

  // [2] 核心機制：監聽狀態變化並立即寫入硬碟 (LocalStorage)
  // 這樣無論是新增、刪除、還是領用，只要狀態一變，硬碟資料就會同步
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
  }, [items]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
  }, [logs]);

  // [3] 刪除功能：使用函數式更新 (Functional Update)
  const deleteItem = (id: string) => {
    // 先確認 ID 是否存在於目前的清單中
    const itemToDelete = items.find(i => i.id === id);
    if (!itemToDelete) {
      console.warn("找不到要刪除的項目 ID:", id);
      return;
    }

    if (window.confirm(`【確認刪除】\n項目名稱：${itemToDelete.name}\n\n注意：此動作將立即從清冊移除且無法復原。`)) {
      // 使用 prevItems 確保操作的是最新狀態
      setItems(prevItems => {
        const filtered = prevItems.filter(item => item.id !== id);
        console.log("刪除成功，剩餘項目數量:", filtered.length);
        return filtered;
      });
