        return { 
          ...i, 
          quantity: issuanceMode === 'IN' ? i.quantity + qty : i.quantity - qty,
          lastUpdated: Date.now()
        };
      }
      return i;
    }));

    // 2. 建立紀錄
    const newLog: Transaction = {
      id: crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).substring(2),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: qty,
      person: inputPerson || (issuanceMode === 'IN' ? '入庫' : '領用人員'),
      reason: inputReason,
      timestamp: Date.now()
    };

    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      alert('庫存更新成功');
    }

    setSelectedItemId('');
    setInputQty(1);
