  const [isSyncing, setIsSyncing] = useState(false);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // 領用登記狀態
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<number>(1);
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');

  // [1] 初始化載入：只執行一次
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);

    if (savedItems) {
      try {
        const parsed = JSON.parse(savedItems);
        if (Array.isArray(parsed)) setItems(parsed);
      } catch (e) { console.error("Items parse error", e); }
    }

    if (savedLogs) {
      try {
        const parsed = JSON.parse(savedLogs);
        if (Array.isArray(parsed)) setLogs(parsed);
      } catch (e) { console.error("Logs parse error", e); }
    }

    setIsLoaded(true); // 標記載入完成，現在可以開始儲存了
    console.log("資料載入完成");
  }, []);

  // [2] 自動儲存：僅在 isLoaded 為 true 時允許寫入硬碟
  useEffect(() => {
    if (!isLoaded) return; 
    localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
    console.log("項目清單已更新至本地硬碟");
  }, [items, isLoaded]);

  useEffect(() => {
    if (!isLoaded) return;
    localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
  }, [logs, isLoaded]);

  // [3] 生成穩定 ID 的函數
  const generateId = () => Date.now().toString(36) + Math.random().toString(36).substring(2);

  // [4] 【修正】刪除功能：極簡且強大的邏輯
  const deleteItem = (id: string) => {
    const target = items.find(i => i.id === id);
    if (!target) return;

    if (window.confirm(`確定要徹底刪除「${target.name}」嗎？`)) {
      // 核心：使用過濾器產生新陣列並更新狀態
      setItems(currentItems => {
        const newItems = currentItems.filter(item => item.id !== id);
        console.log(`刪除完成。原數量: ${currentItems.length}, 現數量: ${newItems.length}`);
        return newItems;
      });
    }
  };

  // [5] 【修正】新增項目：確保 ID 格式正確
  const handleAddItem = () => {
    if (!newForm.name.trim()) return alert('請輸入名稱');

    const newItem: InventoryItem = {
      id: generateId(), // 使用穩定 ID
      name: newForm.name,
      category: newForm.category,
      unit: newForm.unit,
      quantity: Number(newForm.quantity),
      minStock: Number(newForm.minStock),
      description: '',
      lastUpdated: Date.now()
    };

    setItems(prev => [...prev, newItem]);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, unit: '個', minStock: 5, quantity: 0 });
    alert('項目已成功新增！');
  };

  // [6] 【修正】領用登記：庫存預檢與狀態更新
  const handleTransaction = () => {
    if (!selectedItemId) return alert('請先選取耗材項目');

    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    const qty = Number(inputQty);
    const currentStock = Number(targetItem.quantity);

    // 嚴格庫存檢查
    if (issuanceMode === 'OUT' && qty > currentStock) {
      alert(`⚠️ 庫存不足！\n\n項目：${targetItem.name}\n現有庫存：${currentStock}\n欲領用數：${qty}\n\n請調整數量或先補貨。`);
      return;
    }

    if (qty <= 0) return alert('請輸入正確數量');

    // 更新庫存狀態
    setItems(prev => prev.map(item => {
      if (item.id === selectedItemId) {
        const newQty = issuanceMode === 'IN' ? item.quantity + qty : item.quantity - qty;
        return { ...item, quantity: newQty, lastUpdated: Date.now() };
      }
      return item;
    }));

    // 建立日誌
    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: qty,
      person: inputPerson || (issuanceMode === 'IN' ? '系統入庫' : '領用人'),
      reason: inputReason,
      timestamp: Date.now()
    };

    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      alert('庫存補貨完成！');
    }

    // 重置
    setSelectedItemId('');
    setInputQty(1);
    setInputPerson('');
    setInputReason('');
  };

  // 雲端同步 (手動觸發)
  const syncToCloud = async () => {
    if (!FIXED_URL) return alert('未設定雲端 URL');
    setIsSyncing(true);
    try {
      await fetch(FIXED_URL, {
        method: 'POST',
        mode: 'no-cors', 
        body: JSON.stringify({ items, logs, lastUpdate: Date.now() })
      });
      alert('✅ 雲端同步成功 (本地資料已備份)');
    } catch (err) {
      alert('❌ 同步失敗，請檢查網路');
    } finally {
      setIsSyncing(false);
    }
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    unit: '個',
    minStock: 5,
    quantity: 0
  });

  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const now = new Date(transaction.timestamp);
    const minguoYear = now.getFullYear() - 1911;

    return (
      <div className="bg-white p-10 w-[210mm] mx-auto text-black print:p-0" id="print-area">
        <style>{`
          @media print { 
             body { background: white !important; }
             .no-print { display: none !important; }
             #print-area { position: absolute; left: 0; top: 0; width: 100%; color: black !important; }
             * { color: #000000 !important; border-color: #000000 !important; }
          }
          .kai { font-family: "標楷體", "DFKai-SB", serif; }
          .t-table { width: 100%; border-collapse: collapse; border: 2px solid black; }
          .t-table th, .t-table td { border: 1.5px solid black; padding: 12px; text-align: center; font-size: 14pt; }
        `}</style>
        <div className="kai text-black">
          <h1 className="text-center text-3xl font-bold mb-6">台灣電力公司電力修護處南部分處</h1>
          <div className="flex justify-center gap-10 mb-8 text-xl">
            <div className="flex items-center gap-2"><div className="w-6 h-6 border-2 border-black"></div> 安全衛生設備借用單</div>
            <div className="flex items-center gap-2"><div className="w-6 h-6 border-2 border-black flex items-center justify-center font-bold">V</div> 安全衛生類消耗品領用單</div>
          </div>
          <div className="flex justify-between mb-4 font-bold text-lg px-2">
            <p>部門：<span className="underline underline-offset-4 px-10">{transaction.person}</span></p>
            <p>日期：{minguoYear} 年 {now.getMonth() + 1} 月 {now.getDate()} 日</p>
          </div>
          <table className="t-table">
            <thead>
              <tr className="bg-gray-100">
                <th className="w-1/3">名　　稱</th>
                <th className="w-1/4">規 範 ( 序 號 )</th>
                <th className="w-20">單位</th>
                <th className="w-20">數量</th>
                <th>備　　註</th>
              </tr>
            </thead>
            <tbody>
              <tr className="h-28">
                <td className="font-bold text-2xl">{transaction.itemName}</td>
                <td>--</td>
                <td>{targetItem?.unit || '個'}</td>
                <td className="font-bold text-3xl">{transaction.quantity}</td>
                <td className="text-left align-top">{transaction.reason}</td>
              </tr>
              {[...Array(12)].map((_, i) => (
                <tr key={i} className="h-10"><td></td><td></td><td></td><td></td><td></td></tr>
              ))}
            </tbody>
          </table>
          <div className="mt-12 grid grid-cols-2 gap-12 text-lg">
            <div><p className="mb-6 font-bold">申請部門簽章：________________</p></div>
            <div><p className="mb-6 font-bold">經辦部門簽章：________________</p></div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900 font-sans">
      {/* 側邊導航 */}
      <aside className="no-print w-64 bg-slate-900 text-white p-6 flex flex-col shadow-2xl shrink-0">
        <div className="flex items-center gap-3 mb-10">
          <div className="p-2 bg-blue-600 rounded-lg"><Package size={20} /></div>
          <h1 className="font-black text-lg">工安管理系統</h1>
        </div>
        <nav className="flex-1 space-y-2">
          <button onClick={() => setActiveTab('inventory')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${activeTab === 'inventory' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}>
            <Package size={18} /> 耗材清冊
          </button>
          <button onClick={() => setActiveTab('issuance')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${activeTab === 'issuance' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}>
            <FileText size={18} /> 領用登記
          </button>
          <button onClick={() => setActiveTab('history')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${activeTab === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}>
            <History size={18} /> 異動日誌
          </button>
          <button onClick={() => setActiveTab('dashboard')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${activeTab === 'dashboard' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}>
            <LayoutDashboard size={18} /> 儀表板
          </button>
        </nav>
        <div className="mt-auto pt-6 border-t border-slate-800">
           <button onClick={syncToCloud} className="w-full flex items-center justify-center gap-2 py-3 bg-slate-800 hover:bg-slate-700 rounded-xl text-xs font-bold transition-all border border-slate-700">
             {isSyncing ? <RefreshCw className="animate-spin" size={14}/> : <Cloud size={14}/>} 雲端備份
           </button>
        </div>
      </aside>

      {/* 主畫面 */}
      <main className="no-print flex-1 p-8 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-3xl font-black text-slate-800 uppercase tracking-tight">
            {activeTab === 'inventory' ? '耗材清冊' : activeTab === 'issuance' ? '領用登記' : activeTab === 'history' ? '異動日誌' : '儀表板'}
          </h2>
          {activeTab === 'inventory' && (
            <button onClick={() => setShowAddModal(true)} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold flex items-center gap-2 shadow-xl hover:bg-blue-700 active:scale-95 transition-all">
              <Plus size={18} /> 新增項目
            </button>
          )}
        </header>

        {activeTab === 'inventory' && (
          <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden">
            <div className="p-6 bg-slate-50 border-b flex items-center gap-4">
              <div className="relative flex-1 max-w-sm">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  type="text" placeholder="搜尋耗材名稱..." 
                  className="w-full pl-12 pr-4 py-4 bg-white border-2 border-slate-100 rounded-2xl font-bold outline-none focus:border-blue-500 transition-all text-black"
                  value={searchTerm} onChange={e => setSearchTerm(e.target.value)}
                />
              </div>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase tracking-widest border-b">
                  <tr>
                    <th className="px-8 py-5">耗材名稱</th>
                    <th className="px-8 py-5 text-center">庫存數量</th>
                    <th className="px-8 py-5 text-center">警戒水位</th>
                    <th className="px-8 py-5 text-right">操作</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {items.filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                    <tr key={item.id} className="hover:bg-slate-50 transition-colors group">
                      <td className="px-8 py-6">
                        <p className="font-black text-slate-900 text-lg">{item.name}</p>
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-tighter">{item.unit}</p>
                      </td>
                      <td className="px-8 py-6 text-center">
                        <span className={`px-5 py-2 rounded-xl text-xs font-black ${item.quantity <= item.minStock ? 'bg-rose-100 text-rose-600' : 'bg-emerald-100 text-emerald-600'}`}>
                          {item.quantity} {item.unit}
                        </span>
                      </td>
                      <td className="px-8 py-6 text-center font-bold text-slate-400">{item.minStock}</td>
                      <td className="px-8 py-6 text-right">
                        <button 
                          onClick={() => deleteItem(item.id)} 
                          className="p-3 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded-2xl transition-all"
                        >
                          <Trash2 size={22} />
                        </button>
                      </td>
                    </tr>
                  ))}
                  {items.length === 0 && (
                    <tr><td colSpan={4} className="py-24 text-center text-slate-400 italic font-medium">目前清冊為空，請點擊右上方「新增項目」。</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'issuance' && (
          <div className="max-w-xl mx-auto bg-white p-12 rounded-[3rem] shadow-2xl border border-slate-100 text-black">
            <div className="flex bg-slate-100 p-2 rounded-2xl mb-10">
              <button onClick={() => setIssuanceMode('OUT')} className={`flex-1 py-4 rounded-xl font-black transition-all ${issuanceMode === 'OUT' ? 'bg-white shadow-lg text-blue-600' : 'text-slate-400'}`}>領用出庫</button>
              <button onClick={() => setIssuanceMode('IN')} className={`flex-1 py-4 rounded-xl font-black transition-all ${issuanceMode === 'IN' ? 'bg-white shadow-lg text-emerald-600' : 'text-slate-400'}`}>補貨入庫</button>
            </div>
            <div className="space-y-8">
              <div>
                <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">1. 選取項目</label>
                <select className="w-full p-5 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black text-slate-800 text-lg outline-none focus:border-blue-500" value={selectedItemId} onChange={e => setSelectedItemId(e.target.value)}>
                  <option value="">-- 請選擇耗材 --</option>
                  {items.map(i => <option key={i.id} value={i.id}>{i.name} (剩餘: {i.quantity})</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-8">
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">2. 數量</label>
                  <input type="number" className="w-full p-5 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black text-slate-800" value={inputQty} onChange={e => setInputQty(Number(e.target.value))} />
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">3. {issuanceMode === 'OUT' ? '領用人/組別' : '來源'}</label>
                  <input type="text" className="w-full p-5 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black text-slate-800" value={inputPerson} onChange={e => setInputPerson(e.target.value)} />
                </div>
              </div>
              <button onClick={handleTransaction} className={`w-full py-6 rounded-[2rem] font-black text-white text-xl shadow-2xl transition-all active:scale-95 ${issuanceMode === 'OUT' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-emerald-600 hover:bg-emerald-700'}`}>
                {issuanceMode === 'OUT' ? '確認領用' : '確認補貨'}
              </button>
            </div>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-xl border overflow-hidden">
             <table className="w-full text-left">
              <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase tracking-widest border-b">
                <tr><th className="px-8 py-5">異動時間</th><th className="px-8 py-5">耗材項目</th><th className="px-8 py-5">類別</th><th className="px-8 py-5">單位/人員</th><th className="px-8 py-5 text-right">單據</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {logs.map(log => (
                  <tr key={log.id} className="hover:bg-slate-50">
                    <td className="px-8 py-5 text-xs text-slate-400 font-mono">{new Date(log.timestamp).toLocaleString()}</td>
                    <td className="px-8 py-5 font-black text-slate-900">{log.itemName} (x{log.quantity})</td>
                    <td className="px-8 py-5">
                      {log.type === 'OUT' ? <span className="text-[10px] font-black text-blue-600 bg-blue-50 px-3 py-1 rounded-full uppercase">領用</span> : <span className="text-[10px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full uppercase">補貨</span>}
                    </td>
                    <td className="px-8 py-5 text-sm font-bold text-slate-600">{log.person}</td>
                    <td className="px-8 py-5 text-right">
                      {log.type === 'OUT' && <button onClick={() => {setLastTransaction(log); setShowPrintModal(true);}} className="p-3 text-blue-600 hover:bg-blue-50 rounded-2xl transition-all"><Printer size={18}/></button>}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="bg-white p-10 rounded-[3rem] shadow-xl border border-slate-100">
              <p className="text-slate-400 text-xs font-black uppercase mb-4 tracking-widest">資產項目總量</p>
              <p className="text-7xl font-black text-slate-900">{items.length}</p>
            </div>
            <div className="bg-white p-10 rounded-[3rem] shadow-xl border border-slate-100">
              <p className="text-rose-500 text-xs font-black uppercase mb-4 tracking-widest">低庫存警戒項目</p>
              <p className="text-7xl font-black text-rose-600">{items.filter(i => i.quantity <= i.minStock).length}</p>
            </div>
          </div>
        )}
      </main>

      {/* 列印預覽彈窗 */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-slate-900/95 z-[100] flex flex-col items-center justify-start p-6 overflow-y-auto no-print">
          <div className="w-full max-w-5xl bg-white rounded-[3rem] relative p-8 flex flex-col shadow-2xl text-black">
            <div className="flex justify-between items-center mb-8 pb-6 border-b border-slate-100">
              <span className="font-black text-blue-600 text-2xl uppercase tracking-widest flex items-center gap-3"><Printer size={32}/> 台電單據預覽</span>
              <div className="flex gap-4">
                <button onClick={() => window.print()} className="bg-blue-600 text-white px-12 py-4 rounded-2xl font-black shadow-xl hover:bg-blue-700 active:scale-95 transition-all text-xl">列印單據</button>
                <button onClick={() => setShowPrintModal(false)} className="p-4 text-slate-400 hover:text-black bg-slate-100 rounded-full"><X size={32}/></button>
              </div>
            </div>
            <div className="flex justify-center bg-slate-100 p-10 rounded-3xl">
               <div className="bg-white shadow-2xl border border-slate-300">
                 <PrintableForm transaction={lastTransaction} />
               </div>
            </div>
          </div>
        </div>
      )}

      {/* 新增項目彈窗 */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-md shadow-2xl overflow-hidden text-black animate-in fade-in zoom-in duration-200">
            <div className="p-8 border-b flex justify-between items-center bg-slate-50">
              <h3 className="font-black text-2xl tracking-tight">新增耗材清單</h3>
              <button onClick={() => setShowAddModal(false)} className="text-slate-400 hover:text-black"><X/></button>
            </div>
            <div className="p-10 space-y-6">
              <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">耗材名稱</label><input type="text" className="w-full p-5 border-2 border-slate-100 rounded-2xl font-black bg-white text-black outline-none focus:border-blue-500" value={newForm.name} onChange={e => setNewForm({...newForm, name: e.target.value})} /></div>
              <div className="grid grid-cols-2 gap-6">
                <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">單位</label><input type="text" placeholder="如: 雙" className="w-full p-5 border-2 border-slate-100 rounded-2xl font-black bg-white" value={newForm.unit} onChange={e => setNewForm({...newForm, unit: e.target.value})} /></div>
                <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">警戒水位</label><input type="number" className="w-full p-5 border-2 border-slate-100 rounded-2xl font-black bg-white" value={newForm.minStock} onChange={e => setNewForm({...newForm, minStock: Number(e.target.value)})} /></div>
              </div>
              <button onClick={handleAddItem} className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black text-xl hover:bg-black shadow-xl transition-all">儲存至清冊</button>
            </div>
          </div>
        </div>
      )}

      {/* 隱藏的列印區 */}
      <div className="hidden print:block absolute top-0 left-0 w-full">
         {lastTransaction && <PrintableForm transaction={lastTransaction} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  RefreshCw,
  Search,
  X,
  Printer,
  Cloud
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType } from './types';

// 配置：您的 Google Apps Script URL
const FIXED_URL = "https://script.google.com/macros/s/AKfycbyVn1L9L98Oq0C29M42pS18f7fX_6m85h3q0UqKk9qW9q9q9q9q9q9q9q9q9q9q9q/exec"; 

const STORAGE_KEY_ITEMS = 'safeman_v6_items';
const STORAGE_KEY_LOGS = 'safeman_v6_logs';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<number>(1);
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');

  // 初始化載入
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);

    if (savedItems) {
      try {
        const parsed = JSON.parse(savedItems);
        if (Array.isArray(parsed)) setItems(parsed);
      } catch (e) { console.error("Load items error", e); }
    }

    if (savedLogs) {
      try {
        const parsed = JSON.parse(savedLogs);
        if (Array.isArray(parsed)) setLogs(parsed);
      } catch (e) { console.error("Load logs error", e); }
    }

    setIsLoaded(true);
  }, []);

  // 自動存檔
  useEffect(() => {
    if (!isLoaded) return; 
    localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
  }, [items, isLoaded]);

  useEffect(() => {
    if (!isLoaded) return;
    localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
  }, [logs, isLoaded]);

  const generateId = () => `ID-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

  // 【核心修復】刪除函數：直接接收參數，不再從狀態中查找
  const handleDelete = (id: string, name: string) => {
    // 1. 先跳出確認視窗
    const confirmed = window.confirm(`【確認刪除項目】\n\n名稱：${name}\n\n此操作將永久移除該項目且無法復原，確定嗎？`);

    if (confirmed) {
      // 2. 執行過濾並更新狀態
      setItems(prevItems => {
        const filtered = prevItems.filter(item => item.id !== id);
        console.log("Delete success:", id);
        return filtered;
      });
    }
  };

  const handleAddItem = () => {
    if (!newForm.name.trim()) return alert('請輸入名稱');

    const newItem: InventoryItem = {
      id: generateId(),
      name: newForm.name.trim(),
      category: newForm.category,
      unit: newForm.unit || '個',
      quantity: Number(newForm.quantity) || 0,
      minStock: Number(newForm.minStock) || 0,
      description: '',
      lastUpdated: Date.now()
    };

    setItems(prev => [...prev, newItem]);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, unit: '個', minStock: 5, quantity: 0 });
    alert(`「${newItem.name}」已新增成功！`);
  };

  const handleTransaction = () => {
    if (!selectedItemId) return alert('請先選取項目');
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    const qty = Number(inputQty);
    if (issuanceMode === 'OUT' && qty > targetItem.quantity) {
      alert(`⚠️ 庫存不足！\n項目：${targetItem.name}\n剩餘：${targetItem.quantity}`);
      return;
    }

    setItems(prev => prev.map(item => {
      if (item.id === selectedItemId) {
        return { ...item, quantity: issuanceMode === 'IN' ? item.quantity + qty : item.quantity - qty, lastUpdated: Date.now() };
      }
      return item;
    }));

    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: qty,
      person: inputPerson || (issuanceMode === 'IN' ? '入庫' : '領用人員'),
      reason: inputReason,
      timestamp: Date.now()
    };

    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);
    if (issuanceMode === 'OUT') setShowPrintModal(true);
    setSelectedItemId('');
    setInputQty(1);
    setInputPerson('');
    setInputReason('');
  };

  const syncToCloud = async () => {
    setIsSyncing(true);
    try {
      await fetch(FIXED_URL, { method: 'POST', mode: 'no-cors', body: JSON.stringify({ items, logs }) });
      alert('✅ 雲端同步完成');
    } catch (err) {
      alert('❌ 同步失敗');
    } finally {
      setIsSyncing(false);
    }
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    unit: '個',
    minStock: 5,
    quantity: 0
  });

  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const now = new Date(transaction.timestamp);
    const minguoYear = now.getFullYear() - 1911;

    return (
      <div className="bg-white p-10 w-[210mm] mx-auto text-black" id="print-area">
        <style>{`
          @media print { 
            body { background: white !important; }
            .no-print { display: none !important; }
            * { color: #000000 !important; border-color: #000000 !important; }
          }
          .kai { font-family: "標楷體", "DFKai-SB", serif; }
          .t-table { width: 100%; border-collapse: collapse; border: 2px solid black; }
          .t-table th, .t-table td { border: 1.5px solid black; padding: 12px; text-align: center; }
        `}</style>
        <div className="kai text-black">
          <h1 className="text-center text-3xl font-bold mb-6">台灣電力公司電力修護處南部分處</h1>
          <div className="flex justify-center gap-10 mb-8 text-xl text-black">
            <div className="flex items-center gap-2"><div className="w-6 h-6 border-2 border-black"></div> 借用單</div>
            <div className="flex items-center gap-2"><div className="w-6 h-6 border-2 border-black flex items-center justify-center font-bold">V</div> 領用單</div>
          </div>
          <div className="flex justify-between mb-4 font-bold text-lg">
            <p>部門：{transaction.person}</p>
            <p>日期：{minguoYear} 年 {now.getMonth() + 1} 月 {now.getDate()} 日</p>
          </div>
          <table className="t-table">
            <thead><tr><th className="w-1/3">名稱</th><th className="w-1/4">規範</th><th className="w-20">單位</th><th className="w-20">數量</th><th>備註</th></tr></thead>
            <tbody>
              <tr className="h-28">
                <td className="font-bold text-2xl">{transaction.itemName}</td>
                <td>--</td>
                <td>{targetItem?.unit || '個'}</td>
                <td className="font-bold text-3xl">{transaction.quantity}</td>
                <td className="text-left align-top">{transaction.reason}</td>
              </tr>
              {[...Array(10)].map((_, i) => (<tr key={i} className="h-10"><td></td><td></td><td></td><td></td><td></td></tr>))}
            </tbody>
          </table>
          <div className="mt-12 grid grid-cols-2 gap-12 text-lg font-bold text-black">
            <div>申請人簽章：________________</div>
            <div>經辦人簽章：________________</div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-slate-100 text-slate-900">
      {/* 側邊欄 */}
      <aside className="no-print w-64 bg-slate-900 text-white p-6 flex flex-col shrink-0">
        <div className="flex items-center gap-3 mb-10">
          <Package className="text-blue-500" />
          <h1 className="font-black text-lg">工安管理系統</h1>
        </div>
        <nav className="flex-1 space-y-2">
          <button onClick={() => setActiveTab('inventory')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === 'inventory' ? 'bg-blue-600' : 'text-slate-400 hover:bg-slate-800'}`}>
            <Package size={18} /> 耗材清冊
          </button>
          <button onClick={() => setActiveTab('issuance')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === 'issuance' ? 'bg-blue-600' : 'text-slate-400 hover:bg-slate-800'}`}>
            <FileText size={18} /> 領用登記
          </button>
          <button onClick={() => setActiveTab('history')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === 'history' ? 'bg-blue-600' : 'text-slate-400 hover:bg-slate-800'}`}>
            <History size={18} /> 異動日誌
          </button>
          <button onClick={() => setActiveTab('dashboard')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === 'dashboard' ? 'bg-blue-600' : 'text-slate-400 hover:bg-slate-800'}`}>
            <LayoutDashboard size={18} /> 儀表板
          </button>
        </nav>
        <button onClick={syncToCloud} className="mt-auto py-3 bg-slate-800 rounded-xl text-xs font-bold flex items-center justify-center gap-2">
          {isSyncing ? <RefreshCw className="animate-spin" size={14}/> : <Cloud size={14}/>} 雲端備份
        </button>
      </aside>

      {/* 主內容區 */}
      <main className="no-print flex-1 p-8 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-2xl font-black text-slate-800 uppercase">
            {activeTab === 'inventory' ? '耗材清冊' : activeTab === 'issuance' ? '領用登記' : activeTab === 'history' ? '異動日誌' : '儀表板'}
          </h2>
          {activeTab === 'inventory' && (
            <button onClick={() => setShowAddModal(true)} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold shadow-lg hover:bg-blue-700 transition-all flex items-center gap-2">
              <Plus size={18} /> 新增項目
            </button>
          )}
        </header>

        {activeTab === 'inventory' && (
          <div className="bg-white rounded-3xl shadow-sm border overflow-hidden">
            <div className="p-6 bg-slate-50 border-b">
              <div className="relative max-w-sm">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input type="text" placeholder="搜尋項目名稱..." className="w-full pl-12 pr-4 py-3 border-2 rounded-2xl font-bold outline-none focus:border-blue-500" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
              </div>
            </div>
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase tracking-widest border-b">
                <tr><th className="px-8 py-5">耗材名稱</th><th className="px-8 py-5 text-center">數量</th><th className="px-8 py-5 text-center">警戒</th><th className="px-8 py-5 text-right">管理</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-8 py-6 font-black text-slate-900">{item.name}</td>
                    <td className="px-8 py-6 text-center">
                      <span className={`px-4 py-1.5 rounded-full text-xs font-black ${item.quantity <= item.minStock ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>
                        {item.quantity} {item.unit}
                      </span>
                    </td>
                    <td className="px-8 py-6 text-center text-slate-400 font-bold">{item.minStock}</td>
                    <td className="px-8 py-6 text-right">
                      {/* 【修正按鈕】直接呼叫 handleDelete 並傳入參數 */}
                      <button 
                        type="button"
                        onClick={(e) => {
                          e.preventDefault();
                          handleDelete(item.id, item.name);
                        }} 
                        className="p-3 text-red-400 hover:text-red-700 hover:bg-red-50 rounded-2xl transition-all inline-flex items-center justify-center"
                        title="刪除"
                      >
                        <Trash2 size={22} />
                      </button>
                    </td>
                  </tr>
                ))}
                {items.length === 0 && (
                  <tr><td colSpan={4} className="py-24 text-center text-slate-400 italic">目前沒有任何項目。</td></tr>
                )}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'issuance' && (
          <div className="max-w-xl mx-auto bg-white p-12 rounded-[2.5rem] shadow-xl border text-black">
            <div className="flex bg-slate-100 p-2 rounded-2xl mb-10">
              <button onClick={() => setIssuanceMode('OUT')} className={`flex-1 py-4 rounded-xl font-black transition-all ${issuanceMode === 'OUT' ? 'bg-white shadow text-blue-600' : 'text-slate-400'}`}>領用出庫</button>
              <button onClick={() => setIssuanceMode('IN')} className={`flex-1 py-4 rounded-xl font-black transition-all ${issuanceMode === 'IN' ? 'bg-white shadow text-emerald-600' : 'text-slate-400'}`}>補貨入庫</button>
            </div>
            <div className="space-y-8">
              <div>
                <label className="block text-xs font-black text-slate-400 mb-2 uppercase">選取項目</label>
                <select className="w-full p-4 border-2 rounded-2xl font-black bg-slate-50 text-black" value={selectedItemId} onChange={e => setSelectedItemId(e.target.value)}>
                  <option value="">-- 請選擇 --</option>
                  {items.map(i => <option key={i.id} value={i.id}>{i.name} (剩餘: {i.quantity})</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-6">
                <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase">數量</label><input type="number" className="w-full p-4 border-2 rounded-2xl font-black bg-slate-50 text-black" value={inputQty} onChange={e => setInputQty(Number(e.target.value))} /></div>
                <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase">部門/人員</label><input type="text" className="w-full p-4 border-2 rounded-2xl font-black bg-slate-50 text-black" value={inputPerson} onChange={e => setInputPerson(e.target.value)} /></div>
              </div>
              <button onClick={handleTransaction} className={`w-full py-5 rounded-2xl font-black text-white text-xl shadow-xl transition-all ${issuanceMode === 'OUT' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-emerald-600 hover:bg-emerald-700'}`}>
                確認提交
              </button>
            </div>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-sm border overflow-hidden">
             <table className="w-full text-left">
              <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase tracking-widest border-b">
                <tr><th className="px-8 py-5">時間</th><th className="px-8 py-5">項目</th><th className="px-8 py-5">類型</th><th className="px-8 py-5 text-right">單據</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {logs.map(log => (
                  <tr key={log.id} className="hover:bg-slate-50">
                    <td className="px-8 py-5 text-xs text-slate-400 font-mono">{new Date(log.timestamp).toLocaleString()}</td>
                    <td className="px-8 py-5 font-black">{log.itemName} (x{log.quantity})</td>
                    <td className="px-8 py-5">
                      {log.type === 'OUT' ? <span className="text-blue-600 font-black">領用</span> : <span className="text-emerald-600 font-black">補貨</span>}
                    </td>
                    <td className="px-8 py-5 text-right">
                      {log.type === 'OUT' && <button onClick={() => {setLastTransaction(log); setShowPrintModal(true);}} className="p-2 text-blue-600 hover:bg-blue-50 rounded-xl transition-all"><Printer size={18}/></button>}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border text-center">
              <p className="text-slate-400 font-black uppercase text-xs mb-2">耗材總項</p>
              <p className="text-6xl font-black text-slate-900">{items.length}</p>
            </div>
            <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border text-center">
              <p className="text-red-500 font-black uppercase text-xs mb-2">低庫存警戒</p>
              <p className="text-6xl font-black text-red-600">{items.filter(i => i.quantity <= i.minStock).length}</p>
            </div>
          </div>
        )}
      </main>

      {/* 預覽視窗 */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-slate-900/90 z-[100] flex flex-col items-center justify-center p-4 overflow-y-auto no-print text-black">
          <div className="bg-white rounded-[2rem] w-full max-w-5xl p-8 relative shadow-2xl">
            <div className="flex justify-between items-center mb-6 pb-4 border-b">
              <span className="font-black text-xl text-blue-600 flex items-center gap-2"><Printer/> 單據列印預覽</span>
              <div className="flex gap-4">
                <button onClick={() => window.print()} className="bg-blue-600 text-white px-10 py-3 rounded-xl font-black hover:bg-blue-700 shadow-lg">執行列印</button>
                <button onClick={() => setShowPrintModal(false)} className="p-3 bg-slate-100 rounded-full hover:bg-slate-200"><X size={24}/></button>
              </div>
            </div>
            <div className="bg-slate-50 p-6 rounded-2xl overflow-x-auto">
               <PrintableForm transaction={lastTransaction} />
            </div>
          </div>
        </div>
      )}

      {/* 新增視窗 */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/60 z-50 flex items-center justify-center p-4 text-black">
          <div className="bg-white rounded-[2.5rem] w-full max-w-md shadow-2xl overflow-hidden p-8">
            <h3 className="font-black text-2xl mb-8">新增耗材清單</h3>
            <div className="space-y-6">
              <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase">名稱</label><input type="text" className="w-full p-4 border-2 rounded-2xl font-black bg-white text-black" value={newForm.name} onChange={e => setNewForm({...newForm, name: e.target.value})} /></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase">單位</label><input type="text" className="w-full p-4 border-2 rounded-2xl font-black bg-white" value={newForm.unit} onChange={e => setNewForm({...newForm, unit: e.target.value})} /></div>
                <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase">警戒水位</label><input type="number" className="w-full p-4 border-2 rounded-2xl font-black bg-white" value={newForm.minStock} onChange={e => setNewForm({...newForm, minStock: Number(e.target.value)})} /></div>
              </div>
              <button onClick={handleAddItem} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black text-lg hover:bg-black transition-all shadow-xl">儲存項目</button>
              <button onClick={() => setShowAddModal(false)} className="w-full py-3 text-slate-400 font-bold hover:text-black">取消關閉</button>
            </div>
          </div>
        </div>
      )}

      {/* 列印專屬區 */}
      <div className="hidden print:block absolute top-0 left-0 w-full">
         {lastTransaction && <PrintableForm transaction={lastTransaction} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  RefreshCw,
  Search,
  X,
  Printer,
  Cloud,
  AlertTriangle
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType } from './types';

const FIXED_URL = "https://script.google.com/macros/s/AKfycbyVn1L9L98Oq0C29M42pS18f7fX_6m85h3q0UqKk9qW9q9q9q9q9q9q9q9q9q9q9q/exec"; 

const STORAGE_KEY_ITEMS = 'safeman_v7_items';
const STORAGE_KEY_LOGS = 'safeman_v7_logs';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);

  // 【新狀態】刪除確認模態視窗
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<number>(1);
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');

  // 初始化
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  // 存檔
  useEffect(() => {
    if (isLoaded) localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
  }, [items, isLoaded]);

  useEffect(() => {
    if (isLoaded) localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
  }, [logs, isLoaded]);

  const generateId = () => `ID-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

  // 【核心功能】執行刪除
  const confirmDelete = () => {
    if (!deleteTarget) return;
    const targetId = deleteTarget.id;
    setItems(prev => prev.filter(item => item.id !== targetId));
    setDeleteTarget(null); // 關閉視窗
  };

  const handleAddItem = () => {
    if (!newForm.name.trim()) return alert('請輸入名稱');
    const newItem: InventoryItem = {
      id: generateId(),
      name: newForm.name.trim(),
      category: newForm.category,
      unit: newForm.unit || '個',
      quantity: Number(newForm.quantity) || 0,
      minStock: Number(newForm.minStock) || 0,
      description: '',
      lastUpdated: Date.now()
    };
    setItems(prev => [...prev, newItem]);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, unit: '個', minStock: 5, quantity: 0 });
  };

  const handleTransaction = () => {
    if (!selectedItemId) return alert('請選取項目');
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;
    const qty = Number(inputQty);
    if (issuanceMode === 'OUT' && qty > targetItem.quantity) return alert('庫存不足');

    setItems(prev => prev.map(item => item.id === selectedItemId ? { ...item, quantity: issuanceMode === 'IN' ? item.quantity + qty : item.quantity - qty, lastUpdated: Date.now() } : item));
    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: qty,
      person: inputPerson || '未填寫',
      reason: inputReason,
      timestamp: Date.now()
    };
    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);
    if (issuanceMode === 'OUT') setShowPrintModal(true);
    setSelectedItemId(''); setInputQty(1); setInputPerson(''); setInputReason('');
  };

  const syncToCloud = async () => {
    setIsSyncing(true);
    try {
      await fetch(FIXED_URL, { method: 'POST', mode: 'no-cors', body: JSON.stringify({ items, logs }) });
      alert('同步完成');
    } catch (err) { alert('同步失敗'); } finally { setIsSyncing(false); }
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    unit: '個',
    minStock: 5,
    quantity: 0
  });

  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const now = new Date(transaction.timestamp);
    return (
      <div className="bg-white p-10 w-[210mm] mx-auto text-black border-2 border-black" id="print-area">
        <style>{`@media print { .no-print { display: none !important; } #print-area { border: none !important; } }`}</style>
        <h1 className="text-center text-3xl font-bold mb-8">台灣電力公司電力修護處南部分處領用單</h1>
        <div className="flex justify-between mb-4 font-bold">
          <p>領用人：{transaction.person}</p>
          <p>日期：{now.toLocaleDateString()}</p>
        </div>
        <table className="w-full border-collapse border-2 border-black text-center text-xl">
          <thead><tr className="bg-gray-100">
            <th className="border-2 border-black p-4">項目名稱</th>
            <th className="border-2 border-black p-4">單位</th>
            <th className="border-2 border-black p-4">數量</th>
            <th className="border-2 border-black p-4">用途說明</th>
          </tr></thead>
          <tbody>
            <tr className="h-32">
              <td className="border-2 border-black p-4 font-bold">{transaction.itemName}</td>
              <td className="border-2 border-black p-4">{targetItem?.unit || '個'}</td>
              <td className="border-2 border-black p-4 font-bold text-3xl">{transaction.quantity}</td>
              <td className="border-2 border-black p-4">{transaction.reason}</td>
            </tr>
          </tbody>
        </table>
        <div className="mt-20 flex justify-around font-bold text-lg">
          <p>申請人簽章：________________</p>
          <p>主管簽章：________________</p>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900">
      {/* 側邊欄 */}
      <aside className="no-print w-64 bg-slate-900 text-white p-6 flex flex-col shrink-0">
        <div className="flex items-center gap-3 mb-10"><Package className="text-blue-500" /><h1 className="font-black">工安管理系統</h1></div>
        <nav className="flex-1 space-y-2">
          {['inventory', 'issuance', 'history', 'dashboard'].map((tab) => (
            <button key={tab} onClick={() => setActiveTab(tab as any)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold capitalize ${activeTab === tab ? 'bg-blue-600' : 'text-slate-400 hover:bg-slate-800'}`}>
              {tab === 'inventory' ? <Package size={18}/> : tab === 'issuance' ? <FileText size={18}/> : tab === 'history' ? <History size={18}/> : <LayoutDashboard size={18}/>}
              {tab === 'inventory' ? '耗材清冊' : tab === 'issuance' ? '領用登記' : tab === 'history' ? '異動日誌' : '儀表板'}
            </button>
          ))}
        </nav>
        <button onClick={syncToCloud} className="py-3 bg-slate-800 rounded-xl text-xs font-bold flex items-center justify-center gap-2">
          {isSyncing ? <RefreshCw className="animate-spin" size={14}/> : <Cloud size={14}/>} 雲端備份
        </button>
      </aside>

      {/* 主區塊 */}
      <main className="no-print flex-1 p-8 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-2xl font-black text-slate-800 uppercase">{activeTab === 'inventory' ? '耗材清冊' : activeTab === 'issuance' ? '領用登記' : activeTab === 'history' ? '異動日誌' : '儀表板'}</h2>
          {activeTab === 'inventory' && <button onClick={() => setShowAddModal(true)} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold flex items-center gap-2 shadow-lg"><Plus size={18}/> 新增項目</button>}
        </header>

        {activeTab === 'inventory' && (
          <div className="bg-white rounded-3xl shadow-sm border overflow-hidden">
            <div className="p-6 bg-slate-50 border-b flex items-center gap-4">
               <Search className="text-slate-400" size={20} />
               <input type="text" placeholder="搜尋耗材..." className="bg-transparent font-bold outline-none flex-1 text-black" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
            </div>
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase tracking-widest border-b">
                <tr><th className="px-8 py-5">耗材名稱</th><th className="px-8 py-5 text-center">數量</th><th className="px-8 py-5 text-center">警戒</th><th className="px-8 py-5 text-right">管理</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50">
                    <td className="px-8 py-6 font-black text-slate-900">{item.name}</td>
                    <td className="px-8 py-6 text-center">
                      <span className={`px-4 py-1 rounded-full text-xs font-black ${item.quantity <= item.minStock ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>
                        {item.quantity} {item.unit}
