                    </td>
                    <td className="px-8 py-6 text-center text-slate-400 font-bold">{item.minStock}</td>
                    <td className="px-8 py-6 text-right">
                      {/* 【修正】這裡點擊後僅設置刪除目標，彈窗由狀態控制 */}
                      <button 
                        onClick={() => setDeleteTarget({id: item.id, name: item.name})} 
