                      >
                        <Trash2 size={20} />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* 領用/日誌/儀表板 保持原邏輯 (簡略) */}
        {activeTab === 'issuance' && (
          <div className="max-w-xl mx-auto bg-white p-12 rounded-[2.5rem] shadow-xl border text-black">
