               <button onClick={()=>setIssuanceMode('IN')} className={`flex-1 py-3 rounded-xl font-bold ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
             </div>
             <div className="space-y-6">
                <div><label className="block text-xs font-black text-slate-400 mb-2">耗材項目</label><select className="w-full p-4 border-2 rounded-2xl font-bold bg-slate-50 text-black" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}><option value="">-- 請選擇 --</option>{items.map(i=><option key={i.id} value={i.id}>{i.name} (剩餘:{i.quantity})</option>)}</select></div>
                <div className="grid grid-cols-2 gap-4">
                  <div><label className="block text-xs font-black text-slate-400 mb-2">數量</label><input type="number" className="w-full p-4 border-2 rounded-2xl font-bold bg-slate-50 text-black" value={inputQty} onChange={e=>setInputQty(Number(e.target.value))}/></div>
                  <div><label className="block text-xs font-black text-slate-400 mb-2">領用部門/人員</label><input type="text" className="w-full p-4 border-2 rounded-2xl font-bold bg-slate-50 text-black" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div>
                </div>
                <button onClick={handleTransaction} className={`w-full py-5 rounded-2xl font-black text-white text-xl ${issuanceMode==='OUT'?'bg-blue-600':'bg-emerald-600'}`}>確認提交</button>
             </div>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-sm border overflow-hidden">
             <table className="w-full text-left">
               <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase tracking-widest border-b"><tr><th className="px-8 py-4">時間</th><th className="px-8 py-4">耗材項目</th><th className="px-8 py-4">人員</th><th className="px-8 py-4 text-right">單據</th></tr></thead>
               <tbody className="divide-y">
                 {logs.map(log => (
                   <tr key={log.id} className="hover:bg-slate-50">
                     <td className="px-8 py-4 text-xs text-slate-400 font-mono">{new Date(log.timestamp).toLocaleString()}</td>
                     <td className="px-8 py-4 font-bold">{log.itemName} (x{log.quantity})</td>
                     <td className="px-8 py-4 text-slate-600">{log.person}</td>
                     <td className="px-8 py-4 text-right">{log.type==='OUT' && <button onClick={()=>{setLastTransaction(log);setShowPrintModal(true);}} className="text-blue-600 p-2 hover:bg-blue-50 rounded-lg"><Printer size={16}/></button>}</td>
                   </tr>
                 ))}
               </tbody>
             </table>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="bg-white p-12 rounded-[3rem] shadow-sm border text-center">
              <p className="text-slate-400 font-black uppercase text-xs mb-2">耗材總數</p>
              <p className="text-7xl font-black text-slate-900">{items.length}</p>
            </div>
            <div className="bg-white p-12 rounded-[3rem] shadow-sm border text-center">
              <p className="text-red-500 font-black uppercase text-xs mb-2">庫存告急</p>
              <p className="text-7xl font-black text-red-600">{items.filter(i=>i.quantity<=i.minStock).length}</p>
            </div>
          </div>
        )}
      </main>

      {/* 【核心】刪除確認自定義彈窗 */}
      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-sm p-10 shadow-2xl text-center text-black animate-in fade-in zoom-in duration-200">
            <div className="w-20 h-20 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-6">
              <AlertTriangle size={40} />
            </div>
            <h3 className="text-2xl font-black mb-2 text-slate-900">確認刪除項目？</h3>
            <p className="text-slate-500 font-bold mb-8">
              項目：<span className="text-red-600">「{deleteTarget.name}」</span><br/>
              刪除後將無法恢復，確定要移除嗎？
            </p>
            <div className="space-y-3">
              <button 
                onClick={confirmDelete} 
                className="w-full py-4 bg-red-600 text-white rounded-2xl font-black text-lg hover:bg-red-700 shadow-xl transition-all active:scale-95"
              >
                是的，確定刪除
              </button>
              <button 
                onClick={() => setDeleteTarget(null)} 
                className="w-full py-4 bg-slate-100 text-slate-400 rounded-2xl font-black text-lg hover:bg-slate-200 transition-all"
              >
                取消
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 新增項目彈窗 */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/60 z-50 flex items-center justify-center p-4 text-black">
          <div className="bg-white rounded-[2.5rem] w-full max-w-md p-8 shadow-2xl">
            <h3 className="font-black text-2xl mb-6">新增耗材項目</h3>
            <div className="space-y-4">
              <div><label className="block text-xs font-black text-slate-400 mb-1">耗材名稱</label><input type="text" className="w-full p-4 border-2 rounded-2xl font-bold bg-white text-black" value={newForm.name} onChange={e=>setNewForm({...newForm,name:e.target.value})}/></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="block text-xs font-black text-slate-400 mb-1">單位</label><input type="text" className="w-full p-4 border-2 rounded-2xl font-bold bg-white" value={newForm.unit} onChange={e=>setNewForm({...newForm,unit:e.target.value})}/></div>
                <div><label className="block text-xs font-black text-slate-400 mb-1">警戒水位</label><input type="number" className="w-full p-4 border-2 rounded-2xl font-bold bg-white" value={newForm.minStock} onChange={e=>setNewForm({...newForm,minStock:Number(e.target.value)})}/></div>
              </div>
              <button onClick={handleAddItem} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black text-lg mt-4 shadow-xl">儲存並加入清冊</button>
              <button onClick={()=>setShowAddModal(false)} className="w-full py-3 text-slate-400 font-bold">取消</button>
            </div>
          </div>
        </div>
      )}

      {/* 列印彈窗 */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-slate-900/90 z-[100] flex flex-col items-center justify-center p-4 text-black">
          <div className="bg-white rounded-3xl w-full max-w-5xl p-6 relative overflow-y-auto max-h-[95vh]">
            <div className="flex justify-between items-center mb-6 no-print">
               <span className="font-black text-xl text-blue-600">單據預覽</span>
               <div className="flex gap-3">
                 <button onClick={()=>window.print()} className="bg-blue-600 text-white px-8 py-3 rounded-xl font-bold">執行列印</button>
                 <button onClick={()=>setShowPrintModal(false)} className="p-3 bg-slate-100 rounded-full"><X size={20}/></button>
               </div>
            </div>
            <PrintableForm transaction={lastTransaction} />
          </div>
        </div>
      )}

      {/* 列印區 */}
      <div className="hidden print:block absolute top-0 left-0 w-full">
         {lastTransaction && <PrintableForm transaction={lastTransaction} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  RefreshCw,
  Search,
  X,
  Printer,
  Cloud,
  AlertTriangle,
  BrainCircuit,
  TrendingDown
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell,
  ReferenceLine
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v7_items';
const STORAGE_KEY_LOGS = 'safeman_v7_logs';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  // AI 建議相關狀態
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<number>(1);
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');

  // 初始化
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  // 存檔
  useEffect(() => {
    if (isLoaded) localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
  }, [items, isLoaded]);

  useEffect(() => {
    if (isLoaded) localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
  }, [logs, isLoaded]);

  // 當切換到儀表板時，自動請求 AI 建議
  useEffect(() => {
    if (activeTab === 'dashboard' && items.length > 0 && !aiInsights) {
      handleGetAiInsights();
    }
  }, [activeTab]);

  const handleGetAiInsights = async () => {
    setIsAiLoading(true);
    const result = await getInventoryInsights(items);
    setAiInsights(result);
    setIsAiLoading(false);
  };

  const generateId = () => `ID-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

  const confirmDelete = () => {
    if (!deleteTarget) return;
    setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  const handleAddItem = () => {
    if (!newForm.name.trim()) return;
    const newItem: InventoryItem = {
      id: generateId(),
      name: newForm.name.trim(),
      category: newForm.category,
      unit: newForm.unit || '個',
      quantity: Number(newForm.quantity) || 0,
      minStock: Number(newForm.minStock) || 0,
      description: '',
      lastUpdated: Date.now()
    };
    setItems(prev => [...prev, newItem]);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, unit: '個', minStock: 5, quantity: 0 });
  };

  const handleTransaction = () => {
    if (!selectedItemId) return;
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;
    const qty = Number(inputQty);
    if (issuanceMode === 'OUT' && qty > targetItem.quantity) return alert('庫存不足');

    setItems(prev => prev.map(item => item.id === selectedItemId ? { ...item, quantity: issuanceMode === 'IN' ? item.quantity + qty : item.quantity - qty, lastUpdated: Date.now() } : item));
    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: qty,
      person: inputPerson || '未填寫',
      reason: inputReason,
      timestamp: Date.now()
    };
    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);
    if (issuanceMode === 'OUT') setShowPrintModal(true);
    setSelectedItemId(''); setInputQty(1); setInputPerson(''); setInputReason('');
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    unit: '個',
    minStock: 5,
    quantity: 0
  });

  // 圖表數據處理
  const chartData = useMemo(() => {
    return items.slice(0, 10).map(item => ({
      name: item.name,
      '實際庫存': item.quantity,
      '警戒線': item.minStock
    }));
  }, [items]);

  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const now = new Date(transaction.timestamp);
    return (
      <div className="bg-white p-10 w-[210mm] mx-auto text-black border-2 border-black" id="print-area">
