        <div className="flex justify-between mb-4 font-bold border-b-2 border-black pb-2">
          <p>領用人：{transaction.person}</p>
          <p>日期：{now.toLocaleDateString()}</p>
        </div>
        <table className="w-full border-collapse border-2 border-black text-center text-xl mt-4">
          <thead><tr className="bg-slate-100">
            <th className="border-2 border-black p-4 w-1/2">項目名稱</th>
            <th className="border-2 border-black p-4">單位</th>
            <th className="border-2 border-black p-4">數量</th>
          </tr></thead>
          <tbody>
            <tr className="h-40">
              <td className="border-2 border-black p-4 font-black text-2xl">{transaction.itemName}</td>
              <td className="border-2 border-black p-4">{targetItem?.unit || '個'}</td>
              <td className="border-2 border-black p-4 font-black text-5xl">{transaction.quantity}</td>
            </tr>
            <tr>
               <td colSpan={3} className="border-2 border-black p-4 text-left align-top h-24 font-bold">
                  用途說明：{transaction.reason || '公務領用'}
               </td>
            </tr>
          </tbody>
        </table>
        <div className="mt-24 flex justify-around font-bold text-lg">
          <p>申請人簽章：________________</p>
          <p>經辦人簽章：________________</p>
        </div>
