                <button onClick={handleTransaction} className={`w-full py-6 rounded-2xl font-black text-white text-2xl shadow-2xl transition-all active:scale-95 ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>
