                     <td className="px-10 py-6 text-slate-600 font-bold">{log.person}</td>
                     <td className="px-10 py-6">
                        {log.type === 'OUT' ? <span className="text-blue-600 font-black">領用</span> : <span className="text-emerald-600 font-black">補貨</span>}
                     </td>
                     <td className="px-10 py-6 text-right">
                        {log.type === 'OUT' && <button onClick={()=>{setLastTransaction(log);setShowPrintModal(true);}} className="text-blue-600 p-3 hover:bg-blue-50 rounded-xl transition-all inline-flex items-center gap-2 font-bold text-sm"><Printer size={16}/> 列印</button>}
                     </td>
                   </tr>
                 ))}
               </tbody>
             </table>
          </div>
        )}
      </main>

      {/* 刪除確認視窗 */}
      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-sm p-12 shadow-2xl text-center text-black">
            <div className="w-24 h-24 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-8">
              <AlertTriangle size={48} />
            </div>
            <h3 className="text-3xl font-black mb-3">確認刪除？</h3>
            <p className="text-slate-500 font-bold mb-10 leading-relaxed">
              您即將移除 <span className="text-red-600 font-black underline">「{deleteTarget.name}」</span>。<br/>這項操作將永久刪除該耗材的所有數據。
            </p>
            <div className="flex flex-col gap-3">
              <button onClick={confirmDelete} className="w-full py-5 bg-red-600 text-white rounded-2xl font-black text-xl hover:bg-red-700 shadow-xl transition-all active:scale-95">確定，執行刪除</button>
              <button onClick={() => setDeleteTarget(null)} className="w-full py-5 bg-slate-100 text-slate-400 rounded-2xl font-black text-xl hover:bg-slate-200 transition-all">取消</button>
            </div>
          </div>
        </div>
      )}

      {/* 新增項目彈窗 */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-50 flex items-center justify-center p-4 text-black">
          <div className="bg-white rounded-[3rem] w-full max-w-md p-10 shadow-2xl">
            <div className="flex justify-between items-center mb-10">
              <h3 className="font-black text-3xl">新增耗材</h3>
              <button onClick={()=>setShowAddModal(false)} className="p-2 bg-slate-100 rounded-full text-slate-400"><X/></button>
            </div>
            <div className="space-y-6">
              <div><label className="block text-xs font-black text-slate-400 mb-2">耗材全稱</label><input type="text" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white text-black text-lg focus:border-blue-500 outline-none" value={newForm.name} onChange={e=>setNewForm({...newForm,name:e.target.value})}/></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="block text-xs font-black text-slate-400 mb-2">單位 (如: 雙, 個)</label><input type="text" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold text-lg" value={newForm.unit} onChange={e=>setNewForm({...newForm,unit:e.target.value})}/></div>
                <div><label className="block text-xs font-black text-slate-400 mb-2">安全警戒水位</label><input type="number" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold text-lg" value={newForm.minStock} onChange={e=>setNewForm({...newForm,minStock:Number(e.target.value)})}/></div>
              </div>
              <button onClick={handleAddItem} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl mt-4 shadow-xl hover:bg-blue-700 transition-all active:scale-95">完成儲存並入庫</button>
            </div>
          </div>
        </div>
      )}

      {/* 列印預覽視窗 */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-slate-900/90 z-[100] flex flex-col items-center justify-center p-4 text-black overflow-y-auto">
          <div className="bg-white rounded-[2rem] w-full max-w-5xl p-8 relative shadow-2xl my-10">
            <div className="flex justify-between items-center mb-10 no-print border-b pb-6">
               <div className="flex items-center gap-3">
                 <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center"><Printer/></div>
                 <span className="font-black text-2xl">單據列印預覽</span>
