               <div className="flex gap-4">
                 <button onClick={()=>window.print()} className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black text-lg shadow-lg hover:bg-blue-700 transition-all">執行列印</button>
                 <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full hover:bg-slate-200 transition-all"><X size={24}/></button>
               </div>
            </div>
            <div className="bg-slate-50 p-10 rounded-[2.5rem] overflow-x-auto shadow-inner">
               <PrintableForm transaction={lastTransaction} />
            </div>
          </div>
        </div>
      )}

      {/* 列印專用隱藏區塊 */}
      <div className="hidden print:block absolute top-0 left-0 w-full">
         {lastTransaction && <PrintableForm transaction={lastTransaction} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  RefreshCw,
  Search,
  X,
  Printer,
  Cloud,
  AlertTriangle,
  BrainCircuit,
  TrendingDown,
  Calendar
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v7_items';
const STORAGE_KEY_LOGS = 'safeman_v7_logs';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<number>(1);
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    unit: '個',
    minStock: 5,
    quantity: 0
  });

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
  }, [items, isLoaded]);

  useEffect(() => {
    if (isLoaded) localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
  }, [logs, isLoaded]);

  useEffect(() => {
    if (activeTab === 'dashboard' && items.length > 0 && !aiInsights) {
      handleGetAiInsights();
    }
  }, [activeTab]);

  const handleGetAiInsights = async () => {
    setIsAiLoading(true);
    const result = await getInventoryInsights(items);
    setAiInsights(result);
    setIsAiLoading(false);
  };

  const generateId = () => `ID-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

  const confirmDelete = () => {
    if (!deleteTarget) return;
    setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  const handleAddItem = () => {
    if (!newForm.name.trim()) return alert('請輸入耗材名稱');
    const newItem: InventoryItem = {
      id: generateId(),
      name: newForm.name.trim(),
      category: newForm.category,
      unit: newForm.unit || '個',
      quantity: Number(newForm.quantity) || 0,
      minStock: Number(newForm.minStock) || 0,
      description: '',
      lastUpdated: Date.now()
    };
    setItems(prev => [...prev, newItem]);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, unit: '個', minStock: 5, quantity: 0 });
  };

  const handleTransaction = () => {
    if (!selectedItemId) return alert('請選擇一個耗材項目');
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    const qty = Number(inputQty);
    if (isNaN(qty) || qty <= 0) return alert('請輸入正確的數量');

    // 庫存檢查
    if (issuanceMode === 'OUT' && qty > targetItem.quantity) {
      return alert(`庫存不足！\n\n項目：「${targetItem.name}」\n目前僅剩餘：${targetItem.quantity} ${targetItem.unit}\n您的領用量：${qty} ${targetItem.unit}`);
    }

    setItems(prev => prev.map(item => item.id === selectedItemId ? { ...item, quantity: issuanceMode === 'IN' ? item.quantity + qty : item.quantity - qty, lastUpdated: Date.now() } : item));

    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: qty,
      person: issuanceMode === 'OUT' ? (inputPerson || '未填寫') : '庫存補貨',
      reason: issuanceMode === 'OUT' ? (inputReason || '公務領用') : '定期補貨入庫',
      timestamp: Date.now()
    };

    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      alert('補貨入庫成功！');
    }

    setSelectedItemId(''); setInputQty(1); setInputPerson(''); setInputReason('');
  };

  const chartData = useMemo(() => {
    return items.slice(0, 10).map(item => ({
      name: item.name,
      '實際庫存': item.quantity,
      '警戒線': item.minStock
    }));
  }, [items]);

  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const now = new Date(transaction.timestamp);
    return (
      <div className="bg-white p-12 w-[210mm] mx-auto text-black" id="print-area">
        <style>{`
          @media print { 
            .no-print { display: none !important; } 
            body { background: white !important; }
            #print-area { padding: 0 !important; width: 100% !important; }
          }
        `}</style>
        <div className="border-[3px] border-black p-8">
          <h1 className="text-center text-4xl font-bold mb-2 tracking-widest">台灣電力公司電力修護處南部分處</h1>
          <h2 className="text-center text-2xl font-bold mb-10 border-b-2 border-black pb-4">工安耗材領用單</h2>

          <div className="flex justify-between mb-6 text-xl font-bold px-2">
            <p>領用部門 / 人員：<span className="border-b border-black px-4">{transaction.person}</span></p>
            <p>日期：<span className="border-b border-black px-4">{now.toLocaleDateString('zh-TW')}</span></p>
          </div>

          <table className="w-full border-collapse border-[2.5px] border-black text-center text-2xl">
            <thead>
              <tr className="bg-gray-50">
                <th className="border-2 border-black p-4 w-1/2">耗材項目名稱</th>
                <th className="border-2 border-black p-4 w-1/6">單位</th>
                <th className="border-2 border-black p-4 w-1/3">領用數量</th>
              </tr>
            </thead>
            <tbody>
              <tr className="h-48">
                <td className="border-2 border-black p-4 font-bold">{transaction.itemName}</td>
                <td className="border-2 border-black p-4">{targetItem?.unit || '個'}</td>
                <td className="border-2 border-black p-4 font-black text-6xl">{transaction.quantity}</td>
              </tr>
              <tr>
                <td colSpan={3} className="border-2 border-black p-6 text-left align-top h-32 text-xl">
                  <span className="font-bold">用途說明：</span>
                  <div className="mt-2 pl-4">{transaction.reason}</div>
                </td>
              </tr>
            </tbody>
          </table>

          <div className="mt-24 flex justify-between items-end px-4 text-xl font-bold">
            <div className="flex flex-col items-center">
              <div className="h-1 bg-black w-48 mb-2"></div>
              <p>申請人簽章</p>
            </div>
            <div className="flex flex-col items-center">
              <div className="h-1 bg-black w-48 mb-2"></div>
              <p>主管 / 經辦簽章</p>
            </div>
          </div>

          <div className="mt-12 text-sm text-gray-500 text-right italic no-print">
            單據編號: {transaction.id}
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-slate-100 text-slate-900 font-sans">
      {/* 側邊導覽 */}
      <aside className="no-print w-72 bg-slate-900 text-white p-8 flex flex-col shrink-0">
        <div className="flex items-center gap-3 mb-12">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg">
            <Package size={22} />
          </div>
          <div>
            <h1 className="font-black text-lg">工安管理系統</h1>
            <p className="text-[10px] text-slate-500 font-bold tracking-widest uppercase">Safety Pro v7.6</p>
          </div>
        </div>

        <nav className="flex-1 space-y-3">
          {[
            { id: 'inventory', label: '耗材清冊', icon: Package },
            { id: 'issuance', label: '領用/補貨', icon: FileText },
            { id: 'history', label: '異動日誌', icon: History },
            { id: 'dashboard', label: '儀表板', icon: LayoutDashboard },
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 shadow-lg text-white' : 'text-slate-400 hover:bg-slate-800'}`}>
              <tab.icon size={20} /> {tab.label}
            </button>
          ))}
        </nav>

        <button className="mt-8 py-4 bg-slate-800 rounded-2xl text-xs font-bold flex items-center justify-center gap-3 hover:bg-slate-700">
          <Cloud size={16} className="text-blue-400" /> 資料已加密備份
        </button>
      </aside>

      {/* 主內容區 */}
      <main className="no-print flex-1 p-10 overflow-y-auto">
        <header className="mb-10 flex justify-between items-center">
          <h2 className="text-4xl font-black text-slate-900 capitalize">
            {activeTab === 'inventory' ? '耗材清冊' : activeTab === 'issuance' ? '領用與補貨' : activeTab === 'history' ? '歷史日誌' : '數據儀表板'}
