            </div>
            <table className="w-full text-left">
              <thead>
                <tr className="text-[11px] font-black text-slate-400 uppercase tracking-widest border-b">
                  <th className="px-10 py-6">耗材名稱</th>
                  <th className="px-10 py-6 text-center">數量</th>
