                  ) : (
                    <div>
                      <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">入庫時間</label>
                      <div className="w-full p-5 border-2 border-slate-100 rounded-2xl font-bold bg-slate-100 text-slate-400 text-xl flex items-center gap-3">
