                      </div>
                    </div>
                  )}
                </div>

                {issuanceMode === 'OUT' && (
                  <div>
                    <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">領用用途</label>
                    <textarea className="w-full p-5 border-2 border-slate-100 rounded-2xl font-bold bg-white text-black outline-none h-24" value={inputReason} onChange={e=>setInputReason(e.target.value)} placeholder="填寫領用之工令或用途..."></textarea>
