               <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase border-b">
                 <tr><th className="px-10 py-6">日期</th><th className="px-10 py-6">耗材</th><th className="px-10 py-6">人員/備註</th><th className="px-10 py-6">類型</th><th className="px-10 py-6 text-right">單據</th></tr>
               </thead>
               <tbody className="divide-y divide-slate-50">
                 {logs.map(log => (
                   <tr key={log.id} className="hover:bg-slate-50">
