                        {log.type === 'OUT' && <button onClick={()=>{setLastTransaction(log);setShowPrintModal(true);}} className="text-blue-600 p-3 hover:bg-blue-50 rounded-xl transition-all"><Printer size={18}/></button>}
                     </td>
                   </tr>
                 ))}
               </tbody>
             </table>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8 text-black">
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100"><p className="text-slate-400 font-black text-xs mb-3">總項數</p><p className="text-6xl font-black">{items.length}</p></div>
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border-l-8 border-l-red-500"><p className="text-red-500 font-black text-xs mb-3">庫存告急</p><p className="text-6xl font-black text-red-600">{items.filter(i=>i.quantity<=i.minStock).length}</p></div>
              <div className="bg-slate-900 p-10 rounded-[2.5rem] shadow-2xl text-white relative overflow-hidden">
                <BrainCircuit className="absolute -right-6 -bottom-6 text-white/5" size={160} />
                <p className="text-blue-400 font-black text-xs mb-3">AI 助理</p>
                <button onClick={handleGetAiInsights} disabled={isAiLoading} className="px-6 py-3 bg-blue-600 rounded-xl font-bold text-sm hover:bg-blue-500 disabled:opacity-50">
                  {isAiLoading ? '分析中...' : '重新產出建議'}
