                    <Bar dataKey="實際庫存" barSize={35}>
                      {chartData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry['實際庫存'] <= entry['警戒線'] ? '#ef4444' : '#3b82f6'} />
