              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border flex flex-col">
                <h3 className="text-xl font-black mb-8 flex items-center gap-2 text-purple-600"><BrainCircuit size={22}/> AI 智慧庫存建議</h3>
