              <AlertTriangle size={40} />
            </div>
            <h3 className="text-2xl font-black mb-3">確認刪除項目？</h3>
            <p className="text-slate-500 font-bold mb-10 leading-relaxed">
              您即將從資料庫永久移除：<br/><span className="text-red-600 font-black">「{deleteTarget.name}」</span>
