            <div className="flex flex-col gap-3">
              <button onClick={confirmDelete} className="w-full py-5 bg-red-600 text-white rounded-2xl font-black text-lg hover:bg-red-700 shadow-xl transition-all active:scale-95">是的，確認刪除</button>
              <button onClick={() => setDeleteTarget(null)} className="w-full py-5 bg-slate-100 text-slate-400 rounded-2xl font-black text-lg hover:bg-slate-200">取消</button>
            </div>
          </div>
        </div>
      )}

      {/* 新增耗材彈窗 (底色修正) */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 text-black">
          <div className="bg-white rounded-[3rem] w-full max-w-md p-10 shadow-2xl">
            <div className="flex justify-between items-center mb-10">
              <h3 className="font-black text-3xl">新增耗材項目</h3>
              <button onClick={()=>setShowAddModal(false)} className="p-2 bg-slate-100 rounded-full"><X/></button>
            </div>
            <div className="space-y-6">
              <div>
                <label className="block text-xs font-black text-slate-400 mb-2">耗材名稱</label>
                <input type="text" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white text-black text-lg outline-none focus:border-blue-500" value={newForm.name} onChange={e=>setNewForm({...newForm,name:e.target.value})}/>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-2">單位 (如: 雙, 個)</label>
                  <input type="text" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white text-black text-lg outline-none focus:border-blue-500" value={newForm.unit} onChange={e=>setNewForm({...newForm,unit:e.target.value})}/>
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-2">警戒安全水位</label>
                  <input type="number" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white text-black text-lg outline-none focus:border-blue-500" value={newForm.minStock} onChange={e=>setNewForm({...newForm,minStock:Number(e.target.value)})}/>
                </div>
              </div>
              <button onClick={handleAddItem} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl mt-4 shadow-xl hover:bg-blue-700 transition-all active:scale-95">儲存項目至資料庫</button>
            </div>
          </div>
        </div>
      )}

      {/* 列印預覽 (恢復完美單據) */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-slate-900/90 z-[100] flex flex-col items-center justify-start p-10 text-black overflow-y-auto">
          <div className="bg-white rounded-3xl w-full max-w-5xl p-10 relative shadow-2xl my-4">
            <div className="flex justify-between items-center mb-8 no-print border-b pb-4">
               <div className="flex items-center gap-3">
                 <Printer className="text-blue-600"/>
                 <span className="font-black text-2xl">領用單預覽 (列印建議設為 A4)</span>
               </div>
               <div className="flex gap-4">
                 <button onClick={()=>window.print()} className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black text-xl hover:bg-blue-700 shadow-lg">執行列印</button>
                 <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full"><X size={24}/></button>
               </div>
            </div>
            <div className="bg-white">
               <PrintableForm transaction={lastTransaction} />
            </div>
          </div>
        </div>
      )}

      {/* 純列印區塊 */}
      <div className="hidden print:block absolute top-0 left-0 w-full">
         {lastTransaction && <PrintableForm transaction={lastTransaction} />}
      </div>
    </div>
  );
};

export default App;

