const STORAGE_KEY_LOGS = 'safeman_v8_logs';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<number>(1);
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [inputDept, setInputDept] = useState('南部分處');

  const fileInputRef = useRef<HTMLInputElement>(null);

  // 初始化
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  // 存檔
  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  // AI 分析
  useEffect(() => {
    if (activeTab === 'dashboard' && items.length > 0 && !aiInsights) {
      handleGetAiInsights();
    }
  }, [activeTab]);

  const handleGetAiInsights = async () => {
    setIsAiLoading(true);
    const result = await getInventoryInsights(items);
    setAiInsights(result);
    setIsAiLoading(false);
  };

  const generateId = () => `ID-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

  const confirmDelete = () => {
    if (!deleteTarget) return;
    setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  // 匯出資料
  const handleExportData = () => {
    const data = { items, logs, timestamp: Date.now() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `工安管理備份_${new Date().toLocaleDateString()}.json`;
    a.click();
  };

  // 匯入資料
  const handleImportData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (data.items && Array.isArray(data.items)) {
          if (window.confirm('匯入將覆蓋現有資料，確定嗎？')) {
            setItems(data.items);
            setLogs(data.logs || []);
            alert('匯入成功！');
          }
        }
      } catch (err) {
        alert('檔案格式錯誤');
      }
    };
    reader.readAsText(file);
  };

  const handleTransaction = () => {
    if (!selectedItemId) return alert('請先選擇一個耗材項目');
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    const qty = Number(inputQty);
    if (isNaN(qty) || qty <= 0) return alert('請輸入有效的數字');

    // 關鍵：領用量檢查
    if (issuanceMode === 'OUT' && qty > targetItem.quantity) {
      window.alert(`❌ 警告：庫存不足！\n\n項目：「${targetItem.name}」\n當前庫存：${targetItem.quantity} ${targetItem.unit}\n領用量：${qty} ${targetItem.unit}\n\n請先進行補貨或調整領用量。`);
      return;
    }

    // 更新庫存
    setItems(prev => prev.map(item => 
      item.id === selectedItemId 
        ? { ...item, quantity: issuanceMode === 'IN' ? item.quantity + qty : item.quantity - qty, lastUpdated: Date.now() } 
        : item
    ));

    // 記錄日誌
    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: qty,
      person: issuanceMode === 'OUT' ? (inputPerson || '未填寫') : '入庫人員',
      reason: issuanceMode === 'OUT' ? (inputReason || '無備註') : '庫存補充',
      timestamp: Date.now()
    };

    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      alert('補貨入庫完成！');
    }

    setSelectedItemId(''); setInputQty(1); setInputPerson(''); setInputReason('');
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    unit: '個',
    minStock: 5,
    quantity: 0
  });

  const handleAddItem = () => {
    if (!newForm.name.trim()) return alert('請輸入耗材名稱');
    const newItem: InventoryItem = {
      id: generateId(),
      name: newForm.name.trim(),
      category: newForm.category,
      unit: newForm.unit || '個',
      quantity: Number(newForm.quantity) || 0,
      minStock: Number(newForm.minStock) || 0,
      description: '',
      lastUpdated: Date.now()
    };
    setItems(prev => [...prev, newItem]);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, unit: '個', minStock: 5, quantity: 0 });
  };

  // 領用單元件 (完全依照圖片格式)
  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const date = new Date(transaction.timestamp);
    const emptyRows = Array(12).fill(null); // 補滿 12 行空白行

    return (
      <div className="print-area bg-white text-black p-4 w-[210mm] mx-auto overflow-hidden" id="official-form">
        <style>{`
          @font-face {
            font-family: 'BiauKai';
            src: local('標楷體'), local('DFKai-SB');
          }
          #official-form * {
            font-family: 'BiauKai', serif;
            font-size: 14pt;
            color: black !important;
            border-color: black !important;
          }
          @media print {
            .no-print { display: none !important; }
            body { background: white; margin: 0; padding: 0; }
            #official-form { padding: 0; width: 100%; }
          }
          .custom-table th, .custom-table td {
            border: 1px solid black;
            padding: 4px 8px;
            height: 32px;
            vertical-align: middle;
          }
        `}</style>

        {/* 標題 */}
        <h1 className="text-center text-3xl font-bold mb-2">台灣電力公司電力修護處南部分處</h1>

        {/* 單據類型勾選 */}
        <div className="flex justify-center gap-12 mb-4 font-bold">
          <label className="flex items-center gap-2">
            <span className="w-5 h-5 border-2 border-black inline-block text-center leading-4 text-xs"> </span>
            安全衛生設備借用單
          </label>
          <label className="flex items-center gap-2">
            <span className="w-5 h-5 border-2 border-black inline-block text-center leading-4 text-xs font-black">V</span>
            安全衛生類消耗品領用單
          </label>
        </div>

        {/* 表頭資訊 */}
        <div className="flex justify-between mb-2 font-bold px-1">
          <div>部門：<span className="inline-block border-b border-dotted border-black min-w-[150px]">{inputDept}</span></div>
          <div>{date.getFullYear() - 1911} 年 {date.getMonth() + 1} 月 {date.getDate()} 日</div>
        </div>

        {/* 表格 */}
        <table className="w-full border-collapse custom-table text-center">
          <thead>
            <tr>
              <th className="w-1/3">名　　　　　稱</th>
              <th className="w-1/4">規　範（序　號）</th>
              <th className="w-12">單位</th>
              <th className="w-12">數量</th>
              <th className="w-1/4">備　　　　　註</th>
            </tr>
          </thead>
          <tbody>
            {/* 第一行填寫實際資料 */}
            <tr>
              <td className="text-left font-bold">{transaction.itemName}</td>
              <td>{transaction.id.split('-')[1]}</td>
              <td>{targetItem?.unit || '個'}</td>
              <td className="font-black">{transaction.quantity}</td>
              <td className="text-left text-xs">{transaction.reason}</td>
            </tr>
            {/* 補充空白行 */}
            {emptyRows.map((_, idx) => (
              <tr key={idx}><td /><td /><td /><td /><td /></tr>
            ))}
          </tbody>
        </table>

        {/* 頁尾簽核 */}
        <div className="mt-4 font-bold flex flex-col gap-6">
          <div className="flex justify-between px-1">
             <div>申請部門：<span className="inline-block border-b border-dotted border-black min-w-[200px]">{inputPerson}</span></div>
             <div>經管部門：________________</div>
          </div>

          <div className="grid grid-cols-2 gap-4">
             {/* 申請部門簽核區 */}
             <div className="flex gap-4 items-end">
                <div>經辦：<span className="inline-block border-b border-dotted border-black min-w-[60px]"> </span></div>
                <div>課長：<span className="inline-block border-b border-dotted border-black min-w-[60px]"> </span></div>
                <div>經理：<span className="inline-block border-b border-dotted border-black min-w-[60px]"> </span></div>
             </div>
             {/* 經管部門簽核區 */}
             <div className="flex gap-4 items-end">
                <div>經辦：<span className="inline-block border-b border-dotted border-black min-w-[60px]"> </span></div>
                <div>課長：<span className="inline-block border-b border-dotted border-black min-w-[60px]"> </span></div>
                <div>經理：<span className="inline-block border-b border-dotted border-black min-w-[60px]"> </span></div>
             </div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-slate-100 text-slate-900 font-sans">
      {/* 隱藏的檔案選擇器 */}
      <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={handleImportData} />

      {/* 側邊導覽 */}
      <aside className="no-print w-72 bg-slate-900 text-white p-8 flex flex-col shrink-0">
        <div className="flex items-center gap-3 mb-12">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg">
            <Package size={22} />
          </div>
          <div><h1 className="font-black text-lg">工安管理系統</h1><p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Official v8.0</p></div>
        </div>

        <nav className="flex-1 space-y-2">
          {[
            { id: 'inventory', label: '耗材清冊', icon: Package },
            { id: 'issuance', label: '領用與補貨', icon: FileText },
            { id: 'history', label: '歷史紀錄', icon: History },
            { id: 'dashboard', label: '智慧儀表板', icon: LayoutDashboard },
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 shadow-lg text-white' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}>
              <tab.icon size={20} /> {tab.label}
            </button>
          ))}
        </nav>

        {/* 資料遷移功能區 */}
        <div className="mt-8 pt-8 border-t border-slate-800 space-y-3">
          <p className="text-[10px] text-slate-500 font-black uppercase mb-2">資料與協作管理</p>
          <button onClick={handleExportData} className="w-full flex items-center gap-3 px-4 py-3 bg-slate-800 rounded-xl text-xs font-bold hover:bg-slate-700 transition-all">
            <Download size={14} className="text-blue-400" /> 匯出備份 (傳給同事)
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-4 py-3 bg-slate-800 rounded-xl text-xs font-bold hover:bg-slate-700 transition-all">
            <Upload size={14} className="text-emerald-400" /> 匯入還原 (接收同事)
          </button>
        </div>
      </aside>

      {/* 主內容區 */}
      <main className="no-print flex-1 p-10 overflow-y-auto">
        <header className="mb-10 flex justify-between items-center">
          <h2 className="text-4xl font-black text-slate-900">
            {activeTab === 'inventory' ? '耗材管理清冊' : activeTab === 'issuance' ? '領用與補貨登記' : activeTab === 'history' ? '歷史異動日誌' : '智慧庫存分析'}
          </h2>
          {activeTab === 'inventory' && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black flex items-center gap-3 shadow-xl hover:bg-black active:scale-95 transition-all">
              <Plus size={20}/> 新增工安耗材
            </button>
          )}
        </header>

        {activeTab === 'inventory' && (
          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 overflow-hidden">
            <div className="p-8 bg-slate-50 border-b flex items-center gap-6">
               <div className="relative flex-1">
                 <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                 <input type="text" placeholder="快速搜尋耗材名稱..." className="w-full pl-14 pr-6 py-4 bg-white border-2 border-slate-200 rounded-2xl font-bold outline-none focus:border-blue-500 text-black shadow-inner" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
               </div>
            </div>
            <table className="w-full text-left">
              <thead>
                <tr className="text-[11px] font-black text-slate-400 uppercase tracking-widest border-b">
                  <th className="px-10 py-6">耗材名稱</th>
                  <th className="px-10 py-6 text-center">數量</th>
                  <th className="px-10 py-6 text-center">安全水位</th>
                  <th className="px-10 py-6 text-right">操作</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 text-black">
                {items.filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                  <tr key={item.id} className="group hover:bg-slate-50 transition-all">
                    <td className="px-10 py-7 font-black text-lg">{item.name}</td>
                    <td className="px-10 py-7 text-center">
                      <span className={`px-5 py-2 rounded-xl text-sm font-black ${item.quantity <= item.minStock ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>
                        {item.quantity} {item.unit}
                      </span>
                    </td>
                    <td className="px-10 py-7 text-center font-bold text-slate-400">{item.minStock}</td>
                    <td className="px-10 py-7 text-right">
                      <button onClick={() => setDeleteTarget({id: item.id, name: item.name})} className="p-4 text-slate-200 hover:text-red-600 hover:bg-red-50 rounded-2xl opacity-0 group-hover:opacity-100 transition-all">
                        <Trash2 size={22} />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'issuance' && (
          <div className="max-w-2xl mx-auto bg-white p-12 rounded-[3rem] shadow-xl border border-slate-100 text-black">
             <div className="flex bg-slate-100 p-2 rounded-2xl mb-12">
               <button onClick={()=>setIssuanceMode('OUT')} className={`flex-1 py-5 rounded-xl font-black text-lg transition-all ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button>
               <button onClick={()=>setIssuanceMode('IN')} className={`flex-1 py-5 rounded-xl font-black text-lg transition-all ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
             </div>

             <div className="space-y-8">
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">選取項目</label>
                  <select className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold bg-slate-50 text-black text-xl outline-none focus:border-blue-600 transition-all" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                    <option value="">-- 請從清單中選取 --</option>
                    {items.map(i=><option key={i.id} value={i.id}>{i.name} (剩餘: {i.quantity} {i.unit})</option>)}
                  </select>
                </div>

                <div className="grid grid-cols-2 gap-8">
                  <div>
                    <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">異動數量</label>
                    <input type="number" min="1" className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold bg-white text-black text-xl outline-none" value={inputQty} onChange={e=>setInputQty(Number(e.target.value))}/>
                  </div>

                  {issuanceMode === 'OUT' ? (
                    <div>
                      <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">申請部門 / 人員</label>
                      <input type="text" placeholder="例: 修護一組 王小明" className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold bg-white text-black text-xl outline-none" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/>
                    </div>
                  ) : (
                    <div>
                      <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">入庫日期</label>
                      <div className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold bg-slate-100 text-slate-400 text-xl flex items-center gap-3">
                        <Calendar size={20} /> {new Date().toLocaleDateString()}
                      </div>
                    </div>
                  )}
                </div>

                {issuanceMode === 'OUT' && (
                  <div>
                    <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">用途備註</label>
                    <textarea className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold bg-white text-black outline-none h-24" value={inputReason} onChange={e=>setInputReason(e.target.value)} placeholder="填寫領用之工程項目或原因..."></textarea>
                  </div>
                )}

                <button onClick={handleTransaction} className={`w-full py-6 rounded-2xl font-black text-white text-2xl shadow-2xl transition-all active:scale-95 ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700 shadow-blue-500/20':'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-500/20'}`}>
                  {issuanceMode === 'OUT' ? '產出領用單並扣庫存' : '確認入庫並增加庫存'}
                </button>
             </div>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 overflow-hidden text-black">
             <table className="w-full text-left">
               <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase border-b">
                 <tr><th className="px-10 py-6">異動日期</th><th className="px-10 py-6">耗材名稱</th><th className="px-10 py-6">對象</th><th className="px-10 py-6">操作類型</th><th className="px-10 py-6 text-right">單據</th></tr>
               </thead>
               <tbody className="divide-y divide-slate-50">
                 {logs.map(log => (
                   <tr key={log.id} className="hover:bg-slate-50">
                     <td className="px-10 py-6 text-xs text-slate-400 font-mono font-bold">{new Date(log.timestamp).toLocaleString()}</td>
                     <td className="px-10 py-6 font-black">{log.itemName} <span className="text-slate-400 ml-1">x{log.quantity}</span></td>
                     <td className="px-10 py-6 text-slate-600 font-bold">{log.person}</td>
                     <td className="px-10 py-6">
                        {log.type === 'OUT' ? <span className="text-blue-600 font-black">領用出庫</span> : <span className="text-emerald-600 font-black">補貨入庫</span>}
                     </td>
                     <td className="px-10 py-6 text-right">
                        {log.type === 'OUT' && <button onClick={()=>{setLastTransaction(log);setShowPrintModal(true);}} className="text-blue-600 p-3 hover:bg-blue-50 rounded-xl transition-all"><Printer size={18}/></button>}
                     </td>
                   </tr>
                 ))}
               </tbody>
             </table>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8 text-black">
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100"><p className="text-slate-400 font-black text-xs mb-3">總耗材項目</p><p className="text-6xl font-black">{items.length}</p></div>
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border-l-8 border-l-red-500"><p className="text-red-500 font-black text-xs mb-3">低水位警告</p><p className="text-6xl font-black text-red-600">{items.filter(i=>i.quantity<=i.minStock).length}</p></div>
              <div className="bg-slate-900 p-10 rounded-[2.5rem] shadow-2xl text-white relative overflow-hidden">
                <BrainCircuit className="absolute -right-6 -bottom-6 text-white/5" size={160} />
                <p className="text-blue-400 font-black text-xs mb-3">AI 分析助手</p>
                <button onClick={handleGetAiInsights} disabled={isAiLoading} className="px-6 py-3 bg-blue-600 rounded-xl font-bold text-sm hover:bg-blue-500 active:scale-95 transition-all">
                  {isAiLoading ? 'Gemini 正在計算中...' : '重新生成 AI 建議'}
                </button>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100 h-[500px]">
                <h3 className="text-xl font-black mb-8 text-black">目前庫存與水位圖</h3>
                <ResponsiveContainer width="100%" height="90%">
                  <BarChart data={items.slice(0, 10).map(i => ({ name: i.name, quantity: i.quantity, min: i.minStock }))}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="name" tick={{fill: '#94a3b8', fontSize: 12, fontWeight: 'bold'}} />
                    <YAxis />
                    <Tooltip contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} />
