                <div className="flex-1 bg-slate-50 p-8 rounded-3xl font-bold text-slate-700 whitespace-pre-wrap leading-relaxed shadow-inner">
                  {isAiLoading ? <div className="flex flex-col items-center justify-center py-12 gap-4"><RefreshCw className="animate-spin text-blue-500" size={30}/><p className="text-xs text-slate-400">正在分析庫存大數據...</p></div> : aiInsights || "點擊上方按鈕，讓 Gemini 為您提供專業建議。"}
                </div>
              </div>
            </div>
          </div>
        )}
      </main>

      {/* 刪除確認彈窗 (穩定版) */}
      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-sm p-12 shadow-2xl text-center text-black">
            <div className="w-20 h-20 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-8">
              <AlertTriangle size={40} />
            </div>
            <h3 className="text-2xl font-black mb-3">刪除確認</h3>
            <p className="text-slate-500 font-bold mb-10">
              您即將刪除：<br/><span className="text-red-600 font-black">「{deleteTarget.name}」</span><br/>此操作無法恢復。
            </p>
            <div className="flex flex-col gap-3">
              <button onClick={confirmDelete} className="w-full py-5 bg-red-600 text-white rounded-2xl font-black text-lg hover:bg-red-700 shadow-xl">確認刪除</button>
              <button onClick={() => setDeleteTarget(null)} className="w-full py-5 bg-slate-100 text-slate-400 rounded-2xl font-black text-lg hover:bg-slate-200">取消返回</button>
            </div>
          </div>
        </div>
      )}

      {/* 新增耗材彈窗 (修正底色) */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 text-black">
          <div className="bg-white rounded-[3rem] w-full max-w-md p-10 shadow-2xl">
            <div className="flex justify-between items-center mb-10">
              <h3 className="font-black text-3xl">新增工安耗材</h3>
              <button onClick={()=>setShowAddModal(false)} className="p-2 bg-slate-100 rounded-full hover:bg-slate-200 transition-all"><X/></button>
            </div>
            <div className="space-y-6">
              <div>
                <label className="block text-xs font-black text-slate-400 mb-2">耗材名稱</label>
                <input type="text" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold bg-white text-black text-lg outline-none focus:border-blue-500" value={newForm.name} onChange={e=>setNewForm({...newForm,name:e.target.value})}/>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-2">單位 (如: 雙, 個)</label>
                  <input type="text" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold bg-white text-black text-lg outline-none" value={newForm.unit} onChange={e=>setNewForm({...newForm,unit:e.target.value})}/>
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-2">安全警戒線</label>
                  <input type="number" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold bg-white text-black text-lg outline-none" value={newForm.minStock} onChange={e=>setNewForm({...newForm,minStock:Number(e.target.value)})}/>
                </div>
              </div>
              <button onClick={handleAddItem} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl mt-4 shadow-xl hover:bg-blue-700 transition-all active:scale-95">確認並儲存資料</button>
            </div>
          </div>
        </div>
      )}

      {/* 列印預覽 (正式台電格式) */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-slate-900/95 z-[100] flex flex-col items-center justify-start p-10 text-black overflow-y-auto">
          <div className="bg-white rounded-3xl w-full max-w-5xl p-8 relative shadow-2xl my-4">
            <div className="flex justify-between items-center mb-8 no-print border-b pb-4">
               <div className="flex items-center gap-3">
                 <Printer className="text-blue-600" size={28}/>
                 <span className="font-black text-2xl text-black">正式單據列印預覽 (字體：標楷體)</span>
               </div>
               <div className="flex gap-4">
                 <button onClick={()=>window.print()} className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black text-xl hover:bg-blue-700 shadow-lg active:scale-95 transition-all">執行列印 (A4)</button>
                 <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full hover:bg-slate-200"><X size={24} className="text-black"/></button>
               </div>
            </div>
            <div className="flex justify-center bg-white">
               <PrintableForm transaction={lastTransaction} />
            </div>
          </div>
        </div>
      )}

      {/* 列印專用 (瀏覽器渲染區) */}
      <div className="hidden print:block absolute top-0 left-0 w-full">
         {lastTransaction && <PrintableForm transaction={lastTransaction} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  RefreshCw,
  Search,
  X,
  Printer,
  Download,
  Upload,
  AlertTriangle,
  BrainCircuit,
  TrendingDown,
  Calendar
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v8_items';
const STORAGE_KEY_LOGS = 'safeman_v8_logs';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<number>(1);
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [inputDept, setInputDept] = useState('南部分處');

  const fileInputRef = useRef<HTMLInputElement>(null);

  // 初始化
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  // 存檔
  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  // AI 分析
  useEffect(() => {
    if (activeTab === 'dashboard' && items.length > 0 && !aiInsights) {
      handleGetAiInsights();
    }
  }, [activeTab]);

  const handleGetAiInsights = async () => {
    setIsAiLoading(true);
    const result = await getInventoryInsights(items);
    setAiInsights(result);
    setIsAiLoading(false);
  };

  const generateId = () => `ID-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

  const confirmDelete = () => {
    if (!deleteTarget) return;
    setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  const handleTransaction = () => {
    if (!selectedItemId) return alert('請先選擇一個耗材項目');
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    const qty = Number(inputQty);
    if (isNaN(qty) || qty <= 0) return alert('請輸入大於 0 的領用數量');

    // 庫存警告攔截 (強制修正)
    if (issuanceMode === 'OUT') {
      const currentStock = Number(targetItem.quantity);
      if (qty > currentStock) {
        window.alert(`❌ 警告：庫存不足！\n\n項目名稱：${targetItem.name}\n目前庫存：${currentStock} ${targetItem.unit}\n領用量：${qty} ${targetItem.unit}\n\n無法完成領用程序，請確認數量或先進行補貨。`);
        return; // 中斷程序
      }
    }

    setItems(prev => prev.map(item => 
      item.id === selectedItemId 
        ? { ...item, quantity: issuanceMode === 'IN' ? item.quantity + qty : item.quantity - qty, lastUpdated: Date.now() } 
        : item
    ));

    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: qty,
      person: issuanceMode === 'OUT' ? (inputPerson || '未填寫') : '庫存補貨',
      reason: issuanceMode === 'OUT' ? (inputReason || '公務領用') : '定期補貨入庫',
      timestamp: Date.now()
    };

    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      alert('補貨入庫完成！');
    }

    setSelectedItemId(''); setInputQty(1); setInputPerson(''); setInputReason('');
  };

  // 修改耗材功能
  const handleEditItem = (updatedItem: InventoryItem) => {
    setItems(prev => prev.map(item => item.id === updatedItem.id ? updatedItem : item));
    setEditTarget(null);
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    unit: '個',
    minStock: 5,
    quantity: 0
  });

  const handleAddItem = () => {
    if (!newForm.name.trim()) return alert('請輸入耗材名稱');
    const newItem: InventoryItem = {
      id: generateId(),
      name: newForm.name.trim(),
      category: newForm.category,
      unit: newForm.unit || '個',
      quantity: Number(newForm.quantity) || 0,
      minStock: Number(newForm.minStock) || 0,
      description: '',
      lastUpdated: Date.now()
    };
    setItems(prev => [...prev, newItem]);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, unit: '個', minStock: 5, quantity: 0 });
  };

  // 領用單元件 (完美依照圖片格式)
  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const date = new Date(transaction.timestamp);
    const emptyRows = Array(15).fill(null); // 補滿 15 行空白行

    return (
      <div className="print-area bg-white text-black p-6 w-[210mm] mx-auto overflow-hidden" id="official-form-v2">
        <style>{`
          @font-face {
            font-family: 'StandardKai';
            src: local('標楷體'), local('DFKai-SB'), local('BiauKai');
          }
          #official-form-v2 {
            font-family: 'StandardKai', serif;
            font-size: 14pt;
            color: black !important;
          }
          #official-form-v2 table {
            border-collapse: collapse;
            width: 100%;
            border: 2px solid black;
          }
          #official-form-v2 th, #official-form-v2 td {
            border: 1.5px solid black;
            padding: 6px 10px;
            height: 38px;
            text-align: center;
            color: black !important;
          }
          @media print {
            .no-print { display: none !important; }
            body { background: white; margin: 0; padding: 0; }
            #official-form-v2 { padding: 0; width: 100%; }
          }
        `}</style>

        <h1 className="text-center text-3xl font-bold mb-4">台灣電力公司電力修護處南部分處</h1>

        <div className="flex justify-center gap-12 mb-6 font-bold">
          <label className="flex items-center gap-2">
            <span className="w-5 h-5 border-2 border-black inline-block"></span>
            安全衛生設備借用單
          </label>
          <label className="flex items-center gap-2">
            <span className="w-5 h-5 border-2 border-black inline-flex items-center justify-center font-black">V</span>
            安全衛生類消耗品領用單
          </label>
        </div>

        <div className="flex justify-between mb-2 font-bold px-1">
          <div>部門：<span className="inline-block border-b-2 border-dotted border-black min-w-[180px]">{inputDept}</span></div>
          <div>{date.getFullYear() - 1911} 年 {date.getMonth() + 1} 月 {date.getDate()} 日</div>
        </div>

        <table>
          <thead>
            <tr className="font-bold">
              <th className="w-[35%]">名　　　　　稱</th>
              <th className="w-[25%]">規　範（序　號）</th>
              <th className="w-[10%]">單位</th>
              <th className="w-[10%]">數量</th>
              <th className="w-[20%]">備　　　　　註</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td className="text-left font-bold">{transaction.itemName}</td>
              <td className="text-xs">{transaction.id.split('-')[1]}</td>
              <td>{targetItem?.unit || '個'}</td>
              <td className="font-black">{transaction.quantity}</td>
              <td className="text-left text-xs">{transaction.reason}</td>
            </tr>
            {emptyRows.map((_, idx) => (
              <tr key={idx}><td /><td /><td /><td /><td /></tr>
            ))}
          </tbody>
        </table>

        <div className="mt-8 font-bold flex flex-col gap-8">
          <div className="flex justify-between px-1">
             <div>申請部門：<span className="inline-block border-b-2 border-dotted border-black min-w-[220px]">{transaction.person}</span></div>
             <div>經管部門：____________________</div>
          </div>

          <div className="grid grid-cols-2 gap-10 mt-4">
             <div className="flex gap-4">
                <div>經辦：__________</div>
                <div>課長：__________</div>
                <div>經理：__________</div>
             </div>
             <div className="flex gap-4">
                <div>經辦：__________</div>
                <div>課長：__________</div>
                <div>經理：__________</div>
             </div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-slate-100 text-slate-900 font-sans">
      <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={e => {
        const file = e.target.files?.[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (event) => {
          try {
            const data = JSON.parse(event.target?.result as string);
            if (data.items) {
              setItems(data.items);
              setLogs(data.logs || []);
              alert('匯入成功');
            }
          } catch { alert('格式錯誤'); }
        };
        reader.readAsText(file);
      }} />

      {/* 側邊導覽 */}
      <aside className="no-print w-72 bg-slate-900 text-white p-8 flex flex-col shrink-0">
        <div className="flex items-center gap-3 mb-12">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg"><Package size={22}/></div>
          <div><h1 className="font-black text-lg leading-tight">工安管理系統</h1><p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Official v8.5</p></div>
        </div>

        <nav className="flex-1 space-y-2">
          {[
            { id: 'inventory', label: '耗材清冊', icon: Package },
            { id: 'issuance', label: '領用與補貨', icon: FileText },
            { id: 'history', label: '紀錄查詢', icon: History },
            { id: 'dashboard', label: '數據儀表板', icon: LayoutDashboard },
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 shadow-lg text-white' : 'text-slate-400 hover:bg-slate-800'}`}>
              <tab.icon size={20} /> {tab.label}
            </button>
          ))}
        </nav>

        <div className="mt-8 pt-8 border-t border-slate-800 space-y-3">
          <button onClick={() => {
            const blob = new Blob([JSON.stringify({items, logs})], {type: 'application/json'});
            const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = '工安資料備份.json'; a.click();
          }} className="w-full flex items-center gap-3 px-4 py-3 bg-slate-800 rounded-xl text-xs font-bold hover:bg-slate-700">
            <Download size={14} className="text-blue-400" /> 備份資料
          </button>
        </div>
      </aside>

      {/* 主內容區 */}
      <main className="no-print flex-1 p-10 overflow-y-auto">
        <header className="mb-10 flex justify-between items-center">
          <h2 className="text-4xl font-black text-slate-900">
            {activeTab === 'inventory' ? '耗材清冊' : activeTab === 'issuance' ? '領用登記' : activeTab === 'history' ? '歷史日誌' : '智慧分析'}
          </h2>
          {activeTab === 'inventory' && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black flex items-center gap-3 shadow-xl hover:bg-black transition-all">
              <Plus size={20}/> 新增耗材
            </button>
          )}
        </header>

        {activeTab === 'inventory' && (
          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 overflow-hidden text-black">
            <div className="p-8 bg-slate-50 border-b flex items-center gap-6">
               <div className="relative flex-1">
                 <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                 <input type="text" placeholder="搜尋耗材..." className="w-full pl-14 pr-6 py-4 bg-white border-2 border-slate-200 rounded-2xl font-bold outline-none focus:border-blue-500 text-black shadow-inner" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
               </div>
            </div>
            <table className="w-full text-left">
              <thead>
                <tr className="text-[11px] font-black text-slate-400 uppercase tracking-widest border-b">
