                <div className="grid grid-cols-2 gap-8">
                  <div>
                    <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">操作數量</label>
                    <input type="number" min="1" className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold bg-white text-black text-xl outline-none" value={inputQty} onChange={e=>setInputQty(Number(e.target.value))}/>
                  </div>
                  {issuanceMode === 'OUT' && (
                    <div>
                      <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">領用人 / 申請部門</label>
                      <input type="text" className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold bg-white text-black text-xl outline-none" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/>
                    </div>
                  )}
                </div>

                {issuanceMode === 'OUT' && (
                  <div>
                    <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">備註用途</label>
                    <textarea className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold bg-white text-black outline-none h-24" value={inputReason} onChange={e=>setInputReason(e.target.value)}></textarea>
                  </div>
                )}

                <button onClick={handleTransaction} className={`w-full py-6 rounded-2xl font-black text-white text-2xl shadow-2xl transition-all ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>
                  {issuanceMode === 'OUT' ? '產出領用單並核銷' : '確認補貨入庫'}
                </button>
             </div>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 overflow-hidden text-black">
             <table className="w-full text-left">
               <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase border-b">
                 <tr><th className="px-10 py-6">異動日期</th><th className="px-10 py-6">耗材</th><th className="px-10 py-6">人員</th><th className="px-10 py-6">類型</th><th className="px-10 py-6 text-right">單據</th></tr>
               </thead>
               <tbody className="divide-y divide-slate-50">
                 {logs.map(log => (
                   <tr key={log.id} className="hover:bg-slate-50">
                     <td className="px-10 py-6 text-xs text-slate-400 font-mono font-bold">{new Date(log.timestamp).toLocaleString()}</td>
                     <td className="px-10 py-6 font-black">{log.itemName} (x{log.quantity})</td>
                     <td className="px-10 py-6 text-slate-600 font-bold">{log.person}</td>
                     <td className="px-10 py-6">
                        {log.type === 'OUT' ? <span className="text-blue-600 font-black">領用</span> : <span className="text-emerald-600 font-black">補貨</span>}
                     </td>
                     <td className="px-10 py-6 text-right">
                        {log.type === 'OUT' && <button onClick={()=>{setLastTransaction(log);setShowPrintModal(true);}} className="text-blue-600 p-3 hover:bg-blue-50 rounded-xl"><Printer size={18}/></button>}
                     </td>
                   </tr>
                 ))}
               </tbody>
             </table>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8 text-black">
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100"><p className="text-slate-400 font-black text-xs mb-3">總項目數</p><p className="text-6xl font-black">{items.length}</p></div>
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border-l-8 border-l-red-500"><p className="text-red-500 font-black text-xs mb-3">低庫存警告</p><p className="text-6xl font-black text-red-600">{items.filter(i=>i.quantity<=i.minStock).length}</p></div>
              <div className="bg-slate-900 p-10 rounded-[2.5rem] shadow-2xl text-white relative overflow-hidden">
                <BrainCircuit className="absolute -right-6 -bottom-6 text-white/5" size={160} />
                <button onClick={handleGetAiInsights} disabled={isAiLoading} className="px-6 py-3 bg-blue-600 rounded-xl font-bold text-sm hover:bg-blue-500 transition-all">
                  {isAiLoading ? '分析中...' : '重新產出 AI 建議'}
                </button>
              </div>
            </div>
            <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100 font-bold text-slate-700 whitespace-pre-wrap leading-relaxed">
              {aiInsights || "數據分析後將顯示建議內容。"}
            </div>
          </div>
        )}
      </main>

      {/* 修改視窗 */}
      {editTarget && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[200] flex items-center justify-center p-4 text-black">
          <div className="bg-white rounded-[3rem] w-full max-w-md p-10 shadow-2xl">
            <div className="flex justify-between items-center mb-8">
              <h3 className="font-black text-3xl">編輯耗材資訊</h3>
              <button onClick={()=>setEditTarget(null)} className="p-2 bg-slate-100 rounded-full"><X/></button>
            </div>
            <div className="space-y-6">
              <div><label className="block text-xs font-black text-slate-400 mb-2">耗材名稱</label><input type="text" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold bg-white text-black" value={editTarget.name} onChange={e=>setEditTarget({...editTarget, name: e.target.value})}/></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="block text-xs font-black text-slate-400 mb-2">單位</label><input type="text" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold" value={editTarget.unit} onChange={e=>setEditTarget({...editTarget, unit: e.target.value})}/></div>
                <div><label className="block text-xs font-black text-slate-400 mb-2">安全水位</label><input type="number" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold" value={editTarget.minStock} onChange={e=>setEditTarget({...editTarget, minStock: Number(e.target.value)})}/></div>
              </div>
              <button onClick={()=>handleEditItem(editTarget)} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl">更新資料</button>
            </div>
          </div>
        </div>
      )}

      {/* 刪除視窗 */}
      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-sm p-12 shadow-2xl text-center text-black">
            <AlertTriangle className="text-red-600 mx-auto mb-6" size={48} />
            <h3 className="text-2xl font-black mb-3">確認刪除</h3>
            <p className="text-slate-500 font-bold mb-10">將永久移除「{deleteTarget.name}」，確定嗎？</p>
            <div className="flex flex-col gap-3">
              <button onClick={confirmDelete} className="w-full py-4 bg-red-600 text-white rounded-2xl font-black">確定刪除</button>
              <button onClick={()=>setDeleteTarget(null)} className="w-full py-4 bg-slate-100 text-slate-400 rounded-2xl font-black">取消</button>
            </div>
          </div>
        </div>
      )}

      {/* 新增視窗 */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 text-black">
          <div className="bg-white rounded-[3rem] w-full max-w-md p-10 shadow-2xl">
            <div className="flex justify-between items-center mb-8">
              <h3 className="font-black text-3xl">新增工安耗材</h3>
              <button onClick={()=>setShowAddModal(false)} className="p-2 bg-slate-100 rounded-full"><X/></button>
            </div>
            <div className="space-y-6">
              <div><label className="block text-xs font-black text-slate-400 mb-2">名稱</label><input type="text" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold bg-white text-black" value={newForm.name} onChange={e=>setNewForm({...newForm, name: e.target.value})}/></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="block text-xs font-black text-slate-400 mb-2">單位</label><input type="text" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold bg-white text-black" value={newForm.unit} onChange={e=>setNewForm({...newForm, unit: e.target.value})}/></div>
                <div><label className="block text-xs font-black text-slate-400 mb-2">安全水位</label><input type="number" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold bg-white text-black" value={newForm.minStock} onChange={e=>setNewForm({...newForm, minStock: Number(e.target.value)})}/></div>
              </div>
              <button onClick={handleAddItem} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl">儲存資料</button>
            </div>
          </div>
        </div>
      )}

      {/* 列印預覽 */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-slate-900/95 z-[100] flex flex-col items-center justify-start p-10 text-black overflow-y-auto">
          <div className="bg-white rounded-3xl w-full max-w-5xl p-10 relative shadow-2xl my-4">
            <div className="flex justify-between items-center mb-8 no-print border-b pb-4">
               <div className="flex items-center gap-3">
                 <Printer className="text-blue-600" size={28}/><span className="font-black text-2xl text-black">正式單據預覽 (標楷體 14pt)</span>
               </div>
               <div className="flex gap-4">
                 <button onClick={()=>window.print()} className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black text-xl shadow-lg">執行列印 (A4)</button>
                 <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full hover:bg-slate-200"><X size={24} className="text-black"/></button>
               </div>
            </div>
            <div className="flex justify-center bg-white">
               <PrintableForm transaction={lastTransaction} />
            </div>
          </div>
        </div>
      )}

      <div className="hidden print:block absolute top-0 left-0 w-full">
         {lastTransaction && <PrintableForm transaction={lastTransaction} />}
      </div>
    </div>
  );
};

export default App;

export enum Category {
  PROTECTION = '個人防護 (PPE)',
  FIRE_SAFETY = '消防安全',
  FIRST_AID = '急救耗材',
  SIGNAGE = '標誌警告',
  TOOL = '工具設備',
  OTHER = '其他'
}

export interface InventoryItem {
  id: string;
  name: string;
  category: Category;
  unit: string;
  spec: string; // 新增規格欄位
  quantity: number;
  minStock: number;
  description: string;
  lastUpdated: number;
}

export type TransactionType = 'IN' | 'OUT';

export interface Transaction {
  id: string;
  itemId: string;
  itemName: string;
  type: TransactionType;
  quantity: number;
  person: string;
  reason: string;
  timestamp: number;
}

export interface DashboardStats {
  totalItems: number;
  lowStockItems: number;
  monthlyOutbound: number;
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  RefreshCw,
  Search,
  X,
  Printer,
  Download,
  Upload,
  AlertTriangle,
  BrainCircuit,
  TrendingDown,
  Calendar
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v8_items';
const STORAGE_KEY_LOGS = 'safeman_v8_logs';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<number>(1);
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [inputDept, setInputDept] = useState('南部分處');

  const fileInputRef = useRef<HTMLInputElement>(null);

  // 初始化
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  // 存檔
  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  // AI 分析
  useEffect(() => {
    if (activeTab === 'dashboard' && items.length > 0 && !aiInsights) {
      handleGetAiInsights();
    }
  }, [activeTab]);

  const handleGetAiInsights = async () => {
    setIsAiLoading(true);
    const result = await getInventoryInsights(items);
    setAiInsights(result);
    setIsAiLoading(false);
  };

  const generateId = () => `ID-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

  const confirmDelete = () => {
    if (!deleteTarget) return;
    setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  const handleTransaction = () => {
    if (!selectedItemId) return alert('請先選擇一個耗材項目');
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    const qty = Number(inputQty);
    if (isNaN(qty) || qty <= 0) return alert('請輸入大於 0 的領用數量');

    // 庫存警告攔截 (核心修正)
    if (issuanceMode === 'OUT') {
      const currentStock = Number(targetItem.quantity);
      if (qty > currentStock) {
        // 使用 window.alert 確保阻塞式警告
        window.alert(`❌ 警告：庫存不足！\n\n項目名稱：${targetItem.name}\n目前庫存：${currentStock} ${targetItem.unit}\n欲領用量：${qty} ${targetItem.unit}\n\n庫存不足以支應此次領用，請調整數量或先執行補貨。`);
        return; // 絕對停止後續執行
      }
    }

    setItems(prev => prev.map(item => 
      item.id === selectedItemId 
        ? { ...item, quantity: issuanceMode === 'IN' ? item.quantity + qty : item.quantity - qty, lastUpdated: Date.now() } 
        : item
    ));

    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: qty,
      person: issuanceMode === 'OUT' ? (inputPerson || '未填寫') : '庫存補貨',
      reason: issuanceMode === 'OUT' ? (inputReason || '公務領用') : '定期補貨入庫',
      timestamp: Date.now()
    };

    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      alert('補貨入庫完成！');
    }

    setSelectedItemId(''); setInputQty(1); setInputPerson(''); setInputReason('');
  };

  // 修改耗材功能
  const handleEditItem = (updatedItem: InventoryItem) => {
    setItems(prev => prev.map(item => item.id === updatedItem.id ? updatedItem : item));
    setEditTarget(null);
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    unit: '個',
    spec: '',
    minStock: 5,
    quantity: 0
  });

  const handleAddItem = () => {
    if (!newForm.name.trim()) return alert('請輸入耗材名稱');
    const newItem: InventoryItem = {
      id: generateId(),
      name: newForm.name.trim(),
      category: newForm.category,
      unit: newForm.unit || '個',
      spec: newForm.spec || '',
      quantity: Number(newForm.quantity) || 0,
      minStock: Number(newForm.minStock) || 0,
      description: '',
      lastUpdated: Date.now()
    };
    setItems(prev => [...prev, newItem]);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, unit: '個', spec: '', minStock: 5, quantity: 0 });
  };

  // 領用單元件 (完美依照圖片格式)
  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const date = new Date(transaction.timestamp);
    const emptyRows = Array(15).fill(null); // 補滿 15 行空白行

    return (
      <div className="print-area bg-white text-black p-6 w-[210mm] mx-auto overflow-hidden" id="official-form-v2">
        <style>{`
          @font-face {
            font-family: 'StandardKai';
            src: local('標楷體'), local('DFKai-SB'), local('BiauKai');
          }
          #official-form-v2 {
            font-family: 'StandardKai', serif;
            font-size: 14pt;
            color: black !important;
          }
          #official-form-v2 table {
            border-collapse: collapse;
            width: 100%;
            border: 2px solid black;
          }
          #official-form-v2 th, #official-form-v2 td {
            border: 1.5px solid black;
            padding: 6px 10px;
            height: 38px;
            text-align: center;
            color: black !important;
          }
          @media print {
            .no-print { display: none !important; }
            body { background: white; margin: 0; padding: 0; }
            #official-form-v2 { padding: 0; width: 100%; }
          }
        `}</style>

        <h1 className="text-center text-3xl font-bold mb-4">台灣電力公司電力修護處南部分處</h1>

        <div className="flex justify-center gap-12 mb-6 font-bold">
          <label className="flex items-center gap-2">
            <span className="w-5 h-5 border-2 border-black inline-block"></span>
            安全衛生設備借用單
          </label>
          <label className="flex items-center gap-2">
            <span className="w-5 h-5 border-2 border-black inline-flex items-center justify-center font-black">V</span>
            安全衛生類消耗品領用單
          </label>
        </div>

        <div className="flex justify-between mb-2 font-bold px-1">
          <div>部門：<span className="inline-block border-b-2 border-dotted border-black min-w-[180px] text-center">{inputDept}</span></div>
          <div>{date.getFullYear() - 1911} 年 {date.getMonth() + 1} 月 {date.getDate()} 日</div>
        </div>

        <table>
          <thead>
            <tr className="font-bold">
              <th className="w-[35%]">名　　　　　稱</th>
              <th className="w-[25%]">規　範（序　號）</th>
              <th className="w-[10%]">單位</th>
              <th className="w-[10%]">數量</th>
              <th className="w-[20%]">備　　　　　註</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td className="text-left font-bold">{transaction.itemName}</td>
              <td className="text-sm">{targetItem?.spec || ''}</td>
              <td>{targetItem?.unit || '個'}</td>
              <td className="font-black">{transaction.quantity}</td>
              <td className="text-left text-xs">{transaction.reason}</td>
            </tr>
            {emptyRows.map((_, idx) => (
              <tr key={idx}><td /><td /><td /><td /><td /></tr>
            ))}
          </tbody>
        </table>

        <div className="mt-8 font-bold flex flex-col gap-8">
          <div className="flex justify-between px-1">
             <div>申請部門：<span className="inline-block border-b-2 border-dotted border-black min-w-[220px] text-center">{transaction.person}</span></div>
             <div>經管部門：____________________</div>
          </div>

          <div className="grid grid-cols-2 gap-10 mt-4">
             <div className="flex gap-4">
                <div>經辦：__________</div>
                <div>課長：__________</div>
                <div>經理：__________</div>
             </div>
             <div className="flex gap-4">
                <div>經辦：__________</div>
                <div>課長：__________</div>
                <div>經理：__________</div>
             </div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-slate-100 text-slate-900 font-sans">
      <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={e => {
        const file = e.target.files?.[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (event) => {
          try {
            const data = JSON.parse(event.target?.result as string);
            if (data.items) {
              setItems(data.items);
              setLogs(data.logs || []);
              alert('匯入成功');
            }
          } catch { alert('格式錯誤'); }
        };
        reader.readAsText(file);
      }} />

      {/* 側邊導覽 */}
      <aside className="no-print w-72 bg-slate-900 text-white p-8 flex flex-col shrink-0">
        <div className="flex items-center gap-3 mb-12">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg"><Package size={22}/></div>
          <div><h1 className="font-black text-lg leading-tight">工安管理系統</h1><p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Official v8.6</p></div>
        </div>

        <nav className="flex-1 space-y-2">
          {[
            { id: 'inventory', label: '耗材清冊', icon: Package },
            { id: 'issuance', label: '領用與補貨', icon: FileText },
            { id: 'history', label: '紀錄查詢', icon: History },
            { id: 'dashboard', label: '數據儀表板', icon: LayoutDashboard },
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 shadow-lg text-white' : 'text-slate-400 hover:bg-slate-800'}`}>
              <tab.icon size={20} /> {tab.label}
            </button>
          ))}
        </nav>

        <div className="mt-8 pt-8 border-t border-slate-800 space-y-3">
          <button onClick={() => {
            const blob = new Blob([JSON.stringify({items, logs})], {type: 'application/json'});
            const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = '工安資料備份.json'; a.click();
          }} className="w-full flex items-center gap-3 px-4 py-3 bg-slate-800 rounded-xl text-xs font-bold hover:bg-slate-700">
            <Download size={14} className="text-blue-400" /> 備份資料
          </button>
        </div>
      </aside>

      {/* 主內容區 */}
      <main className="no-print flex-1 p-10 overflow-y-auto">
        <header className="mb-10 flex justify-between items-center">
          <h2 className="text-4xl font-black text-slate-900">
            {activeTab === 'inventory' ? '耗材清冊' : activeTab === 'issuance' ? '領用登記' : activeTab === 'history' ? '歷史日誌' : '智慧分析'}
          </h2>
          {activeTab === 'inventory' && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black flex items-center gap-3 shadow-xl hover:bg-black transition-all">
              <Plus size={20}/> 新增耗材
            </button>
          )}
        </header>

        {activeTab === 'inventory' && (
          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 overflow-hidden text-slate-900">
            <div className="p-8 bg-slate-50 border-b flex items-center gap-6">
               <div className="relative flex-1">
                 <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                 <input type="text" placeholder="搜尋耗材..." className="w-full pl-14 pr-6 py-4 bg-white border-2 border-slate-200 rounded-2xl font-bold outline-none focus:border-blue-500 text-slate-900 shadow-inner" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
               </div>
            </div>
            <table className="w-full text-left">
              <thead>
                <tr className="text-[11px] font-black text-slate-400 uppercase tracking-widest border-b">
                  <th className="px-10 py-6">耗材名稱 / 規格</th>
                  <th className="px-10 py-6 text-center">現有數量</th>
                  <th className="px-10 py-6 text-center">警戒值</th>
                  <th className="px-10 py-6 text-right">管理操作</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                  <tr key={item.id} className="group hover:bg-slate-50 transition-all">
                    <td className="px-10 py-7">
                      <div className="font-black text-lg text-slate-900">{item.name}</div>
                      <div className="text-xs text-slate-500 font-bold">{item.spec || '無規格'}</div>
                    </td>
                    <td className="px-10 py-7 text-center">
                      <span className={`px-5 py-2 rounded-xl text-sm font-black ${item.quantity <= item.minStock ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>
                        {item.quantity} {item.unit}
                      </span>
                    </td>
                    <td className="px-10 py-7 text-center font-bold text-slate-500">{item.minStock}</td>
                    <td className="px-10 py-7 text-right flex items-center justify-end gap-2">
                      <button onClick={() => setEditTarget(item)} className="p-3 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all">
                        <Edit3 size={18} />
                      </button>
                      <button onClick={() => setDeleteTarget({id: item.id, name: item.name})} className="p-3 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all">
                        <Trash2 size={18} />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'issuance' && (
          <div className="max-w-2xl mx-auto bg-white p-12 rounded-[3rem] shadow-xl border border-slate-100 text-slate-900">
             <div className="flex bg-slate-100 p-2 rounded-2xl mb-12">
               <button onClick={()=>setIssuanceMode('OUT')} className={`flex-1 py-5 rounded-xl font-black text-lg transition-all ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button>
               <button onClick={()=>setIssuanceMode('IN')} className={`flex-1 py-5 rounded-xl font-black text-lg transition-all ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
             </div>

             <div className="space-y-8">
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">選取耗材項目</label>
                  <select className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold bg-white text-slate-900 text-xl outline-none focus:border-blue-600 transition-all" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                    <option value="">-- 請從清單中選取 --</option>
                    {items.map(i=><option key={i.id} value={i.id}>{i.name} {i.spec ? `(${i.spec})` : ''} - 剩餘: {i.quantity} {i.unit}</option>)}
                  </select>
                </div>

                <div className="grid grid-cols-2 gap-8">
                  <div>
                    <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">操作數量</label>
                    <input type="number" min="1" className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold bg-white text-slate-900 text-xl outline-none" value={inputQty} onChange={e=>setInputQty(Number(e.target.value))}/>
                  </div>
                  {issuanceMode === 'OUT' && (
                    <div>
                      <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">領用人 / 申請部門</label>
                      <input type="text" className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold bg-white text-slate-900 text-xl outline-none" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/>
                    </div>
                  )}
                </div>

                {issuanceMode === 'OUT' && (
                  <div>
                    <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">備註用途</label>
                    <textarea className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold bg-white text-slate-900 outline-none h-24" value={inputReason} onChange={e=>setInputReason(e.target.value)}></textarea>
                  </div>
                )}

                <button onClick={handleTransaction} className={`w-full py-6 rounded-2xl font-black text-white text-2xl shadow-2xl transition-all ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>
                  {issuanceMode === 'OUT' ? '列印領用單並更新' : '確認補貨入庫'}
                </button>
             </div>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 overflow-hidden text-slate-900">
             <table className="w-full text-left">
               <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase border-b">
                 <tr><th className="px-10 py-6">異動日期</th><th className="px-10 py-6">耗材</th><th className="px-10 py-6">人員</th><th className="px-10 py-6">類型</th><th className="px-10 py-6 text-right">單據</th></tr>
               </thead>
               <tbody className="divide-y divide-slate-50">
                 {logs.map(log => (
                   <tr key={log.id} className="hover:bg-slate-50">
                     <td className="px-10 py-6 text-xs text-slate-400 font-mono font-bold">{new Date(log.timestamp).toLocaleString()}</td>
                     <td className="px-10 py-6 font-black text-slate-900">{log.itemName} (x{log.quantity})</td>
                     <td className="px-10 py-6 text-slate-600 font-bold">{log.person}</td>
                     <td className="px-10 py-6">
                        {log.type === 'OUT' ? <span className="text-blue-600 font-black">領用</span> : <span className="text-emerald-600 font-black">補貨</span>}
                     </td>
                     <td className="px-10 py-6 text-right">
                        {log.type === 'OUT' && <button onClick={()=>{setLastTransaction(log);setShowPrintModal(true);}} className="text-blue-600 p-3 hover:bg-blue-50 rounded-xl"><Printer size={18}/></button>}
                     </td>
                   </tr>
                 ))}
               </tbody>
             </table>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8 text-slate-900">
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100"><p className="text-slate-400 font-black text-xs mb-3">總項目數</p><p className="text-6xl font-black">{items.length}</p></div>
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border-l-8 border-l-red-500"><p className="text-red-500 font-black text-xs mb-3">低庫存警告</p><p className="text-6xl font-black text-red-600">{items.filter(i=>i.quantity<=i.minStock).length}</p></div>
              <div className="bg-slate-900 p-10 rounded-[2.5rem] shadow-2xl text-white relative overflow-hidden">
                <BrainCircuit className="absolute -right-6 -bottom-6 text-white/5" size={160} />
                <button onClick={handleGetAiInsights} disabled={isAiLoading} className="px-6 py-3 bg-blue-600 rounded-xl font-bold text-sm hover:bg-blue-500 transition-all">
                  {isAiLoading ? '分析中...' : '重新產出 AI 建議'}
                </button>
              </div>
            </div>
            <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100 font-bold text-slate-700 whitespace-pre-wrap leading-relaxed">
              {aiInsights || "數據分析後將顯示建議內容。"}
            </div>
          </div>
        )}
      </main>

      {/* 修改視窗 (UI 修正：底色改為白色) */}
      {editTarget && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[200] flex items-center justify-center p-4 text-slate-900">
          <div className="bg-white rounded-[3rem] w-full max-w-md p-10 shadow-2xl">
            <div className="flex justify-between items-center mb-8">
              <h3 className="font-black text-3xl">編輯耗材資訊</h3>
              <button onClick={()=>setEditTarget(null)} className="p-2 bg-slate-100 rounded-full"><X/></button>
            </div>
            <div className="space-y-6">
              <div><label className="block text-xs font-black text-slate-400 mb-2">耗材名稱</label><input type="text" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold bg-white text-slate-900" value={editTarget.name} onChange={e=>setEditTarget({...editTarget, name: e.target.value})}/></div>
              <div><label className="block text-xs font-black text-slate-400 mb-2">規格規範</label><input type="text" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold bg-white text-slate-900" value={editTarget.spec} onChange={e=>setEditTarget({...editTarget, spec: e.target.value})}/></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="block text-xs font-black text-slate-400 mb-2">單位</label><input type="text" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold bg-white text-slate-900" value={editTarget.unit} onChange={e=>setEditTarget({...editTarget, unit: e.target.value})}/></div>
                <div><label className="block text-xs font-black text-slate-400 mb-2">安全水位</label><input type="number" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold bg-white text-slate-900" value={editTarget.minStock} onChange={e=>setEditTarget({...editTarget, minStock: Number(e.target.value)})}/></div>
              </div>
              <button onClick={()=>handleEditItem(editTarget)} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl">更新資料</button>
            </div>
          </div>
        </div>
      )}

      {/* 刪除視窗 */}
      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-sm p-12 shadow-2xl text-center text-slate-900">
            <AlertTriangle className="text-red-600 mx-auto mb-6" size={48} />
            <h3 className="text-2xl font-black mb-3">確認刪除</h3>
            <p className="text-slate-500 font-bold mb-10">將永久移除「{deleteTarget.name}」，確定嗎？</p>
            <div className="flex flex-col gap-3">
              <button onClick={confirmDelete} className="w-full py-4 bg-red-600 text-white rounded-2xl font-black">確定刪除</button>
              <button onClick={()=>setDeleteTarget(null)} className="w-full py-4 bg-slate-100 text-slate-400 rounded-2xl font-black">取消</button>
            </div>
          </div>
        </div>
      )}

      {/* 新增視窗 (規格欄位回復) */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 text-slate-900">
          <div className="bg-white rounded-[3rem] w-full max-w-md p-10 shadow-2xl">
            <div className="flex justify-between items-center mb-8">
              <h3 className="font-black text-3xl">新增工安耗材</h3>
              <button onClick={()=>setShowAddModal(false)} className="p-2 bg-slate-100 rounded-full"><X/></button>
            </div>
            <div className="space-y-6">
              <div><label className="block text-xs font-black text-slate-400 mb-2">耗材名稱</label><input type="text" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold bg-white text-slate-900" value={newForm.name} onChange={e=>setNewForm({...newForm, name: e.target.value})}/></div>
              <div><label className="block text-xs font-black text-slate-400 mb-2">規格規範</label><input type="text" placeholder="例: 3M-1234 或 尺寸L" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold bg-white text-slate-900" value={newForm.spec} onChange={e=>setNewForm({...newForm, spec: e.target.value})}/></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="block text-xs font-black text-slate-400 mb-2">單位</label><input type="text" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold bg-white text-slate-900" value={newForm.unit} onChange={e=>setNewForm({...newForm, unit: e.target.value})}/></div>
                <div><label className="block text-xs font-black text-slate-400 mb-2">安全水位</label><input type="number" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold bg-white text-slate-900" value={newForm.minStock} onChange={e=>setNewForm({...newForm, minStock: Number(e.target.value)})}/></div>
              </div>
              <button onClick={handleAddItem} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl">儲存資料</button>
            </div>
          </div>
        </div>
      )}

      {/* 列印預覽 */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-slate-900/95 z-[100] flex flex-col items-center justify-start p-10 text-slate-900 overflow-y-auto">
          <div className="bg-white rounded-3xl w-full max-w-5xl p-10 relative shadow-2xl my-4">
            <div className="flex justify-between items-center mb-8 no-print border-b pb-4">
               <div className="flex items-center gap-3">
                 <Printer className="text-blue-600" size={28}/><span className="font-black text-2xl text-slate-900">正式單據預覽 (標楷體 14pt)</span>
               </div>
               <div className="flex gap-4">
                 <button onClick={()=>window.print()} className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black text-xl shadow-lg">執行列印 (A4)</button>
                 <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full hover:bg-slate-200"><X size={24} className="text-slate-900"/></button>
               </div>
            </div>
            <div className="flex justify-center bg-white">
               <PrintableForm transaction={lastTransaction} />
            </div>
          </div>
        </div>
      )}

      <div className="hidden print:block absolute top-0 left-0 w-full">
         {lastTransaction && <PrintableForm transaction={lastTransaction} />}
      </div>
    </div>
  );
};

export default App;

export enum Category {
  PROTECTION = '個人防護 (PPE)',
  FIRE_SAFETY = '消防安全',
  FIRST_AID = '急救耗材',
  SIGNAGE = '標誌警告',
  TOOL = '工具設備',
  OTHER = '其他'
}

export interface InventoryItem {
  id: string;
  name: string;
  category: Category;
  unit: string;
  spec: string;
  quantity: number;
  minStock: number;
  description: string;
  lastUpdated: number;
}

export type TransactionType = 'IN' | 'OUT';

export interface Transaction {
  id: string;
  itemId: string;
  itemName: string;
  type: TransactionType;
  quantity: number;
  person: string;
  dept: string; // 新增部門欄位
  reason: string;
  timestamp: number;
}

export interface DashboardStats {
  totalItems: number;
  lowStockItems: number;
  monthlyOutbound: number;
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  RefreshCw,
  Search,
  X,
  Printer,
  Download,
  Upload,
  AlertTriangle,
  BrainCircuit,
  TrendingDown,
  Calendar,
  Users
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell,
  Legend
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v8_items';
const STORAGE_KEY_LOGS = 'safeman_v8_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<number>(1);
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // 初始化
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  // 存檔
  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  // AI 分析
  useEffect(() => {
    if (activeTab === 'dashboard' && items.length > 0 && !aiInsights) {
      handleGetAiInsights();
    }
  }, [activeTab]);

  const handleGetAiInsights = async () => {
    setIsAiLoading(true);
    const result = await getInventoryInsights(items);
    setAiInsights(result);
    setIsAiLoading(false);
  };

  const generateId = () => `ID-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

  const confirmDelete = () => {
    if (!deleteTarget) return;
    setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  const handleTransaction = () => {
    if (!selectedItemId) return alert('請先選擇一個耗材項目');
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    const qty = Number(inputQty);
    if (isNaN(qty) || qty <= 0) return alert('請輸入大於 0 的數量');

    // --- 強化庫存警示攔截 ---
    if (issuanceMode === 'OUT') {
      const currentStock = Number(targetItem.quantity);
      if (qty > currentStock) {
        window.alert(`❌ 警告：庫存不足！\n\n項目名稱：${targetItem.name}\n目前庫存：${currentStock} ${targetItem.unit}\n預計領用：${qty} ${targetItem.unit}\n\n無法完成領用，請修正數量。`);
        return; 
      }
    }
    // -----------------------

    setItems(prev => prev.map(item => 
      item.id === selectedItemId 
        ? { ...item, quantity: issuanceMode === 'IN' ? item.quantity + qty : item.quantity - qty, lastUpdated: Date.now() } 
        : item
    ));

    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: qty,
      person: issuanceMode === 'OUT' ? (inputPerson || '未填寫') : '補貨員',
      dept: issuanceMode === 'OUT' ? selectedDept : '管理部',
      reason: issuanceMode === 'OUT' ? (inputReason || '公務領用') : '定期補貨',
      timestamp: Date.now()
    };

    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      alert('補貨入庫已完成並更新。');
    }

    setSelectedItemId(''); setInputQty(1); setInputPerson(''); setInputReason('');
  };

  const handleEditItem = (updatedItem: InventoryItem) => {
    setItems(prev => prev.map(item => item.id === updatedItem.id ? updatedItem : item));
    setEditTarget(null);
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    unit: '個',
    spec: '',
    minStock: 5,
    quantity: 0
  });

  const handleAddItem = () => {
    if (!newForm.name.trim()) return alert('請輸入耗材名稱');
