                  {issuanceMode === 'OUT' ? (
                    <div>
                      <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">領用部門</label>
                      <select className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold bg-white text-slate-900 text-xl outline-none focus:border-blue-600" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>
                        {DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
                      </select>
                    </div>
                  ) : (
                    <div>
                       <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">目前日期</label>
                       <div className="w-full p-5 bg-slate-50 border-2 border-slate-100 rounded-2xl text-slate-400 font-bold text-xl">{new Date().toLocaleDateString()}</div>
                    </div>
                  )}
                </div>

                {issuanceMode === 'OUT' && (
                  <div className="grid grid-cols-2 gap-8">
                    <div>
                      <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">領用人姓名</label>
                      <input type="text" placeholder="請輸入姓名" className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold bg-white text-slate-900 text-xl outline-none" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/>
                    </div>
                    <div>
                      <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">備註</label>
                      <input type="text" placeholder="公務用途" className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold bg-white text-slate-900 text-xl outline-none" value={inputReason} onChange={e=>setInputReason(e.target.value)}/>
                    </div>
                  </div>
                )}

                <button onClick={handleTransaction} className={`w-full py-6 rounded-2xl font-black text-white text-2xl shadow-2xl transition-all active:scale-95 ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700 shadow-blue-500/20':'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-500/20'}`}>
                  {issuanceMode === 'OUT' ? '列印領用單並更新' : '確認補貨入庫'}
                </button>
             </div>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8 text-slate-900">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100 flex items-center justify-between">
                <div><p className="text-slate-400 font-black text-xs mb-3 uppercase tracking-widest">總項目數</p><p className="text-6xl font-black">{items.length}</p></div>
                <Package size={48} className="text-blue-100" />
              </div>
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border-l-8 border-l-red-500 flex items-center justify-between">
                <div><p className="text-red-500 font-black text-xs mb-3 uppercase tracking-widest">低庫存警戒</p><p className="text-6xl font-black text-red-600">{items.filter(i=>i.quantity<=i.minStock).length}</p></div>
                <AlertTriangle size={48} className="text-red-100" />
              </div>
              <div className="bg-slate-900 p-10 rounded-[2.5rem] shadow-2xl text-white relative overflow-hidden">
                <BrainCircuit className="absolute -right-6 -bottom-6 text-white/5" size={160} />
                <p className="text-blue-400 font-black text-xs mb-4">AI 管理決策建議</p>
                <button onClick={handleGetAiInsights} disabled={isAiLoading} className="px-6 py-3 bg-blue-600 rounded-xl font-bold text-sm hover:bg-blue-500 transition-all flex items-center gap-2">
                  {isAiLoading ? <RefreshCw className="animate-spin" size={16}/> : <BrainCircuit size={16}/>}
                  {isAiLoading ? '建議分析中...' : '產出優化建議'}
                </button>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100">
                <h3 className="text-xl font-black mb-8 flex items-center gap-2 text-slate-900"><Users size={20} className="text-blue-500"/> 各部門累計領用狀況</h3>
                <div className="h-[400px]">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={deptStats} layout="vertical" margin={{ left: 50, right: 30 }}>
                      <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
                      <XAxis type="number" hide />
                      <YAxis dataKey="name" type="category" tick={{fontSize: 12, fontWeight: 'bold', fill: '#64748b'}} width={100} />
                      <Tooltip contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} />
                      <Bar dataKey="count" name="件數" fill="#3b82f6" radius={[0, 8, 8, 0]} barSize={24} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>

              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100">
                <h3 className="text-xl font-black mb-8 flex items-center gap-2 text-slate-900"><BrainCircuit size={20} className="text-purple-500"/> 庫存趨勢 AI 分析</h3>
                <div className="bg-slate-50 p-8 rounded-3xl font-bold text-slate-600 whitespace-pre-wrap leading-relaxed min-h-[300px] shadow-inner">
                  {isAiLoading ? "正透過機器學習分析庫存流向..." : aiInsights || "點擊按鈕獲取庫存配置建議。"}
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 overflow-hidden text-slate-900">
             <table className="w-full text-left">
               <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase border-b">
                 <tr><th className="px-10 py-6">異動日期</th><th className="px-10 py-6">耗材名稱</th><th className="px-10 py-6">人員 / 部門</th><th className="px-10 py-6">類型</th><th className="px-10 py-6 text-right">操作</th></tr>
               </thead>
               <tbody className="divide-y divide-slate-50">
                 {logs.map(log => (
                   <tr key={log.id} className="hover:bg-slate-50">
                     <td className="px-10 py-6 text-xs text-slate-400 font-mono font-bold">{new Date(log.timestamp).toLocaleString()}</td>
                     <td className="px-10 py-6 font-black">{log.itemName} (x{log.quantity})</td>
                     <td className="px-10 py-6">
                        <div className="font-bold text-slate-900">{log.person}</div>
                        <div className="text-[10px] text-slate-400 font-black">{log.dept}</div>
                     </td>
                     <td className="px-10 py-6">
                        {log.type === 'OUT' ? <span className="text-blue-600 font-black">領用出庫</span> : <span className="text-emerald-600 font-black">進貨補庫</span>}
                     </td>
                     <td className="px-10 py-6 text-right">
                        {log.type === 'OUT' && <button onClick={()=>{setLastTransaction(log);setShowPrintModal(true);}} className="text-blue-600 p-3 hover:bg-blue-50 rounded-xl transition-all"><Printer size={18}/></button>}
                     </td>
                   </tr>
                 ))}
               </tbody>
             </table>
          </div>
        )}
      </main>

      {/* 修改視窗 */}
      {editTarget && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[200] flex items-center justify-center p-4 text-slate-900">
          <div className="bg-white rounded-[3rem] w-full max-w-md p-10 shadow-2xl">
            <div className="flex justify-between items-center mb-8">
              <h3 className="font-black text-3xl">編輯耗材資訊</h3>
              <button onClick={()=>setEditTarget(null)} className="p-2 bg-slate-100 rounded-full hover:bg-slate-200 transition-colors"><X/></button>
            </div>
            <div className="space-y-6">
              <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">耗材名稱</label><input type="text" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white text-slate-900 outline-none" value={editTarget.name} onChange={e=>setEditTarget({...editTarget, name: e.target.value})}/></div>
              <div>
                <label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">單據類別</label>
                <select className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white text-slate-900" value={editTarget.itemType} onChange={e=>setEditTarget({...editTarget, itemType: e.target.value as ItemType})}>
                  <option value="CONSUMABLE">安全衛生類消耗品</option>
                  <option value="EQUIPMENT">安全衛生設備</option>
                </select>
              </div>
              <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">規格規範</label><input type="text" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white text-slate-900" value={editTarget.spec} onChange={e=>setEditTarget({...editTarget, spec: e.target.value})}/></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">單位</label><input type="text" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white text-slate-900" value={editTarget.unit} onChange={e=>setEditTarget({...editTarget, unit: e.target.value})}/></div>
                <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">警戒水位</label><input type="number" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white text-slate-900" value={editTarget.minStock} onChange={e=>setEditTarget({...editTarget, minStock: Number(e.target.value)})}/></div>
              </div>
              <button onClick={()=>handleEditItem(editTarget)} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl hover:bg-blue-700 transition-all active:scale-95">完成更新</button>
            </div>
          </div>
        </div>
      )}

      {/* 新增視窗 */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 text-slate-900">
          <div className="bg-white rounded-[3rem] w-full max-w-md p-10 shadow-2xl">
            <div className="flex justify-between items-center mb-8">
              <h3 className="font-black text-3xl">新增耗材項目</h3>
              <button onClick={()=>setShowAddModal(false)} className="p-2 bg-slate-100 rounded-full hover:bg-slate-200 transition-colors"><X/></button>
            </div>
            <div className="space-y-5">
              <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">耗材名稱</label><input type="text" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white text-slate-900 outline-none" value={newForm.name} onChange={e=>setNewForm({...newForm, name: e.target.value})}/></div>
              <div>
                <label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">單據類別</label>
                <select className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white text-slate-900" value={newForm.itemType} onChange={e=>setNewForm({...newForm, itemType: e.target.value as ItemType})}>
                  <option value="CONSUMABLE">安全衛生類消耗品</option>
                  <option value="EQUIPMENT">安全衛生設備</option>
                </select>
              </div>
              <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">規格規範</label><input type="text" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white text-slate-900 outline-none" value={newForm.spec} onChange={e=>setNewForm({...newForm, spec: e.target.value})}/></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">單位</label><input type="text" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white text-slate-900 outline-none" value={newForm.unit} onChange={e=>setNewForm({...newForm, unit: e.target.value})}/></div>
                <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">警戒水位</label><input type="number" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white text-slate-900 outline-none" value={newForm.minStock} onChange={e=>setNewForm({...newForm, minStock: Number(e.target.value)})}/></div>
              </div>
              <button onClick={handleAddItem} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl hover:bg-blue-700 transition-all active:scale-95">確認新增</button>
            </div>
          </div>
        </div>
      )}

      {/* 刪除確認 */}
      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-sm p-12 shadow-2xl text-center text-slate-900">
            <AlertTriangle className="text-red-600 mx-auto mb-6" size={48} />
            <h3 className="text-2xl font-black mb-3">確認刪除項目？</h3>
            <p className="text-slate-500 font-bold mb-10">將永久移除「{deleteTarget.name}」，無法復原。</p>
            <div className="flex flex-col gap-3">
              <button onClick={confirmDelete} className="w-full py-4 bg-red-600 text-white rounded-2xl font-black">確定刪除</button>
              <button onClick={()=>setDeleteTarget(null)} className="w-full py-4 bg-slate-100 text-slate-400 rounded-2xl font-black">取消</button>
            </div>
          </div>
        </div>
      )}

      {/* 列印預覽 */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-slate-900/95 z-[100] flex flex-col items-center justify-start p-10 text-slate-900 overflow-y-auto">
          <div className="bg-white rounded-3xl w-full max-w-5xl p-10 relative shadow-2xl my-4">
            <div className="flex justify-between items-center mb-8 no-print border-b pb-4">
               <div className="flex items-center gap-3">
                 <Printer className="text-blue-600" size={28}/><span className="font-black text-2xl">台電領用單 (A4 標楷體)</span>
               </div>
               <div className="flex gap-4">
                 <button onClick={()=>window.print()} className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black text-xl shadow-lg hover:bg-blue-500 active:scale-95 transition-all">執行列印</button>
                 <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full hover:bg-slate-200 transition-colors"><X size={24}/></button>
               </div>
            </div>
            <div className="flex justify-center bg-white border">
               <PrintableForm transaction={lastTransaction} />
            </div>
          </div>
        </div>
      )}

      <div className="hidden print:block absolute top-0 left-0 w-full">
         {lastTransaction && <PrintableForm transaction={lastTransaction} />}
      </div>
    </div>
  );
};

export default App;

export enum Category {
  PROTECTION = '個人防護 (PPE)',
  FIRE_SAFETY = '消防安全',
  FIRST_AID = '急救耗材',
  SIGNAGE = '標誌警告',
  TOOL = '工具設備',
  OTHER = '其他'
}

export type ItemType = 'EQUIPMENT' | 'CONSUMABLE';
// 新增：群組分類 (耗材或藥材)
export type ItemGroup = 'INVENTORY' | 'MEDICINE';

export interface InventoryItem {
  id: string;
  name: string;
  category: Category;
  itemType: ItemType; 
  itemGroup: ItemGroup; // 新增分類
  unit: string;
  spec: string;
  quantity: number;
  minStock: number;
  purchaseDate?: string; // 新增：購入日期
  expiryDate?: string;   // 新增：到期日
  description: string;
  lastUpdated: number;
}

export type TransactionType = 'IN' | 'OUT';

export interface Transaction {
  id: string;
  itemId: string;
  itemName: string;
  type: TransactionType;
  quantity: number;
  person: string;
  dept: string;
  reason: string;
  timestamp: number;
}

export interface DashboardStats {
  totalItems: number;
  lowStockItems: number;
  monthlyOutbound: number;
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  RefreshCw,
  Search,
  X,
  Printer,
  Download,
  Upload,
  AlertTriangle,
  BrainCircuit,
  TrendingDown,
  Calendar,
  Users,
  Stethoscope
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell,
  Legend
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v8_items';
const STORAGE_KEY_LOGS = 'safeman_v8_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // 初始化
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { 
      try { 
        const p = JSON.parse(savedItems); 
        if (Array.isArray(p)) setItems(p); 
      } catch (e) {} 
    }
    if (savedLogs) { 
      try { 
        const p = JSON.parse(savedLogs); 
        if (Array.isArray(p)) setLogs(p); 
      } catch (e) {} 
    }
    setIsLoaded(true);
  }, []);

  // 存檔與藥材過期檢查
  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));

      // 過期警示檢查
      const now = new Date();
      const expiredMedicines = items.filter(i => 
        i.itemGroup === 'MEDICINE' && i.expiryDate && new Date(i.expiryDate) < now
      );
      if (expiredMedicines.length > 0) {
        // 使用 setTimeout 避免在渲染期間彈窗
        setTimeout(() => {
          window.alert(`⚠️ 藥材過期提醒：\n以下藥材已超過有效期限，請立即處理：\n\n${expiredMedicines.map(m => `• ${m.name} (到期日: ${m.expiryDate})`).join('\n')}`);
        }, 500);
      }
    }
  }, [items, logs, isLoaded]);

  const handleGetAiInsights = async () => {
    setIsAiLoading(true);
    const result = await getInventoryInsights(items);
    setAiInsights(result);
    setIsAiLoading(false);
  };

  const generateId = () => `ID-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

  const confirmDelete = () => {
    if (!deleteTarget) return;
    setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  const handleTransaction = () => {
    if (!selectedItemId) return window.alert('請先選擇一個項目');
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    const qty = parseInt(inputQty);
    if (isNaN(qty) || qty <= 0) return window.alert('請輸入大於 0 的領用數量');

    // --- 核心修正：強制類型轉換與阻塞式警告 ---
    if (issuanceMode === 'OUT') {
      const currentStock = Number(targetItem.quantity);
      if (qty > currentStock) {
        window.alert(`❌ 庫存不足！\n\n您欲領用：${qty} ${targetItem.unit}\n目前庫存：${currentStock} ${targetItem.unit}\n\n系統將停止開單程序，請調整領用量。`);
        return; // 確保中斷
      }
    }

    setItems(prev => prev.map(item => 
      item.id === selectedItemId 
        ? { ...item, quantity: issuanceMode === 'IN' ? Number(item.quantity) + qty : Number(item.quantity) - qty, lastUpdated: Date.now() } 
        : item
    ));

    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: qty,
      person: issuanceMode === 'OUT' ? (inputPerson || '未填寫') : '補貨管理員',
      dept: issuanceMode === 'OUT' ? selectedDept : '管理課',
      reason: issuanceMode === 'OUT' ? (inputReason || '公務使用') : '到貨入庫',
      timestamp: Date.now()
    };

    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      window.alert('✅ 庫存補貨成功！');
    }

    setSelectedItemId(''); setInputQty('1'); setInputPerson(''); setInputReason('');
  };

  const handleEditItem = (updatedItem: InventoryItem) => {
    setItems(prev => prev.map(item => item.id === updatedItem.id ? updatedItem : item));
    setEditTarget(null);
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    itemType: 'CONSUMABLE' as ItemType,
    itemGroup: 'INVENTORY' as ItemGroup,
    unit: '個',
