              <button onClick={()=>handleEditItem(editTarget)} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl hover:bg-blue-700 active:scale-95 transition-all">更新資料</button>
            </div>
          </div>
        </div>
      )}

      {/* 新增視窗 */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 text-slate-900">
