  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));

      const now = new Date();
      const expiredMedicines = items.filter(i => 
        i.itemGroup === 'MEDICINE' && i.expiryDate && new Date(i.expiryDate) < now
      );
      if (expiredMedicines.length > 0) {
        setTimeout(() => {
          window.alert(`⚠️ 系統藥材警告：\n共有 ${expiredMedicines.length} 項藥材已過期！\n請前往「藥材管理」頁面進行清理。`);
        }, 500);
      }
    }
  }, [items, logs, isLoaded]);

  const handleGetAiInsights = async () => {
    setIsAiLoading(true);
    const result = await getInventoryInsights(items);
    setAiInsights(result);
    setIsAiLoading(false);
  };

  const generateId = () => `ID-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

  const confirmDelete = () => {
    if (!deleteTarget) return;
    setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  const handleTransaction = () => {
    if (!selectedItemId) {
      window.alert('請先從選單中選擇一個項目');
      return;
    }
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    const qty = parseInt(inputQty);
    if (isNaN(qty) || qty <= 0) {
      window.alert('請輸入有效的數字且必須大於 0');
      return;
    }

    // --- 關鍵修復：領用超過庫存攔截 ---
    if (issuanceMode === 'OUT') {
      const currentStock = Number(targetItem.quantity);
      if (qty > currentStock) {
        // 使用 window.alert 確保使用者中斷操作
        window.alert(`❌ 領用失敗：數量超過現有庫存！\n\n名稱：${targetItem.name}\n庫存僅剩：${currentStock} ${targetItem.unit}\n欲領用：${qty} ${targetItem.unit}\n\n請修正領用量後再試一次。`);
        return; 
      }
    }

    setItems(prev => prev.map(item => 
      item.id === selectedItemId 
        ? { ...item, quantity: issuanceMode === 'IN' ? Number(item.quantity) + qty : Number(item.quantity) - qty, lastUpdated: Date.now() } 
        : item
    ));

    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: qty,
      person: issuanceMode === 'OUT' ? (inputPerson || '未註記') : '入庫管理員',
      dept: issuanceMode === 'OUT' ? selectedDept : '管理組',
      reason: issuanceMode === 'OUT' ? (inputReason || '公務領用') : '常態補貨',
      timestamp: Date.now()
    };

    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      window.alert('✅ 庫存入庫更新成功！');
    }

    setSelectedItemId(''); setInputQty('1'); setInputPerson(''); setInputReason('');
  };

  const handleEditItem = (updatedItem: InventoryItem) => {
    setItems(prev => prev.map(item => item.id === updatedItem.id ? updatedItem : item));
    setEditTarget(null);
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    itemType: 'CONSUMABLE' as ItemType,
    itemGroup: 'INVENTORY' as ItemGroup,
    unit: '個',
    spec: '',
    minStock: 5,
    quantity: 0,
    purchaseDate: '',
    expiryDate: ''
  });

  const handleAddItem = () => {
    if (!newForm.name.trim()) return window.alert('請輸入名稱');
    const newItem: InventoryItem = {
      id: generateId(),
      name: newForm.name.trim(),
      category: newForm.category,
      itemType: newForm.itemType,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: newForm.unit || '個',
      spec: newForm.spec || '',
      quantity: Number(newForm.quantity) || 0,
      minStock: Number(newForm.minStock) || 0,
      purchaseDate: newForm.purchaseDate,
      expiryDate: newForm.expiryDate,
      description: '',
      lastUpdated: Date.now()
    };
    setItems(prev => [...prev, newItem]);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, itemType: 'CONSUMABLE', itemGroup: 'INVENTORY', unit: '個', spec: '', minStock: 5, quantity: 0, purchaseDate: '', expiryDate: '' });
  };

  const deptStats = useMemo(() => {
    const stats: Record<string, number> = {};
    DEPARTMENTS.forEach(d => stats[d] = 0);
    logs.filter(l => l.type === 'OUT').forEach(log => {
      if (stats[log.dept] !== undefined) {
        stats[log.dept] += log.quantity;
      }
    });
    return Object.entries(stats).map(([name, count]) => ({ name, count }));
  }, [logs]);

  // 領用單
  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const date = new Date(transaction.timestamp);
    const emptyRows = Array(15).fill(null);

    const isEquipment = targetItem?.itemGroup === 'INVENTORY' && targetItem?.itemType === 'EQUIPMENT';
    const isConsumable = targetItem?.itemGroup === 'MEDICINE' || (targetItem?.itemGroup === 'INVENTORY' && targetItem?.itemType === 'CONSUMABLE');

    return (
      <div className="print-area bg-white text-black p-6 w-[210mm] mx-auto" id="official-form-final">
        <style>{`
          @font-face {
            font-family: 'StandardKai';
            src: local('標楷體'), local('DFKai-SB'), local('BiauKai');
          }
          #official-form-final { font-family: 'StandardKai', serif; font-size: 14pt; color: black; }
          #official-form-final table { border-collapse: collapse; width: 100%; border: 2px solid black; }
          #official-form-final th, #official-form-final td { border: 1.5px solid black; padding: 6px 10px; height: 38px; text-align: center; }
          @media print { .no-print { display: none !important; } }
        `}</style>

        <h1 className="text-center text-3xl font-bold mb-4">台灣電力公司電力修護處南部分處</h1>

        <div className="flex justify-center gap-12 mb-6 font-bold">
          <label className="flex items-center gap-2">
            <span className="w-5 h-5 border-2 border-black flex items-center justify-center font-black">
              {isEquipment ? 'V' : ''}
            </span>
            安全衛生設備
          </label>
          <label className="flex items-center gap-2">
            <span className="w-5 h-5 border-2 border-black flex items-center justify-center font-black">
              {isConsumable ? 'V' : ''}
            </span>
            安全衛生類消耗品
          </label>
        </div>

        <div className="flex justify-between mb-2 font-bold">
          <div>部門：<span className="inline-block border-b-2 border-dotted border-black min-w-[180px] text-center">{transaction.dept}</span></div>
          <div>{date.getFullYear() - 1911} 年 {date.getMonth() + 1} 月 {date.getDate()} 日</div>
        </div>

        <table>
          <thead>
            <tr className="font-bold">
              <th className="w-[35%]">名　　　　　稱</th>
              <th className="w-[25%]">規　範（序　號）</th>
              <th className="w-[10%]">單位</th>
              <th className="w-[10%]">數量</th>
              <th className="w-[20%]">備　　　　　註</th>
            </tr>
          </thead>
          <tbody>
            <tr className="font-bold">
              <td className="text-left">{transaction.itemName}</td>
              <td className="text-sm font-normal">{targetItem?.spec || ''}</td>
              <td>{targetItem?.unit || '個'}</td>
              <td>{transaction.quantity}</td>
              <td className="text-left text-xs font-normal">{transaction.reason}</td>
            </tr>
            {emptyRows.map((_, idx) => <tr key={idx}><td /><td /><td /><td /><td /></tr>)}
          </tbody>
        </table>

        <div className="mt-8 font-bold grid grid-cols-2 gap-x-12">
          <div className="flex flex-col gap-10">
             <div>申請部門：</div>
             <div className="flex justify-between w-full pr-4">
                <div>經辦：</div>
                <div>課長：</div>
                <div>經理：</div>
             </div>
          </div>
          <div className="flex flex-col gap-10">
             <div>經管部門：</div>
             <div className="flex justify-between w-full pr-4">
                <div>經辦：</div>
                <div>課長：</div>
                <div>經理：</div>
             </div>
          </div>
        </div>
        <div className="mt-8 text-xs text-gray-400 font-normal">領用編號：{transaction.id} / 領用人：{transaction.person}</div>
      </div>
    );
  };

  const filteredItemsInTable = useMemo(() => {
    const group = activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY';
    return items.filter(i => i.itemGroup === group && i.name.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [items, activeTab, searchTerm]);

  const issuanceItems = useMemo(() => {
    return items.filter(i => i.itemGroup === issuanceGroup);
  }, [items, issuanceGroup]);

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900 font-sans">
      <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={e => {
        const file = e.target.files?.[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (ev) => {
          try {
            const data = JSON.parse(ev.target?.result as string);
            if (data.items) { setItems(data.items); setLogs(data.logs || []); window.alert('✅ 匯入成功'); }
          } catch { window.alert('❌ 解析失敗'); }
        };
        reader.readAsText(file);
      }} />

      <aside className="no-print w-72 bg-slate-900 text-white p-8 flex flex-col shrink-0">
        <div className="flex items-center gap-3 mb-12">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg"><Package size={22}/></div>
          <div><h1 className="font-black text-lg">工安管理系統</h1><p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">v9.1 Professional</p></div>
        </div>

        <nav className="flex-1 space-y-2">
          {[
            { id: 'inventory', label: '工安耗材管理', icon: Package },
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
            { id: 'issuance', label: '領用登記作業', icon: FileText },
            { id: 'history', label: '歷史異動日誌', icon: History },
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard },
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}>
              <tab.icon size={20} /> {tab.label}
            </button>
          ))}
        </nav>

        <button onClick={() => {
          const blob = new Blob([JSON.stringify({items, logs})], {type: 'application/json'});
          const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = '工安系統數據.json'; a.click();
        }} className="mt-8 flex items-center gap-3 px-4 py-3 bg-slate-800 rounded-xl text-xs font-bold text-blue-400 hover:bg-slate-700">
          <Download size={14} /> 下載數據備份
        </button>
      </aside>

      <main className="no-print flex-1 p-10 overflow-y-auto">
        <header className="mb-10 flex justify-between items-center">
          <h2 className="text-4xl font-black text-slate-900">
            {activeTab === 'inventory' ? '工安耗材' : activeTab === 'medicine' ? '藥材管理' : activeTab === 'issuance' ? '領用補貨' : activeTab === 'history' ? '歷史日誌' : '數據中心'}
          </h2>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black flex items-center gap-3 shadow-xl hover:bg-black active:scale-95 transition-all">
              <Plus size={20}/> 新增{activeTab === 'inventory' ? '耗材' : '藥材'}
            </button>
          )}
        </header>

        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 overflow-hidden">
            <div className="p-8 bg-slate-50 border-b flex items-center gap-6">
               <div className="relative flex-1">
                 <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                 <input type="text" placeholder="搜尋項目名稱..." className="w-full pl-14 pr-6 py-4 bg-white border-2 border-slate-200 rounded-2xl font-bold outline-none focus:border-blue-500 shadow-inner" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
               </div>
            </div>
            <table className="w-full text-left">
              <thead>
                <tr className="text-[11px] font-black text-slate-400 uppercase tracking-widest border-b">
                  <th className="px-10 py-6">名稱規格</th>
                  {activeTab === 'medicine' && <th className="px-10 py-6">有效日期</th>}
                  <th className="px-10 py-6">類別</th>
                  <th className="px-10 py-6 text-center">庫存數量</th>
                  <th className="px-10 py-6 text-right">操作</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filteredItemsInTable.map(item => {
                  const isExpired = item.expiryDate && new Date(item.expiryDate) < new Date();
                  return (
                    <tr key={item.id} className="group hover:bg-slate-50 transition-all">
                      <td className="px-10 py-7">
                        <div className="font-black text-lg">{item.name}</div>
                        <div className="text-xs text-slate-400 font-bold">{item.spec || '無規格紀錄'}</div>
                      </td>
                      {activeTab === 'medicine' && (
                        <td className="px-10 py-7">
                          <div className={`flex items-center gap-2 font-bold ${isExpired ? 'text-red-600 animate-pulse' : 'text-slate-600'}`}>
                            {isExpired ? <AlertTriangle size={14}/> : <Clock size={14}/>}
                            {item.expiryDate || '未填'}
                          </div>
                          {isExpired && <span className="text-[10px] font-black bg-red-100 px-2 py-0.5 rounded text-red-700">已過期</span>}
                        </td>
                      )}
                      <td className="px-10 py-7">
                        <span className={`px-3 py-1 rounded-lg text-[10px] font-black ${item.itemType === 'EQUIPMENT' ? 'bg-orange-100 text-orange-600' : 'bg-blue-100 text-blue-600'}`}>
                          {item.itemType === 'EQUIPMENT' ? '安全衛生設備' : '安全衛生類消耗品'}
                        </span>
                      </td>
                      <td className="px-10 py-7 text-center">
                        <span className={`px-5 py-2 rounded-xl text-sm font-black ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>
                          {item.quantity} {item.unit}
                        </span>
                      </td>
                      <td className="px-10 py-7 text-right flex items-center justify-end gap-2">
                        <button onClick={() => setEditTarget(item)} className="p-3 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all"><Edit3 size={18}/></button>
                        <button onClick={() => setDeleteTarget({id: item.id, name: item.name})} className="p-3 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all"><Trash2 size={18}/></button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'issuance' && (
          <div className="max-w-3xl mx-auto bg-white p-12 rounded-[3.5rem] shadow-xl border border-slate-100">
             <div className="flex bg-slate-100 p-2 rounded-2xl mb-8">
               <button onClick={()=>setIssuanceMode('OUT')} className={`flex-1 py-5 rounded-xl font-black text-lg transition-all ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button>
               <button onClick={()=>setIssuanceMode('IN')} className={`flex-1 py-5 rounded-xl font-black text-lg transition-all ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
             </div>

             <div className="flex gap-4 mb-8">
               <button onClick={()=>setIssuanceGroup('INVENTORY')} className={`flex-1 py-3 rounded-xl font-bold text-sm border-2 transition-all ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-200 text-slate-400'}`}>1. 工安耗材項目</button>
               <button onClick={()=>setIssuanceGroup('MEDICINE')} className={`flex-1 py-3 rounded-xl font-bold text-sm border-2 transition-all ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-200 text-slate-400'}`}>2. 急救藥材項目</button>
             </div>

             <div className="space-y-8">
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">選取具體項目</label>
                  <select className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold text-xl outline-none focus:border-blue-600" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                    <option value="">-- 請從{issuanceGroup==='INVENTORY'?'耗材':'藥材'}選單中選擇 --</option>
                    {issuanceItems.map(i=>(
                      <option key={i.id} value={i.id}>{i.name} (剩餘: {i.quantity} {i.unit})</option>
                    ))}
                  </select>
                </div>

                <div className="grid grid-cols-2 gap-8">
                  <div>
                    <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">操作數量</label>
                    <input type="number" min="1" className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold text-xl outline-none" value={inputQty} onChange={e=>setInputQty(e.target.value)}/>
                  </div>
                  {issuanceMode === 'OUT' ? (
                    <div>
                      <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">領用部門</label>
                      <select className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold text-xl outline-none focus:border-blue-600" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>
                        {DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
                      </select>
                    </div>
                  ) : (
                    <div>
                       <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">更新日期</label>
                       <div className="w-full p-5 bg-slate-50 border-2 border-slate-100 rounded-2xl text-slate-400 font-bold text-xl">{new Date().toLocaleDateString()}</div>
                    </div>
                  )}
                </div>

                {issuanceMode === 'OUT' && (
                  <div className="grid grid-cols-2 gap-8">
                    <div>
                      <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">領用人</label>
                      <input type="text" placeholder="填寫姓名" className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold text-xl outline-none" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/>
                    </div>
                    <div>
                      <label className="block text-xs font-black text-slate-400 mb-3 uppercase tracking-widest">領用原因</label>
                      <input type="text" placeholder="例: 現場巡檢" className="w-full p-5 border-2 border-slate-200 rounded-2xl font-bold text-xl outline-none" value={inputReason} onChange={e=>setInputReason(e.target.value)}/>
                    </div>
                  </div>
                )}

                <button onClick={handleTransaction} className={`w-full py-6 rounded-2xl font-black text-white text-2xl shadow-2xl transition-all active:scale-95 ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>
                  {issuanceMode === 'OUT' ? '列印領用單並更新' : '確認入庫更新'}
                </button>
             </div>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100">
                <p className="text-slate-400 font-black text-xs mb-3 uppercase tracking-widest">工安耗材低庫存</p>
                <p className="text-6xl font-black text-orange-600">{items.filter(i=>i.itemGroup==='INVENTORY' && i.quantity<=i.minStock).length}</p>
              </div>
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100">
                <p className="text-slate-400 font-black text-xs mb-3 uppercase tracking-widest">急救藥材低庫存</p>
                <p className="text-6xl font-black text-red-600">{items.filter(i=>i.itemGroup==='MEDICINE' && i.quantity<=i.minStock).length}</p>
              </div>
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border-l-8 border-l-red-600">
                <p className="text-red-500 font-black text-xs mb-3 uppercase tracking-widest">已過期藥材項目</p>
                <p className="text-6xl font-black text-red-600">{items.filter(i=>i.itemGroup==='MEDICINE' && i.expiryDate && new Date(i.expiryDate) < new Date()).length}</p>
              </div>
              <div className="bg-slate-900 p-10 rounded-[2.5rem] shadow-2xl text-white relative overflow-hidden flex flex-col justify-center">
                <BrainCircuit className="absolute -right-6 -bottom-6 text-white/5" size={160} />
                <button onClick={handleGetAiInsights} disabled={isAiLoading} className="px-6 py-3 bg-blue-600 rounded-xl font-bold text-sm hover:bg-blue-500 transition-all">
                   {isAiLoading ? '建議生成中...' : 'AI 採購建議'}
                </button>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
