              {editTarget.itemGroup === 'MEDICINE' && (
                <div className="grid grid-cols-2 gap-4">
                  <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">購入日期</label><input type="date" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white" value={editTarget.purchaseDate} onChange={e=>setEditTarget({...editTarget, purchaseDate: e.target.value})}/></div>
