              <div className="grid grid-cols-2 gap-4">
                <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">單位</label><input type="text" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white" value={editTarget.unit} onChange={e=>setEditTarget({...editTarget, unit: e.target.value})}/></div>
                <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">警戒庫存</label><input type="number" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white" value={editTarget.minStock} onChange={e=>setEditTarget({...editTarget, minStock: Number(e.target.value)})}/></div>
