            <div className="flex justify-between items-center mb-8">
              <h3 className="font-black text-3xl">新增{activeTab === 'inventory' ? '工安耗材' : '急救藥材'}</h3>
              <button onClick={()=>setShowAddModal(false)} className="p-2 bg-slate-100 rounded-full"><X/></button>
            </div>
            <div className="space-y-4">
              <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">名稱</label><input type="text" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white" value={newForm.name} onChange={e=>setNewForm({...newForm, name: e.target.value})}/></div>
              {activeTab === 'inventory' ? (
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">單據類別</label>
                  <select className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white" value={newForm.itemType} onChange={e=>setNewForm({...newForm, itemType: e.target.value as ItemType})}>
                    <option value="EQUIPMENT">安全衛生設備</option>
                    <option value="CONSUMABLE">安全衛生類消耗品</option>
                  </select>
                </div>
              ) : (
                <div className="grid grid-cols-2 gap-4">
                  <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">購入日期</label><input type="date" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white" value={newForm.purchaseDate} onChange={e=>setNewForm({...newForm, purchaseDate: e.target.value})}/></div>
                  <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">到期日期</label><input type="date" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white" value={newForm.expiryDate} onChange={e=>setNewForm({...newForm, expiryDate: e.target.value})}/></div>
                </div>
              )}
              <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">規格說明</label><input type="text" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white" value={newForm.spec} onChange={e=>setNewForm({...newForm, spec: e.target.value})}/></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">單位</label><input type="text" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white text-slate-900" value={newForm.unit} onChange={e=>setNewForm({...newForm, unit: e.target.value})}/></div>
                <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">初期數量</label><input type="number" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold bg-white" value={newForm.quantity} onChange={e=>setNewForm({...newForm, quantity: Number(e.target.value)})}/></div>
              </div>
              <button onClick={handleAddItem} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl hover:bg-blue-700 active:scale-95 transition-all">確認存入資料庫</button>
            </div>
          </div>
        </div>
      )}

      {/* 刪除確認 */}
      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-sm p-12 shadow-2xl text-center text-slate-900">
            <AlertTriangle className="text-red-600 mx-auto mb-6" size={48} />
            <h3 className="text-2xl font-black mb-3">移除確認</h3>
            <p className="text-slate-500 font-bold mb-10">將永久移除「{deleteTarget.name}」，此動作不可復原。</p>
            <div className="flex flex-col gap-3">
              <button onClick={confirmDelete} className="w-full py-4 bg-red-600 text-white rounded-2xl font-black shadow-lg">確認刪除</button>
              <button onClick={()=>setDeleteTarget(null)} className="w-full py-4 bg-slate-100 text-slate-400 rounded-2xl font-black">取消返回</button>
            </div>
          </div>
        </div>
      )}

      {/* 列印視窗 */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-slate-900/95 z-[100] flex flex-col items-center justify-start p-10 text-slate-900 overflow-y-auto">
          <div className="bg-white rounded-3xl w-full max-w-5xl p-10 relative shadow-2xl my-4">
            <div className="flex justify-between items-center mb-8 no-print border-b pb-4">
               <div className="flex items-center gap-3">
                 <Printer className="text-blue-600" size={28}/><span className="font-black text-2xl">台電正式領用單 (A4預覽)</span>
               </div>
               <div className="flex gap-4">
                 <button onClick={()=>window.print()} className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black text-xl shadow-lg active:scale-95 transition-all">執行列印</button>
                 <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full hover:bg-slate-200"><X size={24}/></button>
               </div>
            </div>
            <div className="flex justify-center bg-white border p-4 overflow-hidden">
               <PrintableForm transaction={lastTransaction} />
            </div>
          </div>
        </div>
      )}

      <div className="hidden print:block absolute top-0 left-0 w-full">
         {lastTransaction && <PrintableForm transaction={lastTransaction} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  RefreshCw,
  Search,
  X,
  Printer,
  Download,
  AlertTriangle,
  BrainCircuit,
  Users,
  Stethoscope,
  Clock,
  Calendar as CalendarIcon
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v9_items_v2';
const STORAGE_KEY_LOGS = 'safeman_v9_logs_v2';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));

      const now = new Date();
      const expiredMedicines = items.filter(i => 
        i.itemGroup === 'MEDICINE' && i.expiryDate && new Date(i.expiryDate) < now
      );
      if (expiredMedicines.length > 0) {
        setTimeout(() => {
          window.alert(`⚠️ 系統藥材警告：\n共有 ${expiredMedicines.length} 項藥材已過期！\n請務必檢查「藥材管理」頁面的紅燈示警項目。`);
        }, 500);
      }
    }
  }, [items, logs, isLoaded]);

  const handleGetAiInsights = async () => {
    setIsAiLoading(true);
    const result = await getInventoryInsights(items);
    setAiInsights(result);
    setIsAiLoading(false);
  };

  const generateId = () => `ID-${Date.now() % 100000}`;

  const confirmDelete = () => {
    if (!deleteTarget) return;
    setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  const handleTransaction = () => {
    // 1. 強制檢查是否有選擇項目
    if (!selectedItemId) {
      window.alert('請先選擇一個項目名稱！');
      return;
    }

    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    const qty = parseInt(inputQty);
    if (isNaN(qty) || qty <= 0) {
      window.alert('數量必須為大於 0 的整數數字！');
      return;
    }

    // 2. 核心：庫存不足警告攔截 (優先於所有邏輯)
    if (issuanceMode === 'OUT') {
      const currentStock = Number(targetItem.quantity);
      if (qty > currentStock) {
        // 使用同步 Alert 確保使用者必須處理
        window.alert(`❌ 無法領用：超過現有庫存！\n\n項目：${targetItem.name}\n目前剩餘：${currentStock} ${targetItem.unit}\n欲領用量：${qty} ${targetItem.unit}\n\n系統已取消此筆操作。`);
        return; // 這裡絕對不能移除，否則會繼續執行後面的狀態更新
      }
    }

    // 3. 更新庫存
    setItems(prev => prev.map(item => 
      item.id === selectedItemId 
        ? { ...item, quantity: issuanceMode === 'IN' ? Number(item.quantity) + qty : Number(item.quantity) - qty, lastUpdated: Date.now() } 
        : item
    ));

    // 4. 寫入日誌
    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: qty,
      person: issuanceMode === 'OUT' ? (inputPerson || '未填寫') : '庫存管理員',
      dept: issuanceMode === 'OUT' ? selectedDept : '管理課',
      reason: issuanceMode === 'OUT' ? (inputReason || '公務使用') : '入庫補貨',
      timestamp: Date.now()
    };

    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    // 5. 成功後續處理
    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      window.alert('✅ 補貨入庫已成功更新！');
    }

    // 重置欄位
    setSelectedItemId(''); setInputQty('1'); setInputPerson(''); setInputReason('');
  };

  const handleEditItem = (updatedItem: InventoryItem) => {
    setItems(prev => prev.map(item => item.id === updatedItem.id ? updatedItem : item));
    setEditTarget(null);
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    itemType: 'CONSUMABLE' as ItemType,
    itemGroup: 'INVENTORY' as ItemGroup,
    unit: '個',
    spec: '',
    minStock: 5,
    quantity: 0,
    purchaseDate: '',
    expiryDate: ''
  });

  const handleAddItem = () => {
    if (!newForm.name.trim()) return window.alert('請輸入名稱');
    const newItem: InventoryItem = {
      id: generateId(),
      name: newForm.name.trim(),
      category: newForm.category,
      itemType: newForm.itemType,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: newForm.unit || '個',
      spec: newForm.spec || '',
      quantity: Number(newForm.quantity) || 0,
      minStock: Number(newForm.minStock) || 0,
      purchaseDate: newForm.purchaseDate,
      expiryDate: newForm.expiryDate,
      description: '',
      lastUpdated: Date.now()
    };
    setItems(prev => [...prev, newItem]);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, itemType: 'CONSUMABLE', itemGroup: 'INVENTORY', unit: '個', spec: '', minStock: 5, quantity: 0, purchaseDate: '', expiryDate: '' });
  };

  const deptStats = useMemo(() => {
    const stats: Record<string, number> = {};
    DEPARTMENTS.forEach(d => stats[d] = 0);
    logs.filter(l => l.type === 'OUT').forEach(log => {
      if (stats[log.dept] !== undefined) {
        stats[log.dept] += log.quantity;
      }
    });
    return Object.entries(stats).map(([name, count]) => ({ name, count }));
  }, [logs]);

  // 領用單元件
  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const date = new Date(transaction.timestamp);
    const emptyRows = Array(15).fill(null);

    const isEquipment = targetItem?.itemGroup === 'INVENTORY' && targetItem?.itemType === 'EQUIPMENT';
    const isConsumable = targetItem?.itemGroup === 'MEDICINE' || (targetItem?.itemGroup === 'INVENTORY' && targetItem?.itemType === 'CONSUMABLE');

    return (
      <div className="print-area bg-white text-black p-6 w-[210mm] mx-auto relative" id="official-form-v6">
        <style>{`
          @font-face {
            font-family: 'StandardKai';
            src: local('標楷體'), local('DFKai-SB'), local('BiauKai');
          }
          #official-form-v6 { font-family: 'StandardKai', serif; font-size: 14pt; color: black; }
          #official-form-v6 table { border-collapse: collapse; width: 100%; border: 2px solid black; }
          #official-form-v6 th, #official-form-v6 td { border: 1.5px solid black; padding: 6px 10px; height: 38px; text-align: center; }
          @media print { .no-print { display: none !important; } }
        `}</style>

        {/* 移至右上角的內容 */}
        <div className="absolute top-6 right-6 text-sm text-right font-bold">
           <div>領用編號：{transaction.id}</div>
           <div>領用人員：{transaction.person}</div>
        </div>

        <h1 className="text-center text-3xl font-bold mb-6 pt-4">台灣電力公司電力修護處南部分處</h1>

        <div className="flex justify-center gap-12 mb-8 font-bold">
          <label className="flex items-center gap-2">
            <span className="w-5 h-5 border-2 border-black flex items-center justify-center font-black">
              {isEquipment ? 'V' : ''}
            </span>
            安全衛生設備
          </label>
          <label className="flex items-center gap-2">
            <span className="w-5 h-5 border-2 border-black flex items-center justify-center font-black">
              {isConsumable ? 'V' : ''}
            </span>
            安全衛生類消耗品
          </label>
        </div>

        <div className="flex justify-between mb-2 font-bold px-1">
          <div>部門：<span className="inline-block border-b-2 border-dotted border-black min-w-[180px] text-center">{transaction.dept}</span></div>
          <div>{date.getFullYear() - 1911} 年 {date.getMonth() + 1} 月 {date.getDate()} 日</div>
        </div>

        <table>
          <thead>
            <tr className="font-bold">
              <th className="w-[35%]">名　　　　　稱</th>
              <th className="w-[25%]">規　範（序　號）</th>
              <th className="w-[10%]">單位</th>
              <th className="w-[10%]">數量</th>
              <th className="w-[20%]">備　　　　　註</th>
            </tr>
          </thead>
          <tbody>
            <tr className="font-bold">
              <td className="text-left">{transaction.itemName}</td>
              <td className="text-sm font-normal">{targetItem?.spec || ''}</td>
              <td>{targetItem?.unit || '個'}</td>
              <td>{transaction.quantity}</td>
              <td className="text-left text-xs font-normal">{transaction.reason}</td>
