                    <label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">到期日期</label>
                    <input type="date" className="w-full p-4 border-2 border-slate-300 rounded-2xl font-bold bg-white text-slate-900 outline-none" value={newForm.expiryDate} onChange={e=>setNewForm({...newForm, expiryDate: e.target.value})}/>
                  </div>
                </div>
              )}
              <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">規格規格</label><input type="text" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold bg-white text-slate-900" value={newForm.spec} onChange={e=>setNewForm({...newForm, spec: e.target.value})}/></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">單位</label><input type="text" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold bg-white text-slate-900" value={newForm.unit} onChange={e=>setNewForm({...newForm, unit: e.target.value})}/></div>
                <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">初期庫存量</label><input type="number" className="w-full p-4 border-2 border-slate-200 rounded-2xl font-bold bg-white text-slate-900" value={newForm.quantity} onChange={e=>setNewForm({...newForm, quantity: Number(e.target.value)})}/></div>
              </div>
              <button onClick={handleAddItem} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl hover:bg-blue-700 active:scale-95 transition-all">確認存入</button>
            </div>
          </div>
        </div>
      )}

      {/* 刪除確認 */}
      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-sm p-12 shadow-2xl text-center text-slate-900">
            <AlertTriangle className="text-red-600 mx-auto mb-6" size={48} />
            <h3 className="text-2xl font-black mb-3">確認移除項目？</h3>
            <p className="text-slate-500 font-bold mb-10">將永久移除「{deleteTarget.name}」，此動作無法復原。</p>
            <div className="flex flex-col gap-3">
              <button onClick={confirmDelete} className="w-full py-4 bg-red-600 text-white rounded-2xl font-black shadow-lg">確認刪除</button>
              <button onClick={()=>setDeleteTarget(null)} className="w-full py-4 bg-slate-100 text-slate-400 rounded-2xl font-black">取消</button>
            </div>
          </div>
        </div>
      )}

      {/* 列印視窗 */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-slate-900/95 z-[100] flex flex-col items-center justify-start p-10 text-slate-900 overflow-y-auto">
          <div className="bg-white rounded-3xl w-full max-w-5xl p-10 relative shadow-2xl my-4">
            <div className="flex justify-between items-center mb-8 no-print border-b pb-4">
               <div className="flex items-center gap-3">
                 <Printer className="text-blue-600" size={28}/><span className="font-black text-2xl text-slate-900">正式單據列印預覽 (A4)</span>
               </div>
               <div className="flex gap-4">
                 <button onClick={()=>window.print()} className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black text-xl shadow-lg active:scale-95 transition-all">執行列印</button>
                 <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full hover:bg-slate-200 transition-colors"><X size={24} className="text-slate-900"/></button>
               </div>
            </div>
            <div className="flex justify-center bg-white border p-4 shadow-inner overflow-hidden">
               <PrintableForm transaction={lastTransaction} />
            </div>
          </div>
        </div>
      )}

      <div className="hidden print:block absolute top-0 left-0 w-full">
         {lastTransaction && <PrintableForm transaction={lastTransaction} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  Download,
  AlertTriangle,
  BrainCircuit,
  Users,
  Stethoscope,
  Clock,
  Calendar as CalendarIcon
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v9_items_v3';
const STORAGE_KEY_LOGS = 'safeman_v9_logs_v3';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // 初始化讀取
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  // 儲存與過期提醒
  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));

      const now = new Date();
      const expiredMedicines = items.filter(i => 
        i.itemGroup === 'MEDICINE' && i.expiryDate && new Date(i.expiryDate) < now
      );
      if (expiredMedicines.length > 0) {
        setTimeout(() => {
          window.alert(`⚠️ 系統藥材過期警告：\n檢測到有 ${expiredMedicines.length} 項藥材已失效，請立即前往藥材管理確認。`);
        }, 800);
      }
    }
  }, [items, logs, isLoaded]);

  const handleGetAiInsights = async () => {
    setIsAiLoading(true);
    const result = await getInventoryInsights(items);
    setAiInsights(result);
    setIsAiLoading(false);
  };

  const generateId = () => `NO-${Math.floor(Math.random() * 900000 + 100000)}`;

  const confirmDelete = () => {
    if (!deleteTarget) return;
    setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  const handleTransaction = () => {
    // 0. 選項檢查
    if (!selectedItemId) {
      window.alert('請先選取具體項目名稱！');
      return;
    }

    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    // 1. 數量轉換與驗證
    const requestQty = parseInt(inputQty);
    const availableQty = Number(targetItem.quantity);

    if (isNaN(requestQty) || requestQty <= 0) {
      window.alert('請輸入有效的數字（必須大於 0）！');
      return;
    }

    // 2. 重中之重：庫存不足攔截邏輯
    if (issuanceMode === 'OUT') {
      if (requestQty > availableQty) {
        // 同步跳出警示，中斷所有後續代碼執行
        window.alert(
          `❌ 警告：庫存量不足！\n\n` +
          `名稱：${targetItem.name}\n` +
          `現有庫存：${availableQty} ${targetItem.unit}\n` +
          `本次欲領用：${requestQty} ${targetItem.unit}\n\n` +
          `缺口為 ${requestQty - availableQty} ${targetItem.unit}，系統已拒絕此筆交易。`
        );
        return; // 必須徹底 Return
      }
    }

    // 3. 執行資料更新
    setItems(prev => prev.map(item => 
      item.id === selectedItemId 
        ? { ...item, quantity: issuanceMode === 'IN' ? Number(item.quantity) + requestQty : Number(item.quantity) - requestQty, lastUpdated: Date.now() } 
        : item
    ));

    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: requestQty,
      person: issuanceMode === 'OUT' ? (inputPerson || '未註記') : '管理員補貨',
      dept: issuanceMode === 'OUT' ? selectedDept : '後勤課',
      reason: issuanceMode === 'OUT' ? (inputReason || '現場領用') : '採購入庫',
      timestamp: Date.now()
    };

    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    // 4. 完成後的反饋
    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      window.alert('✅ 補貨更新完成。');
    }

    // 重置選單
    setSelectedItemId(''); setInputQty('1'); setInputPerson(''); setInputReason('');
  };

  const handleEditItem = (updatedItem: InventoryItem) => {
    setItems(prev => prev.map(item => item.id === updatedItem.id ? updatedItem : item));
    setEditTarget(null);
  };

  const [newForm, setNewForm] = useState({
    name: '',
    category: Category.PROTECTION,
    itemType: 'CONSUMABLE' as ItemType,
    itemGroup: 'INVENTORY' as ItemGroup,
    unit: '個',
    spec: '',
    minStock: 5,
    quantity: 0,
    purchaseDate: '',
    expiryDate: ''
  });

  const handleAddItem = () => {
    if (!newForm.name.trim()) return window.alert('請輸入項目名稱');
    const newItem: InventoryItem = {
      id: generateId(),
      name: newForm.name.trim(),
      category: newForm.category,
      itemType: newForm.itemType,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: newForm.unit || '個',
      spec: newForm.spec || '',
      quantity: Number(newForm.quantity) || 0,
      minStock: Number(newForm.minStock) || 0,
      purchaseDate: newForm.purchaseDate,
      expiryDate: newForm.expiryDate,
      description: '',
      lastUpdated: Date.now()
    };
    setItems(prev => [...prev, newItem]);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, itemType: 'CONSUMABLE', itemGroup: 'INVENTORY', unit: '個', spec: '', minStock: 5, quantity: 0, purchaseDate: '', expiryDate: '' });
  };

  const deptStats = useMemo(() => {
    const stats: Record<string, number> = {};
    DEPARTMENTS.forEach(d => stats[d] = 0);
    logs.filter(l => l.type === 'OUT').forEach(log => {
      if (stats[log.dept] !== undefined) {
        stats[log.dept] += log.quantity;
      }
    });
    return Object.entries(stats).map(([name, count]) => ({ name, count }));
  }, [logs]);

  // 領用單元件
  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const date = new Date(transaction.timestamp);
    const emptyRows = Array(15).fill(null);

    const isEquipment = targetItem?.itemGroup === 'INVENTORY' && targetItem?.itemType === 'EQUIPMENT';
    const isConsumable = targetItem?.itemGroup === 'MEDICINE' || (targetItem?.itemGroup === 'INVENTORY' && targetItem?.itemType === 'CONSUMABLE');

    return (
      <div className="print-area bg-white text-black p-6 w-[210mm] mx-auto relative overflow-hidden" id="official-form-v7">
        <style>{`
          @font-face {
            font-family: 'StandardKai';
            src: local('標楷體'), local('DFKai-SB'), local('BiauKai');
          }
          #official-form-v7 { font-family: 'StandardKai', serif; font-size: 14pt; color: black !important; }
          #official-form-v7 table { border-collapse: collapse; width: 100%; border: 2.5px solid black; }
          #official-form-v7 th, #official-form-v7 td { border: 2px solid black; padding: 6px 10px; height: 38px; text-align: center; }
          @media print { .no-print { display: none !important; } }
        `}</style>

        {/* 右上角領用編號與人員：改為淺灰色、小字級 */}
        <div className="absolute top-4 right-6 text-xs text-slate-400 font-bold text-right space-y-1">
           <div>領用編號：{transaction.id}</div>
           <div>領用人員：{transaction.person}</div>
        </div>

        <h1 className="text-center text-3xl font-bold mb-6 pt-6 tracking-widest">台灣電力公司電力修護處南部分處</h1>

        <div className="flex justify-center gap-12 mb-8 font-bold text-black">
          <label className="flex items-center gap-2 cursor-pointer">
            <span className="w-5 h-5 border-2 border-black flex items-center justify-center font-black">
              {isEquipment ? 'V' : ''}
            </span>
            安全衛生設備
          </label>
          <label className="flex items-center gap-2 cursor-pointer">
            <span className="w-5 h-5 border-2 border-black flex items-center justify-center font-black">
              {isConsumable ? 'V' : ''}
            </span>
            安全衛生類消耗品
          </label>
        </div>

        <div className="flex justify-between mb-2 font-bold px-1 text-black">
          <div>領用單位：<span className="inline-block border-b-2 border-dotted border-black min-w-[200px] text-center">{transaction.dept}</span></div>
          <div>中華民國 {date.getFullYear() - 1911} 年 {date.getMonth() + 1} 月 {date.getDate()} 日</div>
        </div>

        <table>
          <thead>
            <tr className="font-bold bg-slate-50">
              <th className="w-[35%]">名　　　　　稱</th>
              <th className="w-[25%]">規　範（序　號）</th>
              <th className="w-[10%]">單位</th>
              <th className="w-[10%]">數量</th>
              <th className="w-[20%]">備　　　　　註</th>
            </tr>
          </thead>
          <tbody>
            <tr className="font-bold">
              <td className="text-left">{transaction.itemName}</td>
              <td className="text-sm font-normal">{targetItem?.spec || ''}</td>
              <td>{targetItem?.unit || '個'}</td>
              <td className="text-xl">{transaction.quantity}</td>
              <td className="text-left text-xs font-normal">{transaction.reason}</td>
            </tr>
            {emptyRows.map((_, idx) => <tr key={idx}><td /><td /><td /><td /><td /></tr>)}
          </tbody>
        </table>

        <div className="mt-12 font-bold grid grid-cols-2 gap-x-12 text-black">
          <div className="flex flex-col gap-10">
             <div>申請部門：</div>
             <div className="flex justify-between w-full">
                <div>經辦：</div>
                <div>課長：</div>
                <div>經理：</div>
             </div>
          </div>
          <div className="flex flex-col gap-10">
             <div>經管部門：</div>
             <div className="flex justify-between w-full">
                <div>經辦：</div>
                <div>課長：</div>
                <div>經理：</div>
             </div>
          </div>
        </div>
      </div>
    );
  };

  const filteredItemsInTable = useMemo(() => {
    const group = activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY';
    return items.filter(i => i.itemGroup === group && i.name.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [items, activeTab, searchTerm]);

  const issuanceItems = useMemo(() => {
    return items.filter(i => i.itemGroup === issuanceGroup);
  }, [items, issuanceGroup]);

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900 font-sans">
      <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={e => {
        const file = e.target.files?.[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (ev) => {
          try {
            const data = JSON.parse(ev.target?.result as string);
            if (data.items) { setItems(data.items); setLogs(data.logs || []); window.alert('✅ 數據庫載入成功'); }
          } catch { window.alert('❌ 檔案解析失敗。'); }
        };
        reader.readAsText(file);
      }} />

      <aside className="no-print w-72 bg-slate-900 text-white p-8 flex flex-col shrink-0">
        <div className="flex items-center gap-3 mb-12">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg"><Package size={22}/></div>
          <div><h1 className="font-black text-lg">工安管理系統</h1><p className="text-[10px] text-slate-500 font-bold tracking-widest">v9.3 PROFESSIONAL</p></div>
        </div>

        <nav className="flex-1 space-y-2">
          {[
            { id: 'inventory', label: '工安耗材管理', icon: Package },
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
            { id: 'issuance', label: '領用登記作業', icon: FileText },
            { id: 'history', label: '歷史異動日誌', icon: History },
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard },
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}>
              <tab.icon size={20} /> {tab.label}
            </button>
          ))}
        </nav>

        <button onClick={() => {
          const blob = new Blob([JSON.stringify({items, logs})], {type: 'application/json'});
          const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = '工安系統數據.json'; a.click();
        }} className="mt-8 flex items-center gap-3 px-4 py-3 bg-slate-800 rounded-xl text-xs font-bold text-blue-400 hover:bg-slate-700">
          <Download size={14} /> 備份本地數據
        </button>
      </aside>

      <main className="no-print flex-1 p-10 overflow-y-auto">
        <header className="mb-10 flex justify-between items-center">
          <h2 className="text-4xl font-black text-slate-900 tracking-tight">
            {activeTab === 'inventory' ? '耗材清冊' : activeTab === 'medicine' ? '藥材清冊' : activeTab === 'issuance' ? '作業台' : activeTab === 'history' ? '歷史日誌' : '數據中心'}
          </h2>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black flex items-center gap-3 shadow-xl hover:bg-black active:scale-95 transition-all">
              <Plus size={20}/> 新增{activeTab === 'inventory' ? '耗材' : '藥材'}項目
            </button>
          )}
        </header>

        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 overflow-hidden">
            <div className="p-8 bg-slate-50 border-b flex items-center gap-6">
               <div className="relative flex-1">
                 <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                 <input type="text" placeholder="輸入關鍵字快速搜尋..." className="w-full pl-14 pr-6 py-4 bg-white border-2 border-slate-300 rounded-2xl font-bold outline-none focus:border-blue-500 shadow-sm text-slate-900" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
               </div>
            </div>
            <table className="w-full text-left">
              <thead>
                <tr className="text-[11px] font-black text-slate-400 uppercase tracking-widest border-b">
                  <th className="px-10 py-6">名稱規格</th>
                  {activeTab === 'medicine' && <th className="px-10 py-6">有效期限</th>}
                  <th className="px-10 py-6">單據類別</th>
                  <th className="px-10 py-6 text-center">數量</th>
                  <th className="px-10 py-6 text-right">管理</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filteredItemsInTable.map(item => {
                  const isExpired = item.expiryDate && new Date(item.expiryDate) < new Date();
                  return (
                    <tr key={item.id} className="group hover:bg-slate-50 transition-all">
                      <td className="px-10 py-7">
                        <div className="font-black text-lg text-slate-900">{item.name}</div>
                        <div className="text-xs text-slate-400 font-bold">{item.spec || '未註記規格'}</div>
                      </td>
                      {activeTab === 'medicine' && (
                        <td className="px-10 py-7">
                          <div className={`flex items-center gap-2 font-bold ${isExpired ? 'text-red-600' : 'text-slate-900'}`}>
                            {isExpired ? <AlertTriangle size={14} className="animate-pulse" /> : <Clock size={14} className="text-slate-400"/>}
                            {item.expiryDate || '未填'}
                          </div>
                          {isExpired && <span className="text-[10px] font-black bg-red-100 text-red-700 px-2 py-0.5 rounded">過期！</span>}
                        </td>
                      )}
                      <td className="px-10 py-7">
                        <span className={`px-3 py-1 rounded-lg text-[10px] font-black ${item.itemType === 'EQUIPMENT' ? 'bg-orange-100 text-orange-600' : 'bg-blue-100 text-blue-600'}`}>
                          {item.itemType === 'EQUIPMENT' ? '安全衛生設備' : '安全衛生類消耗品'}
                        </span>
                      </td>
                      <td className="px-10 py-7 text-center">
                        <span className={`px-5 py-2 rounded-xl text-sm font-black ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>
                          {item.quantity} {item.unit}
                        </span>
