              <div className="grid grid-cols-2 gap-6">
                <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">計量單位</label><input type="text" className="w-full p-5 border-2 border-slate-500 rounded-2xl font-black bg-white text-slate-900" value={editTarget.unit} onChange={e=>setEditTarget({...editTarget, unit: e.target.value})}/></div>
