              {activeTab === 'inventory' ? (
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">正式單據類別</label>
                  <select className="w-full p-5 border-2 border-slate-500 rounded-2xl font-black bg-white text-slate-900 outline-none" value={newForm.itemType} onChange={e=>setNewForm({...newForm, itemType: e.target.value as ItemType})}>
