                  <div>
                    <label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest flex items-center gap-1">購入日期 <CalendarIcon size={14} className="text-slate-900"/></label>
                    <input type="date" className="w-full p-5 border-2 border-slate-500 rounded-2xl font-black bg-white text-slate-900 outline-none focus:border-blue-600" value={newForm.purchaseDate} onChange={e=>setNewForm({...newForm, purchaseDate: e.target.value})}/>
                  </div>
                  <div>
                    <label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest flex items-center gap-1">有效到期日 <CalendarIcon size={14} className="text-slate-900"/></label>
                    <input type="date" className="w-full p-5 border-2 border-slate-500 rounded-2xl font-black bg-white text-slate-900 outline-none focus:border-blue-600" value={newForm.expiryDate} onChange={e=>setNewForm({...newForm, expiryDate: e.target.value})}/>
                  </div>
                </div>
              )}
              <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">規格備註</label><input type="text" className="w-full p-5 border-2 border-slate-500 rounded-2xl font-black bg-white text-slate-900" value={newForm.spec} onChange={e=>setNewForm({...newForm, spec: e.target.value})}/></div>
              <div className="grid grid-cols-2 gap-6">
                <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">單位</label><input type="text" className="w-full p-5 border-2 border-slate-500 rounded-2xl font-black bg-white text-slate-900" value={newForm.unit} onChange={e=>setNewForm({...newForm, unit: e.target.value})}/></div>
                <div><label className="block text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">初始庫存量</label><input type="number" className="w-full p-5 border-2 border-slate-500 rounded-2xl font-black bg-white text-slate-900" value={newForm.quantity} onChange={e=>setNewForm({...newForm, quantity: Number(e.target.value)})}/></div>
              </div>
              <button onClick={handleAddItem} className="w-full py-6 bg-blue-600 text-white rounded-[2rem] font-black text-2xl shadow-xl hover:bg-blue-700 active:scale-95 transition-all">確認加入資料庫</button>
            </div>
          </div>
        </div>
      )}

      {/* 刪除確認 */}
      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[200] flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-sm p-12 shadow-2xl text-center text-slate-900">
            <AlertTriangle className="text-red-600 mx-auto mb-6" size={56} />
            <h3 className="text-3xl font-black mb-4">確認移除？</h3>
            <p className="text-slate-500 font-bold mb-10 text-lg">項目「{deleteTarget.name}」將被永久移除。</p>
            <div className="flex flex-col gap-4">
              <button onClick={confirmDelete} className="w-full py-5 bg-red-600 text-white rounded-2xl font-black shadow-lg text-xl">確認刪除</button>
              <button onClick={()=>setDeleteTarget(null)} className="w-full py-5 bg-slate-100 text-slate-400 rounded-2xl font-black text-xl">取消返回</button>
            </div>
          </div>
        </div>
      )}

      {/* 列印預覽 */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-slate-900/95 z-[100] flex flex-col items-center justify-start p-10 text-slate-900 overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] w-full max-w-5xl p-10 relative shadow-2xl my-4">
            <div className="flex justify-between items-center mb-8 no-print border-b pb-6">
               <div className="flex items-center gap-3 text-slate-900">
                 <Printer className="text-blue-600" size={32}/><span className="font-black text-3xl">領用單正式文件 (A4 預覽)</span>
               </div>
               <div className="flex gap-4">
                 <button onClick={()=>window.print()} className="bg-blue-600 text-white px-12 py-5 rounded-2xl font-black text-2xl shadow-lg hover:bg-blue-700 transition-all">立即列印</button>
                 <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full hover:bg-slate-200 transition-colors"><X size={28} className="text-slate-900"/></button>
               </div>
            </div>
            <div className="flex justify-center bg-white border-4 border-slate-100 p-4 shadow-inner overflow-hidden">
               <PrintableForm transaction={lastTransaction} />
            </div>
          </div>
        </div>
      )}

      <div className="hidden print:block absolute top-0 left-0 w-full">
         {lastTransaction && <PrintableForm transaction={lastTransaction} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  Download,
  AlertTriangle,
  BrainCircuit,
  Users,
  Stethoscope,
  Clock,
  Calendar as CalendarIcon
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v9_items_v5';
const STORAGE_KEY_LOGS = 'safeman_v9_logs_v5';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // 初始化載入
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  // 儲存與提醒
  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));

      const now = new Date();
      const expiredMedicines = items.filter(i => 
        i.itemGroup === 'MEDICINE' && i.expiryDate && new Date(i.expiryDate) < now
      );
      if (expiredMedicines.length > 0) {
        setTimeout(() => {
          window.alert(`⚠️ 系統通知：藥庫中有 ${expiredMedicines.length} 項藥品已超過有效日期。`);
        }, 800);
      }
    }
  }, [items, logs, isLoaded]);

  const handleGetAiInsights = async () => {
    setIsAiLoading(true);
    const result = await getInventoryInsights(items);
    setAiInsights(result);
    setIsAiLoading(false);
  };

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const confirmDelete = () => {
    if (!deleteTarget) return;
    setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  /**
   * 優先處理的核心邏輯：庫存攔截與更新
   */
  const handleTransaction = () => {
    // 0. 基本資料選取檢查
    if (!selectedItemId) {
      window.alert('請先選取項目名稱！');
      return;
    }

    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    // 1. 強制數值轉型與校驗
    const reqQty = parseInt(inputQty);
    const currentQty = Number(targetItem.quantity);

    if (isNaN(reqQty) || reqQty <= 0) {
      window.alert('數量欄位必須輸入大於 0 的整數數字。');
      return;
    }

    // 2. 領用出庫 - 庫存量檢查 (同步攔截關鍵點)
    if (issuanceMode === 'OUT') {
      if (reqQty > currentQty) {
        // 使用同步 Alert 確保中斷
        window.alert(
          `❌ 警告：領用失敗 (庫存不足)！\n\n` +
          `項目名稱：${targetItem.name}\n` +
          `目前庫存：${currentQty} ${targetItem.unit}\n` +
          `申請數量：${reqQty} ${targetItem.unit}\n\n` +
          `請檢查數量是否輸入錯誤或先執行入庫補貨。`
        );
        return; // 嚴格阻斷後續邏輯執行
      }
    }

    // 3. 通過檢查後，執行更新流程
    setItems(prev => prev.map(item => 
      item.id === selectedItemId 
        ? { ...item, quantity: issuanceMode === 'IN' ? Number(item.quantity) + reqQty : Number(item.quantity) - reqQty, lastUpdated: Date.now() } 
        : item
    ));

    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: reqQty,
      person: issuanceMode === 'OUT' ? (inputPerson || '未填') : '系統入庫',
      dept: issuanceMode === 'OUT' ? selectedDept : '管理課',
      reason: issuanceMode === 'OUT' ? (inputReason || '公務領用') : '採購入庫',
      timestamp: Date.now()
    };

    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    // 4. 展示回饋
    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      window.alert('✅ 入庫補貨已成功更新。');
    }

    // 5. 重置表單
    setSelectedItemId(''); setInputQty('1'); setInputPerson(''); setInputReason('');
  };

  const handleEditItem = (updatedItem: InventoryItem) => {
    setItems(prev => prev.map(item => item.id === updatedItem.id ? updatedItem : item));
    setEditTarget(null);
  };

  const [newForm, setNewForm] = useState({
    name: '', category: Category.PROTECTION, itemType: 'CONSUMABLE' as ItemType,
    itemGroup: 'INVENTORY' as ItemGroup, unit: '個', spec: '', minStock: 5, quantity: 0,
    purchaseDate: '', expiryDate: ''
  });

  const handleAddItem = () => {
    if (!newForm.name.trim()) return window.alert('名稱不得為空');
    const newItem: InventoryItem = {
      id: generateId(),
      name: newForm.name.trim(),
      category: newForm.category,
      itemType: newForm.itemType,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: newForm.unit || '個',
      spec: newForm.spec || '',
      quantity: Number(newForm.quantity) || 0,
      minStock: Number(newForm.minStock) || 0,
      purchaseDate: newForm.purchaseDate,
      expiryDate: newForm.expiryDate,
      description: '',
      lastUpdated: Date.now()
    };
    setItems(prev => [...prev, newItem]);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, itemType: 'CONSUMABLE', itemGroup: 'INVENTORY', unit: '個', spec: '', minStock: 5, quantity: 0, purchaseDate: '', expiryDate: '' });
  };

  const deptStats = useMemo(() => {
    const stats: Record<string, number> = {};
    DEPARTMENTS.forEach(d => stats[d] = 0);
    logs.filter(l => l.type === 'OUT').forEach(log => {
      if (stats[log.dept] !== undefined) stats[log.dept] += log.quantity;
    });
    return Object.entries(stats).map(([name, count]) => ({ name, count }));
  }, [logs]);

  // 領用單報表元件
  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const date = new Date(transaction.timestamp);
    const emptyRows = Array(15).fill(null);

    const isEquipment = targetItem?.itemType === 'EQUIPMENT';
    const isConsumable = targetItem?.itemType === 'CONSUMABLE';

    return (
      <div className="print-area bg-white text-black p-6 w-[210mm] mx-auto relative overflow-hidden" id="official-form-v9">
        <style>{`
          @font-face {
            font-family: 'StandardKai';
            src: local('標楷體'), local('DFKai-SB'), local('BiauKai');
          }
          #official-form-v9 { font-family: 'StandardKai', serif; font-size: 14pt; color: black !important; }
          #official-form-v9 table { border-collapse: collapse; width: 100%; border: 2.5px solid black; }
          #official-form-v9 th, #official-form-v9 td { border: 2px solid black; padding: 6px 10px; height: 38px; text-align: center; }
          @media print { .no-print { display: none !important; } }
        `}</style>

        {/* 右上角：領用編號與人員 - 淺灰色、小字、絕對定位 */}
        <div className="absolute top-4 right-8 text-[10pt] text-slate-400 font-bold text-right">
           <div>領用編號：{transaction.id}</div>
           <div>領用人員：{transaction.person}</div>
        </div>

        <h1 className="text-center text-3xl font-bold mb-8 pt-10 tracking-[0.2em]">台灣電力公司電力修護處南部分處</h1>

        <div className="flex justify-center gap-12 mb-8 font-bold text-xl">
          <label className="flex items-center gap-2">
            <span className="w-6 h-6 border-2 border-black flex items-center justify-center font-black">{isEquipment ? 'V' : ''}</span>
            安全衛生設備
          </label>
          <label className="flex items-center gap-2">
            <span className="w-6 h-6 border-2 border-black flex items-center justify-center font-black">{isConsumable ? 'V' : ''}</span>
            安全衛生類消耗品
          </label>
        </div>

        <div className="flex justify-between mb-3 font-bold px-2">
          <div>領用單位：<span className="inline-block border-b-2 border-dotted border-black min-w-[220px] text-center">{transaction.dept}</span></div>
          <div>中華民國 {date.getFullYear() - 1911} 年 {date.getMonth() + 1} 月 {date.getDate()} 日</div>
        </div>

        <table>
          <thead>
            <tr className="font-bold bg-slate-50">
              <th className="w-[35%]">名　　　　　稱</th>
              <th className="w-[25%]">規　範（序　號）</th>
              <th className="w-[10%]">單位</th>
              <th className="w-[10%]">數量</th>
              <th className="w-[20%]">備　　　　　註</th>
            </tr>
          </thead>
          <tbody>
            <tr className="font-bold">
              <td className="text-left">{transaction.itemName}</td>
              <td className="text-sm font-normal">{targetItem?.spec || ''}</td>
              <td>{targetItem?.unit || '個'}</td>
              <td className="text-2xl">{transaction.quantity}</td>
              <td className="text-left text-xs font-normal">{transaction.reason}</td>
            </tr>
            {emptyRows.map((_, idx) => <tr key={idx}><td /><td /><td /><td /><td /></tr>)}
          </tbody>
        </table>

        <div className="mt-14 font-bold grid grid-cols-2 gap-x-12">
          <div className="flex flex-col gap-10">
             <div>申請部門：</div>
             <div className="flex justify-between w-full px-2">
                <div>經辦：</div><div>課長：</div><div>經理：</div>
             </div>
          </div>
          <div className="flex flex-col gap-10">
             <div>經管部門：</div>
             <div className="flex justify-between w-full px-2">
                <div>經辦：</div><div>課長：</div><div>經理：</div>
             </div>
          </div>
        </div>
      </div>
    );
  };

  const filteredItemsInTable = useMemo(() => {
    const group = activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY';
    return items.filter(i => i.itemGroup === group && i.name.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [items, activeTab, searchTerm]);

  const issuanceItems = useMemo(() => {
    return items.filter(i => i.itemGroup === issuanceGroup);
  }, [items, issuanceGroup]);

  return (
    <div className="min-h-screen flex bg-slate-100 text-slate-900 font-sans">
