                       />
                    </div>
                 </div>
               )}

               <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="block text-xs font-bold text-slate-400 mb-1">單位</label>
                    <input type="text" className="w-full p-4 border border-slate-600 rounded-xl font-bold bg-white text-slate-900" 
                      value={editTarget ? editTarget.unit : newForm.unit} 
                      onChange={e => editTarget ? setEditTarget({...editTarget, unit: e.target.value}) : setNewForm({...newForm, unit: e.target.value})} 
                    />
                 </div>
                 <div>
                    <label className="block text-xs font-bold text-slate-400 mb-1">警戒水位量</label>
                    <input type="number" className="w-full p-4 border border-slate-600 rounded-xl font-bold bg-white text-slate-900" 
                      value={editTarget ? editTarget.minStock : newForm.minStock} 
                      onChange={e => editTarget ? setEditTarget({...editTarget, minStock: Number(e.target.value)}) : setNewForm({...newForm, minStock: Number(e.target.value)})} 
                    />
                 </div>
               </div>

               <button 
                 onClick={editTarget ? () => handleEditItem(editTarget) : handleAddItem} 
                 className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl active:scale-95 transition-all mt-4"
               >
                 確認並儲存資料
               </button>
            </div>
          </div>
        </div>
      )}

      {/* 刪除確認 */}
      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl w-full max-w-sm p-10 shadow-2xl text-center text-slate-900">
            <AlertTriangle className="text-red-600 mx-auto mb-4" size={56} />
            <h3 className="text-2xl font-black mb-2">確定刪除項目？</h3>
            <p className="text-slate-500 font-bold mb-8">「{deleteTarget.name}」將永久從資料庫移除。</p>
            <div className="space-y-3">
              <button onClick={confirmDelete} className="w-full py-4 bg-red-600 text-white rounded-xl font-black shadow-lg">確認刪除</button>
              <button onClick={()=>setDeleteTarget(null)} className="w-full py-4 bg-slate-100 text-slate-400 rounded-xl font-bold">取消</button>
            </div>
          </div>
        </div>
      )}

      {/* 單據列印預覽 */}
      {showPrintModal && lastTransaction && (
        <div className="fixed inset-0 bg-slate-900/95 z-[100] flex flex-col items-center justify-start p-10 overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] w-full max-w-5xl p-10 relative shadow-2xl my-4 text-slate-900">
            <div className="flex justify-between items-center mb-8 no-print border-b pb-6">
               <div className="flex items-center gap-3">
                 <Printer className="text-blue-600" size={32}/><span className="font-black text-2xl">台電領用單據正式文件</span>
               </div>
               <div className="flex gap-4">
                 <button onClick={()=>window.print()} className="bg-blue-600 text-white px-10 py-4 rounded-xl font-black text-xl shadow-lg hover:bg-blue-700 transition-all">立即執行列印</button>
                 <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full hover:bg-slate-200 transition-colors"><X size={24} className="text-slate-900"/></button>
               </div>
            </div>
            <div className="flex justify-center bg-white border p-4 shadow-inner overflow-hidden">
               <PrintableForm transaction={lastTransaction} />
            </div>
          </div>
        </div>
      )}

      {/* 列印用區域 */}
      <div className="hidden print:block absolute top-0 left-0 w-full">
         {lastTransaction && <PrintableForm transaction={lastTransaction} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
