               <button onClick={()=>setIssuanceGroup('MEDICINE')} className={`flex-1 py-6 rounded-2xl font-black text-2xl border-2 transition-all ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-200 text-slate-400 hover:border-slate-500'}`}>急救藥材</button>
