              <div className="space-y-4">
                <div><label className="block text-xs font-bold text-slate-400 mb-1">項目名稱</label><input type="text" className="w-full p-4 border border-slate-400 rounded-xl font-bold bg-white" value={editTarget ? editTarget.name : newForm.name} onChange={e => editTarget ? setEditTarget({...editTarget, name: e.target.value}) : setNewForm({...newForm, name: e.target.value})} /></div>
                <div><label className="block text-xs font-bold text-slate-400 mb-1">類別歸類</label><select className="w-full p-4 border border-slate-400 rounded-xl font-bold bg-white" value={editTarget ? editTarget.category : newForm.category} onChange={e => editTarget ? setEditTarget({...editTarget, category: e.target.value as Category}) : setNewForm({...newForm, category: e.target.value as Category})}>{Object.values(Category).map(c => <option key={c} value={c}>{c}</option>)}</select></div>

                {((editTarget?.itemGroup === 'MEDICINE') || (activeTab === 'medicine' && !editTarget)) && (
                  <div className="grid grid-cols-2 gap-4">
                    <div><label className="block text-xs font-bold text-slate-400 mb-1">購入日期</label><input type="date" className="w-full p-4 border border-slate-400 rounded-xl font-bold bg-white" value={editTarget ? editTarget.purchaseDate : newForm.purchaseDate} onChange={e => editTarget ? setEditTarget({...editTarget, purchaseDate: e.target.value}) : setNewForm({...newForm, purchaseDate: e.target.value})} /></div>
                    <div><label className="block text-xs font-bold text-slate-400 mb-1 text-red-500 font-black">有效期限</label><input type="date" className="w-full p-4 border border-slate-400 rounded-xl font-bold bg-white" value={editTarget ? editTarget.expiryDate : newForm.expiryDate} onChange={e => editTarget ? setEditTarget({...editTarget, expiryDate: e.target.value}) : setNewForm({...newForm, expiryDate: e.target.value})} /></div>
                  </div>
                )}

                <div className="grid grid-cols-2 gap-4">
                  <div><label className="block text-xs font-bold text-slate-400 mb-1">單位</label><input type="text" className="w-full p-4 border border-slate-400 rounded-xl font-bold bg-white" value={editTarget ? editTarget.unit : newForm.unit} onChange={e => editTarget ? setEditTarget({...editTarget, unit: e.target.value}) : setNewForm({...newForm, unit: e.target.value})} /></div>
                  <div><label className="block text-xs font-bold text-slate-400 mb-1">警戒庫存量</label><input type="number" className="w-full p-4 border border-slate-400 rounded-xl font-bold bg-white" value={editTarget ? editTarget.minStock : newForm.minStock} onChange={e => editTarget ? setEditTarget({...editTarget, minStock: Number(e.target.value)}) : setNewForm({...newForm, minStock: Number(e.target.value)})} /></div>
                </div>
                <button onClick={editTarget ? () => handleEditItem(editTarget) : handleAddItem} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl mt-4">確認儲存</button>
              </div>
            </div>
          </div>
        )}

        {showPrintModal && lastTransaction && (
          <div className="fixed inset-0 bg-slate-900/95 z-[100] flex flex-col items-center justify-start p-10 overflow-y-auto">
            <div className="bg-white rounded-[2.5rem] w-full max-w-5xl p-10 relative shadow-2xl my-4 text-slate-900">
              <div className="flex justify-between items-center mb-8 no-print border-b pb-6">
                 <div className="flex items-center gap-3"><Printer className="text-blue-600" size={32}/><span className="font-black text-2xl">正式領用單文件</span></div>
                 <div className="flex gap-4"><button onClick={()=>window.print()} className="bg-blue-600 text-white px-10 py-4 rounded-xl font-black text-xl">立即列印</button><button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full text-slate-900"><X size={24}/></button></div>
              </div>
              <div className="flex justify-center bg-white border p-4 shadow-inner overflow-hidden"><PrintableForm transaction={lastTransaction} /></div>
            </div>
          </div>
        )}
      </main>

      <div className="hidden print:block absolute top-0 left-0 w-full">{lastTransaction && <PrintableForm transaction={lastTransaction} />}</div>
    </div>
  );
};

export default App;

