const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // 初始化載入
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  // 儲存資料
  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const handleGetAiInsights = async () => {
    setIsAiLoading(true);
    const result = await getInventoryInsights(items);
    setAiInsights(result);
    setIsAiLoading(false);
  };

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  // 【修復】刪除功能
  const confirmDelete = () => {
    if (!deleteTarget) return;
    setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  /**
   * 【核心修復】庫存更新與嚴格攔截邏輯
   */
  const handleTransaction = () => {
    if (!selectedItemId) {
      window.alert('錯誤：請先選取項目！');
      return;
    }

    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    const reqQty = parseInt(inputQty);
    const availableQty = Number(targetItem.quantity);

    if (isNaN(reqQty) || reqQty <= 0) {
      window.alert('錯誤：請輸入有效的領用數量。');
      return;
    }

    // 【最強庫存攔截】
    if (issuanceMode === 'OUT') {
      if (reqQty > availableQty) {
        window.alert(
          `❌ 警告：庫存量不足，無法領用！\n\n` +
          `項目名稱：${targetItem.name}\n` +
          `目前庫存：${availableQty} ${targetItem.unit}\n` +
          `您要領用：${reqQty} ${targetItem.unit}\n\n` +
          `操作已終止。請調整數量或先執行補貨。`
        );
        return; // 這裡絕對會中斷程序
      }
    }

    // 更新資料庫
    setItems(prev => prev.map(item => 
      item.id === selectedItemId 
        ? { ...item, quantity: issuanceMode === 'IN' ? Number(item.quantity) + reqQty : Number(item.quantity) - reqQty, lastUpdated: Date.now() } 
        : item
    ));

    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: reqQty,
      person: issuanceMode === 'OUT' ? (inputPerson || '未填') : '管理員',
      dept: issuanceMode === 'OUT' ? selectedDept : '採購組',
      reason: issuanceMode === 'OUT' ? (inputReason || '公務使用') : '庫存補貨',
      timestamp: Date.now()
    };

    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      window.alert('✅ 庫存補貨已成功更新。');
    }

    setSelectedItemId(''); setInputQty('1'); setInputPerson(''); setInputReason('');
  };

  const handleEditItem = (updatedItem: InventoryItem) => {
    setItems(prev => prev.map(item => item.id === updatedItem.id ? updatedItem : item));
    setEditTarget(null);
  };

  const [newForm, setNewForm] = useState({
    name: '', category: Category.PROTECTION, itemType: 'CONSUMABLE' as ItemType,
    itemGroup: 'INVENTORY' as ItemGroup, unit: '個', spec: '', minStock: 5, quantity: 0,
    purchaseDate: '', expiryDate: ''
  });

  const handleAddItem = () => {
    if (!newForm.name.trim()) return window.alert('請輸入名稱');
    const newItem: InventoryItem = {
      id: generateId(),
      name: newForm.name.trim(),
      category: newForm.category,
      itemType: newForm.itemType,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: newForm.unit || '個',
      spec: newForm.spec || '',
      quantity: Number(newForm.quantity) || 0,
      minStock: Number(newForm.minStock) || 0,
      purchaseDate: newForm.purchaseDate,
      expiryDate: newForm.expiryDate,
      description: '',
      lastUpdated: Date.now()
    };
    setItems(prev => [...prev, newItem]);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, itemType: 'CONSUMABLE', itemGroup: 'INVENTORY', unit: '個', spec: '', minStock: 5, quantity: 0, purchaseDate: '', expiryDate: '' });
  };

  // 領用單報表
  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const date = new Date(transaction.timestamp);
    const emptyRows = Array(15).fill(null);

    return (
      <div className="print-area bg-white text-black p-6 w-[210mm] mx-auto relative overflow-hidden" id="official-form-v11">
        <style>{`
          @font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); }
          #official-form-v11 { font-family: 'StandardKai', serif; font-size: 14pt; color: black !important; }
          #official-form-v11 table { border-collapse: collapse; width: 100%; border: 2.5px solid black; }
          #official-form-v11 th, #official-form-v11 td { border: 2px solid black; padding: 6px 10px; height: 38px; text-align: center; }
          @media print { .no-print { display: none !important; } }
        `}</style>

        <div className="absolute top-4 right-8 text-[10pt] text-slate-400 font-bold text-right leading-relaxed">
           <div>領用編號：{transaction.id}</div>
           <div>領用人員：{transaction.person}</div>
        </div>

        <h1 className="text-center text-3xl font-bold mb-8 pt-10 tracking-[0.2em]">台灣電力公司電力修護處南部分處</h1>

        <div className="flex justify-center gap-12 mb-8 font-bold text-xl">
          <label className="flex items-center gap-2">
            <span className="w-6 h-6 border-2 border-black flex items-center justify-center font-black">
              {targetItem?.itemType === 'EQUIPMENT' ? 'V' : ''}
            </span> 安全衛生設備
          </label>
          <label className="flex items-center gap-2">
            <span className="w-6 h-6 border-2 border-black flex items-center justify-center font-black">
              {targetItem?.itemType === 'CONSUMABLE' ? 'V' : ''}
            </span> 安全衛生類消耗品
          </label>
        </div>

        <div className="flex justify-between mb-3 font-bold px-2">
          <div>領用單位：<span className="inline-block border-b-2 border-dotted border-black min-w-[220px] text-center">{transaction.dept}</span></div>
          <div>中華民國 {date.getFullYear() - 1911} 年 {date.getMonth() + 1} 月 {date.getDate()} 日</div>
        </div>

        <table>
          <thead>
            <tr className="bg-slate-50 font-bold">
              <th className="w-[35%]">名　　　　　稱</th><th className="w-[25%]">規　範（序　號）</th>
              <th className="w-[10%]">單位</th><th className="w-[10%]">數量</th><th className="w-[20%]">備　　　　　註</th>
            </tr>
          </thead>
          <tbody>
            <tr className="font-bold">
              <td className="text-left">{transaction.itemName}</td>
              <td className="text-sm font-normal">{targetItem?.spec || ''}</td>
              <td>{targetItem?.unit || '個'}</td>
              <td className="text-2xl">{transaction.quantity}</td>
              <td className="text-left text-xs font-normal">{transaction.reason}</td>
            </tr>
            {emptyRows.map((_, idx) => <tr key={idx}><td /><td /><td /><td /><td /></tr>)}
          </tbody>
        </table>

        <div className="mt-14 font-bold grid grid-cols-2 gap-x-12">
          <div className="flex flex-col gap-10"><div>申請部門：</div><div className="flex justify-between w-full px-2 text-sm"><div>經辦：</div><div>課長：</div><div>經理：</div></div></div>
          <div className="flex flex-col gap-10"><div>經管部門：</div><div className="flex justify-between w-full px-2 text-sm"><div>經辦：</div><div>課長：</div><div>經理：</div></div></div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-slate-100 text-slate-900 font-sans">
      <style>{`
        /* 日期選擇器視覺：確保圖示為深色，清楚可見 */
        input[type="date"]::-webkit-calendar-picker-indicator {
          filter: invert(0%) sepia(0%) saturate(100%) hue-rotate(0deg) brightness(30%) contrast(100%);
          cursor: pointer;
          font-size: 1.1rem;
        }
        input[type="date"] {
          color-scheme: light;
          font-weight: 500;
          background-color: white !important;
        }
        select, input {
          background-color: white !important;
        }
      `}</style>

      <aside className="no-print w-72 bg-slate-900 text-white p-8 flex flex-col shrink-0">
        <div className="flex items-center gap-3 mb-12">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg"><Package size={22}/></div>
          <div><h1 className="font-black text-lg">工安管理系統</h1><p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">V11 Stable</p></div>
        </div>
        <nav className="flex-1 space-y-3">
          {[
            { id: 'inventory', label: '工安耗材管理', icon: Package },
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
            { id: 'issuance', label: '領用登記作業', icon: FileText },
            { id: 'history', label: '歷史異動日誌', icon: History },
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard },
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-xl' : 'text-slate-400 hover:bg-slate-800'}`}>
              <tab.icon size={20} /> {tab.label}
            </button>
          ))}
        </nav>
      </aside>

      <main className="no-print flex-1 p-10 overflow-y-auto">
        <header className="mb-10 flex justify-between items-center text-slate-900">
          <h2 className="text-3xl font-black">{activeTab === 'inventory' ? '工安耗材清冊' : activeTab === 'medicine' ? '急救藥材清冊' : activeTab === 'issuance' ? '領用/補貨作業' : activeTab === 'history' ? '歷史異動日誌' : '數據中心'}</h2>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-3 shadow-lg hover:bg-black transition-all">
              <Plus size={18}/> 新增項目
            </button>
          )}
        </header>

        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden text-slate-900">
            <div className="p-6 bg-slate-50 border-b">
               <div className="relative max-w-md">
                 <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                 <input type="text" placeholder="輸入關鍵字..." className="w-full pl-12 pr-4 py-3 bg-white border border-slate-300 rounded-xl font-bold outline-none focus:border-blue-500 shadow-sm" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
               </div>
            </div>
            <table className="w-full text-left">
              <thead>
                <tr className="text-[11px] font-black text-slate-400 uppercase tracking-widest border-b">
                  <th className="px-8 py-4">名稱與類別</th><th className="px-8 py-4 text-center">庫存數量</th><th className="px-8 py-4 text-right">操作</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(i => (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-8 py-5">
                      <div className="font-bold">{item.name}</div>
                      <div className="text-xs text-slate-400 font-medium">
                        {item.itemType === 'EQUIPMENT' ? '安全衛生設備' : '安全衛生類消耗品'} / {item.spec || '無規格'}
                      </div>
                    </td>
                    <td className="px-8 py-5 text-center">
                      <span className={`px-4 py-1.5 rounded-lg text-sm font-black ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>{item.quantity} {item.unit}</span>
                    </td>
                    <td className="px-8 py-5 text-right flex items-center justify-end gap-1">
                      <button onClick={() => setEditTarget(item)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg"><Edit3 size={16}/></button>
                      <button onClick={() => setDeleteTarget({id: item.id, name: item.name})} className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg"><Trash2 size={16}/></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'issuance' && (
          <div className="max-w-4xl mx-auto bg-white p-12 rounded-[2.5rem] shadow-xl border border-slate-100 text-slate-900">
             <div className="flex bg-slate-100 p-2 rounded-2xl mb-10">
               <button onClick={()=>setIssuanceMode('OUT')} className={`flex-1 py-6 rounded-xl font-black text-2xl transition-all ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button>
               <button onClick={()=>setIssuanceMode('IN')} className={`flex-1 py-6 rounded-xl font-black text-2xl transition-all ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
             </div>

             <div className="flex gap-4 mb-12">
               <button onClick={()=>setIssuanceGroup('INVENTORY')} className={`flex-1 py-6 rounded-2xl font-black text-2xl border-2 transition-all ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-200 text-slate-400 hover:border-slate-500'}`}>工安耗材</button>
               <button onClick={()=>setIssuanceGroup('MEDICINE')} className={`flex-1 py-6 rounded-2xl font-black text-2xl border-2 transition-all ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-200 text-slate-400 hover:border-slate-500'}`}>急救藥材</button>
             </div>

             <div className="grid grid-cols-1 gap-6">
                <div>
                  <label className="block text-sm font-bold text-slate-500 mb-2 uppercase">選取項目 (顯示剩餘庫存)</label>
                  <select className="w-full p-4 border-2 border-slate-500 rounded-xl font-bold bg-white text-lg" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                    <option value="">-- 請點擊選取 --</option>
                    {items.filter(i => i.itemGroup === issuanceGroup).map(i=>(
                      <option key={i.id} value={i.id}>{i.name} (庫存: {i.quantity} {i.unit})</option>
                    ))}
                  </select>
                </div>

                <div className="grid grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-bold text-slate-500 mb-2 uppercase">操作數量</label>
                    <input type="number" min="1" className="w-full p-4 border-2 border-slate-500 rounded-xl font-bold text-lg" value={inputQty} onChange={e=>setInputQty(e.target.value)}/>
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-slate-500 mb-2 uppercase">領用單位</label>
                    <select className="w-full p-4 border-2 border-slate-500 rounded-xl font-bold text-lg" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>
                      {DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
                    </select>
                  </div>
                </div>

                {issuanceMode === 'OUT' && (
                  <div className="grid grid-cols-2 gap-6">
                    <div><label className="block text-sm font-bold text-slate-500 mb-2 uppercase">領用人姓名</label><input type="text" className="w-full p-4 border-2 border-slate-500 rounded-xl font-bold text-lg" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div>
                    <div><label className="block text-sm font-bold text-slate-500 mb-2 uppercase">領用用途</label><input type="text" className="w-full p-4 border-2 border-slate-500 rounded-xl font-bold text-lg" value={inputReason} onChange={e=>setInputReason(e.target.value)}/></div>
                  </div>
                )}

                <button onClick={handleTransaction} className={`w-full py-6 rounded-2xl font-black text-white text-3xl shadow-xl transition-all active:scale-95 mt-6 ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>
                  {issuanceMode === 'OUT' ? '列印領用單並更新' : '完成補貨入庫'}
                </button>
             </div>
          </div>
        )}

        {/* 編輯與新增視窗 */}
        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md z-[200] flex items-center justify-center p-4 text-slate-900">
            <div className="bg-white rounded-3xl w-full max-w-lg p-10 shadow-2xl">
              <div className="flex justify-between items-center mb-8"><h3 className="font-black text-2xl">{editTarget ? '編輯項目' : '新增項目'}</h3><button onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="p-2 bg-slate-100 rounded-full hover:bg-slate-200"><X/></button></div>
              <div className="space-y-4">
                <div><label className="block text-xs font-bold text-slate-400 mb-1 uppercase">項目名稱</label><input type="text" className="w-full p-4 border-2 border-slate-500 rounded-xl font-bold bg-white" value={editTarget ? editTarget.name : newForm.name} onChange={e => editTarget ? setEditTarget({...editTarget, name: e.target.value}) : setNewForm({...newForm, name: e.target.value})} /></div>

                <div>
                  <label className="block text-xs font-bold text-slate-400 mb-1 uppercase">單據類別</label>
                  <select className="w-full p-4 border-2 border-slate-500 rounded-xl font-bold bg-white" value={editTarget ? editTarget.itemType : newForm.itemType} onChange={e => editTarget ? setEditTarget({...editTarget, itemType: e.target.value as ItemType}) : setNewForm({...newForm, itemType: e.target.value as ItemType})}>
                    <option value="EQUIPMENT">安全衛生設備</option>
                    <option value="CONSUMABLE">安全衛生類消耗品</option>
                  </select>
                </div>

                {((editTarget?.itemGroup === 'MEDICINE') || (activeTab === 'medicine' && !editTarget)) && (
                  <div className="grid grid-cols-2 gap-4">
                    <div><label className="block text-xs font-bold text-slate-400 mb-1 uppercase">購入日期</label><input type="date" className="w-full p-4 border-2 border-slate-500 rounded-xl font-bold" value={editTarget ? editTarget.purchaseDate : newForm.purchaseDate} onChange={e => editTarget ? setEditTarget({...editTarget, purchaseDate: e.target.value}) : setNewForm({...newForm, purchaseDate: e.target.value})} /></div>
                    <div><label className="block text-xs font-bold text-slate-400 mb-1 uppercase text-red-500 font-black">有效期限</label><input type="date" className="w-full p-4 border-2 border-slate-500 rounded-xl font-bold" value={editTarget ? editTarget.expiryDate : newForm.expiryDate} onChange={e => editTarget ? setEditTarget({...editTarget, expiryDate: e.target.value}) : setNewForm({...newForm, expiryDate: e.target.value})} /></div>
                  </div>
                )}

                <div className="grid grid-cols-2 gap-4">
                  <div><label className="block text-xs font-bold text-slate-400 mb-1 uppercase">單位</label><input type="text" className="w-full p-4 border-2 border-slate-500 rounded-xl font-bold" value={editTarget ? editTarget.unit : newForm.unit} onChange={e => editTarget ? setEditTarget({...editTarget, unit: e.target.value}) : setNewForm({...newForm, unit: e.target.value})} /></div>
                  <div><label className="block text-xs font-bold text-slate-400 mb-1 uppercase">低庫存警告量</label><input type="number" className="w-full p-4 border-2 border-slate-500 rounded-xl font-bold" value={editTarget ? editTarget.minStock : newForm.minStock} onChange={e => editTarget ? setEditTarget({...editTarget, minStock: Number(e.target.value)}) : setNewForm({...newForm, minStock: Number(e.target.value)})} /></div>
                </div>
                <button onClick={editTarget ? () => handleEditItem(editTarget) : handleAddItem} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl mt-4">確認儲存項目</button>
              </div>
            </div>
          </div>
        )}

        {/* 刪除確認視窗 */}
        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-4">
            <div className="bg-white rounded-3xl w-full max-w-sm p-10 shadow-2xl text-center text-slate-900">
              <AlertTriangle className="text-red-600 mx-auto mb-4" size={56} />
              <h3 className="text-2xl font-black mb-2">確認刪除項目？</h3>
              <p className="text-slate-500 font-bold mb-8">項目「{deleteTarget.name}」將永久移除。</p>
              <div className="space-y-3">
                <button onClick={confirmDelete} className="w-full py-4 bg-red-600 text-white rounded-xl font-black shadow-lg">執行刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="w-full py-4 bg-slate-100 text-slate-400 rounded-xl font-bold">取消</button>
              </div>
            </div>
          </div>
        )}

        {showPrintModal && lastTransaction && (
          <div className="fixed inset-0 bg-slate-900/95 z-[100] flex flex-col items-center justify-start p-10 overflow-y-auto">
            <div className="bg-white rounded-[2.5rem] w-full max-w-5xl p-10 relative shadow-2xl my-4 text-slate-900">
              <div className="flex justify-between items-center mb-8 no-print border-b pb-6">
                 <div className="flex items-center gap-3"><Printer className="text-blue-600" size={32}/><span className="font-black text-2xl">台電正式領用單文件 (V11)</span></div>
                 <div className="flex gap-4">
                    <button onClick={()=>window.print()} className="bg-blue-600 text-white px-10 py-4 rounded-xl font-black text-xl">立即列印</button>
                    <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full text-slate-900"><X size={24}/></button>
                 </div>
              </div>
              <div className="flex justify-center bg-white border p-4 shadow-inner overflow-hidden"><PrintableForm transaction={lastTransaction} /></div>
            </div>
          </div>
        )}
      </main>

      <div className="hidden print:block absolute top-0 left-0 w-full">{lastTransaction && <PrintableForm transaction={lastTransaction} />}</div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
