               <h3 className="text-6xl font-black text-orange-600 mt-2">{items.filter(i=>i.itemGroup==='INVENTORY' && i.quantity <= i.minStock).length}</h3>
            </div>
            <div className="bg-white p-8 rounded-3xl shadow-sm border-t-8 border-t-red-500">
               <p className="text-slate-400 font-bold text-sm uppercase">低庫存急救藥材</p>
               <h3 className="text-6xl font-black text-red-600 mt-2">{items.filter(i=>i.itemGroup==='MEDICINE' && i.quantity <= i.minStock).length}</h3>
            </div>
            <div className="bg-slate-900 p-8 rounded-3xl shadow-xl flex flex-col justify-between">
               <p className="text-slate-500 font-bold text-sm uppercase">AI 營運建議</p>
               <button onClick={handleGetAiInsights} className="mt-4 px-6 py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-500 transition-all flex items-center justify-center gap-2">
                 <BrainCircuit size={18}/> {isAiLoading ? '分析中...' : '生成報告'}
               </button>
            </div>
            {aiInsights && <div className="md:col-span-3 bg-blue-50 p-8 rounded-3xl border border-blue-100 text-blue-900 font-bold whitespace-pre-wrap leading-relaxed">{aiInsights}</div>}
