              </thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(i => (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-8 py-5">
                      <div className="font-bold text-slate-900">{item.name}</div>
                      <div className="text-xs text-slate-400 font-medium">
                        {item.itemType === 'EQUIPMENT' ? '安全衛生設備' : '安全衛生類消耗品'} / {item.spec || '預設規格'}
                        {item.expiryDate && <span className={`ml-2 px-1.5 py-0.5 rounded ${new Date(item.expiryDate) < new Date() ? 'bg-red-100 text-red-600 font-black' : 'text-slate-400'}`}>效期: {item.expiryDate}</span>}
                      </div>
                    </td>
                    <td className="px-8 py-5 text-center">
                      <span className={`px-4 py-1.5 rounded-lg text-sm font-black ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>{item.quantity} {item.unit}</span>
                    </td>
                    <td className="px-8 py-5 text-right flex items-center justify-end gap-1">
                      <button onClick={() => setEditTarget(item)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg"><Edit3 size={16}/></button>
                      <button onClick={() => setDeleteTarget({id: item.id, name: item.name})} className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg"><Trash2 size={16}/></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* 領用/補貨登記 (V13 核心：補貨模式下簡化欄位) */}
        {activeTab === 'issuance' && (
          <div className="max-w-4xl mx-auto bg-white p-12 rounded-[2.5rem] shadow-xl border border-slate-100 text-slate-900">
             <div className="flex bg-slate-100 p-2 rounded-2xl mb-8">
               <button onClick={()=>setIssuanceMode('OUT')} className={`flex-1 py-5 rounded-xl font-black text-2xl transition-all ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button>
               <button onClick={()=>setIssuanceMode('IN')} className={`flex-1 py-5 rounded-xl font-black text-2xl transition-all ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
             </div>

             <div className="flex gap-4 mb-8">
               <button onClick={()=>setIssuanceGroup('INVENTORY')} className={`flex-1 py-5 rounded-2xl font-black text-2xl border-2 transition-all ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-200 text-slate-400'}`}>工安耗材</button>
               <button onClick={()=>setIssuanceGroup('MEDICINE')} className={`flex-1 py-5 rounded-2xl font-black text-2xl border-2 transition-all ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-200 text-slate-400'}`}>急救藥材</button>
             </div>

             <div className="grid grid-cols-1 gap-6">
                <div>
                  <label className="block text-sm font-bold text-slate-500 mb-2 uppercase tracking-wide">選取項目 (顯示剩餘庫存)</label>
                  <select className="w-full p-4 border-2 border-slate-400 rounded-xl font-bold text-lg bg-white text-slate-900 shadow-sm" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                    <option value="">-- 請點擊開啟下拉選單 --</option>
                    {items.filter(i => i.itemGroup === issuanceGroup).map(i=>(
                      <option key={i.id} value={i.id}>{i.name} (剩餘: {i.quantity} {i.unit})</option>
                    ))}
                  </select>
                </div>

                <div className="grid grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-bold text-slate-500 mb-2 uppercase tracking-wide">輸入數量</label>
                    <input type="number" min="1" className="w-full p-4 border-2 border-slate-400 rounded-xl font-bold text-lg bg-white text-slate-900 shadow-sm" value={inputQty} onChange={e=>setInputQty(e.target.value)}/>
                  </div>
                  {issuanceMode === 'OUT' ? (
                    <div>
                      <label className="block text-sm font-bold text-slate-500 mb-2 uppercase tracking-wide">領用單位</label>
                      <select className="w-full p-4 border-2 border-slate-400 rounded-xl font-bold text-lg bg-white text-slate-900 shadow-sm" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>
                        {DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
                      </select>
                    </div>
                  ) : (
                    <div>
                      <label className="block text-sm font-bold text-slate-500 mb-2 uppercase tracking-wide">補貨日期</label>
                      <div className="w-full p-4 border-2 border-slate-200 bg-slate-50 text-slate-400 rounded-xl font-bold text-lg">{new Date().toLocaleDateString()}</div>
                    </div>
                  )}
                </div>

                {issuanceMode === 'OUT' && (
                  <div className="grid grid-cols-2 gap-6">
                    <div><label className="block text-sm font-bold text-slate-500 mb-2 uppercase tracking-wide">領用人</label><input type="text" className="w-full p-4 border-2 border-slate-400 rounded-xl font-bold text-lg bg-white text-slate-900 shadow-sm" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div>
                    <div><label className="block text-sm font-bold text-slate-500 mb-2 uppercase tracking-wide">用途/事由</label><input type="text" className="w-full p-4 border-2 border-slate-400 rounded-xl font-bold text-lg bg-white text-slate-900 shadow-sm" value={inputReason} onChange={e=>setInputReason(e.target.value)}/></div>
                  </div>
                )}

                <button onClick={handleTransaction} className={`w-full py-6 rounded-2xl font-black text-white text-3xl shadow-xl transition-all active:scale-95 mt-4 ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>
                  {issuanceMode === 'OUT' ? '確認領用並列印單據' : '完成補貨入庫作業'}
                </button>
             </div>
          </div>
        )}

        {/* 歷史異動日誌 (明確標註 領用/補貨) */}
        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden text-slate-900">
             <table className="w-full text-left">
               <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase border-b">
                 <tr><th className="px-8 py-5">時間</th><th className="px-8 py-5">類型</th><th className="px-8 py-5">內容項目</th><th className="px-8 py-5">經手人/單位</th><th className="px-8 py-5 text-right">管理</th></tr>
               </thead>
               <tbody className="divide-y divide-slate-100">
                 {logs.map(log => (
                   <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                     <td className="px-8 py-5 text-xs text-slate-400 font-mono">{new Date(log.timestamp).toLocaleString()}</td>
                     <td className="px-8 py-5">
                        <span className={`px-3 py-1 rounded-full text-xs font-black ${log.type === 'OUT' ? 'bg-blue-100 text-blue-600' : 'bg-emerald-100 text-emerald-600'}`}>
                          {log.type === 'OUT' ? '領用' : '補貨'}
                        </span>
                     </td>
                     <td className="px-8 py-5 font-bold text-slate-900">{log.itemName} (x{log.quantity})</td>
                     <td className="px-8 py-5 text-sm">
                        <div className="font-bold">{log.person}</div>
                        <div className="text-[10px] text-slate-400">{log.dept}</div>
                     </td>
                     <td className="px-8 py-5 text-right">
                        {log.type === 'OUT' && <button onClick={()=>{setLastTransaction(log);setShowPrintModal(true);}} className="text-slate-400 hover:text-blue-600 p-2"><Printer size={18}/></button>}
                     </td>
                   </tr>
                 ))}
                 {logs.length === 0 && <tr><td colSpan={5} className="p-20 text-center text-slate-400 font-bold">目前無異動紀錄</td></tr>}
               </tbody>
             </table>
          </div>
        )}

        {/* 數據看板 (增加過期統計) */}
        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <div className="bg-white p-8 rounded-3xl shadow-sm border-l-8 border-l-blue-500">
               <p className="text-slate-400 font-bold text-sm uppercase">總項目數</p>
               <h3 className="text-5xl font-black text-slate-900 mt-2">{items.length}</h3>
            </div>
            <div className="bg-white p-8 rounded-3xl shadow-sm border-l-8 border-l-orange-500">
               <p className="text-slate-400 font-bold text-sm uppercase">庫存不足警示</p>
               <h3 className="text-5xl font-black text-orange-600 mt-2">{items.filter(i=>i.quantity <= i.minStock).length}</h3>
            </div>
            <div className="bg-white p-8 rounded-3xl shadow-sm border-l-8 border-l-red-500">
               <p className="text-slate-400 font-bold text-sm uppercase">已過期藥材數</p>
               <h3 className="text-5xl font-black text-red-600 mt-2">{expiredMedicineCount}</h3>
            </div>
            <div className="bg-slate-900 p-8 rounded-3xl shadow-xl flex flex-col justify-center">
               <button onClick={async () => { setIsAiLoading(true); setAiInsights(await getInventoryInsights(items)); setIsAiLoading(false); }} className="w-full py-4 bg-blue-600 text-white rounded-xl font-bold flex items-center justify-center gap-2 hover:bg-blue-500">
                 <BrainCircuit size={18}/> {isAiLoading ? '分析中...' : '生成管理報告'}
               </button>
            </div>
            {aiInsights && <div className="lg:col-span-4 bg-blue-50 p-8 rounded-3xl border border-blue-100 text-blue-900 font-bold whitespace-pre-wrap leading-relaxed">{aiInsights}</div>}
          </div>
        )}

        {/* 新增/編輯 Modal (文字顏色絕對修復) */}
        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-lg p-10 shadow-2xl">
              <div className="flex justify-between items-center mb-6">
                <h3 className="font-black text-2xl text-slate-900">{editTarget ? '編輯項目資料' : '新增管理項目'}</h3>
                <button onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="p-2 bg-slate-100 rounded-full text-slate-900"><X size={20}/></button>
              </div>
              <div className="space-y-4">
                <div>
                  <label className="block text-xs font-black text-slate-500 mb-1 uppercase">名稱</label>
                  <input type="text" className="w-full p-4 border-2 border-slate-400 rounded-xl font-bold bg-white text-slate-900" 
                    value={editTarget ? editTarget.name : newForm.name} 
                    onChange={e => editTarget ? setEditTarget({...editTarget, name: e.target.value}) : setNewForm({...newForm, name: e.target.value})} />
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-500 mb-1 uppercase">單據類別</label>
                  <select className="w-full p-4 border-2 border-slate-400 rounded-xl font-bold bg-white text-slate-900" 
                    value={editTarget ? editTarget.itemType : newForm.itemType} 
                    onChange={e => editTarget ? setEditTarget({...editTarget, itemType: e.target.value as ItemType}) : setNewForm({...newForm, itemType: e.target.value as ItemType})}>
                    <option value="EQUIPMENT">安全衛生設備</option>
                    <option value="CONSUMABLE">安全衛生類消耗品</option>
                  </select>
                </div>
                {((editTarget?.itemGroup === 'MEDICINE') || (activeTab === 'medicine' && !editTarget)) && (
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-xs font-black text-slate-500 mb-1 uppercase">購入日</label>
                      <input type="date" className="w-full p-4 border-2 border-slate-400 rounded-xl font-bold bg-white text-slate-900" 
                        value={editTarget ? editTarget.purchaseDate : newForm.purchaseDate} 
                        onChange={e => editTarget ? setEditTarget({...editTarget, purchaseDate: e.target.value}) : setNewForm({...newForm, purchaseDate: e.target.value})} />
                    </div>
                    <div>
                      <label className="block text-xs font-black text-red-500 mb-1 uppercase">效期日</label>
                      <input type="date" className="w-full p-4 border-2 border-slate-400 rounded-xl font-bold bg-white text-slate-900" 
                        value={editTarget ? editTarget.expiryDate : newForm.expiryDate} 
                        onChange={e => editTarget ? setEditTarget({...editTarget, expiryDate: e.target.value}) : setNewForm({...newForm, expiryDate: e.target.value})} />
                    </div>
                  </div>
                )}
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-black text-slate-500 mb-1 uppercase">單位</label>
                    <input type="text" className="w-full p-4 border-2 border-slate-400 rounded-xl font-bold bg-white text-slate-900" 
                      value={editTarget ? editTarget.unit : newForm.unit} 
                      onChange={e => editTarget ? setEditTarget({...editTarget, unit: e.target.value}) : setNewForm({...newForm, unit: e.target.value})} />
                  </div>
                  <div>
                    <label className="block text-xs font-black text-slate-500 mb-1 uppercase">低庫存警告</label>
                    <input type="number" className="w-full p-4 border-2 border-slate-400 rounded-xl font-bold bg-white text-slate-900" 
                      value={editTarget ? editTarget.minStock : newForm.minStock} 
                      onChange={e => editTarget ? setEditTarget({...editTarget, minStock: Number(e.target.value)}) : setNewForm({...newForm, minStock: Number(e.target.value)})} />
                  </div>
                </div>
                <button onClick={editTarget ? () => { setItems(prev => prev.map(i => i.id === editTarget.id ? editTarget : i)); setEditTarget(null); } : handleAddItem} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl mt-4">儲存並應用</button>
              </div>
            </div>
          </div>
        )}

        {/* 刪除 Modal (縮小寬度修復) */}
        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
            <div className="bg-white rounded-3xl w-full max-w-[320px] p-8 shadow-2xl text-center">
              <div className="w-16 h-16 bg-red-50 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4">
                <AlertTriangle size={32} />
              </div>
              <h3 className="text-xl font-black mb-2 text-slate-900">確認要刪除？</h3>
              <p className="text-slate-500 text-sm font-bold mb-8">「{deleteTarget.name}」將無法復原。</p>
              <div className="space-y-2">
                <button onClick={confirmDelete} className="w-full py-3 bg-red-600 text-white rounded-xl font-black">執行刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="w-full py-3 bg-slate-100 text-slate-400 rounded-xl font-bold">先不要</button>
              </div>
            </div>
          </div>
        )}

        {/* 列印 Modal */}
        {showPrintModal && lastTransaction && (
          <div className="fixed inset-0 bg-slate-900/95 z-[100] flex flex-col items-center justify-start p-10 overflow-y-auto">
            <div className="bg-white rounded-[2.5rem] w-full max-w-5xl p-10 relative shadow-2xl my-4">
              <div className="flex justify-between items-center mb-8 no-print border-b pb-6">
                 <div className="flex items-center gap-3"><Printer className="text-blue-600" size={32}/><span className="font-black text-2xl text-slate-900">領用單正式文件 (V13)</span></div>
                 <div className="flex gap-4">
                    <button onClick={()=>window.print()} className="bg-blue-600 text-white px-10 py-4 rounded-xl font-black text-xl shadow-xl">執行列印</button>
                    <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full text-slate-900"><X size={24}/></button>
                 </div>
              </div>
              <div className="flex justify-center bg-white border p-4 overflow-hidden shadow-inner"><PrintableForm transaction={lastTransaction} /></div>
            </div>
          </div>
        )}
      </main>

      <div className="hidden print:block absolute top-0 left-0 w-full">{lastTransaction && <PrintableForm transaction={lastTransaction} />}</div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  Calendar as CalendarIcon
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

// 維持 V13 Key 確保資料延續，不讓用戶重新輸入
const STORAGE_KEY_ITEMS = 'safeman_v13_audit_items';
const STORAGE_KEY_LOGS = 'safeman_v13_audit_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);

  // 初始化載入
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  // 儲存資料
  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const confirmDelete = () => {
    if (!deleteTarget) return;
    setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  /**
   * 【核心功能】庫存嚴格攔截與更新
   */
  const handleTransaction = () => {
    if (!selectedItemId) {
      window.alert('⚠️ 錯誤：請先選取項目！');
      return;
    }

    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    // 數值強制轉換，確保計算精確
    const reqQty = Number(inputQty);
    const availableQty = Number(targetItem.quantity);

    if (isNaN(reqQty) || reqQty <= 0) {
      window.alert('⚠️ 數量輸入無效，請輸入正整數。');
      return;
    }

    // 【庫存攔截機制】領用不可超過庫存
    if (issuanceMode === 'OUT') {
      if (reqQty > availableQty) {
        window.alert(
          `❌ 庫存不足警告！\n\n` +
          `項目：${targetItem.name}\n` +
          `現有庫存：${availableQty} ${targetItem.unit}\n` +
          `欲領數量：${reqQty} ${targetItem.unit}\n\n` +
          `操作已取消，請調整領用數量。`
        );
        return; // 直接中斷執行
      }
    }

    // 更新 Items
    setItems(prev => prev.map(item => 
      item.id === selectedItemId 
        ? { ...item, quantity: issuanceMode === 'IN' ? Number(item.quantity) + reqQty : Number(item.quantity) - reqQty, lastUpdated: Date.now() } 
        : item
    ));

    // 建立日誌
    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: reqQty,
      person: issuanceMode === 'OUT' ? (inputPerson || '未填寫') : '管理員補貨',
      dept: issuanceMode === 'OUT' ? selectedDept : '庫房管理',
      reason: issuanceMode === 'OUT' ? (inputReason || '領用') : '入庫補貨',
      timestamp: Date.now()
    };

    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      window.alert(`✅ 補貨成功：${targetItem.name} 庫存已增加。`);
    }

    // 重設輸入
    setSelectedItemId(''); setInputQty('1'); setInputPerson(''); setInputReason('');
  };

  const [newForm, setNewForm] = useState({
    name: '', category: Category.PROTECTION, itemType: 'CONSUMABLE' as ItemType,
    itemGroup: 'INVENTORY' as ItemGroup, unit: '個', spec: '', minStock: 5, quantity: 0,
    purchaseDate: '', expiryDate: ''
  });

  const handleAddItem = () => {
    if (!newForm.name.trim()) return window.alert('請輸入名稱');
    const newItem: InventoryItem = {
      id: generateId(),
      name: newForm.name.trim(),
      category: newForm.category,
      itemType: newForm.itemType,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: newForm.unit || '個',
      spec: newForm.spec || '',
      quantity: Number(newForm.quantity) || 0,
      minStock: Number(newForm.minStock) || 0,
      purchaseDate: newForm.purchaseDate,
      expiryDate: newForm.expiryDate,
      description: '',
      lastUpdated: Date.now()
    };
    setItems(prev => [...prev, newItem]);
    setShowAddModal(false);
    setNewForm({ name: '', category: Category.PROTECTION, itemType: 'CONSUMABLE', itemGroup: 'INVENTORY', unit: '個', spec: '', minStock: 5, quantity: 0, purchaseDate: '', expiryDate: '' });
  };

