               <p className="text-slate-400 font-bold text-sm uppercase">庫存不足</p>
               <h3 className="text-5xl font-black text-orange-600 mt-2">{items.filter(i=>i.quantity <= i.minStock).length}</h3>
            </div>
            <div className="bg-white p-8 rounded-3xl shadow-sm border-l-8 border-l-red-500">
               <p className="text-slate-400 font-bold text-sm uppercase">藥材已過期</p>
               <h3 className="text-5xl font-black text-red-600 mt-2">{expiredMedicineCount}</h3>
            </div>
            <div className="bg-slate-900 p-8 rounded-3xl shadow-xl flex flex-col justify-center">
               <button onClick={async () => { setIsAiLoading(true); setAiInsights(await getInventoryInsights(items)); setIsAiLoading(false); }} className="w-full py-4 bg-blue-600 text-white rounded-xl font-black flex items-center justify-center gap-2 hover:bg-blue-500">
                 <BrainCircuit size={18}/> {isAiLoading ? '分析中...' : '生成營運報告'}
               </button>
            </div>
            {aiInsights && <div className="lg:col-span-4 bg-blue-50 p-8 rounded-3xl border border-blue-100 text-blue-900 font-bold whitespace-pre-wrap leading-relaxed">{aiInsights}</div>}
          </div>
        )}

        {/* 新增/編輯 Modal (強制文字顏色修復) */}
        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-lg p-10 shadow-2xl">
              <div className="flex justify-between items-center mb-8">
                <h3 className="modal-title text-2xl">{(editTarget ? '編輯資料' : '新增管理項目')}</h3>
                <button onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="p-2 bg-slate-100 rounded-full text-slate-900"><X size={20}/></button>
              </div>
              <form className="space-y-4" onSubmit={(e) => {
                e.preventDefault();
                const formData = new FormData(e.currentTarget);
                const data = Object.fromEntries(formData.entries()) as any;
                if (editTarget) {
                  setItems(prev => prev.map(i => i.id === editTarget.id ? { ...editTarget, ...data, quantity: Number(data.quantity), minStock: Number(data.minStock) } : i));
                  setEditTarget(null);
                } else {
                  handleAddItem(data);
                }
              }}>
                <div>
                  <label className="block text-xs uppercase mb-1">名稱</label>
                  <input name="name" type="text" required className="w-full p-4 border-2 rounded-xl font-bold" defaultValue={editTarget?.name} />
                </div>
                <div>
                  <label className="block text-xs uppercase mb-1">單據類別</label>
                  <select name="itemType" className="w-full p-4 border-2 rounded-xl font-bold" defaultValue={editTarget?.itemType || 'CONSUMABLE'}>
                    <option value="EQUIPMENT">安全衛生設備</option>
                    <option value="CONSUMABLE">安全衛生類消耗品</option>
                  </select>
                </div>
                {((editTarget?.itemGroup === 'MEDICINE') || (activeTab === 'medicine' && !editTarget)) && (
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-xs uppercase mb-1">購入日期</label>
                      <input name="purchaseDate" type="date" className="w-full p-4 border-2 rounded-xl font-bold" defaultValue={editTarget?.purchaseDate} />
                    </div>
                    <div>
                      <label className="block text-xs uppercase mb-1 text-red-600">有效期限</label>
                      <input name="expiryDate" type="date" className="w-full p-4 border-2 rounded-xl font-bold" defaultValue={editTarget?.expiryDate} />
                    </div>
                  </div>
                )}
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs uppercase mb-1">單位</label>
                    <input name="unit" type="text" className="w-full p-4 border-2 rounded-xl font-bold" defaultValue={editTarget?.unit || '個'} />
                  </div>
                  <div>
                    <label className="block text-xs uppercase mb-1">警戒庫存</label>
                    <input name="minStock" type="number" className="w-full p-4 border-2 rounded-xl font-bold" defaultValue={editTarget?.minStock || 5} />
                  </div>
                </div>
                {!editTarget && (
                   <div>
                    <label className="block text-xs uppercase mb-1">初始庫存</label>
                    <input name="quantity" type="number" className="w-full p-4 border-2 rounded-xl font-bold" defaultValue={0} />
                   </div>
                )}
                <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl mt-4">儲存設定</button>
              </form>
            </div>
          </div>
        )}

        {/* 刪除 Modal */}
        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
            <div className="bg-white rounded-3xl w-full max-w-[320px] p-8 shadow-2xl text-center">
              <div className="w-16 h-16 bg-red-50 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4">
                <AlertTriangle size={32} />
              </div>
              <h3 className="text-xl font-black mb-2 text-slate-900">確認刪除項目？</h3>
              <p className="text-slate-500 text-sm font-bold mb-8">「{deleteTarget.name}」將無法復原。</p>
              <div className="space-y-2">
                <button onClick={confirmDelete} className="w-full py-3 bg-red-600 text-white rounded-xl font-black">確定刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="w-full py-3 bg-slate-100 text-slate-400 rounded-xl font-bold">先不要</button>
              </div>
            </div>
          </div>
        )}

        {/* 列印 Modal (強化黑字對比) */}
        {showPrintModal && lastTransaction && (
          <div className="fixed inset-0 bg-slate-900/95 z-[100] flex flex-col items-center justify-start p-10 overflow-y-auto">
            <div className="bg-white rounded-[2.5rem] w-full max-w-5xl p-10 relative shadow-2xl my-4">
              <div className="flex justify-between items-center mb-8 no-print border-b pb-6">
                 <div className="flex items-center gap-3"><Printer className="text-blue-600" size={32}/><span className="font-black text-2xl text-slate-900">領用單據正式預覽</span></div>
                 <div className="flex gap-4">
                    <button onClick={()=>window.print()} className="bg-blue-600 text-white px-10 py-4 rounded-xl font-black text-xl shadow-xl">執行列印</button>
                    <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full text-slate-900"><X size={24}/></button>
                 </div>
              </div>
              <div className="flex justify-center bg-white border p-4 overflow-hidden shadow-inner"><PrintableForm transaction={lastTransaction} /></div>
            </div>
          </div>
        )}
      </main>

      <div className="hidden print:block absolute top-0 left-0 w-full">{lastTransaction && <PrintableForm transaction={lastTransaction} />}</div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  Users
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v16_final_items';
const STORAGE_KEY_LOGS = 'safeman_v16_final_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const confirmDelete = () => {
    if (!deleteTarget) return;
    setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  /**
   * 【核心功能】強化庫存攔截邏輯
   */
  const handleTransaction = () => {
    if (!selectedItemId) { window.alert('⚠️ 錯誤：請先選取項目！'); return; }

    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    // 嚴格轉換數值
    const reqQty = parseInt(inputQty);
    const availableQty = Number(targetItem.quantity);

    if (isNaN(reqQty) || reqQty <= 0) {
      window.alert('⚠️ 請輸入有效的數字量。');
      return;
    }

    // 【領用攔截】
    if (issuanceMode === 'OUT') {
      if (reqQty > availableQty) {
        window.alert(
          `❌ 警告：庫存量不足！操作已終止。\n\n` +
          `項目：${targetItem.name}\n` +
          `目前現存：${availableQty} ${targetItem.unit}\n` +
          `欲領數量：${reqQty} ${targetItem.unit}\n\n` +
          `請檢查數量或先進行補貨入庫。`
        );
        return; // 強制阻斷
      }
    }

    // 通過檢查，執行更新
    setItems(prev => prev.map(item => 
      item.id === selectedItemId 
        ? { ...item, quantity: issuanceMode === 'IN' ? Number(item.quantity) + reqQty : Number(item.quantity) - reqQty, lastUpdated: Date.now() } 
        : item
    ));

    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: reqQty,
      person: issuanceMode === 'OUT' ? (inputPerson || '未填寫') : '管理員補貨',
      dept: issuanceMode === 'OUT' ? selectedDept : '庫房管理',
      reason: issuanceMode === 'OUT' ? (inputReason || '領用') : '入庫作業',
      timestamp: Date.now()
    };

    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      window.alert(`✅ 補貨成功！${targetItem.name} 庫存已增加 ${reqQty} ${targetItem.unit}。`);
    }

    setSelectedItemId(''); setInputQty('1'); setInputPerson(''); setInputReason('');
  };

  const handleAddItem = (form: any) => {
    if (!form.name.trim()) return window.alert('請輸入名稱');
    const newItem: InventoryItem = {
      id: generateId(),
      name: form.name.trim(),
      category: form.category || Category.OTHER,
      itemType: form.itemType,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: form.unit || '個',
      spec: form.spec || '',
      quantity: Number(form.quantity) || 0,
      minStock: Number(form.minStock) || 0,
      purchaseDate: form.purchaseDate,
      expiryDate: form.expiryDate,
      description: '',
      lastUpdated: Date.now()
    };
    setItems(prev => [...prev, newItem]);
    setShowAddModal(false);
  };

  // 數據統計計算
  const stats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    const medItems = items.filter(i => i.itemGroup === 'MEDICINE');
    const todayStr = new Date().toISOString().split('T')[0];

    // 部門統計
    const deptUsage: Record<string, number> = {};
    logs.filter(l => l.type === 'OUT').forEach(l => {
      deptUsage[l.dept] = (deptUsage[l.dept] || 0) + 1;
    });

    return {
      invTotal: invItems.length,
      invLow: invItems.filter(i => i.quantity <= i.minStock).length,
      medTotal: medItems.length,
      medLow: medItems.filter(i => i.quantity <= i.minStock).length,
      medExpired: medItems.filter(i => i.expiryDate && i.expiryDate < todayStr).length,
      deptStats: Object.entries(deptUsage).sort((a,b) => b[1] - a[1])
    };
  }, [items, logs]);

  // 【領用單報表】右上角灰階，其餘黑
  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const date = new Date(transaction.timestamp);
    const emptyRows = Array(15).fill(null);

    return (
      <div className="print-area bg-white text-black p-6 w-[210mm] mx-auto relative overflow-hidden" id="official-form-v16">
        <style>{`
          @font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); }
          #official-form-v16 { font-family: 'StandardKai', serif; font-size: 14pt; color: #000000 !important; }
          #official-form-v16 table { border-collapse: collapse; width: 100%; border: 2.5px solid #000000; }
          #official-form-v16 th, #official-form-v16 td { border: 2px solid #000000; padding: 6px 10px; height: 38px; text-align: center; color: #000000 !important; }
          @media print { .no-print { display: none !important; } }
        `}</style>
        {/* 右上角灰階字體 */}
        <div className="absolute top-4 right-8 text-[10pt] font-bold text-right" style={{color: '#94a3b8'}}>
           <div>領用編號：{transaction.id}</div>
           <div>領用人員：{transaction.person}</div>
        </div>
        <h1 className="text-center text-3xl font-bold mb-8 pt-10 tracking-[0.2em]" style={{color: '#000000'}}>台灣電力公司電力修護處南部分處</h1>
        <div className="flex justify-center gap-12 mb-8 font-bold text-xl" style={{color: '#000000'}}>
          <label className="flex items-center gap-2">
            <span className="w-6 h-6 border-2 border-black flex items-center justify-center font-black">{targetItem?.itemType === 'EQUIPMENT' ? 'V' : ''}</span> 安全衛生設備
          </label>
          <label className="flex items-center gap-2">
            <span className="w-6 h-6 border-2 border-black flex items-center justify-center font-black">{targetItem?.itemType === 'CONSUMABLE' ? 'V' : ''}</span> 安全衛生類消耗品
          </label>
        </div>
        <div className="flex justify-between mb-3 font-bold px-2" style={{color: '#000000'}}>
          <div>領用單位：<span className="inline-block border-b-2 border-dotted border-black min-w-[220px] text-center">{transaction.dept}</span></div>
          <div>中華民國 {date.getFullYear() - 1911} 年 {date.getMonth() + 1} 月 {date.getDate()} 日</div>
        </div>
        <table>
          <thead>
            <tr className="bg-slate-50 font-bold">
              <th className="w-[35%]">名　　　　　稱</th><th className="w-[25%]">規　範（序　號）</th>
              <th className="w-[10%]">單位</th><th className="w-[10%]">數量</th><th className="w-[20%]">備　　　　　註</th>
            </tr>
          </thead>
          <tbody>
            <tr className="font-bold">
              <td className="text-left">{transaction.itemName}</td>
              <td className="text-sm font-normal">{targetItem?.spec || ''}</td>
              <td>{targetItem?.unit || '個'}</td>
              <td className="text-2xl">{transaction.quantity}</td>
              <td className="text-left text-xs font-normal">{transaction.reason}</td>
            </tr>
            {emptyRows.map((_, idx) => <tr key={idx}><td /><td /><td /><td /><td /></tr>)}
          </tbody>
        </table>
        <div className="mt-14 font-bold grid grid-cols-2 gap-x-12" style={{color: '#000000'}}>
          <div className="flex flex-col gap-10"><div>申請部門：</div><div className="flex justify-between w-full px-2 text-sm"><div>經辦：</div><div>課長：</div><div>經理：</div></div></div>
          <div className="flex flex-col gap-10"><div>經管部門：</div><div className="flex justify-between w-full px-2 text-sm"><div>經辦：</div><div>課長：</div><div>經理：</div></div></div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-slate-100 text-slate-900 font-sans">
      <style>{`
        input, select, textarea {
          color: #000000 !important;
          background-color: #ffffff !important;
          border: 2px solid #cbd5e1 !important;
        }
        input[type="date"] {
          color-scheme: light;
          font-weight: bold;
        }
        input[type="date"]::-webkit-calendar-picker-indicator {
          filter: invert(0%) brightness(30%);
          cursor: pointer;
        }
        label { color: #334155 !important; font-weight: 800 !important; }
        .modal-title { color: #000000 !important; font-weight: 900 !important; }
      `}</style>

      {/* 側邊導覽 */}
      <aside className="no-print w-72 bg-slate-900 text-white p-8 flex flex-col shrink-0">
        <div className="flex items-center gap-3 mb-12">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg"><Package size={22}/></div>
          <div><h1 className="font-black text-lg leading-tight">工安管理系統</h1><p className="text-[10px] text-slate-500 font-bold tracking-widest">V16 ULTIMATE</p></div>
        </div>
        <nav className="flex-1 space-y-2">
          {[
            { id: 'inventory', label: '工安耗材管理', icon: Package },
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
            { id: 'issuance', label: '領用補貨作業', icon: FileText },
            { id: 'history', label: '歷史異動日誌', icon: History },
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard },
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-xl' : 'text-slate-400 hover:bg-slate-800'}`}>
              <tab.icon size={20} /> {tab.label}
            </button>
          ))}
        </nav>
      </aside>

      <main className="no-print flex-1 p-10 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-3xl font-black text-slate-900">
            {activeTab === 'inventory' ? '工安耗材清冊' : 
             activeTab === 'medicine' ? '急救藥材清冊' : 
             activeTab === 'issuance' ? '領用/補貨登記' : 
             activeTab === 'history' ? '歷史異動日誌' : '數據統計看板'}
          </h2>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-3 shadow-lg">
              <Plus size={18}/> 新增管理項目
            </button>
          )}
        </header>

        {/* 庫存列表 */}
        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
            <div className="p-6 bg-slate-50 border-b">
               <div className="relative max-w-md w-full">
                 <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                 <input type="text" placeholder="關鍵字快速搜尋..." className="w-full pl-12 pr-4 py-3 rounded-xl font-bold" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
               </div>
            </div>
            <table className="w-full text-left">
              <thead>
                <tr className="text-[11px] font-black text-slate-400 uppercase tracking-widest border-b">
                  <th className="px-8 py-4">名稱與分類</th><th className="px-8 py-4 text-center">數量</th><th className="px-8 py-4 text-right">管理</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(i => (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-8 py-5">
                      <div className="font-bold text-slate-900">{item.name}</div>
                      <div className="text-xs text-slate-400 font-medium">
                        {item.itemType === 'EQUIPMENT' ? '安全衛生設備' : '安全衛生類消耗品'} / {item.spec || '無規格'}
                        {item.expiryDate && <span className={`ml-2 px-1.5 py-0.5 rounded font-black ${new Date(item.expiryDate) < new Date() ? 'bg-red-100 text-red-600' : 'bg-slate-100 text-slate-500'}`}>效期: {item.expiryDate}</span>}
                      </div>
                    </td>
                    <td className="px-8 py-5 text-center font-black">
                      <span className={`px-4 py-1.5 rounded-lg ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>{item.quantity} {item.unit}</span>
                    </td>
                    <td className="px-8 py-5 text-right flex items-center justify-end gap-1">
                      <button onClick={() => setEditTarget(item)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg"><Edit3 size={16}/></button>
