               <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase border-b">
                 <tr><th className="px-8 py-5">異動時間</th><th className="px-8 py-5">種類</th><th className="px-8 py-5">項目名稱</th><th className="px-8 py-5">單位/經辦</th><th className="px-8 py-5 text-right">單據</th></tr>
               </thead>
               <tbody className="divide-y divide-slate-100">
                 {logs.map(log => (
