                      <div className="flex-1 h-4 bg-slate-100 rounded-full overflow-hidden">
                        <div className="h-full bg-blue-500" style={{ width: `${(count / stats.deptStats[0][1]) * 100}%` }}></div>
                      </div>
                      <div className="w-10 text-right font-black text-blue-600">{count}</div>
                    </div>
                  )) : <p className="text-slate-400 italic">尚無領用數據</p>}
                </div>
              </div>
            </div>

            <div className="bg-slate-900 p-10 rounded-[2rem] shadow-2xl flex flex-col md:flex-row items-center gap-6">
               <div className="flex-1">
                 <h4 className="text-white text-xl font-black mb-2">AI 工安顧問系統</h4>
                 <p className="text-slate-400 text-sm font-bold">根據目前庫存情況生成管理建議與採購提醒。</p>
               </div>
               <button onClick={async () => { setIsAiLoading(true); setAiInsights(await getInventoryInsights(items)); setIsAiLoading(false); }} className="px-8 py-4 bg-blue-600 text-white rounded-xl font-black flex items-center gap-2 hover:bg-blue-500 transition-all shadow-lg">
                 <BrainCircuit size={20}/> {isAiLoading ? '分析數據中...' : '生成營運建議'}
               </button>
            </div>
            {aiInsights && <div className="bg-blue-50 p-8 rounded-3xl border-2 border-blue-100 text-blue-900 font-bold whitespace-pre-wrap leading-relaxed shadow-sm">{aiInsights}</div>}
          </div>
        )}

        {/* 新增/編輯 Modal (修復編輯數量異常) */}
        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-lg p-10 shadow-2xl">
              <div className="flex justify-between items-center mb-8">
                <h3 className="modal-title text-2xl">{(editTarget ? '編輯項目資料' : '新增管理項目')}</h3>
                <button onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="p-2 bg-slate-100 rounded-full text-slate-900"><X size={20}/></button>
              </div>
              <form className="space-y-4" onSubmit={(e) => {
                e.preventDefault();
                const formData = new FormData(e.currentTarget);
                const data = Object.fromEntries(formData.entries()) as any;
                const finalQty = Number(data.quantity);
                const finalMin = Number(data.minStock);

                if (editTarget) {
                  setItems(prev => prev.map(i => i.id === editTarget.id ? { 
                    ...editTarget, 
                    name: data.name, 
                    itemType: data.itemType as ItemType,
                    unit: data.unit,
                    spec: data.spec,
                    purchaseDate: data.purchaseDate,
                    expiryDate: data.expiryDate,
                    quantity: isNaN(finalQty) ? editTarget.quantity : finalQty, 
                    minStock: isNaN(finalMin) ? editTarget.minStock : finalMin 
                  } : i));
                  setEditTarget(null);
                } else {
                  handleAddItem(data);
                }
              }}>
                <div><label className="block text-xs uppercase mb-1">名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.name} /></div>
                <div>
                  <label className="block text-xs uppercase mb-1">單據類別</label>
                  <select name="itemType" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.itemType || 'CONSUMABLE'}>
                    <option value="EQUIPMENT">安全衛生設備</option>
                    <option value="CONSUMABLE">安全衛生類消耗品</option>
                  </select>
                </div>
                {((editTarget?.itemGroup === 'MEDICINE') || (activeTab === 'medicine' && !editTarget)) && (
                  <div className="grid grid-cols-2 gap-4">
                    <div><label className="block text-xs uppercase mb-1">購入日期</label><input name="purchaseDate" type="date" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.purchaseDate} /></div>
                    <div><label className="block text-xs uppercase mb-1 text-red-600">有效期限</label><input name="expiryDate" type="date" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.expiryDate} /></div>
                  </div>
                )}
                <div className="grid grid-cols-2 gap-4">
                  <div><label className="block text-xs uppercase mb-1">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.unit || '個'} /></div>
                  <div><label className="block text-xs uppercase mb-1">警戒庫存</label><input name="minStock" type="number" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.minStock || 5} /></div>
                </div>
                <div><label className="block text-xs uppercase mb-1">現有庫存</label><input name="quantity" type="number" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.quantity || 0} /></div>
                <div><label className="block text-xs uppercase mb-1">規範/序號</label><input name="spec" type="text" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.spec || ''} /></div>
                <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl mt-4 active:scale-95">儲存並應用設定</button>
              </form>
            </div>
          </div>
        )}

        {/* 刪除 Modal */}
        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
            <div className="bg-white rounded-3xl w-full max-w-[320px] p-8 shadow-2xl text-center">
              <div className="w-16 h-16 bg-red-50 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4"><AlertTriangle size={32} /></div>
              <h3 className="text-xl font-black mb-2 text-slate-900">確認刪除？</h3>
              <p className="text-slate-500 text-sm font-bold mb-8">「{deleteTarget.name}」將無法復原。</p>
              <div className="space-y-2">
                <button onClick={confirmDelete} className="w-full py-3 bg-red-600 text-white rounded-xl font-black">確定刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="w-full py-3 bg-slate-100 text-slate-400 rounded-xl font-bold">先不要</button>
              </div>
            </div>
          </div>
        )}

        {/* 列印 Modal */}
        {showPrintModal && lastTransaction && (
          <div className="fixed inset-0 bg-slate-900/95 z-[100] flex flex-col items-center justify-start p-10 overflow-y-auto">
            <div className="bg-white rounded-[2.5rem] w-full max-w-5xl p-10 relative shadow-2xl my-4">
              <div className="flex justify-between items-center mb-8 no-print border-b pb-6">
                 <div className="flex items-center gap-3"><Printer className="text-blue-600" size={32}/><span className="font-black text-2xl text-slate-900">領用單正式預覽 (V16)</span></div>
                 <div className="flex gap-4">
                    <button onClick={()=>window.print()} className="bg-blue-600 text-white px-10 py-4 rounded-xl font-black text-xl shadow-xl">執行列印</button>
                    <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full text-slate-900"><X size={24}/></button>
                 </div>
              </div>
              <div className="flex justify-center bg-white border p-4 overflow-hidden shadow-inner"><PrintableForm transaction={lastTransaction} /></div>
            </div>
          </div>
        )}
      </main>

      <div className="hidden print:block absolute top-0 left-0 w-full">{lastTransaction && <PrintableForm transaction={lastTransaction} />}</div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  Users
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

// 使用 V17 專屬 Key 確保環境純淨，不與舊版衝突
const STORAGE_KEY_ITEMS = 'safeman_v17_stable_items';
const STORAGE_KEY_LOGS = 'safeman_v17_stable_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);

  // 初始化載入
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  // 自動存檔
  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const confirmDelete = () => {
    if (!deleteTarget) return;
    setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  /**
   * 【核心修復 5】強化庫存攔截：絕對不允許領取超過現有量的數量
   */
  const handleTransaction = () => {
    if (!selectedItemId) {
      window.alert('⚠️ 錯誤：請先選取管理項目！');
      return;
    }

    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    // 強制轉換為純數字
    const reqQty = parseInt(inputQty, 10);
    const availableQty = Number(targetItem.quantity);

    if (isNaN(reqQty) || reqQty <= 0) {
      window.alert('⚠️ 請輸入正確的領用/補貨數量。');
      return;
    }

    // 領用模式下的絕對攔截
    if (issuanceMode === 'OUT') {
      if (reqQty > availableQty) {
        window.alert(
          `❌ 庫存不足警報！領用失敗。\n\n` +
          `項目：${targetItem.name}\n` +
          `現有庫存：${availableQty} ${targetItem.unit}\n` +
          `欲領數量：${reqQty} ${targetItem.unit}\n\n` +
          `請調整數量或先執行補貨入庫。`
        );
        return; // 強制阻斷執行，絕不進行後續更新
      }
    }

    // 通過檢查，執行更新
    const updatedItems = items.map(item => 
      item.id === selectedItemId 
        ? { ...item, quantity: issuanceMode === 'IN' ? Number(item.quantity) + reqQty : Number(item.quantity) - reqQty, lastUpdated: Date.now() } 
        : item
    );

    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: reqQty,
      person: issuanceMode === 'OUT' ? (inputPerson || '未填寫') : '庫房管理員',
      dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
      reason: issuanceMode === 'OUT' ? (inputReason || '例行領用') : '進貨補倉',
      timestamp: Date.now()
    };

    setItems(updatedItems);
    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      window.alert(`✅ 補貨成功：${targetItem.name} 庫存已增加至 ${availableQty + reqQty} ${targetItem.unit}。`);
    }

    setSelectedItemId(''); setInputQty('1'); setInputPerson(''); setInputReason('');
  };

  /**
   * 【核心修復 1】修復新增/編輯時的數據異常
   */
  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = {
      name: formData.get('name') as string,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
    };

    if (!data.name.trim()) return window.alert('名稱不可為空');

    if (editTarget) {
