                    <option value="EQUIPMENT">安全衛生設備 (領用單左側)</option>
                    <option value="CONSUMABLE">安全衛生類消耗品 (領用單右側)</option>
                  </select>
                </div>
                {((editTarget?.itemGroup === 'MEDICINE') || (activeTab === 'medicine' && !editTarget)) && (
                  <div className="grid grid-cols-2 gap-4">
                    <div><label className="block text-xs uppercase mb-1">購入日期</label><input name="purchaseDate" type="date" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.purchaseDate} /></div>
                    <div><label className="block text-xs uppercase mb-1 text-red-600 font-black">藥材有效期限</label><input name="expiryDate" type="date" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.expiryDate} /></div>
                  </div>
                )}
                <div className="grid grid-cols-2 gap-4">
                  <div><label className="block text-xs uppercase mb-1">庫存單位 (如:個/盒)</label><input name="unit" type="text" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.unit || '個'} /></div>
                  <div><label className="block text-xs uppercase mb-1">警戒庫存量</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.minStock || 5} /></div>
                </div>
                <div><label className="block text-xs uppercase mb-1">現有庫存數量 (修正：編輯時可修改)</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.quantity || 0} /></div>
                <div><label className="block text-xs uppercase mb-1">規格/序號 (會印在領用單)</label><input name="spec" type="text" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.spec || ''} /></div>
                <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl mt-4 hover:bg-blue-700 active:scale-95 transition-all">
                  儲存並立即更新清冊
                </button>
              </form>
            </div>
          </div>
        )}

        {/* Modal: 刪除確認 */}
        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2rem] w-full max-w-[320px] p-8 shadow-2xl text-center">
              <div className="w-16 h-16 bg-red-50 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4"><AlertTriangle size={32} /></div>
              <h3 className="text-xl font-black mb-2 text-slate-900">確認永久刪除？</h3>
              <p className="text-slate-500 text-sm font-bold mb-8">項目「{deleteTarget.name}」將會從資料庫移除。</p>
              <div className="space-y-2">
                <button onClick={confirmDelete} className="w-full py-3 bg-red-600 text-white rounded-xl font-black hover:bg-red-700">確認刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="w-full py-3 bg-slate-100 text-slate-400 rounded-xl font-bold">取消操作</button>
              </div>
            </div>
          </div>
        )}

        {/* Modal: 列印領用單 */}
        {showPrintModal && lastTransaction && (
          <div className="fixed inset-0 bg-slate-900/95 z-[100] flex flex-col items-center justify-start p-10 overflow-y-auto">
            <div className="bg-white rounded-[2.5rem] w-full max-w-5xl p-10 relative shadow-2xl my-4">
              <div className="flex justify-between items-center mb-8 no-print border-b pb-6">
                 <div className="flex items-center gap-3"><Printer className="text-blue-600" size={32}/><span className="font-black text-2xl text-slate-900">台電領用單 (V17 正式格式)</span></div>
                 <div className="flex gap-4">
                    <button onClick={()=>window.print()} className="bg-blue-600 text-white px-10 py-4 rounded-xl font-black text-xl shadow-xl hover:bg-blue-700">啟動列印裝置</button>
                    <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full text-slate-900 hover:bg-slate-200 transition-colors"><X size={24}/></button>
                 </div>
              </div>
              <div className="flex justify-center bg-white border p-4 overflow-hidden shadow-inner"><PrintableForm transaction={lastTransaction} /></div>
            </div>
          </div>
        )}
      </main>

      {/* 隱藏列印區域 */}
      <div className="hidden print:block absolute top-0 left-0 w-full">{lastTransaction && <PrintableForm transaction={lastTransaction} />}</div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  Users
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

// 使用 V18 專屬 Key
const STORAGE_KEY_ITEMS = 'safeman_v18_strict_items';
const STORAGE_KEY_LOGS = 'safeman_v18_strict_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);

  // 初始化載入
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  // 自動存檔
  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const confirmDelete = () => {
    if (!deleteTarget) return;
    setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  /**
   * 【核心修正 4】強化庫存攔截：修正邏輯確保必跳警告
   */
  const handleTransaction = () => {
    if (!selectedItemId) {
      window.alert('⚠️ 錯誤：請先選取項目！');
      return;
    }

    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    // 強制轉換為純數字比對
    const currentStock = Number(targetItem.quantity);
    const orderQty = Number(inputQty);

    if (isNaN(orderQty) || orderQty <= 0) {
      window.alert('⚠️ 請輸入有效的數量。');
      return;
    }

    // 領用模式下的絕對攔截：最優先執行
    if (issuanceMode === 'OUT') {
      if (orderQty > currentStock) {
        window.alert(
          `❌ 庫存量不足！領用失敗。\n\n` +
          `項目：${targetItem.name}\n` +
          `現有庫存：${currentStock} ${targetItem.unit}\n` +
          `欲領數量：${orderQty} ${targetItem.unit}\n\n` +
          `請調整數量或先補貨。`
        );
        return; // 強制中斷，絕對不執行後續程式碼
      }
    }

    // 通過比對後才執行更新
    const updatedItems = items.map(item => 
      item.id === selectedItemId 
        ? { ...item, quantity: issuanceMode === 'IN' ? Number(item.quantity) + orderQty : Number(item.quantity) - orderQty, lastUpdated: Date.now() } 
        : item
    );

    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: orderQty,
      person: issuanceMode === 'OUT' ? (inputPerson || '未填寫') : '管理員',
      dept: issuanceMode === 'OUT' ? selectedDept : '庫房',
      reason: issuanceMode === 'OUT' ? inputReason : '進貨', // 若沒填寫則為空字串
      timestamp: Date.now()
    };

    setItems(updatedItems);
    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      window.alert(`✅ 補貨成功：${targetItem.name} 庫存已更新。`);
    }

    setSelectedItemId(''); setInputQty('1'); setInputPerson(''); setInputReason('');
  };

  /**
   * 【核心修正 1】編輯時數量處理
   */
  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = {
      name: formData.get('name') as string,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
    };

    if (!data.name.trim()) return window.alert('名稱不可為空');

    if (editTarget) {
      setItems(prev => prev.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i));
      setEditTarget(null);
    } else {
      const newItem: InventoryItem = {
        id: generateId(),
        ...data,
        itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
        category: Category.OTHER,
        description: '',
        lastUpdated: Date.now()
      };
      setItems(prev => [...prev, newItem]);
      setShowAddModal(false);
    }
  };

  const dashboardStats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    const medItems = items.filter(i => i.itemGroup === 'MEDICINE');
    const today = new Date().toISOString().split('T')[0];
    const deptMap: Record<string, number> = {};
    logs.filter(l => l.type === 'OUT').forEach(l => {
      deptMap[l.dept] = (deptMap[l.dept] || 0) + 1;
    });
    return {
      inv: { total: invItems.length, low: invItems.filter(i => i.quantity <= i.minStock).length },
      med: { total: medItems.length, low: medItems.filter(i => i.quantity <= i.minStock).length, expired: medItems.filter(i => i.expiryDate && i.expiryDate < today).length },
      depts: Object.entries(deptMap).sort((a, b) => b[1] - a[1])
    };
  }, [items, logs]);

  // 【修復 2】領用單備註邏輯
  const PrintableForm = ({ transaction }: { transaction: Transaction }) => {
    const targetItem = items.find(i => i.id === transaction.itemId);
    const date = new Date(transaction.timestamp);
    const emptyRows = Array(15).fill(null);

    return (
      <div className="print-area bg-white text-black p-6 w-[210mm] mx-auto relative overflow-hidden" id="official-form-v18">
        <style>{`
          @font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); }
          #official-form-v18 { font-family: 'StandardKai', serif; font-size: 14pt; color: #000000 !important; }
          #official-form-v18 table { border-collapse: collapse; width: 100%; border: 2.5px solid #000000; }
          #official-form-v18 th, #official-form-v18 td { border: 2px solid #000000; padding: 6px 10px; height: 38px; text-align: center; color: #000000 !important; }
          @media print { .no-print { display: none !important; } body { background: white; } }
        `}</style>
        <div className="absolute top-4 right-8 text-[10pt] font-bold text-right text-slate-400">
           <div>領用編號：{transaction.id}</div>
           <div>領用人員：{transaction.person}</div>
        </div>
        <h1 className="text-center text-3xl font-bold mb-8 pt-10 tracking-[0.2em]" style={{color: '#000000'}}>台灣電力公司電力修護處南部分處</h1>
        <div className="flex justify-center gap-12 mb-8 font-bold text-xl" style={{color: '#000000'}}>
          <label className="flex items-center gap-2">
            <span className="w-6 h-6 border-2 border-black flex items-center justify-center font-black">{targetItem?.itemType === 'EQUIPMENT' ? 'V' : ''}</span> 安全衛生設備
          </label>
          <label className="flex items-center gap-2">
            <span className="w-6 h-6 border-2 border-black flex items-center justify-center font-black">{targetItem?.itemType === 'CONSUMABLE' ? 'V' : ''}</span> 安全衛生類消耗品
          </label>
        </div>
        <div className="flex justify-between mb-3 font-bold px-2" style={{color: '#000000'}}>
          <div>領用單位：<span className="inline-block border-b-2 border-dotted border-black min-w-[220px] text-center">{transaction.dept}</span></div>
          <div>中華民國 {date.getFullYear() - 1911} 年 {date.getMonth() + 1} 月 {date.getDate()} 日</div>
        </div>
        <table>
          <thead>
            <tr className="bg-slate-50 font-bold">
              <th className="w-[35%]">名　　　　　稱</th><th className="w-[25%]">規　範（序　號）</th>
              <th className="w-[10%]">單位</th><th className="w-[10%]">數量</th><th className="w-[20%]">備　　　　　註</th>
            </tr>
          </thead>
          <tbody>
            <tr className="font-bold">
              <td className="text-left">{transaction.itemName}</td>
              <td className="text-sm font-normal">{targetItem?.spec || ''}</td>
              <td>{targetItem?.unit || '個'}</td>
              <td className="text-2xl">{transaction.quantity}</td>
              {/* 【修正 2】備註內容處理：若無內容則不顯示 */}
              <td className="text-left text-xs font-normal">{transaction.reason || ''}</td>
            </tr>
            {emptyRows.map((_, idx) => <tr key={idx}><td /><td /><td /><td /><td /></tr>)}
          </tbody>
        </table>
        <div className="mt-14 font-bold grid grid-cols-2 gap-x-12" style={{color: '#000000'}}>
          <div className="flex flex-col gap-10"><div>申請部門：</div><div className="flex justify-between w-full px-2 text-sm"><div>經辦：</div><div>課長：</div><div>經理：</div></div></div>
          <div className="flex flex-col gap-10"><div>經管部門：</div><div className="flex justify-between w-full px-2 text-sm"><div>經辦：</div><div>課長：</div><div>經理：</div></div></div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-slate-100 text-slate-900 font-sans">
      <style>{`
        input, select, textarea { color: #000000 !important; background-color: #ffffff !important; border: 2px solid #94a3b8 !important; }
        input[type="date"] { color-scheme: light !important; font-weight: 700 !important; }
        input[type="date"]::-webkit-calendar-picker-indicator { filter: brightness(0); cursor: pointer; }
        label { color: #1e293b !important; font-weight: 900 !important; }
        .modal-title { color: #000000 !important; font-weight: 900 !important; }
      `}</style>

      {/* 側邊導覽 */}
      <aside className="no-print w-72 bg-slate-900 text-white p-8 flex flex-col shrink-0">
        <div className="flex items-center gap-3 mb-12">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg"><Package size={22}/></div>
          <div><h1 className="font-black text-lg leading-tight">工安管理系統</h1><p className="text-[10px] text-slate-500 font-bold tracking-widest uppercase">V18 Strict</p></div>
        </div>
        <nav className="flex-1 space-y-2">
          {[
            { id: 'inventory', label: '工安耗材管理', icon: Package },
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
            { id: 'issuance', label: '領用補貨作業', icon: FileText },
            { id: 'history', label: '歷史異動日誌', icon: History },
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard },
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-xl' : 'text-slate-400 hover:bg-slate-800'}`}>
              <tab.icon size={20} /> {tab.label}
            </button>
          ))}
        </nav>
      </aside>

      <main className="no-print flex-1 p-10 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-3xl font-black text-slate-900">
            {activeTab === 'inventory' ? '工安耗材清冊' : 
             activeTab === 'medicine' ? '急救藥材清冊' : 
             activeTab === 'issuance' ? '領用/補貨登記' : 
             activeTab === 'history' ? '歷史異動日誌' : '數據中心統計'}
