  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);

  // 初始化載入
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  // 自動存檔
  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const confirmDelete = () => {
    if (!deleteTarget) return;
    setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  /**
   * 【核心修正 1】極限制庫存攔截
   * 確保比對邏輯在任何更新發生前執行
   */
  const handleTransaction = () => {
    if (!selectedItemId) {
      window.alert('⚠️ 錯誤：請先選取管理項目！');
      return;
    }

    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    const stockAmount = Number(targetItem.quantity);
    const orderAmount = Number(inputQty);

    if (isNaN(orderAmount) || orderAmount <= 0) {
      window.alert('⚠️ 錯誤：請輸入有效的領用或補貨數量。');
      return;
    }

    // 領用出庫模式：嚴格檢查庫存是否充足
    if (issuanceMode === 'OUT') {
      if (orderAmount > stockAmount) {
        window.alert(
          `❌ 庫存不足，無法執行領用作業！\n\n` +
          `項目：${targetItem.name}\n` +
          `目前現有庫存：${stockAmount} ${targetItem.unit}\n` +
          `本次申請領用：${orderAmount} ${targetItem.unit}\n\n` +
          `差額為 ${orderAmount - stockAmount} ${targetItem.unit}。請調整領用數量或先進行採購補貨。`
        );
        return; // 此 return 確保絕不執行後續庫存更新
      }
    }

    // 通過驗證，開始更新資料
    const updatedItems = items.map(item => 
      item.id === selectedItemId 
        ? { ...item, quantity: issuanceMode === 'IN' ? Number(item.quantity) + orderAmount : Number(item.quantity) - orderAmount, lastUpdated: Date.now() } 
        : item
    );

    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: orderAmount,
      person: issuanceMode === 'OUT' ? (inputPerson || '未填寫') : '庫房管理員',
      dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
      reason: issuanceMode === 'OUT' ? inputReason : '進貨補庫',
      timestamp: Date.now()
    };

    setItems(updatedItems);
    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      window.alert(`✅ 資料已更新：${targetItem.name} 目前庫存增至 ${stockAmount + orderAmount} ${targetItem.unit}。`);
    }

    // 清空輸入欄位
    setSelectedItemId(''); setInputQty('1'); setInputPerson(''); setInputReason('');
  };

  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = {
      name: formData.get('name') as string,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
    };

    if (!data.name.trim()) return window.alert('名稱不可為空');

    if (editTarget) {
      setItems(prev => prev.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i));
      setEditTarget(null);
    } else {
      const newItem: InventoryItem = {
        id: generateId(),
        ...data,
        itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
        category: Category.OTHER,
        description: '',
        lastUpdated: Date.now()
      };
      setItems(prev => [...prev, newItem]);
      setShowAddModal(false);
    }
  };

  const dashboardStats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    const medItems = items.filter(i => i.itemGroup === 'MEDICINE');
    const today = new Date().toISOString().split('T')[0];
    const deptMap: Record<string, number> = {};
    logs.filter(l => l.type === 'OUT').forEach(l => {
      deptMap[l.dept] = (deptMap[l.dept] || 0) + 1;
    });
    return {
      inv: { total: invItems.length, low: invItems.filter(i => i.quantity <= i.minStock).length },
      med: { 
        total: medItems.length, 
        low: medItems.filter(i => i.quantity <= i.minStock).length, 
        expired: medItems.filter(i => i.expiryDate && i.expiryDate < today).length 
      },
      depts: deptMap
    };
  }, [items, logs]);

  const handleFetchAiInsights = async () => {
    setIsAiLoading(true);
    const result = await getInventoryInsights(items);
    setAiInsights(result);
    setIsAiLoading(false);
  };

  const filteredItems = items.filter(i => 
    (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') &&
    i.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredIssuanceItems = items.filter(i => i.itemGroup === issuanceGroup);

  return (
    <div className="flex h-screen bg-slate-50 font-sans text-slate-800">
      {/* Sidebar */}
      <nav className="w-64 bg-slate-900 text-white flex flex-col shadow-xl">
        <div className="p-6 border-b border-slate-700 flex items-center gap-3">
          <Package className="text-blue-400" size={28} />
          <h1 className="text-xl font-bold tracking-tight">SafeMan V20</h1>
        </div>
        <div className="flex-1 py-4 overflow-y-auto">
          {[
            { id: 'dashboard', icon: LayoutDashboard, label: '儀表板', color: 'text-blue-400' },
            { id: 'inventory', icon: Package, label: '工安耗材', color: 'text-emerald-400' },
            { id: 'medicine', icon: Stethoscope, label: '急救醫藥', color: 'text-rose-400' },
            { id: 'issuance', icon: FileText, label: '領用作業', color: 'text-amber-400' },
            { id: 'history', icon: History, label: '歷史紀錄', color: 'text-purple-400' },
          ].map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as any)}
              className={`w-full px-6 py-4 flex items-center gap-4 transition-all ${
                activeTab === item.id ? 'bg-slate-800 border-r-4 border-blue-500' : 'hover:bg-slate-800/50'
              }`}
            >
              <item.icon className={activeTab === item.id ? item.color : 'text-slate-400'} size={20} />
              <span className={`font-medium ${activeTab === item.id ? 'text-white' : 'text-slate-400'}`}>{item.label}</span>
            </button>
          ))}
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden">
        {/* Header */}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-8 shadow-sm">
          <h2 className="text-lg font-bold text-slate-700">
            {activeTab === 'dashboard' && '數據儀表板'}
            {activeTab === 'inventory' && '工安耗材管理'}
            {activeTab === 'medicine' && '急救醫藥管理'}
            {activeTab === 'issuance' && '庫存領用與補貨'}
            {activeTab === 'history' && '異動紀錄'}
          </h2>
          <div className="flex items-center gap-4">
            {(activeTab === 'inventory' || activeTab === 'medicine') && (
              <button 
                onClick={() => setShowAddModal(true)}
                className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-colors"
              >
                <Plus size={18} /> 新增項目
              </button>
            )}
          </div>
        </header>

        {/* Tab Content */}
        <div className="flex-1 overflow-y-auto p-8">
          {activeTab === 'dashboard' && (
            <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                  <div className="flex justify-between items-start">
                    <div>
                      <p className="text-slate-500 text-sm font-medium">總物資項目</p>
                      <h3 className="text-3xl font-bold mt-1">{items.length}</h3>
                    </div>
                    <div className="p-3 bg-blue-50 text-blue-600 rounded-xl"><Package size={24} /></div>
                  </div>
                </div>
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                  <div className="flex justify-between items-start">
                    <div>
                      <p className="text-slate-500 text-sm font-medium">庫存不足警示</p>
                      <h3 className="text-3xl font-bold mt-1 text-rose-600">{dashboardStats.inv.low + dashboardStats.med.low}</h3>
                    </div>
                    <div className="p-3 bg-rose-50 text-rose-600 rounded-xl"><AlertTriangle size={24} /></div>
                  </div>
                </div>
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                  <div className="flex justify-between items-start">
                    <div>
                      <p className="text-slate-500 text-sm font-medium">藥品過期警告</p>
                      <h3 className="text-3xl font-bold mt-1 text-amber-600">{dashboardStats.med.expired}</h3>
                    </div>
                    <div className="p-3 bg-amber-50 text-amber-600 rounded-xl"><Stethoscope size={24} /></div>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-100">
                  <div className="flex items-center justify-between mb-6">
                    <h3 className="text-lg font-bold flex items-center gap-2">
                      <BrainCircuit className="text-blue-500" /> AI 庫存分析建議
                    </h3>
                    <button 
                      onClick={handleFetchAiInsights}
                      disabled={isAiLoading}
                      className="text-sm font-medium text-blue-600 hover:text-blue-700 disabled:opacity-50"
                    >
                      {isAiLoading ? '分析中...' : '重新分析'}
                    </button>
                  </div>
                  <div className="prose prose-slate max-w-none">
                    {isAiLoading ? (
                      <div className="flex flex-col items-center py-12 text-slate-400">
                        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500 mb-4"></div>
                        正在分析即時庫存數據...
                      </div>
                    ) : aiInsights ? (
                      <div className="bg-blue-50/50 p-6 rounded-xl border border-blue-100 text-slate-700 leading-relaxed whitespace-pre-wrap">
                        {aiInsights}
                      </div>
                    ) : (
                      <div className="text-center py-12 text-slate-400 border-2 border-dashed border-slate-100 rounded-xl">
                        點擊按鈕獲取 AI 採購管理建議
                      </div>
                    )}
                  </div>
                </div>

                <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-100">
                  <h3 className="text-lg font-bold mb-6 flex items-center gap-2">
                    <Users className="text-purple-500" /> 單位領用佔比
                  </h3>
                  <div className="space-y-4">
                    {Object.entries(dashboardStats.depts).length > 0 ? (
                      Object.entries(dashboardStats.depts).map(([dept, count]) => (
                        <div key={dept} className="flex items-center gap-4">
                          <span className="w-24 text-sm font-medium text-slate-600 truncate">{dept}</span>
                          <div className="flex-1 h-3 bg-slate-100 rounded-full overflow-hidden">
                            <div 
                              className="h-full bg-purple-500" 
                              style={{ width: `${(count / logs.filter(l => l.type === 'OUT').length) * 100}%` }}
                            ></div>
                          </div>
                          <span className="w-8 text-right text-sm text-slate-400">{count}</span>
                        </div>
                      ))
                    ) : (
                      <div className="text-center py-12 text-slate-400">尚無領用數據</div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          )}

          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <div className="space-y-6 animate-in fade-in duration-300">
              <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
                <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center gap-4">
                  <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                    <input 
                      type="text" 
                      placeholder="搜尋名稱或編號..." 
                      className="w-full pl-10 pr-4 py-2 border rounded-xl bg-white focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                      value={searchTerm}
                      onChange={(e) => setSearchTerm(e.target.value)}
                    />
                  </div>
                </div>
                <table className="w-full border-collapse">
                  <thead>
                    <tr className="bg-slate-50 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">
                      <th className="px-6 py-4">物資名稱</th>
                      <th className="px-6 py-4">規格 / 購入日期</th>
                      <th className="px-6 py-4">目前數量</th>
                      <th className="px-6 py-4">低庫存警示值</th>
                      {activeTab === 'medicine' && <th className="px-6 py-4">有效日期</th>}
                      <th className="px-6 py-4 text-center">操作</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 text-sm">
                    {filteredItems.map(item => (
                      <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-6 py-4">
                          <div className="font-bold text-slate-700">{item.name}</div>
                          <div className="text-xs text-slate-400 mt-0.5">ID: {item.id}</div>
                        </td>
                        <td className="px-6 py-4">
                          <div className="text-slate-600">{item.spec}</div>
                          <div className="text-xs text-slate-400 mt-0.5">{item.purchaseDate || '--'}</div>
                        </td>
                        <td className="px-6 py-4">
                          <span className={`inline-flex items-center px-3 py-1 rounded-full font-bold ${
                            item.quantity <= item.minStock ? 'bg-rose-50 text-rose-600' : 'bg-emerald-50 text-emerald-600'
                          }`}>
                            {item.quantity} {item.unit}
                          </span>
                        </td>
                        <td className="px-6 py-4 text-slate-500">{item.minStock} {item.unit}</td>
                        {activeTab === 'medicine' && (
                          <td className="px-6 py-4">
                            <span className={`font-medium ${
                              item.expiryDate && item.expiryDate < new Date().toISOString().split('T')[0] 
                              ? 'text-rose-600 underline decoration-wavy' 
                              : 'text-slate-600'
                            }`}>
                              {item.expiryDate || '未註記'}
                            </span>
                          </td>
                        )}
                        <td className="px-6 py-4">
                          <div className="flex items-center justify-center gap-2">
                            <button 
                              onClick={() => { setEditTarget(item); setShowAddModal(true); }}
                              className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
                            >
                              <Edit3 size={18} />
                            </button>
                            <button 
                              onClick={() => setDeleteTarget({id: item.id, name: item.name})}
                              className="p-2 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-all"
                            >
                              <Trash2 size={18} />
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                {filteredItems.length === 0 && (
                  <div className="py-20 text-center text-slate-400 bg-white">
                    找不到相關項目
                  </div>
                )}
              </div>
            </div>
          )}

          {activeTab === 'issuance' && (
            <div className="max-w-2xl mx-auto bg-white rounded-2xl shadow-md border border-slate-200 overflow-hidden animate-in zoom-in-95 duration-300">
              <div className="p-8 border-b border-slate-100 bg-slate-50/50">
                <div className="flex gap-2 p-1 bg-slate-200 rounded-xl mb-8">
                  <button 
                    onClick={() => setIssuanceMode('OUT')}
                    className={`flex-1 py-3 rounded-lg font-bold transition-all ${issuanceMode === 'OUT' ? 'bg-rose-600 text-white shadow-md' : 'text-slate-600'}`}
                  >
                    單位領用 (出庫)
                  </button>
                  <button 
                    onClick={() => setIssuanceMode('IN')}
                    className={`flex-1 py-3 rounded-lg font-bold transition-all ${issuanceMode === 'IN' ? 'bg-emerald-600 text-white shadow-md' : 'text-slate-600'}`}
                  >
                    進貨補庫 (入庫)
                  </button>
                </div>

                <div className="space-y-6">
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-bold text-slate-700 mb-2">物資類別</label>
                      <select 
                        className="w-full p-3 border rounded-xl focus:ring-2 focus:ring-blue-500/20"
                        value={issuanceGroup}
                        onChange={(e) => { setIssuanceGroup(e.target.value as ItemGroup); setSelectedItemId(''); }}
                      >
                        <option value="INVENTORY">工安耗材</option>
                        <option value="MEDICINE">急救醫藥</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-bold text-slate-700 mb-2">選取物資名稱</label>
                      <select 
                        className="w-full p-3 border rounded-xl focus:ring-2 focus:ring-blue-500/20"
                        value={selectedItemId}
                        onChange={(e) => setSelectedItemId(e.target.value)}
                      >
                        <option value="">-- 請選擇 --</option>
                        {filteredIssuanceItems.map(i => (
                          <option key={i.id} value={i.id}>{i.name} (剩餘: {i.quantity} {i.unit})</option>
                        ))}
                      </select>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-bold text-slate-700 mb-2">數量</label>
                      <input 
                        type="number" 
                        className="w-full p-3 border rounded-xl focus:ring-2 focus:ring-blue-500/20"
                        value={inputQty}
                        onChange={(e) => setInputQty(e.target.value)}
                        min="1"
                      />
                    </div>
                    {issuanceMode === 'OUT' ? (
                      <div>
                        <label className="block text-sm font-bold text-slate-700 mb-2">領用單位</label>
                        <select 
                          className="w-full p-3 border rounded-xl focus:ring-2 focus:ring-blue-500/20"
                          value={selectedDept}
                          onChange={(e) => setSelectedDept(e.target.value)}
                        >
                          {DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
                        </select>
                      </div>
                    ) : (
                      <div className="flex items-end">
                        <div className="p-3 bg-blue-50 text-blue-700 rounded-xl text-xs flex-1 border border-blue-100">
                          進貨補庫時系統將自動標記為「庫房管理員」入庫。
                        </div>
                      </div>
                    )}
                  </div>

                  {issuanceMode === 'OUT' && (
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-sm font-bold text-slate-700 mb-2">領用人</label>
                        <input 
                          type="text" 
                          placeholder="姓名"
                          className="w-full p-3 border rounded-xl focus:ring-2 focus:ring-blue-500/20"
                          value={inputPerson}
                          onChange={(e) => setInputPerson(e.target.value)}
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-bold text-slate-700 mb-2">事由 / 用途</label>
                        <input 
                          type="text" 
                          placeholder="例如: 維修南二機組"
                          className="w-full p-3 border rounded-xl focus:ring-2 focus:ring-blue-500/20"
                          value={inputReason}
                          onChange={(e) => setInputReason(e.target.value)}
                        />
                      </div>
                    </div>
                  )}

                  <button 
                    onClick={handleTransaction}
                    className={`w-full py-4 rounded-xl font-bold text-lg shadow-lg transition-all transform active:scale-95 ${
                      issuanceMode === 'OUT' ? 'bg-rose-600 hover:bg-rose-700 text-white' : 'bg-emerald-600 hover:bg-emerald-700 text-white'
                    }`}
                  >
                    {issuanceMode === 'OUT' ? '確認領用出庫' : '確認進貨入庫'}
                  </button>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'history' && (
            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden animate-in fade-in duration-300">
              <div className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                <span className="text-sm font-bold text-slate-500">異動紀錄列表 (最新優先)</span>
                <button 
                  onClick={() => { if(window.confirm('確定要清空所有紀錄嗎？')) setLogs([]); }}
                  className="text-xs text-rose-600 hover:underline"
                >
                  清空歷史
                </button>
              </div>
              <table className="w-full">
                <thead>
                  <tr className="bg-slate-50 text-left text-xs font-bold text-slate-500 uppercase">
                    <th className="px-6 py-4">時間</th>
                    <th className="px-6 py-4">類型</th>
                    <th className="px-6 py-4">項目名稱</th>
                    <th className="px-6 py-4">數量</th>
                    <th className="px-6 py-4">經辦單位 / 人員</th>
                    <th className="px-6 py-4">備註</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-sm">
                  {logs.map(log => (
                    <tr key={log.id} className="hover:bg-slate-50">
                      <td className="px-6 py-4 text-slate-400 tabular-nums">
                        {new Date(log.timestamp).toLocaleString('zh-TW', { hour12: false })}
                      </td>
                      <td className="px-6 py-4">
                        <span className={`px-2 py-1 rounded-md text-xs font-bold ${
                          log.type === 'IN' ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'
                        }`}>
                          {log.type === 'IN' ? '入庫' : '出庫'}
