              <div className="flex justify-between py-2 border-b border-dashed border-slate-200">
                <span className="text-slate-500">領用人</span>
                <span className="font-bold text-slate-800">{lastTransaction.person}</span>
              </div>
              <div className="flex justify-between py-2">
                <span className="text-slate-500">時間</span>
                <span className="text-slate-500">{new Date(lastTransaction.timestamp).toLocaleString()}</span>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <button 
                onClick={() => { window.print(); setShowPrintModal(false); }}
                className="py-4 bg-slate-800 hover:bg-slate-900 text-white font-bold rounded-2xl flex items-center justify-center gap-2 shadow-lg transition-all"
              >
                <Printer size={20} /> 列印單據
