              <button 
                onClick={() => setShowPrintModal(false)}
                className="py-4 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-2xl shadow-lg transition-all"
              >
                完成
              </button>
            </div>
            <p className="text-center text-[10px] text-slate-300 mt-6 uppercase tracking-widest">Powered by SafeMan V20 Inventory Engine</p>
          </div>
        </div>
      )}

      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/60 flex items-center justify-center p-4 z-[100]">
          <div className="bg-white rounded-2xl p-8 max-w-sm w-full text-center shadow-2xl">
            <div className="w-16 h-16 bg-rose-50 text-rose-600 rounded-full flex items-center justify-center mx-auto mb-4">
