        input[type="date"] { color-scheme: light !important; font-weight: 700 !important; }
        label { color: #000000 !important; font-weight: 900 !important; }
        .modal-title { color: #000000 !important; font-weight: 900 !important; }
        .item-name-bold { color: #000000 !important; font-weight: 900 !important; font-size: 1.125rem; }
      `}</style>

      {/* 側邊導覽 */}
      <aside className="no-print w-72 bg-slate-900 text-white p-8 flex flex-col shrink-0">
        <div className="flex items-center gap-3 mb-12">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg"><Package size={22}/></div>
          <div><h1 className="font-black text-lg leading-tight">工安管理系統</h1><p className="text-[10px] text-slate-500 font-bold tracking-widest uppercase">V21 Final</p></div>
