              <thead>
                <tr className="text-[11px] font-black text-slate-400 uppercase border-b tracking-widest">
                  <th className="px-8 py-4">名稱及規格</th><th className="px-8 py-4 text-center">數量</th><th className="px-8 py-4 text-right">管理</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(i => (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-8 py-5">
                      <div className="item-name-bold">{item.name}</div>
                      <div className="text-xs text-slate-500 font-medium">
                        {item.spec && <span>規格: {item.spec}</span>}
                        {item.itemType === 'EQUIPMENT' ? ' [設備]' : ' [耗材]'}
                      </div>
                    </td>
                    <td className="px-8 py-5 text-center font-black">
                      <span className={`px-4 py-1.5 rounded-lg ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>{item.quantity} {item.unit}</span>
                    </td>
                    <td className="px-8 py-5 text-right">
                      <button onClick={() => setEditTarget(item)} className="p-2 text-slate-400 hover:text-blue-600"><Edit3 size={16}/></button>
                      <button onClick={() => setDeleteTarget({id: item.id, name: item.name})} className="p-2 text-slate-400 hover:text-red-600"><Trash2 size={16}/></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* 領用作業 */}
        {activeTab === 'issuance' && (
          <div className="max-w-4xl mx-auto bg-white p-12 rounded-[2.5rem] shadow-xl border border-slate-100">
             <div className="flex bg-slate-100 p-2 rounded-2xl mb-8">
               <button onClick={()=>setIssuanceMode('OUT')} className={`flex-1 py-5 rounded-xl font-black text-2xl transition-all ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button>
               <button onClick={()=>setIssuanceMode('IN')} className={`flex-1 py-5 rounded-xl font-black text-2xl transition-all ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
             </div>

             <div className="flex gap-4 mb-8">
               <button onClick={()=>setIssuanceGroup('INVENTORY')} className={`flex-1 py-5 rounded-2xl font-black text-2xl border-2 transition-all ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-200 text-slate-400'}`}>工安耗材</button>
               <button onClick={()=>setIssuanceGroup('MEDICINE')} className={`flex-1 py-5 rounded-2xl font-black text-2xl border-2 transition-all ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-200 text-slate-400'}`}>急救藥材</button>
             </div>

             <div className="grid grid-cols-1 gap-6">
                <div>
                  <label className="block text-sm font-black mb-2 uppercase tracking-wide">選取項目</label>
                  <select className="w-full p-4 border-2 rounded-xl font-bold text-lg" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                    <option value="">-- 請選擇項目 --</option>
                    {items.filter(i => i.itemGroup === issuanceGroup).map(i=>(
                      <option key={i.id} value={i.id}>{i.name} (庫存: {i.quantity} {i.unit})</option>
                    ))}
                  </select>
                </div>

                <div className="grid grid-cols-2 gap-6">
                  <div><label className="block text-sm font-black mb-2 uppercase tracking-wide">數量</label><input type="number" min="1" className="w-full p-4 border-2 rounded-xl font-bold text-lg" value={inputQty} onChange={e=>setInputQty(e.target.value)}/></div>
                  <div>
                    <label className="block text-sm font-black mb-2 uppercase tracking-wide">{issuanceMode === 'OUT' ? '領用單位' : '日期'}</label>
                    {issuanceMode === 'OUT' ? (
                      <select className="w-full p-4 border-2 rounded-xl font-bold text-lg" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>
                        {DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
                      </select>
                    ) : (
                      <div className="w-full p-4 border-2 bg-slate-50 text-slate-400 rounded-xl font-bold text-lg">{new Date().toLocaleDateString()}</div>
                    )}
                  </div>
                </div>

                {issuanceMode === 'OUT' && (
                  <div className="grid grid-cols-2 gap-6">
                    <div><label className="block text-sm font-black mb-2 uppercase tracking-wide">領用人</label><input type="text" className="w-full p-4 border-2 rounded-xl font-bold text-lg" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div>
                    <div><label className="block text-sm font-black mb-2 uppercase tracking-wide">領用用途/原因</label><input type="text" className="w-full p-4 border-2 rounded-xl font-bold text-lg" value={inputReason} onChange={e=>setInputReason(e.target.value)}/></div>
                  </div>
                )}

                <button onClick={handleTransaction} className={`w-full py-6 rounded-2xl font-black text-white text-3xl shadow-xl transition-all active:scale-95 mt-6 ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>
                  {issuanceMode === 'OUT' ? '列印領用單並更新庫存' : '完成補貨入庫並更新庫存'}
                </button>
             </div>
          </div>
        )}

        {/* 歷史日誌 */}
        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
             <table className="w-full text-left">
               <thead className="bg-slate-50 text-[11px] font-black text-slate-400 border-b uppercase">
                 <tr><th className="px-8 py-5">時間</th><th className="px-8 py-5">種類</th><th className="px-8 py-5">項目</th><th className="px-8 py-5 text-right">操作</th></tr>
               </thead>
               <tbody className="divide-y divide-slate-100">
                 {logs.map(log => (
                   <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                     <td className="px-8 py-5 text-xs text-slate-400 font-mono font-bold">{new Date(log.timestamp).toLocaleString()}</td>
                     <td className="px-8 py-5"><span className={`px-3 py-1 rounded-full text-[10px] font-black ${log.type === 'OUT' ? 'bg-blue-100 text-blue-600' : 'bg-emerald-100 text-emerald-600'}`}>{log.type === 'OUT' ? '領用' : '補貨'}</span></td>
                     <td className="px-8 py-5 item-name-bold">{log.itemName} (x{log.quantity})</td>
                     <td className="px-8 py-5 text-right">
                        {log.type === 'OUT' && <button onClick={()=>{setLastTransaction(log);setShowPrintModal(true);}} className="text-slate-400 hover:text-blue-600"><Printer size={18}/></button>}
                     </td>
                   </tr>
                 ))}
               </tbody>
             </table>
          </div>
        )}

        {/* 【核心修正 3】數據統計看板：分類區分 */}
        {activeTab === 'dashboard' && (
          <div className="space-y-10">
            {/* 工安耗材區塊 */}
            <section>
              <h3 className="text-xl font-black mb-4 flex items-center gap-2 text-blue-700"><Package /> 工安設備統計</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-white p-8 rounded-3xl shadow-sm border-l-8 border-l-blue-500">
                   <p className="text-slate-400 font-bold text-xs uppercase">耗材管理總數</p>
                   <h3 className="text-5xl font-black mt-2 text-slate-900">{dashboardStats.inv.total}</h3>
                </div>
                <div className="bg-white p-8 rounded-3xl shadow-sm border-l-8 border-l-orange-500">
                   <p className="text-orange-600 font-bold text-xs uppercase">耗材庫存警示</p>
                   <h3 className="text-5xl font-black text-orange-600 mt-2">{dashboardStats.inv.low}</h3>
                </div>
              </div>
            </section>

            {/* 急救藥材區塊 */}
            <section>
              <h3 className="text-xl font-black mb-4 flex items-center gap-2 text-emerald-700"><Stethoscope /> 急救藥材統計</h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-white p-8 rounded-3xl shadow-sm border-l-8 border-l-emerald-500">
                   <p className="text-slate-400 font-bold text-xs uppercase">藥材管理總數</p>
                   <h3 className="text-5xl font-black mt-2 text-slate-900">{dashboardStats.med.total}</h3>
                </div>
                <div className="bg-white p-8 rounded-3xl shadow-sm border-l-8 border-l-orange-400">
                   <p className="text-orange-400 font-bold text-xs uppercase">藥材庫存警示</p>
                   <h3 className="text-5xl font-black text-orange-400 mt-2">{dashboardStats.med.low}</h3>
                </div>
                <div className="bg-white p-8 rounded-3xl shadow-sm border-l-8 border-l-red-500">
                   <p className="text-red-600 font-bold text-xs uppercase">已過期藥材</p>
                   <h3 className="text-5xl font-black text-red-600 mt-2">{dashboardStats.med.expired}</h3>
                </div>
              </div>
            </section>

            <div className="bg-slate-900 p-10 rounded-[2.5rem] flex flex-col md:flex-row items-center gap-8 shadow-2xl">
               <div className="flex-1"><h4 className="text-white text-2xl font-black mb-2 flex items-center gap-3"><BrainCircuit className="text-blue-400"/> 工安 AI 顧問</h4><p className="text-slate-400 text-sm font-bold">自動分析各區庫存，生成專業管理建議。</p></div>
               <button onClick={async () => { setIsAiLoading(true); setAiInsights(await getInventoryInsights(items)); setIsAiLoading(false); }} className="px-10 py-5 bg-blue-600 text-white rounded-2xl font-black text-lg hover:bg-blue-500 transition-all shadow-xl">{isAiLoading ? '分析中...' : '生成營運建議'}</button>
            </div>
            {aiInsights && <div className="bg-blue-50 p-10 rounded-[2.5rem] border-2 border-blue-100 text-blue-900 font-bold shadow-sm">{aiInsights}</div>}
          </div>
        )}

        {/* Modal: 新增/編輯 */}
        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md z-[200] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-lg p-10 shadow-2xl">
              <div className="flex justify-between items-center mb-8">
                <h3 className="modal-title text-2xl">{(editTarget ? '編輯資料' : '新增管理項目')}</h3>
                <button onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="p-2 bg-slate-100 rounded-full text-slate-900"><X size={20}/></button>
              </div>
              <form className="space-y-4" onSubmit={handleSaveItem}>
                <div><label className="block text-xs uppercase mb-1">名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.name} /></div>
                <div>
                  <label className="block text-xs uppercase mb-1">單據類別</label>
                  {/* 【核心修正 4】固定分類名稱 */}
                  <select name="itemType" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.itemType || 'CONSUMABLE'}>
                    <option value="EQUIPMENT">安全衛生設備</option>
                    <option value="CONSUMABLE">安全衛生類消耗品</option>
                  </select>
                </div>
                {((editTarget?.itemGroup === 'MEDICINE') || (activeTab === 'medicine' && !editTarget)) && (
                  <div className="grid grid-cols-2 gap-4">
                    <div><label className="block text-xs uppercase mb-1">購入日期</label><input name="purchaseDate" type="date" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.purchaseDate} /></div>
                    <div><label className="block text-xs uppercase mb-1 text-red-600 font-black">效期截止日</label><input name="expiryDate" type="date" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.expiryDate} /></div>
                  </div>
                )}
                <div className="grid grid-cols-2 gap-4">
                  <div><label className="block text-xs uppercase mb-1">庫存單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.unit || '個'} /></div>
                  <div><label className="block text-xs uppercase mb-1">警戒庫存</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.minStock || 5} /></div>
                </div>
                <div><label className="block text-xs uppercase mb-1">現有庫存</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.quantity || 0} /></div>
                <div><label className="block text-xs uppercase mb-1">規格/規範</label><input name="spec" type="text" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.spec || ''} /></div>
                <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl mt-4 hover:bg-blue-700">儲存資料設定</button>
              </form>
            </div>
          </div>
        )}

        {/* 刪除確認 */}
        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[300] flex items-center justify-center p-4 text-center">
            <div className="bg-white rounded-[2rem] w-full max-w-[320px] p-8 shadow-2xl">
              <div className="w-16 h-16 bg-red-50 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4"><AlertTriangle size={32} /></div>
              <h3 className="text-xl font-black mb-2 text-slate-900">確認刪除？</h3>
              <p className="text-slate-500 text-sm font-bold mb-8">「{deleteTarget.name}」資料將會永久移除。</p>
              <div className="space-y-2">
                <button onClick={confirmDelete} className="w-full py-3 bg-red-600 text-white rounded-xl font-black">確定刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="w-full py-3 bg-slate-100 text-slate-400 rounded-xl font-bold">取消</button>
              </div>
            </div>
          </div>
        )}

        {/* 列印視窗 */}
        {showPrintModal && lastTransaction && (
          <div className="fixed inset-0 bg-slate-900/95 z-[100] flex flex-col items-center justify-start p-10 overflow-y-auto">
            <div className="bg-white rounded-[2.5rem] w-full max-w-5xl p-10 relative shadow-2xl my-4">
              <div className="flex justify-between items-center mb-8 no-print border-b pb-6">
                 <div className="flex items-center gap-3"><Printer className="text-blue-600" size={32}/><span className="font-black text-2xl text-slate-900">領用單正式預覽 (V21)</span></div>
                 <div className="flex gap-4">
                    <button onClick={()=>window.print()} className="bg-blue-600 text-white px-10 py-4 rounded-xl font-black text-xl shadow-xl">執行列印</button>
                    <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full text-slate-900 hover:bg-slate-200 transition-colors"><X size={24}/></button>
                 </div>
              </div>
              <div className="flex justify-center bg-white border p-4 shadow-inner"><PrintableForm transaction={lastTransaction} /></div>
            </div>
          </div>
        )}
      </main>

      <div className="hidden print:block absolute top-0 left-0 w-full">{lastTransaction && <PrintableForm transaction={lastTransaction} />}</div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  Users
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

// 使用 V21/V22 專屬 Key
const STORAGE_KEY_ITEMS = 'safeman_v21_final_items';
const STORAGE_KEY_LOGS = 'safeman_v21_final_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const confirmDelete = () => {
    if (!deleteTarget) return;
    setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  /**
   * 【核心修正：V22 優先任務】庫存攔截邏輯強制修復
   */
  const handleTransaction = () => {
    // 1. 基本檢查
    if (!selectedItemId) {
      window.alert('⚠️ 錯誤：請先選取項目！');
      return;
    }

    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    // 2. 數值強制轉換，避免字串比對錯誤
    const currentStock = parseFloat(targetItem.quantity.toString());
    const requestedAmount = parseFloat(inputQty);

    if (isNaN(requestedAmount) || requestedAmount <= 0) {
      window.alert('⚠️ 錯誤：請輸入有效的數量。');
      return;
    }

    // 3. 【攔截點】領用出庫模式：領用量 > 庫存量 時，必須跳出警告並中斷
    if (issuanceMode === 'OUT') {
      if (requestedAmount > currentStock) {
        window.alert(
          `❌ 庫存不足，領用作業失敗！\n\n` +
          `項目名稱：${targetItem.name}\n` +
          `現有庫存：${currentStock} ${targetItem.unit}\n` +
          `申請領用：${requestedAmount} ${targetItem.unit}\n\n` +
          `系統提示：申請數量已超過剩餘庫存，請先進行補貨或修正領用數量。`
        );
        return; // 強制中斷執行
      }
    }

    // 4. 通過檢查才執行更新
    const updatedItems = items.map(item => 
      item.id === selectedItemId 
        ? { ...item, quantity: issuanceMode === 'IN' ? Number(item.quantity) + requestedAmount : Number(item.quantity) - requestedAmount, lastUpdated: Date.now() } 
        : item
    );

    const newLog: Transaction = {
      id: generateId(),
      itemId: selectedItemId,
      itemName: targetItem.name,
      type: issuanceMode,
      quantity: requestedAmount,
      person: issuanceMode === 'OUT' ? (inputPerson || '未填寫') : '系統管理員',
      dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
      reason: issuanceMode === 'OUT' ? inputReason : '進貨',
      timestamp: Date.now()
    };

    setItems(updatedItems);
    setLogs(prev => [newLog, ...prev]);
    setLastTransaction(newLog);

    if (issuanceMode === 'OUT') {
      setShowPrintModal(true);
    } else {
      window.alert(`✅ 補貨成功：${targetItem.name} 庫存已更新至 ${currentStock + requestedAmount} ${targetItem.unit}`);
    }

    setSelectedItemId(''); setInputQty('1'); setInputPerson(''); setInputReason('');
  };

  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = {
      name: formData.get('name') as string,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
    };

    if (!data.name.trim()) return window.alert('名稱不可為空');

    if (editTarget) {
      setItems(prev => prev.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i));
      setEditTarget(null);
    } else {
      const newItem: InventoryItem = {
        id: generateId(),
        ...data,
        itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
        category: Category.OTHER,
        description: '',
        lastUpdated: Date.now()
      };
      setItems(prev => [...prev, newItem]);
      setShowAddModal(false);
    }
  };

  const dashboardStats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    const medItems = items.filter(i => i.itemGroup === 'MEDICINE');
    const today = new Date().toISOString().split('T')[0];
    const deptMap: Record<string, number> = {};
    logs.filter(l => l.type === 'OUT').forEach(l => {
      deptMap[l.dept] = (deptMap[l.dept] || 0) + 1;
    });
    return {
      inv: { total: invItems.length, low: invItems.filter(i => i.quantity <= i.minStock).length },
      med: { total: medItems.length, low: medItems.filter(i => i.quantity <= i.minStock).length, expired: medItems.filter(i => i.expiryDate && i.expiryDate < today).length },
