              <th className="w-[10%]">單位</th><th className="w-[10%]">數量</th><th className="w-[20%]">備　　　　　註</th>
            </tr>
          </thead>
          <tbody>
            {batch.items.map((item, idx) => (
              <tr key={idx} className="font-bold">
                <td className="text-left leading-tight text-base">{item.name}</td>
                <td className="text-xs font-normal leading-tight">{item.spec}</td>
                <td>{item.unit}</td>
                <td className="text-xl">{item.quantity}</td>
