                                 <td className="px-6 py-4 text-center font-black text-blue-600">{bItem.quantity} {bItem.unit}</td>
                                 <td className="px-6 py-4 text-right">
                                    <button onClick={()=>setBasket(prev => prev.filter((_, i) => i !== idx))} className="text-slate-300 hover:text-red-500"><X size={18}/></button>
                                 </td>
                               </tr>
                             ))}
                           </tbody>
                         </table>
                       ) : (
                         <div className="h-full flex flex-col items-center justify-center text-slate-300 p-10 text-center">
                           <ShoppingCart size={48} className="mb-4 opacity-20" />
                           <p className="font-bold">目前清單內尚無項目<br/>請由左側挑選並加入</p>
                         </div>
                       )}
                    </div>

                    <div className="space-y-4">
                      {issuanceMode === 'OUT' && (
                        <div className="grid grid-cols-2 gap-4">
                          <div><label className="block text-xs font-black mb-1">領用單位</label>
                            <select className="w-full p-3 border-2 rounded-xl font-bold" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>
                              {DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
                            </select>
                          </div>
                          <div><label className="block text-xs font-black mb-1">領用人 *</label><input type="text" className="w-full p-3 border-2 rounded-xl font-bold" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div>
                          <div className="col-span-2"><label className="block text-xs font-black mb-1">用途/備註</label><input type="text" className="w-full p-3 border-2 rounded-xl font-bold" value={inputReason} onChange={e=>setInputReason(e.target.value)}/></div>
                        </div>
                      )}
                      <button onClick={processIssuance} disabled={basket.length === 0} className={`w-full py-6 rounded-2xl font-black text-white text-3xl shadow-xl transition-all active:scale-95 disabled:opacity-30 disabled:grayscale ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>
                        {issuanceMode === 'OUT' ? '確認並列印領用單' : '確認入庫'}
                      </button>
                    </div>
                  </div>
               </div>
             </div>
          </div>
        )}

        {/* 歷史日誌 */}
        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
             <table className="w-full text-left">
               <thead className="bg-slate-50 text-[11px] font-black text-slate-400 border-b uppercase">
                 <tr><th className="px-8 py-5">時間</th><th className="px-8 py-5">種類</th><th className="px-8 py-5">項目</th><th className="px-8 py-5">領用單位/經辦</th><th className="px-8 py-5 text-right">操作</th></tr>
               </thead>
               <tbody className="divide-y divide-slate-100">
                 {logs.map(log => (
                   <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                     <td className="px-8 py-5 text-xs text-slate-400 font-mono font-bold">{new Date(log.timestamp).toLocaleString()}</td>
                     <td className="px-8 py-5"><span className={`px-3 py-1 rounded-full text-[10px] font-black ${log.type === 'OUT' ? 'bg-blue-100 text-blue-600' : 'bg-emerald-100 text-emerald-600'}`}>{log.type === 'OUT' ? '領用' : '補貨'}</span></td>
                     <td className="px-8 py-5 item-name-bold">{log.itemName} (x{log.quantity})</td>
                     <td className="px-8 py-5 text-xs font-bold text-slate-600">{log.dept} / {log.person}</td>
                     <td className="px-8 py-5 text-right">
                        <button onClick={()=>{ if(window.confirm('此為單筆紀錄，合併單據請至領用作業列印。是否單獨列印此項？')) { setLastTransactionBatch({id: log.id, dept: log.dept, person: log.person, reason: log.reason, items: [{itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '個', spec: '', itemType: 'CONSUMABLE'}], timestamp: log.timestamp}); setShowPrintModal(true); } }} className="text-slate-400 hover:text-blue-600"><Printer size={18}/></button>
                     </td>
                   </tr>
                 ))}
               </tbody>
             </table>
          </div>
        )}

        {/* 數據統計看板 */}
        {activeTab === 'dashboard' && (
          <div className="space-y-10 animate-in fade-in duration-500">
            <section>
              <h3 className="text-xl font-black mb-4 flex items-center gap-2 text-blue-700"><Package /> 工安耗材統計</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-white p-8 rounded-3xl shadow-sm border-l-8 border-l-blue-500">
                   <p className="text-slate-400 font-bold text-xs uppercase">總品項數</p>
                   <h3 className="text-5xl font-black mt-2 text-slate-900">{dashboardStats.inv.total}</h3>
                </div>
                <div className="bg-white p-8 rounded-3xl shadow-sm border-l-8 border-l-orange-500">
                   <p className="text-orange-600 font-bold text-xs uppercase">庫存警示數</p>
                   <h3 className="text-5xl font-black text-orange-600 mt-2">{dashboardStats.inv.low}</h3>
                </div>
              </div>
            </section>

            <section>
              <h3 className="text-xl font-black mb-4 flex items-center gap-2 text-emerald-700"><Stethoscope /> 急救藥材統計</h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-white p-8 rounded-3xl shadow-sm border-l-8 border-l-emerald-500">
                   <p className="text-slate-400 font-bold text-xs uppercase">總品項數</p>
                   <h3 className="text-5xl font-black mt-2 text-slate-900">{dashboardStats.med.total}</h3>
                </div>
                <div className="bg-white p-8 rounded-3xl shadow-sm border-l-8 border-l-orange-400">
                   <p className="text-orange-400 font-bold text-xs uppercase">庫存警示數</p>
                   <h3 className="text-5xl font-black text-orange-400 mt-2">{dashboardStats.med.low}</h3>
                </div>
                <div className="bg-white p-8 rounded-3xl shadow-sm border-l-8 border-l-red-500">
                   <p className="text-red-600 font-bold text-xs uppercase">過期項目數</p>
                   <h3 className="text-5xl font-black text-red-600 mt-2">{dashboardStats.med.expired}</h3>
                </div>
              </div>
            </section>

            <div className="bg-slate-900 p-10 rounded-[2.5rem] flex flex-col md:flex-row items-center gap-8 shadow-2xl">
               <div className="flex-1">
                 <h4 className="text-white text-2xl font-black mb-2 flex items-center gap-3"><BrainCircuit className="text-blue-400"/> 工安 AI 顧問分析</h4>
                 <p className="text-slate-400 text-sm font-bold">根據目前庫存水位與領用歷史，為您提供專業的採購建議。</p>
               </div>
               <button onClick={async () => { setIsAiLoading(true); setAiInsights(await getInventoryInsights(items)); setIsAiLoading(false); }} className="px-10 py-5 bg-blue-600 text-white rounded-2xl font-black text-lg hover:bg-blue-500 transition-all shadow-xl">{isAiLoading ? '分析中...' : '生成採購策略'}</button>
            </div>
            {aiInsights && <div className="bg-blue-50 p-10 rounded-[2.5rem] border-2 border-blue-100 text-blue-900 font-bold shadow-sm whitespace-pre-wrap">{aiInsights}</div>}
          </div>
        )}

        {/* Modal: 新增/編輯 */}
        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md z-[200] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-lg p-10 shadow-2xl">
              <div className="flex justify-between items-center mb-8">
                <h3 className="text-2xl font-black text-slate-900">{(editTarget ? '編輯資料' : '新增管理項目')}</h3>
                <button onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="p-2 bg-slate-100 rounded-full text-slate-900"><X size={20}/></button>
              </div>
              <form className="space-y-4" onSubmit={handleSaveItem}>
                <div><label className="block text-xs uppercase mb-1">名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.name} /></div>
                <div>
                  <label className="block text-xs uppercase mb-1">類別</label>
                  <select name="itemType" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.itemType || 'CONSUMABLE'}>
                    <option value="EQUIPMENT">安全衛生設備</option>
                    <option value="CONSUMABLE">安全衛生類消耗品</option>
                  </select>
                </div>
                {((editTarget?.itemGroup === 'MEDICINE') || (activeTab === 'medicine' && !editTarget)) && (
                  <div className="grid grid-cols-2 gap-4">
                    <div><label className="block text-xs uppercase mb-1">購入日期</label><input name="purchaseDate" type="date" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.purchaseDate} /></div>
                    <div><label className="block text-xs uppercase mb-1 text-red-600 font-black">效期截止日</label><input name="expiryDate" type="date" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.expiryDate} /></div>
                  </div>
                )}
                <div className="grid grid-cols-2 gap-4">
                  <div><label className="block text-xs uppercase mb-1">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.unit || '個'} /></div>
                  <div><label className="block text-xs uppercase mb-1">警戒庫存</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.minStock || 5} /></div>
                </div>
                <div><label className="block text-xs uppercase mb-1">現有庫存</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.quantity || 0} /></div>
                <div><label className="block text-xs uppercase mb-1">規格/規範</label><input name="spec" type="text" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.spec || ''} /></div>
                <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl mt-4 hover:bg-blue-700">儲存項目設定</button>
              </form>
            </div>
          </div>
        )}

        {/* 刪除確認 */}
        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[300] flex items-center justify-center p-4 text-center">
            <div className="bg-white rounded-[2rem] w-full max-w-[320px] p-8 shadow-2xl">
              <div className="w-16 h-16 bg-red-50 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4"><AlertTriangle size={32} /></div>
              <h3 className="text-xl font-black mb-2 text-slate-900">確認刪除？</h3>
              <p className="text-slate-500 text-sm font-bold mb-8">「{deleteTarget.name}」將被永久移除。</p>
              <div className="space-y-2">
                <button onClick={confirmDelete} className="w-full py-3 bg-red-600 text-white rounded-xl font-black">確定刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="w-full py-3 bg-slate-100 text-slate-400 rounded-xl font-bold">取消</button>
              </div>
            </div>
          </div>
        )}

        {/* 批次列印視窗 */}
        {showPrintModal && lastTransactionBatch && (
          <div className="fixed inset-0 bg-slate-900/95 z-[500] flex flex-col items-center justify-start p-10 overflow-y-auto">
            <div className="bg-white rounded-[2.5rem] w-full max-w-5xl p-10 relative shadow-2xl my-4">
              <div className="flex justify-between items-center mb-8 no-print border-b pb-6">
                 <div className="flex items-center gap-4">
                   <div className="p-3 bg-emerald-50 text-emerald-600 rounded-full"><CheckCircle2 size={32}/></div>
                   <div><h3 className="font-black text-2xl text-slate-900">領用完成：多樣合併單據預覽</h3><p className="text-slate-400 font-bold">已同步扣除共 {lastTransactionBatch.items.length} 個項目的庫存</p></div>
                 </div>
                 <div className="flex gap-4">
                    <button onClick={()=>window.print()} className="bg-blue-600 text-white px-10 py-4 rounded-xl font-black text-xl shadow-xl hover:scale-105 transition-all">執行列印</button>
                    <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full text-slate-900 hover:bg-slate-200 transition-colors"><X size={24}/></button>
                 </div>
              </div>
              <div className="flex justify-center bg-white border p-4 shadow-inner">
                <PrintableForm batch={lastTransactionBatch} />
              </div>
            </div>
          </div>
        )}
      </main>

      <div className="hidden print:block absolute top-0 left-0 w-full">
        {lastTransactionBatch && <PrintableForm batch={lastTransactionBatch} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  Users,
  ShoppingCart,
  CheckCircle2
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v23_batch_items';
const STORAGE_KEY_LOGS = 'safeman_v23_batch_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
    id: string;
  } | null>(null);

  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const confirmDelete = () => {
    if (!deleteTarget) return;
    setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  const addToBasket = () => {
    if (!selectedItemId) {
      window.alert('⚠️ 請先從下拉選單選取項目！');
      return;
    }

    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    const currentStock = Number(targetItem.quantity);
    const requestedAmount = Number(inputQty);

    if (isNaN(requestedAmount) || requestedAmount <= 0) {
      window.alert('⚠️ 數量輸入不正確。');
      return;
    }

    const alreadyInBasket = basket.filter(b => b.itemId === selectedItemId).reduce((acc, curr) => acc + curr.quantity, 0);
    const totalRequested = requestedAmount + alreadyInBasket;

    if (issuanceMode === 'OUT' && totalRequested > currentStock) {
      window.alert(
        `❌ 庫存不足，無法加入！\n\n` +
        `項目：${targetItem.name}\n` +
        `現有總庫存：${currentStock} ${targetItem.unit}\n` +
        `待處理清單已佔用：${alreadyInBasket} ${targetItem.unit}\n\n` +
        `提示：剩餘庫存無法滿足本次領用需求。`
      );
      return;
    }

    setBasket(prev => [
      ...prev,
      {
        itemId: targetItem.id,
        name: targetItem.name,
        quantity: requestedAmount,
        unit: targetItem.unit,
        spec: targetItem.spec,
        itemType: targetItem.itemType
      }
    ]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) {
      window.alert('⚠️ 清單目前是空的，請先加入項目。');
      return;
    }

    if (issuanceMode === 'OUT' && (!inputPerson.trim())) {
      window.alert('❌ 無法處理：領用出庫必須填寫「領用人」姓名！');
      return;
    }

    const timestamp = Date.now();
    const batchId = generateId();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(bItem => {
      updatedItems = updatedItems.map(item => {
        if (item.id === bItem.itemId) {
          const newQty = issuanceMode === 'IN' ? item.quantity + bItem.quantity : item.quantity - bItem.quantity;
          return { ...item, quantity: newQty, lastUpdated: timestamp };
        }
        return item;
      });
      newLogs.push({
        id: generateId() + Math.random().toString(36).substr(2, 4),
        itemId: bItem.itemId,
        itemName: bItem.name,
        type: issuanceMode,
        quantity: bItem.quantity,
        person: issuanceMode === 'OUT' ? inputPerson : '系統管理員',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: issuanceMode === 'OUT' ? inputReason : '批次進貨',
        timestamp: timestamp
      });
    });

    setItems(updatedItems);
    setLogs(prev => [...newLogs, ...prev]);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({
        id: batchId,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: basket,
        timestamp: timestamp
      });
      setShowPrintModal(true);
    } else {
      window.alert(`✅ 入庫作業完成，共更新 ${basket.length} 項物資庫存。`);
    }

    setBasket([]); setInputPerson(''); setInputReason('');
  };

  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = {
      name: formData.get('name') as string,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
    };
    if (!data.name.trim()) return window.alert('名稱不可為空');
    if (editTarget) {
      setItems(prev => prev.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i));
      setEditTarget(null);
    } else {
      setItems(prev => [...prev, { id: generateId(), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: Date.now() }]);
      setShowAddModal(false);
    }
  };

  const dashboardStats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    const medItems = items.filter(i => i.itemGroup === 'MEDICINE');
    const today = new Date().toISOString().split('T')[0];
    return {
      inv: { total: invItems.length, low: invItems.filter(i => i.quantity <= i.minStock).length },
      med: { total: medItems.length, low: medItems.filter(i => i.quantity <= i.minStock).length, expired: medItems.filter(i => i.expiryDate && i.expiryDate < today).length }
    };
  }, [items]);

  const PrintableForm = ({ batch }: { batch: { id: string, dept: string, person: string, reason: string, items: BasketItem[], timestamp: number } }) => {
    const date = new Date(batch.timestamp);
    const emptyRows = Array(Math.max(0, 15 - batch.items.length)).fill(null);
    const primaryType = batch.items[0]?.itemType || 'CONSUMABLE';
    return (
      <div className="print-area bg-white text-black p-6 w-[210mm] mx-auto relative overflow-hidden" id="official-form-v24">
        <style>{`
          @font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); }
          #official-form-v24 { font-family: 'StandardKai', serif; font-size: 13pt; color: #000000 !important; }
          #official-form-v24 table { border-collapse: collapse; width: 100%; border: 2.5px solid #000000; }
          #official-form-v24 th, #official-form-v24 td { border: 2px solid #000000; padding: 4px 8px; height: 35px; text-align: center; color: #000000 !important; }
          @media print { .no-print { display: none !important; } }
        `}</style>
        <div className="absolute top-4 right-8 text-[9pt] font-bold text-right text-slate-400">
           <div>批次單號：{batch.id}</div>
           <div>領用人：{batch.person}</div>
        </div>
        <h1 className="text-center text-3xl font-bold mb-6 pt-10 tracking-[0.2em]" style={{color: '#000000'}}>台灣電力公司電力修護處南部分處</h1>
        <div className="flex justify-center gap-12 mb-6 font-bold text-xl" style={{color: '#000000'}}>
          <label className="flex items-center gap-2"><span className="w-6 h-6 border-2 border-black flex items-center justify-center font-black">{primaryType === 'EQUIPMENT' ? 'V' : ''}</span> 安全衛生設備</label>
