import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v25_batch_items';
const STORAGE_KEY_LOGS = 'safeman_v25_batch_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  // 【功能：計算清單內已佔用的庫存】
  const getReservedQty = (itemId: string) => {
    return basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);
  };

  const addToBasket = () => {
    if (!selectedItemId) {
      window.alert('⚠️ 請先選取項目。');
      return;
    }
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    const currentStock = Number(targetItem.quantity);
    const requestedAmount = Number(inputQty);
    const reservedAmount = getReservedQty(selectedItemId);
    const availableStock = currentStock - reservedAmount;

    if (isNaN(requestedAmount) || requestedAmount <= 0) {
      window.alert('⚠️ 數量輸入不正確。');
      return;
    }

    // 【核心修正：強制攔截警示視窗】
    if (issuanceMode === 'OUT' && requestedAmount > availableStock) {
      window.alert(
        `❌ 庫存警報：領用量超過剩餘庫存！\n\n` +
        `項目名稱：${targetItem.name}\n` +
        `原始庫存：${currentStock} ${targetItem.unit}\n` +
        `待處理清單已佔用：${reservedAmount} ${targetItem.unit}\n` +
        `剩餘可用：${availableStock} ${targetItem.unit}\n\n` +
        `您欲領用：${requestedAmount} ${targetItem.unit}\n\n` +
        `系統提示：申請數量過大，請調整數量或先完成補貨。`
      );
      return; // 強制中斷，不加入清單
    }

    setBasket(prev => [
      ...prev,
      {
        itemId: targetItem.id,
        name: targetItem.name,
        quantity: requestedAmount,
        unit: targetItem.unit,
        spec: targetItem.spec,
        itemType: targetItem.itemType
      }
    ]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) {
      window.alert('⚠️ 待處理清單是空的。');
      return;
    }
    if (issuanceMode === 'OUT' && !inputPerson.trim()) {
      window.alert('❌ 錯誤：領用出庫必須填寫「領用人」。');
      return;
    }

    const timestamp = Date.now();
    const batchId = generateId();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(bItem => {
      updatedItems = updatedItems.map(item => {
        if (item.id === bItem.itemId) {
          const newQty = issuanceMode === 'IN' ? item.quantity + bItem.quantity : item.quantity - bItem.quantity;
          return { ...item, quantity: newQty, lastUpdated: timestamp };
        }
        return item;
      });
      newLogs.push({
        id: generateId() + Math.random().toString(36).substr(2, 4),
        itemId: bItem.itemId,
        itemName: bItem.name,
        type: issuanceMode,
        quantity: bItem.quantity,
        person: issuanceMode === 'OUT' ? inputPerson : '系統管理員',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: issuanceMode === 'OUT' ? inputReason : '批次進貨',
        timestamp: timestamp
      });
    });

    setItems(updatedItems);
    setLogs(prev => [...newLogs, ...prev]);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({
        id: batchId,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: timestamp
      });
      setShowPrintModal(true);
    } else {
      window.alert(`✅ 入庫完成，已更新 ${basket.length} 項物資。`);
      setBasket([]); setInputPerson(''); setInputReason('');
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = {
      name: formData.get('name') as string,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
    };
    if (!data.name.trim()) return window.alert('名稱不可為空');
    if (editTarget) {
      setItems(prev => prev.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i));
      setEditTarget(null);
    } else {
      setItems(prev => [...prev, { id: generateId(), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: Date.now() }]);
      setShowAddModal(false);
    }
  };

  const dashboardStats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    const medItems = items.filter(i => i.itemGroup === 'MEDICINE');
    const today = new Date().toISOString().split('T')[0];
    return {
      inv: { total: invItems.length, low: invItems.filter(i => i.quantity <= i.minStock).length },
      med: { total: medItems.length, low: medItems.filter(i => i.quantity <= i.minStock).length, expired: medItems.filter(i => i.expiryDate && i.expiryDate < today).length }
    };
  }, [items]);

  const PrintableForm = ({ batch }: { batch: { id: string, dept: string, person: string, reason: string, items: BasketItem[], timestamp: number } }) => {
    const date = new Date(batch.timestamp);
    const emptyRows = Array(Math.max(0, 15 - batch.items.length)).fill(null);
    const primaryType = batch.items[0]?.itemType || 'CONSUMABLE';
    return (
      <div className="print-area-content bg-white text-black p-10 w-[210mm] mx-auto relative overflow-hidden" style={{ minHeight: '297mm', color: '#000000' }}>
        <style>{`
          @font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); }
          .print-area-content { font-family: 'StandardKai', serif; font-size: 13pt; line-height: 1.5; }
          .print-area-content table { border-collapse: collapse; width: 100%; border: 2.5px solid #000000; margin-bottom: 20px; }
          .print-area-content th, .print-area-content td { border: 2px solid #000000; padding: 6px 10px; height: 38px; text-align: center; color: #000000 !important; }
          .print-area-content h1 { font-size: 28pt; margin-bottom: 40px; }
        `}</style>
        <div className="absolute top-6 right-10 text-[10pt] font-bold text-right text-slate-400 no-print-item">
           <div>單號：{batch.id}</div>
           <div>領用人：{batch.person}</div>
        </div>
        <h1 className="text-center font-bold tracking-[0.2em] text-black">台灣電力公司電力修護處南部分處</h1>
        <div className="flex justify-center gap-14 mb-10 font-bold text-2xl text-black">
          <label className="flex items-center gap-3">
            <span className="w-7 h-7 border-2 border-black flex items-center justify-center font-black">{primaryType === 'EQUIPMENT' ? 'V' : ''}</span> 安全衛生設備
          </label>
          <label className="flex items-center gap-3">
            <span className="w-7 h-7 border-2 border-black flex items-center justify-center font-black">{primaryType === 'CONSUMABLE' ? 'V' : ''}</span> 安全衛生類消耗品
          </label>
        </div>
        <div className="flex justify-between mb-4 font-bold px-2 text-xl text-black">
          <div>領用單位：<span className="inline-block border-b-2 border-dotted border-black min-w-[220px] text-center">{batch.dept}</span></div>
          <div>中華民國 {date.getFullYear() - 1911} 年 {date.getMonth() + 1} 月 {date.getDate()} 日</div>
        </div>
        <table>
          <thead>
            <tr className="bg-slate-50 font-bold">
              <th className="w-[35%]">名　　　　　稱</th><th className="w-[25%]">規　範（序　號）</th>
              <th className="w-[10%]">單位</th><th className="w-[10%]">數量</th><th className="w-[20%]">備　　　　　註</th>
            </tr>
          </thead>
          <tbody>
            {batch.items.map((item, idx) => (
              <tr key={idx} className="font-bold">
                <td className="text-left leading-tight">{item.name}</td>
                <td className="text-sm font-normal">{item.spec}</td>
                <td>{item.unit}</td>
                <td className="text-2xl">{item.quantity}</td>
                <td className="text-left text-xs font-normal">{idx === 0 ? batch.reason : ''}</td>
              </tr>
            ))}
            {emptyRows.map((_, idx) => <tr key={idx}><td /><td /><td /><td /><td /></tr>)}
          </tbody>
        </table>
        <div className="mt-16 font-bold grid grid-cols-2 gap-x-12 text-black">
          <div className="flex flex-col gap-14"><div>申請部門：</div><div className="flex justify-between w-full px-4 text-base"><div>經辦：</div><div>課長：</div><div>經理：</div></div></div>
          <div className="flex flex-col gap-14"><div>經管部門：</div><div className="flex justify-between w-full px-4 text-base"><div>經辦：</div><div>課長：</div><div>經理：</div></div></div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-slate-100 text-slate-900 font-sans">
      {/* 全域樣式修正：日期選擇器、輸入框顯影 */}
      <style>{`
        input, select, textarea { 
          color: #000000 !important; 
          background-color: #ffffff !important; 
          border: 2px solid #94a3b8 !important; 
          font-weight: 700 !important;
        }
        input[type="date"]::-webkit-calendar-picker-indicator {
          background-color: #ffffff;
          padding: 4px;
          cursor: pointer;
          border-radius: 4px;
          filter: invert(0);
          border: 1px solid #000;
        }
        input:focus, select:focus { border-color: #2563eb !important; outline: none; }
        label { color: #000000 !important; font-weight: 900 !important; }
        .item-name-bold { color: #000000 !important; font-weight: 900 !important; font-size: 1.125rem; }

        @media print {
          body * { visibility: hidden !important; }
          #print-section, #print-section * { visibility: visible !important; }
          #print-section { position: absolute; left: 0; top: 0; width: 100%; display: block !important; }
          .no-print, aside, main, .modal-backdrop { display: none !important; }
        }
      `}</style>

      <aside className="no-print w-72 bg-slate-900 text-white p-8 flex flex-col shrink-0 shadow-2xl z-20">
        <div className="flex items-center gap-3 mb-12">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg"><Package size={22}/></div>
          <div><h1 className="font-black text-lg leading-tight">工安管理系統</h1><p className="text-[10px] text-slate-500 font-bold tracking-widest uppercase">V25 Final Repair</p></div>
        </div>
        <nav className="flex-1 space-y-2">
          {[
            { id: 'inventory', label: '工安耗材管理', icon: Package },
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
            { id: 'issuance', label: '領用補貨作業', icon: FileText },
            { id: 'history', label: '歷史異動日誌', icon: History },
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard },
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-xl scale-105' : 'text-slate-400 hover:bg-slate-800'}`}><tab.icon size={20} /> {tab.label}</button>
          ))}
        </nav>
      </aside>

      <main className="no-print flex-1 p-10 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-3xl font-black text-slate-900">
            {activeTab === 'inventory' ? '工安耗材清冊' : activeTab === 'medicine' ? '急救藥材清冊' : activeTab === 'issuance' ? '領用/補貨批次登記' : activeTab === 'history' ? '歷史異動日誌' : '數據中心統計'}
          </h2>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-3 shadow-lg hover:bg-black transition-colors"><Plus size={18}/> 新增管理項目</button>
          )}
        </header>

        {activeTab === 'issuance' && (
          <div className="max-w-6xl mx-auto space-y-8 animate-in fade-in zoom-in-95 duration-300">
             <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
               {/* 1. 挑選項目 */}
               <div className="lg:col-span-2 bg-white p-10 rounded-[2.5rem] shadow-xl border border-slate-100 flex flex-col">
                  <h3 className="text-2xl font-black mb-8 flex items-center gap-3 text-slate-800"><ShoppingCart className="text-blue-500"/> 1. 挑選項目</h3>
                  <div className="flex bg-slate-100 p-1.5 rounded-2xl mb-6">
                    <button onClick={()=>{setIssuanceMode('OUT'); setBasket([]);}} className={`flex-1 py-3 rounded-xl font-black transition-all ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button>
                    <button onClick={()=>{setIssuanceMode('IN'); setBasket([]);}} className={`flex-1 py-3 rounded-xl font-black transition-all ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
                  </div>
                  <div className="flex gap-2 mb-6 text-xs">
                    <button onClick={()=>setIssuanceGroup('INVENTORY')} className={`flex-1 py-3 rounded-xl font-black border-2 transition-all ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-200 text-slate-400'}`}>工安耗材</button>
                    <button onClick={()=>setIssuanceGroup('MEDICINE')} className={`flex-1 py-3 rounded-xl font-black border-2 transition-all ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-200 text-slate-400'}`}>急救藥材</button>
                  </div>
                  <div className="space-y-6">
                    <div>
                      <label className="block text-xs font-black mb-1">選取項目 (顯示剩餘可用)</label>
                      <select className="w-full p-4 border-2 rounded-xl font-bold text-lg" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                        <option value="">-- 請選擇 --</option>
                        {items.filter(i => i.itemGroup === issuanceGroup).map(i => {
                          const reserved = getReservedQty(i.id);
                          const available = i.quantity - reserved;
                          return (
                            <option key={i.id} value={i.id} className={available <= 0 ? 'text-red-400' : ''}>
                              {i.name} (剩餘: {available} {i.unit})
                            </option>
                          );
                        })}
                      </select>
                    </div>
                    <div><label className="block text-xs font-black mb-1">數量</label><input type="number" min="1" className="w-full p-4 border-2 rounded-xl font-bold text-lg" value={inputQty} onChange={e=>setInputQty(e.target.value)}/></div>
                    <button onClick={addToBasket} className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black text-xl hover:bg-black shadow-lg flex items-center justify-center gap-3"><Plus size={20}/> {issuanceMode === 'OUT' ? '加入領用清單' : '加入入庫清單'}</button>
                  </div>
               </div>
               {/* 2. 待處理清單 */}
               <div className="lg:col-span-3 flex flex-col gap-6">
                  <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-slate-100 flex-1 flex flex-col">
                    <div className="flex justify-between items-center mb-6"><h3 className="text-2xl font-black flex items-center gap-3 text-slate-800"><FileText className="text-emerald-500"/> 2. 待處理清單</h3><span className="bg-slate-100 px-4 py-1 rounded-full text-sm font-black">{basket.length} 項目</span></div>
                    <div className="flex-1 overflow-y-auto border-2 border-dashed border-slate-100 rounded-2xl mb-6 min-h-[200px]">
                       {basket.length > 0 ? (
                         <table className="w-full text-left">
                           <thead><tr className="text-[10px] font-black text-slate-400 uppercase border-b bg-slate-50"><th className="px-6 py-3">物資名稱</th><th className="px-6 py-3 text-center">數量</th><th className="px-6 py-3 text-right">移除</th></tr></thead>
                           <tbody className="divide-y divide-slate-50">{basket.map((bItem, idx) => (<tr key={idx} className="hover:bg-slate-50 transition-colors"><td className="px-6 py-4 font-black text-slate-800">{bItem.name}</td><td className="px-6 py-4 text-center font-black text-blue-600">{bItem.quantity} {bItem.unit}</td><td className="px-6 py-4 text-right"><button onClick={()=>setBasket(prev => prev.filter((_, i) => i !== idx))} className="text-slate-300 hover:text-red-500"><X size={18}/></button></td></tr>))}</tbody>
                         </table>
                       ) : (<div className="h-full flex flex-col items-center justify-center text-slate-300 p-10 text-center"><ShoppingCart size={48} className="mb-4 opacity-20" /><p className="font-bold">目前清單內尚無項目</p></div>)}
                    </div>
                    <div className="space-y-4">
                      {issuanceMode === 'OUT' && (
                        <div className="grid grid-cols-2 gap-4">
                          <div><label className="block text-xs font-black mb-1">領用單位</label><select className="w-full p-3 border-2 rounded-xl font-bold" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>{DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}</select></div>
                          <div><label className="block text-xs font-black mb-1">領用人 *</label><input type="text" className="w-full p-3 border-2 rounded-xl font-bold" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div>
                          <div className="col-span-2"><label className="block text-xs font-black mb-1">用途/備註</label><input type="text" className="w-full p-3 border-2 rounded-xl font-bold" value={inputReason} onChange={e=>setInputReason(e.target.value)}/></div>
                        </div>
                      )}
                      <button onClick={processIssuance} disabled={basket.length === 0} className={`w-full py-6 rounded-2xl font-black text-white text-3xl shadow-xl transition-all active:scale-95 disabled:opacity-30 ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>
                        {issuanceMode === 'OUT' ? '確認並列印領用單' : '加入入庫單'}
                      </button>
                    </div>
                  </div>
               </div>
             </div>
          </div>
        )}

        {/* 庫存清冊列表 */}
        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
            <div className="p-6 bg-slate-50 border-b"><div className="relative max-w-md w-full"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="快速搜尋..." className="w-full pl-12 pr-4 py-3 rounded-xl font-bold" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} /></div></div>
            <table className="w-full text-left">
              <thead><tr className="text-[11px] font-black text-slate-400 uppercase border-b tracking-widest"><th className="px-8 py-4">名稱及規格</th><th className="px-8 py-4 text-center">數量</th><th className="px-8 py-4 text-right">管理</th></tr></thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(i => (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-8 py-5"><div className="item-name-bold">{item.name}</div><div className="text-xs text-slate-500 font-medium tracking-tighter uppercase">{item.spec && <span className="mr-2">規格: {item.spec}</span>}<span className="bg-slate-100 px-1 rounded font-black">{item.itemType === 'EQUIPMENT' ? '安全衛生設備' : '安全衛生類消耗品'}</span></div></td>
                    <td className="px-8 py-5 text-center font-black"><span className={`px-4 py-1.5 rounded-lg text-lg ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>{item.quantity} {item.unit}</span></td>
                    <td className="px-8 py-5 text-right"><button onClick={() => setEditTarget(item)} className="p-2 text-slate-400 hover:text-blue-600"><Edit3 size={16}/></button><button onClick={() => setDeleteTarget({id: item.id, name: item.name})} className="p-2 text-slate-400 hover:text-red-600"><Trash2 size={16}/></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* 歷史與看板 (省略部分顯示內容以保持 App.tsx 精簡，功能維持) */}
        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
             <table className="w-full text-left">
               <thead className="bg-slate-50 text-[11px] font-black text-slate-400 border-b uppercase"><tr><th className="px-8 py-5">時間</th><th className="px-8 py-5">種類</th><th className="px-8 py-5">項目</th><th className="px-8 py-5">單位/人</th><th className="px-8 py-5 text-right">操作</th></tr></thead>
               <tbody className="divide-y divide-slate-100">{logs.map(log => (<tr key={log.id} className="hover:bg-slate-50 transition-colors"><td className="px-8 py-5 text-xs text-slate-400 font-bold">{new Date(log.timestamp).toLocaleString()}</td><td className="px-8 py-5"><span className={`px-3 py-1 rounded-full text-[10px] font-black ${log.type === 'OUT' ? 'bg-blue-100 text-blue-600' : 'bg-emerald-100 text-emerald-600'}`}>{log.type === 'OUT' ? '領用' : '補貨'}</span></td><td className="px-8 py-5 item-name-bold">{log.itemName} (x{log.quantity})</td><td className="px-8 py-5 text-xs font-bold text-slate-600">{log.dept} / {log.person}</td><td className="px-8 py-5 text-right"><button onClick={()=>{ setLastTransactionBatch({id: log.id, dept: log.dept, person: log.person, reason: log.reason, items: [{itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '個', spec: '', itemType: 'CONSUMABLE'}], timestamp: log.timestamp}); setShowPrintModal(true); }} className="text-slate-400 hover:text-blue-600"><Printer size={18}/></button></td></tr>))}</tbody>
             </table>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-10">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6"><div className="bg-white p-8 rounded-3xl border-l-8 border-l-blue-500 shadow-sm"><p className="text-slate-400 text-xs font-black uppercase">耗材管理品項</p><h3 className="text-5xl font-black mt-2 text-slate-900">{dashboardStats.inv.total}</h3></div><div className="bg-white p-8 rounded-3xl border-l-8 border-l-orange-500 shadow-sm"><p className="text-orange-600 text-xs font-black uppercase">庫存預警</p><h3 className="text-5xl font-black text-orange-600 mt-2">{dashboardStats.inv.low}</h3></div></div>
            <div className="bg-slate-900 p-10 rounded-[2.5rem] flex items-center gap-8 shadow-2xl"><div className="flex-1 text-white"><h4 className="text-2xl font-black mb-2 flex items-center gap-3 text-blue-400"><BrainCircuit /> 工安 AI 管理分析</h4><p className="text-slate-400 font-bold">自動掃描庫存水位，生成優化建議。</p></div><button onClick={async () => { setIsAiLoading(true); setAiInsights(await getInventoryInsights(items)); setIsAiLoading(false); }} className="px-10 py-5 bg-blue-600 text-white rounded-2xl font-black text-lg hover:bg-blue-500 transition-all">{isAiLoading ? '分析中...' : '生成營運報表建議'}</button></div>
            {aiInsights && <div className="bg-blue-50 p-10 rounded-[2.5rem] border-2 border-blue-100 text-blue-900 font-bold whitespace-pre-wrap">{aiInsights}</div>}
          </div>
        )}

        {/* Modal: 新增/編輯 */}
        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md z-[300] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-lg p-10 shadow-2xl relative">
              <div className="flex justify-between items-center mb-8"><h3 className="text-2xl font-black text-slate-900">{(editTarget ? '編輯設定' : '新增管理項目')}</h3><button onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="p-2 bg-slate-100 rounded-full text-slate-900"><X size={20}/></button></div>
              <form className="space-y-4" onSubmit={handleSaveItem}>
                <div><label className="block text-xs uppercase mb-1">名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl" defaultValue={editTarget?.name} /></div>
                <div><label className="block text-xs uppercase mb-1">單據類別</label><select name="itemType" className="w-full p-4 rounded-xl" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="EQUIPMENT">安全衛生設備</option><option value="CONSUMABLE">安全衛生類消耗品</option></select></div>
                {((editTarget?.itemGroup === 'MEDICINE') || (activeTab === 'medicine' && !editTarget)) && (
                  <div className="grid grid-cols-2 gap-4">
                    <div><label className="block text-xs uppercase mb-1">購入日期</label><input name="purchaseDate" type="date" className="w-full p-4 rounded-xl" defaultValue={editTarget?.purchaseDate} /></div>
                    <div><label className="block text-xs uppercase mb-1 text-red-600 font-black">效期截止日</label><input name="expiryDate" type="date" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.expiryDate} /></div>
                  </div>
                )}
                <div className="grid grid-cols-2 gap-4"><div><label className="block text-xs uppercase mb-1">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl" defaultValue={editTarget?.unit || '個'} /></div><div><label className="block text-xs uppercase mb-1">警戒水位</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl" defaultValue={editTarget?.minStock || 5} /></div></div>
                <div><label className="block text-xs uppercase mb-1">現有數量</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl" defaultValue={editTarget?.quantity || 0} /></div>
                <div><label className="block text-xs uppercase mb-1">規格/規範</label><input name="spec" type="text" className="w-full p-4 rounded-xl" defaultValue={editTarget?.spec || ''} /></div>
                <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl hover:bg-blue-700">儲存資料設定</button>
              </form>
            </div>
          </div>
        )}

        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[400] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2rem] w-full max-w-[320px] p-8 text-center shadow-2xl">
              <div className="w-16 h-16 bg-red-50 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4"><AlertTriangle size={32} /></div>
              <h3 className="text-xl font-black mb-2 text-slate-900">確認刪除？</h3>
              <p className="text-slate-500 text-sm font-bold mb-8">「{deleteTarget.name}」將被移除。</p>
              <div className="space-y-2"><button onClick={confirmDelete} className="w-full py-3 bg-red-600 text-white rounded-xl font-black">確定刪除</button><button onClick={()=>setDeleteTarget(null)} className="w-full py-3 bg-slate-100 text-slate-400 rounded-xl font-bold">取消</button></div>
            </div>
          </div>
        )}
      </main>

      {/* 列印預覽 Modal (具備 no-print) */}
      {showPrintModal && lastTransactionBatch && (
        <div className="fixed inset-0 bg-slate-900/95 z-[500] flex flex-col items-center justify-start p-10 overflow-y-auto no-print">
          <div className="bg-white rounded-[2.5rem] w-full max-w-5xl p-10 relative shadow-2xl my-4">
            <div className="flex justify-between items-center mb-8 border-b pb-6">
               <div className="flex items-center gap-4"><div className="p-3 bg-emerald-50 text-emerald-600 rounded-full"><CheckCircle2 size={32}/></div><div><h3 className="font-black text-2xl text-slate-900">領用單正式預覽</h3><p className="text-slate-400 font-bold">已同步扣除共 {lastTransactionBatch.items.length} 個項目的庫存</p></div></div>
               <div className="flex gap-4">
                  <button onClick={handlePrint} className="bg-blue-600 text-white px-10 py-4 rounded-xl font-black text-xl shadow-xl hover:scale-105 transition-all">執行列印</button>
                  <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full text-slate-900 hover:bg-slate-200 transition-colors"><X size={24}/></button>
               </div>
            </div>
            <div className="flex justify-center bg-gray-100 p-8 border rounded-2xl"><div className="bg-white shadow-lg p-1"><PrintableForm batch={lastTransactionBatch} /></div></div>
          </div>
        </div>
      )}

      {/* 獨立列印區域 (平常隱藏，列印時唯一顯示) */}
      <div id="print-section" className="hidden">
        {lastTransactionBatch && <PrintableForm batch={lastTransactionBatch} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  Users,
  ShoppingCart,
  CheckCircle2
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v25_batch_items';
const STORAGE_KEY_LOGS = 'safeman_v25_batch_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  // 【功能：計算清單內已佔用的庫存】
  const getReservedQty = (itemId: string) => {
    return basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);
  };

  const addToBasket = () => {
    if (!selectedItemId) {
      window.alert('⚠️ 請先選取項目。');
      return;
    }
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    const currentStock = Number(targetItem.quantity);
    const requestedAmount = Number(inputQty);
    const reservedAmount = getReservedQty(selectedItemId);
    const availableStock = currentStock - reservedAmount;

    if (isNaN(requestedAmount) || requestedAmount <= 0) {
      window.alert('⚠️ 數量輸入不正確。');
      return;
    }

    // 【核心修正：強制攔截警示視窗】
    if (issuanceMode === 'OUT' && requestedAmount > availableStock) {
      window.alert(
        `❌ 庫存警報：領用量超過剩餘庫存！\n\n` +
        `項目名稱：${targetItem.name}\n` +
        `原始庫存：${currentStock} ${targetItem.unit}\n` +
        `待處理清單已佔用：${reservedAmount} ${targetItem.unit}\n` +
        `剩餘可用：${availableStock} ${targetItem.unit}\n\n` +
        `您欲領用：${requestedAmount} ${targetItem.unit}\n\n` +
        `系統提示：申請數量過大，請調整數量或先完成補貨。`
      );
      return; // 強制中斷，不加入清單
    }

    setBasket(prev => [
      ...prev,
      {
        itemId: targetItem.id,
        name: targetItem.name,
        quantity: requestedAmount,
        unit: targetItem.unit,
        spec: targetItem.spec,
        itemType: targetItem.itemType
      }
    ]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) {
      window.alert('⚠️ 待處理清單是空的。');
      return;
    }
    if (issuanceMode === 'OUT' && !inputPerson.trim()) {
      window.alert('❌ 錯誤：領用出庫必須填寫「領用人」。');
      return;
    }

    const timestamp = Date.now();
    const batchId = generateId();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(bItem => {
      updatedItems = updatedItems.map(item => {
        if (item.id === bItem.itemId) {
          const newQty = issuanceMode === 'IN' ? item.quantity + bItem.quantity : item.quantity - bItem.quantity;
          return { ...item, quantity: newQty, lastUpdated: timestamp };
        }
        return item;
      });
      newLogs.push({
        id: generateId() + Math.random().toString(36).substr(2, 4),
        itemId: bItem.itemId,
        itemName: bItem.name,
        type: issuanceMode,
        quantity: bItem.quantity,
        person: issuanceMode === 'OUT' ? inputPerson : '系統管理員',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: issuanceMode === 'OUT' ? inputReason : '批次進貨',
        timestamp: timestamp
      });
    });

    setItems(updatedItems);
    setLogs(prev => [...newLogs, ...prev]);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({
        id: batchId,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: timestamp
      });
      setShowPrintModal(true);
    } else {
      window.alert(`✅ 入庫完成，已更新 ${basket.length} 項物資。`);
      setBasket([]); setInputPerson(''); setInputReason('');
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = {
      name: formData.get('name') as string,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
    };
    if (!data.name.trim()) return window.alert('名稱不可為空');
    if (editTarget) {
      setItems(prev => prev.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i));
      setEditTarget(null);
    } else {
      setItems(prev => [...prev, { id: generateId(), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: Date.now() }]);
      setShowAddModal(false);
    }
  };

  // Add confirmDelete function to fix the error in the modal
  const confirmDelete = () => {
    if (deleteTarget) {
      setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
      setDeleteTarget(null);
    }
  };

  const dashboardStats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    const medItems = items.filter(i => i.itemGroup === 'MEDICINE');
    const today = new Date().toISOString().split('T')[0];
    return {
      inv: { total: invItems.length, low: invItems.filter(i => i.quantity <= i.minStock).length },
      med: { total: medItems.length, low: medItems.filter(i => i.quantity <= i.minStock).length, expired: medItems.filter(i => i.expiryDate && i.expiryDate < today).length }
    };
  }, [items]);

  const PrintableForm = ({ batch }: { batch: { id: string, dept: string, person: string, reason: string, items: BasketItem[], timestamp: number } }) => {
    const date = new Date(batch.timestamp);
    const emptyRows = Array(Math.max(0, 15 - batch.items.length)).fill(null);
    const primaryType = batch.items[0]?.itemType || 'CONSUMABLE';
    return (
      <div className="print-area-content bg-white text-black p-10 w-[210mm] mx-auto relative overflow-hidden" style={{ minHeight: '297mm', color: '#000000' }}>
        <style>{`
          @font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); }
          .print-area-content { font-family: 'StandardKai', serif; font-size: 13pt; line-height: 1.5; }
          .print-area-content table { border-collapse: collapse; width: 100%; border: 2.5px solid #000000; margin-bottom: 20px; }
          .print-area-content th, .print-area-content td { border: 2px solid #000000; padding: 6px 10px; height: 38px; text-align: center; color: #000000 !important; }
          .print-area-content h1 { font-size: 28pt; margin-bottom: 40px; }
        `}</style>
        <div className="absolute top-6 right-10 text-[10pt] font-bold text-right text-slate-400 no-print-item">
           <div>單號：{batch.id}</div>
           <div>領用人：{batch.person}</div>
        </div>
        <h1 className="text-center font-bold tracking-[0.2em] text-black">台灣電力公司電力修護處南部分處</h1>
        <div className="flex justify-center gap-14 mb-10 font-bold text-2xl text-black">
          <label className="flex items-center gap-3">
            <span className="w-7 h-7 border-2 border-black flex items-center justify-center font-black">{primaryType === 'EQUIPMENT' ? 'V' : ''}</span> 安全衛生設備
          </label>
          <label className="flex items-center gap-3">
            <span className="w-7 h-7 border-2 border-black flex items-center justify-center font-black">{primaryType === 'CONSUMABLE' ? 'V' : ''}</span> 安全衛生類消耗品
          </label>
        </div>
        <div className="flex justify-between mb-4 font-bold px-2 text-xl text-black">
          <div>領用單位：<span className="inline-block border-b-2 border-dotted border-black min-w-[220px] text-center">{batch.dept}</span></div>
          <div>中華民國 {date.getFullYear() - 1911} 年 {date.getMonth() + 1} 月 {date.getDate()} 日</div>
        </div>
        <table>
          <thead>
            <tr className="bg-slate-50 font-bold">
              <th className="w-[35%]">名　　　　　稱</th><th className="w-[25%]">規　範（序　號）</th>
              <th className="w-[10%]">單位</th><th className="w-[10%]">數量</th><th className="w-[20%]">備　　　　　註</th>
            </tr>
          </thead>
          <tbody>
            {batch.items.map((item, idx) => (
              <tr key={idx} className="font-bold">
                <td className="text-left leading-tight">{item.name}</td>
                <td className="text-sm font-normal">{item.spec}</td>
                <td>{item.unit}</td>
                <td className="text-2xl">{item.quantity}</td>
                <td className="text-left text-xs font-normal">{idx === 0 ? batch.reason : ''}</td>
              </tr>
            ))}
            {emptyRows.map((_, idx) => <tr key={idx}><td /><td /><td /><td /><td /></tr>)}
          </tbody>
        </table>
        <div className="mt-16 font-bold grid grid-cols-2 gap-x-12 text-black">
          <div className="flex flex-col gap-14"><div>申請部門：</div><div className="flex justify-between w-full px-4 text-base"><div>經辦：</div><div>課長：</div><div>經理：</div></div></div>
          <div className="flex flex-col gap-14"><div>經管部門：</div><div className="flex justify-between w-full px-4 text-base"><div>經辦：</div><div>課長：</div><div>經理：</div></div></div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-slate-100 text-slate-900 font-sans">
      {/* 全域樣式修正：日期選擇器、輸入框顯影 */}
      <style>{`
        input, select, textarea { 
          color: #000000 !important; 
          background-color: #ffffff !important; 
          border: 2px solid #94a3b8 !important; 
          font-weight: 700 !important;
        }
        input[type="date"]::-webkit-calendar-picker-indicator {
          background-color: #ffffff;
          padding: 4px;
          cursor: pointer;
          border-radius: 4px;
          filter: invert(0);
          border: 1px solid #000;
        }
        input:focus, select:focus { border-color: #2563eb !important; outline: none; }
        label { color: #000000 !important; font-weight: 900 !important; }
