             <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
               {/* 1. 挑選項目 */}
               <div className="lg:col-span-2 bg-white p-10 rounded-[2.5rem] shadow-xl border border-slate-100 flex flex-col">
                  <h3 className="text-2xl font-black mb-8 flex items-center gap-3 text-slate-800"><ShoppingCart className="text-blue-500"/> 1. 挑選項目</h3>
                  <div className="flex bg-slate-100 p-1.5 rounded-2xl mb-6">
                    <button onClick={()=>{setIssuanceMode('OUT'); setBasket([]);}} className={`flex-1 py-3 rounded-xl font-black transition-all ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button>
                    <button onClick={()=>{setIssuanceMode('IN'); setBasket([]);}} className={`flex-1 py-3 rounded-xl font-black transition-all ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
                  </div>
                  <div className="flex gap-2 mb-6 text-xs">
                    <button onClick={()=>setIssuanceGroup('INVENTORY')} className={`flex-1 py-3 rounded-xl font-black border-2 transition-all ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-200 text-slate-400'}`}>工安耗材</button>
                    <button onClick={()=>setIssuanceGroup('MEDICINE')} className={`flex-1 py-3 rounded-xl font-black border-2 transition-all ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-200 text-slate-400'}`}>急救藥材</button>
                  </div>
                  <div className="space-y-6">
                    <div>
                      <label className="block text-xs font-black mb-1">選取項目 (顯示剩餘可用)</label>
                      <select className="w-full p-4 border-2 rounded-xl font-bold text-lg" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                        <option value="">-- 請選擇 --</option>
                        {items.filter(i => i.itemGroup === issuanceGroup).map(i => {
                          const reserved = getReservedQty(i.id);
                          const available = i.quantity - reserved;
                          return (
                            <option key={i.id} value={i.id} className={available <= 0 ? 'text-red-400' : ''}>
                              {i.name} (剩餘: {available} {i.unit})
                            </option>
                          );
                        })}
                      </select>
                    </div>
                    <div><label className="block text-xs font-black mb-1">數量</label><input type="number" min="1" className="w-full p-4 border-2 rounded-xl font-bold text-lg" value={inputQty} onChange={e=>setInputQty(e.target.value)}/></div>
                    <button onClick={addToBasket} className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black text-xl hover:bg-black shadow-lg flex items-center justify-center gap-3"><Plus size={20}/> {issuanceMode === 'OUT' ? '加入領用清單' : '加入入庫清單'}</button>
                  </div>
               </div>
               {/* 2. 待處理清單 */}
               <div className="lg:col-span-3 flex flex-col gap-6">
                  <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-slate-100 flex-1 flex flex-col">
                    <div className="flex justify-between items-center mb-6"><h3 className="text-2xl font-black flex items-center gap-3 text-slate-800"><FileText className="text-emerald-500"/> 2. 待處理清單</h3><span className="bg-slate-100 px-4 py-1 rounded-full text-sm font-black">{basket.length} 項目</span></div>
                    <div className="flex-1 overflow-y-auto border-2 border-dashed border-slate-100 rounded-2xl mb-6 min-h-[200px]">
                       {basket.length > 0 ? (
                         <table className="w-full text-left">
                           <thead><tr className="text-[10px] font-black text-slate-400 uppercase border-b bg-slate-50"><th className="px-6 py-3">物資名稱</th><th className="px-6 py-3 text-center">數量</th><th className="px-6 py-3 text-right">移除</th></tr></thead>
                           <tbody className="divide-y divide-slate-50">{basket.map((bItem, idx) => (<tr key={idx} className="hover:bg-slate-50 transition-colors"><td className="px-6 py-4 font-black text-slate-800">{bItem.name}</td><td className="px-6 py-4 text-center font-black text-blue-600">{bItem.quantity} {bItem.unit}</td><td className="px-6 py-4 text-right"><button onClick={()=>setBasket(prev => prev.filter((_, i) => i !== idx))} className="text-slate-300 hover:text-red-500"><X size={18}/></button></td></tr>))}</tbody>
                         </table>
                       ) : (<div className="h-full flex flex-col items-center justify-center text-slate-300 p-10 text-center"><ShoppingCart size={48} className="mb-4 opacity-20" /><p className="font-bold">目前清單內尚無項目</p></div>)}
                    </div>
                    <div className="space-y-4">
                      {issuanceMode === 'OUT' && (
                        <div className="grid grid-cols-2 gap-4">
                          <div><label className="block text-xs font-black mb-1">領用單位</label><select className="w-full p-3 border-2 rounded-xl font-bold" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>{DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}</select></div>
                          <div><label className="block text-xs font-black mb-1">領用人 *</label><input type="text" className="w-full p-3 border-2 rounded-xl font-bold" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div>
                          <div className="col-span-2"><label className="block text-xs font-black mb-1">用途/備註</label><input type="text" className="w-full p-3 border-2 rounded-xl font-bold" value={inputReason} onChange={e=>setInputReason(e.target.value)}/></div>
                        </div>
                      )}
                      <button onClick={processIssuance} disabled={basket.length === 0} className={`w-full py-6 rounded-2xl font-black text-white text-3xl shadow-xl transition-all active:scale-95 disabled:opacity-30 ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>
