                    <td className="px-8 py-5 text-center font-black"><span className={`px-4 py-1.5 rounded-lg text-lg ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>{item.quantity} {item.unit}</span></td>
                    <td className="px-8 py-5 text-right"><button onClick={() => setEditTarget(item)} className="p-2 text-slate-400 hover:text-blue-600"><Edit3 size={16}/></button><button onClick={() => setDeleteTarget({id: item.id, name: item.name})} className="p-2 text-slate-400 hover:text-red-600"><Trash2 size={16}/></button></td>
                  </tr>
