        {/* 歷史與看板 (省略部分顯示內容以保持 App.tsx 精簡，功能維持) */}
        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
             <table className="w-full text-left">
               <thead className="bg-slate-50 text-[11px] font-black text-slate-400 border-b uppercase"><tr><th className="px-8 py-5">時間</th><th className="px-8 py-5">種類</th><th className="px-8 py-5">項目</th><th className="px-8 py-5">單位/人</th><th className="px-8 py-5 text-right">操作</th></tr></thead>
               <tbody className="divide-y divide-slate-100">{logs.map(log => (<tr key={log.id} className="hover:bg-slate-50 transition-colors"><td className="px-8 py-5 text-xs text-slate-400 font-bold">{new Date(log.timestamp).toLocaleString()}</td><td className="px-8 py-5"><span className={`px-3 py-1 rounded-full text-[10px] font-black ${log.type === 'OUT' ? 'bg-blue-100 text-blue-600' : 'bg-emerald-100 text-emerald-600'}`}>{log.type === 'OUT' ? '領用' : '補貨'}</span></td><td className="px-8 py-5 item-name-bold">{log.itemName} (x{log.quantity})</td><td className="px-8 py-5 text-xs font-bold text-slate-600">{log.dept} / {log.person}</td><td className="px-8 py-5 text-right"><button onClick={()=>{ setLastTransactionBatch({id: log.id, dept: log.dept, person: log.person, reason: log.reason, items: [{itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '個', spec: '', itemType: 'CONSUMABLE'}], timestamp: log.timestamp}); setShowPrintModal(true); }} className="text-slate-400 hover:text-blue-600"><Printer size={18}/></button></td></tr>))}</tbody>
             </table>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-10">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6"><div className="bg-white p-8 rounded-3xl border-l-8 border-l-blue-500 shadow-sm"><p className="text-slate-400 text-xs font-black uppercase">耗材管理品項</p><h3 className="text-5xl font-black mt-2 text-slate-900">{dashboardStats.inv.total}</h3></div><div className="bg-white p-8 rounded-3xl border-l-8 border-l-orange-500 shadow-sm"><p className="text-orange-600 text-xs font-black uppercase">庫存預警</p><h3 className="text-5xl font-black text-orange-600 mt-2">{dashboardStats.inv.low}</h3></div></div>
            <div className="bg-slate-900 p-10 rounded-[2.5rem] flex items-center gap-8 shadow-2xl"><div className="flex-1 text-white"><h4 className="text-2xl font-black mb-2 flex items-center gap-3 text-blue-400"><BrainCircuit /> 工安 AI 管理分析</h4><p className="text-slate-400 font-bold">自動掃描庫存水位，生成優化建議。</p></div><button onClick={async () => { setIsAiLoading(true); setAiInsights(await getInventoryInsights(items)); setIsAiLoading(false); }} className="px-10 py-5 bg-blue-600 text-white rounded-2xl font-black text-lg hover:bg-blue-500 transition-all">{isAiLoading ? '分析中...' : '生成營運報表建議'}</button></div>
            {aiInsights && <div className="bg-blue-50 p-10 rounded-[2.5rem] border-2 border-blue-100 text-blue-900 font-bold whitespace-pre-wrap">{aiInsights}</div>}
          </div>
        )}

        {/* Modal: 新增/編輯 */}
        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md z-[300] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-lg p-10 shadow-2xl relative">
              <div className="flex justify-between items-center mb-8"><h3 className="text-2xl font-black text-slate-900">{(editTarget ? '編輯設定' : '新增管理項目')}</h3><button onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="p-2 bg-slate-100 rounded-full text-slate-900"><X size={20}/></button></div>
              <form className="space-y-4" onSubmit={handleSaveItem}>
                <div><label className="block text-xs uppercase mb-1">名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl" defaultValue={editTarget?.name} /></div>
                <div><label className="block text-xs uppercase mb-1">單據類別</label><select name="itemType" className="w-full p-4 rounded-xl" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="EQUIPMENT">安全衛生設備</option><option value="CONSUMABLE">安全衛生類消耗品</option></select></div>
                {((editTarget?.itemGroup === 'MEDICINE') || (activeTab === 'medicine' && !editTarget)) && (
                  <div className="grid grid-cols-2 gap-4">
                    <div><label className="block text-xs uppercase mb-1">購入日期</label><input name="purchaseDate" type="date" className="w-full p-4 rounded-xl" defaultValue={editTarget?.purchaseDate} /></div>
                    <div><label className="block text-xs uppercase mb-1 text-red-600 font-black">效期截止日</label><input name="expiryDate" type="date" className="w-full p-4 rounded-xl font-bold" defaultValue={editTarget?.expiryDate} /></div>
                  </div>
                )}
                <div className="grid grid-cols-2 gap-4"><div><label className="block text-xs uppercase mb-1">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl" defaultValue={editTarget?.unit || '個'} /></div><div><label className="block text-xs uppercase mb-1">警戒水位</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl" defaultValue={editTarget?.minStock || 5} /></div></div>
                <div><label className="block text-xs uppercase mb-1">現有數量</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl" defaultValue={editTarget?.quantity || 0} /></div>
                <div><label className="block text-xs uppercase mb-1">規格/規範</label><input name="spec" type="text" className="w-full p-4 rounded-xl" defaultValue={editTarget?.spec || ''} /></div>
                <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl hover:bg-blue-700">儲存資料設定</button>
              </form>
            </div>
          </div>
        )}

        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[400] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2rem] w-full max-w-[320px] p-8 text-center shadow-2xl">
              <div className="w-16 h-16 bg-red-50 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4"><AlertTriangle size={32} /></div>
              <h3 className="text-xl font-black mb-2 text-slate-900">確認刪除？</h3>
              <p className="text-slate-500 text-sm font-bold mb-8">「{deleteTarget.name}」將被移除。</p>
              <div className="space-y-2"><button onClick={confirmDelete} className="w-full py-3 bg-red-600 text-white rounded-xl font-black">確定刪除</button><button onClick={()=>setDeleteTarget(null)} className="w-full py-3 bg-slate-100 text-slate-400 rounded-xl font-bold">取消</button></div>
            </div>
          </div>
        )}
      </main>

      {/* 列印預覽 Modal (具備 no-print) */}
      {showPrintModal && lastTransactionBatch && (
        <div className="fixed inset-0 bg-slate-900/95 z-[500] flex flex-col items-center justify-start p-10 overflow-y-auto no-print">
          <div className="bg-white rounded-[2.5rem] w-full max-w-5xl p-10 relative shadow-2xl my-4">
            <div className="flex justify-between items-center mb-8 border-b pb-6">
               <div className="flex items-center gap-4"><div className="p-3 bg-emerald-50 text-emerald-600 rounded-full"><CheckCircle2 size={32}/></div><div><h3 className="font-black text-2xl text-slate-900">領用單正式預覽</h3><p className="text-slate-400 font-bold">已同步扣除共 {lastTransactionBatch.items.length} 個項目的庫存</p></div></div>
               <div className="flex gap-4">
                  <button onClick={handlePrint} className="bg-blue-600 text-white px-10 py-4 rounded-xl font-black text-xl shadow-xl hover:scale-105 transition-all">執行列印</button>
                  <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full text-slate-900 hover:bg-slate-200 transition-colors"><X size={24}/></button>
               </div>
            </div>
            <div className="flex justify-center bg-gray-100 p-8 border rounded-2xl"><div className="bg-white shadow-lg p-1"><PrintableForm batch={lastTransactionBatch} /></div></div>
          </div>
        </div>
      )}

      {/* 獨立列印區域 (平常隱藏，列印時唯一顯示) */}
      <div id="print-section" className="hidden">
        {lastTransactionBatch && <PrintableForm batch={lastTransactionBatch} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  CheckCircle2
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v26_items';
const STORAGE_KEY_LOGS = 'safeman_v26_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const getReservedQty = (itemId: string) => {
    return basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);
  };

  const addToBasket = () => {
    if (!selectedItemId) {
      window.alert('⚠️ 請先選取項目。');
      return;
    }
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    const currentStock = Number(targetItem.quantity);
    const requestedAmount = Number(inputQty);
    const reservedAmount = getReservedQty(selectedItemId);
    const availableStock = currentStock - reservedAmount;

    if (isNaN(requestedAmount) || requestedAmount <= 0) {
      window.alert('⚠️ 請輸入有效的數量。');
      return;
    }

    if (issuanceMode === 'OUT' && requestedAmount > availableStock) {
      window.alert(
        `❌ 庫存不足警示！\n\n` +
        `項目：${targetItem.name}\n` +
        `庫存總量：${currentStock} ${targetItem.unit}\n` +
        `清單中已佔用：${reservedAmount} ${targetItem.unit}\n` +
        `剩餘可用量：${availableStock} ${targetItem.unit}\n\n` +
        `無法領用 ${requestedAmount} ${targetItem.unit}。`
      );
      return;
    }

    setBasket(prev => [
      ...prev,
      {
        itemId: targetItem.id,
        name: targetItem.name,
        quantity: requestedAmount,
        unit: targetItem.unit,
        spec: targetItem.spec,
        itemType: targetItem.itemType
      }
    ]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) {
      window.alert('⚠️ 待處理清單是空的。');
      return;
    }
    if (issuanceMode === 'OUT' && !inputPerson.trim()) {
      window.alert('❌ 請填寫領用人姓名。');
      return;
    }

    const timestamp = Date.now();
    const batchId = generateId();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(bItem => {
      updatedItems = updatedItems.map(item => {
        if (item.id === bItem.itemId) {
          const newQty = issuanceMode === 'IN' ? item.quantity + bItem.quantity : item.quantity - bItem.quantity;
          return { ...item, quantity: newQty, lastUpdated: timestamp };
        }
        return item;
      });
      newLogs.push({
        id: generateId() + Math.random().toString(36).substr(2, 4),
        itemId: bItem.itemId,
        itemName: bItem.name,
        type: issuanceMode,
        quantity: bItem.quantity,
        person: issuanceMode === 'OUT' ? inputPerson : '管理員',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: issuanceMode === 'OUT' ? inputReason : '批次進貨',
        timestamp: timestamp
      });
    });

    setItems(updatedItems);
    setLogs(prev => [...newLogs, ...prev]);

    if (issuanceMode === 'OUT') {
      const batchData = {
        id: batchId,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: timestamp
      };
      setLastTransactionBatch(batchData);
      setShowPrintModal(true);
