            <div className="grid grid-cols-1 md:grid-cols-2 gap-6"><div className="bg-white p-8 rounded-3xl border-l-8 border-l-blue-500 shadow-sm"><p className="text-slate-400 text-xs font-black uppercase tracking-widest">工安耗材總品項</p><h3 className="text-5xl font-black mt-2 text-slate-900">{dashboardStats.inv.total}</h3></div><div className="bg-white p-8 rounded-3xl border-l-8 border-l-orange-500 shadow-sm"><p className="text-orange-600 text-xs font-black uppercase tracking-widest">低水位警報中</p><h3 className="text-5xl font-black text-orange-600 mt-2">{dashboardStats.inv.low}</h3></div></div>
            <div className="bg-slate-900 p-10 rounded-[2.5rem] flex items-center gap-8 shadow-2xl"><div className="flex-1 text-white"><h4 className="text-2xl font-black mb-2 flex items-center gap-3 text-blue-400"><BrainCircuit /> 工安 AI 採購助手</h4><p className="text-slate-400 font-bold">自動分析過往領用頻率，並對低庫存品項給予專業建議。</p></div><button onClick={async () => { setIsAiLoading(true); setAiInsights(await getInventoryInsights(items)); setIsAiLoading(false); }} className="px-10 py-5 bg-blue-600 text-white rounded-2xl font-black text-lg hover:bg-blue-500 transition-all">{isAiLoading ? '分析中...' : '生成最新建議'}</button></div>
            {aiInsights && <div className="bg-blue-50 p-10 rounded-[2.5rem] border-2 border-blue-100 text-blue-900 font-bold whitespace-pre-wrap">{aiInsights}</div>}
          </div>
        )}

        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md z-[300] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-lg p-10 shadow-2xl">
              <div className="flex justify-between items-center mb-8"><h3 className="text-2xl font-black text-slate-900">{(editTarget ? '編輯設定' : '新增管理項目')}</h3><button onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="p-2 bg-slate-100 rounded-full text-slate-900 hover:scale-110 transition-transform"><X size={20}/></button></div>
              <form className="space-y-4" onSubmit={handleSaveItem}>
                <div><label className="block text-xs font-black mb-1 uppercase tracking-widest text-slate-400">項目名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl border-2 border-slate-300" defaultValue={editTarget?.name} /></div>
                <div className="grid grid-cols-2 gap-4">
                  <div><label className="block text-xs font-black mb-1 uppercase tracking-widest text-slate-400">類別</label><select name="itemType" className="w-full p-4 rounded-xl border-2 border-slate-300" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="EQUIPMENT">安全衛生設備</option><option value="CONSUMABLE">安全衛生類消耗品</option></select></div>
                  <div><label className="block text-xs font-black mb-1 uppercase tracking-widest text-slate-400">規格</label><input name="spec" type="text" className="w-full p-4 rounded-xl border-2 border-slate-300" defaultValue={editTarget?.spec || ''} /></div>
                </div>
                {((editTarget?.itemGroup === 'MEDICINE') || (activeTab === 'medicine' && !editTarget)) && (
                  <div className="grid grid-cols-2 gap-4">
                    <div><label className="block text-xs font-black mb-1 uppercase tracking-widest text-slate-400">購入日期</label><input name="purchaseDate" type="date" className="w-full" defaultValue={editTarget?.purchaseDate} /></div>
                    <div><label className="block text-xs font-black mb-1 uppercase tracking-widest text-red-500">效期截止日</label><input name="expiryDate" type="date" className="w-full" defaultValue={editTarget?.expiryDate} /></div>
                  </div>
                )}
                <div className="grid grid-cols-2 gap-4">
                  <div><label className="block text-xs font-black mb-1 uppercase tracking-widest text-slate-400">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl border-2 border-slate-300" defaultValue={editTarget?.unit || '個'} /></div>
                  <div><label className="block text-xs font-black mb-1 uppercase tracking-widest text-slate-400">警戒水位</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl border-2 border-slate-300" defaultValue={editTarget?.minStock || 5} /></div>
                </div>
                <div><label className="block text-xs font-black mb-1 uppercase tracking-widest text-slate-400">現有數量</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl border-2 border-slate-300" defaultValue={editTarget?.quantity || 0} /></div>
                <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl hover:bg-blue-700 active:scale-95 transition-all mt-4">儲存並建立資料</button>
              </form>
            </div>
          </div>
        )}

        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[400] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2rem] w-full max-w-[320px] p-8 text-center shadow-2xl"><div className="w-16 h-16 bg-red-50 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4"><AlertTriangle size={32} /></div><h3 className="text-xl font-black mb-2 text-slate-900">確定移除項目？</h3><p className="text-slate-500 text-sm font-bold mb-8">「{deleteTarget.name}」的所有紀錄將會消失。</p><div className="space-y-2"><button onClick={confirmDelete} className="w-full py-3 bg-red-600 text-white rounded-xl font-black">確定刪除</button><button onClick={()=>setDeleteTarget(null)} className="w-full py-3 bg-slate-100 text-slate-400 rounded-xl font-bold">取消</button></div></div>
          </div>
        )}

        {/* 列印預覽 Modal */}
        {showPrintModal && lastTransactionBatch && (
          <div className="fixed inset-0 bg-slate-900/95 z-[500] flex flex-col items-center justify-start p-10 overflow-y-auto">
            <div className="bg-white rounded-[2.5rem] w-full max-w-5xl p-10 relative shadow-2xl my-4">
              <div className="flex justify-between items-center mb-8 border-b pb-6">
                 <div className="flex items-center gap-4"><div className="p-3 bg-emerald-50 text-emerald-600 rounded-full"><CheckCircle2 size={32}/></div><div><h3 className="font-black text-2xl text-slate-900">單據處理完成</h3><p className="text-slate-400 font-bold">庫存已同步扣除，請確認預覽並執行列印。</p></div></div>
                 <div className="flex gap-4">
                    <button onClick={handlePrint} className="bg-blue-600 text-white px-10 py-4 rounded-xl font-black text-xl shadow-xl hover:scale-105 transition-all flex items-center gap-2"><Printer size={24}/> 立即列印</button>
                    <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-full text-slate-900 hover:bg-slate-200 transition-colors"><X size={24}/></button>
                 </div>
              </div>
              <div className="bg-slate-100 p-10 rounded-3xl border shadow-inner flex justify-center">
                 <div className="bg-white shadow-2xl p-4 scale-90 origin-top">
                    {/* 預覽元件 */}
                    <div style={{width: '210mm', minHeight: '297mm', padding: '10mm', color: 'black', background: 'white', fontStyle: 'serif'}}>
                       <h1 style={{textAlign: 'center', fontSize: '24pt', fontWeight: 'bold'}}>台灣電力公司電力修護處南部分處</h1>
                       <div style={{display: 'flex', justifyContent: 'center', gap: '20px', fontSize: '16pt', marginBottom: '20px'}}>
                          <label><span style={{border: '2px solid black', width: '20px', height: '20px', display: 'inline-block', textAlign: 'center', lineHeight: '20px'}}>{lastTransactionBatch.items[0]?.itemType === 'EQUIPMENT' ? 'V' : ''}</span> 安全衛生設備</label>
                          <label><span style={{border: '2px solid black', width: '20px', height: '20px', display: 'inline-block', textAlign: 'center', lineHeight: '20px'}}>{lastTransactionBatch.items[0]?.itemType === 'CONSUMABLE' ? 'V' : ''}</span> 安全衛生類消耗品</label>
                       </div>
                       <table style={{width: '100%', borderCollapse: 'collapse', border: '2px solid black'}}>
                          <thead><tr style={{background: '#eee'}}><th style={{border: '1.5px solid black', padding: '5px'}}>項目</th><th style={{border: '1.5px solid black', padding: '5px'}}>單位</th><th style={{border: '1.5px solid black', padding: '5px'}}>數量</th><th style={{border: '1.5px solid black', padding: '5px'}}>備註</th></tr></thead>
                          <tbody>{lastTransactionBatch.items.map((it, i) => (<tr key={i}><td style={{border: '1.5px solid black', padding: '8px'}}>{it.name}</td><td style={{border: '1.5px solid black', textAlign: 'center'}}>{it.unit}</td><td style={{border: '1.5px solid black', textAlign: 'center', fontWeight: 'bold'}}>{it.quantity}</td><td style={{border: '1.5px solid black', padding: '5px'}}>{lastTransactionBatch.reason}</td></tr>))}</tbody>
                       </table>
                       <p style={{marginTop: '20px', fontWeight: 'bold'}}>單號：${lastTransactionBatch.id}</p>
                    </div>
                 </div>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  CheckCircle2
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v27_final_items';
const STORAGE_KEY_LOGS = 'safeman_v27_final_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  // 用於列印的隱藏 Iframe
  const printFrameRef = useRef<HTMLIFrameElement>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const getReservedQty = (itemId: string) => {
    return basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);
  };

  // 即時計算當前選中項目的可用數量與警示狀態
  const currentAvailable = useMemo(() => {
    if (!selectedItemId) return 0;
    const item = items.find(i => i.id === selectedItemId);
    if (!item) return 0;
    return item.quantity - getReservedQty(selectedItemId);
  }, [selectedItemId, items, basket]);

  const isQtyOver = useMemo(() => {
    if (issuanceMode === 'IN') return false;
    const qty = Number(inputQty);
    return !isNaN(qty) && qty > currentAvailable;
  }, [inputQty, currentAvailable, issuanceMode]);

  const addToBasket = () => {
    if (!selectedItemId || isQtyOver) return;
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;

    const qty = Number(inputQty);
    if (isNaN(qty) || qty <= 0) return;

    setBasket(prev => [
      ...prev,
      {
        itemId: targetItem.id,
        name: targetItem.name,
        quantity: qty,
        unit: targetItem.unit,
        spec: targetItem.spec,
        itemType: targetItem.itemType
      }
    ]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    if (issuanceMode === 'OUT' && !inputPerson.trim()) {
      window.alert('⚠️ 請填寫領用人姓名。');
      return;
    }

    const timestamp = Date.now();
    const batchId = generateId();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(bItem => {
      updatedItems = updatedItems.map(item => {
        if (item.id === bItem.itemId) {
          const newQty = issuanceMode === 'IN' ? item.quantity + bItem.quantity : item.quantity - bItem.quantity;
          return { ...item, quantity: newQty, lastUpdated: timestamp };
        }
        return item;
      });
      newLogs.push({
        id: generateId() + Math.random().toString(36).substr(2, 4),
        itemId: bItem.itemId,
        itemName: bItem.name,
        type: issuanceMode,
        quantity: bItem.quantity,
        person: issuanceMode === 'OUT' ? inputPerson : '管理員',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: issuanceMode === 'OUT' ? inputReason : '批次進貨',
        timestamp: timestamp
      });
    });

    setItems(updatedItems);
    setLogs(prev => [...newLogs, ...prev]);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({
        id: batchId,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: timestamp
      });
      setShowPrintModal(true);
    } else {
      window.alert(`✅ 入庫完成。`);
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  /**
   * 【核心修復：隱藏 Iframe 列印法】
   */
  const handlePrint = () => {
    if (!lastTransactionBatch || !printFrameRef.current) return;

    const doc = printFrameRef.current.contentDocument;
    if (!doc) return;

    const date = new Date(lastTransactionBatch.timestamp);
    const primaryType = lastTransactionBatch.items[0]?.itemType || 'CONSUMABLE';
    const rows = lastTransactionBatch.items.map(item => `
      <tr>
        <td style="text-align:left;">${item.name}</td>
        <td>${item.spec || ''}</td>
        <td>${item.unit}</td>
        <td style="font-size:20pt; font-weight:bold;">${item.quantity}</td>
        <td>${lastTransactionBatch.reason}</td>
      </tr>
    `).join('');
    const emptyRowsCount = Math.max(0, 15 - lastTransactionBatch.items.length);
    const emptyRows = Array(emptyRowsCount).fill('<tr><td>&nbsp;</td><td></td><td></td><td></td><td></td></tr>').join('');

    doc.open();
    doc.write(`
      <html>
        <head>
          <style>
            @font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); }
            body { font-family: 'StandardKai', serif; padding: 40px; color: black; line-height: 1.2; }
            h1 { text-align: center; font-size: 26pt; margin-bottom: 30px; letter-spacing: 5px; }
            .type-labels { display: flex; justify-content: center; gap: 40px; font-size: 16pt; font-weight: bold; margin-bottom: 25px; }
            .checkbox { width: 22px; height: 22px; border: 2.5px solid black; display: inline-flex; align-items: center; justify-content: center; margin-right: 8px; vertical-align: middle; }
            .header-info { display: flex; justify-content: space-between; font-size: 15pt; font-weight: bold; margin-bottom: 12px; }
            table { width: 100%; border-collapse: collapse; border: 2.5px solid black; }
            th, td { border: 1.5px solid black; padding: 10px; text-align: center; height: 35px; }
            th { background: #f2f2f2; font-size: 13pt; }
            .footer { margin-top: 50px; display: grid; grid-template-cols: 1fr 1fr; gap: 40px; }
            .sig-section { font-weight: bold; font-size: 14pt; }
            .sig-row { display: flex; justify-content: space-between; margin-top: 45px; font-size: 12pt; }
            @media print { .no-print { display: none; } }
          </style>
        </head>
        <body>
          <div style="text-align:right; font-size: 10pt; color: #666;">單號：${lastTransactionBatch.id}</div>
          <h1>台灣電力公司電力修護處南部分處</h1>
          <div class="type-labels">
            <div><span class="checkbox">${primaryType === 'EQUIPMENT' ? 'V' : ''}</span>安全衛生設備</div>
            <div><span class="checkbox">${primaryType === 'CONSUMABLE' ? 'V' : ''}</span>安全衛生類消耗品</div>
          </div>
          <div class="header-info">
            <div>領用單位：<span style="border-bottom: 2px dotted black; min-width: 220px; display: inline-block; text-align: center;">${lastTransactionBatch.dept}</span></div>
            <div>中華民國 ${date.getFullYear() - 1911} 年 ${date.getMonth() + 1} 月 ${date.getDate()} 日</div>
          </div>
          <table>
            <thead>
              <tr><th style="width:35%">名稱</th><th style="width:25%">規範</th><th style="width:10%">單位</th><th style="width:10%">數量</th><th style="width:20%">備註</th></tr>
            </thead>
            <tbody>${rows}${emptyRows}</tbody>
          </table>
          <div class="footer">
            <div class="sig-section">申請部門：<div class="sig-row"><span>經辦：</span><span>課長：</span><span>經理：</span></div></div>
            <div class="sig-section">經管部門：<div class="sig-row"><span>經辦：</span><span>課長：</span><span>經理：</span></div></div>
          </div>
        </body>
      </html>
    `);
    doc.close();

    setTimeout(() => {
      printFrameRef.current?.contentWindow?.focus();
      printFrameRef.current?.contentWindow?.print();
    }, 500);
  };

  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = {
      name: formData.get('name') as string,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
    };
    if (!data.name.trim()) return window.alert('名稱不可為空');
    if (editTarget) {
      setItems(prev => prev.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i));
      setEditTarget(null);
    } else {
      setItems(prev => [...prev, { id: generateId(), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: Date.now() }]);
      setShowAddModal(false);
    }
  };

  const confirmDelete = () => {
    if (deleteTarget) {
      setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
      setDeleteTarget(null);
    }
  };

  const dashboardStats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    const medItems = items.filter(i => i.itemGroup === 'MEDICINE');
    const today = new Date().toISOString().split('T')[0];
    return {
      inv: { total: invItems.length, low: invItems.filter(i => i.quantity <= i.minStock).length },
      med: { total: medItems.length, low: medItems.filter(i => i.quantity <= i.minStock).length, expired: medItems.filter(i => i.expiryDate && i.expiryDate < today).length }
    };
  }, [items]);

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900 font-sans">
      <style>{`
        /* 【全域強化顯影】 */
        input, select, textarea { 
          color: #000000 !important; 
          background-color: #ffffff !important; 
          border: 2px solid #cbd5e1 !important;
          font-weight: 600 !important;
        }
        /* 【日期選擇器修復】 */
        input[type="date"] { position: relative; min-height: 2.8rem; }
        input[type="date"]::-webkit-calendar-picker-indicator {
          background-color: #e2e8f0;
          padding: 3px;
          cursor: pointer;
          border-radius: 4px;
          border: 1px solid #000;
        }
        /* 【低水位動畫】 */
        .low-pulse { animation: alert-red 1.5s infinite; }
        @keyframes alert-red { 0%, 100% { color: #dc2626; } 50% { color: #ef4444; opacity: 0.6; } }
      `}</style>

      {/* 隱藏的列印框架 */}
      <iframe ref={printFrameRef} className="hidden" title="print-frame" />

      <aside className="w-72 bg-slate-900 text-white p-8 flex flex-col shrink-0 shadow-2xl z-20">
        <div className="flex items-center gap-3 mb-10">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg"><Package size={22}/></div>
          <div><h1 className="font-black text-lg leading-tight text-white">工安管理系統</h1><p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">V27 FINAL FIX</p></div>
        </div>
        <nav className="flex-1 space-y-1.5">
          {[
            { id: 'inventory', label: '工安耗材管理', icon: Package },
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
            { id: 'issuance', label: '領用補貨作業', icon: FileText },
            { id: 'history', label: '歷史異動日誌', icon: History },
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard },
