              <div className="flex bg-slate-100 p-1 rounded-xl mb-6">
                <button onClick={()=>{setIssuanceMode('OUT'); setBasket([]);}} className={`flex-1 py-3 rounded-lg font-black transition-all ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button>
                <button onClick={()=>{setIssuanceMode('IN'); setBasket([]);}} className={`flex-1 py-3 rounded-lg font-black transition-all ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
              </div>
              <div className="space-y-6">
                <div>
                  <label className="block text-[10px] font-black mb-2 uppercase tracking-widest text-slate-400">來源類別</label>
                  <div className="flex gap-2">
                    <button onClick={()=>setIssuanceGroup('INVENTORY')} className={`flex-1 py-3 rounded-xl font-black border-2 transition-all ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-200 text-slate-400'}`}>工安耗材</button>
                    <button onClick={()=>setIssuanceGroup('MEDICINE')} className={`flex-1 py-3 rounded-xl font-black border-2 transition-all ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-200 text-slate-400'}`}>急救藥材</button>
                  </div>
                </div>
                <div>
                  <label className="block text-[10px] font-black mb-2 uppercase tracking-widest text-slate-400">物資名稱</label>
                  <select className="w-full p-4 rounded-xl text-lg font-bold" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                    <option value="">-- 請選擇 --</option>
                    {items.filter(i => i.itemGroup === issuanceGroup).map(i => {
                      const avail = i.quantity - getReservedQty(i.id);
                      // 【優化】入庫不顯示剩餘可用，領用才顯示
                      const label = issuanceMode === 'OUT' 
                        ? `${i.name} (剩餘: ${avail} ${i.unit})`
                        : `${i.name} (庫存: ${i.quantity} ${i.unit})`;
                      return <option key={i.id} value={i.id} className={avail <= 0 && issuanceMode === 'OUT' ? 'text-red-400' : ''}>{label}</option>;
                    })}
                  </select>
                </div>
                <div>
                  <label className="block text-[10px] font-black mb-2 uppercase tracking-widest text-slate-400">輸入數量</label>
                  <input type="number" min="1" className="w-full p-4 rounded-xl text-xl font-bold" value={inputQty} onChange={e=>setInputQty(e.target.value)}/>
