                  {isQtyOver && <p className="text-red-600 text-xs font-black mt-2 flex items-center gap-1"><AlertTriangle size={14}/> 數量超過庫存可用餘額 ({currentAvailable})</p>}
                </div>
                <button onClick={addToBasket} disabled={!selectedItemId || isQtyOver} className={`w-full py-5 rounded-2xl font-black text-xl flex items-center justify-center gap-2 shadow-lg transition-all ${!selectedItemId || isQtyOver ? 'bg-slate-200 text-slate-400 cursor-not-allowed' : 'bg-slate-900 text-white hover:bg-black active:scale-95'}`}><Plus size={20}/> 加入清單</button>
              </div>
            </div>

            <div className="lg:col-span-3 bg-white p-8 rounded-[2rem] shadow-xl border border-slate-200 flex flex-col">
              <div className="flex justify-between items-center mb-6"><h3 className="text-xl font-black flex items-center gap-2"><FileText className="text-emerald-500"/> 2. 待處理清單</h3><span className="bg-slate-100 text-slate-600 px-4 py-1 rounded-full text-xs font-black uppercase tracking-widest">{basket.length} 項目</span></div>
              <div className="flex-1 overflow-y-auto border-2 border-dashed border-slate-100 rounded-3xl p-2 mb-6 min-h-[250px] bg-slate-50/50">
                {basket.length > 0 ? (
                  <table className="w-full text-left">
                    <thead><tr className="text-[10px] font-black text-slate-400 border-b uppercase"><th className="px-4 py-3">名稱規格</th><th className="px-4 py-3 text-center">數量</th><th className="px-4 py-3 text-right">管理</th></tr></thead>
                    <tbody className="divide-y">
                      {basket.map((b, idx) => (
                        <tr key={idx} className="hover:bg-white transition-colors">
                          {/* 【核心修復：強制深色文字】 */}
                          <td className="px-4 py-4 font-bold text-slate-900 text-sm">{b.name}</td>
                          <td className="px-4 py-4 text-center font-black text-blue-700 text-lg">{b.quantity} {b.unit}</td>
                          <td className="px-4 py-4 text-right"><button onClick={()=>setBasket(prev => prev.filter((_, i) => i !== idx))} className="text-slate-300 hover:text-red-500"><X size={18}/></button></td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                ) : (<div className="h-full flex flex-col items-center justify-center text-slate-300 font-bold opacity-40"><ShoppingCart size={40} className="mb-2"/><p>尚未加入任何項目</p></div>)}
              </div>
              {issuanceMode === 'OUT' && (
                <div className="grid grid-cols-2 gap-4 mb-6">
                  <div><label className="block text-[10px] font-black mb-1 uppercase tracking-widest text-slate-400">領用單位</label><select className="w-full p-3 rounded-xl text-sm font-bold" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>{DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}</select></div>
