                  <div className="col-span-2"><label className="block text-[10px] font-black mb-1 uppercase tracking-widest text-slate-400">用途備註</label><input type="text" placeholder="例：定期發放、現場施工..." className="w-full p-3 rounded-xl text-sm font-bold placeholder:text-slate-300" value={inputReason} onChange={e=>setInputReason(e.target.value)}/></div>
                </div>
              )}
              <button onClick={processIssuance} disabled={basket.length === 0} className={`w-full py-6 rounded-2xl font-black text-3xl shadow-2xl transition-all active:scale-95 disabled:opacity-30 text-white ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>
                {issuanceMode === 'OUT' ? '確認領用單' : '確認入庫'}
              </button>
            </div>
          </div>
        )}

        {/* 庫存清冊列表 */}
        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
            <div className="p-6 bg-slate-50/50 border-b flex justify-between items-center"><div className="relative max-w-md w-full"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="搜尋項目名稱..." className="w-full pl-12 pr-4 py-3 rounded-xl border border-slate-200 font-bold" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} /></div></div>
            <table className="w-full text-left">
              <thead><tr className="text-[10px] font-black text-slate-400 uppercase border-b bg-slate-50 tracking-widest"><th className="px-8 py-5">名稱及規格</th><th className="px-8 py-5 text-center">庫存水位</th><th className="px-8 py-5 text-right">管理</th></tr></thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(i => (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50 transition-colors group">
                    <td className="px-8 py-5">
                      <div className="font-black text-lg text-slate-900">{item.name}</div>
                      <div className="text-xs text-slate-400 font-bold uppercase tracking-tight">規格: {item.spec || '無'} | {item.itemType === 'EQUIPMENT' ? '安全設備' : '消耗品'}</div>
                    </td>
                    <td className="px-8 py-5 text-center">
                      <div className="flex flex-col items-center">
                        <span className={`px-5 py-2 rounded-xl text-xl font-black ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600 border border-red-200' : 'bg-emerald-50 text-emerald-600'}`}>{item.quantity} {item.unit}</span>
                        {item.quantity <= item.minStock && <span className="text-[9px] font-black mt-1 low-pulse uppercase tracking-widest">⚠️ 低庫存</span>}
                      </div>
                    </td>
                    <td className="px-8 py-5 text-right opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => setEditTarget(item)} className="p-2 text-slate-400 hover:text-blue-600"><Edit3 size={18}/></button><button onClick={() => setDeleteTarget({id: item.id, name: item.name})} className="p-2 text-slate-400 hover:text-red-600"><Trash2 size={18}/></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
            <table className="w-full text-left border-collapse">
              <thead className="bg-slate-50 text-[10px] font-black text-slate-400 border-b uppercase tracking-widest"><tr><th className="px-8 py-5">異動時間</th><th className="px-8 py-5">性質</th><th className="px-8 py-5">領用項目</th><th className="px-8 py-5">單位 / 人員</th><th className="px-8 py-5 text-right">列印</th></tr></thead>
              <tbody className="divide-y divide-slate-100">{logs.map(log => (<tr key={log.id} className="hover:bg-slate-50"><td className="px-8 py-5 text-xs text-slate-400 font-bold">{new Date(log.timestamp).toLocaleString()}</td><td className="px-8 py-5"><span className={`px-3 py-1 rounded-full text-[10px] font-black ${log.type === 'OUT' ? 'bg-blue-100 text-blue-600' : 'bg-emerald-100 text-emerald-600'}`}>{log.type === 'OUT' ? '領用' : '補貨'}</span></td><td className="px-8 py-5 font-black text-slate-800">{log.itemName} (x{log.quantity})</td><td className="px-8 py-5 text-xs font-bold text-slate-600">{log.dept} / {log.person}</td><td className="px-8 py-5 text-right"><button onClick={()=>{ setLastTransactionBatch({id: log.id, dept: log.dept, person: log.person, reason: log.reason, items: [{itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '個', spec: '', itemType: 'CONSUMABLE'}], timestamp: log.timestamp}); setShowPrintModal(true); }} className="text-slate-400 hover:text-blue-600"><Printer size={18}/></button></td></tr>))}</tbody>
            </table>
          </div>
        )}

        {/* 數據看板 */}
        {activeTab === 'dashboard' && (
          <div className="space-y-10">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8"><div className="bg-white p-10 rounded-[2rem] border-l-8 border-l-blue-500 shadow-xl flex justify-between items-center"><div><p className="text-slate-400 text-xs font-black uppercase tracking-widest">總品項管理</p><h3 className="text-6xl font-black mt-2 text-slate-900">{dashboardStats.inv.total}</h3></div><Package size={60} className="text-slate-100"/></div><div className="bg-white p-10 rounded-[2rem] border-l-8 border-l-red-500 shadow-xl flex justify-between items-center"><div><p className="text-red-500 text-xs font-black uppercase tracking-widest">低庫存警戒</p><h3 className="text-6xl font-black text-red-600 mt-2">{dashboardStats.inv.low}</h3></div><AlertTriangle size={60} className="text-red-50"/></div></div>
            <div className="bg-slate-900 p-12 rounded-[3rem] flex items-center gap-10 shadow-2xl relative overflow-hidden"><div className="absolute top-0 right-0 w-64 h-64 bg-blue-600/10 blur-[100px] rounded-full"></div><div className="flex-1 text-white relative z-10"><h4 className="text-3xl font-black mb-4 flex items-center gap-3 text-blue-400"><BrainCircuit size={32}/> 工安採購智能分析</h4><p className="text-slate-400 font-bold text-lg">系統正透過 AI 掃描您的領用模式與庫存現狀。</p></div><button onClick={async () => { setIsAiLoading(true); setAiInsights(await getInventoryInsights(items)); setIsAiLoading(false); }} className="px-12 py-5 bg-blue-600 text-white rounded-2xl font-black text-xl hover:bg-blue-500 hover:scale-105 active:scale-95 transition-all z-10 shadow-xl">{isAiLoading ? '運算中...' : '生成報告'}</button></div>
            {aiInsights && <div className="bg-white p-12 rounded-[3rem] border-2 border-blue-100 text-slate-800 text-xl font-bold whitespace-pre-wrap leading-relaxed shadow-lg animate-in fade-in slide-in-from-bottom-5 duration-500">{aiInsights}</div>}
          </div>
        )}

        {/* Modal: 新增/編輯項目 */}
        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl animate-in zoom-in-95 duration-300">
              <div className="flex justify-between items-center mb-8"><h3 className="text-2xl font-black text-slate-900">{(editTarget ? '編輯物資設定' : '新增管理品項')}</h3><button onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="p-3 bg-slate-100 rounded-full text-slate-900 hover:rotate-90 transition-all"><X size={20}/></button></div>
              <form className="space-y-5" onSubmit={handleSaveItem}>
                <div><label className="block text-[10px] font-black mb-1.5 uppercase tracking-widest text-slate-400">物資全名</label><input name="name" type="text" required className="w-full p-4 rounded-xl" defaultValue={editTarget?.name} /></div>
                <div className="grid grid-cols-2 gap-5">
                  <div><label className="block text-[10px] font-black mb-1.5 uppercase tracking-widest text-slate-400">單據性質</label><select name="itemType" className="w-full p-4 rounded-xl" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="EQUIPMENT">安全衛生設備</option><option value="CONSUMABLE">安全衛生消耗品</option></select></div>
                  <div><label className="block text-[10px] font-black mb-1.5 uppercase tracking-widest text-slate-400">規格 / 序號</label><input name="spec" type="text" className="w-full p-4 rounded-xl" defaultValue={editTarget?.spec || ''} /></div>
                </div>
                {((editTarget?.itemGroup === 'MEDICINE') || (activeTab === 'medicine' && !editTarget)) && (
                  <div className="grid grid-cols-2 gap-5">
                    <div><label className="block text-[10px] font-black mb-1.5 uppercase tracking-widest text-slate-400">購入日期</label><input name="purchaseDate" type="date" className="w-full" defaultValue={editTarget?.purchaseDate} /></div>
                    <div><label className="block text-[10px] font-black mb-1.5 uppercase tracking-widest text-red-500">效期截止</label><input name="expiryDate" type="date" className="w-full font-black text-red-600" defaultValue={editTarget?.expiryDate} /></div>
                  </div>
                )}
                <div className="grid grid-cols-3 gap-5">
                  <div className="col-span-1"><label className="block text-[10px] font-black mb-1.5 uppercase tracking-widest text-slate-400">單位</label><input name="unit" type="text" placeholder="個/雙/盒" className="w-full p-4 rounded-xl" defaultValue={editTarget?.unit || '個'} /></div>
                  <div className="col-span-1"><label className="block text-[10px] font-black mb-1.5 uppercase tracking-widest text-slate-400">初始庫存</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl" defaultValue={editTarget?.quantity || 0} /></div>
                  <div className="col-span-1"><label className="block text-[10px] font-black mb-1.5 uppercase tracking-widest text-orange-500">警戒水位</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl" defaultValue={editTarget?.minStock || 5} /></div>
                </div>
                <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl hover:bg-blue-700 active:scale-95 transition-all mt-6">儲存物資設定</button>
              </form>
            </div>
          </div>
        )}

        {/* 刪除確認 */}
        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm z-[400] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2rem] w-full max-w-[340px] p-10 text-center shadow-2xl animate-in fade-in zoom-in-95 duration-200">
              <div className="w-20 h-20 bg-red-50 text-red-600 rounded-full flex items-center justify-center mx-auto mb-6"><AlertTriangle size={40} /></div>
              <h3 className="text-2xl font-black mb-2 text-slate-900">確認移除？</h3>
              <p className="text-slate-500 text-sm font-bold mb-10 leading-relaxed">項目「{deleteTarget.name}」將連同歷史紀錄一併從資料庫中移除。</p>
              <div className="flex flex-col gap-3"><button onClick={confirmDelete} className="w-full py-4 bg-red-600 text-white rounded-xl font-black text-lg">確定永久刪除</button><button onClick={()=>setDeleteTarget(null)} className="w-full py-4 bg-slate-100 text-slate-400 rounded-xl font-bold">返回</button></div>
            </div>
          </div>
        )}

        {/* 列印預覽視窗 */}
        {showPrintModal && lastTransactionBatch && (
          <div className="fixed inset-0 bg-slate-900/95 z-[500] flex flex-col items-center justify-start p-10 overflow-y-auto">
            <div className="bg-white rounded-[2.5rem] w-full max-w-5xl p-10 relative shadow-2xl my-4">
              <div className="flex justify-between items-center mb-8 border-b pb-8">
                 <div className="flex items-center gap-5"><div className="p-4 bg-emerald-50 text-emerald-600 rounded-2xl shadow-sm"><CheckCircle2 size={40}/></div><div><h3 className="font-black text-3xl text-slate-900">單據處理成功</h3><p className="text-slate-400 font-bold text-lg">庫存已同步完成更新。請確認以下預覽並列印。</p></div></div>
                 <div className="flex gap-4">
                    <button onClick={handlePrint} className="bg-blue-600 text-white px-12 py-5 rounded-2xl font-black text-2xl shadow-xl hover:scale-105 transition-all flex items-center gap-3"><Printer size={28}/> 執行列印</button>
                    <button onClick={()=>setShowPrintModal(false)} className="p-5 bg-slate-100 rounded-2xl text-slate-900 hover:bg-slate-200 transition-colors"><X size={28}/></button>
                 </div>
              </div>
              <div className="bg-slate-50 p-12 rounded-[3rem] border shadow-inner flex justify-center">
                 <div className="bg-white shadow-2xl p-6 border rounded-sm origin-top" style={{ transform: 'scale(0.85)' }}>
                    {/* 簡易靜態預覽內容 */}
                    <div style={{ width: '210mm', minHeight: '180mm', color: 'black', background: 'white', padding: '10mm' }}>
                       <div style={{ textAlign: 'right', fontSize: '10pt' }}>單號：{lastTransactionBatch.id}</div>
                       <h1 style={{ textAlign: 'center', fontSize: '24pt', borderBottom: '2px solid black', paddingBottom: '10px' }}>台電修護處南部分處 - 領用單預覽</h1>
                       <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '20px', fontWeight: 'bold', fontSize: '14pt' }}>
                         <span>領用人：{lastTransactionBatch.person}</span>
                         <span>單位：{lastTransactionBatch.dept}</span>
                         <span>日期：{new Date(lastTransactionBatch.timestamp).toLocaleDateString()}</span>
                       </div>
                       <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '30px', border: '2px solid black' }}>
                         <thead><tr style={{ background: '#f5f5f5' }}><th style={{ border: '1px solid black', padding: '10px' }}>物資名稱</th><th style={{ border: '1px solid black', padding: '10px' }}>數量</th><th style={{ border: '1px solid black', padding: '10px' }}>備註</th></tr></thead>
                         <tbody>{lastTransactionBatch.items.map((it, i) => (<tr key={i}><td style={{ border: '1px solid black', padding: '12px' }}>{it.name}</td><td style={{ border: '1px solid black', textAlign: 'center', fontWeight: 'bold', fontSize: '16pt' }}>{it.quantity} {it.unit}</td><td style={{ border: '1px solid black', padding: '10px' }}>{lastTransactionBatch.reason}</td></tr>))}</tbody>
                       </table>
                       <p style={{ marginTop: '50px', fontStyle: 'italic', color: '#888' }}>* 列印時將自動採用正式台電標準格式</p>
                    </div>
                 </div>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
