];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  const printFrameRef = useRef<HTMLIFrameElement>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const getReservedQty = (itemId: string) => {
    return basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);
  };

  const currentAvailable = useMemo(() => {
    if (!selectedItemId) return 0;
    const item = items.find(i => i.id === selectedItemId);
    if (!item) return 0;
    return item.quantity - getReservedQty(selectedItemId);
  }, [selectedItemId, items, basket]);

  const isQtyOver = useMemo(() => {
    if (issuanceMode === 'IN') return false;
    const qty = Number(inputQty);
    return !isNaN(qty) && qty > currentAvailable;
  }, [inputQty, currentAvailable, issuanceMode]);

  const addToBasket = () => {
    if (!selectedItemId || isQtyOver) return;
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;
    const qty = Number(inputQty);
    if (isNaN(qty) || qty <= 0) return;

    setBasket(prev => [
      ...prev,
      {
        itemId: targetItem.id,
        name: targetItem.name,
        quantity: qty,
        unit: targetItem.unit,
        spec: targetItem.spec,
        itemType: targetItem.itemType
      }
    ]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    // V28: 移除領用人強制檢查

    const timestamp = Date.now();
    const batchId = generateId();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(bItem => {
      updatedItems = updatedItems.map(item => {
        if (item.id === bItem.itemId) {
          const newQty = issuanceMode === 'IN' ? item.quantity + bItem.quantity : item.quantity - bItem.quantity;
          return { ...item, quantity: newQty, lastUpdated: timestamp };
        }
        return item;
      });
      newLogs.push({
        id: generateId() + Math.random().toString(36).substr(2, 4),
        itemId: bItem.itemId,
        itemName: bItem.name,
        type: issuanceMode,
        quantity: bItem.quantity,
        person: inputPerson || '未填寫',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: inputReason,
        timestamp: timestamp
      });
    });

    setItems(updatedItems);
    setLogs(prev => [...newLogs, ...prev]);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({
        id: batchId,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: timestamp
      });
      setShowPrintModal(true);
    } else {
      window.alert(`✅ 入庫成功。`);
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  const handlePrint = () => {
    if (!lastTransactionBatch || !printFrameRef.current) return;
    const doc = printFrameRef.current.contentDocument;
    if (!doc) return;

    const date = new Date(lastTransactionBatch.timestamp);
    const isEquip = lastTransactionBatch.items.some(it => it.itemType === 'EQUIPMENT');
    const isConsum = lastTransactionBatch.items.every(it => it.itemType === 'CONSUMABLE') || !isEquip;

    const rows = lastTransactionBatch.items.map(item => `
      <tr>
        <td style="text-align:left;">${item.name}</td>
        <td>${item.spec || ''}</td>
        <td>${item.unit}</td>
        <td style="font-size:18pt; font-weight:bold;">${item.quantity}</td>
        <td>${lastTransactionBatch.reason}</td>
      </tr>
    `).join('');
    const emptyRowsCount = Math.max(0, 15 - lastTransactionBatch.items.length);
    const emptyRows = Array(emptyRowsCount).fill('<tr><td>&nbsp;</td><td></td><td></td><td></td><td></td></tr>').join('');

    doc.open();
    doc.write(`
      <html>
        <head>
          <style>
            @font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); }
            body { font-family: 'StandardKai', serif; padding: 30px; color: black; line-height: 1.1; margin: 0; }
            .title { text-align: center; font-size: 24pt; font-weight: bold; margin-bottom: 20px; text-decoration: underline; }
            .checkbox-area { display: flex; justify-content: center; gap: 30px; font-size: 16pt; margin-bottom: 20px; font-weight: bold; }
            .checkbox { width: 22px; height: 22px; border: 2px solid black; display: inline-flex; align-items: center; justify-content: center; margin-right: 5px; vertical-align: middle; }
            .dept-row { font-size: 15pt; font-weight: bold; margin-bottom: 5px; display: flex; justify-content: space-between; }
            .dots { border-bottom: 1.5px dotted black; display: inline-block; min-width: 150px; text-align: center; }
            table { width: 100%; border-collapse: collapse; border: 2.5px solid black; margin-bottom: 20px; }
            th, td { border: 1.5px solid black; padding: 6px; text-align: center; height: 32px; font-size: 12pt; }
            th { font-size: 13pt; font-weight: bold; }
            .footer-row { font-size: 13pt; font-weight: bold; margin-top: 20px; }
            .sig-area { display: flex; justify-content: space-between; margin-top: 35px; font-size: 12pt; }
            @media print { .no-print { display: none; } }
          </style>
        </head>
        <body>
          <div style="text-align:right; font-size: 8pt; color: #888;">ID: ${lastTransactionBatch.id}</div>
          <div class="title">台灣電力公司電力修護處南部分處</div>
          <div class="checkbox-area">
            <div><span class="checkbox">${isEquip ? 'V' : ''}</span>安全衛生設備借用單</div>
            <div><span class="checkbox">${isConsum ? 'V' : ''}</span>安全衛生類消耗品領用單</div>
          </div>
          <div class="dept-row">
            <div>部門：<span class="dots" style="min-width: 350px;">${lastTransactionBatch.dept}</span></div>
            <div>${date.getFullYear() - 1911} 年 ${date.getMonth() + 1} 月 ${date.getDate()} 日</div>
          </div>
          <table>
            <thead>
              <tr><th style="width:35%">名　　　稱</th><th style="width:25%">規　範（序　號）</th><th style="width:10%">單位</th><th style="width:10%">數量</th><th style="width:20%">備　　註</th></tr>
            </thead>
            <tbody>${rows}${emptyRows}</tbody>
          </table>
          <div class="footer-row">
            <div style="display: flex; justify-content: space-between;">
              <div style="flex:1">申請部門：<span class="dots" style="min-width: 250px;"></span></div>
              <div style="flex:1">經管部門：</div>
            </div>
            <div class="sig-area">
              <div style="flex:1; display:flex; justify-content:space-between; padding-right: 40px;">
                <span>經辦：</span><span>課長：</span><span>經理：</span>
              </div>
              <div style="flex:1; display:flex; justify-content:space-between; padding-left: 10px;">
                <span>經辦：</span><span>課長：</span><span>經理：</span>
              </div>
            </div>
          </div>
        </body>
      </html>
    `);
    doc.close();
    setTimeout(() => {
      printFrameRef.current?.contentWindow?.focus();
      printFrameRef.current?.contentWindow?.print();
    }, 300);
  };

  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = {
      name: formData.get('name') as string,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
    };
    if (!data.name.trim()) return window.alert('名稱不可為空');
    if (editTarget) {
      setItems(prev => prev.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i));
      setEditTarget(null);
    } else {
      setItems(prev => [...prev, { id: generateId(), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: Date.now() }]);
      setShowAddModal(false);
    }
  };

  const confirmDelete = () => {
    if (deleteTarget) {
      setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
      setDeleteTarget(null);
    }
  };

  const stats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    return {
      total: invItems.length,
      low: invItems.filter(i => i.quantity <= i.minStock).length,
      logsCount: logs.filter(l => l.type === 'OUT' && new Date(l.timestamp).getMonth() === new Date().getMonth()).length
    };
  }, [items, logs]);

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900 font-sans">
      <style>{`
        input, select { color: #000 !important; background-color: #fff !important; font-weight: 600 !important; border: 2px solid #cbd5e1 !important; }
        input[type="date"]::-webkit-calendar-picker-indicator { cursor: pointer; border: 1px solid #000; padding: 2px; }
        .text-deep-black { color: #000000 !important; }
      `}</style>

      <iframe ref={printFrameRef} className="hidden" title="print-frame" />

      <aside className="w-64 bg-slate-900 text-white p-6 flex flex-col shrink-0">
        <div className="flex items-center gap-3 mb-10">
          <div className="w-8 h-8 bg-blue-600 rounded flex items-center justify-center"><Package size={18}/></div>
          <h1 className="font-black text-lg">工安管理系統</h1>
        </div>
        <nav className="flex-1 space-y-1">
          {[
            { id: 'inventory', label: '工安耗材管理', icon: Package },
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
            { id: 'issuance', label: '領用補貨作業', icon: FileText },
            { id: 'history', label: '歷史異動日誌', icon: History },
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard },
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white' : 'text-slate-400 hover:bg-slate-800'}`}><tab.icon size={18} /> {tab.label}</button>
          ))}
        </nav>
      </aside>

      <main className="flex-1 p-10 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-2xl font-black">{activeTab === 'inventory' ? '工安耗材清冊' : activeTab === 'medicine' ? '急救藥材清冊' : activeTab === 'issuance' ? '領用/補貨登記' : activeTab === 'history' ? '歷史異動日誌' : '數據中心'}</h2>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-5 py-2 rounded-lg font-bold flex items-center gap-2 hover:bg-black"><Plus size={16}/> 新增項目</button>
          )}
        </header>

        {activeTab === 'issuance' && (
          <div className="grid grid-cols-1 lg:grid-cols-5 gap-6">
            <div className="lg:col-span-2 bg-white p-8 rounded-2xl shadow border border-slate-200">
              <h3 className="text-lg font-bold mb-6 flex items-center gap-2"><ShoppingCart className="text-blue-500"/> 1. 選擇品項</h3>
              <div className="flex bg-slate-100 p-1 rounded-lg mb-6">
                <button onClick={()=>{setIssuanceMode('OUT'); setBasket([]);}} className={`flex-1 py-2 rounded font-bold ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button>
                <button onClick={()=>{setIssuanceMode('IN'); setBasket([]);}} className={`flex-1 py-2 rounded font-bold ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
              </div>
              <div className="space-y-4">
                <div><label className="text-xs font-bold text-slate-400 uppercase">群組</label>
                  <div className="flex gap-2 mt-1">
                    <button onClick={()=>setIssuanceGroup('INVENTORY')} className={`flex-1 py-2 rounded-lg font-bold border-2 ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-200 text-slate-400'}`}>耗材</button>
                    <button onClick={()=>setIssuanceGroup('MEDICINE')} className={`flex-1 py-2 rounded-lg font-bold border-2 ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-200 text-slate-400'}`}>藥材</button>
                  </div>
                </div>
                <div><label className="text-xs font-bold text-slate-400 uppercase">品項名稱</label>
                  <select className="w-full p-3 rounded-lg mt-1" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                    <option value="">-- 請選擇 --</option>
                    {items.filter(i => i.itemGroup === issuanceGroup).map(i => {
                      const avail = i.quantity - getReservedQty(i.id);
                      const label = issuanceMode === 'OUT' ? `${i.name} (可用: ${avail})` : `${i.name} (庫存: ${i.quantity})`;
                      return <option key={i.id} value={i.id} className={avail <= 0 && issuanceMode === 'OUT' ? 'text-red-400' : ''}>{label}</option>;
                    })}
                  </select>
                </div>
                <div><label className="text-xs font-bold text-slate-400 uppercase">數量</label><input type="number" min="1" className="w-full p-3 rounded-lg mt-1" value={inputQty} onChange={e=>setInputQty(e.target.value)}/>
                  {isQtyOver && <p className="text-red-600 text-[10px] font-bold mt-1">⚠️ 數量超過現有庫存 ({currentAvailable})</p>}
                </div>
                <button onClick={addToBasket} disabled={!selectedItemId || isQtyOver} className={`w-full py-4 rounded-xl font-bold flex items-center justify-center gap-2 ${!selectedItemId || isQtyOver ? 'bg-slate-100 text-slate-400' : 'bg-slate-900 text-white hover:bg-black'}`}><Plus size={18}/> 加入待處理清單</button>
              </div>
            </div>

            <div className="lg:col-span-3 bg-white p-8 rounded-2xl shadow border border-slate-200 flex flex-col">
              <h3 className="text-lg font-bold mb-4 flex items-center gap-2"><FileText className="text-emerald-500"/> 2. 待處理清單</h3>
              <div className="flex-1 overflow-y-auto border-2 border-dashed border-slate-100 rounded-xl mb-6 min-h-[250px] bg-slate-50/50">
                {basket.length > 0 ? (
                  <table className="w-full text-left">
                    <thead className="bg-slate-100 text-[10px] font-bold text-slate-400"><tr><th className="px-4 py-2">品項</th><th className="px-4 py-2 text-center">數量</th><th className="px-4 py-2 text-right">管理</th></tr></thead>
                    <tbody className="divide-y">
                      {basket.map((b, idx) => (
                        <tr key={idx} className="bg-white">
                          <td className="px-4 py-3 font-bold text-deep-black text-sm">{b.name}</td>
                          <td className="px-4 py-3 text-center font-black text-blue-600">{b.quantity} {b.unit}</td>
                          <td className="px-4 py-3 text-right"><button onClick={()=>setBasket(prev => prev.filter((_, i) => i !== idx))} className="text-slate-300 hover:text-red-500"><X size={16}/></button></td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                ) : (<div className="h-full flex flex-col items-center justify-center text-slate-300 font-bold opacity-30"><ShoppingCart size={32} className="mb-2"/><p>清單是空的</p></div>)}
              </div>
              {issuanceMode === 'OUT' && (
                <div className="grid grid-cols-2 gap-4 mb-4">
                  <div><label className="text-[10px] font-bold text-slate-400">領用部門</label><select className="w-full p-2 rounded-lg mt-1" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>{DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}</select></div>
                  <div><label className="text-[10px] font-bold text-slate-400">領用人 (選填)</label><input type="text" className="w-full p-2 rounded-lg mt-1" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div>
                  <div className="col-span-2"><label className="text-[10px] font-bold text-slate-400">備註 / 用途</label><input type="text" className="w-full p-2 rounded-lg mt-1" value={inputReason} onChange={e=>setInputReason(e.target.value)}/></div>
                </div>
              )}
              <button onClick={processIssuance} disabled={basket.length === 0} className={`w-full py-5 rounded-xl font-bold text-2xl text-white ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>
                {issuanceMode === 'OUT' ? '確認並生成領用單' : '確認入庫'}
              </button>
            </div>
          </div>
        )}

        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-xl shadow border border-slate-200 overflow-hidden">
            <div className="p-4 bg-slate-50 border-b flex items-center"><div className="relative max-w-xs w-full"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} /><input type="text" placeholder="搜尋項目..." className="w-full pl-9 pr-3 py-2 rounded-lg text-sm" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} /></div></div>
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b"><tr><th className="px-8 py-4">名稱及規格</th><th className="px-8 py-4 text-center">庫存狀態</th><th className="px-8 py-4 text-right">管理</th></tr></thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(i => (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-8 py-4"><div className="font-bold text-slate-900">{item.name}</div><div className="text-[10px] text-slate-400 font-bold">規格: {item.spec || '無'} | {item.itemType === 'EQUIPMENT' ? '設備' : '耗材'}</div></td>
                    <td className="px-8 py-4 text-center"><span className={`px-4 py-1.5 rounded-lg font-black text-lg ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-emerald-50 text-emerald-600'}`}>{item.quantity} {item.unit}</span></td>
                    <td className="px-8 py-4 text-right"><button onClick={() => setEditTarget(item)} className="p-2 text-slate-300 hover:text-blue-600"><Edit3 size={16}/></button><button onClick={() => setDeleteTarget({id: item.id, name: item.name})} className="p-2 text-slate-300 hover:text-red-600"><Trash2 size={16}/></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-xl shadow border border-slate-200 overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[10px] font-bold text-slate-400 border-b"><tr><th className="px-6 py-4">時間</th><th className="px-6 py-4">類型</th><th className="px-6 py-4">品項</th><th className="px-6 py-4">部門/人員</th><th className="px-6 py-4 text-right">操作</th></tr></thead>
              <tbody className="divide-y divide-slate-100">{logs.map(log => (<tr key={log.id} className="hover:bg-slate-50"><td className="px-6 py-4 text-xs font-bold text-slate-400">{new Date(log.timestamp).toLocaleString()}</td><td className="px-6 py-4"><span className={`px-2 py-1 rounded-full text-[9px] font-bold ${log.type === 'OUT' ? 'bg-blue-100 text-blue-600' : 'bg-emerald-100 text-emerald-600'}`}>{log.type === 'OUT' ? '領用' : '補貨'}</span></td><td className="px-6 py-4 font-bold text-slate-800">{log.itemName} (x{log.quantity})</td><td className="px-6 py-4 text-xs font-bold text-slate-600">{log.dept} / {log.person}</td><td className="px-6 py-4 text-right"><button onClick={()=>{ setLastTransactionBatch({id: log.id, dept: log.dept, person: log.person, reason: log.reason, items: [{itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '個', spec: '', itemType: 'CONSUMABLE'}], timestamp: log.timestamp}); setShowPrintModal(true); }} className="text-slate-300 hover:text-blue-600"><Printer size={16}/></button></td></tr>))}</tbody>
            </table>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-white p-8 rounded-2xl shadow border-l-4 border-blue-500"><p className="text-slate-400 text-xs font-bold uppercase tracking-widest">總品項管理</p><h3 className="text-4xl font-black mt-2 text-slate-900">{stats.total}</h3></div>
              <div className="bg-white p-8 rounded-2xl shadow border-l-4 border-red-500"><p className="text-red-500 text-xs font-bold uppercase tracking-widest">低水位警戒</p><h3 className="text-4xl font-black text-red-600 mt-2">{stats.low}</h3></div>
              <div className="bg-white p-8 rounded-2xl shadow border-l-4 border-emerald-500"><p className="text-emerald-500 text-xs font-bold uppercase tracking-widest">本月領用次數</p><h3 className="text-4xl font-black text-emerald-600 mt-2">{stats.logsCount}</h3></div>
            </div>
            <div className="bg-slate-900 p-8 rounded-2xl text-white flex items-center justify-between"><div className="flex-1"><h4 className="text-xl font-bold flex items-center gap-2 text-blue-400"><BrainCircuit size={20}/> 工安 AI 採購分析助手</h4><p className="text-slate-400 text-sm mt-1">分析歷史異動規律，生成採購優化建議。</p></div><button onClick={async () => { setIsAiLoading(true); setAiInsights(await getInventoryInsights(items)); setIsAiLoading(false); }} className="px-8 py-3 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-500">{isAiLoading ? '運算中...' : '生成報告'}</button></div>
            {aiInsights && <div className="bg-white p-8 rounded-2xl border-2 border-blue-50 text-slate-800 font-bold whitespace-pre-wrap shadow-sm">{aiInsights}</div>}
          </div>
        )}

        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
            <div className="bg-white rounded-2xl w-full max-w-md p-8 shadow-2xl">
              <div className="flex justify-between items-center mb-6"><h3 className="text-xl font-bold">{(editTarget ? '編輯設定' : '新增管理品項')}</h3><button onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="p-2 hover:bg-slate-100 rounded-full"><X size={18}/></button></div>
              <form className="space-y-4" onSubmit={handleSaveItem}>
                <div><label className="text-[10px] font-bold text-slate-400">項目名稱</label><input name="name" type="text" required className="w-full p-2.5 rounded-lg" defaultValue={editTarget?.name} /></div>
                <div className="grid grid-cols-2 gap-4">
                  <div><label className="text-[10px] font-bold text-slate-400">性質</label><select name="itemType" className="w-full p-2.5 rounded-lg" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="EQUIPMENT">安全設備</option><option value="CONSUMABLE">消耗品</option></select></div>
                  <div><label className="text-[10px] font-bold text-slate-400">規格 / 序號</label><input name="spec" type="text" className="w-full p-2.5 rounded-lg" defaultValue={editTarget?.spec || ''} /></div>
                </div>
                {((editTarget?.itemGroup === 'MEDICINE') || (activeTab === 'medicine' && !editTarget)) && (
                  <div className="grid grid-cols-2 gap-4">
                    <div><label className="text-[10px] font-bold text-slate-400">購入日期</label><input name="purchaseDate" type="date" className="w-full" defaultValue={editTarget?.purchaseDate} /></div>
                    <div><label className="text-[10px] font-bold text-red-500">效期截止</label><input name="expiryDate" type="date" className="w-full" defaultValue={editTarget?.expiryDate} /></div>
                  </div>
                )}
                <div className="grid grid-cols-3 gap-4">
                  <div><label className="text-[10px] font-bold text-slate-400">單位</label><input name="unit" type="text" className="w-full p-2.5 rounded-lg" defaultValue={editTarget?.unit || '個'} /></div>
                  <div><label className="text-[10px] font-bold text-slate-400">數量</label><input name="quantity" type="number" required className="w-full p-2.5 rounded-lg" defaultValue={editTarget?.quantity || 0} /></div>
                  <div><label className="text-[10px] font-bold text-slate-400">警戒</label><input name="minStock" type="number" required className="w-full p-2.5 rounded-lg" defaultValue={editTarget?.minStock || 5} /></div>
                </div>
                <button type="submit" className="w-full py-4 bg-blue-600 text-white rounded-xl font-bold mt-4 shadow-lg">儲存設定</button>
              </form>
            </div>
          </div>
        )}

        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[400] flex items-center justify-center">
            <div className="bg-white rounded-2xl p-8 text-center max-w-sm"><h3 className="text-xl font-bold mb-2">確定刪除？</h3><p className="text-slate-500 text-sm mb-6">「{deleteTarget.name}」將被永久移除。</p><div className="flex gap-2"><button onClick={confirmDelete} className="flex-1 py-2 bg-red-600 text-white rounded-lg font-bold">刪除</button><button onClick={()=>setDeleteTarget(null)} className="flex-1 py-2 bg-slate-100 text-slate-400 rounded-lg font-bold">取消</button></div></div>
          </div>
        )}

        {showPrintModal && lastTransactionBatch && (
          <div className="fixed inset-0 bg-slate-900/90 z-[500] flex flex-col items-center justify-center p-6">
            <div className="bg-white rounded-3xl w-full max-w-4xl p-8 shadow-2xl flex flex-col h-[90vh]">
              <div className="flex justify-between items-center mb-6 border-b pb-4">
                 <div className="flex items-center gap-4"><CheckCircle2 className="text-emerald-500" size={32}/><h3 className="font-bold text-xl">已產生成領用單 (預覽)</h3></div>
                 <div className="flex gap-3">
                    <button onClick={handlePrint} className="bg-blue-600 text-white px-8 py-3 rounded-xl font-bold flex items-center gap-2 shadow-lg"><Printer size={18}/> 執行列印</button>
                    <button onClick={()=>setShowPrintModal(false)} className="p-3 bg-slate-100 rounded-xl hover:bg-slate-200"><X size={20}/></button>
                 </div>
              </div>
              <div className="flex-1 bg-slate-100 p-8 rounded-2xl overflow-y-auto border shadow-inner flex justify-center">
                 <div className="bg-white shadow-lg p-1 origin-top" style={{ transform: 'scale(0.8)' }}>
                    {/* 簡易靜態預覽 - 同時顯影給使用者看 */}
                    <div style={{width:'210mm', minHeight:'297mm', padding:'20px', color:'black', fontStyle:'serif'}}>
                       <h1 style={{textAlign:'center', fontSize:'22pt', fontWeight:'bold', borderBottom:'1px solid #eee', paddingBottom:'10px'}}>台灣電力公司電力修護處南部分處</h1>
                       <div style={{display:'flex', justifyContent:'center', gap:'20px', fontSize:'14pt', margin:'20px 0', fontWeight:'bold'}}>
                         <label>[ ] 安全衛生設備借用單</label>
                         <label>[V] 安全衛生類消耗品領用單</label>
                       </div>
                       <div style={{display:'flex', justifyContent:'space-between', marginBottom:'10px', fontWeight:'bold', fontSize:'12pt'}}>
                         <span>部門：${lastTransactionBatch.dept}</span>
                         <span>${new Date(lastTransactionBatch.timestamp).toLocaleDateString()}</span>
                       </div>
                       <table style={{width:'100%', borderCollapse:'collapse', border:'2px solid black'}}>
                          <thead><tr style={{background:'#f9f9f9'}}><th style={{border:'1.5px solid black', padding:'10px'}}>名　　稱</th><th style={{border:'1.5px solid black', padding:'10px'}}>規範(序號)</th><th style={{border:'1.5px solid black', padding:'10px'}}>單位</th><th style={{border:'1.5px solid black', padding:'10px'}}>數量</th><th style={{border:'1.5px solid black', padding:'10px'}}>備　　註</th></tr></thead>
                          <tbody>{lastTransactionBatch.items.map((it, i) => (<tr key={i}><td style={{border:'1px solid black', padding:'10px', textAlign:'left'}}>{it.name}</td><td style={{border:'1px solid black'}}>{it.spec}</td><td style={{border:'1px solid black'}}>{it.unit}</td><td style={{border:'1px solid black', fontWeight:'bold', fontSize:'14pt'}}>{it.quantity}</td><td style={{border:'1px solid black'}}>{lastTransactionBatch.reason}</td></tr>))}</tbody>
                       </table>
                       <p style={{marginTop:'20px', color:'#999', fontSize:'10pt'}}>* 預覽僅供參考，列印時會採用正式 15 列格線格式</p>
                    </div>
                 </div>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  CheckCircle2
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v29_items';
const STORAGE_KEY_LOGS = 'safeman_v29_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  const printFrameRef = useRef<HTMLIFrameElement>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const getReservedQty = (itemId: string) => {
    return basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);
  };

  const currentAvailable = useMemo(() => {
    if (!selectedItemId) return 0;
    const item = items.find(i => i.id === selectedItemId);
    if (!item) return 0;
    return item.quantity - getReservedQty(selectedItemId);
  }, [selectedItemId, items, basket]);

  const isQtyOver = useMemo(() => {
    if (issuanceMode === 'IN') return false;
    const qty = Number(inputQty);
    return !isNaN(qty) && qty > currentAvailable;
  }, [inputQty, currentAvailable, issuanceMode]);

  const addToBasket = () => {
    if (!selectedItemId || isQtyOver) return;
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;
    const qty = Number(inputQty);
    if (isNaN(qty) || qty <= 0) return;

    setBasket(prev => [
      ...prev,
      {
        itemId: targetItem.id,
        name: targetItem.name,
        quantity: qty,
        unit: targetItem.unit,
        spec: targetItem.spec,
        itemType: targetItem.itemType
      }
    ]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const timestamp = Date.now();
    const batchId = generateId();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(bItem => {
      updatedItems = updatedItems.map(item => {
        if (item.id === bItem.itemId) {
          const newQty = issuanceMode === 'IN' ? item.quantity + bItem.quantity : item.quantity - bItem.quantity;
          return { ...item, quantity: newQty, lastUpdated: timestamp };
        }
        return item;
      });
      newLogs.push({
        id: generateId() + Math.random().toString(36).substr(2, 4),
        itemId: bItem.itemId,
        itemName: bItem.name,
        type: issuanceMode,
        quantity: bItem.quantity,
        person: inputPerson || '未填寫',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: inputReason,
        timestamp: timestamp
      });
    });

    setItems(updatedItems);
    setLogs(prev => [...newLogs, ...prev]);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({
        id: batchId,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: timestamp
      });
      setShowPrintModal(true);
    } else {
      window.alert(`✅ 入庫成功。`);
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  const handlePrint = () => {
    if (!lastTransactionBatch || !printFrameRef.current) return;
    const doc = printFrameRef.current.contentDocument;
    if (!doc) return;

    const date = new Date(lastTransactionBatch.timestamp);
    const isEquip = lastTransactionBatch.items.some(it => it.itemType === 'EQUIPMENT');
    const isConsum = lastTransactionBatch.items.every(it => it.itemType === 'CONSUMABLE') || !isEquip;

    const rows = lastTransactionBatch.items.map(item => `
      <tr>
        <td style="text-align:left; color:black;">${item.name}</td>
        <td style="color:black;">${item.spec || ''}</td>
        <td style="color:black;">${item.unit}</td>
        <td style="font-size:18pt; font-weight:bold; color:black;">${item.quantity}</td>
        <td style="color:black;">${lastTransactionBatch.reason}</td>
      </tr>
    `).join('');
    const emptyRowsCount = Math.max(0, 15 - lastTransactionBatch.items.length);
    const emptyRows = Array(emptyRowsCount).fill('<tr><td>&nbsp;</td><td></td><td></td><td></td><td></td></tr>').join('');

    doc.open();
    doc.write(`
      <html>
        <head>
          <style>
            @font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); }
            body { font-family: 'StandardKai', serif; padding: 40px; color: black !important; line-height: 1.2; margin: 0; background: white; }
            .title { text-align: center; font-size: 26pt; font-weight: bold; margin-bottom: 25px; letter-spacing: 2px; color: black; }
            .checkbox-area { display: flex; justify-content: center; gap: 40px; font-size: 16pt; margin-bottom: 25px; font-weight: bold; color: black; }
            .checkbox { width: 22px; height: 22px; border: 2.5px solid black; display: inline-flex; align-items: center; justify-content: center; margin-right: 8px; vertical-align: middle; }
            .dept-row { font-size: 15pt; font-weight: bold; margin-bottom: 10px; display: flex; justify-content: space-between; color: black; }
            .dots { border-bottom: 2px dotted black; display: inline-block; min-width: 150px; text-align: center; }
            table { width: 100%; border-collapse: collapse; border: 2.5px solid black; margin-bottom: 25px; color: black; }
            th, td { border: 1.5px solid black; padding: 8px; text-align: center; height: 35px; color: black !important; }
            th { font-size: 14pt; font-weight: bold; background: #f0f0f0; }
            .footer-row { font-size: 14pt; font-weight: bold; margin-top: 30px; color: black; }
            .sig-area { display: flex; justify-content: space-between; margin-top: 45px; font-size: 13pt; color: black; }
            @media print { .no-print { display: none; } body { padding: 20px; } }
          </style>
        </head>
        <body>
          <div style="text-align:right; font-size: 9pt; color: #666;">單號：${lastTransactionBatch.id}</div>
          <div class="title">台灣電力公司電力修護處南部分處</div>
          <div class="checkbox-area">
            <div><span class="checkbox">${isEquip ? 'V' : ''}</span>安全衛生設備借用單</div>
            <div><span class="checkbox">${isConsum ? 'V' : ''}</span>安全衛生類消耗品領用單</div>
          </div>
          <div class="dept-row">
            <div>部 門：<span class="dots" style="min-width: 380px;">${lastTransactionBatch.dept}</span></div>
            <div>${date.getFullYear() - 1911} 年 ${date.getMonth() + 1} 月 ${date.getDate()} 日</div>
          </div>
          <table>
            <thead>
              <tr><th style="width:35%">名　　　稱</th><th style="width:25%">規　範（序　號）</th><th style="width:10%">單 位</th><th style="width:10%">數 量</th><th style="width:20%">備　　註</th></tr>
            </thead>
            <tbody>${rows}${emptyRows}</tbody>
          </table>
          <div class="footer-row">
            <div style="display: flex; justify-content: space-between;">
              <div style="flex:1">申請部門：<span class="dots" style="min-width: 280px;"></span></div>
              <div style="flex:1">經管部門：</div>
            </div>
            <div class="sig-area">
              <div style="flex:1; display:flex; justify-content:space-between; padding-right: 50px;">
                <span>經辦：</span><span>課長：</span><span>經理：</span>
              </div>
              <div style="flex:1; display:flex; justify-content:space-between; padding-left: 10px;">
                <span>經辦：</span><span>課長：</span><span>經理：</span>
              </div>
            </div>
          </div>
        </body>
      </html>
    `);
    doc.close();
    setTimeout(() => {
      printFrameRef.current?.contentWindow?.focus();
      printFrameRef.current?.contentWindow?.print();
    }, 500);
  };

  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = {
      name: formData.get('name') as string,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
    };
    if (!data.name.trim()) return window.alert('名稱不可為空');
    if (editTarget) {
      setItems(prev => prev.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i));
      setEditTarget(null);
    } else {
      setItems(prev => [...prev, { id: generateId(), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: Date.now() }]);
      setShowAddModal(false);
    }
  };

  const confirmDelete = () => {
    if (deleteTarget) {
      setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
      setDeleteTarget(null);
    }
  };

  const stats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    return {
      total: invItems.length,
      low: invItems.filter(i => i.quantity <= i.minStock).length,
      logsCount: logs.filter(l => l.type === 'OUT' && new Date(l.timestamp).getMonth() === new Date().getMonth()).length
    };
  }, [items, logs]);

  return (
    <div className="min-h-screen flex bg-slate-100 text-black font-sans">
      <style>{`
        /* 【核心修復：強制黑色與 UI 可見度】 */
        input, select, textarea { 
          color: #000000 !important; 
          background-color: #ffffff !important; 
          border: 2px solid #94a3b8 !important;
          font-weight: 700 !important; 
        }

        /* 【日期選擇器指示器強制顯示】 */
        input[type="date"]::-webkit-calendar-picker-indicator {
          background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="black" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"></rect><line x1="16" y1="2" x2="16" y2="6"></line><line x1="8" y1="2" x2="8" y2="6"></line><line x1="3" y1="10" x2="21" y2="10"></line></svg>');
          cursor: pointer;
          filter: invert(0);
          opacity: 1;
        }

        .text-deep-black { color: #000000 !important; }
        .table-cell-black { color: #000000 !important; font-weight: bold; }

        /* 表格內文字強制顯影 */
        th, td { color: #000000 !important; }
      `}</style>

      <iframe ref={printFrameRef} className="hidden" title="print-frame" />

      <aside className="w-64 bg-slate-900 text-white p-6 flex flex-col shrink-0">
        <div className="flex items-center gap-3 mb-10">
          <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22}/></div>
          <h1 className="font-black text-xl tracking-tight">工安管理系統</h1>
        </div>
        <nav className="flex-1 space-y-1">
          {[
            { id: 'inventory', label: '工安耗材管理', icon: Package },
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
            { id: 'issuance', label: '領用補貨作業', icon: FileText },
            { id: 'history', label: '歷史異動日誌', icon: History },
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard },
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}><tab.icon size={20} /> {tab.label}</button>
          ))}
        </nav>
      </aside>

      <main className="flex-1 p-10 overflow-y-auto bg-slate-100">
        <header className="mb-8 flex justify-between items-center">
