            {aiInsights && <div className="bg-white p-10 rounded-[2.5rem] border-2 border-blue-100 text-black text-xl font-bold whitespace-pre-wrap leading-relaxed shadow-lg animate-in slide-in-from-bottom-2">{aiInsights}</div>}
