                  <div><label className="text-xs font-black text-orange-600 tracking-widest">警戒水位</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl mt-2 text-black" defaultValue={editTarget?.minStock || 5} /></div>
                </div>
                <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-2xl shadow-xl hover:bg-blue-700 active:scale-95 transition-all mt-6">儲存並建立資料</button>
              </form>
            </div>
          </div>
        )}

        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm z-[400] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] p-10 text-center max-w-sm shadow-2xl"><div className="w-20 h-20 bg-red-50 text-red-600 rounded-full flex items-center justify-center mx-auto mb-6"><AlertTriangle size={48} /></div><h3 className="text-2xl font-black mb-2 text-black">確定刪除項目？</h3><p className="text-slate-500 font-bold mb-10 leading-relaxed">「{deleteTarget.name}」及其歷史異動紀錄將從資料庫中永久抹除。</p><div className="flex flex-col gap-3"><button onClick={confirmDelete} className="w-full py-4 bg-red-600 text-white rounded-xl font-black text-lg shadow-lg">確認刪除</button><button onClick={()=>setDeleteTarget(null)} className="w-full py-4 bg-slate-100 text-slate-400 rounded-xl font-bold">返回</button></div></div>
