interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  const printFrameRef = useRef<HTMLIFrameElement>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const getReservedQty = (itemId: string) => {
    return basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);
  };

  const currentAvailable = useMemo(() => {
    if (!selectedItemId) return 0;
    const item = items.find(i => i.id === selectedItemId);
    if (!item) return 0;
    return item.quantity - getReservedQty(selectedItemId);
  }, [selectedItemId, items, basket]);

  const isQtyOver = useMemo(() => {
    if (issuanceMode === 'IN') return false;
    const qty = Number(inputQty);
    return !isNaN(qty) && qty > currentAvailable;
  }, [inputQty, currentAvailable, issuanceMode]);

  const addToBasket = () => {
    if (!selectedItemId || isQtyOver) return;
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;
    const qty = Number(inputQty);
    if (isNaN(qty) || qty <= 0) return;

    setBasket(prev => [
      ...prev,
      {
        itemId: targetItem.id,
        name: targetItem.name,
        quantity: qty,
        unit: targetItem.unit,
        spec: targetItem.spec,
        itemType: targetItem.itemType
      }
    ]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const timestamp = Date.now();
    const batchId = generateId();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(bItem => {
      updatedItems = updatedItems.map(item => {
        if (item.id === bItem.itemId) {
          const newQty = issuanceMode === 'IN' ? item.quantity + bItem.quantity : item.quantity - bItem.quantity;
          return { ...item, quantity: newQty, lastUpdated: timestamp };
        }
        return item;
      });
      newLogs.push({
        id: generateId() + Math.random().toString(36).substr(2, 4),
        itemId: bItem.itemId,
        itemName: bItem.name,
        type: issuanceMode,
        quantity: bItem.quantity,
        person: inputPerson || '未填寫',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: inputReason,
        timestamp: timestamp
      });
    });

    setItems(updatedItems);
    setLogs(prev => [...newLogs, ...prev]);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({
        id: batchId,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: timestamp
      });
      setShowPrintModal(true);
    } else {
      window.alert(`✅ 入庫成功。`);
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  const handlePrint = () => {
    if (!lastTransactionBatch || !printFrameRef.current) return;
    const doc = printFrameRef.current.contentDocument;
    if (!doc) return;

    const date = new Date(lastTransactionBatch.timestamp);
    const isEquip = lastTransactionBatch.items.some(it => it.itemType === 'EQUIPMENT');
    const isConsum = lastTransactionBatch.items.every(it => it.itemType === 'CONSUMABLE') || !isEquip;

    const rows = lastTransactionBatch.items.map(item => `
      <tr>
        <td style="text-align:left; color:black;">${item.name}</td>
        <td style="color:black;">${item.spec || ''}</td>
        <td style="color:black;">${item.unit}</td>
        <td style="font-size:18pt; font-weight:bold; color:black;">${item.quantity}</td>
        <td style="color:black;">${lastTransactionBatch.reason}</td>
      </tr>
    `).join('');
    const emptyRowsCount = Math.max(0, 15 - lastTransactionBatch.items.length);
    const emptyRows = Array(emptyRowsCount).fill('<tr><td>&nbsp;</td><td></td><td></td><td></td><td></td></tr>').join('');

    doc.open();
    doc.write(`
      <html>
        <head>
          <style>
            @font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); }
            body { font-family: 'StandardKai', serif; padding: 40px; color: black !important; line-height: 1.2; margin: 0; background: white; }
            .title { text-align: center; font-size: 26pt; font-weight: bold; margin-bottom: 25px; letter-spacing: 2px; color: black; }
            .checkbox-area { display: flex; justify-content: center; gap: 40px; font-size: 16pt; margin-bottom: 25px; font-weight: bold; color: black; }
            .checkbox { width: 22px; height: 22px; border: 2.5px solid black; display: inline-flex; align-items: center; justify-content: center; margin-right: 8px; vertical-align: middle; }
            .dept-row { font-size: 15pt; font-weight: bold; margin-bottom: 10px; display: flex; justify-content: space-between; color: black; }
            .dots { border-bottom: 2px dotted black; display: inline-block; min-width: 150px; text-align: center; }
            table { width: 100%; border-collapse: collapse; border: 2.5px solid black; margin-bottom: 25px; color: black; }
            th, td { border: 1.5px solid black; padding: 8px; text-align: center; height: 35px; color: black !important; }
            th { font-size: 14pt; font-weight: bold; background: #f0f0f0; }
            .footer-row { font-size: 14pt; font-weight: bold; margin-top: 30px; color: black; }
            .sig-area { display: flex; justify-content: space-between; margin-top: 45px; font-size: 13pt; color: black; }
            @media print { .no-print { display: none; } body { padding: 20px; } }
          </style>
        </head>
        <body>
          <div style="text-align:right; font-size: 9pt; color: #666;">單號：${lastTransactionBatch.id}</div>
          <div class="title">台灣電力公司電力修護處南部分處</div>
          <div class="checkbox-area">
            <div><span class="checkbox">${isEquip ? 'V' : ''}</span>安全衛生設備借用單</div>
            <div><span class="checkbox">${isConsum ? 'V' : ''}</span>安全衛生類消耗品領用單</div>
          </div>
          <div class="dept-row">
            <div>部 門：<span class="dots" style="min-width: 380px;">${lastTransactionBatch.dept}</span></div>
            <div>${date.getFullYear() - 1911} 年 ${date.getMonth() + 1} 月 ${date.getDate()} 日</div>
          </div>
          <table>
            <thead>
              <tr><th style="width:35%">名　　　稱</th><th style="width:25%">規　範（序　號）</th><th style="width:10%">單 位</th><th style="width:10%">數 量</th><th style="width:20%">備　　註</th></tr>
            </thead>
            <tbody>${rows}${emptyRows}</tbody>
          </table>
          <div class="footer-row">
            <div style="display: flex; justify-content: space-between;">
              <div style="flex:1">申請部門：<span class="dots" style="min-width: 280px;"></span></div>
              <div style="flex:1">經管部門：</div>
            </div>
            <div class="sig-area">
              <div style="flex:1; display:flex; justify-content:space-between; padding-right: 50px;">
                <span>經辦：</span><span>課長：</span><span>經理：</span>
              </div>
              <div style="flex:1; display:flex; justify-content:space-between; padding-left: 10px;">
                <span>經辦：</span><span>課長：</span><span>經理：</span>
              </div>
            </div>
          </div>
        </body>
      </html>
    `);
    doc.close();
    setTimeout(() => {
      printFrameRef.current?.contentWindow?.focus();
      printFrameRef.current?.contentWindow?.print();
    }, 500);
  };

  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = {
      name: formData.get('name') as string,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
    };
    if (!data.name.trim()) return window.alert('名稱不可為空');
    if (editTarget) {
      setItems(prev => prev.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i));
      setEditTarget(null);
    } else {
      setItems(prev => [...prev, { id: generateId(), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: Date.now() }]);
      setShowAddModal(false);
    }
  };

  const confirmDelete = () => {
    if (deleteTarget) {
      setItems(prev => prev.filter(item => item.id !== deleteTarget.id));
      setDeleteTarget(null);
    }
  };

  const stats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    const medItems = items.filter(i => i.itemGroup === 'MEDICINE');

    // 部門領用統計
    const deptMap: Record<string, number> = {};
    logs.filter(l => l.type === 'OUT').forEach(log => {
      deptMap[log.dept] = (deptMap[log.dept] || 0) + log.quantity;
    });
    const sortedDeptStats = Object.entries(deptMap).sort((a, b) => b[1] - a[1]);

    return {
      inv: {
        total: invItems.length,
        low: invItems.filter(i => i.quantity <= i.minStock).length
      },
      med: {
        total: medItems.length,
        low: medItems.filter(i => i.quantity <= i.minStock).length
      },
      deptStats: sortedDeptStats,
      logsCount: logs.filter(l => l.type === 'OUT' && new Date(l.timestamp).getMonth() === new Date().getMonth()).length
    };
  }, [items, logs]);

  return (
    <div className="min-h-screen flex bg-slate-100 text-black font-sans">
      <style>{`
        input, select, textarea { 
          color: #000000 !important; 
          background-color: #ffffff !important; 
          border: 2px solid #94a3b8 !important;
          font-weight: 700 !important; 
        }

        input[type="date"]::-webkit-calendar-picker-indicator {
          background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="black" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"></rect><line x1="16" y1="2" x2="16" y2="6"></line><line x1="8" y1="2" x2="8" y2="6"></line><line x1="3" y1="10" x2="21" y2="10"></line></svg>');
          cursor: pointer;
          filter: invert(0);
          opacity: 1;
        }

        .text-deep-black { color: #000000 !important; }
        .table-cell-black { color: #000000 !important; font-weight: bold; }
        th, td { color: #000000 !important; }
      `}</style>

      <iframe ref={printFrameRef} className="hidden" title="print-frame" />

      <aside className="w-64 bg-slate-900 text-white p-6 flex flex-col shrink-0">
        <div className="flex items-center gap-3 mb-10">
          <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22}/></div>
          <h1 className="font-black text-xl tracking-tight">工安管理系統</h1>
        </div>
        <nav className="flex-1 space-y-1">
          {[
            { id: 'inventory', label: '工安耗材管理', icon: Package },
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
            { id: 'issuance', label: '領用補貨作業', icon: FileText },
            { id: 'history', label: '歷史異動日誌', icon: History },
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard },
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}><tab.icon size={20} /> {tab.label}</button>
          ))}
        </nav>
      </aside>

      <main className="flex-1 p-10 overflow-y-auto bg-slate-100">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-3xl font-black text-black">{activeTab === 'inventory' ? '工安耗材清冊' : activeTab === 'medicine' ? '急救藥材清冊' : activeTab === 'issuance' ? '領用 / 補貨登記' : activeTab === 'history' ? '歷史異動日誌' : '數據統計看板'}</h2>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-black shadow-xl"><Plus size={18}/> 新增項目</button>
          )}
        </header>

        {activeTab === 'issuance' && (
          <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
            <div className="lg:col-span-2 bg-white p-8 rounded-3xl shadow-xl border border-slate-200">
              <h3 className="text-xl font-black mb-8 flex items-center gap-2 text-black"><ShoppingCart className="text-blue-500"/> 1. 挑選項目</h3>
              <div className="flex bg-slate-100 p-1 rounded-xl mb-6">
                <button onClick={()=>{setIssuanceMode('OUT'); setBasket([]);}} className={`flex-1 py-3 rounded-lg font-black transition-all ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button>
                <button onClick={()=>{setIssuanceMode('IN'); setBasket([]);}} className={`flex-1 py-3 rounded-lg font-black transition-all ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
              </div>
              <div className="space-y-6">
                <div><label className="text-xs font-black text-slate-500 uppercase tracking-widest">項目分類</label>
                  <div className="flex gap-2 mt-2">
                    <button onClick={()=>setIssuanceGroup('INVENTORY')} className={`flex-1 py-3 rounded-xl font-black border-2 ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-200 text-slate-400'}`}>耗材類</button>
                    <button onClick={()=>setIssuanceGroup('MEDICINE')} className={`flex-1 py-3 rounded-xl font-black border-2 ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-200 text-slate-400'}`}>藥材類</button>
                  </div>
                </div>
                <div><label className="text-xs font-black text-slate-500 uppercase tracking-widest">物資選擇</label>
                  <select className="w-full p-4 rounded-xl mt-2 text-lg" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                    <option value="">-- 請選擇品項 --</option>
                    {items.filter(i => i.itemGroup === issuanceGroup).map(i => {
                      const avail = i.quantity - getReservedQty(i.id);
                      const label = issuanceMode === 'OUT' ? `${i.name} (剩餘: ${avail})` : `${i.name} (庫存: ${i.quantity})`;
                      return <option key={i.id} value={i.id} className={avail <= 0 && issuanceMode === 'OUT' ? 'text-red-500' : 'text-black'}>{label}</option>;
                    })}
                  </select>
                </div>
                <div><label className="text-xs font-black text-slate-500 uppercase tracking-widest">數量</label><input type="number" min="1" className="w-full p-4 rounded-xl mt-2 text-xl" value={inputQty} onChange={e=>setInputQty(e.target.value)}/>
                  {isQtyOver && <p className="text-red-600 text-xs font-black mt-2">⚠️ 數量超過現有可用庫存 ({currentAvailable})</p>}
                </div>
                <button onClick={addToBasket} disabled={!selectedItemId || isQtyOver} className={`w-full py-5 rounded-2xl font-black text-xl flex items-center justify-center gap-2 shadow-lg ${!selectedItemId || isQtyOver ? 'bg-slate-200 text-slate-400' : 'bg-slate-900 text-white hover:bg-black'}`}><Plus size={20}/> 加入待處理清單</button>
              </div>
            </div>

            <div className="lg:col-span-3 bg-white p-8 rounded-3xl shadow-xl border border-slate-200 flex flex-col">
              <h3 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><FileText className="text-emerald-500"/> 2. 待處理清單</h3>
              <div className="flex-1 overflow-y-auto border-2 border-dashed border-slate-100 rounded-2xl mb-6 min-h-[250px] bg-slate-50">
                {basket.length > 0 ? (
                  <table className="w-full text-left">
                    <thead className="bg-slate-100 text-[11px] font-black text-slate-500 uppercase border-b"><tr><th className="px-6 py-4">品項名稱規格</th><th className="px-6 py-4 text-center">數量</th><th className="px-6 py-4 text-right">管理</th></tr></thead>
                    <tbody className="divide-y divide-slate-100">
                      {basket.map((b, idx) => (
                        <tr key={idx} className="bg-white">
                          <td className="px-6 py-5 font-black text-black text-base">{b.name}</td>
                          <td className="px-6 py-5 text-center font-black text-blue-700 text-xl">{b.quantity} {b.unit}</td>
                          <td className="px-6 py-5 text-right"><button onClick={()=>setBasket(prev => prev.filter((_, i) => i !== idx))} className="text-slate-300 hover:text-red-600 transition-colors"><X size={20}/></button></td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                ) : (<div className="h-full flex flex-col items-center justify-center text-slate-300 font-bold opacity-30"><ShoppingCart size={48} className="mb-4"/><p className="text-xl">目前清單內無物資</p></div>)}
              </div>
              {issuanceMode === 'OUT' && (
                <div className="grid grid-cols-2 gap-6 mb-6">
                  <div><label className="text-xs font-black text-slate-500 uppercase">領用部門</label><select className="w-full p-3 rounded-xl mt-2 text-black" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>{DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}</select></div>
                  <div><label className="text-xs font-black text-slate-500 uppercase">領用人姓名 (選填)</label><input type="text" className="w-full p-3 rounded-xl mt-2 text-black" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div>
                  <div className="col-span-2"><label className="text-xs font-black text-slate-500 uppercase">用途說明 / 備註</label><input type="text" className="w-full p-3 rounded-xl mt-2 text-black" value={inputReason} onChange={e=>setInputReason(e.target.value)}/></div>
                </div>
              )}
              <button onClick={processIssuance} disabled={basket.length === 0} className={`w-full py-6 rounded-2xl font-black text-3xl shadow-2xl transition-all active:scale-95 text-white ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>
                {issuanceMode === 'OUT' ? '確認領用並列印單據' : '確認物資補貨入庫'}
              </button>
            </div>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-10">
            {/* 分組數據卡片 */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              <div className="bg-white p-6 rounded-2xl shadow border-l-8 border-blue-500">
                <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">工安耗材總數</p>
                <h3 className="text-4xl font-black mt-2 text-black">{stats.inv.total}</h3>
              </div>
              <div className="bg-white p-6 rounded-2xl shadow border-l-8 border-red-500">
                <p className="text-red-500 text-[10px] font-black uppercase tracking-widest">耗材低水位</p>
                <h3 className="text-4xl font-black text-red-600 mt-2">{stats.inv.low}</h3>
              </div>
              <div className="bg-white p-6 rounded-2xl shadow border-l-8 border-emerald-500">
                <p className="text-emerald-500 text-[10px] font-black uppercase tracking-widest">急救藥材總數</p>
                <h3 className="text-4xl font-black text-emerald-600 mt-2">{stats.med.total}</h3>
              </div>
              <div className="bg-white p-6 rounded-2xl shadow border-l-8 border-orange-500">
                <p className="text-orange-500 text-[10px] font-black uppercase tracking-widest">藥材低水位</p>
                <h3 className="text-4xl font-black text-orange-600 mt-2">{stats.med.low}</h3>
              </div>
            </div>

            {/* 部門領用排行 */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
              <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-slate-200">
                <h4 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><Users className="text-blue-500"/> 各部門領用量統計</h4>
                <div className="space-y-4 max-h-[400px] overflow-y-auto pr-2">
                  {stats.deptStats.length > 0 ? stats.deptStats.map(([dept, count], idx) => (
                    <div key={dept} className="flex items-center gap-4 bg-slate-50 p-4 rounded-xl border border-slate-100">
