                </div>
                <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-2xl shadow-xl hover:bg-blue-700 active:scale-95 transition-all mt-6">儲存並建立資料</button>
              </form>
            </div>
          </div>
        )}

        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm z-[400] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] p-10 text-center max-w-sm shadow-2xl"><div className="w-20 h-20 bg-red-50 text-red-600 rounded-full flex items-center justify-center mx-auto mb-6"><AlertTriangle size={48} /></div><h3 className="text-2xl font-black mb-2 text-black">確定刪除項目？</h3><p className="text-slate-500 font-bold mb-10 leading-relaxed">「{deleteTarget.name}」及其歷史異動紀錄將從資料庫中永久抹除。</p><div className="flex flex-col gap-3"><button onClick={confirmDelete} className="w-full py-4 bg-red-600 text-white rounded-xl font-black text-lg shadow-lg">確認刪除</button><button onClick={()=>setDeleteTarget(null)} className="w-full py-4 bg-slate-100 text-slate-400 rounded-xl font-bold">返回</button></div></div>
          </div>
        )}

        {showPrintModal && lastTransactionBatch && (
          <div className="fixed inset-0 bg-slate-900/95 z-[500] flex flex-col items-center justify-center p-6">
            <div className="bg-white rounded-[3rem] w-full max-w-5xl h-[90vh] shadow-2xl flex flex-col overflow-hidden">
              <div className="p-8 flex justify-between items-center border-b bg-white relative z-10 shadow-sm">
                 <div className="flex items-center gap-4"><CheckCircle2 className="text-emerald-500" size={40}/><h3 className="font-black text-2xl text-black">已生成領用單 (請預覽完整格式)</h3></div>
                 <div className="flex gap-4">
                    <button onClick={handlePrint} className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black text-2xl shadow-2xl hover:scale-105 active:scale-95 transition-all flex items-center gap-3"><Printer size={28}/> 執行列印</button>
                    <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-2xl text-black hover:bg-slate-200"><X size={32}/></button>
                 </div>
              </div>
              <div className="flex-1 bg-slate-100 p-10 overflow-y-auto shadow-inner flex justify-center">
                 <div className="bg-white shadow-2xl p-6 border rounded-sm origin-top mb-10">
                    <div style={{width:'210mm', minHeight:'297mm', padding:'40px', color:'black !important', fontStyle:'serif', background:'white'}}>
                       <div style={{textAlign:'right', fontSize:'9pt', color:'#999'}}>單號：{lastTransactionBatch.id}</div>
                       <h1 style={{textAlign:'center', fontSize:'24pt', fontWeight:'bold', marginBottom:'25px', color:'black'}}>台灣電力公司電力修護處南部分處</h1>
                       <div style={{display:'flex', justifyContent:'center', gap:'40px', fontSize:'15pt', marginBottom:'25px', fontWeight:'bold', color:'black'}}>
                         <div><span style={{border:'2px solid black', width:'20px', height:'20px', display:'inline-flex', alignItems:'center', justifySelf:'center', marginRight:'8px', verticalAlign:'middle'}}>{lastTransactionBatch.items.some(it => it.itemType === 'EQUIPMENT') ? 'V' : ''}</span> 安全衛生設備借用單</div>
                         <div><span style={{border:'2px solid black', width:'20px', height:'20px', display:'inline-flex', alignItems:'center', justifySelf:'center', marginRight:'8px', verticalAlign:'middle'}}>{lastTransactionBatch.items.every(it => it.itemType === 'CONSUMABLE') ? 'V' : ''}</span> 安全衛生類消耗品領用單</div>
                       </div>
                       <div style={{display:'flex', justifyContent:'space-between', marginBottom:'15px', fontWeight:'bold', fontSize:'14pt', color:'black'}}>
                         <div style={{display:'flex', alignItems:'center'}}>部 門：<span style={{borderBottom:'1.5px dotted black', minWidth:'350px', display:'inline-block', textAlign:'center'}}>{lastTransactionBatch.dept}</span></div>
                         <div>{new Date(lastTransactionBatch.timestamp).getFullYear() - 1911} 年 {new Date(lastTransactionBatch.timestamp).getMonth() + 1} 月 {new Date(lastTransactionBatch.timestamp).getDate()} 日</div>
                       </div>
                       <table style={{width:'100%', borderCollapse:'collapse', border:'2px solid black', color:'black'}}>
                          <thead><tr style={{background:'#eee'}}><th style={{border:'1.5px solid black', padding:'10px', color:'black'}}>名　　　稱</th><th style={{border:'1.5px solid black', padding:'10px', color:'black'}}>規　範（序　號）</th><th style={{border:'1.5px solid black', padding:'10px', color:'black'}}>單 位</th><th style={{border:'1.5px solid black', padding:'10px', color:'black'}}>數 量</th><th style={{border:'1.5px solid black', padding:'10px', color:'black'}}>備　　註</th></tr></thead>
                          <tbody>
                            {lastTransactionBatch.items.map((it, i) => (<tr key={i}><td style={{border:'1.5px solid black', padding:'12px', textAlign:'left', color:'black'}}>{it.name}</td><td style={{border:'1.5px solid black', color:'black'}}>{it.spec}</td><td style={{border:'1.5px solid black', color:'black'}}>{it.unit}</td><td style={{border:'1.5px solid black', fontWeight:'bold', fontSize:'16pt', color:'black'}}>{it.quantity}</td><td style={{border:'1.5px solid black', color:'black'}}>{lastTransactionBatch.reason}</td></tr>))}
                            {Array(Math.max(0, 15 - lastTransactionBatch.items.length)).fill(0).map((_, i) => (<tr key={i + 100}><td style={{border:'1.5px solid black', height:'35px'}}>&nbsp;</td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td></tr>))}
                          </tbody>
                       </table>
                       <div style={{marginTop:'35px', fontWeight:'bold', fontSize:'13pt', color:'black'}}>
                         <div style={{display:'flex', justifyContent:'space-between'}}>
                           <div style={{flex:1}}>申請部門：<span style={{borderBottom:'1.5px dotted black', minWidth:'250px', display:'inline-block'}}></span></div>
                           <div style={{flex:1}}>經管部門：</div>
                         </div>
                         <div style={{display:'flex', justifyContent:'space-between', marginTop:'45px', fontSize:'12pt'}}>
                           <div style={{flex:1, display:'flex', justifyContent:'space-between', paddingRight:'50px'}}><span>經辦：</span><span>課長：</span><span>經理：</span></div>
                           <div style={{flex:1, display:'flex', justifyContent:'space-between', paddingLeft:'10px'}}><span>經辦：</span><span>課長：</span><span>經理：</span></div>
