                     <p className="text-slate-400 text-sm mt-1 font-bold">由 Gemini 提供基於目前庫存的專業採購建議。</p>
                     <button onClick={async () => { setIsAiLoading(true); setAiInsights(await getInventoryInsights(items)); setIsAiLoading(false); }} className="w-full mt-6 py-4 bg-blue-600 text-white rounded-2xl font-black text-lg hover:bg-blue-500 transition-all shadow-xl">{isAiLoading ? '分析中...' : '生成分析報告'}</button>
