            <div className="p-6 bg-slate-50 border-b flex items-center justify-between"><div className="relative max-w-sm w-full"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="快速搜尋庫存項目..." className="w-full pl-12 pr-4 py-3 rounded-xl font-bold" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} /></div></div>
            <table className="w-full text-left">
              <thead className="bg-slate-100 text-[11px] font-black text-slate-500 uppercase tracking-widest border-b"><tr><th className="px-8 py-5">名稱及規格規範</th><th className="px-8 py-5 text-center">目前庫存</th><th className="px-8 py-5 text-right">資料管理</th></tr></thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(i => (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-8 py-5"><div className="font-black text-black text-lg">{item.name}</div><div className="text-xs text-slate-500 font-bold">規格: {item.spec || '無'} | {item.itemType === 'EQUIPMENT' ? '安全衛生設備' : '安全衛生類消耗品'}</div></td>
