              <div className="flex items-center gap-3">
                <Filter size={18} className="text-blue-500" />
                <span className="font-black text-slate-700">數據篩選</span>
              </div>
              <div className="flex items-center gap-2">
                <label className="text-xs font-black text-slate-400 uppercase">年份</label>
                <select 
                  className="p-2 rounded-lg text-sm min-w-[100px]" 
                  value={statsYearFilter} 
                  onChange={e => setStatsYearFilter(Number(e.target.value))}
                >
                  {yearOptions.map(y => <option key={y} value={y}>{y} 年度</option>)}
                </select>
              </div>
              <div className="flex items-center gap-2">
                <label className="text-xs font-black text-slate-400 uppercase">部門</label>
                <select 
                  className="p-2 rounded-lg text-sm min-w-[150px]" 
                  value={statsDeptFilter} 
                  onChange={e => setStatsDeptFilter(e.target.value)}
