                <p className="text-blue-400 text-xs font-black uppercase tracking-widest">{statsYearFilter} 年度 | {statsDeptFilter === 'ALL' ? '全廠' : statsDeptFilter} 總領用量</p>
                <h3 className="text-5xl font-black mt-2">{stats.filtered.invQty + stats.filtered.medQty} <span className="text-lg">件</span></h3>
              </div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-blue-500">
                <p className="text-slate-400 text-xs font-black uppercase tracking-widest">工安耗材領用</p>
                <h3 className="text-4xl font-black mt-2 text-blue-600">{stats.filtered.invQty} <span className="text-lg text-slate-400">件</span></h3>
                <div className="mt-2 text-xs font-bold text-slate-400 italic">對應您所選的年份與部門</div>
              </div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-emerald-500">
                <p className="text-slate-400 text-xs font-black uppercase tracking-widest">急救藥材領用</p>
                <h3 className="text-4xl font-black mt-2 text-emerald-600">{stats.filtered.medQty} <span className="text-lg text-slate-400">件</span></h3>
                <div className="mt-2 text-xs font-bold text-slate-400 italic">對應您所選的年份與部門</div>
              </div>
            </div>

            {/* 系統庫存現況 (不隨篩選變動) */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mt-10">
              <div className="bg-white p-8 rounded-[2rem] shadow-lg border border-slate-100">
                <h4 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><Users className="text-blue-500"/> {statsYearFilter} 年度各部門領用排行</h4>
                <div className="space-y-3 max-h-[350px] overflow-y-auto pr-2">
                  {stats.deptRanking.length > 0 ? stats.deptRanking.map(([dept, count], idx) => (
                    <div key={dept} className="flex items-center gap-4 bg-slate-50 p-4 rounded-2xl border border-slate-100 hover:bg-white transition-colors">
                      <div className="w-8 h-8 flex items-center justify-center font-black bg-slate-900 text-white rounded-xl text-xs">{idx + 1}</div>
                      <div className="flex-1 font-bold text-slate-700">{dept}</div>
                      <div className="text-right">
                        <span className="font-black text-slate-900 text-lg">{count}</span>
                        <span className="text-[10px] text-slate-400 font-bold ml-1">件</span>
                      </div>
                    </div>
                  )) : (
                    <div className="h-40 flex items-center justify-center text-slate-300 font-bold italic">該年度無任何領用紀錄</div>
                  )}
                </div>
              </div>

              <div className="space-y-6">
                <div className="bg-white p-8 rounded-[2rem] shadow-lg border border-slate-100">
                   <h4 className="text-xl font-black mb-6 text-black flex items-center gap-2"><AlertTriangle className="text-orange-500" /> 目前庫存警戒狀況</h4>
                   <div className="grid grid-cols-2 gap-4">
                      <div className="bg-blue-50 p-5 rounded-2xl">
                         <div className="text-[10px] font-black text-blue-400 uppercase">工安耗材低水位</div>
                         <div className="text-3xl font-black text-blue-600">{stats.sys.invLow} <span className="text-sm">項</span></div>
                      </div>
                      <div className="bg-emerald-50 p-5 rounded-2xl">
                         <div className="text-[10px] font-black text-emerald-400 uppercase">急救藥材低水位</div>
                         <div className="text-3xl font-black text-emerald-600">{stats.sys.medLow} <span className="text-sm">項</span></div>
                      </div>
                   </div>
                   <button onClick={async () => { setIsAiLoading(true); setAiInsights(await getInventoryInsights(items)); setIsAiLoading(false); }} className="w-full mt-6 py-4 bg-slate-900 text-white rounded-2xl font-black text-lg hover:bg-black transition-all flex items-center justify-center gap-2 shadow-xl"><BrainCircuit size={22}/> {isAiLoading ? 'AI 分析中...' : '生成 AI 採購建議報告'}</button>
                </div>
                {aiInsights && (
                  <div className="bg-white p-8 rounded-[2rem] border-l-8 border-blue-600 text-black text-lg font-bold whitespace-pre-wrap leading-relaxed shadow-lg animate-in fade-in duration-500">
                    {aiInsights}
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden">
            <div className="p-6 bg-slate-50 border-b flex items-center justify-between"><div className="relative max-w-sm w-full"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="快速搜尋庫存項目..." className="w-full pl-12 pr-4 py-3 rounded-xl font-bold" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} /></div></div>
            <table className="w-full text-left">
              <thead className="bg-slate-100 text-[11px] font-black text-slate-500 uppercase tracking-widest border-b"><tr><th className="px-8 py-5">名稱及規格規範</th><th className="px-8 py-5 text-center">目前庫存</th><th className="px-8 py-5 text-right">資料管理</th></tr></thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(i => (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-8 py-5"><div className="font-black text-black text-lg">{item.name}</div><div className="text-xs text-slate-500 font-bold">規格: {item.spec || '無'} | {item.itemType === 'EQUIPMENT' ? '安全衛生設備' : '安全衛生類消耗品'}</div></td>
                    <td className="px-8 py-5 text-center"><span className={`px-6 py-2 rounded-xl font-black text-xl shadow-sm ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-emerald-50 text-emerald-600'}`}>{item.quantity} {item.unit}</span></td>
                    <td className="px-8 py-5 text-right"><button onClick={() => setEditTarget(item)} className="p-2 text-slate-400 hover:text-blue-600 transition-colors"><Edit3 size={20}/></button><button onClick={() => setDeleteTarget({id: item.id, name: item.name})} className="p-2 text-slate-400 hover:text-red-600 transition-colors"><Trash2 size={20}/></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-slate-100 text-[11px] font-black text-slate-500 border-b uppercase"><tr><th className="px-6 py-5">時間</th><th className="px-6 py-5">操作類型</th><th className="px-6 py-5">物資項目</th><th className="px-6 py-5">部門 / 經辦</th><th className="px-6 py-5 text-right">補印</th></tr></thead>
