              <div className="p-8 flex justify-between items-center border-b bg-white relative z-10 shadow-sm">
                 <div className="flex items-center gap-4"><CheckCircle2 className="text-emerald-500" size={40}/><h3 className="font-black text-2xl text-black">已生成領用單 (請預覽完整格式)</h3></div>
                 <div className="flex gap-4">
                    <button onClick={handlePrint} className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black text-2xl shadow-2xl hover:scale-105 active:scale-95 transition-all flex items-center gap-3"><Printer size={28}/> 執行列印</button>
                    <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-2xl text-black hover:bg-slate-200"><X size={32}/></button>
