            <button onClick={exportData} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-xs font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><Download size={14}/> 匯出備份檔案</button>
            <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-xs font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><Upload size={14}/> 匯入資料還原</button>
        </div>
      </aside>

      <main className="flex-1 p-10 overflow-y-auto bg-slate-100">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-3xl font-black text-black">{activeTab === 'inventory' ? '工安耗材清冊' : activeTab === 'medicine' ? '急救藥材清冊' : activeTab === 'issuance' ? '領用 / 補貨登記' : activeTab === 'history' ? '歷史異動日誌' : '數據統計看板'}</h2>
