              <div className="flex items-center gap-2"><label className="text-xs font-black text-slate-400 uppercase">年度</label><select className="p-2 rounded-lg text-sm min-w-[100px]" value={statsYearFilter} onChange={e => setStatsYearFilter(Number(e.target.value))}>{yearOptions.map(y => <option key={y} value={y}>{y} 年度</option>)}</select></div>
