              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-emerald-500"><p className="text-slate-400 text-xs font-black uppercase tracking-widest">急救藥材領用量</p><h3 className="text-4xl font-black mt-2 text-emerald-600">{stats.filtered.medQty} <span className="text-lg text-slate-400">件</span></h3></div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
               <div className="bg-white p-8 rounded-[2.5rem] shadow-lg border border-slate-100 flex flex-col"><h4 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><ClipboardList size={22} className="text-blue-500"/> 工安耗材領用明細彙整</h4><div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">{stats.filtered.invDetails.length > 0 ? stats.filtered.invDetails.map((detail, i) => (<div key={i} className="flex items-center justify-between p-4 bg-blue-50/50 rounded-2xl border border-blue-100/50 group hover:bg-blue-50 transition-all"><div className="flex items-center gap-3"><div className="w-2 h-2 rounded-full bg-blue-500"></div><span className="font-bold text-slate-700">{detail.name}</span></div><div className="flex items-center gap-2"><span className="font-black text-blue-700 text-lg">{detail.qty}</span><span className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">件</span></div></div>)) : (<div className="h-40 flex flex-col items-center justify-center text-slate-300 font-bold opacity-40"><Package size={32} className="mb-2"/><p>該時段無耗材領用資料</p></div>)}</div></div>
               <div className="bg-white p-8 rounded-[2.5rem] shadow-lg border border-slate-100 flex flex-col"><h4 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><Stethoscope size={22} className="text-emerald-500"/> 急救藥材領用明細彙整</h4><div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">{stats.filtered.medDetails.length > 0 ? stats.filtered.medDetails.map((detail, i) => (<div key={i} className="flex items-center justify-between p-4 bg-emerald-50/50 rounded-2xl border border-emerald-100/50 group hover:bg-emerald-50 transition-all"><div className="flex items-center gap-3"><div className="w-2 h-2 rounded-full bg-emerald-500"></div><span className="font-bold text-slate-700">{detail.name}</span></div><div className="flex items-center gap-2"><span className="font-black text-emerald-700 text-lg">{detail.qty}</span><span className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">件</span></div></div>)) : (<div className="h-40 flex flex-col items-center justify-center text-slate-300 font-bold opacity-40"><Stethoscope size={32} className="mb-2"/><p>該時段無藥材領用資料</p></div>)}</div></div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mt-6">
              <div className="bg-white p-8 rounded-[2.5rem] shadow-lg border border-slate-100"><h4 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><Users className="text-slate-900"/> {statsYearFilter} 年度各部門領用佔比排行</h4><div className="space-y-3 max-h-[350px] overflow-y-auto pr-2">{stats.deptRanking.length > 0 ? stats.deptRanking.map(([dept, count]: any, idx) => (<div key={dept} className="flex items-center gap-4 bg-slate-50 p-4 rounded-2xl border border-slate-100"><div className="w-8 h-8 flex items-center justify-center font-black bg-slate-900 text-white rounded-xl text-xs">{idx + 1}</div><div className="flex-1 font-bold text-slate-700">{dept}</div><div className="text-right"><span className="font-black text-slate-900 text-lg">{count}</span><span className="text-[10px] text-slate-400 font-bold ml-1">件</span></div></div>)) : (<div className="h-40 flex items-center justify-center text-slate-300 font-bold italic">該年度無任何領用紀錄</div>)}</div></div>
              <div className="space-y-6"><div className="bg-slate-900 p-8 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden h-fit"><div className="relative z-10"><h4 className="text-2xl font-black flex items-center gap-3 text-blue-400"><BrainCircuit size={28}/> 工安管理 AI 核心建議</h4><p className="text-slate-400 text-sm mt-1 font-bold">根據全廠目前庫存狀態與篩選後的異動趨勢進行智慧分析。</p><button onClick={async () => { setIsAiLoading(true); setAiInsights(await getInventoryInsights(items)); setIsAiLoading(false); }} className="w-full mt-6 py-4 bg-blue-600 text-white rounded-2xl font-black text-lg hover:bg-blue-500 transition-all shadow-xl">{isAiLoading ? '分析中...' : '立即生成專業分析報告'}</button></div></div>{aiInsights && (<div className="bg-white p-8 rounded-[2.5rem] border-2 border-blue-50 text-black text-lg font-bold whitespace-pre-wrap leading-relaxed shadow-lg animate-in fade-in duration-500">{aiInsights}</div>)}</div>
            </div>
          </div>
        )}

        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden">
            <div className="p-6 bg-slate-50 border-b flex items-center justify-between"><div className="relative max-w-sm w-full"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="快速搜尋庫存項目..." className="w-full pl-12 pr-4 py-3 rounded-xl font-bold" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} /></div></div>
            <table className="w-full text-left"><thead className="bg-slate-100 text-[11px] font-black text-slate-500 uppercase tracking-widest border-b"><tr><th className="px-8 py-5">名稱及規格規範</th><th className="px-8 py-5 text-center">目前庫存</th><th className="px-8 py-5 text-right">資料管理</th></tr></thead><tbody className="divide-y divide-slate-100">{items.filter(i => (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (<tr key={item.id} className="hover:bg-slate-50 transition-colors"><td className="px-8 py-5"><div className="font-black text-black text-lg">{item.name}</div><div className="text-xs text-slate-500 font-bold">規格: {item.spec || '無'} | {item.itemType === 'EQUIPMENT' ? '安全衛生設備' : '安全衛生類消耗品'}</div></td><td className="px-8 py-5 text-center"><span className={`px-6 py-2 rounded-xl font-black text-xl shadow-sm ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-emerald-50 text-emerald-600'}`}>{item.quantity} {item.unit}</span></td><td className="px-8 py-5 text-right"><button onClick={() => setEditTarget(item)} className="p-2 text-slate-400 hover:text-blue-600 transition-colors"><Edit3 size={20}/></button><button onClick={() => setDeleteTarget({id: item.id, name: item.name})} className="p-2 text-slate-400 hover:text-red-600 transition-colors"><Trash2 size={20}/></button></td></tr>))}</tbody></table>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden">
            <table className="w-full text-left"><thead className="bg-slate-100 text-[11px] font-black text-slate-500 border-b uppercase"><tr><th className="px-6 py-5">時間</th><th className="px-6 py-5">操作類型</th><th className="px-6 py-5">物資項目</th><th className="px-6 py-5">部門 / 經辦</th><th className="px-6 py-5 text-right">補印</th></tr></thead><tbody className="divide-y divide-slate-100">{logs.map(log => (<tr key={log.id} className="hover:bg-slate-50"><td className="px-6 py-5 text-xs font-black text-slate-400">{new Date(log.timestamp).toLocaleString()}</td><td className="px-6 py-5"><span className={`px-3 py-1 rounded-full text-[10px] font-black ${log.type === 'OUT' ? 'bg-blue-100 text-blue-600' : 'bg-emerald-100 text-emerald-600'}`}>{log.type === 'OUT' ? '領用' : '補貨'}</span></td><td className="px-6 py-5 font-black text-black">{log.itemName} (x{log.quantity})</td><td className="px-6 py-5 text-xs font-black text-slate-600">{log.dept} / {log.person}</td><td className="px-6 py-5 text-right"><button onClick={()=>{ setLastTransactionBatch({id: log.id, dept: log.dept, person: log.person, reason: log.reason, items: [{itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '個', spec: '', itemType: 'CONSUMABLE'}], timestamp: log.timestamp}); setShowPrintModal(true); }} className="text-slate-400 hover:text-blue-600"><Printer size={20}/></button></td></tr>))}</tbody></table>
          </div>
        )}

        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl"><div className="flex justify-between items-center mb-8"><h3 className="text-2xl font-black text-black">{(editTarget ? '編輯項目資料' : '新增管理項目')}</h3><button onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="p-3 hover:bg-slate-100 rounded-full transition-transform hover:rotate-90"><X size={24} className="text-black"/></button></div><form className="space-y-6" onSubmit={handleSaveItem}><div><label className="text-xs font-black text-slate-500 tracking-widest">物資名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl mt-2 text-black" defaultValue={editTarget?.name} /></div><div className="grid grid-cols-2 gap-6"><div><label className="text-xs font-black text-slate-500 tracking-widest">項目性質</label><select name="itemType" className="w-full p-4 rounded-xl mt-2 text-black" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="EQUIPMENT">安全衛生設備</option><option value="CONSUMABLE">安全衛生類消耗品</option></select></div><div><label className="text-xs font-black text-slate-500 tracking-widest">規範 / 序號</label><input name="spec" type="text" className="w-full p-4 rounded-xl mt-2 text-black" defaultValue={editTarget?.spec || ''} /></div></div>{((editTarget?.itemGroup === 'MEDICINE') || (activeTab === 'medicine' && !editTarget)) && (<div className="grid grid-cols-2 gap-6"><div><label className="text-xs font-black text-slate-500 tracking-widest">購入日期</label><input name="purchaseDate" type="date" className="w-full p-4 rounded-xl mt-2 text-black" defaultValue={editTarget?.purchaseDate} /></div><div><label className="text-xs font-black text-red-600 tracking-widest">效期截止日</label><input name="expiryDate" type="date" className="w-full p-4 rounded-xl mt-2 text-black" defaultValue={editTarget?.expiryDate} /></div></div>)}<div className="grid grid-cols-3 gap-6"><div><label className="text-xs font-black text-slate-500 tracking-widest">領用單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl mt-2 text-black" defaultValue={editTarget?.unit || '個'} /></div><div><label className="text-xs font-black text-slate-500 tracking-widest">現有數量</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl mt-2 text-black" defaultValue={editTarget?.quantity || 0} /></div><div><label className="text-xs font-black text-orange-600 tracking-widest">警戒水位</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl mt-2 text-black" defaultValue={editTarget?.minStock || 5} /></div></div><button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-2xl shadow-xl hover:bg-blue-700 transition-all mt-6">儲存並建立資料</button></form></div>
          </div>
        )}

        {showPrintModal && lastTransactionBatch && (
          <div className="fixed inset-0 bg-slate-900/95 z-[500] flex flex-col items-center justify-center p-6">
            <div className="bg-white rounded-[3rem] w-full max-w-5xl h-[90vh] shadow-2xl flex flex-col overflow-hidden">
              <div className="p-8 flex justify-between items-center border-b bg-white relative z-10 shadow-sm">
                 <div className="flex items-center gap-4"><CheckCircle2 className="text-emerald-500" size={40}/><h3 className="font-black text-2xl text-black">領用單預覽 (可點擊執行列印存為 PDF)</h3></div>
                 <div className="flex gap-4">
