        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-slate-100 text-[11px] font-black text-slate-500 uppercase border-b"><tr><th className="px-6 py-5">異動時間</th><th className="px-6 py-5">項目</th><th className="px-6 py-5">部門</th><th className="px-6 py-5 text-right">補印</th></tr></thead>
              <tbody className="divide-y divide-slate-100">{logs.map(log => (<tr key={log.id} className="hover:bg-slate-50"><td className="px-6 py-5 text-xs font-bold text-slate-400">{new Date(log.timestamp).toLocaleString()}</td><td className="px-6 py-5 font-black">{log.itemName} (x{log.quantity})</td><td className="px-6 py-5 font-bold text-slate-600">{log.dept}</td><td className="px-6 py-5 text-right"><button onClick={()=>{ setLastTransactionBatch({id: log.id, dept: log.dept, person: log.person, reason: log.reason, items: [{itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '個', spec: '', itemType: 'CONSUMABLE'}], timestamp: log.timestamp}); setShowPrintModal(true); }} className="text-slate-400 hover:text-blue-600"><Printer size={20}/></button></td></tr>))}</tbody>
            </table>
