            <div className="bg-white rounded-[3rem] w-full max-w-5xl h-[90vh] shadow-2xl flex flex-col overflow-hidden">
              <div className="p-8 flex justify-between items-center border-b bg-white relative z-10 shadow-sm">
                 <div className="flex items-center gap-4"><CheckCircle2 className="text-emerald-500" size={40}/><h3 className="font-black text-2xl text-black">領用單預覽 (請確認無誤後輸出)</h3></div>
                 <div className="flex gap-4">
                    <button onClick={() => handleFinalPrint(false)} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xl shadow-xl hover:scale-105 transition-all flex items-center gap-2"><Printer size={24}/> 直接列印</button>
                    <button onClick={() => handleFinalPrint(true)} className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black text-xl shadow-xl hover:scale-105 transition-all flex items-center gap-2"><FileDown size={24}/> 另存為 PDF</button>
                    <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-2xl text-black hover:bg-slate-200"><X size={32}/></button>
                 </div>
              </div>
              <div className="flex-1 bg-slate-100 p-10 overflow-y-auto flex justify-center shadow-inner">
                 <div className="bg-white shadow-2xl p-6 border rounded-sm origin-top mb-10 scale-90">
                    {/* 紙本預覽內容 */}
                    <div style={{width:'210mm', minHeight:'297mm', padding:'40px', color:'black', background:'white'}}>
                       <div style={{display:'flex', flexDirection:'column', alignItems:'flex-end'}}><div style={{fontSize:'9pt', color:'#666'}}>單號：{lastTransactionBatch.id}</div>{lastTransactionBatch.person ? <div style={{fontSize:'9pt', color:'#ccc', marginTop:'2px'}}>領用人：{lastTransactionBatch.person}</div> : null}</div>
                       <h1 style={{textAlign:'center', fontSize:'24pt', fontWeight:'bold', marginBottom:'25px'}}>台灣電力公司電力修護處南部分處</h1>
                       <div style={{display:'flex', justifyContent:'center', gap:'40px', fontSize:'15pt', marginBottom:'25px', fontWeight:'bold'}}><div><span style={{border:'2px solid black', width:'20px', height:'20px', display:'inline-flex', alignItems:'center', justifyCenter:'center', marginRight:'8px', verticalAlign:'middle'}}>{lastTransactionBatch.items.some(it => it.itemType === 'EQUIPMENT') ? 'V' : ''}</span> 安全衛生設備借用單</div><div><span style={{border:'2px solid black', width:'20px', height:'20px', display:'inline-flex', alignItems:'center', justifyCenter:'center', marginRight:'8px', verticalAlign:'middle'}}>{lastTransactionBatch.items.every(it => it.itemType === 'CONSUMABLE') ? 'V' : ''}</span> 安全衛生類消耗品領用單</div></div>
                       <div style={{display:'flex', justifyContent:'space-between', marginBottom:'15px', fontWeight:'bold', fontSize:'14pt'}}><div style={{display:'flex', alignItems:'center'}}>部 門：<span style={{borderBottom:'1.5px dotted black', minWidth:'350px', display:'inline-block', textAlign:'center'}}>{lastTransactionBatch.dept}</span></div><div>{new Date(lastTransactionBatch.timestamp).getFullYear() - 1911} 年 {new Date(lastTransactionBatch.timestamp).getMonth() + 1} 月 {new Date(lastTransactionBatch.timestamp).getDate()} 日</div></div>
                       <table style={{width:'100%', borderCollapse:'collapse', border:'2px solid black'}}><thead><tr style={{background:'#eee'}}><th style={{padding:'8px', border:'1.5px solid black'}}>名稱</th><th style={{padding:'8px', border:'1.5px solid black'}}>規範</th><th style={{padding:'8px', border:'1.5px solid black'}}>單位</th><th style={{padding:'8px', border:'1.5px solid black'}}>數量</th><th style={{padding:'8px', border:'1.5px solid black'}}>備註</th></tr></thead><tbody>{lastTransactionBatch.items.map((it, i) => (<tr key={i}><td style={{textAlign:'left', padding:'12px', border:'1.5px solid black'}}>{it.name}</td><td style={{border:'1.5px solid black'}}>{it.spec}</td><td style={{border:'1.5px solid black'}}>{it.unit}</td><td style={{fontWeight:'bold', fontSize:'16pt', border:'1.5px solid black'}}>{it.quantity}</td><td style={{border:'1.5px solid black'}}>{lastTransactionBatch.reason}</td></tr>))}{Array(Math.max(0, 15 - lastTransactionBatch.items.length)).fill(0).map((_, i) => (<tr key={i + 100}><td style={{height:'35px', border:'1.5px solid black'}}>&nbsp;</td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td></tr>))}</tbody></table>
                       <div style={{marginTop:'35px', fontWeight:'bold', fontSize:'13pt'}}><div style={{display:'flex', justifyContent:'space-between'}}><div style={{flex:1}}>申請部門：</div><div style={{flex:1}}>經管部門：</div></div><div style={{display:'flex', justifyContent:'space-between', marginTop:'45px', fontSize:'12pt'}}><div style={{flex:1, display:'flex', justifyContent:'space-between', paddingRight:'50px'}}><span>經辦：</span><span>課長：</span><span>經理：</span></div><div style={{flex:1, display:'flex', justifyContent:'space-between', paddingLeft:'10px'}}><span>經辦：</span><span>課長：</span><span>經理：</span></div></div></div>
                    </div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl"><form className="space-y-6" onSubmit={handleSaveItem}><div><label className="text-xs font-black text-slate-500 uppercase">物資名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl mt-2" defaultValue={editTarget?.name} /></div><div className="grid grid-cols-2 gap-6"><div><label className="text-xs font-black text-slate-500">性質</label><select name="itemType" className="w-full p-4 rounded-xl mt-2" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="EQUIPMENT">設備</option><option value="CONSUMABLE">消耗品</option></select></div><div><label className="text-xs font-black text-slate-500">規範</label><input name="spec" type="text" className="w-full p-4 rounded-xl mt-2" defaultValue={editTarget?.spec || ''} /></div></div><div className="grid grid-cols-3 gap-6"><div><label className="text-xs font-black text-slate-500">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl mt-2" defaultValue={editTarget?.unit || '個'} /></div><div><label className="text-xs font-black text-slate-500">庫存</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl mt-2" defaultValue={editTarget?.quantity || 0} /></div><div><label className="text-xs font-black text-slate-500">警戒</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl mt-2" defaultValue={editTarget?.minStock || 5} /></div></div><button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-2xl shadow-xl mt-6">儲存資料</button><button type="button" onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="w-full py-3 text-slate-400 font-bold">取消返回</button></form></div>
          </div>
        )}

        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/90 flex items-center justify-center p-4 z-[400]"><div className="bg-white p-10 rounded-3xl text-center max-w-sm"><h3 className="text-2xl font-black mb-4">確定刪除「{deleteTarget.name}」？</h3><button onClick={()=>{setItems(prev => prev.filter(i => i.id !== deleteTarget.id)); setDeleteTarget(null);}} className="w-full py-4 bg-red-600 text-white rounded-xl font-black mb-2">確認刪除</button><button onClick={()=>setDeleteTarget(null)} className="w-full py-4 text-slate-400 font-bold">取消</button></div></div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  CheckCircle2,
  Users,
  Filter,
  ClipboardList,
  Download,
  Upload,
  FileDown
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [statsDeptFilter, setStatsDeptFilter] = useState<string>('ALL');
  const [statsYearFilter, setStatsYearFilter] = useState<number>(new Date().getFullYear());

  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  // --- 數據同步功能 ---
  const exportData = () => {
    const data = { items, logs, timestamp: Date.now() };
    const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `工安管理系統備份_${new Date().toLocaleDateString().replace(/\//g, '-')}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const importData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (data.items && data.logs) {
          if (window.confirm("確定要導入此備份並同步數據嗎？這將會覆蓋您目前的庫存與異動紀錄。")) {
            setItems(data.items);
            setLogs(data.logs);
            window.alert("✅ 數據同步完成！");
          }
        }
      } catch (err) {
        window.alert("❌ 檔案格式不正確，無法同步。");
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const getReservedQty = (itemId: string) => {
    return basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);
  };

  const currentAvailable = useMemo(() => {
    if (!selectedItemId) return 0;
    const item = items.find(i => i.id === selectedItemId);
    if (!item) return 0;
    return item.quantity - getReservedQty(selectedItemId);
  }, [selectedItemId, items, basket]);

  const isQtyOver = useMemo(() => {
    if (issuanceMode === 'IN') return false;
    const qty = Number(inputQty);
    return !isNaN(qty) && qty > currentAvailable;
  }, [inputQty, currentAvailable, issuanceMode]);

  const addToBasket = () => {
    if (!selectedItemId || isQtyOver) return;
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;
    const qty = Number(inputQty);
    if (isNaN(qty) || qty <= 0) return;

    setBasket(prev => [
      ...prev,
      {
        itemId: targetItem.id,
        name: targetItem.name,
        quantity: qty,
        unit: targetItem.unit,
        spec: targetItem.spec,
        itemType: targetItem.itemType
      }
    ]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const timestamp = Date.now();
    const batchId = generateId();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(bItem => {
      updatedItems = updatedItems.map(item => {
        if (item.id === bItem.itemId) {
          const newQty = issuanceMode === 'IN' ? item.quantity + bItem.quantity : item.quantity - bItem.quantity;
          return { ...item, quantity: newQty, lastUpdated: timestamp };
        }
        return item;
      });
      newLogs.push({
        id: generateId() + Math.random().toString(36).substr(2, 4),
        itemId: bItem.itemId,
        itemName: bItem.name,
        type: issuanceMode,
        quantity: bItem.quantity,
        person: inputPerson || '未填寫',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: inputReason,
        timestamp: timestamp
      });
    });

    setItems(updatedItems);
    setLogs(prev => [...newLogs, ...prev]);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({
        id: batchId,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: timestamp
      });
      setShowPrintModal(true);
    } else {
      window.alert(`✅ 物資已補貨入庫。`);
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  // --- 修復：終極穩定列印邏輯 (彈出視窗法) ---
  const handleFinalPrint = (isPDF: boolean = false) => {
    if (!lastTransactionBatch) return;

    if (isPDF) {
      window.alert("💡 另存 PDF 教學：\n\n點擊確認後將彈出列印視窗，請在「印表機/目的地」下拉選單中選擇「另存為 PDF (Save as PDF)」即可儲存。");
    }

    const date = new Date(lastTransactionBatch.timestamp);
    const isEquip = lastTransactionBatch.items.some(it => it.itemType === 'EQUIPMENT');
    const isConsum = lastTransactionBatch.items.every(it => it.itemType === 'CONSUMABLE') || !isEquip;

    const rowsHtml = lastTransactionBatch.items.map(item => `
      <tr>
        <td style="text-align:left; color:black; padding: 12px;">${item.name}</td>
        <td style="color:black;">${item.spec || ''}</td>
        <td style="color:black;">${item.unit}</td>
        <td style="font-size:18pt; font-weight:bold; color:black;">${item.quantity}</td>
        <td style="color:black;">${lastTransactionBatch.reason}</td>
      </tr>
    `).join('');

    const emptyRowsCount = Math.max(0, 15 - lastTransactionBatch.items.length);
    const emptyRowsHtml = Array(emptyRowsCount).fill('<tr><td style="height:35px;">&nbsp;</td><td></td><td></td><td></td><td></td></tr>').join('');

    // 使用彈出視窗確保絕對可以連動系統列印
    const printWin = window.open('', '_blank', 'width=1100,height=900');
    if (!printWin) {
      alert("❌ 錯誤：瀏覽器封鎖了彈出視窗，請允許彈出視窗以進行列印。");
      return;
    }

    printWin.document.write(`
      <html>
        <head>
          <title>單據列印_${lastTransactionBatch.id}</title>
          <style>
            @font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); }
            body { font-family: 'StandardKai', serif; padding: 40px; color: black !important; background: white; margin: 0; line-height: 1.2; }
            .title { text-align: center; font-size: 26pt; font-weight: bold; margin-bottom: 25px; letter-spacing: 2px; }
            .checkbox-area { display: flex; justify-content: center; gap: 40px; font-size: 16pt; margin-bottom: 25px; font-weight: bold; }
            .checkbox { width: 22px; height: 22px; border: 2.5px solid black; display: inline-flex; align-items: center; justify-content: center; margin-right: 8px; vertical-align: middle; }
            .dept-row { font-size: 15pt; font-weight: bold; margin-bottom: 10px; display: flex; justify-content: space-between; }
            table { width: 100%; border-collapse: collapse; border: 2.5px solid black; margin-bottom: 25px; }
            th, td { border: 1.5px solid black; padding: 8px; text-align: center; color: black !important; }
            th { font-size: 14pt; font-weight: bold; background: #f0f0f0; }
            .footer-row { font-size: 14pt; font-weight: bold; margin-top: 30px; }
            .sig-area { display: flex; justify-content: space-between; margin-top: 45px; font-size: 13pt; }
            @media print { .no-print { display: none; } body { padding: 20px; } }
          </style>
        </head>
        <body>
          <div style="display: flex; flex-direction: column; align-items: flex-end;">
            <div style="font-size: 9pt; color: #666;">單號：${lastTransactionBatch.id}</div>
            ${lastTransactionBatch.person ? `<div style="font-size: 9pt; color: #ccc; margin-top: 2px;">領用人：${lastTransactionBatch.person}</div>` : ''}
          </div>
          <div class="title">台灣電力公司電力修護處南部分處</div>
          <div class="checkbox-area">
            <div><span class="checkbox">${isEquip ? 'V' : ''}</span>安全衛生設備借用單</div>
            <div><span class="checkbox">${isConsum ? 'V' : ''}</span>安全衛生類消耗品領用單</div>
          </div>
          <div class="dept-row">
            <div>部 門：<span style="border-bottom: 2px dotted black; min-width: 350px; display: inline-block; text-align: center;">${lastTransactionBatch.dept}</span></div>
            <div>${date.getFullYear() - 1911} 年 ${date.getMonth() + 1} 月 ${date.getDate()} 日</div>
          </div>
          <table>
            <thead>
              <tr><th style="width:35%">名　　　稱</th><th style="width:25%">規　範（序　號）</th><th style="width:10%">單 位</th><th style="width:10%">數 量</th><th style="width:20%">備　　註</th></tr>
            </thead>
            <tbody>${rowsHtml}${emptyRowsHtml}</tbody>
          </table>
          <div class="footer-row">
            <div style="display: flex; justify-content: space-between;">
              <div style="flex:1">申請部門：</div>
              <div style="flex:1">經管部門：</div>
            </div>
            <div class="sig-area">
              <div style="flex:1; display:flex; justify-content:space-between; padding-right: 50px;">
                <span>經辦：</span><span>課長：</span><span>經理：</span>
              </div>
              <div style="flex:1; display:flex; justify-content:space-between; padding-left: 10px;">
                <span>經辦：</span><span>課長：</span><span>經理：</span>
              </div>
            </div>
          </div>
          <script>
            window.onload = function() {
              setTimeout(function() {
                window.print();
                window.close();
              }, 600);
            };
          </script>
        </body>
      </html>
    `);
    printWin.document.close();
  };

  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = {
      name: formData.get('name') as string,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
    };
    if (editTarget) {
      setItems(prev => prev.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i));
      setEditTarget(null);
    } else {
      setItems(prev => [...prev, { id: generateId(), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: Date.now() }]);
      setShowAddModal(false);
    }
  };

  const stats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    const medItems = items.filter(i => i.itemGroup === 'MEDICINE');
    const filteredLogs = logs.filter(l => {
        const logDate = new Date(l.timestamp);
        const matchesYear = logDate.getFullYear() === statsYearFilter;
        const matchesDept = statsDeptFilter === 'ALL' || l.dept === statsDeptFilter;
        return l.type === 'OUT' && matchesYear && matchesDept;
    });
    const invDetailMap: Record<string, {name: string, qty: number}> = {};
    const medDetailMap: Record<string, {name: string, qty: number}> = {};
    let filteredInvQty = 0;
    let filteredMedQty = 0;
    filteredLogs.forEach(log => {
        const item = items.find(it => it.id === log.itemId);
        const isMedicine = item ? item.itemGroup === 'MEDICINE' : false;
        if (!isMedicine) {
            filteredInvQty += log.quantity;
            if (!invDetailMap[log.itemId]) invDetailMap[log.itemId] = { name: log.itemName, qty: 0 };
            invDetailMap[log.itemId].qty += log.quantity;
        } else {
            filteredMedQty += log.quantity;
            if (!medDetailMap[log.itemId]) medDetailMap[log.itemId] = { name: log.itemName, qty: 0 };
            medDetailMap[log.itemId].qty += log.quantity;
        }
    });
    return {
      sys: { invTotal: invItems.length, medTotal: medItems.length },
      filtered: {
        invQty: filteredInvQty,
        medQty: filteredMedQty,
        invDetails: Object.values(invDetailMap).sort((a, b) => b.qty - a.qty),
        medDetails: Object.values(medDetailMap).sort((a, b) => b.qty - a.qty),
      },
      deptRanking: Object.entries(logs.filter(l => l.type === 'OUT' && new Date(l.timestamp).getFullYear() === statsYearFilter).reduce((acc: any, curr) => {
          acc[curr.dept] = (acc[curr.dept] || 0) + curr.quantity; return acc;
      }, {})).sort((a: any, b: any) => b[1] - a[1])
    };
  }, [items, logs, statsDeptFilter, statsYearFilter]);

  return (
    <div className="min-h-screen flex bg-slate-100 text-black font-sans">
      <style>{`
        input, select, textarea { color: #000000 !important; background-color: #ffffff !important; border: 2px solid #94a3b8 !important; font-weight: 700 !important; }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
      `}</style>

      <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={importData} />

      <aside className="w-64 bg-slate-900 text-white p-6 flex flex-col shrink-0">
        <div className="flex items-center gap-3 mb-10">
          <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22}/></div>
          <h1 className="font-black text-xl tracking-tight">工安管理系統</h1>
        </div>
        <nav className="flex-1 space-y-1">
          {[
            { id: 'inventory', label: '工安耗材管理', icon: Package },
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
            { id: 'issuance', label: '領用補貨作業', icon: FileText },
            { id: 'history', label: '歷史異動日誌', icon: History },
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard },
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}><tab.icon size={20} /> {tab.label}</button>
          ))}
        </nav>
        <div className="pt-6 mt-6 border-t border-slate-800 space-y-2">
            <p className="px-4 text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">同步備份中心</p>
            <button onClick={exportData} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-xs font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><Download size={14}/> 匯出備份</button>
            <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-xs font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><Upload size={14}/> 導入同步</button>
        </div>
      </aside>

      <main className="flex-1 p-10 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-3xl font-black text-black">
            {activeTab === 'inventory' ? '工安耗材清冊' : 
             activeTab === 'medicine' ? '急救藥材清冊' : 
             activeTab === 'issuance' ? '領用 / 補貨登記' : 
             activeTab === 'history' ? '歷史異動日誌' : '數據統計看板'}
          </h2>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-black shadow-xl"><Plus size={18}/> 新增項目</button>
          )}
        </header>

        {activeTab === 'issuance' && (
          <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
            <div className="lg:col-span-2 bg-white p-8 rounded-3xl shadow-xl border border-slate-200">
              <h3 className="text-xl font-black mb-8 flex items-center gap-2 text-black"><ShoppingCart className="text-blue-500"/> 1. 挑選項目</h3>
              <div className="flex bg-slate-100 p-1 rounded-xl mb-6">
                <button onClick={()=>{setIssuanceMode('OUT'); setBasket([]);}} className={`flex-1 py-3 rounded-lg font-black transition-all ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button>
                <button onClick={()=>{setIssuanceMode('IN'); setBasket([]);}} className={`flex-1 py-3 rounded-lg font-black transition-all ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
              </div>
              <div className="space-y-6">
                <div><label className="text-xs font-black text-slate-500 uppercase tracking-widest">分類</label>
                  <div className="flex gap-2 mt-2">
                    <button onClick={()=>setIssuanceGroup('INVENTORY')} className={`flex-1 py-3 rounded-xl font-black border-2 ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-200 text-slate-400'}`}>耗材類</button>
                    <button onClick={()=>setIssuanceGroup('MEDICINE')} className={`flex-1 py-3 rounded-xl font-black border-2 ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-200 text-slate-400'}`}>藥材類</button>
                  </div>
                </div>
                <div><label className="text-xs font-black text-slate-500 uppercase tracking-widest">物資</label>
                  <select className="w-full p-4 rounded-xl mt-2 text-lg" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                    <option value="">-- 請選擇品項 --</option>
                    {items.filter(i => i.itemGroup === issuanceGroup).map(i => {
                      const avail = i.quantity - getReservedQty(i.id);
                      return <option key={i.id} value={i.id}>{i.name} ({issuanceMode === 'OUT' ? `剩餘:${avail}` : `庫存:${i.quantity}`})</option>;
                    })}
                  </select>
                </div>
                <div><label className="text-xs font-black text-slate-500 uppercase tracking-widest">數量</label><input type="number" min="1" className="w-full p-4 rounded-xl mt-2 text-xl" value={inputQty} onChange={e=>setInputQty(e.target.value)}/>{isQtyOver && <p className="text-red-600 text-xs font-black mt-2">⚠️ 超出庫存</p>}</div>
                <button onClick={addToBasket} disabled={!selectedItemId || isQtyOver} className={`w-full py-5 rounded-2xl font-black text-xl flex items-center justify-center gap-2 shadow-lg ${!selectedItemId || isQtyOver ? 'bg-slate-200 text-slate-400' : 'bg-slate-900 text-white hover:bg-black'}`}><Plus size={20}/> 加入待處理清單</button>
              </div>
            </div>
            <div className="lg:col-span-3 bg-white p-8 rounded-3xl shadow-xl border border-slate-200 flex flex-col">
              <h3 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><FileText className="text-emerald-500"/> 2. 待處理清單</h3>
              <div className="flex-1 overflow-y-auto border-2 border-dashed border-slate-100 rounded-2xl mb-6 min-h-[250px] bg-slate-50">
                {basket.length > 0 ? (
                  <table className="w-full text-left">
                    <tbody className="divide-y divide-slate-100">
                      {basket.map((b, idx) => (
                        <tr key={idx} className="bg-white"><td className="px-6 py-5 font-black text-black">{b.name}</td><td className="px-6 py-5 text-center font-black text-blue-700">{b.quantity} {b.unit}</td><td className="px-6 py-5 text-right"><button onClick={()=>setBasket(prev => prev.filter((_, i) => i !== idx))} className="text-slate-300 hover:text-red-600"><X size={20}/></button></td></tr>
                      ))}
                    </tbody>
                  </table>
                ) : (<div className="h-full flex items-center justify-center text-slate-300 font-bold opacity-30">清單目前為空</div>)}
              </div>
              {issuanceMode === 'OUT' && (
                <div className="grid grid-cols-2 gap-6 mb-6">
                  <div><label className="text-xs font-black text-slate-500 uppercase">領用部門</label><select className="w-full p-3 rounded-xl mt-2 text-black" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>{DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}</select></div>
                  <div><label className="text-xs font-black text-slate-500 uppercase">領用人</label><input type="text" className="w-full p-3 rounded-xl mt-2 text-black" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div>
                  <div className="col-span-2"><label className="text-xs font-black text-slate-500 uppercase">備註說明</label><input type="text" className="w-full p-3 rounded-xl mt-2 text-black" value={inputReason} onChange={e=>setInputReason(e.target.value)}/></div>
                </div>
              )}
              <button onClick={processIssuance} disabled={basket.length === 0} className={`w-full py-6 rounded-2xl font-black text-3xl shadow-2xl transition-all active:scale-95 text-white ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>{issuanceMode === 'OUT' ? '確認領用' : '確認入庫'}</button>
            </div>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-200 flex flex-wrap items-center gap-6">
              <div className="flex items-center gap-2"><label className="text-xs font-black text-slate-400">統計年度</label><select className="p-2 rounded-lg text-sm" value={statsYearFilter} onChange={e => setStatsYearFilter(Number(e.target.value))}><option value={new Date().getFullYear()}>{new Date().getFullYear()}</option><option value={2024}>2024</option></select></div>
              <div className="flex items-center gap-2"><label className="text-xs font-black text-slate-400">部門篩選</label><select className="p-2 rounded-lg text-sm" value={statsDeptFilter} onChange={e => setStatsDeptFilter(e.target.value)}><option value="ALL">全廠總覽</option>{DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}</select></div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-slate-900 p-8 rounded-[2rem] text-white shadow-xl"><p className="text-blue-400 text-xs font-black uppercase">總領用量</p><h3 className="text-5xl font-black mt-2">{stats.filtered.invQty + stats.filtered.medQty} 件</h3></div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-blue-500"><p className="text-slate-400 text-xs font-black uppercase">耗材領用</p><h3 className="text-4xl font-black mt-2 text-blue-600">{stats.filtered.invQty}</h3></div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-emerald-500"><p className="text-slate-400 text-xs font-black uppercase">藥材領用</p><h3 className="text-4xl font-black mt-2 text-emerald-600">{stats.filtered.medQty}</h3></div>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-white p-8 rounded-[2.5rem] shadow-lg">
                <h4 className="text-xl font-black mb-6">部門領用佔比排行</h4>
                <div className="space-y-3">{stats.deptRanking.map(([dept, count]: any, idx) => (<div key={dept} className="flex items-center gap-4 bg-slate-50 p-4 rounded-2xl"><div className="w-8 h-8 flex items-center justify-center bg-slate-900 text-white rounded-xl text-xs">{idx + 1}</div><div className="flex-1 font-bold">{dept}</div><div className="font-black">{count} 件</div></div>))}</div>
              </div>
              <div className="space-y-6"><div className="bg-slate-900 p-8 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden h-fit"><h4 className="text-2xl font-black flex items-center gap-3 text-blue-400"><BrainCircuit size={28}/> AI 核心建議報告</h4><button onClick={async () => { setIsAiLoading(true); setAiInsights(await getInventoryInsights(items)); setIsAiLoading(false); }} className="w-full mt-6 py-4 bg-blue-600 text-white rounded-2xl font-black text-lg shadow-xl">{isAiLoading ? '分析中...' : '生成即時分析建議'}</button></div>{aiInsights && (<div className="bg-white p-8 rounded-[2.5rem] border-2 border-blue-50 text-black text-lg font-bold shadow-lg whitespace-pre-wrap leading-relaxed animate-in fade-in">{aiInsights}</div>)}</div>
            </div>
          </div>
        )}

        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-200">
            <div className="p-6 bg-slate-50 border-b flex items-center justify-between"><div className="relative max-w-sm w-full"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="搜尋項目名稱..." className="w-full pl-12 pr-4 py-3 rounded-xl font-bold" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} /></div></div>
            <table className="w-full text-left">
              <thead className="bg-slate-100 text-[11px] font-black text-slate-500 uppercase border-b"><tr><th className="px-8 py-5">名稱及規格</th><th className="px-8 py-5 text-center">目前庫存</th><th className="px-8 py-5 text-right">操作</th></tr></thead>
              <tbody className="divide-y divide-slate-100">{items.filter(i => (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (<tr key={item.id} className="hover:bg-slate-50"><td className="px-8 py-5"><div className="font-black">{item.name}</div><div className="text-xs text-slate-400 font-bold">{item.spec || '無規格'}</div></td><td className="px-8 py-5 text-center"><span className={`px-6 py-2 rounded-xl font-black text-xl ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-emerald-50 text-emerald-600'}`}>{item.quantity} {item.unit}</span></td><td className="px-8 py-5 text-right"><button onClick={() => setEditTarget(item)} className="p-2 text-slate-400 hover:text-blue-600"><Edit3 size={20}/></button><button onClick={() => setDeleteTarget({id: item.id, name: item.name})} className="p-2 text-slate-400 hover:text-red-600"><Trash2 size={20}/></button></td></tr>))}</tbody>
            </table>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-slate-100 text-[11px] font-black text-slate-500 uppercase border-b"><tr><th className="px-6 py-5">異動時間</th><th className="px-6 py-5">項目</th><th className="px-6 py-5">部門</th><th className="px-6 py-5 text-right">補印</th></tr></thead>
              <tbody className="divide-y divide-slate-100">{logs.map(log => (<tr key={log.id} className="hover:bg-slate-50"><td className="px-6 py-5 text-xs font-bold text-slate-400">{new Date(log.timestamp).toLocaleString()}</td><td className="px-6 py-5 font-black">{log.itemName} (x{log.quantity})</td><td className="px-6 py-5 font-bold text-slate-600">{log.dept}</td><td className="px-6 py-5 text-right"><button onClick={()=>{ setLastTransactionBatch({id: log.id, dept: log.dept, person: log.person, reason: log.reason, items: [{itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '個', spec: '', itemType: 'CONSUMABLE'}], timestamp: log.timestamp}); setShowPrintModal(true); }} className="text-slate-400 hover:text-blue-600"><Printer size={20}/></button></td></tr>))}</tbody>
            </table>
          </div>
        )}

        {showPrintModal && lastTransactionBatch && (
          <div className="fixed inset-0 bg-slate-900/95 z-[500] flex flex-col items-center justify-center p-6">
            <div className="bg-white rounded-[3rem] w-full max-w-5xl h-[90vh] shadow-2xl flex flex-col overflow-hidden">
              <div className="p-8 flex justify-between items-center border-b bg-white relative z-10 shadow-sm">
                 <div className="flex items-center gap-4"><CheckCircle2 className="text-emerald-500" size={40}/><h3 className="font-black text-2xl text-black">領用單預覽 (請確認無誤後輸出)</h3></div>
                 <div className="flex gap-4">
                    <button onClick={() => handleFinalPrint(false)} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xl shadow-xl hover:scale-105 transition-all flex items-center gap-2"><Printer size={24}/> 直接列印</button>
                    <button onClick={() => handleFinalPrint(true)} className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black text-xl shadow-xl hover:scale-105 transition-all flex items-center gap-2"><FileDown size={24}/> 另存為 PDF</button>
                    <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-2xl text-black hover:bg-slate-200"><X size={32}/></button>
                 </div>
              </div>
              <div className="flex-1 bg-slate-100 p-10 overflow-y-auto flex justify-center shadow-inner">
                 <div className="bg-white shadow-2xl p-6 border rounded-sm origin-top mb-10 scale-90">
                    {/* 紙本預覽內容 */}
                    <div style={{width:'210mm', minHeight:'297mm', padding:'40px', color:'black', background:'white'}}>
                       <div style={{display:'flex', flexDirection:'column', alignItems:'flex-end'}}><div style={{fontSize:'9pt', color:'#666'}}>單號：{lastTransactionBatch.id}</div>{lastTransactionBatch.person ? <div style={{fontSize:'9pt', color:'#ccc', marginTop:'2px'}}>領用人：{lastTransactionBatch.person}</div> : null}</div>
                       <h1 style={{textAlign:'center', fontSize:'24pt', fontWeight:'bold', marginBottom:'25px'}}>台灣電力公司電力修護處南部分處</h1>
                       {/* Fix: changed justifyCenter to justifyContent in style object below */}
                       <div style={{display:'flex', justifyContent:'center', gap:'40px', fontSize:'15pt', marginBottom:'25px', fontWeight:'bold'}}><div><span style={{border:'2px solid black', width:'20px', height:'20px', display:'inline-flex', alignItems:'center', justifyContent:'center', marginRight:'8px', verticalAlign:'middle'}}>{lastTransactionBatch.items.some(it => it.itemType === 'EQUIPMENT') ? 'V' : ''}</span> 安全衛生設備借用單</div><div><span style={{border:'2px solid black', width:'20px', height:'20px', display:'inline-flex', alignItems:'center', justifyContent:'center', marginRight:'8px', verticalAlign:'middle'}}>{lastTransactionBatch.items.every(it => it.itemType === 'CONSUMABLE') ? 'V' : ''}</span> 安全衛生類消耗品領用單</div></div>
                       <div style={{display:'flex', justifyContent:'space-between', marginBottom:'15px', fontWeight:'bold', fontSize:'14pt'}}><div style={{display:'flex', alignItems:'center'}}>部 門：<span style={{borderBottom:'1.5px dotted black', minWidth:'350px', display:'inline-block', textAlign:'center'}}>{lastTransactionBatch.dept}</span></div><div>{new Date(lastTransactionBatch.timestamp).getFullYear() - 1911} 年 {new Date(lastTransactionBatch.timestamp).getMonth() + 1} 月 {new Date(lastTransactionBatch.timestamp).getDate()} 日</div></div>
                       <table style={{width:'100%', borderCollapse:'collapse', border:'2px solid black'}}><thead><tr style={{background:'#eee'}}><th style={{padding:'8px', border:'1.5px solid black'}}>名稱</th><th style={{padding:'8px', border:'1.5px solid black'}}>規範</th><th style={{padding:'8px', border:'1.5px solid black'}}>單位</th><th style={{padding:'8px', border:'1.5px solid black'}}>數量</th><th style={{padding:'8px', border:'1.5px solid black'}}>備註</th></tr></thead><tbody>{lastTransactionBatch.items.map((it, i) => (<tr key={i}><td style={{textAlign:'left', padding:'12px', border:'1.5px solid black'}}>{it.name}</td><td style={{border:'1.5px solid black'}}>{it.spec}</td><td style={{border:'1.5px solid black'}}>{it.unit}</td><td style={{fontWeight:'bold', fontSize:'16pt', border:'1.5px solid black'}}>{it.quantity}</td><td style={{border:'1.5px solid black'}}>{lastTransactionBatch.reason}</td></tr>))}{Array(Math.max(0, 15 - lastTransactionBatch.items.length)).fill(0).map((_, i) => (<tr key={i + 100}><td style={{height:'35px', border:'1.5px solid black'}}>&nbsp;</td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td></tr>))}</tbody></table>
                       <div style={{marginTop:'35px', fontWeight:'bold', fontSize:'13pt'}}><div style={{display:'flex', justifyContent:'space-between'}}><div style={{flex:1}}>申請部門：</div><div style={{flex:1}}>經管部門：</div></div><div style={{display:'flex', justifyContent:'space-between', marginTop:'45px', fontSize:'12pt'}}><div style={{flex:1, display:'flex', justifyContent:'space-between', paddingRight:'50px'}}><span>經辦：</span><span>課長：</span><span>經理：</span></div><div style={{flex:1, display:'flex', justifyContent:'space-between', paddingLeft:'10px'}}><span>經辦：</span><span>課長：</span><span>經理：</span></div></div></div>
                    </div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl"><form className="space-y-6" onSubmit={handleSaveItem}><div><label className="text-xs font-black text-slate-500 uppercase">物資名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl mt-2" defaultValue={editTarget?.name} /></div><div className="grid grid-cols-2 gap-6"><div><label className="text-xs font-black text-slate-500">性質</label><select name="itemType" className="w-full p-4 rounded-xl mt-2" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="EQUIPMENT">設備</option><option value="CONSUMABLE">消耗品</option></select></div><div><label className="text-xs font-black text-slate-500">規範</label><input name="spec" type="text" className="w-full p-4 rounded-xl mt-2" defaultValue={editTarget?.spec || ''} /></div></div><div className="grid grid-cols-3 gap-6"><div><label className="text-xs font-black text-slate-500">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl mt-2" defaultValue={editTarget?.unit || '個'} /></div><div><label className="text-xs font-black text-slate-500">庫存</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl mt-2" defaultValue={editTarget?.quantity || 0} /></div><div><label className="text-xs font-black text-slate-500">警戒</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl mt-2" defaultValue={editTarget?.minStock || 5} /></div></div><button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-2xl shadow-xl mt-6">儲存資料</button><button type="button" onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="w-full py-3 text-slate-400 font-bold">取消返回</button></form></div>
          </div>
        )}

        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/90 flex items-center justify-center p-4 z-[400]"><div className="bg-white p-10 rounded-3xl text-center max-w-sm"><h3 className="text-2xl font-black mb-4">確定刪除「{deleteTarget.name}」？</h3><button onClick={()=>{setItems(prev => prev.filter(i => i.id !== deleteTarget.id)); setDeleteTarget(null);}} className="w-full py-4 bg-red-600 text-white rounded-xl font-black mb-2">確認刪除</button><button onClick={()=>setDeleteTarget(null)} className="w-full py-4 text-slate-400 font-bold">取消</button></div></div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  CheckCircle2,
  Users,
  Filter,
  ClipboardList,
  Download,
  Upload,
  FileDown
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [statsDeptFilter, setStatsDeptFilter] = useState<string>('ALL');
  const [statsYearFilter, setStatsYearFilter] = useState<number>(new Date().getFullYear());

  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
    if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  // --- 數據備份與同步 ---
  const exportData = () => {
    const data = { items, logs, timestamp: Date.now() };
    const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `工安管理備份_${new Date().toLocaleDateString().replace(/\//g, '-')}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const importData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (data.items && data.logs) {
          if (window.confirm("確定要導入此備份並同步數據嗎？這將會覆蓋您目前的數據。")) {
            setItems(data.items);
            setLogs(data.logs);
            window.alert("✅ 數據同步成功！");
          }
        }
      } catch (err) {
        window.alert("❌ 檔案格式不正確。");
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const getReservedQty = (itemId: string) => {
    return basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);
  };

  const currentAvailable = useMemo(() => {
    if (!selectedItemId) return 0;
    const item = items.find(i => i.id === selectedItemId);
    if (!item) return 0;
    return item.quantity - getReservedQty(selectedItemId);
  }, [selectedItemId, items, basket]);

  const isQtyOver = useMemo(() => {
    if (issuanceMode === 'IN') return false;
    const qty = Number(inputQty);
    return !isNaN(qty) && qty > currentAvailable;
  }, [inputQty, currentAvailable, issuanceMode]);

  const addToBasket = () => {
    if (!selectedItemId || isQtyOver) return;
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;
    const qty = Number(inputQty);
    if (isNaN(qty) || qty <= 0) return;

    setBasket(prev => [
      ...prev,
      {
        itemId: targetItem.id,
        name: targetItem.name,
        quantity: qty,
        unit: targetItem.unit,
        spec: targetItem.spec,
        itemType: targetItem.itemType
      }
    ]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const timestamp = Date.now();
    const batchId = generateId();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(bItem => {
      updatedItems = updatedItems.map(item => {
        if (item.id === bItem.itemId) {
          const newQty = issuanceMode === 'IN' ? item.quantity + bItem.quantity : item.quantity - bItem.quantity;
          return { ...item, quantity: newQty, lastUpdated: timestamp };
        }
        return item;
      });
      newLogs.push({
        id: generateId() + Math.random().toString(36).substr(2, 4),
        itemId: bItem.itemId,
        itemName: bItem.name,
        type: issuanceMode,
        quantity: bItem.quantity,
        person: inputPerson || '未填寫',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: inputReason,
        timestamp: timestamp
      });
    });

    setItems(updatedItems);
    setLogs(prev => [...newLogs, ...prev]);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({
        id: batchId,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: timestamp
      });
      setShowPrintModal(true);
    } else {
      window.alert(`✅ 物資已補貨。`);
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  // --- 終極穩定列印邏輯：彈出視窗版 (解決無反應問題) ---
  const handleFinalPrint = (isPDF: boolean = false) => {
    if (!lastTransactionBatch) return;

    if (isPDF) {
      window.alert("💡 另存為 PDF 指引：\n\n點擊確認後，請在列印選項中選擇「另存為 PDF」或「Save as PDF」作為目的地印表機。");
    }

    const date = new Date(lastTransactionBatch.timestamp);
    const isEquip = lastTransactionBatch.items.some(it => it.itemType === 'EQUIPMENT');
    const isConsum = lastTransactionBatch.items.every(it => it.itemType === 'CONSUMABLE') || !isEquip;

    const rows = lastTransactionBatch.items.map(item => `
      <tr>
        <td style="text-align:left; color:black; padding: 12px; border: 1.5px solid black;">${item.name}</td>
        <td style="color:black; border: 1.5px solid black;">${item.spec || ''}</td>
        <td style="color:black; border: 1.5px solid black;">${item.unit}</td>
        <td style="font-size:18pt; font-weight:bold; color:black; border: 1.5px solid black;">${item.quantity}</td>
        <td style="color:black; border: 1.5px solid black;">${lastTransactionBatch.reason}</td>
      </tr>
    `).join('');

    const emptyRowsCount = Math.max(0, 15 - lastTransactionBatch.items.length);
    const emptyRows = Array(emptyRowsCount).fill('<tr><td style="height:35px; border: 1.5px solid black;">&nbsp;</td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td></tr>').join('');

    const printWindow = window.open('', '_blank', 'width=1100,height=900');
    if (!printWindow) {
      window.alert("❌ 錯誤：瀏覽器封鎖了列印視窗。請允許此網頁的彈出視窗。");
      return;
    }

    printWindow.document.write(`
      <html>
        <head>
          <title>領用單_${lastTransactionBatch.id}</title>
          <style>
            @font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); }
            body { font-family: 'StandardKai', serif; padding: 40px; color: black !important; background: white; margin: 0; line-height: 1.2; }
            .title { text-align: center; font-size: 26pt; font-weight: bold; margin-bottom: 25px; letter-spacing: 2px; }
            .checkbox-area { display: flex; justify-content: center; gap: 40px; font-size: 16pt; margin-bottom: 25px; font-weight: bold; }
            .checkbox { width: 22px; height: 22px; border: 2.5px solid black; display: inline-flex; align-items: center; justify-content: center; margin-right: 8px; vertical-align: middle; }
            .dept-row { font-size: 15pt; font-weight: bold; margin-bottom: 10px; display: flex; justify-content: space-between; }
            table { width: 100%; border-collapse: collapse; border: 2.5px solid black; margin-bottom: 25px; }
            th { border: 1.5px solid black; padding: 8px; text-align: center; font-size: 14pt; font-weight: bold; background: #f0f0f0; }
            .footer-row { font-size: 14pt; font-weight: bold; margin-top: 30px; }
            .sig-area { display: flex; justify-content: space-between; margin-top: 45px; font-size: 13pt; }
            @media print { body { padding: 20px; } .no-print { display: none; } }
          </style>
        </head>
        <body>
          <div style="display: flex; flex-direction: column; align-items: flex-end;">
            <div style="font-size: 9pt; color: #666;">單號：${lastTransactionBatch.id}</div>
            ${lastTransactionBatch.person ? `<div style="font-size: 9pt; color: #ccc; margin-top: 2px;">領用人：${lastTransactionBatch.person}</div>` : ''}
          </div>
          <div class="title">台灣電力公司電力修護處南部分處</div>
          <div class="checkbox-area">
            <div><span class="checkbox">${isEquip ? 'V' : ''}</span>安全衛生設備借用單</div>
            <div><span class="checkbox">${isConsum ? 'V' : ''}</span>安全衛生類消耗品領用單</div>
          </div>
          <div class="dept-row">
            <div>部 門：<span style="border-bottom: 2px dotted black; min-width: 350px; display: inline-block; text-align: center;">${lastTransactionBatch.dept}</span></div>
            <div>${date.getFullYear() - 1911} 年 ${date.getMonth() + 1} 月 ${date.getDate()} 日</div>
          </div>
          <table>
            <thead>
              <tr><th style="width:35%">名　　　稱</th><th style="width:25%">規　範（序　號）</th><th style="width:10%">單 位</th><th style="width:10%">數 量</th><th style="width:20%">備　　註</th></tr>
            </thead>
            <tbody>${rows}${emptyRows}</tbody>
          </table>
          <div class="footer-row">
            <div style="display: flex; justify-content: space-between;">
              <div style="flex:1">申請部門：</div>
              <div style="flex:1">經管部門：</div>
            </div>
            <div class="sig-area">
              <div style="flex:1; display:flex; justify-content:space-between; padding-right: 50px;">
                <span>經辦：</span><span>課長：</span><span>經理：</span>
              </div>
              <div style="flex:1; display:flex; justify-content:space-between; padding-left: 10px;">
                <span>經辦：</span><span>課長：</span><span>經理：</span>
              </div>
            </div>
          </div>
          <script>
            window.onload = function() {
              setTimeout(function() {
                window.print();
                window.close();
              }, 600);
            };
          </script>
        </body>
      </html>
    `);
    printWindow.document.close();
  };

  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = {
      name: formData.get('name') as string,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
    };
    if (editTarget) {
      setItems(prev => prev.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i));
      setEditTarget(null);
    } else {
      setItems(prev => [...prev, { id: generateId(), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: Date.now() }]);
      setShowAddModal(false);
    }
  };

  const stats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    const medItems = items.filter(i => i.itemGroup === 'MEDICINE');
    const filteredLogs = logs.filter(l => {
        const logDate = new Date(l.timestamp);
        const matchesYear = logDate.getFullYear() === statsYearFilter;
        const matchesDept = statsDeptFilter === 'ALL' || l.dept === statsDeptFilter;
        return l.type === 'OUT' && matchesYear && matchesDept;
    });
    const invDetailMap: Record<string, {name: string, qty: number}> = {};
    const medDetailMap: Record<string, {name: string, qty: number}> = {};
    let filteredInvQty = 0;
    let filteredMedQty = 0;
    filteredLogs.forEach(log => {
        const item = items.find(it => it.id === log.itemId);
        const isMedicine = item ? item.itemGroup === 'MEDICINE' : false;
        if (!isMedicine) {
            filteredInvQty += log.quantity;
            if (!invDetailMap[log.itemId]) invDetailMap[log.itemId] = { name: log.itemName, qty: 0 };
            invDetailMap[log.itemId].qty += log.quantity;
        } else {
            filteredMedQty += log.quantity;
            if (!medDetailMap[log.itemId]) medDetailMap[log.itemId] = { name: log.itemName, qty: 0 };
            medDetailMap[log.itemId].qty += log.quantity;
        }
    });
    return {
      sys: { invTotal: invItems.length, medTotal: medItems.length },
      filtered: {
        invQty: filteredInvQty,
        medQty: filteredMedQty,
        invDetails: Object.values(invDetailMap).sort((a, b) => b.qty - a.qty),
        medDetails: Object.values(medDetailMap).sort((a, b) => b.qty - a.qty),
      },
      deptRanking: Object.entries(logs.filter(l => l.type === 'OUT' && new Date(l.timestamp).getFullYear() === statsYearFilter).reduce((acc: any, curr) => {
          acc[curr.dept] = (acc[curr.dept] || 0) + curr.quantity; return acc;
      }, {})).sort((a: any, b: any) => b[1] - a[1])
    };
  }, [items, logs, statsDeptFilter, statsYearFilter]);

  return (
    <div className="min-h-screen flex bg-slate-100 text-black font-sans">
      <style>{`
        input, select, textarea { color: #000000 !important; background-color: #ffffff !important; border: 2px solid #94a3b8 !important; font-weight: 700 !important; }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
      `}</style>

      <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={importData} />

      <aside className="w-64 bg-slate-900 text-white p-6 flex flex-col shrink-0">
        <div className="flex items-center gap-3 mb-10">
          <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22}/></div>
          <h1 className="font-black text-xl tracking-tight">工安管理系統</h1>
        </div>
