                       <table style={{width:'100%', borderCollapse:'collapse', border:'2px solid black'}}><thead><tr style={{background:'#eee'}}><th style={{padding:'8px', border:'1.5px solid black'}}>名稱</th><th style={{padding:'8px', border:'1.5px solid black'}}>規範</th><th style={{padding:'8px', border:'1.5px solid black'}}>單位</th><th style={{padding:'8px', border:'1.5px solid black'}}>數量</th><th style={{padding:'8px', border:'1.5px solid black'}}>備註</th></tr></thead><tbody>{lastTransactionBatch.items.map((it, i) => (<tr key={i}><td style={{textAlign:'left', padding:'12px', border:'1.5px solid black'}}>{it.name}</td><td style={{border:'1.5px solid black'}}>{it.spec}</td><td style={{border:'1.5px solid black'}}>{it.unit}</td><td style={{fontWeight:'bold', fontSize:'16pt', border:'1.5px solid black'}}>{it.quantity}</td><td style={{border:'1.5px solid black'}}>{lastTransactionBatch.reason}</td></tr>))}{Array(Math.max(0, 15 - lastTransactionBatch.items.length)).fill(0).map((_, i) => (<tr key={i + 100}><td style={{height:'35px', border:'1.5px solid black'}}>&nbsp;</td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td></tr>))}</tbody></table>
                       <div style={{marginTop:'35px', fontWeight:'bold', fontSize:'13pt'}}><div style={{display:'flex', justifyContent:'space-between'}}><div style={{flex:1}}>申請部門：</div><div style={{flex:1}}>經管部門：</div></div><div style={{display:'flex', justifyContent:'space-between', marginTop:'45px', fontSize:'12pt'}}><div style={{flex:1, display:'flex', justifyContent:'space-between', paddingRight:'50px'}}><span>經辦：</span><span>課長：</span><span>經理：</span></div><div style={{flex:1, display:'flex', justifyContent:'space-between', paddingLeft:'10px'}}><span>經辦：</span><span>課長：</span><span>經理：</span></div></div></div>
                    </div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl"><form className="space-y-6" onSubmit={handleSaveItem}><div><label className="text-xs font-black text-slate-500 uppercase">物資名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl mt-2" defaultValue={editTarget?.name} /></div><div className="grid grid-cols-2 gap-6"><div><label className="text-xs font-black text-slate-500">性質</label><select name="itemType" className="w-full p-4 rounded-xl mt-2" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="EQUIPMENT">設備</option><option value="CONSUMABLE">消耗品</option></select></div><div><label className="text-xs font-black text-slate-500">規範</label><input name="spec" type="text" className="w-full p-4 rounded-xl mt-2" defaultValue={editTarget?.spec || ''} /></div></div><div className="grid grid-cols-3 gap-6"><div><label className="text-xs font-black text-slate-500">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl mt-2" defaultValue={editTarget?.unit || '個'} /></div><div><label className="text-xs font-black text-slate-500">現庫存</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl mt-2" defaultValue={editTarget?.quantity || 0} /></div><div><label className="text-xs font-black text-slate-500">警戒量</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl mt-2" defaultValue={editTarget?.minStock || 5} /></div></div><button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-2xl shadow-xl mt-6">儲存物資</button><button type="button" onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="w-full py-3 text-slate-400 font-bold">取消</button></form></div>
          </div>
        )}

        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/90 flex items-center justify-center p-4 z-[400]"><div className="bg-white p-10 rounded-3xl text-center max-w-sm"><h3 className="text-2xl font-black mb-4">確定刪除「{deleteTarget.name}」？</h3><button onClick={()=>{setItems(prev => prev.filter(i => i.id !== deleteTarget.id)); setDeleteTarget(null);}} className="w-full py-4 bg-red-600 text-white rounded-xl font-black mb-2">確認刪除</button><button onClick={()=>setDeleteTarget(null)} className="w-full py-4 text-slate-400 font-bold">取消</button></div></div>
        )}
      </main>
    </div>
  );
};

export default App;

