              <tbody className="divide-y divide-slate-100">{logs.map(log => (<tr key={log.id} className="hover:bg-slate-50"><td className="px-6 py-5 text-xs font-bold text-slate-400">{new Date(log.timestamp).toLocaleString()}</td><td className="px-6 py-5 font-black">{log.type === 'OUT' ? <span className="flex items-center gap-1 text-blue-600 font-bold"><ArrowUpRight size={14}/> 領用出庫</span> : <span className="flex items-center gap-1 text-emerald-600 font-bold"><ArrowDownLeft size={14}/> 補貨入庫</span>}</td><td className="px-6 py-5 font-black text-black">{log.itemName} (x{log.quantity})</td><td className="px-6 py-5 font-bold text-slate-600">{log.dept} / {log.person}</td><td className="px-6 py-5 text-right">{log.type === 'OUT' ? <button onClick={()=>{ setLastTransactionBatch({id: log.id, dept: log.dept, person: log.person, reason: log.reason, items: [{itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '個', spec: '', itemType: 'CONSUMABLE'}], timestamp: log.timestamp}); setShowPrintModal(true); }} className="text-slate-400 hover:text-blue-600"><Printer size={20}/></button> : <span className="text-slate-200">--</span>}</td></tr>))}</tbody>
