                    <td className="px-8 py-5 text-center"><span className={`px-6 py-2 rounded-xl font-black text-xl ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-emerald-50 text-emerald-600'}`}>{item.quantity} {item.unit}</span></td>
