              <form className="space-y-6" onSubmit={handleSaveItem}>
                <h3 className="text-2xl font-black text-black mb-4">{editTarget ? '編輯項目' : '新增項目'}</h3>
                <div><label className="text-xs font-black text-slate-500 uppercase">物資名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl mt-2 text-black font-bold border-2" defaultValue={editTarget?.name} /></div>

                <div className="grid grid-cols-2 gap-6">
                  <div>
                    <label className="text-xs font-black text-slate-500">分類</label>
                    <select name="itemType" className="w-full p-4 rounded-xl mt-2 text-black font-bold border-2" defaultValue={editTarget?.itemType || 'CONSUMABLE'}>
                      <option value="EQUIPMENT">安全衛生設備</option>
                      <option value="CONSUMABLE">安全衛生類消耗品</option>
                    </select>
                  </div>
                  <div><label className="text-xs font-black text-slate-500">規範 (序號)</label><input name="spec" type="text" className="w-full p-4 rounded-xl mt-2 text-black font-bold border-2" defaultValue={editTarget?.spec || ''} /></div>
                </div>

                <div className="grid grid-cols-3 gap-6">
                  <div><label className="text-xs font-black text-slate-500">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl mt-2 text-black font-bold border-2" defaultValue={editTarget?.unit || '個'} /></div>
                  <div><label className="text-xs font-black text-slate-500">目前庫存</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl mt-2 text-black font-bold border-2" defaultValue={editTarget?.quantity || 0} /></div>
                  <div><label className="text-xs font-black text-slate-500">警戒數量</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl mt-2 text-black font-bold border-2" defaultValue={editTarget?.minStock || 5} /></div>
                </div>

                {(activeTab === 'medicine' || editTarget?.itemGroup === 'MEDICINE') && (
                   <div className="grid grid-cols-2 gap-6">
                     <div><label className="text-xs font-black text-slate-500">購入日期</label><input name="purchaseDate" type="date" className="w-full p-4 rounded-xl mt-2 text-black font-bold border-2" defaultValue={editTarget?.purchaseDate} /></div>
                     <div><label className="text-xs font-black text-slate-500">有效日期</label><input name="expiryDate" type="date" className="w-full p-4 rounded-xl mt-2 text-black font-bold border-2" defaultValue={editTarget?.expiryDate} /></div>
                   </div>
                )}

                <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-2xl shadow-xl mt-6 active:scale-95 transition-all">儲存物資</button>
                <button type="button" onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="w-full py-3 text-slate-400 font-bold hover:text-black transition-colors">取消返回</button>
              </form>
            </div>
          </div>
        )}

        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/90 flex items-center justify-center p-4 z-[400] animate-in fade-in"><div className="bg-white p-10 rounded-3xl text-center max-w-sm shadow-2xl"><h3 className="text-2xl font-black mb-4 text-black">確定刪除「{deleteTarget.name}」？</h3><button onClick={()=>{
            const updated = items.filter(i => i.id !== deleteTarget.id);
            setItems(updated);
            syncToCloud(updated, logs);
            setDeleteTarget(null);
          }} className="w-full py-4 bg-red-600 text-white rounded-xl font-black mb-2 shadow-lg hover:bg-red-700 transition-colors">確認刪除</button><button onClick={()=>setDeleteTarget(null)} className="w-full py-4 text-slate-400 font-bold hover:text-black">取消</button></div></div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  CheckCircle2,
  Users,
  Filter,
  ClipboardList,
  Download,
  Upload,
  FileDown,
  ArrowUpRight,
  ArrowDownLeft,
  Settings,
  Cloud,
  CloudOff,
  RefreshCw,
  Clock
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

type SyncStatus = 'synced' | 'syncing' | 'error' | 'local';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');
  const [syncStatus, setSyncStatus] = useState<SyncStatus>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '從未同步');
  const [showSettings, setShowSettings] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [statsDeptFilter, setStatsDeptFilter] = useState<string>('ALL');
  const [statsYearFilter, setStatsYearFilter] = useState<number>(new Date().getFullYear());

  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // 初始化載入
  useEffect(() => {
    const initLoad = async () => {
      const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
      const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
      if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
      if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }

      setIsLoaded(true);

      if (gasUrl) {
        await fetchFromCloud();
      } else {
        setSyncStatus('local');
      }
    };
    initLoad();
  }, []);

  // 監控變化並備份到 LocalStorage
  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const updateSyncTime = () => {
    const now = new Date().toLocaleTimeString('zh-TW', { hour12: false, hour: '2-digit', minute: '2-digit' });
    const fullTime = `${new Date().toLocaleDateString('zh-TW')} ${now}`;
    setLastSyncTime(fullTime);
    localStorage.setItem(STORAGE_KEY_LAST_SYNC, fullTime);
  };

  // --- 雲端同步核心函數 ---
  const syncToCloud = async (currentItems: InventoryItem[], currentLogs: Transaction[]) => {
    if (!gasUrl) {
      setSyncStatus('local');
      return;
    }
    setSyncStatus('syncing');
    try {
      const payload = { items: currentItems, logs: currentLogs, timestamp: Date.now() };
      await fetch(gasUrl, {
        method: 'POST',
        body: JSON.stringify(payload),
        mode: 'no-cors' 
      });
      setSyncStatus('synced');
      updateSyncTime();
    } catch (err) {
      console.error("Cloud Sync Error:", err);
      setSyncStatus('error');
    }
  };

  const fetchFromCloud = async () => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const response = await fetch(gasUrl);
      const data = await response.json();
      if (data && data.items && data.logs) {
        setItems(data.items);
        setLogs(data.logs);
        setSyncStatus('synced');
        updateSyncTime();
        console.log("Cloud data loaded successfully.");
      } else {
        setSyncStatus('synced');
        updateSyncTime();
      }
    } catch (err) {
      console.error("Fetch Cloud Error:", err);
      setSyncStatus('error');
    }
  };

  const handleGasUrlSave = (newUrl: string) => {
    setGasUrl(newUrl);
    localStorage.setItem(STORAGE_KEY_GAS_URL, newUrl);
    setShowSettings(false);
    if (newUrl) {
       fetchFromCloud();
    } else {
       setSyncStatus('local');
    }
  };

  const exportData = () => {
    const data = { items, logs, timestamp: Date.now() };
    const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `工安管理備份_${new Date().toLocaleDateString().replace(/\//g, '-')}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const importData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (data.items && data.logs) {
          if (window.confirm("確定要導入此備份並同步數據嗎？這將覆蓋現有庫存與紀錄。")) {
            setItems(data.items);
            setLogs(data.logs);
            syncToCloud(data.items, data.logs);
            window.alert("✅ 數據導入成功，已嘗試同步至雲端！");
          }
        }
      } catch (err) {
        window.alert("❌ 檔案格式錯誤，無法讀取。");
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const getReservedQty = (itemId: string) => {
    return basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);
  };

  const currentAvailable = useMemo(() => {
    if (!selectedItemId) return 0;
    const item = items.find(i => i.id === selectedItemId);
    if (!item) return 0;
    return item.quantity - getReservedQty(selectedItemId);
  }, [selectedItemId, items, basket]);

  const isQtyOver = useMemo(() => {
    if (issuanceMode === 'IN') return false;
    const qty = Number(inputQty);
    return !isNaN(qty) && qty > currentAvailable;
  }, [inputQty, currentAvailable, issuanceMode]);

  const addToBasket = () => {
    if (!selectedItemId || isQtyOver) return;
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;
    const qty = Number(inputQty);
    if (isNaN(qty) || qty <= 0) return;

    setBasket(prev => [
      ...prev,
      {
        itemId: targetItem.id,
        name: targetItem.name,
        quantity: qty,
        unit: targetItem.unit,
        spec: targetItem.spec,
        itemType: targetItem.itemType
      }
    ]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const timestamp = Date.now();
    const batchId = generateId();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(bItem => {
      updatedItems = updatedItems.map(item => {
        if (item.id === bItem.itemId) {
          const newQty = issuanceMode === 'IN' ? item.quantity + bItem.quantity : item.quantity - bItem.quantity;
          return { ...item, quantity: newQty, lastUpdated: timestamp };
        }
        return item;
      });
      newLogs.push({
        id: generateId() + Math.random().toString(36).substr(2, 4),
        itemId: bItem.itemId,
        itemName: bItem.name,
        type: issuanceMode,
        quantity: bItem.quantity,
        person: inputPerson || '未填寫',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: inputReason,
        timestamp: timestamp
      });
    });

    const finalLogs = [...newLogs, ...logs];
    setItems(updatedItems);
    setLogs(finalLogs);
    syncToCloud(updatedItems, finalLogs);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({
        id: batchId,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: timestamp
      });
      setShowPrintModal(true);
    } else {
      window.alert(`✅ 物資補貨入庫完成。`);
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  const handleFinalPrint = (isPDF: boolean = false) => {
    if (!lastTransactionBatch) return;
    if (isPDF) {
      window.alert("💡 另存為 PDF 指引：\n\n點擊確認後，請在印表機目的地選擇「另存為 PDF (Save as PDF)」。");
    }

    const date = new Date(lastTransactionBatch.timestamp);
    const isEquip = lastTransactionBatch.items.some(it => it.itemType === 'EQUIPMENT');
    const isConsum = lastTransactionBatch.items.every(it => it.itemType === 'CONSUMABLE') || !isEquip;

    const rows = lastTransactionBatch.items.map(item => `
      <tr>
        <td style="text-align:center; color:black; padding: 12px; border: 1.5px solid black;">${item.name}</td>
        <td style="text-align:center; color:black; border: 1.5px solid black;">${item.spec || ''}</td>
        <td style="text-align:center; color:black; border: 1.5px solid black;">${item.unit}</td>
        <td style="text-align:center; font-size:18pt; font-weight:bold; color:black; border: 1.5px solid black;">${item.quantity}</td>
        <td style="text-align:center; color:black; border: 1.5px solid black;">${lastTransactionBatch.reason}</td>
      </tr>
    `).join('');

    const emptyRowsCount = Math.max(0, 15 - lastTransactionBatch.items.length);
    const emptyRows = Array(emptyRowsCount).fill('<tr><td style="height:35px; border: 1.5px solid black;">&nbsp;</td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td></tr>').join('');

    const printWin = window.open('', '_blank', 'width=1100,height=900');
    if (!printWin) return;

    printWin.document.write(`
      <html>
        <head>
          <title>領用單_${lastTransactionBatch.id}</title>
          <style>
            @font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); }
            body { font-family: 'StandardKai', serif; padding: 40px; color: black !important; background: white; margin: 0; line-height: 1.2; }
            .title { text-align: center; font-size: 26pt; font-weight: bold; margin-bottom: 25px; letter-spacing: 2px; color: black !important; }
            .checkbox-area { display: flex; justify-content: center; gap: 40px; font-size: 16pt; margin-bottom: 25px; font-weight: bold; color: black !important; }
            .checkbox { width: 22px; height: 22px; border: 2.5px solid black; display: inline-flex; align-items: center; justify-content: center; margin-right: 8px; vertical-align: middle; }
            .dept-row { font-size: 15pt; font-weight: bold; margin-bottom: 10px; display: flex; justify-content: space-between; color: black !important; }
            table { width: 100%; border-collapse: collapse; border: 2.5px solid black; margin-bottom: 25px; }
            th { border: 1.5px solid black; padding: 10px; text-align: center; font-size: 14pt; font-weight: bold; background: #f2f2f2; color: black !important; }
            td { color: black !important; text-align: center; }
            .footer-row { font-size: 14pt; font-weight: bold; margin-top: 30px; color: black !important; }
            .sig-area { display: flex; justify-content: space-between; margin-top: 45px; font-size: 13pt; color: black !important; }
            @media print { body { padding: 20px; } .no-print { display: none; } }
          </style>
        </head>
        <body>
          <div style="display: flex; flex-direction: column; align-items: flex-end;">
            <div style="font-size: 9pt; color: #666;">單號：${lastTransactionBatch.id}</div>
            ${lastTransactionBatch.person ? `<div style="font-size: 9pt; color: #ccc; margin-top: 2px;">領用人：${lastTransactionBatch.person}</div>` : ''}
          </div>
          <div class="title">台灣電力公司電力修護處南部分處</div>
          <div class="checkbox-area">
            <div><span class="checkbox">${isEquip ? 'V' : ''}</span>安全衛生設備借用單</div>
            <div><span class="checkbox">${isConsum ? 'V' : ''}</span>安全衛生類消耗品領用單</div>
          </div>
          <div class="dept-row">
            <div>部 門：<span style="border-bottom: 2px dotted black; min-width: 350px; display: inline-block; text-align: center;">${lastTransactionBatch.dept}</span></div>
            <div>${date.getFullYear() - 1911} 年 ${date.getMonth() + 1} 月 ${date.getDate()} 日</div>
          </div>
          <table>
            <thead>
              <tr><th style="width:35%">名　　　稱</th><th style="width:25%">規　範（序　號）</th><th style="width:10%">單 位</th><th style="width:10%">數 量</th><th style="width:20%">備　　註</th></tr>
            </thead>
            <tbody>${rows}${emptyRows}</tbody>
          </table>
          <div class="footer-row">
            <div style="display: flex; justify-content: space-between;">
              <div style="flex:1">申請部門：</div>
              <div style="flex:1">經管部門：</div>
            </div>
            <div class="sig-area">
              <div style="flex:1; display:flex; justify-content:space-between; padding-right: 50px;">
                <span>經辦：</span><span>課長：</span><span>經理：</span>
              </div>
              <div style="flex:1; display:flex; justify-content:space-between; padding-left: 10px;">
                <span>經辦：</span><span>課長：</span><span>經理：</span>
              </div>
            </div>
          </div>
          <script>window.onload = () => { setTimeout(() => { window.print(); window.close(); }, 600); };</script>
        </body>
      </html>
    `);
    printWin.document.close();
  };

  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = {
      name: formData.get('name') as string,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
    };

    let updated;
    if (editTarget) {
      updated = items.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i);
      setItems(updated);
      setEditTarget(null);
    } else {
      updated = [...items, { id: generateId(), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: Date.now() }];
      setItems(updated);
      setShowAddModal(false);
    }
    syncToCloud(updated, logs);
  };

  const stats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    const medItems = items.filter(i => i.itemGroup === 'MEDICINE');
    const filteredLogs = logs.filter(l => {
        const logDate = new Date(l.timestamp);
        const matchesYear = logDate.getFullYear() === statsYearFilter;
        const matchesDept = statsDeptFilter === 'ALL' || l.dept === statsDeptFilter;
        return l.type === 'OUT' && matchesYear && matchesDept;
    });
    const invDetailMap: Record<string, {name: string, qty: number}> = {};
    const medDetailMap: Record<string, {name: string, qty: number}> = {};
    let filteredInvQty = 0;
    let filteredMedQty = 0;
    filteredLogs.forEach(log => {
        const item = items.find(it => it.id === log.itemId);
        const isMedicine = item ? item.itemGroup === 'MEDICINE' : false;
        if (!isMedicine) {
            filteredInvQty += log.quantity;
            if (!invDetailMap[log.itemId]) invDetailMap[log.itemId] = { name: log.itemName, qty: 0 };
            invDetailMap[log.itemId].qty += log.quantity;
        } else {
            filteredMedQty += log.quantity;
            if (!medDetailMap[log.itemId]) medDetailMap[log.itemId] = { name: log.itemName, qty: 0 };
            medDetailMap[log.itemId].qty += log.quantity;
        }
    });
    return {
      sys: { invTotal: invItems.length, medTotal: medItems.length },
      filtered: {
        invQty: filteredInvQty,
        medQty: filteredMedQty,
        invDetails: Object.values(invDetailMap).sort((a, b) => b.qty - a.qty),
        medDetails: Object.values(medDetailMap).sort((a, b) => b.qty - a.qty),
      },
      deptRanking: Object.entries(logs.filter(l => l.type === 'OUT' && new Date(l.timestamp).getFullYear() === statsYearFilter).reduce((acc: any, curr) => {
          acc[curr.dept] = (acc[curr.dept] || 0) + curr.quantity; return acc;
      }, {})).sort((a: any, b: any) => b[1] - a[1])
    };
  }, [items, logs, statsDeptFilter, statsYearFilter]);

  return (
    <div className="min-h-screen flex bg-slate-100 text-black font-sans">
      <style>{`
        input, select, textarea { color: #000000 !important; background-color: #ffffff !important; border: 2px solid #94a3b8 !important; font-weight: 700 !important; }
        input[type="date"]::-webkit-calendar-picker-indicator {
          cursor: pointer;
          filter: invert(0) grayscale(100%) brightness(0%);
          opacity: 1;
          padding: 2px;
        }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
        .pulse-orange { animation: pulse-orange 2s infinite; }
        @keyframes pulse-orange {
          0% { box-shadow: 0 0 0 0 rgba(251, 146, 60, 0.7); }
          70% { box-shadow: 0 0 0 10px rgba(251, 146, 60, 0); }
          100% { box-shadow: 0 0 0 0 rgba(251, 146, 60, 0); }
        }
      `}</style>

      <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={importData} />

      <aside className="w-72 bg-slate-900 text-white p-6 flex flex-col shrink-0 border-r border-slate-800 shadow-2xl">
        <div className="flex flex-col gap-1 mb-8">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22} className="text-white"/></div>
            <h1 className="font-black text-xl tracking-tight text-white">工安管理系統</h1>
          </div>

          {/* 同步狀態卡片 - 強化版 */}
          <div className="mt-6 bg-slate-800/50 rounded-2xl p-4 border border-slate-700/50">
            <div className="flex items-center justify-between mb-2">
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">雲端連線狀態</span>
              <div className={`w-3 h-3 rounded-full ${
                syncStatus === 'synced' ? 'bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.8)]' : 
                syncStatus === 'syncing' ? 'bg-amber-500 animate-pulse' : 
                syncStatus === 'error' ? 'bg-red-500 shadow-[0_0_12px_rgba(239,68,68,0.8)]' : 'bg-orange-400 pulse-orange'
              }`}></div>
            </div>
            <div className="text-sm font-black text-white mb-1">
              {syncStatus === 'synced' ? '已成功連線' : 
               syncStatus === 'syncing' ? '正在同步數據...' : 
               syncStatus === 'error' ? '連線中斷 / 網址錯誤' : '尚未設定雲端網址'}
            </div>
            <div className="flex items-center gap-1.5 text-[10px] text-slate-400 font-bold">
              <Clock size={10}/> 最後同步：{lastSyncTime}
            </div>
          </div>
        </div>

        <nav className="flex-1 space-y-1">
          {[
            { id: 'inventory', label: '工安耗材管理', icon: Package },
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
            { id: 'issuance', label: '領用補貨作業', icon: FileText },
            { id: 'history', label: '歷史異動日誌', icon: History },
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard },
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}><tab.icon size={20} /> {tab.label}</button>
          ))}
        </nav>

        <div className="pt-6 mt-6 border-t border-slate-800 space-y-2">
            <p className="px-4 text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">管理與備份</p>
            <button onClick={() => setShowSettings(true)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-black transition-all ${!gasUrl ? 'bg-orange-500/10 text-orange-400 border border-orange-500/30' : 'text-slate-300 hover:bg-slate-800 hover:text-white'}`}><Settings size={16}/> 雲端連線設定</button>
            <button onClick={fetchFromCloud} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><RefreshCw size={16}/> 手動重新同步</button>
            <button onClick={exportData} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><Download size={16}/> 匯出備份 (JSON)</button>
            <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><Upload size={16}/> 導入備份</button>
        </div>
      </aside>

      <main className="flex-1 p-10 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <div>
            <h2 className="text-3xl font-black text-black">
              {activeTab === 'inventory' ? '工安耗材清冊' : 
               activeTab === 'medicine' ? '急救藥材清冊' : 
               activeTab === 'issuance' ? '領用 / 補貨登記' : 
               activeTab === 'history' ? '歷史異動日誌' : '數據統計看板'}
            </h2>
            {!gasUrl && activeTab === 'dashboard' && (
              <div onClick={() => setShowSettings(true)} className="mt-4 bg-orange-50 border-2 border-orange-200 p-4 rounded-2xl flex items-center gap-3 text-orange-700 cursor-pointer hover:bg-orange-100 transition-all shadow-sm">
                <AlertTriangle size={20} className="animate-bounce"/>
                <div className="font-bold">尚未設定雲端同步！點擊此處貼上 GAS 網址，開啟多人協作功能。</div>
              </div>
            )}
          </div>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-black shadow-xl"><Plus size={18}/> 新增項目</button>
          )}
        </header>

        {syncStatus === 'error' && (
          <div className="mb-6 bg-red-50 border-2 border-red-200 p-5 rounded-2xl flex items-center justify-between text-red-700 shadow-md">
             <div className="flex items-center gap-3 font-black text-lg"><AlertTriangle size={24}/> 雲端連線失敗！請檢查網路或 GAS 網址是否正確。</div>
             <div className="flex gap-3">
               <button onClick={fetchFromCloud} className="px-5 py-2.5 bg-red-600 text-white rounded-xl text-sm font-black shadow-lg">重新嘗試同步</button>
               <button onClick={() => setShowSettings(true)} className="px-5 py-2.5 bg-white border-2 border-red-200 text-red-600 rounded-xl text-sm font-black">檢查網址設定</button>
             </div>
          </div>
        )}

        {/* --- 以下內容維持原樣不變 --- */}
        {activeTab === 'issuance' && (
          <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
            <div className="lg:col-span-2 bg-white p-8 rounded-3xl shadow-xl border border-slate-200">
              <h3 className="text-xl font-black mb-8 flex items-center gap-2 text-black"><ShoppingCart className="text-blue-500"/> 1. 挑選項目</h3>
              <div className="flex bg-slate-100 p-1 rounded-xl mb-6">
                <button onClick={()=>{setIssuanceMode('OUT'); setBasket([]);}} className={`flex-1 py-3 rounded-lg font-black transition-all ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button>
                <button onClick={()=>{setIssuanceMode('IN'); setBasket([]);}} className={`flex-1 py-3 rounded-lg font-black transition-all ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
              </div>
              <div className="space-y-6">
                <div><label className="text-xs font-black text-slate-500 uppercase tracking-widest">分類</label>
                  <div className="flex gap-2 mt-2">
                    <button onClick={()=>setIssuanceGroup('INVENTORY')} className={`flex-1 py-3 rounded-xl font-black border-2 ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-200 text-slate-400'}`}>耗材類</button>
                    <button onClick={()=>setIssuanceGroup('MEDICINE')} className={`flex-1 py-3 rounded-xl font-black border-2 ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-200 text-slate-400'}`}>藥材類</button>
                  </div>
                </div>
                <div><label className="text-xs font-black text-slate-500 uppercase tracking-widest">品項選擇</label>
                  <select className="w-full p-4 rounded-xl mt-2 text-lg text-black font-bold" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                    <option value="">-- 請選擇品項 --</option>
                    {items.filter(i => i.itemGroup === issuanceGroup).map(i => {
                      const avail = i.quantity - getReservedQty(i.id);
                      return <option key={i.id} value={i.id}>{i.name} ({issuanceMode === 'OUT' ? `剩餘:${avail}` : `庫存:${i.quantity}`})</option>;
                    })}
                  </select>
                </div>
                <div><label className="text-xs font-black text-slate-500 uppercase tracking-widest">數量</label><input type="number" min="1" className="w-full p-4 rounded-xl mt-2 text-xl font-bold" value={inputQty} onChange={e=>setInputQty(e.target.value)}/>{isQtyOver && <p className="text-red-600 text-xs font-black mt-2">⚠️ 超出庫存</p>}</div>
                <button onClick={addToBasket} disabled={!selectedItemId || isQtyOver} className={`w-full py-5 rounded-2xl font-black text-xl flex items-center justify-center gap-2 shadow-lg ${!selectedItemId || isQtyOver ? 'bg-slate-200 text-slate-400' : 'bg-slate-900 text-white hover:bg-black'}`}><Plus size={20}/> 加入處理清單</button>
              </div>
            </div>
            <div className="lg:col-span-3 bg-white p-8 rounded-3xl shadow-xl border border-slate-200 flex flex-col">
              <h3 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><FileText className="text-emerald-500"/> 2. 待處理作業</h3>
              <div className="flex-1 overflow-y-auto border-2 border-dashed border-slate-100 rounded-2xl mb-6 min-h-[250px] bg-slate-50">
                {basket.length > 0 ? (
                  <table className="w-full text-left">
                    <tbody className="divide-y divide-slate-100">
                      {basket.map((b, idx) => (
                        <tr key={idx} className="bg-white"><td className="px-6 py-5 font-black text-black">{b.name}</td><td className="px-6 py-5 text-center font-black text-blue-700">{b.quantity} {b.unit}</td><td className="px-6 py-5 text-right"><button onClick={()=>setBasket(prev => prev.filter((_, i) => i !== idx))} className="text-slate-300 hover:text-red-600"><X size={20}/></button></td></tr>
                      ))}
                    </tbody>
                  </table>
                ) : (<div className="h-full flex items-center justify-center text-slate-300 font-bold opacity-30">清單目前為空</div>)}
              </div>
              {issuanceMode === 'OUT' && (
                <div className="grid grid-cols-2 gap-6 mb-6">
                  <div><label className="text-xs font-black text-slate-500 uppercase">領用部門</label><select className="w-full p-3 rounded-xl mt-2 text-black font-bold" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>{DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}</select></div>
