                       <table style={{width:'100%', borderCollapse:'collapse', border:'2px solid black'}}><thead><tr style={{background:'#f2f2f2'}}><th style={{padding:'8px', border:'1.5px solid black', color: 'black', textAlign:'center'}}>名稱</th><th style={{padding:'8px', border:'1.5px solid black', color: 'black', textAlign:'center'}}>規範</th><th style={{padding:'8px', border:'1.5px solid black', color: 'black', textAlign:'center'}}>單位</th><th style={{padding:'8px', border:'1.5px solid black', color: 'black', textAlign:'center'}}>數量</th><th style={{padding:'8px', border:'1.5px solid black', color: 'black', textAlign:'center'}}>備註</th></tr></thead><tbody>{lastTransactionBatch.items.map((it, i) => (<tr key={i}><td style={{textAlign:'center', padding:'12px', border:'1.5px solid black', color: 'black'}}>{it.name}</td><td style={{border:'1.5px solid black', color: 'black', textAlign:'center'}}>{it.spec}</td><td style={{border:'1.5px solid black', color: 'black', textAlign:'center'}}>{it.unit}</td><td style={{fontWeight:'bold', fontSize:'16pt', border:'1.5px solid black', color: 'black', textAlign:'center'}}>{it.quantity}</td><td style={{border:'1.5px solid black', color: 'black', textAlign:'center'}}>{lastTransactionBatch.reason}</td></tr>))}{Array(Math.max(0, 15 - lastTransactionBatch.items.length)).fill(0).map((_, i) => (<tr key={i + 100}><td style={{height:'35px', border:'1.5px solid black'}}>&nbsp;</td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td></tr>))}</tbody></table>
