              <button onClick={processIssuance} disabled={basket.length===0} className={`w-full py-6 rounded-2xl font-black text-3xl text-white shadow-2xl ${issuanceMode==='OUT'?'bg-blue-600':'bg-emerald-600'}`}>確認過帳</button>
            </div>
