                    <td className="px-8 py-5 font-black text-black">{item.name}</td>
                    <td className="px-8 py-5 text-center">
                      <span className={`px-4 py-2 rounded-xl font-black text-lg ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>{item.quantity} {item.unit}</span>
                    </td>
                    <td className="px-8 py-5 text-right">
                      <button onClick={()=>setEditTarget(item)} className="p-2 text-slate-400 hover:text-blue-600 transition-colors"><Edit3 size={18}/></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* 設定彈窗 */}
        {showSettings && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[600] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl">
              <h3 className="text-2xl font-black mb-6">雲端連線同步設定</h3>
              <input id="gas-url-input" className="w-full p-4 rounded-xl border-2 mb-6 text-black" placeholder="貼上 GAS Web App 網址" defaultValue={gasUrl}/>
              <div className="flex gap-4">
                <button onClick={() => handleGasUrlSave((document.getElementById('gas-url-input') as HTMLInputElement).value)} className="flex-1 py-4 bg-blue-600 text-white rounded-2xl font-black">儲存並同步</button>
                <button onClick={() => setShowSettings(false)} className="px-8 py-4 bg-slate-100 rounded-2xl font-bold">返回</button>
              </div>
            </div>
          </div>
        )}
      </main>

      {/* 列印模態視窗 */}
      {showPrintModal && lastTransactionBatch && (
        <div className="fixed inset-0 bg-white z-[1000] overflow-y-auto p-10">
          <div className="max-w-4xl mx-auto border-4 border-black p-8 text-black" style={{ minHeight: '1000px' }}>
            <h1 className="text-center text-4xl font-black mb-8">台灣電力公司電力修護處南部分處</h1>
            <div className="flex justify-between font-bold text-xl mb-4">
               <span>領用部門：{lastTransactionBatch.dept}</span>
               <span>領用人：{lastTransactionBatch.person}</span>
               <span>日期：{new Date(lastTransactionBatch.timestamp).toLocaleDateString()}</span>
            </div>
            <table className="w-full border-collapse border-4 border-black">
               <thead>
                  <tr className="bg-gray-100">
                    <th className="border-4 border-black p-4">名稱</th>
                    <th className="border-4 border-black p-4">數量</th>
                    <th className="border-4 border-black p-4">單位</th>
                    <th className="border-4 border-black p-4">備註</th>
                  </tr>
               </thead>
               <tbody>
                  {lastTransactionBatch.items.map((it, i) => (
                    <tr key={i}>
                      <td className="border-4 border-black p-4 text-center font-black">{it.name}</td>
                      <td className="border-4 border-black p-4 text-center font-black text-2xl">{it.quantity}</td>
                      <td className="border-4 border-black p-4 text-center">{it.unit}</td>
                      <td className="border-4 border-black p-4 text-center">{lastTransactionBatch.reason}</td>
                    </tr>
                  ))}
               </tbody>
            </table>
            <div className="mt-20 flex justify-between text-xl font-black">
               <span>申請人簽章：_______________</span>
               <span>主管簽章：_______________</span>
            </div>
            <div className="mt-20 flex justify-end no-print">
               <button onClick={handleFinalPrint} className="bg-blue-600 text-white px-10 py-4 rounded-xl font-black text-2xl shadow-xl mr-4">確認列印</button>
               <button onClick={()=>setShowPrintModal(false)} className="bg-slate-200 px-10 py-4 rounded-xl font-black text-2xl">關閉預覽</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  CheckCircle2,
  Users,
  Download,
  Upload,
  FileDown,
  ArrowUpRight,
  ArrowDownLeft,
  Settings,
  Cloud,
  RefreshCw,
  Clock
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

type SyncStatus = 'synced' | 'syncing' | 'error' | 'local';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');
  const [syncStatus, setSyncStatus] = useState<SyncStatus>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '從未同步');
  const [showSettings, setShowSettings] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [statsDeptFilter, setStatsDeptFilter] = useState<string>('ALL');
  const [statsYearFilter, setStatsYearFilter] = useState<number>(new Date().getFullYear());

  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  // Fix: Corrected the state initialization for deleteTarget with proper useState generic syntax.
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const initLoad = async () => {
      const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
      const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
      if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
      if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
      setIsLoaded(true);
      if (gasUrl) { fetchFromCloud(); } else { setSyncStatus('local'); }
    };
    initLoad();
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const updateSyncTime = () => {
    const now = new Date().toLocaleTimeString('zh-TW', { hour12: false, hour: '2-digit', minute: '2-digit' });
    const fullTime = `${new Date().toLocaleDateString('zh-TW')} ${now}`;
    setLastSyncTime(fullTime);
    localStorage.setItem(STORAGE_KEY_LAST_SYNC, fullTime);
  };

  const syncToCloud = async (currentItems: InventoryItem[], currentLogs: Transaction[]) => {
    if (!gasUrl) { setSyncStatus('local'); return; }
    setSyncStatus('syncing');
    try {
      const payload = { items: currentItems, logs: currentLogs, timestamp: Date.now() };
      // 這裡假設後端 GAS 能處理 POST 請求
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify(payload), mode: 'no-cors' });
      setSyncStatus('synced');
      updateSyncTime();
    } catch (err) {
      console.error("Cloud Sync Error:", err);
      setSyncStatus('error');
    }
  };

  const fetchFromCloud = async () => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const response = await fetch(gasUrl);
      const data = await response.json();
      if (data && data.items) {
        setItems(data.items);
        setLogs(data.logs || []);
        setSyncStatus('synced');
        updateSyncTime();
      }
    } catch (err) {
      console.error("Fetch Cloud Error:", err);
      setSyncStatus('error');
    }
  };

  const handleGasUrlSave = (newUrl: string) => {
    setGasUrl(newUrl);
    localStorage.setItem(STORAGE_KEY_GAS_URL, newUrl);
    setShowSettings(false);
    if (newUrl) { fetchFromCloud(); } else { setSyncStatus('local'); }
  };

  const exportData = () => {
    const data = { items, logs, timestamp: Date.now() };
    const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `工安管理備份_${new Date().toLocaleDateString().replace(/\//g, '-')}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const importData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (data.items && data.logs) {
          if (window.confirm("確定要導入此備份並同步數據嗎？")) {
            setItems(data.items);
            setLogs(data.logs);
            syncToCloud(data.items, data.logs);
            window.alert("✅ 數據導入成功！");
          }
        }
      } catch (err) { window.alert("❌ 檔案格式錯誤。"); }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const getReservedQty = (itemId: string) => basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);

  const addToBasket = () => {
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;
    const qty = Number(inputQty);
    if (isNaN(qty) || qty <= 0) return;
    setBasket(prev => [...prev, { itemId: targetItem.id, name: targetItem.name, quantity: qty, unit: targetItem.unit, spec: targetItem.spec, itemType: targetItem.itemType }]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const timestamp = Date.now();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(bItem => {
      updatedItems = updatedItems.map(item => {
        if (item.id === bItem.itemId) {
          const newQty = issuanceMode === 'IN' ? item.quantity + bItem.quantity : item.quantity - bItem.quantity;
          return { ...item, quantity: newQty, lastUpdated: timestamp };
        }
        return item;
      });
      newLogs.push({ 
        id: generateId() + Math.random().toString(36).substr(2, 4), 
        itemId: bItem.itemId, 
        itemName: bItem.name, 
        type: issuanceMode, 
        quantity: bItem.quantity, 
        person: inputPerson || '未填寫', 
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處', 
        reason: inputReason, 
        timestamp 
      });
    });

    const finalLogs = [...newLogs, ...logs];
    setItems(updatedItems);
    setLogs(finalLogs);
    syncToCloud(updatedItems, finalLogs);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({ 
        id: generateId(), 
        dept: selectedDept, 
        person: inputPerson, 
        reason: inputReason, 
        items: [...basket], 
        timestamp 
      });
      setShowPrintModal(true);
    } else {
      window.alert(`✅ 補貨成功。`);
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  const handleFinalPrint = () => {
    if (!lastTransactionBatch) return;
    window.print();
  };

  return (
    <div className="min-h-screen flex bg-slate-100 text-black font-sans">
      <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={importData} />

      {/* 側邊欄 */}
      <aside className="w-72 bg-slate-900 text-white p-6 flex flex-col shrink-0 border-r border-slate-800 shadow-2xl no-print">
        <div className="flex flex-col gap-1 mb-8">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22} className="text-white"/></div>
            <h1 className="font-black text-xl tracking-tight text-white">工安管理系統</h1>
          </div>
          <div className="mt-6 bg-slate-800/50 rounded-2xl p-4 border border-slate-700/50">
            <div className="flex items-center justify-between mb-2">
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">雲端連線</span>
              <div className={`w-3 h-3 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500' : 'bg-orange-400 animate-pulse'}`}></div>
            </div>
            <div className="text-sm font-black text-white">{syncStatus === 'synced' ? '已連線' : '同步中/未連線'}</div>
            <div className="text-[10px] text-slate-400 mt-1 font-bold">最後同步：{lastSyncTime}</div>
          </div>
        </div>
        <nav className="flex-1 space-y-1">
          {[
            { id: 'inventory', label: '工安耗材管理', icon: Package },
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
            { id: 'issuance', label: '領用補貨作業', icon: FileText },
            { id: 'history', label: '歷史異動日誌', icon: History },
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard },
          ].map((tab) => (
            <button 
              key={tab.id} 
              onClick={() => setActiveTab(tab.id as any)} 
              className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}
            >
              <tab.icon size={20} /> {tab.label}
            </button>
          ))}
        </nav>
        <div className="pt-6 mt-6 border-t border-slate-800 space-y-2">
            <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-black text-slate-300 hover:bg-slate-800 transition-all"><Settings size={16}/> 雲端設定</button>
            <button onClick={exportData} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800 transition-all"><Download size={16}/> 匯出備份</button>
        </div>
      </aside>

      <main className="flex-1 p-10 overflow-y-auto no-print">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-3xl font-black text-black">
            {activeTab === 'inventory' ? '工安耗材清冊' : 
             activeTab === 'medicine' ? '急救藥材清冊' : 
             activeTab === 'issuance' ? '領用 / 補貨登記' : 
             activeTab === 'history' ? '歷史異動日誌' : '數據統計看板'}
          </h2>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-black shadow-xl"><Plus size={18}/> 新增項目</button>
          )}
        </header>

        {activeTab === 'issuance' && (
          <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
            <div className="lg:col-span-2 bg-white p-8 rounded-3xl shadow-xl border border-slate-200">
              <h3 className="text-xl font-black mb-8 flex items-center gap-2"><ShoppingCart className="text-blue-500"/> 1. 挑選項目</h3>
              <div className="flex bg-slate-100 p-1 rounded-xl mb-6">
                <button onClick={()=>setIssuanceMode('OUT')} className={`flex-1 py-3 rounded-lg font-black ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button>
