                  {items.map(i => <option key={i.id} value={i.id}>{i.name} (庫存:{i.quantity})</option>)}
                </select>
                <input type="number" className="w-full p-4 rounded-xl text-xl font-bold" value={inputQty} onChange={e=>setInputQty(e.target.value)} placeholder="數量"/>
                <button onClick={addToBasket} disabled={!selectedItemId} className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black text-xl shadow-lg hover:bg-black transition-all">加入處理清單</button>
              </div>
            </div>
            <div className="lg:col-span-3 bg-white p-8 rounded-3xl shadow-xl border border-slate-200 flex flex-col">
