              <div className="flex-1 bg-slate-50 rounded-2xl p-4 mb-6 overflow-y-auto min-h-[200px]">
                {basket.map((b, idx) => (
                  <div key={idx} className="flex justify-between items-center p-4 bg-white mb-2 rounded-xl shadow-sm border border-slate-100">
                    <span className="font-bold text-black">{b.name}</span>
                    <div className="flex items-center gap-4">
                      <span className="font-black text-blue-600">x{b.quantity} {b.unit}</span>
                      <button onClick={()=>setBasket(prev => prev.filter((_, i) => i !== idx))} className="text-slate-300 hover:text-red-500"><X size={18}/></button>
                    </div>
                  </div>
                ))}
              </div>
              {issuanceMode === 'OUT' && (
                <div className="grid grid-cols-2 gap-4 mb-6">
                   <select className="p-4 rounded-xl font-bold border-2" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>
                      {DEPARTMENTS.map(d=><option key={d}>{d}</option>)}
                   </select>
                   <input className="p-4 rounded-xl font-bold border-2" placeholder="領用人" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/>
                </div>
              )}
              <button onClick={processIssuance} disabled={basket.length===0} className={`w-full py-6 rounded-2xl font-black text-3xl text-white shadow-2xl transition-all ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>確認過帳</button>
            </div>
          </div>
        )}

        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-200">
