                <tr><th className="px-8 py-5">名稱</th><th className="px-8 py-5 text-center">目前庫存</th><th className="px-8 py-5 text-right">管理</th></tr>
              </thead>
              <tbody className="divide-y">
                {items.filter(i => (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') && i.name.includes(searchTerm)).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-8 py-5 font-black text-black">{item.name}</td>
                    <td className="px-8 py-5 text-center">
