                    </td>
                    <td className="px-8 py-5 text-right flex justify-end gap-2">
                      <button onClick={()=>setEditTarget(item)} className="p-2 text-slate-400 hover:text-blue-600 transition-colors"><Edit3 size={18}/></button>
                      <button onClick={()=>setDeleteTarget({id: item.id, name: item.name})} className="p-2 text-slate-400 hover:text-red-600 transition-colors"><Trash2 size={18}/></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {showSettings && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[600] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl">
              <h3 className="text-2xl font-black mb-6">雲端連線同步設定</h3>
              <input id="gas-url-input" className="w-full p-4 rounded-xl border-2 mb-6 text-black" placeholder="貼上 GAS Web App 網址" defaultValue={gasUrl}/>
              <div className="flex gap-4">
                <button onClick={() => handleGasUrlSave((document.getElementById('gas-url-input') as HTMLInputElement).value)} className="flex-1 py-4 bg-blue-600 text-white rounded-2xl font-black">儲存並同步</button>
                <button onClick={() => setShowSettings(false)} className="px-8 py-4 bg-slate-100 rounded-2xl font-bold">返回</button>
              </div>
            </div>
          </div>
        )}
      </main>

      {showPrintModal && lastTransactionBatch && (
        <div className="fixed inset-0 bg-white z-[1000] overflow-y-auto p-10">
          <div className="max-w-4xl mx-auto border-4 border-black p-8 text-black" style={{ minHeight: '1000px' }}>
            <h1 className="text-center text-4xl font-black mb-8">台灣電力公司電力修護處南部分處</h1>
            <div className="flex justify-between font-bold text-xl mb-4">
               <span>領用部門：{lastTransactionBatch.dept}</span>
               <span>領用人：{lastTransactionBatch.person}</span>
               <span>日期：{new Date(lastTransactionBatch.timestamp).toLocaleDateString()}</span>
            </div>
            <table className="w-full border-collapse border-4 border-black">
               <thead>
                  <tr className="bg-gray-100">
                    <th className="border-4 border-black p-4">名稱</th>
                    <th className="border-4 border-black p-4">數量</th>
                    <th className="border-4 border-black p-4">單位</th>
                    <th className="border-4 border-black p-4">備註</th>
                  </tr>
               </thead>
               <tbody>
                  {lastTransactionBatch.items.map((it, i) => (
                    <tr key={i}>
                      <td className="border-4 border-black p-4 text-center font-black">{it.name}</td>
                      <td className="border-4 border-black p-4 text-center font-black text-2xl">{it.quantity}</td>
                      <td className="border-4 border-black p-4 text-center">{it.unit}</td>
                      <td className="border-4 border-black p-4 text-center">{lastTransactionBatch.reason}</td>
                    </tr>
                  ))}
               </tbody>
            </table>
            <div className="mt-20 flex justify-between text-xl font-black">
               <span>申請人簽章：_______________</span>
               <span>主管簽章：_______________</span>
            </div>
            <div className="mt-20 flex justify-end no-print">
               <button onClick={() => window.print()} className="bg-blue-600 text-white px-10 py-4 rounded-xl font-black text-2xl shadow-xl mr-4">確認列印</button>
               <button onClick={()=>setShowPrintModal(false)} className="bg-slate-200 px-10 py-4 rounded-xl font-black text-2xl">關閉預覽</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  CheckCircle2,
  Users,
  Download,
  Settings,
  Cloud,
  Save
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v36_items';
const STORAGE_KEY_LOGS = 'safeman_v36_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v36_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v36_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error' | 'local'>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '從未同步');

  // Modals
  const [showSettings, setShowSettings] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);

  // Form States
  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  // AI
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Print Data
  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) try { setItems(JSON.parse(savedItems)); } catch(e) {}
    if (savedLogs) try { setLogs(JSON.parse(savedLogs)); } catch(e) {}
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  // Cloud Functions
  const syncToCloud = async (currentItems: InventoryItem[], currentLogs: Transaction[]) => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const payload = { items: currentItems, logs: currentLogs, timestamp: Date.now() };
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify(payload), mode: 'no-cors' });
      setSyncStatus('synced');
      const time = new Date().toLocaleString();
      setLastSyncTime(time);
      localStorage.setItem(STORAGE_KEY_LAST_SYNC, time);
    } catch (e) { setSyncStatus('error'); }
  };

  const handleAddItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: InventoryItem = {
      id: Date.now().toString(),
      name: formData.get('name') as string,
      category: formData.get('category') as Category,
      itemType: formData.get('itemType') as ItemType,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    };
    const newItems = [...items, newItem];
    setItems(newItems);
    syncToCloud(newItems, logs);
    setShowAddModal(false);
  };

  const handleEditItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editTarget) return;
    const formData = new FormData(e.currentTarget);
    const updatedItems = items.map(i => i.id === editTarget.id ? {
      ...i,
      name: formData.get('name') as string,
      category: formData.get('category') as Category,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      minStock: Number(formData.get('minStock')),
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    } : i);
    setItems(updatedItems);
    syncToCloud(updatedItems, logs);
    setEditTarget(null);
  };

  const handleDelete = () => {
    if (!deleteTarget) return;
    const newItems = items.filter(i => i.id !== deleteTarget.id);
    setItems(newItems);
    syncToCloud(newItems, logs);
    setDeleteTarget(null);
  };

  const addToBasket = () => {
    const target = items.find(i => i.id === selectedItemId);
    if (!target) return;
    const qty = Number(inputQty);
    if (qty <= 0) return;
    setBasket([...basket, { itemId: target.id, name: target.name, quantity: qty, unit: target.unit }]);
    setSelectedItemId('');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const ts = Date.now();
    let nextItems = [...items];
    const nextLogs: Transaction[] = [];

    basket.forEach(b => {
      nextItems = nextItems.map(item => {
        if (item.id === b.itemId) {
          const nQty = issuanceMode === 'OUT' ? item.quantity - b.quantity : item.quantity + b.quantity;
          return { ...item, quantity: nQty, lastUpdated: ts };
        }
        return item;
      });
      nextLogs.push({
        id: `TX-${ts}-${b.itemId}`,
        itemId: b.itemId,
        itemName: b.name,
        type: issuanceMode,
        quantity: b.quantity,
        person: inputPerson || '系統管理員',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: inputReason,
        timestamp: ts
      });
    });

    const combinedLogs = [...nextLogs, ...logs];
    setItems(nextItems);
    setLogs(combinedLogs);
    syncToCloud(nextItems, combinedLogs);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({
        id: `SN-${ts.toString().slice(-6)}`,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: ts
      });
      setShowPrintModal(true);
    } else {
      alert('補貨完成');
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    const msg = await getInventoryInsights(items);
    setAiInsights(msg);
    setIsAiLoading(false);
  };

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900">
      {/* Sidebar */}
      <aside className="w-72 bg-slate-900 text-white flex flex-col no-print">
        <div className="p-8">
          <div className="flex items-center gap-3 mb-8">
            <div className="w-10 h-10 bg-blue-500 rounded-xl flex items-center justify-center shadow-lg shadow-blue-500/20">
              <Package className="text-white" size={24} />
            </div>
            <span className="text-xl font-black tracking-tight">SAFETY PRO</span>
          </div>

          <nav className="space-y-2">
            {[
              { id: 'inventory', label: '工安耗材', icon: Package },
              { id: 'medicine', label: '急救藥材', icon: Stethoscope },
              { id: 'issuance', label: '領用/補貨', icon: ShoppingCart },
              { id: 'history', label: '異動日誌', icon: History },
              { id: 'dashboard', label: '統計看板', icon: LayoutDashboard },
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${
                  activeTab === tab.id ? 'bg-blue-600 text-white' : 'text-slate-400 hover:bg-slate-800'
                }`}
              >
                <tab.icon size={20} /> {tab.label}
              </button>
            ))}
          </nav>
        </div>

        <div className="mt-auto p-8 space-y-4">
          <div className="bg-slate-800/50 rounded-2xl p-4 border border-slate-700/50">
            <div className="flex items-center justify-between mb-2">
              <span className="text-[10px] font-black text-slate-500 uppercase">Cloud Sync</span>
              <div className={`w-2 h-2 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500' : 'bg-orange-500'}`} />
            </div>
            <p className="text-xs text-slate-400">最後同步: {lastSyncTime}</p>
          </div>
          <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-2 text-slate-400 hover:text-white transition-colors text-sm font-bold">
            <Settings size={16} /> 系統設定
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-10 overflow-y-auto no-print">
        <div className="max-w-6xl mx-auto">
          <header className="flex justify-between items-center mb-10">
            <div>
              <h2 className="text-3xl font-black">
                {activeTab === 'inventory' ? '工安耗材管理' : 
                 activeTab === 'medicine' ? '急救藥材管理' : 
                 activeTab === 'issuance' ? '領用補貨作業' : 
                 activeTab === 'history' ? '歷史異動日誌' : '庫存數據分析'}
              </h2>
              <p className="text-slate-500 font-medium">即時監控工安資源與消耗狀況</p>
            </div>
            {(activeTab === 'inventory' || activeTab === 'medicine') && (
              <button onClick={() => setShowAddModal(true)} className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-blue-600/20">
                <Plus size={20} /> 新增項目
              </button>
            )}
          </header>

          {activeTab === 'issuance' && (
            <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
              <div className="lg:col-span-2 space-y-6">
                <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
                  <div className="flex bg-slate-100 p-1.5 rounded-2xl mb-8">
                    <button onClick={()=>setIssuanceMode('OUT')} className={`flex-1 py-3 rounded-xl font-black transition-all ${issuanceMode==='OUT' ? 'bg-white shadow-md text-blue-600' : 'text-slate-500'}`}>領用出庫</button>
                    <button onClick={()=>setIssuanceMode('IN')} className={`flex-1 py-3 rounded-xl font-black transition-all ${issuanceMode==='IN' ? 'bg-white shadow-md text-emerald-600' : 'text-slate-500'}`}>補貨入庫</button>
                  </div>
                  <div className="space-y-4">
                    <label className="block text-sm font-black text-slate-500 uppercase">選擇品項</label>
                    <select className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                      <option value="">請點擊選擇...</option>
                      {items.map(i => <option key={i.id} value={i.id}>{i.name} (剩餘 {i.quantity})</option>)}
                    </select>
                    <label className="block text-sm font-black text-slate-500 uppercase">數量</label>
                    <input type="number" className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold text-xl" value={inputQty} onChange={e=>setInputQty(e.target.value)} />
                    <button onClick={addToBasket} disabled={!selectedItemId} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black hover:bg-black disabled:opacity-50 mt-4 transition-all">加入處理清單</button>
                  </div>
                </div>
              </div>

              <div className="lg:col-span-3 bg-white p-8 rounded-3xl shadow-sm border border-slate-200 flex flex-col">
                <h3 className="text-xl font-black mb-6">待處理清單 ({basket.length})</h3>
                <div className="flex-1 bg-slate-50 rounded-2xl p-4 mb-6 overflow-y-auto space-y-3 min-h-[300px] border-2 border-dashed border-slate-200">
                  {basket.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center text-slate-400">
                      <ShoppingCart size={48} className="mb-2 opacity-20" />
                      <p className="font-bold">尚未選擇任何項目</p>
                    </div>
                  ) : (
                    basket.map((b, idx) => (
                      <div key={idx} className="flex justify-between items-center p-4 bg-white rounded-xl shadow-sm border border-slate-100 group">
                        <div>
                          <p className="font-black text-slate-800">{b.name}</p>
                          <p className="text-xs text-slate-400 font-bold">ID: {b.itemId}</p>
                        </div>
                        <div className="flex items-center gap-6">
                          <span className="font-black text-blue-600 text-lg">{b.quantity} <span className="text-sm">{b.unit}</span></span>
                          <button onClick={()=>setBasket(prev=>prev.filter((_,i)=>i!==idx))} className="text-slate-300 hover:text-red-500 transition-colors"><X size={20}/></button>
                        </div>
                      </div>
                    ))
                  )}
                </div>

                {issuanceMode === 'OUT' && (
                  <div className="grid grid-cols-2 gap-4 mb-6">
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-400 uppercase">領用部門</label>
                      <select className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>
                        {DEPARTMENTS.map(d=><option key={d}>{d}</option>)}
                      </select>
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-400 uppercase">領用人</label>
                      <input className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" placeholder="輸入姓名" value={inputPerson} onChange={e=>setInputPerson(e.target.value)} />
                    </div>
                  </div>
                )}

                <div className="space-y-2 mb-6">
                  <label className="text-xs font-black text-slate-400 uppercase">用途備註</label>
                  <input className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" placeholder="例：南一隊例行領用" value={inputReason} onChange={e=>setInputReason(e.target.value)} />
                </div>

                <button onClick={processIssuance} disabled={basket.length===0} className={`w-full py-6 rounded-2xl font-black text-2xl text-white shadow-xl transition-all ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>
                  {issuanceMode==='OUT' ? '確認領用並列印' : '確認入庫'}
                </button>
              </div>
            </div>
          )}

          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <div className="grid grid-cols-4 gap-6 mb-8">
              <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                <p className="text-slate-400 text-xs font-black uppercase mb-1">項目總數</p>
                <p className="text-3xl font-black">{items.filter(i => activeTab==='medicine' ? i.itemGroup==='MEDICINE' : i.itemGroup==='INVENTORY').length}</p>
              </div>
              <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                <p className="text-red-400 text-xs font-black uppercase mb-1">庫存預警</p>
                <p className="text-3xl font-black text-red-500">{items.filter(i => (activeTab==='medicine' ? i.itemGroup==='MEDICINE' : i.itemGroup==='INVENTORY') && i.quantity <= i.minStock).length}</p>
              </div>
            </div>
          )}

          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
               <div className="p-6 bg-slate-50 border-b flex items-center justify-between">
                  <div className="relative w-96">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18}/>
                    <input className="w-full pl-12 pr-4 py-3 rounded-xl bg-white border border-slate-200 font-bold" placeholder="搜尋名稱或規格..." value={searchTerm} onChange={e=>setSearchTerm(e.target.value)} />
                  </div>
               </div>
               <table className="w-full border-collapse">
                 <thead>
                    <tr className="bg-slate-100/50 text-left border-b border-slate-200">
                      <th className="px-8 py-5 text-[11px] font-black text-slate-500 uppercase">品項名稱</th>
                      <th className="px-8 py-5 text-[11px] font-black text-slate-500 uppercase">規格/尺寸</th>
                      <th className="px-8 py-5 text-[11px] font-black text-slate-500 uppercase text-center">當前庫存</th>
                      <th className="px-8 py-5 text-[11px] font-black text-slate-500 uppercase">最後更新</th>
                      <th className="px-8 py-5 text-[11px] font-black text-slate-500 uppercase text-right">管理</th>
                    </tr>
                 </thead>
                 <tbody className="divide-y divide-slate-100">
                    {items.filter(i => (activeTab==='medicine' ? i.itemGroup==='MEDICINE' : i.itemGroup==='INVENTORY') && i.name.includes(searchTerm)).map(item => (
                      <tr key={item.id} className="hover:bg-blue-50/30 transition-colors group">
                        <td className="px-8 py-6">
                          <div className="font-black text-slate-800">{item.name}</div>
                          <div className="text-[10px] font-bold text-slate-400 mt-0.5">{item.category}</div>
                        </td>
                        <td className="px-8 py-6 font-bold text-slate-500">{item.spec || '-'}</td>
                        <td className="px-8 py-6 text-center">
                          <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-xl font-black ${item.quantity <= item.minStock ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>
                            {item.quantity} <span className="text-xs opacity-70">{item.unit}</span>
                          </div>
                        </td>
                        <td className="px-8 py-6 text-sm text-slate-400 font-medium">
                          {new Date(item.lastUpdated).toLocaleDateString()}
                        </td>
                        <td className="px-8 py-6 text-right">
                           <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                              <button onClick={()=>setEditTarget(item)} className="p-3 bg-white border border-slate-200 rounded-lg shadow-sm hover:text-blue-600"><Edit3 size={16}/></button>
                              <button onClick={()=>setDeleteTarget({id: item.id, name: item.name})} className="p-3 bg-white border border-slate-200 rounded-lg shadow-sm hover:text-red-600"><Trash2 size={16}/></button>
                           </div>
                        </td>
                      </tr>
                    ))}
                 </tbody>
               </table>
            </div>
          )}

          {activeTab === 'history' && (
            <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
               <table className="w-full text-left">
                  <thead className="bg-slate-100 text-[11px] font-black text-slate-500 uppercase border-b">
                    <tr>
                      <th className="px-8 py-5">時間</th>
                      <th className="px-8 py-5">動作</th>
                      <th className="px-8 py-5">品項</th>
                      <th className="px-8 py-5">數量</th>
                      <th className="px-8 py-5">領用單位/人</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {logs.map(log => (
                      <tr key={log.id} className="hover:bg-slate-50">
                        <td className="px-8 py-5 text-sm text-slate-500 font-medium">{new Date(log.timestamp).toLocaleString()}</td>
                        <td className="px-8 py-5">
                          <span className={`inline-flex items-center gap-1 px-3 py-1 rounded-full text-[10px] font-black uppercase ${log.type === 'IN' ? 'bg-emerald-100 text-emerald-600' : 'bg-blue-100 text-blue-600'}`}>
                            {log.type === 'IN' ? <ArrowUpRight size={12}/> : <ArrowDownLeft size={12}/>}
                            {log.type === 'IN' ? '補貨' : '領用'}
                          </span>
                        </td>
                        <td className="px-8 py-5 font-bold text-slate-800">{log.itemName}</td>
                        <td className="px-8 py-5 font-black">{log.type === 'IN' ? '+' : '-'}{log.quantity}</td>
                        <td className="px-8 py-5">
                          <div className="text-sm font-bold text-slate-800">{log.dept}</div>
                          <div className="text-[10px] text-slate-400 font-black">{log.person}</div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
               </table>
            </div>
          )}

          {activeTab === 'dashboard' && (
            <div className="space-y-8">
               <div className="bg-slate-900 rounded-[2.5rem] p-10 text-white relative overflow-hidden">
                  <BrainCircuit className="absolute -right-10 -bottom-10 w-64 h-64 opacity-10" />
                  <div className="relative z-10">
                    <h3 className="text-2xl font-black mb-4 flex items-center gap-3"><BrainCircuit className="text-blue-400"/> AI 庫存智能分析</h3>
                    <div className="bg-slate-800/50 backdrop-blur-sm p-6 rounded-2xl border border-slate-700 leading-relaxed mb-6 min-h-[100px]">
                      {isAiLoading ? "正在分析數據中..." : (aiInsights || "點擊下方按鈕以獲取建議")}
                    </div>
                    <button onClick={fetchAiInsights} disabled={isAiLoading} className="bg-blue-600 hover:bg-blue-500 text-white px-8 py-4 rounded-2xl font-black shadow-xl flex items-center gap-2 transition-all">
                      <RefreshCw className={isAiLoading ? 'animate-spin' : ''} size={20}/> 執行智能診斷
                    </button>
                  </div>
               </div>
            </div>
          )}
        </div>
      </main>

      {/* 新增/編輯 Modal */}
      {(showAddModal || editTarget) && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[500] flex items-center justify-center p-4">
           <form onSubmit={editTarget ? handleEditItem : handleAddItem} className="bg-white rounded-[2.5rem] w-full max-w-2xl overflow-hidden shadow-2xl">
              <div className="p-10">
                <h3 className="text-2xl font-black mb-8">{editTarget ? `編輯項目: ${editTarget.name}` : '新增管理項目'}</h3>
                <div className="grid grid-cols-2 gap-6 mb-8">
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 uppercase">品項名稱</label>
                    <input name="name" required defaultValue={editTarget?.name} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 uppercase">規格 / 尺寸</label>
                    <input name="spec" defaultValue={editTarget?.spec} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 uppercase">類別</label>
                    <select name="category" defaultValue={editTarget?.category || Category.PROTECTION} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold">
                      {Object.values(Category).map(c=><option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 uppercase">類型</label>
                    <select name="itemType" defaultValue={editTarget?.itemType || 'CONSUMABLE'} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold">
                      <option value="CONSUMABLE">消耗品</option>
                      <option value="EQUIPMENT">設備</option>
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 uppercase">單位</label>
                    <input name="unit" required defaultValue={editTarget?.unit || '個'} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" />
                  </div>
                  {!editTarget && (
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-400 uppercase">初始庫存</label>
                      <input name="quantity" type="number" required defaultValue="0" className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" />
                    </div>
                  )}
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 uppercase">安全庫存量 (警示)</label>
                    <input name="minStock" type="number" required defaultValue={editTarget?.minStock || 5} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" />
                  </div>
                </div>
                <div className="flex gap-4">
                   <button type="submit" className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-lg hover:bg-blue-700 transition-all">確認提交</button>
                   <button type="button" onClick={()=>{setShowAddModal(false); setEditTarget(null);}} className="px-10 py-5 bg-slate-100 rounded-2xl font-black text-xl hover:bg-slate-200">取消</button>
                </div>
              </div>
           </form>
        </div>
      )}

      {/* 刪除確認 Modal */}
      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[700] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-10 max-w-md w-full shadow-2xl">
             <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-6"><AlertTriangle size={32}/></div>
             <h3 className="text-2xl font-black text-center mb-2">確定要刪除？</h3>
             <p className="text-slate-500 text-center font-bold mb-8">您即將刪除 <span className="text-black">"{deleteTarget.name}"</span>，此操作無法復原。</p>
             <div className="flex gap-4">
                <button onClick={handleDelete} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black shadow-lg hover:bg-red-700">確認刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="flex-1 py-4 bg-slate-100 rounded-2xl font-black hover:bg-slate-200">取消</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  CheckCircle2,
  Users,
  Download,
  Settings,
  Cloud,
  Save,
  // Fix: Added missing icons required by the UI
  ArrowUpRight,
  ArrowDownLeft,
  RefreshCw
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v36_items';
const STORAGE_KEY_LOGS = 'safeman_v36_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v36_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v36_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error' | 'local'>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '從未同步');

  // Modals
  const [showSettings, setShowSettings] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);

  // Form States
  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  // AI
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Print Data
  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) try { setItems(JSON.parse(savedItems)); } catch(e) {}
    if (savedLogs) try { setLogs(JSON.parse(savedLogs)); } catch(e) {}
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  // Cloud Functions
  const syncToCloud = async (currentItems: InventoryItem[], currentLogs: Transaction[]) => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const payload = { items: currentItems, logs: currentLogs, timestamp: Date.now() };
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify(payload), mode: 'no-cors' });
      setSyncStatus('synced');
      const time = new Date().toLocaleString();
      setLastSyncTime(time);
      localStorage.setItem(STORAGE_KEY_LAST_SYNC, time);
    } catch (e) { setSyncStatus('error'); }
  };

  const handleAddItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: InventoryItem = {
      id: Date.now().toString(),
      name: formData.get('name') as string,
      category: formData.get('category') as Category,
      itemType: formData.get('itemType') as ItemType,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    };
    const newItems = [...items, newItem];
    setItems(newItems);
    syncToCloud(newItems, logs);
    setShowAddModal(false);
  };

  const handleEditItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editTarget) return;
    const formData = new FormData(e.currentTarget);
    const updatedItems = items.map(i => i.id === editTarget.id ? {
      ...i,
      name: formData.get('name') as string,
      category: formData.get('category') as Category,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      minStock: Number(formData.get('minStock')),
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    } : i);
    setItems(updatedItems);
    syncToCloud(updatedItems, logs);
    setEditTarget(null);
  };

  const handleDelete = () => {
    if (!deleteTarget) return;
    const newItems = items.filter(i => i.id !== deleteTarget.id);
    setItems(newItems);
    syncToCloud(newItems, logs);
    setDeleteTarget(null);
  };

  const addToBasket = () => {
    const target = items.find(i => i.id === selectedItemId);
    if (!target) return;
    const qty = Number(inputQty);
    if (qty <= 0) return;
    setBasket([...basket, { itemId: target.id, name: target.name, quantity: qty, unit: target.unit }]);
    setSelectedItemId('');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const ts = Date.now();
    let nextItems = [...items];
    const nextLogs: Transaction[] = [];

    basket.forEach(b => {
      nextItems = nextItems.map(item => {
        if (item.id === b.itemId) {
          const nQty = issuanceMode === 'OUT' ? item.quantity - b.quantity : item.quantity + b.quantity;
          return { ...item, quantity: nQty, lastUpdated: ts };
        }
        return item;
      });
      nextLogs.push({
        id: `TX-${ts}-${b.itemId}`,
        itemId: b.itemId,
        itemName: b.name,
        type: issuanceMode,
        quantity: b.quantity,
        person: inputPerson || '系統管理員',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: inputReason,
        timestamp: ts
      });
    });

    const combinedLogs = [...nextLogs, ...logs];
    setItems(nextItems);
    setLogs(combinedLogs);
    syncToCloud(nextItems, combinedLogs);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({
        id: `SN-${ts.toString().slice(-6)}`,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: ts
      });
      setShowPrintModal(true);
    } else {
      alert('補貨完成');
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    const msg = await getInventoryInsights(items);
    setAiInsights(msg);
    setIsAiLoading(false);
  };

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900">
      {/* Sidebar */}
      <aside className="w-72 bg-slate-900 text-white flex flex-col no-print">
        <div className="p-8">
          <div className="flex items-center gap-3 mb-8">
            <div className="w-10 h-10 bg-blue-500 rounded-xl flex items-center justify-center shadow-lg shadow-blue-500/20">
              <Package className="text-white" size={24} />
            </div>
            <span className="text-xl font-black tracking-tight">SAFETY PRO</span>
          </div>

          <nav className="space-y-2">
            {[
              { id: 'inventory', label: '工安耗材', icon: Package },
              { id: 'medicine', label: '急救藥材', icon: Stethoscope },
              { id: 'issuance', label: '領用/補貨', icon: ShoppingCart },
              { id: 'history', label: '異動日誌', icon: History },
              { id: 'dashboard', label: '統計看板', icon: LayoutDashboard },
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${
                  activeTab === tab.id ? 'bg-blue-600 text-white' : 'text-slate-400 hover:bg-slate-800'
                }`}
              >
                <tab.icon size={20} /> {tab.label}
              </button>
            ))}
          </nav>
        </div>

        <div className="mt-auto p-8 space-y-4">
          <div className="bg-slate-800/50 rounded-2xl p-4 border border-slate-700/50">
            <div className="flex items-center justify-between mb-2">
              <span className="text-[10px] font-black text-slate-500 uppercase">Cloud Sync</span>
              <div className={`w-2 h-2 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500' : 'bg-orange-500'}`} />
            </div>
            <p className="text-xs text-slate-400">最後同步: {lastSyncTime}</p>
          </div>
          <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-2 text-slate-400 hover:text-white transition-colors text-sm font-bold">
            <Settings size={16} /> 系統設定
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-10 overflow-y-auto no-print">
        <div className="max-w-6xl mx-auto">
          <header className="flex justify-between items-center mb-10">
            <div>
              <h2 className="text-3xl font-black">
                {activeTab === 'inventory' ? '工安耗材管理' : 
                 activeTab === 'medicine' ? '急救藥材管理' : 
                 activeTab === 'issuance' ? '領用補貨作業' : 
                 activeTab === 'history' ? '歷史異動日誌' : '庫存數據分析'}
              </h2>
              <p className="text-slate-500 font-medium">即時監控工安資源與消耗狀況</p>
            </div>
            {(activeTab === 'inventory' || activeTab === 'medicine') && (
              <button onClick={() => setShowAddModal(true)} className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-blue-600/20">
                <Plus size={20} /> 新增項目
              </button>
            )}
          </header>

          {activeTab === 'issuance' && (
            <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
              <div className="lg:col-span-2 space-y-6">
                <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
                  <div className="flex bg-slate-100 p-1.5 rounded-2xl mb-8">
                    <button onClick={()=>setIssuanceMode('OUT')} className={`flex-1 py-3 rounded-xl font-black transition-all ${issuanceMode==='OUT' ? 'bg-white shadow-md text-blue-600' : 'text-slate-500'}`}>領用出庫</button>
                    <button onClick={()=>setIssuanceMode('IN')} className={`flex-1 py-3 rounded-xl font-black transition-all ${issuanceMode==='IN' ? 'bg-white shadow-md text-emerald-600' : 'text-slate-500'}`}>補貨入庫</button>
                  </div>
                  <div className="space-y-4">
                    <label className="block text-sm font-black text-slate-500 uppercase">選擇品項</label>
                    <select className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                      <option value="">請點擊選擇...</option>
                      {items.map(i => <option key={i.id} value={i.id}>{i.name} (剩餘 {i.quantity})</option>)}
                    </select>
                    <label className="block text-sm font-black text-slate-500 uppercase">數量</label>
                    <input type="number" className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold text-xl" value={inputQty} onChange={e=>setInputQty(e.target.value)} />
                    <button onClick={addToBasket} disabled={!selectedItemId} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black hover:bg-black disabled:opacity-50 mt-4 transition-all">加入處理清單</button>
                  </div>
                </div>
              </div>

              <div className="lg:col-span-3 bg-white p-8 rounded-3xl shadow-sm border border-slate-200 flex flex-col">
                <h3 className="text-xl font-black mb-6">待處理清單 ({basket.length})</h3>
                <div className="flex-1 bg-slate-50 rounded-2xl p-4 mb-6 overflow-y-auto space-y-3 min-h-[300px] border-2 border-dashed border-slate-200">
                  {basket.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center text-slate-400">
                      <ShoppingCart size={48} className="mb-2 opacity-20" />
                      <p className="font-bold">尚未選擇任何項目</p>
                    </div>
                  ) : (
                    basket.map((b, idx) => (
                      <div key={idx} className="flex justify-between items-center p-4 bg-white rounded-xl shadow-sm border border-slate-100 group">
                        <div>
                          <p className="font-black text-slate-800">{b.name}</p>
                          <p className="text-xs text-slate-400 font-bold">ID: {b.itemId}</p>
                        </div>
                        <div className="flex items-center gap-6">
                          <span className="font-black text-blue-600 text-lg">{b.quantity} <span className="text-sm">{b.unit}</span></span>
                          <button onClick={()=>setBasket(prev=>prev.filter((_,i)=>i!==idx))} className="text-slate-300 hover:text-red-500 transition-colors"><X size={20}/></button>
                        </div>
                      </div>
                    ))
                  )}
                </div>

                {issuanceMode === 'OUT' && (
                  <div className="grid grid-cols-2 gap-4 mb-6">
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-400 uppercase">領用部門</label>
                      <select className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>
                        {DEPARTMENTS.map(d=><option key={d}>{d}</option>)}
                      </select>
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-400 uppercase">領用人</label>
                      <input className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" placeholder="輸入姓名" value={inputPerson} onChange={e=>setInputPerson(e.target.value)} />
                    </div>
                  </div>
                )}

                <div className="space-y-2 mb-6">
                  <label className="text-xs font-black text-slate-400 uppercase">用途備註</label>
                  <input className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" placeholder="例：南一隊例行領用" value={inputReason} onChange={e=>setInputReason(e.target.value)} />
                </div>

                <button onClick={processIssuance} disabled={basket.length===0} className={`w-full py-6 rounded-2xl font-black text-2xl text-white shadow-xl transition-all ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>
                  {issuanceMode==='OUT' ? '確認領用並列印' : '確認入庫'}
                </button>
              </div>
            </div>
          )}

          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <div className="grid grid-cols-4 gap-6 mb-8">
              <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                <p className="text-slate-400 text-xs font-black uppercase mb-1">項目總數</p>
                <p className="text-3xl font-black">{items.filter(i => activeTab==='medicine' ? i.itemGroup==='MEDICINE' : i.itemGroup==='INVENTORY').length}</p>
              </div>
              <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                <p className="text-red-400 text-xs font-black uppercase mb-1">庫存預警</p>
                <p className="text-3xl font-black text-red-500">{items.filter(i => (activeTab==='medicine' ? i.itemGroup==='MEDICINE' : i.itemGroup==='INVENTORY') && i.quantity <= i.minStock).length}</p>
              </div>
            </div>
          )}

          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
               <div className="p-6 bg-slate-50 border-b flex items-center justify-between">
                  <div className="relative w-96">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18}/>
                    <input className="w-full pl-12 pr-4 py-3 rounded-xl bg-white border border-slate-200 font-bold" placeholder="搜尋名稱或規格..." value={searchTerm} onChange={e=>setSearchTerm(e.target.value)} />
                  </div>
               </div>
               <table className="w-full border-collapse">
                 <thead>
                    <tr className="bg-slate-100/50 text-left border-b border-slate-200">
                      <th className="px-8 py-5 text-[11px] font-black text-slate-500 uppercase">品項名稱</th>
                      <th className="px-8 py-5 text-[11px] font-black text-slate-500 uppercase">規格/尺寸</th>
                      <th className="px-8 py-5 text-[11px] font-black text-slate-500 uppercase text-center">當前庫存</th>
                      <th className="px-8 py-5 text-[11px] font-black text-slate-500 uppercase">最後更新</th>
                      <th className="px-8 py-5 text-[11px] font-black text-slate-500 uppercase text-right">管理</th>
                    </tr>
                 </thead>
                 <tbody className="divide-y divide-slate-100">
                    {items.filter(i => (activeTab==='medicine' ? i.itemGroup==='MEDICINE' : i.itemGroup==='INVENTORY') && i.name.includes(searchTerm)).map(item => (
                      <tr key={item.id} className="hover:bg-blue-50/30 transition-colors group">
                        <td className="px-8 py-6">
                          <div className="font-black text-slate-800">{item.name}</div>
                          <div className="text-[10px] font-bold text-slate-400 mt-0.5">{item.category}</div>
                        </td>
                        <td className="px-8 py-6 font-bold text-slate-500">{item.spec || '-'}</td>
                        <td className="px-8 py-6 text-center">
                          <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-xl font-black ${item.quantity <= item.minStock ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>
                            {item.quantity} <span className="text-xs opacity-70">{item.unit}</span>
                          </div>
                        </td>
                        <td className="px-8 py-6 text-sm text-slate-400 font-medium">
                          {new Date(item.lastUpdated).toLocaleDateString()}
                        </td>
                        <td className="px-8 py-6 text-right">
                           <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                              <button onClick={()=>setEditTarget(item)} className="p-3 bg-white border border-slate-200 rounded-lg shadow-sm hover:text-blue-600"><Edit3 size={16}/></button>
                              <button onClick={()=>setDeleteTarget({id: item.id, name: item.name})} className="p-3 bg-white border border-slate-200 rounded-lg shadow-sm hover:text-red-600"><Trash2 size={16}/></button>
                           </div>
                        </td>
                      </tr>
                    ))}
                 </tbody>
               </table>
            </div>
          )}

          {activeTab === 'history' && (
            <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
               <table className="w-full text-left">
                  <thead className="bg-slate-100 text-[11px] font-black text-slate-500 uppercase border-b">
                    <tr>
                      <th className="px-8 py-5">時間</th>
                      <th className="px-8 py-5">動作</th>
                      <th className="px-8 py-5">品項</th>
                      <th className="px-8 py-5">數量</th>
                      <th className="px-8 py-5">領用單位/人</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {logs.map(log => (
                      <tr key={log.id} className="hover:bg-slate-50">
                        <td className="px-8 py-5 text-sm text-slate-500 font-medium">{new Date(log.timestamp).toLocaleString()}</td>
                        <td className="px-8 py-5">
                          <span className={`inline-flex items-center gap-1 px-3 py-1 rounded-full text-[10px] font-black uppercase ${log.type === 'IN' ? 'bg-emerald-100 text-emerald-600' : 'bg-blue-100 text-blue-600'}`}>
                            {log.type === 'IN' ? <ArrowUpRight size={12}/> : <ArrowDownLeft size={12}/>}
                            {log.type === 'IN' ? '補貨' : '領用'}
                          </span>
                        </td>
                        <td className="px-8 py-5 font-bold text-slate-800">{log.itemName}</td>
                        <td className="px-8 py-5 font-black">{log.type === 'IN' ? '+' : '-'}{log.quantity}</td>
                        <td className="px-8 py-5">
                          <div className="text-sm font-bold text-slate-800">{log.dept}</div>
                          <div className="text-[10px] text-slate-400 font-black">{log.person}</div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
               </table>
            </div>
          )}

          {activeTab === 'dashboard' && (
            <div className="space-y-8">
               <div className="bg-slate-900 rounded-[2.5rem] p-10 text-white relative overflow-hidden">
                  <BrainCircuit className="absolute -right-10 -bottom-10 w-64 h-64 opacity-10" />
                  <div className="relative z-10">
                    <h3 className="text-2xl font-black mb-4 flex items-center gap-3"><BrainCircuit className="text-blue-400"/> AI 庫存智能分析</h3>
                    <div className="bg-slate-800/50 backdrop-blur-sm p-6 rounded-2xl border border-slate-700 leading-relaxed mb-6 min-h-[100px]">
                      {isAiLoading ? "正在分析數據中..." : (aiInsights || "點擊下方按鈕以獲取建議")}
                    </div>
                    <button onClick={fetchAiInsights} disabled={isAiLoading} className="bg-blue-600 hover:bg-blue-500 text-white px-8 py-4 rounded-2xl font-black shadow-xl flex items-center gap-2 transition-all">
                      <RefreshCw className={isAiLoading ? 'animate-spin' : ''} size={20}/> 執行智能診斷
                    </button>
                  </div>
               </div>
            </div>
          )}
        </div>
      </main>

      {/* 新增/編輯 Modal */}
      {(showAddModal || editTarget) && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[500] flex items-center justify-center p-4">
           <form onSubmit={editTarget ? handleEditItem : handleAddItem} className="bg-white rounded-[2.5rem] w-full max-w-2xl overflow-hidden shadow-2xl">
              <div className="p-10">
                <h3 className="text-2xl font-black mb-8">{editTarget ? `編輯項目: ${editTarget.name}` : '新增管理項目'}</h3>
                <div className="grid grid-cols-2 gap-6 mb-8">
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 uppercase">品項名稱</label>
                    <input name="name" required defaultValue={editTarget?.name} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 uppercase">規格 / 尺寸</label>
                    <input name="spec" defaultValue={editTarget?.spec} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 uppercase">類別</label>
                    <select name="category" defaultValue={editTarget?.category || Category.PROTECTION} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold">
                      {Object.values(Category).map(c=><option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 uppercase">類型</label>
                    <select name="itemType" defaultValue={editTarget?.itemType || 'CONSUMABLE'} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold">
                      <option value="CONSUMABLE">消耗品</option>
                      <option value="EQUIPMENT">設備</option>
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 uppercase">單位</label>
                    <input name="unit" required defaultValue={editTarget?.unit || '個'} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" />
                  </div>
                  {!editTarget && (
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-400 uppercase">初始庫存</label>
                      <input name="quantity" type="number" required defaultValue="0" className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" />
                    </div>
                  )}
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 uppercase">安全庫存量 (警示)</label>
                    <input name="minStock" type="number" required defaultValue={editTarget?.minStock || 5} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" />
                  </div>
                </div>
                <div className="flex gap-4">
                   <button type="submit" className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-lg hover:bg-blue-700 transition-all">確認提交</button>
                   <button type="button" onClick={()=>{setShowAddModal(false); setEditTarget(null);}} className="px-10 py-5 bg-slate-100 rounded-2xl font-black text-xl hover:bg-slate-200">取消</button>
                </div>
              </div>
           </form>
        </div>
      )}

      {/* 刪除確認 Modal */}
      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[700] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-10 max-w-md w-full shadow-2xl">
             <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-6"><AlertTriangle size={32}/></div>
             <h3 className="text-2xl font-black text-center mb-2">確定要刪除？</h3>
             <p className="text-slate-500 text-center font-bold mb-8">您即將刪除 <span className="text-black">"{deleteTarget.name}"</span>，此操作無法復原。</p>
             <div className="flex gap-4">
                <button onClick={handleDelete} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black shadow-lg hover:bg-red-700">確認刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="flex-1 py-4 bg-slate-100 rounded-2xl font-black hover:bg-slate-200">取消</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  Settings,
  Cloud,
  ArrowUpRight,
  ArrowDownLeft,
  RefreshCw,
  ClipboardList
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error' | 'local'>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '尚未同步');

  // Modals
  const [showSettings, setShowSettings] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);

  // Form States
  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  // AI
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Print Batch
  const [printBatch, setPrintBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  // Initialization
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) try { setItems(JSON.parse(savedItems)); } catch(e) { console.error(e); }
    if (savedLogs) try { setLogs(JSON.parse(savedLogs)); } catch(e) { console.error(e); }
    setIsLoaded(true);
  }, []);

  // Save to LocalStorage & Sync
  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const syncToCloud = async (currentItems: InventoryItem[], currentLogs: Transaction[]) => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const payload = { items: currentItems, logs: currentLogs, timestamp: Date.now() };
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify(payload), mode: 'no-cors' });
      setSyncStatus('synced');
      const time = new Date().toLocaleString();
      setLastSyncTime(time);
      localStorage.setItem(STORAGE_KEY_LAST_SYNC, time);
    } catch (e) { 
      setSyncStatus('error'); 
    }
  };

  // Handlers
  const handleAddItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: InventoryItem = {
      id: Date.now().toString(),
      name: formData.get('name') as string,
      category: formData.get('category') as any,
      itemType: formData.get('itemType') as any,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    };
    const newItems = [...items, newItem];
    setItems(newItems);
    syncToCloud(newItems, logs);
    setShowAddModal(false);
  };

  const handleEditItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editTarget) return;
    const formData = new FormData(e.currentTarget);
    const updatedItems = items.map(i => i.id === editTarget.id ? {
      ...i,
      name: formData.get('name') as string,
      category: formData.get('category') as any,
      itemType: formData.get('itemType') as any,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      minStock: Number(formData.get('minStock')),
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    } : i);
    setItems(updatedItems);
    syncToCloud(updatedItems, logs);
    setEditTarget(null);
  };

  const handleDelete = () => {
    if (!deleteTarget) return;
    const newItems = items.filter(i => i.id !== deleteTarget.id);
    setItems(newItems);
    syncToCloud(newItems, logs);
    setDeleteTarget(null);
  };

  const addToBasket = () => {
    const target = items.find(i => i.id === selectedItemId);
    if (!target) return;
    const qty = Number(inputQty);
    if (qty <= 0) return;
    if (issuanceMode === 'OUT' && target.quantity < qty) {
      alert('庫存不足以支應該領用數量');
      return;
    }
    setBasket([...basket, { itemId: target.id, name: target.name, quantity: qty, unit: target.unit }]);
    setSelectedItemId('');
    setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const ts = Date.now();
    let nextItems = [...items];
    const nextLogs: Transaction[] = [];

    basket.forEach(b => {
      nextItems = nextItems.map(item => {
        if (item.id === b.itemId) {
          const nQty = issuanceMode === 'OUT' ? item.quantity - b.quantity : item.quantity + b.quantity;
          return { ...item, quantity: nQty, lastUpdated: ts };
        }
        return item;
      });
      nextLogs.push({
        id: `TX-${ts}-${b.itemId}`,
        itemId: b.itemId,
        itemName: b.name,
        type: issuanceMode,
        quantity: b.quantity,
        person: inputPerson || '系統管理員',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: inputReason,
        timestamp: ts
      });
    });

    const combinedLogs = [...nextLogs, ...logs];
    setItems(nextItems);
    setLogs(combinedLogs);
    syncToCloud(nextItems, combinedLogs);

    if (issuanceMode === 'OUT') {
      setPrintBatch({
        id: `SN-${ts.toString().slice(-6)}`,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: ts
      });
      setShowPrintModal(true);
    } else {
      alert('補貨入庫完成');
    }
    setBasket([]); 
    setInputPerson(''); 
    setInputReason('');
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    const msg = await getInventoryInsights(items);
    setAiInsights(msg);
    setIsAiLoading(false);
  };

  const saveGasUrl = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const val = new FormData(e.currentTarget).get('gasUrl') as string;
    setGasUrl(val);
    localStorage.setItem(STORAGE_KEY_GAS_URL, val);
    setShowSettings(false);
    alert('設定已儲存');
  };

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900">
      {/* Sidebar */}
      <aside className="w-72 bg-slate-900 text-white flex flex-col no-print shrink-0">
        <div className="p-8">
          <div className="flex items-center gap-3 mb-10">
            <div className="w-10 h-10 bg-blue-500 rounded-xl flex items-center justify-center shadow-lg shadow-blue-500/30">
              <Package className="text-white" size={24} />
            </div>
            <div>
              <span className="text-xl font-black tracking-tight block">SAFETY PRO</span>
              <span className="text-[10px] text-slate-400 font-bold tracking-widest uppercase">Inventory System</span>
            </div>
          </div>

          <nav className="space-y-2">
            {[
              { id: 'inventory', label: '工安耗材', icon: Package },
              { id: 'medicine', label: '急救藥材', icon: Stethoscope },
              { id: 'issuance', label: '領用/補貨', icon: ShoppingCart },
              { id: 'history', label: '異動日誌', icon: History },
              { id: 'dashboard', label: '統計看板', icon: LayoutDashboard },
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`w-full flex items-center gap-3 px-4 py-3.5 rounded-2xl font-bold transition-all ${
                  activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' : 'text-slate-400 hover:bg-slate-800'
                }`}
              >
                <tab.icon size={20} /> {tab.label}
              </button>
            ))}
          </nav>
        </div>

        <div className="mt-auto p-8 space-y-6">
          <div className="bg-slate-800/40 rounded-2xl p-4 border border-slate-700/50">
            <div className="flex items-center justify-between mb-2">
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-tighter">Cloud Sync</span>
              <div className={`w-2 h-2 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-orange-500'}`} />
            </div>
            <p className="text-[11px] text-slate-400 font-medium">最後同步: {lastSyncTime}</p>
          </div>
