                  <button onClick={()=>window.print()} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-black flex items-center gap-2 hover:bg-blue-700 transition-all shadow-lg shadow-blue-600/20">
                    <Printer size={18}/> 立即列印
