            <div className="flex-1 overflow-y-auto p-12 bg-slate-200/30">
               {/* 實際列印內容區塊 */}
               <div className="bg-white p-12 shadow-2xl mx-auto print-container" id="printable-area" style={{ width: '210mm', minHeight: '297mm', margin: '0 auto' }}>
                  <div className="border-4 border-slate-900 p-8 h-full relative">
                    {/* 水印 */}
                    <div className="absolute inset-0 flex items-center justify-center opacity-[0.03] pointer-events-none rotate-[-45deg]">
                       <span className="text-[120px] font-black italic">SAFETY PRO</span>
                    </div>

                    <header className="flex justify-between items-start border-b-4 border-slate-900 pb-8 mb-8">
                      <div>
                        <h1 className="text-4xl font-black tracking-tighter mb-2">工安耗材領用單</h1>
                        <p className="text-slate-500 font-bold">SAFETY EQUIPMENT ISSUANCE FORM</p>
                      </div>
                      <div className="text-right">
                        <p className="font-black text-xl">單號：{printBatch.id}</p>
                        <p className="text-slate-500 font-bold">日期：{new Date(printBatch.timestamp).toLocaleDateString()}</p>
                      </div>
                    </header>

                    <div className="grid grid-cols-2 gap-8 mb-12">
                      <div className="space-y-1">
                        <span className="text-xs font-black text-slate-400 uppercase">領用部門</span>
                        <p className="text-xl font-black border-b-2 border-slate-100 pb-2">{printBatch.dept}</p>
                      </div>
                      <div className="space-y-1">
                        <span className="text-xs font-black text-slate-400 uppercase">領用人</span>
                        <p className="text-xl font-black border-b-2 border-slate-100 pb-2">{printBatch.person || '未填寫'}</p>
                      </div>
                      <div className="col-span-2 space-y-1">
                        <span className="text-xs font-black text-slate-400 uppercase">用途說明</span>
                        <p className="text-lg font-bold border-b-2 border-slate-100 pb-2">{printBatch.reason || '常規領用'}</p>
                      </div>
                    </div>

                    <table className="w-full mb-12">
                      <thead>
                        <tr className="border-b-2 border-slate-900">
                          <th className="py-4 text-left font-black">品項內容</th>
                          <th className="py-4 text-center font-black">數量</th>
                          <th className="py-4 text-right font-black">備註</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {printBatch.items.map((item, idx) => (
                          <tr key={idx}>
                            <td className="py-5 font-bold text-lg">{item.name}</td>
                            <td className="py-5 text-center font-black text-xl">{item.quantity} {item.unit}</td>
                            <td className="py-5 text-right text-slate-400">---</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>

                    <div className="mt-20 grid grid-cols-3 gap-12">
                      <div className="text-center pt-8 border-t border-slate-300">
                        <p className="text-xs font-black text-slate-400 mb-8 uppercase">領用人簽章</p>
                      </div>
                      <div className="text-center pt-8 border-t border-slate-300">
                        <p className="text-xs font-black text-slate-400 mb-8 uppercase">部門主管簽章</p>
                      </div>
                      <div className="text-center pt-8 border-t border-slate-300">
                        <p className="text-xs font-black text-slate-400 mb-8 uppercase">工安經辦簽章</p>
                      </div>
                    </div>

                    <footer className="absolute bottom-8 left-8 right-8 text-[10px] text-slate-400 font-bold flex justify-between">
                      <span>系統產生時間: {new Date().toLocaleString()}</span>
                      <span>修護處南部分處 - 工安管理組存查</span>
                    </footer>
                  </div>
               </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  Settings,
  Cloud,
  ArrowUpRight,
  ArrowDownLeft,
  RefreshCw,
  ClipboardList,
  /* Fix: Import Save icon which was missing and causing errors on lines 578 and 623 */
  Save
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error' | 'local'>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '尚未同步');

  // Modals
  const [showSettings, setShowSettings] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);

  // Form States
  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  // AI
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Print Batch
  const [printBatch, setPrintBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  // Initialization
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) try { setItems(JSON.parse(savedItems)); } catch(e) { console.error(e); }
    if (savedLogs) try { setLogs(JSON.parse(savedLogs)); } catch(e) { console.error(e); }
    setIsLoaded(true);
  }, []);

  // Save to LocalStorage & Sync
  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const syncToCloud = async (currentItems: InventoryItem[], currentLogs: Transaction[]) => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const payload = { items: currentItems, logs: currentLogs, timestamp: Date.now() };
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify(payload), mode: 'no-cors' });
      setSyncStatus('synced');
      const time = new Date().toLocaleString();
      setLastSyncTime(time);
      localStorage.setItem(STORAGE_KEY_LAST_SYNC, time);
    } catch (e) { 
      setSyncStatus('error'); 
    }
  };

  // Handlers
  const handleAddItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: InventoryItem = {
      id: Date.now().toString(),
      name: formData.get('name') as string,
      category: formData.get('category') as any,
      itemType: formData.get('itemType') as any,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    };
    const newItems = [...items, newItem];
    setItems(newItems);
    syncToCloud(newItems, logs);
    setShowAddModal(false);
  };

  const handleEditItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editTarget) return;
    const formData = new FormData(e.currentTarget);
    const updatedItems = items.map(i => i.id === editTarget.id ? {
      ...i,
      name: formData.get('name') as string,
      category: formData.get('category') as any,
      itemType: formData.get('itemType') as any,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      minStock: Number(formData.get('minStock')),
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    } : i);
    setItems(updatedItems);
    syncToCloud(updatedItems, logs);
    setEditTarget(null);
  };

  const handleDelete = () => {
    if (!deleteTarget) return;
    const newItems = items.filter(i => i.id !== deleteTarget.id);
    setItems(newItems);
    syncToCloud(newItems, logs);
    setDeleteTarget(null);
  };

  const addToBasket = () => {
    const target = items.find(i => i.id === selectedItemId);
    if (!target) return;
    const qty = Number(inputQty);
    if (qty <= 0) return;
    if (issuanceMode === 'OUT' && target.quantity < qty) {
      alert('庫存不足以支應該領用數量');
      return;
    }
    setBasket([...basket, { itemId: target.id, name: target.name, quantity: qty, unit: target.unit }]);
    setSelectedItemId('');
    setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const ts = Date.now();
    let nextItems = [...items];
    const nextLogs: Transaction[] = [];

    basket.forEach(b => {
      nextItems = nextItems.map(item => {
        if (item.id === b.itemId) {
          const nQty = issuanceMode === 'OUT' ? item.quantity - b.quantity : item.quantity + b.quantity;
          return { ...item, quantity: nQty, lastUpdated: ts };
        }
        return item;
      });
      nextLogs.push({
        id: `TX-${ts}-${b.itemId}`,
        itemId: b.itemId,
        itemName: b.name,
        type: issuanceMode,
        quantity: b.quantity,
        person: inputPerson || '系統管理員',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: inputReason,
        timestamp: ts
      });
    });

    const combinedLogs = [...nextLogs, ...logs];
    setItems(nextItems);
    setLogs(combinedLogs);
    syncToCloud(nextItems, combinedLogs);

    if (issuanceMode === 'OUT') {
      setPrintBatch({
        id: `SN-${ts.toString().slice(-6)}`,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: ts
      });
      setShowPrintModal(true);
    } else {
      alert('補貨入庫完成');
    }
    setBasket([]); 
    setInputPerson(''); 
    setInputReason('');
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    const msg = await getInventoryInsights(items);
    setAiInsights(msg);
    setIsAiLoading(false);
  };

  const saveGasUrl = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const val = new FormData(e.currentTarget).get('gasUrl') as string;
    setGasUrl(val);
    localStorage.setItem(STORAGE_KEY_GAS_URL, val);
    setShowSettings(false);
    alert('設定已儲存');
  };

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900">
      {/* Sidebar */}
      <aside className="w-72 bg-slate-900 text-white flex flex-col no-print shrink-0">
        <div className="p-8">
          <div className="flex items-center gap-3 mb-10">
            <div className="w-10 h-10 bg-blue-500 rounded-xl flex items-center justify-center shadow-lg shadow-blue-500/30">
              <Package className="text-white" size={24} />
            </div>
            <div>
              <span className="text-xl font-black tracking-tight block">SAFETY PRO</span>
              <span className="text-[10px] text-slate-400 font-bold tracking-widest uppercase">Inventory System</span>
            </div>
          </div>

          <nav className="space-y-2">
            {[
              { id: 'inventory', label: '工安耗材', icon: Package },
              { id: 'medicine', label: '急救藥材', icon: Stethoscope },
              { id: 'issuance', label: '領用/補貨', icon: ShoppingCart },
              { id: 'history', label: '異動日誌', icon: History },
              { id: 'dashboard', label: '統計看板', icon: LayoutDashboard },
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`w-full flex items-center gap-3 px-4 py-3.5 rounded-2xl font-bold transition-all ${
                  activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' : 'text-slate-400 hover:bg-slate-800'
                }`}
              >
                <tab.icon size={20} /> {tab.label}
              </button>
            ))}
          </nav>
        </div>

        <div className="mt-auto p-8 space-y-6">
          <div className="bg-slate-800/40 rounded-2xl p-4 border border-slate-700/50">
            <div className="flex items-center justify-between mb-2">
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-tighter">Cloud Sync</span>
              <div className={`w-2 h-2 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-orange-500'}`} />
            </div>
            <p className="text-[11px] text-slate-400 font-medium">最後同步: {lastSyncTime}</p>
          </div>
          <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-2 text-slate-400 hover:text-white transition-colors text-sm font-bold">
            <Settings size={16} /> 系統設定與同步
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-10 overflow-y-auto no-print">
        <div className="max-w-6xl mx-auto">
          <header className="flex justify-between items-end mb-12">
            <div>
              <div className="flex items-center gap-2 text-blue-600 font-black text-xs uppercase tracking-widest mb-2">
                <div className="h-1 w-8 bg-blue-600 rounded-full"></div>
                Management System
              </div>
              <h2 className="text-4xl font-black text-slate-900">
                {activeTab === 'inventory' ? '工安耗材管理' : 
                 activeTab === 'medicine' ? '急救藥材管理' : 
                 activeTab === 'issuance' ? '領用補貨作業' : 
                 activeTab === 'history' ? '歷史異動日誌' : '庫存數據分析'}
              </h2>
            </div>
            {(activeTab === 'inventory' || activeTab === 'medicine') && (
              <button onClick={() => setShowAddModal(true)} className="bg-slate-900 hover:bg-black text-white px-8 py-4 rounded-2xl font-black flex items-center gap-2 shadow-xl transition-all hover:-translate-y-1">
                <Plus size={20} /> 新增項目
              </button>
            )}
          </header>

          {activeTab === 'issuance' && (
            <div className="grid grid-cols-1 lg:grid-cols-5 gap-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <div className="lg:col-span-2 space-y-6">
                <div className="bg-white p-8 rounded-[2rem] shadow-xl shadow-slate-200/50 border border-slate-100">
                  <div className="flex bg-slate-100 p-1.5 rounded-2xl mb-8">
                    <button onClick={()=>setIssuanceMode('OUT')} className={`flex-1 py-3.5 rounded-xl font-black transition-all ${issuanceMode==='OUT' ? 'bg-white shadow-md text-blue-600' : 'text-slate-500'}`}>領用出庫</button>
                    <button onClick={()=>setIssuanceMode('IN')} className={`flex-1 py-3.5 rounded-xl font-black transition-all ${issuanceMode==='IN' ? 'bg-white shadow-md text-emerald-600' : 'text-slate-500'}`}>補貨入庫</button>
                  </div>
                  <div className="space-y-5">
                    <div>
                      <label className="block text-[11px] font-black text-slate-400 uppercase mb-2 ml-1">選擇品項</label>
                      <select className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold text-slate-700" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                        <option value="">請點擊選擇庫存品...</option>
                        {items.map(i => <option key={i.id} value={i.id}>{i.name} (剩餘 {i.quantity} {i.unit})</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-[11px] font-black text-slate-400 uppercase mb-2 ml-1">輸入數量</label>
                      <input type="number" className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold text-xl" value={inputQty} onChange={e=>setInputQty(e.target.value)} />
                    </div>
                    <button onClick={addToBasket} disabled={!selectedItemId} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black hover:bg-black disabled:opacity-30 mt-4 transition-all flex items-center justify-center gap-2">
                      <Plus size={18}/> 加入待處理
                    </button>
                  </div>
                </div>
              </div>

              <div className="lg:col-span-3 bg-white p-8 rounded-[2rem] shadow-xl shadow-slate-200/50 border border-slate-100 flex flex-col">
                <div className="flex justify-between items-center mb-6">
                   <h3 className="text-xl font-black flex items-center gap-2"><ClipboardList className="text-blue-500"/> 待處理清單 ({basket.length})</h3>
                   {basket.length > 0 && <button onClick={()=>setBasket([])} className="text-xs font-bold text-red-500 hover:underline">清空全部</button>}
                </div>

                <div className="flex-1 bg-slate-50 rounded-2xl p-4 mb-6 overflow-y-auto space-y-3 min-h-[350px] border-2 border-dashed border-slate-200 custom-scrollbar">
                  {basket.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center text-slate-400 space-y-4">
                      <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center">
                        <ShoppingCart size={32} className="opacity-20" />
                      </div>
                      <p className="font-bold">清單目前是空的，請先從左側選擇品項</p>
                    </div>
                  ) : (
                    basket.map((b, idx) => (
                      <div key={idx} className="flex justify-between items-center p-5 bg-white rounded-2xl shadow-sm border border-slate-100 group animate-in fade-in zoom-in-95 duration-200">
                        <div>
                          <p className="font-black text-slate-800 text-lg">{b.name}</p>
                          <p className="text-[10px] text-slate-400 font-black uppercase tracking-wider">REF: {b.itemId.slice(-6)}</p>
                        </div>
                        <div className="flex items-center gap-6">
                          <span className="font-black text-blue-600 text-xl">{b.quantity} <span className="text-xs text-slate-400">{b.unit}</span></span>
                          <button onClick={()=>setBasket(prev=>prev.filter((_,i)=>i!==idx))} className="w-10 h-10 flex items-center justify-center rounded-full text-slate-300 hover:text-red-500 hover:bg-red-50 transition-all"><X size={20}/></button>
                        </div>
                      </div>
                    ))
                  )}
                </div>

                {issuanceMode === 'OUT' && (
                  <div className="grid grid-cols-2 gap-4 mb-6">
                    <div className="space-y-2">
                      <label className="text-[11px] font-black text-slate-400 uppercase ml-1">領用部門</label>
                      <select className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>
                        {DEPARTMENTS.map(d=><option key={d}>{d}</option>)}
                      </select>
                    </div>
                    <div className="space-y-2">
                      <label className="text-[11px] font-black text-slate-400 uppercase ml-1">領用人姓名</label>
                      <input className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" placeholder="請輸入姓名" value={inputPerson} onChange={e=>setInputPerson(e.target.value)} />
                    </div>
                  </div>
                )}

                <div className="space-y-2 mb-8">
                  <label className="text-[11px] font-black text-slate-400 uppercase ml-1">用途或備註</label>
                  <input className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" placeholder="例如：南一隊年度巡檢消耗" value={inputReason} onChange={e=>setInputReason(e.target.value)} />
                </div>

                <button onClick={processIssuance} disabled={basket.length===0} className={`w-full py-6 rounded-2xl font-black text-2xl text-white shadow-2xl transition-all hover:-translate-y-1 active:scale-95 ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700 shadow-blue-600/30':'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-600/30'}`}>
                  {issuanceMode==='OUT' ? '確認領用並列印單據' : '確認入庫'}
                </button>
              </div>
            </div>
          )}

          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <>
              <div className="grid grid-cols-4 gap-6 mb-8">
                <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
                  <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">項目總數</p>
                  <p className="text-4xl font-black">{items.filter(i => activeTab==='medicine' ? i.itemGroup==='MEDICINE' : i.itemGroup==='INVENTORY').length}</p>
                </div>
                <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
                  <p className="text-red-400 text-[10px] font-black uppercase tracking-widest mb-1">庫存預警</p>
                  <p className="text-4xl font-black text-red-500">
