import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  Settings,
  Cloud,
  ArrowUpRight,
  ArrowDownLeft,
  RefreshCw,
  ClipboardList,
  Save,
  Calendar,
  Layers
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error' | 'local'>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '尚未同步');

  // Modals
  const [showSettings, setShowSettings] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);

  // Form States
  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  // AI
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Print Batch
  const [printBatch, setPrintBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  // Initial Load
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) try { setItems(JSON.parse(savedItems)); } catch(e) { console.error(e); }
    if (savedLogs) try { setLogs(JSON.parse(savedLogs)); } catch(e) { console.error(e); }
    setIsLoaded(true);
  }, []);

  // Persistent Storage
  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const syncToCloud = async (currentItems: InventoryItem[], currentLogs: Transaction[]) => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const payload = { items: currentItems, logs: currentLogs, timestamp: Date.now() };
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify(payload), mode: 'no-cors' });
      setSyncStatus('synced');
      const time = new Date().toLocaleString();
      setLastSyncTime(time);
      localStorage.setItem(STORAGE_KEY_LAST_SYNC, time);
    } catch (e) { setSyncStatus('error'); }
  };

  // Stats Calculation
  const stats = useMemo(() => {
    const now = new Date();
    const currentGroupItems = items.filter(i => 
      activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY'
    );

    const lowStock = currentGroupItems.filter(i => i.quantity <= i.minStock).length;
    const expiringSoon = currentGroupItems.filter(i => {
      if (!i.expiryDate) return false;
      const exp = new Date(i.expiryDate);
      const diffDays = (exp.getTime() - now.getTime()) / (1000 * 3600 * 24);
      return diffDays > 0 && diffDays <= 30;
    }).length;

    const monthlyOut = logs.filter(l => {
      const logDate = new Date(l.timestamp);
      return l.type === 'OUT' && 
             logDate.getMonth() === now.getMonth() && 
             logDate.getFullYear() === now.getFullYear();
    }).reduce((acc, curr) => acc + curr.quantity, 0);

    return { total: currentGroupItems.length, lowStock, expiringSoon, monthlyOut };
  }, [items, logs, activeTab]);

  // CRUD
  const handleAddItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: InventoryItem = {
      id: Date.now().toString(),
      name: formData.get('name') as string,
      category: formData.get('category') as Category,
      itemType: formData.get('itemType') as ItemType,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    };
    const nextItems = [...items, newItem];
    setItems(nextItems);
    syncToCloud(nextItems, logs);
    setShowAddModal(false);
  };

  const handleEditItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editTarget) return;
    const formData = new FormData(e.currentTarget);
    const updatedItems = items.map(i => i.id === editTarget.id ? {
      ...i,
      name: formData.get('name') as string,
      category: formData.get('category') as Category,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      minStock: Number(formData.get('minStock')),
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    } : i);
    setItems(updatedItems);
    syncToCloud(updatedItems, logs);
    setEditTarget(null);
  };

  const handleDelete = () => {
    if (!deleteTarget) return;
    const nextItems = items.filter(i => i.id !== deleteTarget.id);
    setItems(nextItems);
    syncToCloud(nextItems, logs);
    setDeleteTarget(null);
  };

  const addToBasket = () => {
    const target = items.find(i => i.id === selectedItemId);
    if (!target) return;
    const qty = Number(inputQty);
    if (qty <= 0) return;
    if (issuanceMode === 'OUT' && target.quantity < qty) {
      alert('庫存不足'); return;
    }
    setBasket([...basket, { itemId: target.id, name: target.name, quantity: qty, unit: target.unit }]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const ts = Date.now();
    let nextItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(b => {
      nextItems = nextItems.map(item => {
        if (item.id === b.itemId) {
          const nQty = issuanceMode === 'OUT' ? item.quantity - b.quantity : item.quantity + b.quantity;
          return { ...item, quantity: nQty, lastUpdated: ts };
        }
        return item;
      });
      newLogs.push({
        id: `TX-${ts}-${b.itemId}`,
        itemId: b.itemId,
        itemName: b.name,
        type: issuanceMode,
        quantity: b.quantity,
        person: inputPerson || '系統管理員',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: inputReason,
        timestamp: ts
      });
    });

    const combinedLogs = [...newLogs, ...logs];
    setItems(nextItems);
    setLogs(combinedLogs);
    syncToCloud(nextItems, combinedLogs);

    if (issuanceMode === 'OUT') {
      setPrintBatch({
        id: `SN-${ts.toString().slice(-6)}`,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: ts
      });
      setShowPrintModal(true);
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    const msg = await getInventoryInsights(items);
    setAiInsights(msg);
    setIsAiLoading(false);
  };

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900">
      {/* Sidebar */}
      <aside className="w-72 bg-slate-900 text-white flex flex-col no-print shrink-0">
        <div className="p-8">
          <div className="flex items-center gap-3 mb-10">
            <div className="w-10 h-10 bg-blue-500 rounded-xl flex items-center justify-center shadow-lg shadow-blue-500/30">
              <Package className="text-white" size={24} />
            </div>
            <div>
              <span className="text-xl font-black tracking-tight block">SAFETY PRO</span>
              <span className="text-[10px] text-slate-400 font-bold tracking-widest uppercase">Inventory System</span>
            </div>
          </div>

          <nav className="space-y-2">
            {[
              { id: 'inventory', label: '工安耗材', icon: Package },
              { id: 'medicine', label: '急救藥材', icon: Stethoscope },
              { id: 'issuance', label: '領用/補貨', icon: ShoppingCart },
              { id: 'history', label: '異動日誌', icon: History },
              { id: 'dashboard', label: '統計看板', icon: LayoutDashboard },
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`w-full flex items-center gap-3 px-4 py-3.5 rounded-2xl font-bold transition-all ${
                  activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' : 'text-slate-400 hover:bg-slate-800'
                }`}
              >
                <tab.icon size={20} /> {tab.label}
              </button>
            ))}
          </nav>
        </div>

        <div className="mt-auto p-8 space-y-6">
          <div className="bg-slate-800/40 rounded-2xl p-4 border border-slate-700/50">
            <div className="flex items-center justify-between mb-2">
              <span className="text-[10px] font-black text-slate-500 uppercase">Cloud Sync</span>
              <div className={`w-2 h-2 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-orange-500'}`} />
            </div>
            <p className="text-[11px] text-slate-400 font-medium tracking-tight">最後同步: {lastSyncTime}</p>
          </div>
          <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-2 text-slate-400 hover:text-white transition-colors text-sm font-bold">
            <Settings size={16} /> 系統設定
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-10 overflow-y-auto no-print">
        <div className="max-w-6xl mx-auto">
          <header className="flex justify-between items-end mb-10">
            <div>
              <div className="flex items-center gap-2 text-blue-600 font-black text-xs uppercase tracking-widest mb-2">
                <div className="h-1 w-8 bg-blue-600 rounded-full"></div>
                V35 Production Ultimate
              </div>
              <h2 className="text-4xl font-black text-slate-900 uppercase">
                {activeTab === 'inventory' ? '工安耗材資料庫' : 
                 activeTab === 'medicine' ? '急救藥材資料庫' : 
                 activeTab === 'issuance' ? '庫存異動作業' : 
                 activeTab === 'history' ? '歷史異動日誌' : '管理統計看板'}
              </h2>
            </div>
            {(activeTab === 'inventory' || activeTab === 'medicine') && (
              <button onClick={() => setShowAddModal(true)} className="bg-slate-900 hover:bg-black text-white px-8 py-4 rounded-2xl font-black flex items-center gap-2 shadow-xl transition-all hover:-translate-y-1">
                <Plus size={20} /> 新增管理品項
              </button>
            )}
          </header>

          {/* Stats Cards */}
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <div className="grid grid-cols-4 gap-6 mb-10">
              <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
                <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">總項目數</p>
                <p className="text-4xl font-black">{stats.total}</p>
              </div>
              <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
                <p className="text-red-400 text-[10px] font-black uppercase tracking-widest mb-1">庫存水位預警</p>
                <p className="text-4xl font-black text-red-500">{stats.lowStock}</p>
              </div>
              <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
                <p className="text-orange-400 text-[10px] font-black uppercase tracking-widest mb-1">即將到期 (30天內)</p>
                <p className="text-4xl font-black text-orange-500">{stats.expiringSoon}</p>
              </div>
              <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
                <p className="text-blue-400 text-[10px] font-black uppercase tracking-widest mb-1">本月消耗總計</p>
                <p className="text-4xl font-black text-blue-600">{stats.monthlyOut}</p>
              </div>
            </div>
          )}

          {/* Table Area */}
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <div className="bg-white rounded-[2rem] shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden">
               <div className="p-8 bg-slate-50/50 border-b flex items-center justify-between">
                  <div className="relative w-96">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18}/>
                    <input className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-slate-200 font-bold shadow-inner" placeholder="搜尋名稱、規格或分類..." value={searchTerm} onChange={e=>setSearchTerm(e.target.value)} />
                  </div>
               </div>
               <div className="overflow-x-auto">
                 <table className="w-full border-collapse">
                   <thead>
                      <tr className="bg-slate-100/50 text-left border-b border-slate-200">
                        <th className="px-8 py-5 text-[11px] font-black text-slate-500 uppercase tracking-tighter">品項資訊</th>
                        <th className="px-8 py-5 text-[11px] font-black text-slate-500 uppercase tracking-tighter">規格 / 單位</th>
                        <th className="px-8 py-5 text-[11px] font-black text-slate-500 uppercase tracking-tighter text-center">當前庫存</th>
                        <th className="px-8 py-5 text-[11px] font-black text-slate-500 uppercase tracking-tighter">有效日期</th>
                        <th className="px-8 py-5 text-[11px] font-black text-slate-500 uppercase tracking-tighter text-right">動作</th>
                      </tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100">
                      {items.filter(i => (activeTab==='medicine' ? i.itemGroup==='MEDICINE' : i.itemGroup==='INVENTORY') && i.name.includes(searchTerm)).map(item => {
                        const isExpired = item.expiryDate && new Date(item.expiryDate) < new Date();
                        return (
                          <tr key={item.id} className="hover:bg-blue-50/30 transition-colors group">
                            <td className="px-8 py-6">
                              <div className="font-black text-slate-800 text-lg">{item.name}</div>
                              <div className="flex gap-2 mt-1">
                                <span className="px-2 py-0.5 bg-slate-100 text-[10px] font-black text-slate-500 rounded uppercase">{item.category}</span>
                                <span className="px-2 py-0.5 bg-blue-50 text-[10px] font-black text-blue-500 rounded uppercase">{item.itemType === 'EQUIPMENT' ? '設備' : '消耗品'}</span>
                              </div>
                            </td>
                            <td className="px-8 py-6">
                              <div className="font-bold text-slate-500">{item.spec || '-'}</div>
                              <div className="text-[10px] text-slate-400 font-black">單位: {item.unit}</div>
                            </td>
                            <td className="px-8 py-6 text-center">
                              <div className={`inline-flex items-center gap-2 px-5 py-2.5 rounded-2xl font-black ${item.quantity <= item.minStock ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>
                                {item.quantity}
                                {item.quantity <= item.minStock && <AlertTriangle size={14} className="ml-1 animate-pulse"/>}
                              </div>
                            </td>
                            <td className="px-8 py-6">
                              <div className={`text-sm font-bold ${isExpired ? 'text-red-500' : 'text-slate-500'}`}>
                                {item.expiryDate || '永久'}
                              </div>
                              {item.purchaseDate && <div className="text-[10px] text-slate-400 font-bold">購入: {item.purchaseDate}</div>}
                            </td>
                            <td className="px-8 py-6 text-right">
                               <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                  <button onClick={()=>setEditTarget(item)} className="w-10 h-10 flex items-center justify-center bg-white border border-slate-200 rounded-xl shadow-sm hover:text-blue-600 hover:border-blue-200"><Edit3 size={18}/></button>
                                  <button onClick={()=>setDeleteTarget({id: item.id, name: item.name})} className="w-10 h-10 flex items-center justify-center bg-white border border-slate-200 rounded-xl shadow-sm hover:text-red-600 hover:border-red-200"><Trash2 size={18}/></button>
                               </div>
                            </td>
                          </tr>
                        );
                      })}
                   </tbody>
                 </table>
               </div>
            </div>
          )}

          {/* Issuance Tab */}
          {activeTab === 'issuance' && (
            <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
              <div className="lg:col-span-2 space-y-6">
                <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-slate-100">
                  <div className="flex bg-slate-100 p-1.5 rounded-2xl mb-8">
                    <button onClick={()=>setIssuanceMode('OUT')} className={`flex-1 py-3.5 rounded-xl font-black transition-all ${issuanceMode==='OUT' ? 'bg-white shadow-md text-blue-600' : 'text-slate-500'}`}>領用出庫</button>
                    <button onClick={()=>setIssuanceMode('IN')} className={`flex-1 py-3.5 rounded-xl font-black transition-all ${issuanceMode==='IN' ? 'bg-white shadow-md text-emerald-600' : 'text-slate-500'}`}>補貨入庫</button>
                  </div>
                  <div className="space-y-5">
                    <div>
                      <label className="block text-[11px] font-black text-slate-400 uppercase mb-2 ml-1">選擇品項</label>
                      <select className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                        <option value="">請選擇品項...</option>
                        {items.map(i => <option key={i.id} value={i.id}>{i.name} ({i.quantity} {i.unit})</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-[11px] font-black text-slate-400 uppercase mb-2 ml-1">數量</label>
                      <input type="number" className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold text-xl" value={inputQty} onChange={e=>setInputQty(e.target.value)} />
                    </div>
                    <button onClick={addToBasket} disabled={!selectedItemId} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black hover:bg-black disabled:opacity-30 mt-4 transition-all">加入待處理清單</button>
                  </div>
                </div>
              </div>

              <div className="lg:col-span-3 bg-white p-8 rounded-[2.5rem] shadow-xl border border-slate-100 flex flex-col">
                <h3 className="text-xl font-black mb-6 flex items-center gap-2"><ClipboardList className="text-blue-500"/> 待處理清單 ({basket.length})</h3>
                <div className="flex-1 bg-slate-50 rounded-2xl p-4 mb-6 overflow-y-auto space-y-3 min-h-[300px] border-2 border-dashed border-slate-200">
                  {basket.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center text-slate-400 italic">
                      <ShoppingCart size={48} className="mb-4 opacity-10" />
                      <p>尚未加入任何品項</p>
                    </div>
                  ) : (
                    basket.map((b, idx) => (
                      <div key={idx} className="flex justify-between items-center p-5 bg-white rounded-2xl shadow-sm border border-slate-100 animate-in zoom-in-95 duration-200">
                        <div>
                          <p className="font-black text-slate-800 text-lg">{b.name}</p>
                          <p className="text-[10px] text-slate-400 font-black">ID: {b.itemId}</p>
                        </div>
                        <div className="flex items-center gap-6">
                          <span className="font-black text-blue-600 text-xl">{b.quantity} <span className="text-xs text-slate-400">{b.unit}</span></span>
                          <button onClick={()=>setBasket(prev=>prev.filter((_,i)=>i!==idx))} className="text-slate-300 hover:text-red-500"><X/></button>
                        </div>
                      </div>
                    ))
                  )}
                </div>

                {issuanceMode === 'OUT' && (
                  <div className="grid grid-cols-2 gap-4 mb-6">
                    <div className="space-y-2">
                      <label className="text-[11px] font-black text-slate-400 uppercase ml-1">領用部門</label>
                      <select className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>
                        {DEPARTMENTS.map(d=><option key={d}>{d}</option>)}
                      </select>
                    </div>
                    <div className="space-y-2">
                      <label className="text-[11px] font-black text-slate-400 uppercase ml-1">領用人</label>
                      <input className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" placeholder="姓名" value={inputPerson} onChange={e=>setInputPerson(e.target.value)} />
                    </div>
                  </div>
                )}
                <div className="space-y-2 mb-8">
                  <label className="text-[11px] font-black text-slate-400 uppercase ml-1">用途備註</label>
                  <input className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" placeholder="備註內容..." value={inputReason} onChange={e=>setInputReason(e.target.value)} />
                </div>
                <button onClick={processIssuance} disabled={basket.length===0} className={`w-full py-6 rounded-2xl font-black text-2xl text-white shadow-2xl transition-all ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>
                  {issuanceMode==='OUT' ? '確認領用並列印' : '確認入庫'}
                </button>
              </div>
            </div>
          )}

          {/* Other tabs follow the same "Ultimate" pattern */}
          {activeTab === 'history' && (
            <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden">
               <table className="w-full text-left">
                  <thead className="bg-slate-900 text-[11px] font-black text-slate-400 uppercase tracking-widest">
                    <tr>
                      <th className="px-8 py-6">時間</th>
                      <th className="px-8 py-6">動作</th>
                      <th className="px-8 py-6">品項</th>
                      <th className="px-8 py-6">數量</th>
                      <th className="px-8 py-6">對象/單位</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {logs.map(log => (
                      <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-8 py-5 text-sm text-slate-500 font-bold">{new Date(log.timestamp).toLocaleString()}</td>
                        <td className="px-8 py-5">
                          <span className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[10px] font-black uppercase ${log.type === 'IN' ? 'bg-emerald-100 text-emerald-600' : 'bg-blue-100 text-blue-600'}`}>
                            {log.type === 'IN' ? '補貨入庫' : '領用出庫'}
                          </span>
                        </td>
                        <td className="px-8 py-5 font-black text-slate-800">{log.itemName}</td>
                        <td className={`px-8 py-5 font-black text-lg ${log.type === 'IN' ? 'text-emerald-600' : 'text-slate-900'}`}>{log.type === 'IN' ? '+' : '-'}{log.quantity}</td>
                        <td className="px-8 py-5">
                          <div className="text-sm font-black text-slate-800">{log.dept}</div>
                          <div className="text-[10px] text-slate-400 font-bold uppercase">{log.person}</div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
               </table>
            </div>
          )}

          {activeTab === 'dashboard' && (
            <div className="space-y-8">
               <div className="bg-slate-900 rounded-[3rem] p-12 text-white relative overflow-hidden shadow-2xl">
                  <BrainCircuit className="absolute -right-16 -bottom-16 w-80 h-80 opacity-10 rotate-12" />
                  <div className="relative z-10 max-w-3xl">
                    <h3 className="text-3xl font-black mb-6 flex items-center gap-4"><BrainCircuit className="text-blue-400" size={36}/> AI 智能庫存建議</h3>
                    <div className="bg-slate-800/60 backdrop-blur-xl p-8 rounded-3xl border border-slate-700/50 leading-relaxed mb-8 min-h-[160px] text-lg font-medium text-slate-200">
                      {isAiLoading ? "正在深度分析數據庫..." : (aiInsights || "請執行智能診斷以獲得採購建議。")}
                    </div>
                    <button onClick={fetchAiInsights} disabled={isAiLoading} className="bg-blue-600 hover:bg-blue-500 text-white px-10 py-5 rounded-2xl font-black shadow-xl flex items-center gap-3 transition-all hover:-translate-y-1">
                      <RefreshCw className={isAiLoading ? 'animate-spin' : ''} size={24}/> 執行智能診斷
                    </button>
                  </div>
               </div>
            </div>
          )}
        </div>
      </main>

      {/* 新增/編輯彈窗 - 包含所有欄位 */}
      {(showAddModal || editTarget) && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[500] flex items-center justify-center p-4">
           <form onSubmit={editTarget ? handleEditItem : handleAddItem} className="bg-white rounded-[2.5rem] w-full max-w-2xl overflow-hidden shadow-2xl">
              <div className="p-10">
                <h3 className="text-3xl font-black mb-8">{editTarget ? `編輯: ${editTarget.name}` : '新增品項'}</h3>
                <div className="grid grid-cols-2 gap-6 mb-10">
                  <div className="col-span-2 space-y-2">
                    <label className="text-[11px] font-black text-slate-400 uppercase ml-1">品項名稱</label>
                    <input name="name" required defaultValue={editTarget?.name} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold text-lg" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[11px] font-black text-slate-400 uppercase ml-1">規格/尺寸</label>
                    <input name="spec" defaultValue={editTarget?.spec} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[11px] font-black text-slate-400 uppercase ml-1">類別</label>
                    <select name="category" defaultValue={editTarget?.category} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold">
                      {Object.values(Category).map(c=><option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[11px] font-black text-slate-400 uppercase ml-1">類型</label>
                    <select name="itemType" defaultValue={editTarget?.itemType} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold">
                      <option value="CONSUMABLE">消耗品</option>
                      <option value="EQUIPMENT">設備</option>
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[11px] font-black text-slate-400 uppercase ml-1">單位</label>
                    <input name="unit" required defaultValue={editTarget?.unit} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[11px] font-black text-slate-400 uppercase ml-1">購入日期</label>
                    <input name="purchaseDate" type="date" defaultValue={editTarget?.purchaseDate} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[11px] font-black text-slate-400 uppercase ml-1">有效日期 (到期日)</label>
                    <input name="expiryDate" type="date" defaultValue={editTarget?.expiryDate} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" />
                  </div>
                  {!editTarget && (
                    <div className="space-y-2">
                      <label className="text-[11px] font-black text-slate-400 uppercase ml-1">初始庫存量</label>
                      <input name="quantity" type="number" required defaultValue="0" className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" />
                    </div>
                  )}
                  <div className="space-y-2">
                    <label className="text-[11px] font-black text-slate-400 uppercase ml-1">安全庫存警示值</label>
                    <input name="minStock" type="number" required defaultValue={editTarget?.minStock || 5} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold text-red-600" />
                  </div>
                </div>
                <div className="flex gap-4">
                   <button type="submit" className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl hover:bg-blue-700 transition-all flex items-center justify-center gap-2">
                     <Save size={24}/> 確認提交
                   </button>
                   <button type="button" onClick={()=>{setShowAddModal(false); setEditTarget(null);}} className="px-10 py-5 bg-slate-100 rounded-2xl font-black text-xl hover:bg-slate-200 text-slate-500">取消</button>
                </div>
              </div>
           </form>
        </div>
      )}

      {/* 刪除彈窗 */}
      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[700] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-10 max-w-md w-full shadow-2xl">
             <div className="w-20 h-20 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-6"><AlertTriangle size={40}/></div>
             <h3 className="text-2xl font-black text-center mb-2 text-slate-900">確定要刪除？</h3>
             <p className="text-slate-500 text-center font-bold mb-10 leading-relaxed">您即將刪除 <span className="text-slate-900">"{deleteTarget.name}"</span>。<br/>此操作無法復原。</p>
             <div className="flex gap-4">
                <button onClick={handleDelete} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black shadow-lg hover:bg-red-700 transition-all">確認刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="flex-1 py-4 bg-slate-100 rounded-2xl font-black hover:bg-slate-200 text-slate-500">取消</button>
             </div>
          </div>
        </div>
      )}

      {/* 設定彈窗 */}
      {showSettings && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[600] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2rem] w-full max-w-xl overflow-hidden shadow-2xl">
             <div className="p-10">
                <div className="flex justify-between items-center mb-8">
                  <h3 className="text-2xl font-black">系統設定</h3>
                  <button onClick={()=>setShowSettings(false)}><X/></button>
                </div>
                <div className="space-y-6 mb-10">
                  <div className="p-4 bg-blue-50 rounded-2xl border border-blue-100 text-sm text-blue-700 font-bold">
                    輸入 GAS Web App URL 以啟動雲端自動同步備份。
                  </div>
                  <div className="space-y-2">
                    <label className="text-[11px] font-black text-slate-400 uppercase">GAS 部署網址</label>
                    <input value={gasUrl} onChange={e=>{setGasUrl(e.target.value); localStorage.setItem(STORAGE_KEY_GAS_URL, e.target.value);}} placeholder="https://..." className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-mono text-sm" />
                  </div>
                </div>
                <button onClick={()=>setShowSettings(false)} className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black text-xl hover:bg-black transition-all flex items-center justify-center gap-2 shadow-xl">
                  儲存並關閉
                </button>
             </div>
          </div>
        </div>
      )}

      {/* 列印彈窗 */}
      {showPrintModal && printBatch && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm z-[800] flex items-center justify-center p-4 no-print">
          <div className="bg-white rounded-3xl w-full max-w-3xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50">
               <h3 className="font-black text-lg">領用單據預覽</h3>
               <div className="flex gap-2">
                  <button onClick={()=>window.print()} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-black flex items-center gap-2 hover:bg-blue-700 transition-all shadow-lg shadow-blue-600/20">
                    <Printer size={18}/> 立即列印
                  </button>
                  <button onClick={()=>setShowPrintModal(false)} className="p-2 hover:bg-slate-200 rounded-lg"><X/></button>
               </div>
            </div>
            <div className="flex-1 overflow-y-auto p-12 bg-slate-200/30">
               <div className="bg-white p-12 shadow-2xl mx-auto print-container" style={{ width: '210mm', minHeight: '297mm' }}>
                  <div className="border-4 border-slate-900 p-8 h-full relative">
                    <header className="flex justify-between items-start border-b-4 border-slate-900 pb-8 mb-8">
                      <div>
                        <h1 className="text-4xl font-black tracking-tighter mb-2">工安耗材領用單</h1>
                        <p className="text-slate-500 font-bold">SAFETY EQUIPMENT ISSUANCE FORM</p>
                      </div>
                      <div className="text-right">
                        <p className="font-black text-xl">單號：{printBatch.id}</p>
                        <p className="text-slate-500 font-bold">日期：{new Date(printBatch.timestamp).toLocaleDateString()}</p>
                      </div>
                    </header>
                    <div className="grid grid-cols-2 gap-8 mb-12">
                      <div><span className="text-xs font-black text-slate-400 uppercase">領用部門</span><p className="text-xl font-black border-b-2 border-slate-100 pb-2">{printBatch.dept}</p></div>
                      <div><span className="text-xs font-black text-slate-400 uppercase">領用人</span><p className="text-xl font-black border-b-2 border-slate-100 pb-2">{printBatch.person || '未填寫'}</p></div>
                      <div className="col-span-2"><span className="text-xs font-black text-slate-400 uppercase">用途說明</span><p className="text-lg font-bold border-b-2 border-slate-100 pb-2">{printBatch.reason || '常規領用'}</p></div>
                    </div>
                    <table className="w-full mb-20">
                      <thead><tr className="border-b-2 border-slate-900"><th className="py-4 text-left font-black">品項內容</th><th className="py-4 text-center font-black">數量</th><th className="py-4 text-right font-black">單位</th></tr></thead>
                      <tbody className="divide-y divide-slate-100">
                        {printBatch.items.map((item, idx) => (
                          <tr key={idx}><td className="py-5 font-bold text-lg">{item.name}</td><td className="py-5 text-center font-black text-xl">{item.quantity}</td><td className="py-5 text-right font-bold">{item.unit}</td></tr>
                        ))}
                      </tbody>
                    </table>
                    <div className="grid grid-cols-3 gap-12 mt-auto">
                      <div className="text-center pt-8 border-t border-slate-300"><p className="text-xs font-black text-slate-400 mb-8 uppercase">領用人簽章</p></div>
                      <div className="text-center pt-8 border-t border-slate-300"><p className="text-xs font-black text-slate-400 mb-8 uppercase">部門主管簽章</p></div>
                      <div className="text-center pt-8 border-t border-slate-300"><p className="text-xs font-black text-slate-400 mb-8 uppercase">工安經辦簽章</p></div>
                    </div>
                  </div>
               </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  Settings,
  ArrowUpRight,
  ArrowDownLeft,
  RefreshCw,
  ClipboardList,
  Save,
  Calendar,
  Layers,
  CheckCircle2,
  Clock,
  ShieldAlert
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error' | 'local'>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '從未同步');

  // Modals
  const [showSettings, setShowSettings] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);

  // Form States
  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  // AI
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Print Batch
  const [printBatch, setPrintBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  // Initialization
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) try { setItems(JSON.parse(savedItems)); } catch(e) { console.error("Load Items Error:", e); }
    if (savedLogs) try { setLogs(JSON.parse(savedLogs)); } catch(e) { console.error("Load Logs Error:", e); }
    setIsLoaded(true);
  }, []);

  // Sync Logic
  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const syncToCloud = async (currentItems: InventoryItem[], currentLogs: Transaction[]) => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const payload = { items: currentItems, logs: currentLogs, timestamp: Date.now() };
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify(payload), mode: 'no-cors' });
      setSyncStatus('synced');
      const time = new Date().toLocaleString();
      setLastSyncTime(time);
      localStorage.setItem(STORAGE_KEY_LAST_SYNC, time);
    } catch (e) { setSyncStatus('error'); }
  };

  // Dashboard Stats
  const stats = useMemo(() => {
    const now = new Date();
    const currentGroupItems = items.filter(i => 
      activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY'
    );

    const lowStock = currentGroupItems.filter(i => i.quantity <= i.minStock).length;
    const expiringSoon = currentGroupItems.filter(i => {
      if (!i.expiryDate) return false;
      const exp = new Date(i.expiryDate);
      const diffDays = (exp.getTime() - now.getTime()) / (1000 * 3600 * 24);
      return diffDays > 0 && diffDays <= 60; // 60天預警
    }).length;

    const monthlyOut = logs.filter(l => {
      const logDate = new Date(l.timestamp);
      return l.type === 'OUT' && 
             logDate.getMonth() === now.getMonth() && 
             logDate.getFullYear() === now.getFullYear();
    }).reduce((acc, curr) => acc + curr.quantity, 0);

    return { 
      total: currentGroupItems.length, 
      lowStock, 
      expiringSoon, 
      monthlyOut 
    };
  }, [items, logs, activeTab]);

  // UI Handlers
  const handleAddItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: InventoryItem = {
      id: Date.now().toString(),
      name: formData.get('name') as string,
      category: formData.get('category') as Category,
      itemType: formData.get('itemType') as ItemType,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    };
    const nextItems = [...items, newItem];
    setItems(nextItems);
    syncToCloud(nextItems, logs);
    setShowAddModal(false);
  };

  const handleEditItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editTarget) return;
    const formData = new FormData(e.currentTarget);
    const updatedItems = items.map(i => i.id === editTarget.id ? {
      ...i,
      name: formData.get('name') as string,
      category: formData.get('category') as Category,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      minStock: Number(formData.get('minStock')),
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    } : i);
    setItems(updatedItems);
    syncToCloud(updatedItems, logs);
    setEditTarget(null);
  };

  const handleDelete = () => {
    if (!deleteTarget) return;
    const nextItems = items.filter(i => i.id !== deleteTarget.id);
    setItems(nextItems);
    syncToCloud(nextItems, logs);
    setDeleteTarget(null);
  };

  const addToBasket = () => {
    const target = items.find(i => i.id === selectedItemId);
    if (!target) return;
    const qty = Number(inputQty);
    if (qty <= 0) return;
    if (issuanceMode === 'OUT' && target.quantity < qty) {
      alert('庫存餘額不足以支應該領用數量！'); return;
    }
    setBasket([...basket, { itemId: target.id, name: target.name, quantity: qty, unit: target.unit }]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const ts = Date.now();
    let nextItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(b => {
      nextItems = nextItems.map(item => {
        if (item.id === b.itemId) {
          const nQty = issuanceMode === 'OUT' ? item.quantity - b.quantity : item.quantity + b.quantity;
          return { ...item, quantity: nQty, lastUpdated: ts };
        }
        return item;
      });
      newLogs.push({
        id: `TX-${ts}-${b.itemId}`,
        itemId: b.itemId,
        itemName: b.name,
        type: issuanceMode,
        quantity: b.quantity,
        person: inputPerson || '未填寫',
        dept: issuanceMode === 'OUT' ? selectedDept : '庫房管理',
        reason: inputReason,
        timestamp: ts
      });
    });

    const combinedLogs = [...newLogs, ...logs];
    setItems(nextItems);
    setLogs(combinedLogs);
    syncToCloud(nextItems, combinedLogs);

    if (issuanceMode === 'OUT') {
      setPrintBatch({
        id: `SN-${ts.toString().slice(-6)}`,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: ts
      });
      setShowPrintModal(true);
    } else {
      alert('補貨入庫作業已完成，庫存已自動更新。');
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    const msg = await getInventoryInsights(items);
    setAiInsights(msg);
    setIsAiLoading(false);
  };

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900 selection:bg-blue-100 selection:text-blue-900">
      {/* Sidebar - Professional Theme */}
      <aside className="w-72 bg-slate-900 text-white flex flex-col no-print shrink-0 shadow-2xl">
        <div className="p-8">
          <div className="flex items-center gap-4 mb-12">
            <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center shadow-lg shadow-blue-500/40">
              <Package className="text-white" size={28} />
            </div>
            <div>
              <span className="text-xl font-black tracking-tighter block leading-none">SAFETY PRO</span>
              <span className="text-[9px] text-blue-400 font-bold tracking-[0.2em] uppercase mt-1 block">Ultimate V35</span>
            </div>
          </div>

          <nav className="space-y-1.5">
            {[
              { id: 'inventory', label: '工安耗材資料', icon: Package },
              { id: 'medicine', label: '急救藥材資料', icon: Stethoscope },
              { id: 'issuance', label: '領用與補貨', icon: ShoppingCart },
              { id: 'history', label: '歷史變更日誌', icon: History },
              { id: 'dashboard', label: '智能分析看板', icon: LayoutDashboard },
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl font-bold transition-all ${
                  activeTab === tab.id 
                    ? 'bg-blue-600 text-white shadow-xl shadow-blue-900/40 translate-x-1' 
                    : 'text-slate-400 hover:bg-slate-800 hover:text-slate-100'
                }`}
              >
                <tab.icon size={20} /> {tab.label}
              </button>
            ))}
          </nav>
        </div>

        <div className="mt-auto p-8 space-y-6">
          <div className="bg-slate-800/40 rounded-3xl p-5 border border-slate-700/30 backdrop-blur-sm">
            <div className="flex items-center justify-between mb-2.5">
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Cloud Sync</span>
              <div className={`w-2.5 h-2.5 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.4)]' : 'bg-orange-500 animate-pulse'}`} />
            </div>
            <p className="text-[11px] text-slate-300 font-semibold leading-relaxed">最後狀態: {lastSyncTime}</p>
          </div>
          <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-2.5 text-slate-400 hover:text-white transition-all text-sm font-bold group">
            <Settings size={18} className="group-hover:rotate-90 transition-transform duration-500" /> 系統進階設定
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 p-10 overflow-y-auto no-print custom-scrollbar">
        <div className="max-w-6xl mx-auto">
          {/* Header Section */}
          <header className="flex justify-between items-end mb-12">
            <div>
              <div className="flex items-center gap-2.5 text-blue-600 font-black text-[10px] uppercase tracking-[0.3em] mb-3">
                <div className="h-1 w-10 bg-blue-600 rounded-full"></div>
                Repair Division South Branch
              </div>
