export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  Settings,
  ArrowUpRight,
  ArrowDownLeft,
  RefreshCw,
  ClipboardList,
  Save,
  Calendar,
  Layers,
  ShieldAlert,
  Clock,
  CheckCircle2
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error' | 'local'>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '尚未執行同步');

  // Modals
  const [showSettings, setShowSettings] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);

  // Form States
  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  // AI
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Print Batch
  const [printBatch, setPrintBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  // 1. 初始化資料載入
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) try { setItems(JSON.parse(savedItems)); } catch(e) { console.error(e); }
    if (savedLogs) try { setLogs(JSON.parse(savedLogs)); } catch(e) { console.error(e); }
    setIsLoaded(true);
  }, []);

  // 2. 本地持久化
  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  // 3. 雲端同步邏輯
  const syncToCloud = async (currentItems: InventoryItem[], currentLogs: Transaction[]) => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const payload = { items: currentItems, logs: currentLogs, timestamp: Date.now() };
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify(payload), mode: 'no-cors' });
      setSyncStatus('synced');
      const time = new Date().toLocaleString();
      setLastSyncTime(time);
      localStorage.setItem(STORAGE_KEY_LAST_SYNC, time);
    } catch (e) { setSyncStatus('error'); }
  };

  // 4. 統計數據分析 (V35 標準邏輯)
  const stats = useMemo(() => {
    const now = new Date();
    const currentGroupItems = items.filter(i => 
      activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY'
    );

    const lowStock = currentGroupItems.filter(i => i.quantity <= i.minStock).length;
    const expiringSoon = currentGroupItems.filter(i => {
      if (!i.expiryDate) return false;
      const exp = new Date(i.expiryDate);
      const diffDays = (exp.getTime() - now.getTime()) / (1000 * 3600 * 24);
      return diffDays > 0 && diffDays <= 60; // 60天預警
    }).length;

    const monthlyOut = logs.filter(l => {
      const logDate = new Date(l.timestamp);
      return l.type === 'OUT' && 
             logDate.getMonth() === now.getMonth() && 
             logDate.getFullYear() === now.getFullYear();
    }).reduce((acc, curr) => acc + curr.quantity, 0);

    return { total: currentGroupItems.length, lowStock, expiringSoon, monthlyOut };
  }, [items, logs, activeTab]);

  // 5. 品項維護 (新增/編輯)
  const handleAddItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: InventoryItem = {
      id: `ITEM-${Date.now()}`,
      name: formData.get('name') as string,
      category: formData.get('category') as Category,
      itemType: formData.get('itemType') as ItemType,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    };
    const nextItems = [...items, newItem];
    setItems(nextItems);
    syncToCloud(nextItems, logs);
    setShowAddModal(false);
  };

  const handleEditItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editTarget) return;
    const formData = new FormData(e.currentTarget);
    const updatedItems = items.map(i => i.id === editTarget.id ? {
      ...i,
      name: formData.get('name') as string,
      category: formData.get('category') as Category,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      minStock: Number(formData.get('minStock')),
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    } : i);
    setItems(updatedItems);
    syncToCloud(updatedItems, logs);
    setEditTarget(null);
  };

  // Fix for error on line 633: Implement handleDelete
  const handleDelete = () => {
    if (!deleteTarget) return;
    const nextItems = items.filter(i => i.id !== deleteTarget.id);
    setItems(nextItems);
    syncToCloud(nextItems, logs);
    setDeleteTarget(null);
  };

  // Fix for error on line 546: Implement fetchAiInsights
  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    try {
      const insights = await getInventoryInsights(items);
      setAiInsights(insights);
    } catch (error) {
      console.error("AI Insights Error:", error);
      setAiInsights("AI 助理暫時無法提供建議，請稍後再試。");
    } finally {
      setIsAiLoading(false);
    }
  };

  // 6. 領用與補貨邏輯
  const addToBasket = () => {
    const target = items.find(i => i.id === selectedItemId);
    if (!target) return;
    const qty = Number(inputQty);
    if (qty <= 0) return;
    if (issuanceMode === 'OUT' && target.quantity < qty) {
      alert('【庫存警告】在庫數量不足，無法支應該領用需求！'); return;
    }
    setBasket([...basket, { itemId: target.id, name: target.name, quantity: qty, unit: target.unit }]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const ts = Date.now();
    let nextItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(b => {
      nextItems = nextItems.map(item => {
        if (item.id === b.itemId) {
          const nQty = issuanceMode === 'OUT' ? item.quantity - b.quantity : item.quantity + b.quantity;
          return { ...item, quantity: nQty, lastUpdated: ts };
        }
        return item;
      });
      newLogs.push({
        id: `TX-${ts}-${b.itemId}`,
        itemId: b.itemId,
        itemName: b.name,
        type: issuanceMode,
        quantity: b.quantity,
        person: inputPerson || '庫房經辦',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: inputReason,
        timestamp: ts
      });
    });

    const combinedLogs = [...newLogs, ...logs];
    setItems(nextItems);
    setLogs(combinedLogs);
    syncToCloud(nextItems, combinedLogs);

    if (issuanceMode === 'OUT') {
      setPrintBatch({
        id: `DOC-${ts.toString().slice(-6)}`,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: ts
      });
      setShowPrintModal(true);
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900">
      {/* 側邊欄 - V35 專業深色主題 */}
      <aside className="w-72 bg-slate-900 text-white flex flex-col no-print shrink-0 shadow-2xl">
        <div className="p-8">
          <div className="flex items-center gap-4 mb-12">
            <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center shadow-lg shadow-blue-500/40">
              <Package className="text-white" size={28} />
            </div>
            <div>
              <span className="text-xl font-black tracking-tighter block leading-none uppercase">SAFETY PRO</span>
              <span className="text-[9px] text-blue-400 font-bold tracking-[0.2em] uppercase mt-1 block">V35 Ultimate Final</span>
            </div>
          </div>

          <nav className="space-y-1.5">
            {[
              { id: 'inventory', label: '工安耗材管理', icon: Package },
              { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
              { id: 'issuance', label: '領用與補貨作業', icon: ShoppingCart },
              { id: 'history', label: '歷史異動日誌', icon: History },
              { id: 'dashboard', label: '統計分析看板', icon: LayoutDashboard },
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl font-bold transition-all ${
                  activeTab === tab.id 
                    ? 'bg-blue-600 text-white shadow-xl shadow-blue-900/40' 
                    : 'text-slate-400 hover:bg-slate-800'
                }`}
              >
                <tab.icon size={20} /> {tab.label}
              </button>
            ))}
          </nav>
        </div>

        <div className="mt-auto p-8 space-y-6">
          <div className="bg-slate-800/40 rounded-3xl p-5 border border-slate-700/30">
            <div className="flex items-center justify-between mb-2">
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Cloud Status</span>
              <div className={`w-2.5 h-2.5 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500' : 'bg-orange-500'}`} />
            </div>
            <p className="text-[11px] text-slate-300 font-semibold truncate">最後同步: {lastSyncTime}</p>
          </div>
          <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-2.5 text-slate-400 hover:text-white transition-all text-sm font-bold">
            <Settings size={18} /> 系統連線設定
          </button>
        </div>
      </aside>

      {/* 主內容區 */}
      <main className="flex-1 p-10 overflow-y-auto no-print">
        <div className="max-w-6xl mx-auto">
          {/* Header */}
          <header className="flex justify-between items-end mb-10">
            <div>
              <div className="flex items-center gap-2.5 text-blue-600 font-black text-[10px] uppercase tracking-[0.3em] mb-3">
                <div className="h-1 w-10 bg-blue-600 rounded-full"></div>
                Repair Division South - Industrial Safety
              </div>
              <h2 className="text-4xl font-black text-slate-900 tracking-tight uppercase">
                {activeTab === 'inventory' ? '工安耗材及設備管理檔案' : 
                 activeTab === 'medicine' ? '急救藥材及藥品管理檔案' : 
                 activeTab === 'issuance' ? '庫存領用與補貨系統' : 
                 activeTab === 'history' ? '歷史異動日誌審閱' : '管理數據與統計建議'}
              </h2>
            </div>
            {(activeTab === 'inventory' || activeTab === 'medicine') && (
              <button onClick={() => setShowAddModal(true)} className="bg-slate-900 hover:bg-black text-white px-8 py-4.5 rounded-2xl font-black flex items-center gap-3 shadow-2xl transition-all">
                <Plus size={22} /> 新增管理項目
              </button>
            )}
          </header>

          {/* V35 核心四格統計看板 */}
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <div className="grid grid-cols-4 gap-6 mb-10">
              <div className="bg-white p-8 rounded-[2rem] border border-slate-200/60 shadow-sm">
                <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1.5">在庫品項總量</p>
                <p className="text-4xl font-black">{stats.total}</p>
              </div>
              <div className="bg-white p-8 rounded-[2rem] border border-slate-200/60 shadow-sm">
                <p className="text-red-400 text-[10px] font-black uppercase tracking-widest mb-1.5">庫存水位預警</p>
                <p className="text-4xl font-black text-red-500">{stats.lowStock}</p>
              </div>
              <div className="bg-white p-8 rounded-[2rem] border border-slate-200/60 shadow-sm">
                <p className="text-orange-400 text-[10px] font-black uppercase tracking-widest mb-1.5">效期預警 (60天)</p>
                <p className="text-4xl font-black text-orange-500">{stats.expiringSoon}</p>
              </div>
              <div className="bg-white p-8 rounded-[2rem] border border-slate-200/60 shadow-sm">
                <p className="text-blue-400 text-[10px] font-black uppercase tracking-widest mb-1.5">本月累計消耗</p>
                <p className="text-4xl font-black text-blue-600">{stats.monthlyOut}</p>
              </div>
            </div>
          )}

          {/* 庫存列表表格 */}
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <div className="bg-white rounded-[2.5rem] shadow-xl border border-slate-100 overflow-hidden">
               <div className="p-8 bg-slate-50/50 border-b flex items-center justify-between">
