                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18}/>
                    <input className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-slate-200 font-bold shadow-inner" placeholder="搜尋品項名稱、規格或類別..." value={searchTerm} onChange={e=>setSearchTerm(e.target.value)} />
