                        <th className="px-8 py-5 text-[11px] font-black text-slate-500 uppercase tracking-widest text-center">當前庫存</th>
                        <th className="px-8 py-5 text-[11px] font-black text-slate-500 uppercase tracking-widest">購入/到期日期</th>
                        <th className="px-8 py-5 text-[11px] font-black text-slate-500 uppercase tracking-widest text-right">操作</th>
                      </tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100">
