                        const isExpired = item.expiryDate && new Date(item.expiryDate) < new Date();
                        const isLow = item.quantity <= item.minStock;
                        return (
                          <tr key={item.id} className="hover:bg-blue-50/30 transition-colors group">
                            <td className="px-8 py-6">
                              <div className="font-black text-slate-800 text-lg tracking-tight">{item.name}</div>
                              <div className="flex gap-2 mt-1">
                                <span className="px-2 py-0.5 bg-slate-900 text-[10px] font-black text-white rounded uppercase">{item.category}</span>
                                <span className="px-2 py-0.5 bg-blue-100 text-[10px] font-black text-blue-500 rounded uppercase">{item.itemType === 'EQUIPMENT' ? '設備' : '消耗品'}</span>
                              </div>
                            </td>
                            <td className="px-8 py-6">
                              <div className="font-bold text-slate-600 text-sm">{item.spec || '---'}</div>
                              <div className="text-[10px] text-slate-400 font-black">單位: {item.unit}</div>
                            </td>
                            <td className="px-8 py-6 text-center">
                              <div className={`inline-flex items-center gap-2.5 px-6 py-3 rounded-2xl font-black text-lg ${isLow ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-700'}`}>
