                        {items.map(i => <option key={i.id} value={i.id}>{i.name} (剩餘 {i.quantity} {i.unit})</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-[11px] font-black text-slate-400 uppercase mb-2 ml-1">異動數量</label>
