                    </div>
                    <button onClick={addToBasket} disabled={!selectedItemId} className="w-full py-5 bg-slate-900 text-white rounded-[1.25rem] font-black text-lg hover:bg-black disabled:opacity-30 mt-4 transition-all active:scale-95 shadow-xl">加入待處理籃子</button>
