                          <p className="font-black text-slate-800 text-xl tracking-tight">{b.name}</p>
                          <p className="text-[10px] text-slate-400 font-black uppercase mt-1">ID: {b.itemId}</p>
                        </div>
                        <div className="flex items-center gap-8">
                          <span className="font-black text-blue-600 text-2xl">{b.quantity} <span className="text-xs text-slate-400">{b.unit}</span></span>
                          <button onClick={()=>setBasket(prev=>prev.filter((_,i)=>i!==idx))} className="text-slate-200 hover:text-red-500 transition-all"><X size={24}/></button>
                        </div>
                      </div>
                    ))
                  )}
                </div>

                {issuanceMode === 'OUT' && (
