                        {DEPARTMENTS.map(d=><option key={d}>{d}</option>)}
                      </select>
                    </div>
                    <div className="space-y-2">
                      <label className="text-[11px] font-black text-slate-400 uppercase ml-1 tracking-widest">領用人</label>
                      <input className="w-full p-4.5 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" placeholder="輸入姓名" value={inputPerson} onChange={e=>setInputPerson(e.target.value)} />
                    </div>
                  </div>
                )}
                <div className="space-y-2 mb-10">
                  <label className="text-[11px] font-black text-slate-400 uppercase ml-1 tracking-widest">用途或備註說明</label>
                  <input className="w-full p-4.5 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold shadow-inner" placeholder="例：南三隊例行更換用..." value={inputReason} onChange={e=>setInputReason(e.target.value)} />
                </div>
                <button onClick={processIssuance} disabled={basket.length===0} className={`w-full py-7 rounded-[1.5rem] font-black text-2xl text-white shadow-2xl transition-all active:scale-95 ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>
                  {issuanceMode==='OUT' ? '確認領用並列印 A4 單據' : '執行補貨入庫'}
                </button>
              </div>
            </div>
          )}

          {/* 歷史異動 */}
          {activeTab === 'history' && (
            <div className="bg-white rounded-[2.5rem] shadow-2xl border border-slate-100 overflow-hidden">
               <div className="p-8 bg-slate-900 border-b flex justify-between items-center text-white">
                  <h3 className="text-xl font-black">全系統異動審核日誌</h3>
                  <button className="text-xs font-black text-blue-400 hover:underline">匯出異動紀錄 (CSV)</button>
               </div>
               <div className="overflow-x-auto">
                 <table className="w-full text-left">
                    <thead className="bg-slate-100 text-[10px] font-black text-slate-500 uppercase tracking-widest">
                      <tr>
                        <th className="px-8 py-6">異動日期/時間</th>
                        <th className="px-8 py-6">作業類型</th>
                        <th className="px-8 py-6">品項名稱</th>
                        <th className="px-8 py-6">異動數量</th>
                        <th className="px-8 py-6">對象/部門</th>
                        <th className="px-8 py-6">備註</th>
