                          <td className="px-8 py-5">
                            <span className={`inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-full text-[10px] font-black uppercase ${log.type === 'IN' ? 'bg-emerald-100 text-emerald-700' : 'bg-blue-100 text-blue-700'}`}>
                              {log.type === 'IN' ? '補貨入庫' : '領用出庫'}
                            </span>
                          </td>
                          <td className="px-8 py-5 font-black text-slate-800 text-lg">{log.itemName}</td>
                          <td className={`px-8 py-5 font-black text-2xl ${log.type === 'IN' ? 'text-emerald-600' : 'text-slate-900'}`}>{log.type === 'IN' ? '+' : '-'}{log.quantity}</td>
                          <td className="px-8 py-5">
                            <div className="text-sm font-black text-slate-800">{log.dept}</div>
                            <div className="text-[10px] text-slate-400 font-bold uppercase">{log.person}</div>
                          </td>
                          <td className="px-8 py-5 text-sm font-medium text-slate-400 italic max-w-xs truncate">{log.reason || '---'}</td>
                        </tr>
                      ))}
                    </tbody>
                 </table>
               </div>
            </div>
          )}

          {/* AI 分析 */}
          {activeTab === 'dashboard' && (
            <div className="space-y-10 animate-in zoom-in-95 duration-500">
               <div className="bg-slate-900 rounded-[3.5rem] p-16 text-white relative overflow-hidden shadow-2xl">
                  <BrainCircuit className="absolute -right-16 -bottom-16 w-96 h-96 opacity-10 rotate-12" />
                  <div className="relative z-10 max-w-4xl">
                    <h3 className="text-4xl font-black mb-8 flex items-center gap-5"><BrainCircuit className="text-blue-400" size={48}/> 智能管理分析建議</h3>
                    <div className="bg-slate-800/60 backdrop-blur-xl p-10 rounded-[2.5rem] border border-white/5 leading-relaxed mb-10 min-h-[220px] text-xl font-medium text-slate-200 shadow-inner">
                      {isAiLoading ? (
                        <div className="flex flex-col items-center justify-center h-full py-10 space-y-4">
                           <RefreshCw className="animate-spin text-blue-500" size={48} />
                           <span className="text-blue-400 font-black animate-pulse">正在掃描資料庫欄位並生成管理策略...</span>
                        </div>
                      ) : (
                        <div className="whitespace-pre-wrap leading-relaxed">{aiInsights || "數據分析功能已就緒。點擊下方按鈕，系統將會根據庫存、效期及異動頻率，為您提供專業的採購與優化建議。"}</div>
                      )}
                    </div>
                    <button onClick={fetchAiInsights} disabled={isAiLoading} className="bg-blue-600 hover:bg-blue-500 text-white px-12 py-6 rounded-[1.5rem] font-black text-xl shadow-2xl flex items-center gap-4 transition-all hover:-translate-y-2 active:scale-95">
                      <RefreshCw className={isAiLoading ? 'animate-spin' : ''} size={28}/> 啟動全方位管理診斷
                    </button>
                  </div>
               </div>
            </div>
          )}
        </div>
      </main>

      {/* MODALS */}
      {(showAddModal || editTarget) && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-xl z-[500] flex items-center justify-center p-6 overflow-y-auto">
           <form onSubmit={editTarget ? handleEditItem : handleAddItem} className="bg-white rounded-[3.5rem] w-full max-w-3xl overflow-hidden shadow-2xl">
              <div className="p-12">
                <div className="flex justify-between items-center mb-10">
                   <h3 className="text-3xl font-black text-slate-900">{editTarget ? `編輯資料: ${editTarget.name}` : '新增管理品項項目'}</h3>
                   <button type="button" onClick={()=>{setShowAddModal(false); setEditTarget(null);}} className="p-3 hover:bg-slate-100 rounded-2xl transition-colors"><X size={28}/></button>
                </div>
                <div className="grid grid-cols-2 gap-8 mb-12">
                  <div className="col-span-2 space-y-2">
                    <label className="text-[11px] font-black text-slate-400 uppercase ml-1 tracking-widest">品項名稱 (必填)</label>
                    <input name="name" required defaultValue={editTarget?.name} className="w-full p-5 rounded-2xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-black text-xl shadow-inner" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[11px] font-black text-slate-400 uppercase ml-1 tracking-widest">規格尺寸</label>
                    <input name="spec" defaultValue={editTarget?.spec} className="w-full p-5 rounded-2xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[11px] font-black text-slate-400 uppercase ml-1 tracking-widest">管理類別</label>
                    <select name="category" defaultValue={editTarget?.category || Category.PROTECTION} className="w-full p-5 rounded-2xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold">
                      {Object.values(Category).map(c=><option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[11px] font-black text-slate-400 uppercase ml-1 tracking-widest">物品類型</label>
                    <select name="itemType" defaultValue={editTarget?.itemType || 'CONSUMABLE'} className="w-full p-5 rounded-2xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold">
                      <option value="CONSUMABLE">消耗品 (Consumable)</option>
                      <option value="EQUIPMENT">設備與器材 (Equipment)</option>
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[11px] font-black text-slate-400 uppercase ml-1 tracking-widest">單位</label>
                    <input name="unit" required defaultValue={editTarget?.unit || '個'} className="w-full p-5 rounded-2xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold shadow-inner" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[11px] font-black text-slate-400 uppercase ml-1 tracking-widest">購入日期</label>
                    <input name="purchaseDate" type="date" defaultValue={editTarget?.purchaseDate} className="w-full p-5 rounded-2xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[11px] font-black text-slate-400 uppercase ml-1 tracking-widest">有效日期 (到期日)</label>
                    <input name="expiryDate" type="date" defaultValue={editTarget?.expiryDate} className="w-full p-5 rounded-2xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" />
                  </div>
                  {!editTarget && (
                    <div className="space-y-2">
                      <label className="text-[11px] font-black text-slate-400 uppercase ml-1 tracking-widest">初始庫存量</label>
                      <input name="quantity" type="number" required defaultValue="0" className="w-full p-5 rounded-2xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-black shadow-inner" />
                    </div>
                  )}
                  <div className="space-y-2">
                    <label className="text-[11px] font-black text-slate-400 uppercase ml-1 tracking-widest">在庫預警水位</label>
                    <input name="minStock" type="number" required defaultValue={editTarget?.minStock || 5} className="w-full p-5 rounded-2xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-black text-red-600 shadow-inner" />
                  </div>
                  <div className="col-span-2 space-y-2">
                    <label className="text-[11px] font-black text-slate-400 uppercase ml-1 tracking-widest">品項詳細描述/備註</label>
                    <textarea name="description" defaultValue={editTarget?.description} className="w-full p-5 rounded-2xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold shadow-inner min-h-[100px]"></textarea>
                  </div>
                </div>
                <div className="flex gap-6">
                   <button type="submit" className="flex-1 py-6 bg-blue-600 text-white rounded-[1.5rem] font-black text-2xl shadow-2xl hover:bg-blue-700 transition-all flex items-center justify-center gap-3">
                     <Save size={28}/> {editTarget ? '儲存變更資料' : '確認新增入庫'}
                   </button>
                   <button type="button" onClick={()=>{setShowAddModal(false); setEditTarget(null);}} className="px-12 py-6 bg-slate-100 rounded-[1.5rem] font-black text-xl hover:bg-slate-200 text-slate-500 transition-colors">取消離開</button>
                </div>
              </div>
           </form>
        </div>
      )}

      {/* 刪除確認 Modal */}
      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-xl z-[700] flex items-center justify-center p-6">
          <div className="bg-white rounded-[3rem] p-12 max-w-md w-full shadow-2xl text-center">
             <div className="w-24 h-24 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-8"><AlertTriangle size={50}/></div>
             <h3 className="text-3xl font-black text-slate-900 mb-3 tracking-tight">確定永久刪除？</h3>
             <p className="text-slate-500 font-bold mb-12 leading-relaxed">您正準備刪除 <span className="text-slate-900 font-black">"{deleteTarget.name}"</span>。<br/>此動作將影響資料庫完整性且無法復原，請務必確認。</p>
