                <div className="flex justify-between items-center mb-10">
                  <h3 className="text-3xl font-black tracking-tight uppercase">系統同步連線設定</h3>
                  <button onClick={()=>setShowSettings(false)} className="p-2 hover:bg-slate-100 rounded-xl"><X size={24}/></button>
                </div>
                <div className="space-y-8 mb-12">
