               <div className="flex items-center gap-4">
                  <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white"><Printer size={20}/></div>
                  <h3 className="font-black text-xl">領用單據正式列印預覽</h3>
               </div>
               <div className="flex gap-4">
                  <button onClick={()=>window.print()} className="px-8 py-4 bg-blue-600 text-white rounded-2xl font-black flex items-center gap-2.5 hover:bg-blue-700 transition-all shadow-xl">
