                            <th className="py-5 text-center font-black text-sm uppercase" style={{ width: '120px' }}>數量</th>
                            <th className="py-5 text-right font-black text-sm uppercase" style={{ width: '100px' }}>單位</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y-2 divide-slate-100">
                          {printBatch.items.map((item, idx) => (
                            <tr key={idx}>
                              <td className="py-6 font-black text-xl text-slate-900">{item.name}</td>
                              <td className="py-6 text-center font-black text-3xl text-blue-600">{item.quantity}</td>
                              <td className="py-6 text-right font-black text-lg text-slate-600">{item.unit}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>

                    <div className="mt-auto grid grid-cols-3 gap-16 pt-16 relative z-10">
                      <div className="text-center pt-8 border-t-2 border-slate-900 uppercase">
                         <p className="text-[10px] font-black text-slate-900">領用申請人簽章</p>
                      </div>
                      <div className="text-center pt-8 border-t-2 border-slate-900 uppercase">
                         <p className="text-[10px] font-black text-slate-900">部門主管核示</p>
                      </div>
                      <div className="text-center pt-8 border-t-2 border-slate-900 uppercase">
                         <p className="text-[10px] font-black text-slate-900">發放經辦人簽章</p>
                      </div>
                    </div>

                    <footer className="mt-16 text-[9px] text-slate-400 font-bold flex justify-between uppercase tracking-widest border-t border-slate-100 pt-6">
                      <span>Generated by SAFETY PRO Ultimate Final System</span>
                      <span>修護處南部分處 - 工安管理組資料存查單</span>
                      <span>{new Date().toLocaleString()}</span>
                    </footer>
                  </div>
               </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  Settings,
  ArrowUpRight,
  ArrowDownLeft,
  RefreshCw,
  ClipboardList,
  Save,
  Calendar,
  Layers,
  ShieldAlert,
  Clock,
  PieChart,
  BarChart3
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');

  // Modals
  const [showSettings, setShowSettings] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);

  // Form States
  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  // AI
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Print Data
  const [printBatch, setPrintBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) try { setItems(JSON.parse(savedItems)); } catch(e) {}
    if (savedLogs) try { setLogs(JSON.parse(savedLogs)); } catch(e) {}
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  // 看板深度數據分析
  const dashboardData = useMemo(() => {
    const deptStats: Record<string, number> = {};
    const itemStats: Record<string, number> = {};
    DEPARTMENTS.forEach(d => deptStats[d] = 0);

    logs.filter(l => l.type === 'OUT').forEach(log => {
      deptStats[log.dept] = (deptStats[log.dept] || 0) + log.quantity;
      itemStats[log.itemName] = (itemStats[log.itemName] || 0) + log.quantity;
    });

    const topItems = Object.entries(itemStats)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5);

    const lowStock = items.filter(i => i.quantity <= i.minStock).length;
    const expiringSoon = items.filter(i => i.itemGroup === 'MEDICINE' && i.expiryDate && (new Date(i.expiryDate).getTime() - Date.now()) / (1000 * 3600 * 24) <= 60).length;

    return { deptStats, topItems, lowStock, expiringSoon, totalItems: items.length };
  }, [items, logs]);

  const handleAddItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: InventoryItem = {
      id: `ITEM-${Date.now()}`,
      name: formData.get('name') as string,
      category: formData.get('category') as Category,
      itemType: formData.get('itemType') as ItemType,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
      purchaseDate: formData.get('purchaseDate') as string || undefined,
      expiryDate: formData.get('expiryDate') as string || undefined,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    };
    setItems([...items, newItem]);
    setShowAddModal(false);
  };

  const handleEditItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editTarget) return;
    const formData = new FormData(e.currentTarget);
    setItems(items.map(i => i.id === editTarget.id ? {
      ...i,
      name: formData.get('name') as string,
      category: formData.get('category') as Category,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      minStock: Number(formData.get('minStock')),
      purchaseDate: formData.get('purchaseDate') as string || undefined,
      expiryDate: formData.get('expiryDate') as string || undefined,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    } : i));
    setEditTarget(null);
  };

  const handleDelete = () => {
    if (!deleteTarget) return;
    setItems(items.filter(i => i.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  const addToBasket = () => {
    const target = items.find(i => i.id === selectedItemId);
    if (!target) return;
    const qty = Number(inputQty);
    if (qty <= 0) return;
    if (issuanceMode === 'OUT' && target.quantity < qty) {
      alert('庫存不足，無法領用！'); return;
    }
    setBasket([...basket, { itemId: target.id, name: target.name, quantity: qty, unit: target.unit }]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const ts = Date.now();
    let nextItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(b => {
      nextItems = nextItems.map(item => {
        if (item.id === b.itemId) {
          const nQty = issuanceMode === 'OUT' ? item.quantity - b.quantity : item.quantity + b.quantity;
          return { ...item, quantity: nQty, lastUpdated: ts };
        }
        return item;
      });
      newLogs.push({
        id: `TX-${ts}-${b.itemId}`,
        itemId: b.itemId,
        itemName: b.name,
        type: issuanceMode,
        quantity: b.quantity,
        person: inputPerson || '庫房員',
        dept: issuanceMode === 'OUT' ? selectedDept : '倉庫總部',
        reason: inputReason,
        timestamp: ts
      });
    });

    setItems(nextItems);
    setLogs([...newLogs, ...logs]);

    if (issuanceMode === 'OUT') {
      setPrintBatch({
        id: `DOC-${ts.toString().slice(-6)}`,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: ts
      });
      setShowPrintModal(true);
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900">
      {/* 側邊導覽欄 */}
      <aside className="w-64 bg-slate-900 text-white flex flex-col no-print shrink-0">
        <div className="p-6">
          <div className="flex items-center gap-3 mb-10">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center">
              <Package size={24} />
            </div>
            <span className="text-lg font-black tracking-tighter uppercase">SAFETY PRO</span>
          </div>

          <nav className="space-y-1">
            {[
              { id: 'inventory', label: '工安耗材', icon: Package },
              { id: 'medicine', label: '急救藥材', icon: Stethoscope },
              { id: 'issuance', label: '領用/補貨', icon: ShoppingCart },
              { id: 'history', label: '異動日誌', icon: History },
              { id: 'dashboard', label: '分析看板', icon: LayoutDashboard },
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`w-full flex items-center gap-3 px-4 py-3.5 rounded-xl font-bold transition-all ${
                  activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'
                }`}
              >
                <tab.icon size={18} /> {tab.label}
              </button>
            ))}
          </nav>
        </div>
        <button onClick={() => setShowSettings(true)} className="mt-auto p-6 flex items-center gap-2 text-slate-400 hover:text-white transition-all text-sm font-bold border-t border-slate-800">
          <Settings size={16} /> 系統設定
        </button>
      </aside>

      {/* 主介面 */}
      <main className="flex-1 p-8 overflow-y-auto no-print">
        <div className="max-w-6xl mx-auto">
          <header className="flex justify-between items-center mb-8">
            <h2 className="text-3xl font-black text-slate-800 uppercase tracking-tight">
              {activeTab === 'inventory' ? '工安耗材管理檔案' : 
               activeTab === 'medicine' ? '急救藥材及藥品管理' : 
               activeTab === 'issuance' ? '庫存領用與補貨' : 
               activeTab === 'history' ? '歷史異動紀錄' : '管理數據分析'}
            </h2>
            {(activeTab === 'inventory' || activeTab === 'medicine') && (
              <button onClick={() => setShowAddModal(true)} className="bg-slate-900 hover:bg-black text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 shadow-lg transition-all active:scale-95">
                <Plus size={20} /> 新增項目
              </button>
            )}
          </header>

          {/* 列表視圖 */}
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
               <div className="p-6 bg-slate-50 border-b">
                  <div className="relative w-80">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16}/>
                    <input className="w-full pl-10 pr-4 py-3 rounded-xl bg-white border border-slate-200 font-bold" placeholder="搜尋..." value={searchTerm} onChange={e=>setSearchTerm(e.target.value)} />
                  </div>
               </div>
               <div className="overflow-x-auto">
                 <table className="w-full text-left">
                   <thead>
                      <tr className="bg-slate-50 border-b border-slate-100">
                        <th className="px-6 py-4 text-xs font-black text-slate-500 uppercase tracking-widest">品項細節</th>
                        <th className="px-6 py-4 text-xs font-black text-slate-500 uppercase tracking-widest">規格/單位</th>
                        <th className="px-6 py-4 text-xs font-black text-slate-500 uppercase tracking-widest text-center">庫存</th>
                        {activeTab === 'medicine' && <th className="px-6 py-4 text-xs font-black text-slate-500 uppercase tracking-widest">有效日期</th>}
                        <th className="px-6 py-4 text-xs font-black text-slate-500 uppercase tracking-widest text-right">操作</th>
                      </tr>
                   </thead>
                   <tbody className="divide-y divide-slate-50">
                      {items.filter(i => (activeTab==='medicine' ? i.itemGroup==='MEDICINE' : i.itemGroup==='INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                        <tr key={item.id} className="hover:bg-slate-50 transition-colors group">
                          <td className="px-6 py-5">
                            <div className="font-bold text-slate-800">{item.name}</div>
                            <div className="text-[10px] font-black text-slate-400 uppercase mt-1">{item.category}</div>
                          </td>
                          <td className="px-6 py-5 text-sm font-medium text-slate-600">
                            {item.spec || '---'} / {item.unit}
                          </td>
                          <td className="px-6 py-5 text-center">
                            <span className={`px-4 py-1.5 rounded-full font-black text-sm ${item.quantity <= item.minStock ? 'bg-red-100 text-red-600' : 'bg-blue-50 text-blue-600'}`}>
                              {item.quantity}
                            </span>
                          </td>
                          {activeTab === 'medicine' && (
                            <td className="px-6 py-5 text-sm font-bold text-slate-700">
                              {item.expiryDate || '未填'}
                            </td>
                          )}
                          <td className="px-6 py-5 text-right">
                             <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button onClick={()=>setEditTarget(item)} className="p-2 hover:bg-white hover:shadow-md rounded-lg text-slate-400 hover:text-blue-600"><Edit3 size={16}/></button>
                                <button onClick={()=>setDeleteTarget({id: item.id, name: item.name})} className="p-2 hover:bg-white hover:shadow-md rounded-lg text-slate-400 hover:text-red-600"><Trash2 size={16}/></button>
                             </div>
                          </td>
                        </tr>
                      ))}
                   </tbody>
                 </table>
               </div>
            </div>
          )}

          {/* 領用分頁 */}
          {activeTab === 'issuance' && (
            <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
              <div className="lg:col-span-2">
                <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
                  <div className="flex bg-slate-100 p-1.5 rounded-xl mb-8">
                    <button onClick={()=>setIssuanceMode('OUT')} className={`flex-1 py-3 rounded-lg font-bold text-sm transition-all ${issuanceMode==='OUT' ? 'bg-white shadow text-blue-600' : 'text-slate-400'}`}>領用出庫</button>
                    <button onClick={()=>setIssuanceMode('IN')} className={`flex-1 py-3 rounded-lg font-bold text-sm transition-all ${issuanceMode==='IN' ? 'bg-white shadow text-emerald-600' : 'text-slate-400'}`}>補貨入庫</button>
                  </div>
                  <div className="space-y-5">
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ml-1">選擇品項</label>
                      <select className="w-full p-4 rounded-xl bg-slate-50 border border-slate-200 font-bold outline-none focus:ring-2 focus:ring-blue-500/20" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                        <option value="">請點擊選取...</option>
                        {items.map(i => <option key={i.id} value={i.id}>{i.name} (剩餘 {i.quantity})</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ml-1">數量</label>
                      <input type="number" className="w-full p-4 rounded-xl bg-slate-50 border border-slate-200 font-black text-xl" value={inputQty} onChange={e=>setInputQty(e.target.value)} />
                    </div>
                    <button onClick={addToBasket} disabled={!selectedItemId} className="w-full py-4 bg-slate-900 text-white rounded-xl font-bold hover:bg-black disabled:opacity-30 active:scale-95 transition-all">加入待處理清單</button>
                  </div>
                </div>
              </div>
              <div className="lg:col-span-3 flex flex-col">
                <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200 flex-1">
                  <h3 className="font-black text-xl mb-6 flex items-center gap-2"><ClipboardList className="text-blue-500"/> 待處理清單 ({basket.length})</h3>
                  <div className="bg-slate-50 rounded-2xl p-4 min-h-[300px] mb-6 space-y-3">
                    {basket.length === 0 ? (
                      <div className="h-full flex flex-col items-center justify-center text-slate-300 py-10">
                        <ShoppingCart size={48} className="mb-2 opacity-20"/>
                        <p className="font-bold">籃子內尚無項目</p>
                      </div>
                    ) : (
                      basket.map((b, idx) => (
                        <div key={idx} className="flex justify-between items-center p-4 bg-white rounded-xl border border-slate-100 shadow-sm">
                          <span className="font-bold text-slate-700">{b.name}</span>
                          <div className="flex items-center gap-6">
                            <span className="font-black text-blue-600 text-xl">{b.quantity} <span className="text-xs text-slate-400 font-bold">{b.unit}</span></span>
                            <button onClick={()=>setBasket(prev=>prev.filter((_,i)=>i!==idx))} className="text-slate-300 hover:text-red-500"><X size={20}/></button>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                  {issuanceMode === 'OUT' && (
                    <div className="grid grid-cols-2 gap-4 mb-4">
                      <select className="p-4 rounded-xl bg-slate-50 border border-slate-200 font-bold" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>
                        {DEPARTMENTS.map(d=><option key={d}>{d}</option>)}
                      </select>
                      <input className="p-4 rounded-xl bg-slate-50 border border-slate-200 font-bold" placeholder="領用人姓名" value={inputPerson} onChange={e=>setInputPerson(e.target.value)} />
                    </div>
                  )}
                  <input className="w-full p-4 rounded-xl bg-slate-50 border border-slate-200 font-bold mb-6" placeholder="用途備註" value={inputReason} onChange={e=>setInputReason(e.target.value)} />
                  <button onClick={processIssuance} disabled={basket.length===0} className={`w-full py-5 rounded-2xl font-black text-xl text-white shadow-lg active:scale-95 transition-all ${issuanceMode==='OUT' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-emerald-600 hover:bg-emerald-700'}`}>
                    {issuanceMode==='OUT' ? '確認領用並列印' : '確認補貨入庫'}
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* 看板分頁 (深度回溯版) */}
          {activeTab === 'dashboard' && (
            <div className="space-y-8">
              <div className="grid grid-cols-4 gap-6">
                <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-1">現有品項</p>
