          const nQty = issuanceMode === 'OUT' ? item.quantity - b.quantity : item.quantity + b.quantity;
          return { ...item, quantity: nQty, lastUpdated: ts };
        }
        return item;
      });
      newLogs.push({
        id: `TX-${ts}-${b.itemId}`,
        itemId: b.itemId,
        itemName: b.name,
        type: issuanceMode,
        quantity: b.quantity,
        person: inputPerson || '庫房員',
        dept: issuanceMode === 'OUT' ? selectedDept : '倉庫總部',
        reason: inputReason,
        timestamp: ts
      });
    });

    setItems(nextItems);
    setLogs([...newLogs, ...logs]);

    if (issuanceMode === 'OUT') {
      setPrintBatch({
        id: `DOC-${ts.toString().slice(-6)}`,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: ts
