      {/* 刪除確認 */}
      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[1100] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-8 max-w-sm w-full text-center">
             <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-6"><AlertTriangle size={32}/></div>
             <h3 className="text-xl font-black mb-2">確定刪除？</h3>
             <p className="text-slate-500 text-sm font-bold mb-8">"{deleteTarget.name}" 將 be 永久移除。</p>
             <div className="flex flex-col gap-3">
                <button onClick={handleDelete} className="w-full py-4 bg-red-600 text-white rounded-xl font-black shadow-lg">確認永久刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="w-full py-4 bg-slate-100 rounded-xl font-bold text-slate-500">取消</button>
             </div>
          </div>
        </div>
      )}

      {/* 設定頁面 */}
      {showSettings && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[1000] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl">
            <h3 className="text-xl font-black mb-6 uppercase">系統雲端同步設定</h3>
            <div className="space-y-6 mb-8">
              <input value={gasUrl} onChange={e=>{setGasUrl(e.target.value); localStorage.setItem(STORAGE_KEY_GAS_URL, e.target.value);}} placeholder="GAS Web App URL..." className="w-full p-4 rounded-xl bg-slate-50 border border-slate-200 font-mono text-xs" />
            </div>
            <button onClick={()=>setShowSettings(false)} className="w-full py-4 bg-slate-900 text-white rounded-xl font-black">儲存設定</button>
          </div>
        </div>
      )}

      {/* 列印單據 (A4 精簡版) */}
      {showPrintModal && printBatch && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-md z-[2000] flex items-center justify-center p-6 no-print overflow-y-auto">
          <div className="bg-white rounded-3xl w-full max-w-4xl max-h-[90vh] flex flex-col shadow-2xl overflow-hidden">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50">
               <h3 className="font-black text-lg flex items-center gap-2"><Printer size={18}/> 領用單列印預覽</h3>
               <div className="flex gap-3">
                  <button onClick={()=>window.print()} className="px-6 py-3 bg-blue-600 text-white rounded-xl font-black shadow-lg">確認列印</button>
                  <button onClick={()=>setShowPrintModal(false)} className="px-6 py-3 bg-slate-200 text-slate-700 rounded-xl font-bold">關閉</button>
               </div>
            </div>
            <div className="flex-1 p-10 bg-slate-100 flex justify-center">
               <div className="bg-white p-12 shadow-sm border border-slate-300 print-container" style={{ width: '210mm', minHeight: '297mm' }}>
                  <div className="border-[4px] border-slate-900 p-8 h-full flex flex-col">
                    <header className="flex justify-between items-start border-b-4 border-slate-900 pb-6 mb-8">
                      <div>
                        <h1 className="text-4xl font-black mb-1">工安耗材領用單</h1>
                        <p className="text-slate-500 font-bold uppercase text-xs">Industrial Safety Issuance Form</p>
                      </div>
                      <div className="text-right font-black">
                        <p className="text-xs text-slate-400">SERIAL NO.</p>
                        <p className="text-xl">{printBatch.id}</p>
                      </div>
                    </header>
                    <div className="grid grid-cols-2 gap-8 mb-10">
                      <div><p className="text-[10px] font-black text-slate-400 uppercase">領用單位</p><p className="text-xl font-black border-b-2 border-slate-100 pb-1">{printBatch.dept}</p></div>
                      <div><p className="text-[10px] font-black text-slate-400 uppercase">領用人</p><p className="text-xl font-black border-b-2 border-slate-100 pb-1">{printBatch.person || '---'}</p></div>
                    </div>
                    <table className="w-full mb-10">
                      <thead className="border-b-2 border-slate-900">
                        <tr>
                          <th className="py-3 text-left font-black text-sm uppercase">品項名稱</th>
                          <th className="py-3 text-center font-black text-sm uppercase">數量</th>
                          <th className="py-3 text-right font-black text-sm uppercase">單位</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {printBatch.items.map((item, idx) => (
                          <tr key={idx}>
                            <td className="py-4 font-bold text-lg">{item.name}</td>
                            <td className="py-4 text-center font-black text-2xl text-blue-600">{item.quantity}</td>
                            <td className="py-4 text-right font-bold">{item.unit}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    <div className="mt-auto grid grid-cols-3 gap-8 pt-10 border-t-2 border-slate-900 text-center">
                       <div><div className="h-10"></div><p className="text-[10px] font-black uppercase">申請人簽章</p></div>
                       <div><div className="h-10"></div><p className="text-[10px] font-black uppercase">主管核示</p></div>
                       <div><div className="h-10"></div><p className="text-[10px] font-black uppercase">經辦發放人</p></div>
                    </div>
                    <footer className="mt-8 text-[8px] text-slate-300 font-bold text-center uppercase">Safety Pro V35 Final System - {new Date().toLocaleString()}</footer>
                  </div>
               </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export enum Category {
  SAFETY_EQUIP = '安全衛生設備',
  SAFETY_CONS = '安全衛生類消耗品',
  MEDICINE = '急救藥材/藥品',
  OTHER = '其他'
}

export type ItemType = 'EQUIPMENT' | 'CONSUMABLE';
export type ItemGroup = 'INVENTORY' | 'MEDICINE';

export interface InventoryItem {
  id: string;
  name: string;
  category: string; // 改為 string 以利彈性顯示固定選項
  itemType: ItemType; 
  itemGroup: ItemGroup;
  unit: string;
  spec: string;
  quantity: number;
  minStock: number;
  purchaseDate?: string;
  expiryDate?: string;
  description: string;
  lastUpdated: number;
}

export type TransactionType = 'IN' | 'OUT';

export interface Transaction {
  id: string;
  itemId: string;
  itemName: string;
  type: TransactionType;
  quantity: number;
  person: string;
  dept: string;
  reason: string;
  timestamp: number;
  // 為了補印單據，儲存當時的整批次資訊
  batchId?: string; 
  items?: { name: string; quantity: number; unit: string }[];
}

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  Settings,
  ClipboardList,
  Save,
  PieChart,
  BarChart3,
  CheckCircle2
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  // Modals
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);

  // Form States
  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  // AI & Print Data
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [printBatch, setPrintBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) try { setItems(JSON.parse(savedItems)); } catch(e) {}
    if (savedLogs) try { setLogs(JSON.parse(savedLogs)); } catch(e) {}
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  // 看板深度數據分析
  const dashboardData = useMemo(() => {
    const deptStats: Record<string, number> = {};
    const itemStats: Record<string, number> = {};
    DEPARTMENTS.forEach(d => deptStats[d] = 0);

    logs.filter(l => l.type === 'OUT').forEach(log => {
      deptStats[log.dept] = (deptStats[log.dept] || 0) + log.quantity;
      itemStats[log.itemName] = (itemStats[log.itemName] || 0) + log.quantity;
    });

    const topItems = Object.entries(itemStats)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 8);

    const lowStock = items.filter(i => i.quantity <= i.minStock).length;
    const expiringSoon = items.filter(i => i.itemGroup === 'MEDICINE' && i.expiryDate && (new Date(i.expiryDate).getTime() - Date.now()) / (1000 * 3600 * 24) <= 60).length;

    return { deptStats, topItems, lowStock, expiringSoon, totalItems: items.length };
  }, [items, logs]);

  const handleAddItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: InventoryItem = {
      id: `ITEM-${Date.now()}`,
      name: formData.get('name') as string,
      category: formData.get('category') as string,
      itemType: (activeTab === 'inventory' ? 'CONSUMABLE' : 'EQUIPMENT') as ItemType,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
      purchaseDate: formData.get('purchaseDate') as string || undefined,
      expiryDate: formData.get('expiryDate') as string || undefined,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    };
    setItems([...items, newItem]);
    setShowAddModal(false);
  };

  const handleEditItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editTarget) return;
    const formData = new FormData(e.currentTarget);
    setItems(items.map(i => i.id === editTarget.id ? {
      ...i,
      name: formData.get('name') as string,
      category: formData.get('category') as string,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      minStock: Number(formData.get('minStock')),
      purchaseDate: formData.get('purchaseDate') as string || undefined,
      expiryDate: formData.get('expiryDate') as string || undefined,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    } : i));
    setEditTarget(null);
  };

  const handleDelete = () => {
    if (!deleteTarget) return;
    setItems(items.filter(i => i.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  // 領用加入籃子校驗
  const addToBasket = () => {
    const target = items.find(i => i.id === selectedItemId);
    if (!target) return;
    const qty = Number(inputQty);
    if (qty <= 0) return;

    // 計算籃內已有的數量
    const alreadyInBasket = basket.filter(b => b.itemId === target.id).reduce((sum, b) => sum + b.quantity, 0);
    const available = target.quantity - alreadyInBasket;

    if (issuanceMode === 'OUT' && available < qty) {
      alert(`庫存不足！該品項目前僅剩餘 ${available} ${target.unit} 可供領用。`);
      return;
    }

    setBasket([...basket, { itemId: target.id, name: target.name, quantity: qty, unit: target.unit }]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const ts = Date.now();
    const batchId = `DOC-${ts.toString().slice(-6)}`;
    let nextItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(b => {
      nextItems = nextItems.map(item => {
        if (item.id === b.itemId) {
          const nQty = issuanceMode === 'OUT' ? item.quantity - b.quantity : item.quantity + b.quantity;
          return { ...item, quantity: nQty, lastUpdated: ts };
        }
        return item;
      });
      newLogs.push({
        id: `TX-${ts}-${b.itemId}`,
        itemId: b.itemId,
        itemName: b.name,
        type: issuanceMode,
        quantity: b.quantity,
        person: inputPerson || '系統經辦',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: inputReason,
        timestamp: ts,
        batchId: batchId,
        items: [...basket]
      });
    });

    setItems(nextItems);
    setLogs([...newLogs, ...logs]);

    if (issuanceMode === 'OUT') {
      setPrintBatch({
        id: batchId,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: ts
      });
      setShowPrintModal(true);
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  // 補印功能
  const reprint = (log: Transaction) => {
    if (log.type !== 'OUT') return;
    setPrintBatch({
      id: log.batchId || 'N/A',
      dept: log.dept,
      person: log.person,
      reason: log.reason,
      items: log.items || [{ itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '個' }],
      timestamp: log.timestamp
    });
    setShowPrintModal(true);
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    try {
      const result = await getInventoryInsights(items);
      setAiInsights(result);
    } catch (error) {
      setAiInsights("AI 助理暫時無法提供建議。");
    } finally {
      setIsAiLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900">
      {/* 側邊導覽 */}
      <aside className="w-64 bg-slate-900 text-white flex flex-col no-print shrink-0 shadow-2xl">
        <div className="p-6">
          <div className="flex items-center gap-3 mb-10">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center">
              <Package size={24} />
            </div>
            <span className="text-lg font-black tracking-tighter uppercase">SAFETY PRO</span>
          </div>
          <nav className="space-y-1">
            {[
              { id: 'inventory', label: '工安耗材管理', icon: Package },
              { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
              { id: 'issuance', label: '領用/補貨作業', icon: ShoppingCart },
              { id: 'history', label: '異動日誌審核', icon: History },
              { id: 'dashboard', label: '管理分析看板', icon: LayoutDashboard },
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${
                  activeTab === tab.id ? 'bg-blue-600 text-white shadow-xl' : 'text-slate-400 hover:bg-slate-800'
                }`}
              >
                <tab.icon size={18} /> {tab.label}
              </button>
            ))}
          </nav>
        </div>
      </aside>

      <main className="flex-1 p-8 overflow-y-auto no-print">
        <div className="max-w-6xl mx-auto">
          <header className="flex justify-between items-end mb-8 border-b-2 border-slate-200 pb-6">
            <div>
              <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-1">Repair Division South - Industrial Safety</p>
              <h2 className="text-3xl font-black text-slate-800 uppercase tracking-tight">
                {activeTab === 'inventory' ? '工安耗材及設備管理檔案' : 
                 activeTab === 'medicine' ? '急救藥材及藥品管理檔案' : 
                 activeTab === 'issuance' ? '庫存領用與補貨系統' : 
                 activeTab === 'history' ? '歷史異動日誌審閱' : '管理數據與統計分析'}
              </h2>
            </div>
            {(activeTab === 'inventory' || activeTab === 'medicine') && (
              <button onClick={() => setShowAddModal(true)} className="bg-slate-900 hover:bg-black text-white px-8 py-4 rounded-2xl font-black flex items-center gap-2 shadow-xl transition-all">
                <Plus size={22} /> 新增管理項目
              </button>
            )}
          </header>

          {/* 數據看板 (深度回歸) */}
          {activeTab === 'dashboard' && (
            <div className="space-y-10">
              <div className="grid grid-cols-4 gap-6">
                <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-1">在庫品項總數</p>
                  <p className="text-3xl font-black">{dashboardData.totalItems}</p>
                </div>
                <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                  <p className="text-[10px] font-black text-red-400 uppercase mb-1">庫存水位預警</p>
                  <p className="text-3xl font-black text-red-500">{dashboardData.lowStock}</p>
                </div>
                <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                  <p className="text-[10px] font-black text-orange-400 uppercase mb-1">藥材效期預警</p>
                  <p className="text-3xl font-black text-orange-500">{dashboardData.expiringSoon}</p>
                </div>
                <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                  <p className="text-[10px] font-black text-blue-400 uppercase mb-1">本月累計異動</p>
                  <p className="text-3xl font-black text-blue-600">{logs.length}</p>
                </div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* 部門消耗分析 */}
                <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm">
                  <h3 className="text-lg font-black mb-8 flex items-center gap-2 border-b pb-4"><PieChart className="text-blue-500"/> 各部門領用比例分析</h3>
                  <div className="space-y-6">
                    {Object.entries(dashboardData.deptStats).sort((a,b)=>b[1]-a[1]).map(([dept, val]) => (
                      <div key={dept} className="flex items-center gap-4">
                        <div className="w-24 text-xs font-black text-slate-500 uppercase">{dept}</div>
                        <div className="flex-1 h-2.5 bg-slate-100 rounded-full overflow-hidden">
                          <div className="h-full bg-blue-500 rounded-full transition-all duration-1000" style={{ width: `${Math.min(100, (val / (logs.length || 1)) * 50)}%` }}></div>
                        </div>
                        <div className="w-12 text-right text-sm font-black text-slate-800">{val}</div>
                      </div>
                    ))}
                  </div>
                </div>
                {/* 熱門領用品項 */}
                <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm">
                  <h3 className="text-lg font-black mb-8 flex items-center gap-2 border-b pb-4"><BarChart3 className="text-emerald-500"/> 重點消耗品項 Top 8</h3>
                  <div className="space-y-4">
                    {dashboardData.topItems.map(([name, val], idx) => (
                      <div key={name} className="flex justify-between items-center p-4 bg-slate-50 rounded-2xl hover:bg-emerald-50 transition-colors">
                        <div className="flex items-center gap-4">
                          <span className="w-6 h-6 bg-slate-900 text-white rounded-lg flex items-center justify-center text-[10px] font-black">{idx+1}</span>
                          <span className="font-bold text-slate-700">{name}</span>
                        </div>
                        <span className="font-black text-lg text-emerald-600">{val} <span className="text-[10px] text-slate-400">UNIT</span></span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>

              {/* AI 診斷 */}
              <div className="bg-slate-900 rounded-[3rem] p-12 text-white relative overflow-hidden shadow-2xl">
                <BrainCircuit className="absolute -right-10 -bottom-10 w-72 h-72 opacity-10 rotate-12" />
                <div className="relative z-10">
                  <h3 className="text-2xl font-black mb-6 flex items-center gap-3"><BrainCircuit className="text-blue-400" size={32}/> AI 智能管理建議系統</h3>
                  <div className="bg-slate-800/60 backdrop-blur-xl p-8 rounded-2xl border border-white/5 mb-8 text-lg font-medium leading-relaxed text-slate-200 min-h-[120px]">
                    {isAiLoading ? "正在分析資料庫..." : aiInsights || "點擊按鈕，由 AI 協助掃描庫存水位並生成管理對策。"}
                  </div>
                  <button onClick={fetchAiInsights} disabled={isAiLoading} className="bg-blue-600 hover:bg-blue-500 px-10 py-5 rounded-2xl font-black text-lg flex items-center gap-3 transition-all active:scale-95 shadow-lg">
                    <RefreshCw className={isAiLoading ? 'animate-spin' : ''} size={24}/> 啟動庫存診斷
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* 列表與其他功能 (回溯最簡潔版本) */}
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden">
               <div className="p-6 bg-slate-50 border-b flex justify-between items-center">
                  <div className="relative w-96">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18}/>
