                    </div>
                    <div className="flex-1">
                      <table className="w-full">
                        <thead className="border-b-4 border-slate-900">
                          <tr className="text-left">
                            <th className="py-4 font-black text-sm uppercase">品項名稱及規格</th>
                            <th className="py-4 text-center font-black text-sm uppercase" style={{ width: '120px' }}>數量</th>
                            <th className="py-4 text-right font-black text-sm uppercase" style={{ width: '100px' }}>單位</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y-2 divide-slate-100">
                          {printBatch.items.map((item, idx) => (
                            <tr key={idx}>
                              <td className="py-6 font-black text-2xl text-slate-900">{item.name}</td>
                              <td className="py-6 text-center font-black text-4xl text-blue-600">{item.quantity}</td>
                              <td className="py-6 text-right font-black text-xl text-slate-600">{item.unit}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                    <div className="mt-auto grid grid-cols-3 gap-12 pt-16 border-t-[4px] border-slate-900 text-center">
                       <div className="pt-4 border-t-2 border-slate-200"><p className="text-[10px] font-black uppercase">申請人簽章</p></div>
                       <div className="pt-4 border-t-2 border-slate-200"><p className="text-[10px] font-black uppercase">主管核示</p></div>
                       <div className="pt-4 border-t-2 border-slate-200"><p className="text-[10px] font-black uppercase">發放人經辦</p></div>
                    </div>
                    <footer className="mt-12 text-[8px] text-slate-300 font-bold text-center uppercase tracking-[0.4em]">Safety Pro Ultimate Final System - Repair South</footer>
                  </div>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* 刪除確認 (最簡潔版) */}
      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm z-[2000] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2rem] p-8 max-w-sm w-full text-center shadow-2xl">
             <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-6"><AlertTriangle size={32}/></div>
             <h3 className="text-2xl font-black mb-2">確定刪除？</h3>
             <p className="text-slate-500 font-bold mb-8">"{deleteTarget.name}" 將被永久移除且無法還原。</p>
             <div className="flex flex-col gap-3">
                <button onClick={handleDelete} className="w-full py-4 bg-red-600 text-white rounded-xl font-black text-lg shadow-xl">確認永久刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="w-full py-4 bg-slate-100 rounded-xl font-black text-slate-500">取消</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export enum Category {
  SAFETY_EQUIP = '安全衛生設備',
  SAFETY_CONS = '安全衛生類消耗品',
  MEDICINE = '急救藥材/藥品',
  OTHER = '其他'
}

export type ItemType = 'EQUIPMENT' | 'CONSUMABLE';
export type ItemGroup = 'INVENTORY' | 'MEDICINE';

export interface InventoryItem {
  id: string;
  name: string;
  category: string; // 改為 string 以利彈性顯示固定選項
  itemType: ItemType; 
  itemGroup: ItemGroup;
  unit: string;
  spec: string;
  quantity: number;
  minStock: number;
  purchaseDate?: string;
  expiryDate?: string;
  description: string;
  lastUpdated: number;
}

export type TransactionType = 'IN' | 'OUT';

export interface Transaction {
  id: string;
  itemId: string;
  itemName: string;
  type: TransactionType;
  quantity: number;
  person: string;
  dept: string;
  reason: string;
  timestamp: number;
  // 為了補印單據，儲存當時的整批次資訊
  batchId?: string; 
  // Fix: Added itemId to the nested items objects to match BasketItem definition in App.tsx
  items?: { itemId: string; name: string; quantity: number; unit: string }[];
}

