  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  Settings,
  ClipboardList,
  Save,
  PieChart,
  BarChart3,
  CheckCircle2,
  // Fix: Added RefreshCw to the imported icons
  RefreshCw
