  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);

  // Form States
  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  // AI & Print Data
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [printBatch, setPrintBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) try { setItems(JSON.parse(savedItems)); } catch(e) {}
    if (savedLogs) try { setLogs(JSON.parse(savedLogs)); } catch(e) {}
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  // 看板深度數據分析
  const dashboardData = useMemo(() => {
    const deptStats: Record<string, number> = {};
    const itemStats: Record<string, number> = {};
    DEPARTMENTS.forEach(d => deptStats[d] = 0);

    logs.filter(l => l.type === 'OUT').forEach(log => {
      deptStats[log.dept] = (deptStats[log.dept] || 0) + log.quantity;
      itemStats[log.itemName] = (itemStats[log.itemName] || 0) + log.quantity;
    });

    const topItems = Object.entries(itemStats)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 8);

    const lowStock = items.filter(i => i.quantity <= i.minStock).length;
    const expiringSoon = items.filter(i => i.itemGroup === 'MEDICINE' && i.expiryDate && (new Date(i.expiryDate).getTime() - Date.now()) / (1000 * 3600 * 24) <= 60).length;

    return { deptStats, topItems, lowStock, expiringSoon, totalItems: items.length };
  }, [items, logs]);

  const handleAddItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: InventoryItem = {
      id: `ITEM-${Date.now()}`,
      name: formData.get('name') as string,
      category: formData.get('category') as string,
      itemType: (activeTab === 'inventory' ? 'CONSUMABLE' : 'EQUIPMENT') as ItemType,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
      purchaseDate: formData.get('purchaseDate') as string || undefined,
      expiryDate: formData.get('expiryDate') as string || undefined,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    };
    setItems([...items, newItem]);
    setShowAddModal(false);
  };

  const handleEditItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editTarget) return;
    const formData = new FormData(e.currentTarget);
    setItems(items.map(i => i.id === editTarget.id ? {
      ...i,
      name: formData.get('name') as string,
      category: formData.get('category') as string,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      minStock: Number(formData.get('minStock')),
      purchaseDate: formData.get('purchaseDate') as string || undefined,
      expiryDate: formData.get('expiryDate') as string || undefined,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    } : i));
    setEditTarget(null);
  };

  const handleDelete = () => {
    if (!deleteTarget) return;
    setItems(items.filter(i => i.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  // 領用加入籃子校驗
  const addToBasket = () => {
    const target = items.find(i => i.id === selectedItemId);
    if (!target) return;
    const qty = Number(inputQty);
    if (qty <= 0) return;

    // 計算籃內已有的數量
    const alreadyInBasket = basket.filter(b => b.itemId === target.id).reduce((sum, b) => sum + b.quantity, 0);
    const available = target.quantity - alreadyInBasket;

    if (issuanceMode === 'OUT' && available < qty) {
      alert(`庫存不足！該品項目前僅剩餘 ${available} ${target.unit} 可供領用。`);
      return;
    }

    setBasket([...basket, { itemId: target.id, name: target.name, quantity: qty, unit: target.unit }]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const ts = Date.now();
    const batchId = `DOC-${ts.toString().slice(-6)}`;
    let nextItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(b => {
      nextItems = nextItems.map(item => {
        if (item.id === b.itemId) {
          const nQty = issuanceMode === 'OUT' ? item.quantity - b.quantity : item.quantity + b.quantity;
          return { ...item, quantity: nQty, lastUpdated: ts };
        }
        return item;
      });
      newLogs.push({
        id: `TX-${ts}-${b.itemId}`,
        itemId: b.itemId,
        itemName: b.name,
        type: issuanceMode,
        quantity: b.quantity,
        person: inputPerson || '系統經辦',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: inputReason,
        timestamp: ts,
        batchId: batchId,
        items: [...basket]
      });
    });

    setItems(nextItems);
    setLogs([...newLogs, ...logs]);

    if (issuanceMode === 'OUT') {
      setPrintBatch({
        id: batchId,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: ts
      });
      setShowPrintModal(true);
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  // 補印功能
  const reprint = (log: Transaction) => {
    if (log.type !== 'OUT') return;
    // Fix: Explicitly cast log.items to BasketItem[] as they are now compatible following types.ts update.
    setPrintBatch({
      id: log.batchId || 'N/A',
      dept: log.dept,
      person: log.person,
      reason: log.reason,
      items: (log.items as BasketItem[]) || [{ itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '個' }],
      timestamp: log.timestamp
    });
    setShowPrintModal(true);
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    try {
      const result = await getInventoryInsights(items);
      setAiInsights(result);
    } catch (error) {
      setAiInsights("AI 助理暫時無法提供建議。");
    } finally {
      setIsAiLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900">
      {/* 側邊導覽 */}
      <aside className="w-64 bg-slate-900 text-white flex flex-col no-print shrink-0 shadow-2xl">
        <div className="p-6">
          <div className="flex items-center gap-3 mb-10">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center">
              <Package size={24} />
            </div>
            <span className="text-lg font-black tracking-tighter uppercase">SAFETY PRO</span>
          </div>
          <nav className="space-y-1">
            {[
              { id: 'inventory', label: '工安耗材管理', icon: Package },
              { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
              { id: 'issuance', label: '領用/補貨作業', icon: ShoppingCart },
              { id: 'history', label: '異動日誌審核', icon: History },
              { id: 'dashboard', label: '管理分析看板', icon: LayoutDashboard },
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${
                  activeTab === tab.id ? 'bg-blue-600 text-white shadow-xl' : 'text-slate-400 hover:bg-slate-800'
                }`}
              >
                <tab.icon size={18} /> {tab.label}
              </button>
            ))}
          </nav>
        </div>
      </aside>

      <main className="flex-1 p-8 overflow-y-auto no-print">
        <div className="max-w-6xl mx-auto">
          <header className="flex justify-between items-end mb-8 border-b-2 border-slate-200 pb-6">
            <div>
              <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-1">Repair Division South - Industrial Safety</p>
              <h2 className="text-3xl font-black text-slate-800 uppercase tracking-tight">
                {activeTab === 'inventory' ? '工安耗材及設備管理檔案' : 
                 activeTab === 'medicine' ? '急救藥材及藥品管理檔案' : 
                 activeTab === 'issuance' ? '庫存領用與補貨系統' : 
                 activeTab === 'history' ? '歷史異動日誌審閱' : '管理數據與統計分析'}
              </h2>
            </div>
            {(activeTab === 'inventory' || activeTab === 'medicine') && (
              <button onClick={() => setShowAddModal(true)} className="bg-slate-900 hover:bg-black text-white px-8 py-4 rounded-2xl font-black flex items-center gap-2 shadow-xl transition-all">
                <Plus size={22} /> 新增管理項目
              </button>
            )}
          </header>

          {/* 數據看板 (深度回歸) */}
          {activeTab === 'dashboard' && (
            <div className="space-y-10">
              <div className="grid grid-cols-4 gap-6">
                <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-1">在庫品項總數</p>
                  <p className="text-3xl font-black">{dashboardData.totalItems}</p>
                </div>
                <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                  <p className="text-[10px] font-black text-red-400 uppercase mb-1">庫存水位預警</p>
                  <p className="text-3xl font-black text-red-500">{dashboardData.lowStock}</p>
                </div>
                <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                  <p className="text-[10px] font-black text-orange-400 uppercase mb-1">藥材效期預警</p>
                  <p className="text-3xl font-black text-orange-500">{dashboardData.expiringSoon}</p>
                </div>
                <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                  <p className="text-[10px] font-black text-blue-400 uppercase mb-1">本月累計異動</p>
                  <p className="text-3xl font-black text-blue-600">{logs.length}</p>
                </div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* 部門消耗分析 */}
                <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm">
                  <h3 className="text-lg font-black mb-8 flex items-center gap-2 border-b pb-4"><PieChart className="text-blue-500"/> 各部門領用比例分析</h3>
                  <div className="space-y-6">
                    {Object.entries(dashboardData.deptStats).sort((a,b)=>b[1]-a[1]).map(([dept, val]) => (
                      <div key={dept} className="flex items-center gap-4">
                        <div className="w-24 text-xs font-black text-slate-500 uppercase">{dept}</div>
                        <div className="flex-1 h-2.5 bg-slate-100 rounded-full overflow-hidden">
                          <div className="h-full bg-blue-500 rounded-full transition-all duration-1000" style={{ width: `${Math.min(100, (val / (logs.length || 1)) * 50)}%` }}></div>
                        </div>
                        <div className="w-12 text-right text-sm font-black text-slate-800">{val}</div>
                      </div>
                    ))}
                  </div>
                </div>
                {/* 熱門領用品項 */}
                <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm">
                  <h3 className="text-lg font-black mb-8 flex items-center gap-2 border-b pb-4"><BarChart3 className="text-emerald-500"/> 重點消耗品項 Top 8</h3>
                  <div className="space-y-4">
                    {dashboardData.topItems.map(([name, val], idx) => (
                      <div key={name} className="flex justify-between items-center p-4 bg-slate-50 rounded-2xl hover:bg-emerald-50 transition-colors">
                        <div className="flex items-center gap-4">
                          <span className="w-6 h-6 bg-slate-900 text-white rounded-lg flex items-center justify-center text-[10px] font-black">{idx+1}</span>
                          <span className="font-bold text-slate-700">{name}</span>
                        </div>
                        <span className="font-black text-lg text-emerald-600">{val} <span className="text-[10px] text-slate-400">UNIT</span></span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>

              {/* AI 診斷 */}
              <div className="bg-slate-900 rounded-[3rem] p-12 text-white relative overflow-hidden shadow-2xl">
                <BrainCircuit className="absolute -right-10 -bottom-10 w-72 h-72 opacity-10 rotate-12" />
                <div className="relative z-10">
                  <h3 className="text-2xl font-black mb-6 flex items-center gap-3"><BrainCircuit className="text-blue-400" size={32}/> AI 智能管理建議系統</h3>
                  <div className="bg-slate-800/60 backdrop-blur-xl p-8 rounded-2xl border border-white/5 mb-8 text-lg font-medium leading-relaxed text-slate-200 min-h-[120px]">
                    {isAiLoading ? "正在分析資料庫..." : aiInsights || "點擊按鈕，由 AI 協助掃描庫存水位並生成管理對策。"}
                  </div>
                  <button onClick={fetchAiInsights} disabled={isAiLoading} className="bg-blue-600 hover:bg-blue-500 px-10 py-5 rounded-2xl font-black text-lg flex items-center gap-3 transition-all active:scale-95 shadow-lg">
                    <RefreshCw className={isAiLoading ? 'animate-spin' : ''} size={24}/> 啟動庫存診斷
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* 列表與其他功能 (回溯最簡潔版本) */}
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden">
               <div className="p-6 bg-slate-50 border-b flex justify-between items-center">
                  <div className="relative w-96">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18}/>
                    <input className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-slate-200 font-bold shadow-inner" placeholder="快速搜尋品項或類別..." value={searchTerm} onChange={e=>setSearchTerm(e.target.value)} />
                  </div>
               </div>
               <div className="overflow-x-auto">
                 <table className="w-full text-left">
                   <thead>
                      <tr className="bg-slate-100/50 border-b border-slate-200 text-[10px] font-black text-slate-500 uppercase tracking-widest">
                        <th className="px-8 py-5">品項細節與類別</th>
                        <th className="px-8 py-5">規格規格 / 單位</th>
                        <th className="px-8 py-5 text-center">當前庫存量</th>
                        {activeTab === 'medicine' && <th className="px-8 py-5">有效日期</th>}
                        <th className="px-8 py-5 text-right">操作項目</th>
                      </tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100">
                      {items.filter(i => (activeTab==='medicine' ? i.itemGroup==='MEDICINE' : i.itemGroup==='INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                        <tr key={item.id} className="hover:bg-blue-50/50 transition-colors group">
                          <td className="px-8 py-6">
                            <div className="font-black text-slate-800 text-lg">{item.name}</div>
                            <div className="inline-block bg-slate-900 text-white text-[9px] font-black px-2 py-0.5 rounded mt-1 uppercase tracking-wider">{item.category}</div>
                          </td>
                          <td className="px-8 py-6 font-bold text-slate-600">
                            {item.spec || '---'} <span className="text-slate-400 text-xs ml-1">/ {item.unit}</span>
                          </td>
                          <td className="px-8 py-6 text-center">
                            <span className={`inline-block px-6 py-2 rounded-2xl font-black text-xl ${item.quantity <= item.minStock ? 'bg-red-100 text-red-600 animate-pulse' : 'bg-blue-50 text-blue-700'}`}>
                              {item.quantity}
                            </span>
                          </td>
                          {activeTab === 'medicine' && (
                            <td className="px-8 py-6 font-black text-slate-700">
                              {item.expiryDate || '永久有效'}
                            </td>
                          )}
                          <td className="px-8 py-6 text-right">
                             <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button onClick={()=>setEditTarget(item)} className="p-3 hover:bg-white hover:shadow-lg rounded-xl text-blue-600"><Edit3 size={20}/></button>
                                <button onClick={()=>setDeleteTarget({id: item.id, name: item.name})} className="p-3 hover:bg-white hover:shadow-lg rounded-xl text-red-600"><Trash2 size={20}/></button>
                             </div>
                          </td>
                        </tr>
                      ))}
                   </tbody>
                 </table>
               </div>
            </div>
          )}

          {/* 領用作業 (強化檢查) */}
          {activeTab === 'issuance' && (
            <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
              <div className="lg:col-span-2 space-y-8">
                <div className="bg-white p-8 rounded-[2.5rem] shadow-2xl border border-slate-100">
                  <div className="flex bg-slate-100 p-1.5 rounded-2xl mb-8">
                    <button onClick={()=>setIssuanceMode('OUT')} className={`flex-1 py-4 rounded-xl font-black transition-all ${issuanceMode==='OUT' ? 'bg-white shadow-xl text-blue-600' : 'text-slate-400'}`}>領用出庫</button>
                    <button onClick={()=>setIssuanceMode('IN')} className={`flex-1 py-4 rounded-xl font-black transition-all ${issuanceMode==='IN' ? 'bg-white shadow-xl text-emerald-600' : 'text-slate-400'}`}>補貨入庫</button>
                  </div>
                  <div className="space-y-6">
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ml-1">選擇品項 (顯示可用庫存)</label>
                      <select className="w-full p-4 rounded-2xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold shadow-inner" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                        <option value="">請點擊選取...</option>
                        {items.map(i => <option key={i.id} value={i.id}>{i.name} (庫存: {i.quantity} {i.unit})</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ml-1">數量</label>
                      <input type="number" className="w-full p-4 rounded-2xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-black text-2xl shadow-inner" value={inputQty} onChange={e=>setInputQty(e.target.value)} />
                    </div>
                    <button onClick={addToBasket} disabled={!selectedItemId} className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black text-lg hover:bg-black shadow-xl active:scale-95 transition-all">加入待處理清單</button>
                  </div>
                </div>
              </div>
              <div className="lg:col-span-3 flex flex-col">
                <div className="bg-white p-10 rounded-[3rem] shadow-2xl border border-slate-100 flex-1 flex flex-col">
                  <h3 className="font-black text-2xl mb-8 flex items-center gap-3"><ClipboardList className="text-blue-500" size={30}/> 待處理籃子 ({basket.length})</h3>
                  <div className="bg-slate-50 rounded-[2rem] p-6 flex-1 mb-8 overflow-y-auto space-y-4 min-h-[350px] border-2 border-dashed border-slate-200">
                    {basket.length === 0 ? (
                      <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-20">
                        <ShoppingCart size={80} strokeWidth={1}/>
                        <p className="font-black text-xl">清單內尚無項目</p>
                      </div>
                    ) : (
                      basket.map((b, idx) => (
                        <div key={idx} className="flex justify-between items-center p-5 bg-white rounded-2xl shadow-sm border border-slate-100">
                          <span className="font-black text-slate-800 text-lg">{b.name}</span>
                          <div className="flex items-center gap-8">
                            <span className="font-black text-blue-600 text-2xl">{b.quantity} <span className="text-xs text-slate-400">{b.unit}</span></span>
                            <button onClick={()=>setBasket(prev=>prev.filter((_,i)=>i!==idx))} className="text-slate-200 hover:text-red-500"><X size={24}/></button>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                  {issuanceMode === 'OUT' && (
                    <div className="grid grid-cols-2 gap-4 mb-4">
                      <select className="p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>
                        {DEPARTMENTS.map(d=><option key={d}>{d}</option>)}
                      </select>
                      <input className="p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold" placeholder="領用人姓名" value={inputPerson} onChange={e=>setInputPerson(e.target.value)} />
                    </div>
                  )}
                  <input className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold mb-6" placeholder="用途或備註說明" value={inputReason} onChange={e=>setInputReason(e.target.value)} />
                  <button onClick={processIssuance} disabled={basket.length===0} className={`w-full py-7 rounded-3xl font-black text-2xl text-white shadow-2xl active:scale-95 transition-all ${issuanceMode==='OUT' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-emerald-600 hover:bg-emerald-700'}`}>
                    {issuanceMode==='OUT' ? '確認領用並列印 A4 單據' : '執行補貨入庫'}
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* 歷史異動與補印 */}
          {activeTab === 'history' && (
            <div className="bg-white rounded-3xl border border-slate-200 shadow-xl overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead className="bg-slate-900 text-white text-[10px] font-black uppercase tracking-widest">
                    <tr>
                      <th className="px-8 py-5">時間</th>
                      <th className="px-8 py-5">作業類型</th>
                      <th className="px-8 py-5">品項/部門</th>
                      <th className="px-8 py-5 text-center">數量</th>
                      <th className="px-8 py-5 text-right">單據</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {logs.map(log => (
                      <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-8 py-5 text-xs font-bold text-slate-500">{new Date(log.timestamp).toLocaleString()}</td>
                        <td className="px-8 py-5">
                          <span className={`px-4 py-1 rounded-full text-[10px] font-black ${log.type === 'IN' ? 'bg-emerald-100 text-emerald-700' : 'bg-blue-100 text-blue-700'}`}>
                            {log.type === 'IN' ? '補貨入庫' : '領用出庫'}
                          </span>
                        </td>
                        <td className="px-8 py-5">
                          <div className="font-black text-slate-800">{log.itemName}</div>
                          <div className="text-[10px] text-slate-400 font-black uppercase">{log.dept} / {log.person}</div>
                        </td>
                        <td className="px-8 py-5 text-center font-black text-xl">{log.quantity}</td>
                        <td className="px-8 py-5 text-right">
                          {log.type === 'OUT' && (
                            <button onClick={()=>reprint(log)} className="text-blue-600 hover:underline flex items-center gap-1 font-black text-xs ml-auto">
                              <Printer size={14}/> 補印領用單
                            </button>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      </main>

      {/* 新增/編輯 Modal (高度優化) */}
      {(showAddModal || editTarget) && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-xl z-[1000] flex items-center justify-center p-4">
           <form onSubmit={editTarget ? handleEditItem : handleAddItem} className="bg-white rounded-[2.5rem] w-full max-w-2xl overflow-hidden shadow-2xl">
              <div className="p-10">
                <div className="flex justify-between items-center mb-8">
                   <h3 className="text-2xl font-black text-slate-900">{editTarget ? `編輯管理資料` : '新增管理品項'}</h3>
                   <button type="button" onClick={()=>{setShowAddModal(false); setEditTarget(null);}} className="p-2 hover:bg-slate-100 rounded-xl"><X size={24}/></button>
                </div>
                <div className="grid grid-cols-2 gap-6 mb-10">
                  <div className="col-span-2 space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase ml-1">品項名稱 (必填)</label>
                    <input name="name" required defaultValue={editTarget?.name} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-black text-lg shadow-inner" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase ml-1">規格/單位</label>
                    <div className="flex gap-2">
                      <input name="spec" defaultValue={editTarget?.spec} className="flex-1 p-4 rounded-xl bg-slate-50 border border-slate-200 font-bold" placeholder="規格" />
                      <input name="unit" required defaultValue={editTarget?.unit || '個'} className="w-20 p-4 rounded-xl bg-slate-50 border border-slate-200 font-bold" placeholder="單位" />
                    </div>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase ml-1">固定分類</label>
                    <select name="category" defaultValue={editTarget?.category} className="w-full p-4 rounded-xl bg-slate-50 border border-slate-200 font-bold">
                      {activeTab === 'inventory' ? (
                        <>
                          <option value="安全衛生設備">安全衛生設備</option>
                          <option value="安全衛生類消耗品">安全衛生類消耗品</option>
                        </>
                      ) : (
                        <option value="急救藥材/藥品">急救藥材/藥品</option>
                      )}
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase ml-1">庫存設定</label>
                    <div className="flex gap-2">
                      {!editTarget && <input name="quantity" type="number" required defaultValue="0" className="flex-1 p-4 rounded-xl bg-slate-50 border border-slate-200 font-black" placeholder="初始數量" />}
                      <input name="minStock" type="number" required defaultValue={editTarget?.minStock || 5} className="flex-1 p-4 rounded-xl bg-slate-50 border border-slate-200 font-black text-red-600" placeholder="警示水位" />
                    </div>
                  </div>
                  {/* 僅藥材分頁顯示日期 */}
                  {activeTab === 'medicine' && (
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-red-400 uppercase ml-1 tracking-widest">有效日期 (到期日)</label>
                      <input name="expiryDate" type="date" required defaultValue={editTarget?.expiryDate} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-slate-200 font-black text-blue-600" style={{ colorScheme: 'light' }} />
                    </div>
                  )}
                  <div className="col-span-2 space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase ml-1">備註/用途說明</label>
                    <textarea name="description" defaultValue={editTarget?.description} className="w-full p-4 rounded-xl bg-slate-50 border border-slate-200 font-bold h-20 shadow-inner" />
                  </div>
                </div>
                <div className="flex gap-4">
                   <button type="submit" className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-2xl hover:bg-blue-700 active:scale-95 transition-all">儲存並入庫</button>
                   <button type="button" onClick={()=>{setShowAddModal(false); setEditTarget(null);}} className="px-10 py-5 bg-slate-100 rounded-2xl font-black text-slate-500 hover:bg-slate-200">取消</button>
                </div>
              </div>
           </form>
        </div>
      )}

      {/* 列印單據 (A4 正式格式) */}
      {showPrintModal && printBatch && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-2xl z-[2000] flex items-center justify-center p-6 no-print overflow-y-auto">
          <div className="bg-white rounded-[3rem] w-full max-w-4xl max-h-[95vh] flex flex-col shadow-2xl overflow-hidden">
            <div className="p-8 border-b flex justify-between items-center bg-slate-50">
               <h3 className="font-black text-xl flex items-center gap-3"><Printer className="text-blue-600"/> 領用單據正式預覽</h3>
               <div className="flex gap-4">
                  <button onClick={()=>window.print()} className="px-10 py-4 bg-blue-600 text-white rounded-2xl font-black shadow-xl hover:bg-blue-700 transition-all">確認列印</button>
                  <button onClick={()=>setShowPrintModal(false)} className="px-10 py-4 bg-slate-200 text-slate-700 rounded-2xl font-black transition-colors">關閉視窗</button>
               </div>
            </div>
            <div className="flex-1 p-12 bg-slate-200 flex justify-center overflow-y-auto">
               <div className="bg-white p-16 shadow-sm border border-slate-300 print-container" style={{ width: '210mm', minHeight: '297mm' }}>
                  <div className="border-[6px] border-slate-900 p-10 h-full flex flex-col relative">
                    <header className="flex justify-between items-start border-b-[4px] border-slate-900 pb-8 mb-10">
                      <div>
                        <div className="bg-slate-900 text-white px-4 py-1 inline-block text-[10px] font-black uppercase tracking-widest mb-4">INTERNAL DOCUMENT - SOUTH DIVISION</div>
                        <h1 className="text-5xl font-black tracking-tighter mb-2">工安耗材領用單</h1>
                        <p className="text-slate-500 font-bold uppercase text-sm tracking-widest">Industrial Safety Equipment Issuance Form</p>
                      </div>
                      <div className="text-right">
                        <p className="text-[10px] font-black text-slate-400 uppercase mb-1">SERIAL NUMBER</p>
                        <p className="text-3xl font-black">{printBatch.id}</p>
                        <p className="text-slate-500 font-bold mt-4">日期: {new Date(printBatch.timestamp).toLocaleDateString()}</p>
                      </div>
                    </header>
                    <div className="grid grid-cols-2 gap-12 mb-12">
                      <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">領用單位</p><p className="text-2xl font-black border-b-4 border-slate-100 pb-2">{printBatch.dept}</p></div>
                      <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">申請領用人</p><p className="text-2xl font-black border-b-4 border-slate-100 pb-2">{printBatch.person || '---'}</p></div>
                      <div className="col-span-2"><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">用途說明</p><p className="text-xl font-bold border-b-4 border-slate-100 pb-2">{printBatch.reason || '一般巡檢更換用'}</p></div>
                    </div>
                    <div className="flex-1">
                      <table className="w-full">
                        <thead className="border-b-4 border-slate-900">
                          <tr className="text-left">
                            <th className="py-4 font-black text-sm uppercase">品項名稱及規格</th>
                            <th className="py-4 text-center font-black text-sm uppercase" style={{ width: '120px' }}>數量</th>
                            <th className="py-4 text-right font-black text-sm uppercase" style={{ width: '100px' }}>單位</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y-2 divide-slate-100">
                          {printBatch.items.map((item, idx) => (
                            <tr key={idx}>
                              <td className="py-6 font-black text-2xl text-slate-900">{item.name}</td>
                              <td className="py-6 text-center font-black text-4xl text-blue-600">{item.quantity}</td>
                              <td className="py-6 text-right font-black text-xl text-slate-600">{item.unit}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                    <div className="mt-auto grid grid-cols-3 gap-12 pt-16 border-t-[4px] border-slate-900 text-center">
                       <div className="pt-4 border-t-2 border-slate-200"><p className="text-[10px] font-black uppercase">申請人簽章</p></div>
                       <div className="pt-4 border-t-2 border-slate-200"><p className="text-[10px] font-black uppercase">主管核示</p></div>
                       <div className="pt-4 border-t-2 border-slate-200"><p className="text-[10px] font-black uppercase">發放人經辦</p></div>
                    </div>
                    <footer className="mt-12 text-[8px] text-slate-300 font-bold text-center uppercase tracking-[0.4em]">Safety Pro Ultimate Final System - Repair South</footer>
                  </div>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* 刪除確認 (最簡潔版) */}
      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm z-[2000] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2rem] p-8 max-w-sm w-full text-center shadow-2xl">
             <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-6"><AlertTriangle size={32}/></div>
             <h3 className="text-2xl font-black mb-2">確定刪除？</h3>
             <p className="text-slate-500 font-bold mb-8">"{deleteTarget.name}" 將被永久移除且無法還原。</p>
             <div className="flex flex-col gap-3">
                <button onClick={handleDelete} className="w-full py-4 bg-red-600 text-white rounded-xl font-black text-lg shadow-xl">確認永久刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="w-full py-4 bg-slate-100 rounded-xl font-black text-slate-500">取消</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  Settings,
  ClipboardList,
  Save,
  PieChart,
  BarChart3,
  CheckCircle2,
  RefreshCw
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  // Modals
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);

  // Form States
  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  // AI & Print Data
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [printBatch, setPrintBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) try { setItems(JSON.parse(savedItems)); } catch(e) {}
    if (savedLogs) try { setLogs(JSON.parse(savedLogs)); } catch(e) {}
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  // 看板深度數據分析 (含細項分析)
  const dashboardData = useMemo(() => {
    const deptStats: Record<string, number> = {};
    const itemStats: Record<string, number> = {};
    DEPARTMENTS.forEach(d => deptStats[d] = 0);

    logs.filter(l => l.type === 'OUT').forEach(log => {
      deptStats[log.dept] = (deptStats[log.dept] || 0) + log.quantity;
      itemStats[log.itemName] = (itemStats[log.itemName] || 0) + log.quantity;
    });

    const topItems = Object.entries(itemStats)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10);

    const lowStock = items.filter(i => i.quantity <= i.minStock).length;
    const expiringSoon = items.filter(i => i.itemGroup === 'MEDICINE' && i.expiryDate && (new Date(i.expiryDate).getTime() - Date.now()) / (1000 * 3600 * 24) <= 60).length;

    return { deptStats, topItems, lowStock, expiringSoon, totalItems: items.length };
  }, [items, logs]);

  const handleAddItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: InventoryItem = {
      id: `ITEM-${Date.now()}`,
      name: formData.get('name') as string,
      category: formData.get('category') as string,
      itemType: (activeTab === 'inventory' ? 'CONSUMABLE' : 'EQUIPMENT') as ItemType,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
      purchaseDate: formData.get('purchaseDate') as string || undefined,
      expiryDate: formData.get('expiryDate') as string || undefined,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    };
    setItems([...items, newItem]);
    setShowAddModal(false);
  };

  const handleEditItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editTarget) return;
    const formData = new FormData(e.currentTarget);
    setItems(items.map(i => i.id === editTarget.id ? {
      ...i,
      name: formData.get('name') as string,
      category: formData.get('category') as string,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      minStock: Number(formData.get('minStock')),
      purchaseDate: formData.get('purchaseDate') as string || undefined,
      expiryDate: formData.get('expiryDate') as string || undefined,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    } : i));
    setEditTarget(null);
  };

  const handleDelete = () => {
    if (!deleteTarget) return;
    setItems(items.filter(i => i.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  // 領用加入籃子校驗 (預扣與阻斷)
  const addToBasket = () => {
    const target = items.find(i => i.id === selectedItemId);
    if (!target) return;
    const qty = Number(inputQty);
    if (qty <= 0) return;

    // 計算當前籃子裡該品項已佔用的數量
    const alreadyInBasket = basket
      .filter(b => b.itemId === target.id)
      .reduce((sum, b) => sum + b.quantity, 0);

    const available = target.quantity - alreadyInBasket;

    if (issuanceMode === 'OUT' && available < qty) {
      alert(`庫存量不足！該品項目前僅剩餘 ${available} ${target.unit} 可供分配。`);
      return;
    }

    setBasket([...basket, { itemId: target.id, name: target.name, quantity: qty, unit: target.unit }]);
    setSelectedItemId(''); 
    setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const ts = Date.now();
    const batchId = `DOC-${ts.toString().slice(-6)}`;
    let nextItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(b => {
      nextItems = nextItems.map(item => {
        if (item.id === b.itemId) {
          const nQty = issuanceMode === 'OUT' ? item.quantity - b.quantity : item.quantity + b.quantity;
          return { ...item, quantity: nQty, lastUpdated: ts };
        }
        return item;
      });
      newLogs.push({
        id: `TX-${ts}-${b.itemId}`,
        itemId: b.itemId,
        itemName: b.name,
        type: issuanceMode,
        quantity: b.quantity,
        person: inputPerson || '系統經辦',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處倉庫',
        reason: inputReason,
        timestamp: ts,
        batchId: batchId,
        items: [...basket] // 保存整批項目用於補印
      });
    });

    setItems(nextItems);
    setLogs([...newLogs, ...logs]);

    if (issuanceMode === 'OUT') {
      setPrintBatch({
        id: batchId,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: ts
      });
      setShowPrintModal(true);
    }
    setBasket([]); 
    setInputPerson(''); 
    setInputReason('');
  };

  const reprintBatch = (log: Transaction) => {
    if (!log.items || log.type !== 'OUT') return;
    setPrintBatch({
      id: log.batchId || 'N/A',
      dept: log.dept,
      person: log.person,
      reason: log.reason,
      items: log.items as BasketItem[],
      timestamp: log.timestamp
    });
    setShowPrintModal(true);
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    try {
      const result = await getInventoryInsights(items);
      setAiInsights(result);
    } catch (error) {
      setAiInsights("AI 助理暫時無法提供建議。");
    } finally {
      setIsAiLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900">
      {/* 側邊導覽 */}
      <aside className="w-64 bg-slate-900 text-white flex flex-col no-print shrink-0 shadow-2xl">
        <div className="p-6">
          <div className="flex items-center gap-3 mb-10">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center">
              <Package size={24} />
            </div>
            <span className="text-lg font-black tracking-tighter uppercase">SAFETY PRO</span>
          </div>
          <nav className="space-y-1">
            {[
              { id: 'inventory', label: '工安耗材管理', icon: Package },
              { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
              { id: 'issuance', label: '領用/補貨作業', icon: ShoppingCart },
              { id: 'history', label: '異動日誌審核', icon: History },
              { id: 'dashboard', label: '管理分析看板', icon: LayoutDashboard },
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${
                  activeTab === tab.id ? 'bg-blue-600 text-white shadow-xl' : 'text-slate-400 hover:bg-slate-800'
                }`}
              >
                <tab.icon size={18} /> {tab.label}
              </button>
            ))}
          </nav>
        </div>
      </aside>

      <main className="flex-1 p-8 overflow-y-auto no-print">
        <div className="max-w-6xl mx-auto">
          <header className="flex justify-between items-end mb-8 border-b-2 border-slate-200 pb-6">
            <div>
              <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-1">Repair Division South - Industrial Safety</p>
              <h2 className="text-3xl font-black text-slate-800 uppercase tracking-tight">
                {activeTab === 'inventory' ? '工安耗材及設備管理檔案' : 
                 activeTab === 'medicine' ? '急救藥材及藥品管理檔案' : 
                 activeTab === 'issuance' ? '庫存領用與補貨系統' : 
                 activeTab === 'history' ? '歷史異動日誌審閱' : '管理數據與統計分析'}
              </h2>
            </div>
            {(activeTab === 'inventory' || activeTab === 'medicine') && (
              <button onClick={() => setShowAddModal(true)} className="bg-slate-900 hover:bg-black text-white px-8 py-4 rounded-2xl font-black flex items-center gap-2 shadow-xl transition-all active:scale-95">
                <Plus size={22} /> 新增管理項目
              </button>
            )}
          </header>

          {/* 數據看板 */}
          {activeTab === 'dashboard' && (
            <div className="space-y-10">
              <div className="grid grid-cols-4 gap-6">
                <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
