             <div className="w-20 h-20 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-6"><AlertTriangle size={40}/></div>
             <h3 className="text-2xl font-black mb-2 text-slate-800">確定刪除此項？</h3>
             <p className="text-slate-500 font-bold mb-8">"{deleteTarget.name}" 將被永久移除且無法還原。</p>
             <div className="flex flex-col gap-3">
                <button onClick={handleDelete} className="w-full py-4 bg-red-600 text-white rounded-xl font-black text-lg shadow-xl active:scale-95 transition-all">確認永久刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="w-full py-4 bg-slate-100 rounded-xl font-black text-slate-500">取消</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  Settings,
  ClipboardList,
  Save,
  PieChart,
  BarChart3,
  CheckCircle2,
  RefreshCw,
  Filter
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  // Modals
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);

  // Form States
  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  // Dashboard States
  const [dashDeptFilter, setDashDeptFilter] = useState<string>('全部部門');

  // AI & Print Data
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [printBatch, setPrintBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) try { setItems(JSON.parse(savedItems)); } catch(e) {}
    if (savedLogs) try { setLogs(JSON.parse(savedLogs)); } catch(e) {}
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  // 看板深度數據分析 (新增部門篩選邏輯)
  const dashboardData = useMemo(() => {
    const deptStats: Record<string, number> = {};
    const itemStats: Record<string, number> = {};
    DEPARTMENTS.forEach(d => deptStats[d] = 0);

    const filteredLogs = dashDeptFilter === '全部部門' 
      ? logs 
      : logs.filter(l => l.dept === dashDeptFilter);

    filteredLogs.filter(l => l.type === 'OUT').forEach(log => {
      deptStats[log.dept] = (deptStats[log.dept] || 0) + log.quantity;
      itemStats[log.itemName] = (itemStats[log.itemName] || 0) + log.quantity;
    });

    const topItems = Object.entries(itemStats)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10);

    const lowStock = items.filter(i => i.quantity <= i.minStock).length;
    const expiringSoon = items.filter(i => i.itemGroup === 'MEDICINE' && i.expiryDate && (new Date(i.expiryDate).getTime() - Date.now()) / (1000 * 3600 * 24) <= 60).length;

    return { deptStats, topItems, lowStock, expiringSoon, totalItems: items.length };
  }, [items, logs, dashDeptFilter]);

  const handleAddItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: InventoryItem = {
      id: `ITEM-${Date.now()}`,
      name: formData.get('name') as string,
      category: formData.get('category') as string,
      itemType: (activeTab === 'inventory' ? 'CONSUMABLE' : 'EQUIPMENT') as ItemType,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
      purchaseDate: formData.get('purchaseDate') as string || undefined,
      expiryDate: formData.get('expiryDate') as string || undefined,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    };
    setItems([...items, newItem]);
    setShowAddModal(false);
  };

  const handleEditItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editTarget) return;
    const formData = new FormData(e.currentTarget);
    setItems(items.map(i => i.id === editTarget.id ? {
      ...i,
      name: formData.get('name') as string,
      category: formData.get('category') as string,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      minStock: Number(formData.get('minStock')),
      purchaseDate: formData.get('purchaseDate') as string || undefined,
      expiryDate: formData.get('expiryDate') as string || undefined,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    } : i));
    setEditTarget(null);
  };

  const handleDelete = () => {
    if (!deleteTarget) return;
    setItems(items.filter(i => i.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  // 領用加入籃子校驗 (庫存鎖定)
  const addToBasket = () => {
    const target = items.find(i => i.id === selectedItemId);
    if (!target) return;
    const qty = Number(inputQty);
    if (qty <= 0) return;

    const alreadyInBasket = basket
      .filter(b => b.itemId === target.id)
      .reduce((sum, b) => sum + b.quantity, 0);

    const available = target.quantity - alreadyInBasket;

    if (issuanceMode === 'OUT' && available < qty) {
      alert(`庫存量不足！該品項目前僅剩餘 ${available} ${target.unit} 可供分配。請檢查清單中是否已加入過該品項。`);
      return;
    }

    setBasket([...basket, { itemId: target.id, name: target.name, quantity: qty, unit: target.unit }]);
    setSelectedItemId(''); 
    setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const ts = Date.now();
    const batchId = `DOC-${ts.toString().slice(-6)}`;
    let nextItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(b => {
      nextItems = nextItems.map(item => {
        if (item.id === b.itemId) {
          const nQty = issuanceMode === 'OUT' ? item.quantity - b.quantity : item.quantity + b.quantity;
          return { ...item, quantity: nQty, lastUpdated: ts };
        }
        return item;
      });
      newLogs.push({
        id: `TX-${ts}-${b.itemId}`,
        itemId: b.itemId,
        itemName: b.name,
        type: issuanceMode,
        quantity: b.quantity,
        person: inputPerson || '庫房管理員',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: inputReason,
        timestamp: ts,
        batchId: batchId,
        items: [...basket]
      });
    });

    setItems(nextItems);
    setLogs([...newLogs, ...logs]);

    if (issuanceMode === 'OUT') {
      setPrintBatch({
        id: batchId,
        dept: selectedDept,
        person: inputPerson,
        reason: inputReason,
        items: [...basket],
        timestamp: ts
      });
      setShowPrintModal(true);
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  const reprintBatch = (log: Transaction) => {
    if (!log.items || log.type !== 'OUT') return;
    setPrintBatch({
      id: log.batchId || 'N/A',
      dept: log.dept,
      person: log.person,
      reason: log.reason,
      items: log.items as BasketItem[],
      timestamp: log.timestamp
    });
    setShowPrintModal(true);
  };

  const fetchAiInsights = async () => {
    setIsAiLoading(true);
    try {
      const result = await getInventoryInsights(items);
      setAiInsights(result);
    } catch (error) {
      setAiInsights("AI 助理暫時無法提供建議。");
    } finally {
      setIsAiLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900">
      {/* 側邊導覽 */}
      <aside className="w-64 bg-slate-900 text-white flex flex-col no-print shrink-0 shadow-2xl">
        <div className="p-6">
          <div className="flex items-center gap-3 mb-10">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center">
              <Package size={24} />
            </div>
            <span className="text-lg font-black tracking-tighter uppercase">SAFETY PRO</span>
          </div>
          <nav className="space-y-1">
            {[
              { id: 'inventory', label: '工安耗材管理', icon: Package },
              { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
              { id: 'issuance', label: '領用/補貨作業', icon: ShoppingCart },
              { id: 'history', label: '異動日誌審核', icon: History },
              { id: 'dashboard', label: '管理分析看板', icon: LayoutDashboard },
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${
                  activeTab === tab.id ? 'bg-blue-600 text-white shadow-xl' : 'text-slate-400 hover:bg-slate-800'
                }`}
              >
                <tab.icon size={18} /> {tab.label}
              </button>
            ))}
          </nav>
        </div>
      </aside>

      <main className="flex-1 p-8 overflow-y-auto no-print">
        <div className="max-w-6xl mx-auto">
          <header className="flex justify-between items-end mb-8 border-b-2 border-slate-200 pb-6">
            <div>
              <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-1">Repair Division South - Industrial Safety</p>
              <h2 className="text-3xl font-black text-slate-800 uppercase tracking-tight">
                {activeTab === 'inventory' ? '工安耗材及設備管理檔案' : 
                 activeTab === 'medicine' ? '急救藥材及藥品管理檔案' : 
                 activeTab === 'issuance' ? '庫存領用與補貨系統' : 
                 activeTab === 'history' ? '歷史異動日誌審閱' : '管理數據與統計分析'}
              </h2>
            </div>
            {(activeTab === 'inventory' || activeTab === 'medicine') && (
              <button onClick={() => setShowAddModal(true)} className="bg-slate-900 hover:bg-black text-white px-8 py-4 rounded-2xl font-black flex items-center gap-2 shadow-xl transition-all active:scale-95">
                <Plus size={22} /> 新增管理項目
              </button>
            )}
          </header>

          {/* 數據看板 (恢復部門細查功能) */}
          {activeTab === 'dashboard' && (
            <div className="space-y-10">
              <div className="flex justify-between items-center mb-6">
                <div className="flex items-center gap-4 bg-white p-2 rounded-2xl shadow-sm border border-slate-200">
                  <div className="bg-slate-900 text-white p-2 rounded-xl"><Filter size={18}/></div>
                  <select 
                    className="font-black text-sm outline-none px-2 pr-8"
                    value={dashDeptFilter}
                    onChange={(e) => setDashDeptFilter(e.target.value)}
                  >
                    <option>全部部門</option>
                    {DEPARTMENTS.map(d => <option key={d}>{d}</option>)}
                  </select>
                </div>
                <p className="text-xs font-bold text-slate-400">當前統計對象：<span className="text-blue-600">{dashDeptFilter}</span></p>
              </div>

              <div className="grid grid-cols-4 gap-6">
                <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-1">在庫品項總數</p>
                  <p className="text-3xl font-black">{dashboardData.totalItems}</p>
                </div>
                <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                  <p className="text-[10px] font-black text-red-400 uppercase mb-1">低水位警示</p>
                  <p className="text-3xl font-black text-red-500">{dashboardData.lowStock}</p>
                </div>
                <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                  <p className="text-[10px] font-black text-orange-400 uppercase mb-1">藥材效期預警</p>
                  <p className="text-3xl font-black text-orange-500">{dashboardData.expiringSoon}</p>
                </div>
                <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                  <p className="text-[10px] font-black text-blue-400 uppercase mb-1">篩選後異動數</p>
                  <p className="text-3xl font-black text-blue-600">{dashboardData.topItems.reduce((a,b)=>a+b[1], 0)}</p>
                </div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm">
                  <h3 className="text-lg font-black mb-8 flex items-center gap-2 border-b pb-4"><PieChart className="text-blue-500"/> 部門領用比例分析</h3>
                  <div className="space-y-6">
                    {Object.entries(dashboardData.deptStats).sort((a,b)=>b[1]-a[1]).map(([dept, val]) => (
                      <div key={dept} className="flex items-center gap-4">
                        <div className="w-24 text-xs font-black text-slate-500 uppercase">{dept}</div>
                        <div className="flex-1 h-2.5 bg-slate-100 rounded-full overflow-hidden">
                          <div className="h-full bg-blue-500 rounded-full transition-all duration-1000" style={{ width: `${Math.min(100, (val / (logs.length || 1)) * 100)}%` }}></div>
                        </div>
                        <div className="w-12 text-right text-sm font-black text-slate-800">{val}</div>
                      </div>
                    ))}
                  </div>
                </div>
                <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm">
                  <h3 className="text-lg font-black mb-8 flex items-center gap-2 border-b pb-4"><BarChart3 className="text-emerald-500"/> {dashDeptFilter} 消耗排行 Top 10</h3>
                  <div className="space-y-4">
                    {dashboardData.topItems.map(([name, val], idx) => (
                      <div key={name} className="flex justify-between items-center p-4 bg-slate-50 rounded-2xl">
                        <div className="flex items-center gap-4">
                          <span className="w-6 h-6 bg-slate-900 text-white rounded-lg flex items-center justify-center text-[10px] font-black">{idx+1}</span>
                          <span className="font-bold text-slate-700">{name}</span>
                        </div>
                        <span className="font-black text-lg text-emerald-600">{val}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* 列表與其他內容... (保持 V35 既有邏輯，僅優化顯示) */}
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden">
               <div className="p-6 bg-slate-50 border-b">
                  <div className="relative w-96">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18}/>
                    <input className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-slate-200 font-bold shadow-inner outline-none focus:ring-2 focus:ring-blue-500/20" placeholder="搜尋管理品項..." value={searchTerm} onChange={e=>setSearchTerm(e.target.value)} />
                  </div>
               </div>
               <div className="overflow-x-auto">
                 <table className="w-full text-left">
                   <thead>
                      <tr className="bg-slate-100/50 border-b border-slate-200 text-[10px] font-black text-slate-500 uppercase tracking-widest">
                        <th className="px-8 py-5">品項細節 / 分類</th>
                        <th className="px-8 py-5">規格與單位</th>
                        <th className="px-8 py-5 text-center">目前庫存</th>
                        {activeTab === 'medicine' && <th className="px-8 py-5">有效日期</th>}
                        <th className="px-8 py-5 text-right">操作</th>
                      </tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100">
                      {items.filter(i => (activeTab==='medicine' ? i.itemGroup==='MEDICINE' : i.itemGroup==='INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                        <tr key={item.id} className="hover:bg-blue-50/50 transition-colors group">
                          <td className="px-8 py-6">
                            <div className="font-black text-slate-800 text-lg">{item.name}</div>
                            <div className="text-[10px] font-black text-blue-500 mt-1 uppercase tracking-tight">{item.category}</div>
                          </td>
                          <td className="px-8 py-6 font-bold text-slate-600">{item.spec || '---'} / {item.unit}</td>
                          <td className="px-8 py-6 text-center">
                            <span className={`inline-block px-5 py-2 rounded-2xl font-black text-xl ${item.quantity <= item.minStock ? 'bg-red-100 text-red-600' : 'bg-blue-50 text-blue-700'}`}>
                              {item.quantity}
                            </span>
                          </td>
                          {activeTab === 'medicine' && <td className="px-8 py-6 font-black text-slate-700">{item.expiryDate || '未設定'}</td>}
                          <td className="px-8 py-6 text-right">
                             <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button onClick={()=>setEditTarget(item)} className="p-3 hover:bg-white hover:shadow-lg rounded-xl text-blue-600 transition-all"><Edit3 size={20}/></button>
                                <button onClick={()=>setDeleteTarget({id: item.id, name: item.name})} className="p-3 hover:bg-white hover:shadow-lg rounded-xl text-red-600 transition-all"><Trash2 size={20}/></button>
                             </div>
                          </td>
                        </tr>
                      ))}
                   </tbody>
                 </table>
               </div>
            </div>
          )}

          {/* 領用作業 (強化檢查) */}
          {activeTab === 'issuance' && (
            <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
              <div className="lg:col-span-2 space-y-8">
                <div className="bg-white p-8 rounded-[2.5rem] shadow-2xl border border-slate-100">
                  <div className="flex bg-slate-100 p-1.5 rounded-2xl mb-8">
                    <button onClick={()=>setIssuanceMode('OUT')} className={`flex-1 py-4 rounded-xl font-black transition-all ${issuanceMode==='OUT' ? 'bg-white shadow-xl text-blue-600' : 'text-slate-400'}`}>領用出庫</button>
                    <button onClick={()=>setIssuanceMode('IN')} className={`flex-1 py-4 rounded-xl font-black transition-all ${issuanceMode==='IN' ? 'bg-white shadow-xl text-emerald-600' : 'text-slate-400'}`}>補貨入庫</button>
                  </div>
                  <div className="space-y-6">
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ml-1">選擇品項 (顯示庫存量)</label>
                      <select className="w-full p-4 rounded-2xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-black shadow-inner" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                        <option value="">請點擊選取...</option>
                        {items.map(i => {
                          const inBasket = basket.filter(b => b.itemId === i.id).reduce((s,b)=>s+b.quantity, 0);
                          const available = i.quantity - inBasket;
                          return <option key={i.id} value={i.id} disabled={issuanceMode==='OUT' && available <= 0}>
                            {i.name} ({issuanceMode==='OUT' ? `可用: ${available}` : `在庫: ${i.quantity}`})
                          </option>
                        })}
                      </select>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ml-1">數量</label>
                      <input type="number" className="w-full p-4 rounded-2xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-black text-2xl shadow-inner" value={inputQty} onChange={e=>setInputQty(e.target.value)} />
                    </div>
                    <button 
                      onClick={addToBasket} 
                      disabled={!selectedItemId} 
                      className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black text-lg hover:bg-black shadow-xl active:scale-95 transition-all"
                    >
                      加入處理清單
                    </button>
                  </div>
                </div>
              </div>
              <div className="lg:col-span-3 flex flex-col">
                <div className="bg-white p-10 rounded-[3rem] shadow-2xl border border-slate-100 flex-1 flex flex-col">
                  <h3 className="font-black text-2xl mb-8 flex items-center gap-3"><ClipboardList className="text-blue-500" size={30}/> 待處理籃子 ({basket.length})</h3>
                  <div className="bg-slate-50 rounded-[2rem] p-6 flex-1 mb-8 overflow-y-auto space-y-4 min-h-[350px] border-2 border-dashed border-slate-200 custom-scrollbar">
                    {basket.length === 0 ? (
                      <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-20">
                        <ShoppingCart size={80} strokeWidth={1}/>
                        <p className="font-black text-xl">目前清單為空</p>
                      </div>
                    ) : (
                      basket.map((b, idx) => (
                        <div key={idx} className="flex justify-between items-center p-5 bg-white rounded-2xl shadow-sm border border-slate-100">
                          <span className="font-black text-slate-800 text-lg">{b.name}</span>
                          <div className="flex items-center gap-8">
