                    <div className="mt-20 grid grid-cols-3 gap-16 pt-24 border-t-[8px] border-black text-center">
                       <div className="pt-8 border-t-2 border-gray-200"><p className="text-[12px] font-black uppercase text-gray-400 tracking-widest mb-10">領用人簽名欄</p><div className="h-10"></div></div>
                       <div className="pt-8 border-t-2 border-gray-200"><p className="text-[12px] font-black uppercase text-gray-400 tracking-widest mb-10">組長/隊長核示</p><div className="h-10"></div></div>
                       <div className="pt-8 border-t-2 border-gray-200"><p className="text-[12px] font-black uppercase text-gray-400 tracking-widest mb-10">經辦人員發放</p><div className="h-10"></div></div>
