                  </div>

                  {/* 規格與單位：雙列 */}
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">規格說明</label>
                      <input name="spec" defaultValue={editTarget?.spec} className="w-full p-4 rounded-xl bg-slate-50 border border-slate-200 font-bold outline-none" placeholder="例: N95 / 20cm" />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">單位</label>
                      <input name="unit" required defaultValue={editTarget?.unit || '個'} className="w-full p-4 rounded-xl bg-slate-50 border border-slate-200 font-bold outline-none" placeholder="個/雙/組" />
                    </div>
                  </div>

                  {/* 庫存水位 */}
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">在庫數 / 警戒水位</label>
                      <div className="flex gap-2">
                        {!editTarget && <input name="quantity" type="number" required defaultValue="0" className="flex-1 p-4 rounded-xl bg-slate-50 border font-black outline-none" />}
                        <input name="minStock" type="number" required defaultValue={editTarget?.minStock || 5} className="flex-1 p-4 rounded-xl bg-slate-50 border font-black text-red-600 outline-none" />
                      </div>
                    </div>
                    {/* 藥材日期：即使在雙列中也增加高度確保內容不漂移 */}
                    {activeTab === 'medicine' && (
                      <div className="space-y-1.5">
                        <label className="text-[10px] font-black text-red-500 uppercase tracking-widest">有效截止日期</label>
                        <input name="expiryDate" type="date" required defaultValue={editTarget?.expiryDate} className="w-full p-4 rounded-xl bg-blue-50 border-2 border-blue-200 font-black text-blue-700 outline-none h-[58px]" style={{ colorScheme: 'light' }} />
                      </div>
                    )}
