                       <div className="pt-10 border-t-4 border-gray-300 flex flex-col items-center justify-between min-h-[160px]"><p className="text-[15px] font-black uppercase text-gray-400 tracking-[0.4em]">領用申請</p><div className="mb-4 text-gray-200"> (簽章) </div></div>
                       <div className="pt-10 border-t-4 border-gray-300 flex flex-col items-center justify-between min-h-[160px]"><p className="text-[15px] font-black uppercase text-gray-400 tracking-[0.4em]">單位主管</p><div className="mb-4 text-gray-200"> (核章) </div></div>
                       <div className="pt-10 border-t-4 border-gray-300 flex flex-col items-center justify-between min-h-[160px]"><p className="text-[15px] font-black uppercase text-gray-400 tracking-[0.4em]">庫房發放</p><div className="mb-4 text-gray-200"> (蓋章) </div></div>
                    </div>

                    <footer className="mt-auto text-[11px] text-gray-300 font-black text-center uppercase tracking-[1.2em] pt-10 border-t-2 border-gray-50">SAFETY PRO ULTIMATE - SYSTEM RECORD V35</footer>
                  </div>
               </div>
            </div>
          </div>
        </div>
      )}

      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm z-[3000] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2rem] p-8 max-w-sm w-full text-center shadow-2xl animate-in zoom-in-95">
             <div className="w-20 h-20 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-6"><AlertTriangle size={40}/></div>
             <h3 className="text-2xl font-black mb-2 text-slate-800">確定刪除？</h3>
             <p className="text-slate-500 font-bold mb-8">"{deleteTarget.name}" 將永久移除。</p>
             <div className="flex flex-col gap-3">
                <button onClick={handleDelete} className="w-full py-4 bg-red-600 text-white rounded-xl font-black shadow-lg">確認永久刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="w-full py-4 bg-slate-100 rounded-xl font-black text-slate-500">取消</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  Stethoscope,
  ShoppingCart,
  ClipboardList,
  PieChart,
  BarChart3,
  Filter
} from 'lucide-react';
import { InventoryItem, Transaction, TransactionType, ItemType } from './types';

const STORAGE_KEY_ITEMS = 'safeman_v35_ultimate_items';
const STORAGE_KEY_LOGS = 'safeman_v35_ultimate_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  const [dashDeptFilter, setDashDeptFilter] = useState<string>('全部部門');

  const [printBatch, setPrintBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) try { setItems(JSON.parse(savedItems)); } catch(e) {}
    if (savedLogs) try { setLogs(JSON.parse(savedLogs)); } catch(e) {}
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const dashboardData = useMemo(() => {
    const deptStats: Record<string, number> = {};
    const itemStats: Record<string, number> = {};
    DEPARTMENTS.forEach(d => deptStats[d] = 0);

    const filteredLogs = dashDeptFilter === '全部部門' 
      ? logs.filter(l => l.type === 'OUT') 
      : logs.filter(l => l.type === 'OUT' && l.dept === dashDeptFilter);

    filteredLogs.forEach(log => {
      deptStats[log.dept] = (deptStats[log.dept] || 0) + log.quantity;
      itemStats[log.itemName] = (itemStats[log.itemName] || 0) + log.quantity;
    });

    const topItems = Object.entries(itemStats)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10);

    const lowStock = items.filter(i => i.quantity <= i.minStock).length;
    const expiringSoon = items.filter(i => i.itemGroup === 'MEDICINE' && i.expiryDate && (new Date(i.expiryDate).getTime() - Date.now()) / (1000 * 3600 * 24) <= 60).length;

    return { deptStats, topItems, lowStock, expiringSoon, totalItems: items.length };
  }, [items, logs, dashDeptFilter]);

  const handleAddItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: InventoryItem = {
      id: `ITEM-${Date.now()}`,
      name: formData.get('name') as string,
      category: formData.get('category') as string,
      itemType: (activeTab === 'inventory' ? 'CONSUMABLE' : 'EQUIPMENT') as ItemType,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
      expiryDate: formData.get('expiryDate') as string || undefined,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    };
    setItems([...items, newItem]);
    setShowAddModal(false);
  };

  const handleEditItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editTarget) return;
    const formData = new FormData(e.currentTarget);
    setItems(items.map(i => i.id === editTarget.id ? {
      ...i,
      name: formData.get('name') as string,
      category: formData.get('category') as string,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      minStock: Number(formData.get('minStock')),
      expiryDate: formData.get('expiryDate') as string || undefined,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    } : i));
    setEditTarget(null);
  };

  const handleDelete = () => {
    if (!deleteTarget) return;
    setItems(items.filter(i => i.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  const addToBasket = () => {
    const target = items.find(i => i.id === selectedItemId);
    if (!target) return;
    const qty = Number(inputQty);
    if (qty <= 0) return;
    const inB = basket.filter(b => b.itemId === target.id).reduce((s, b) => s + b.quantity, 0);
    const av = target.quantity - inB;
    if (issuanceMode === 'OUT' && av < qty) {
      alert(`庫存不足！該項目目前可用量為: ${av} ${target.unit}`);
      return;
    }
    setBasket([...basket, { itemId: target.id, name: target.name, quantity: qty, unit: target.unit }]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const ts = Date.now();
    const batchId = `DOC-${ts.toString().slice(-6)}`;
    let nextItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(b => {
      nextItems = nextItems.map(item => {
        if (item.id === b.itemId) {
          const nQty = issuanceMode === 'OUT' ? item.quantity - b.quantity : item.quantity + b.quantity;
          return { ...item, quantity: nQty, lastUpdated: ts };
        }
        return item;
      });
      newLogs.push({
        id: `TX-${ts}-${b.itemId}`, itemId: b.itemId, itemName: b.name, type: issuanceMode,
        quantity: b.quantity, person: inputPerson || '管理員',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: inputReason, timestamp: ts, batchId: batchId, items: [...basket]
      });
    });

    setItems(nextItems);
    setLogs([...newLogs, ...logs]);
    if (issuanceMode === 'OUT') {
      setPrintBatch({ id: batchId, dept: selectedDept, person: inputPerson, reason: inputReason, items: [...basket], timestamp: ts });
      setShowPrintModal(true);
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  const reprintBatch = (log: Transaction) => {
    if (!log.items || log.type !== 'OUT') return;
    setPrintBatch({ id: log.batchId || 'N/A', dept: log.dept, person: log.person, reason: log.reason, items: log.items as BasketItem[], timestamp: log.timestamp });
    setShowPrintModal(true);
  };

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900">
      <aside className="w-64 bg-slate-900 text-white flex flex-col no-print shrink-0 shadow-2xl">
        <div className="p-6">
          <div className="flex items-center gap-3 mb-10">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center"><Package size={24} /></div>
            <span className="text-lg font-black tracking-tighter uppercase">SAFETY PRO</span>
          </div>
          <nav className="space-y-1">
            {[
              { id: 'inventory', label: '工安耗材管理', icon: Package },
              { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
              { id: 'issuance', label: '領用/補貨作業', icon: ShoppingCart },
              { id: 'history', label: '異動日誌審核', icon: History },
              { id: 'dashboard', label: '管理分析看板', icon: LayoutDashboard },
            ].map(tab => (
              <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}>
                <tab.icon size={18} /> {tab.label}
              </button>
            ))}
          </nav>
        </div>
      </aside>

      <main className="flex-1 p-8 overflow-y-auto no-print">
        <div className="max-w-6xl mx-auto">
          <header className="flex justify-between items-end mb-8 border-b-2 border-slate-200 pb-6">
            <div>
              <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-1">REPAIR DIVISION SOUTH - SAFETY SYSTEM</p>
              <h2 className="text-3xl font-black text-slate-800 uppercase">
                {activeTab === 'inventory' ? '工安耗材及設備管理' : activeTab === 'medicine' ? '藥材及藥品管理' : activeTab === 'issuance' ? '物料領用/入庫管理' : activeTab === 'history' ? '歷史異動日誌' : '領用數據統計分析看板'}
              </h2>
            </div>
            {(activeTab === 'inventory' || activeTab === 'medicine') && (
              <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black flex items-center gap-2 shadow-xl hover:bg-black transition-all">
                <Plus size={22} /> 新增項目檔案
              </button>
            )}
          </header>

          {activeTab === 'dashboard' && (
            <div className="space-y-8">
              <div className="flex items-center gap-4 bg-white p-3 rounded-2xl border shadow-sm w-fit">
                <div className="bg-slate-100 p-2 rounded-lg text-slate-500"><Filter size={18}/></div>
                <select className="font-black outline-none bg-transparent pr-6" value={dashDeptFilter} onChange={e=>setDashDeptFilter(e.target.value)}>
                  <option>全部部門</option>
                  {DEPARTMENTS.map(d=><option key={d}>{d}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-4 gap-6">
                <div className="bg-white p-6 rounded-3xl border shadow-sm"><p className="text-[10px] font-bold text-slate-400 mb-1 uppercase tracking-widest">總品項數量</p><p className="text-3xl font-black">{dashboardData.totalItems}</p></div>
                <div className="bg-white p-6 rounded-3xl border shadow-sm"><p className="text-[10px] font-bold text-red-400 mb-1 uppercase tracking-widest">低水位預警</p><p className="text-3xl font-black text-red-500">{dashboardData.lowStock}</p></div>
                <div className="bg-white p-6 rounded-3xl border shadow-sm"><p className="text-[10px] font-bold text-orange-400 mb-1 uppercase tracking-widest">效期預警</p><p className="text-3xl font-black text-orange-500">{dashboardData.expiringSoon}</p></div>
                <div className="bg-white p-6 rounded-3xl border shadow-sm"><p className="text-[10px] font-bold text-blue-400 mb-1 uppercase tracking-widest">篩選後領用數</p><p className="text-3xl font-black text-blue-600">{dashboardData.topItems.reduce((a,b)=>a+b[1],0)}</p></div>
              </div>
              <div className="grid grid-cols-2 gap-8">
                <div className="bg-white p-8 rounded-3xl border shadow-sm">
                  <h3 className="text-sm font-black mb-6 border-b pb-4 flex items-center gap-2 uppercase tracking-widest"><PieChart size={18}/> 各部門領用比例</h3>
                  <div className="space-y-4">
                    {Object.entries(dashboardData.deptStats).sort((a,b)=>b[1]-a[1]).map(([dept,v])=>(
                      <div key={dept} className="flex items-center gap-4">
                        <span className="w-24 text-[11px] font-bold text-slate-500">{dept}</span>
                        <div className="flex-1 h-2 bg-slate-100 rounded-full overflow-hidden"><div className="h-full bg-blue-500 rounded-full" style={{width: `${Math.min(100,(v/(logs.length||1))*100)}%`}}></div></div>
                        <span className="text-xs font-black">{v}</span>
                      </div>
                    ))}
                  </div>
                </div>
                <div className="bg-white p-8 rounded-3xl border shadow-sm">
                  <h3 className="text-sm font-black mb-6 border-b pb-4 flex items-center gap-2 uppercase tracking-widest"><BarChart3 size={18}/> {dashDeptFilter} 消耗排行 Top 10</h3>
                  <div className="space-y-3">
                    {dashboardData.topItems.map(([n,v],idx)=>(
                      <div key={n} className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                        <div className="flex items-center gap-3"><span className="text-[10px] font-black text-slate-400">#{idx+1}</span><span className="font-bold text-slate-700">{n}</span></div>
                        <span className="font-black text-blue-600">{v}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          )}

          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <div className="bg-white rounded-3xl shadow-xl border overflow-hidden">
               <div className="p-6 bg-slate-50 border-b flex justify-between items-center">
                  <div className="relative w-96">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18}/><input className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-slate-200 font-bold outline-none shadow-inner" placeholder="搜尋關鍵字..." value={searchTerm} onChange={e=>setSearchTerm(e.target.value)} />
                  </div>
               </div>
               <table className="w-full text-left">
                 <thead>
                    <tr className="bg-slate-100/50 border-b text-[10px] font-black text-slate-500 uppercase tracking-widest">
                      <th className="px-8 py-5">品項細節</th><th className="px-8 py-5">規格與單位</th><th className="px-8 py-5 text-center">目前庫存</th>{activeTab === 'medicine' && <th className="px-8 py-5">有效截止日期</th>}<th className="px-8 py-5 text-right">作業</th>
                    </tr>
                 </thead>
                 <tbody className="divide-y divide-slate-100">
                    {items.filter(i => (activeTab==='medicine' ? i.itemGroup==='MEDICINE' : i.itemGroup==='INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                      <tr key={item.id} className="hover:bg-blue-50/50 transition-colors group">
                        <td className="px-8 py-6"><div className="font-black text-slate-800 text-lg">{item.name}</div><div className="text-[10px] font-bold text-blue-500 uppercase">{item.category}</div></td>
                        <td className="px-8 py-6 font-bold text-slate-600">{item.spec || '---'} / {item.unit}</td>
                        <td className="px-8 py-6 text-center"><span className={`inline-block px-5 py-2 rounded-2xl font-black text-xl ${item.quantity <= item.minStock ? 'bg-red-100 text-red-600' : 'bg-blue-50 text-blue-700'}`}>{item.quantity}</span></td>
                        {activeTab === 'medicine' && <td className="px-8 py-6 font-black text-slate-700">{item.expiryDate || '未設定'}</td>}
                        <td className="px-8 py-6 text-right"><div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-all"><button onClick={()=>setEditTarget(item)} className="p-2 text-blue-600 hover:bg-white rounded-lg shadow-sm border"><Edit3 size={18}/></button><button onClick={()=>setDeleteTarget({id: item.id, name: item.name})} className="p-2 text-red-600 hover:bg-white rounded-lg shadow-sm border"><Trash2 size={18}/></button></div></td>
                      </tr>
                    ))}
                 </tbody>
               </table>
            </div>
          )}

          {activeTab === 'issuance' && (
            <div className="grid grid-cols-5 gap-8">
              <div className="col-span-2 space-y-6">
                <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border">
                  <div className="flex bg-slate-100 p-1 rounded-2xl mb-8">
                    <button onClick={()=>setIssuanceMode('OUT')} className={`flex-1 py-4 rounded-xl font-black transition-all ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button>
                    <button onClick={()=>setIssuanceMode('IN')} className={`flex-1 py-4 rounded-xl font-black transition-all ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
                  </div>
                  <div className="space-y-6">
                    <div><label className="block text-[10px] font-black text-slate-400 mb-2 uppercase tracking-widest ml-1">選擇品項 (可用餘量)</label><select className="w-full p-4 rounded-2xl bg-slate-50 border-2 border-transparent focus:border-blue-500 font-black outline-none shadow-sm" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}><option value="">請點擊選取...</option>{items.map(i => { const inB = basket.filter(b=>b.itemId===i.id).reduce((s,b)=>s+b.quantity,0); const av = i.quantity - inB; return <option key={i.id} value={i.id} disabled={issuanceMode==='OUT'&&av<=0}>{i.name} (可用: {av})</option> })}</select></div>
                    <div><label className="block text-[10px] font-black text-slate-400 mb-2 uppercase tracking-widest ml-1">輸入數量</label><input type="number" className="w-full p-4 rounded-2xl bg-slate-50 border-2 border-transparent focus:border-blue-500 font-black text-2xl outline-none shadow-inner" value={inputQty} onChange={e=>setInputQty(e.target.value)} /></div>
                    <button onClick={addToBasket} disabled={!selectedItemId} className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black hover:bg-black transition-all active:scale-95 shadow-lg">加入待處理籃子</button>
                  </div>
                </div>
              </div>
              <div className="col-span-3 flex flex-col">
                <div className="bg-white p-10 rounded-[3rem] shadow-xl border flex-1 flex flex-col">
                  <h3 className="font-black text-2xl mb-6 flex items-center gap-3 border-b pb-4"><ClipboardList className="text-blue-500" size={30}/> 待處理籃子 ({basket.length})</h3>
                  <div className="bg-slate-50 rounded-[2rem] p-6 flex-1 mb-6 overflow-y-auto space-y-3 border-2 border-dashed border-slate-200 custom-scrollbar min-h-[300px]">
                    {basket.length === 0 ? <div className="h-full flex flex-col items-center justify-center opacity-20"><ShoppingCart size={80} strokeWidth={1}/><p className="font-black mt-4 uppercase tracking-widest text-sm text-center">目前籃子是空的</p></div> : basket.map((b,i)=>(<div key={i} className="flex justify-between items-center p-4 bg-white rounded-2xl shadow-sm border"><div><p className="font-black text-slate-800 text-lg">{b.name}</p></div><div className="flex items-center gap-6"><span className="font-black text-blue-600 text-2xl">{b.quantity} <span className="text-xs text-slate-400 uppercase">{b.unit}</span></span><button onClick={()=>setBasket(prev=>prev.filter((_,idx)=>idx!==i))} className="text-slate-300 hover:text-red-500 transition-colors"><X size={24}/></button></div></div>))}
                  </div>
                  {issuanceMode === 'OUT' && <div className="grid grid-cols-2 gap-4 mb-4"><select className="p-4 rounded-xl bg-slate-50 border font-bold outline-none focus:border-blue-500 shadow-sm" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>{DEPARTMENTS.map(d=><option key={d}>{d}</option>)}</select><input className="p-4 rounded-xl bg-slate-50 border font-bold outline-none focus:border-blue-500 shadow-sm" placeholder="領用人姓名" value={inputPerson} onChange={e=>setInputPerson(e.target.value)} /></div>}
                  <input className="w-full p-4 rounded-xl bg-slate-50 border font-bold mb-6 outline-none focus:border-blue-500 shadow-sm" placeholder="用途與詳細說明備註" value={inputReason} onChange={e=>setInputReason(e.target.value)} />
                  <button onClick={processIssuance} disabled={basket.length===0} className={`w-full py-7 rounded-3xl font-black text-2xl text-white shadow-xl active:scale-95 transition-all ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>{issuanceMode==='OUT'?'確認領用並列印 A4 公文':'執行補貨入庫'}</button>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'history' && (
            <div className="bg-white rounded-3xl shadow-xl border overflow-hidden">
               <table className="w-full text-left">
                  <thead className="bg-slate-900 text-white text-[10px] font-black uppercase tracking-widest"><tr><th className="px-8 py-5">時間</th><th className="px-8 py-5">類型</th><th className="px-8 py-5">品項與領用資訊</th><th className="px-8 py-5 text-center">數量</th><th className="px-8 py-5 text-right">作業</th></tr></thead>
                  <tbody className="divide-y divide-slate-100">
                    {logs.map(log=>(<tr key={log.id} className="hover:bg-slate-50 transition-colors"><td className="px-8 py-5 text-xs font-bold text-slate-400">{new Date(log.timestamp).toLocaleString()}</td><td className="px-8 py-5"><span className={`px-4 py-1 rounded-full text-[10px] font-black ${log.type==='IN'?'bg-emerald-100 text-emerald-700':'bg-blue-100 text-blue-700'}`}>{log.type==='IN'?'補貨':'領用'}</span></td><td className="px-8 py-5"><div className="font-black text-slate-800 text-base">{log.itemName}</div><div className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">{log.dept} / {log.person}</div></td><td className="px-8 py-5 text-center font-black text-2xl">{log.quantity}</td><td className="px-8 py-5 text-right">{log.type==='OUT' && <button onClick={()=>reprintBatch(log)} className="text-blue-600 font-black text-xs flex items-center gap-2 hover:bg-blue-50 px-4 py-2 rounded-lg ml-auto border border-blue-100 shadow-sm"><Printer size={16}/> 補印領用單</button>}</td></tr>))}
                  </tbody>
               </table>
            </div>
          )}
        </div>
      </main>

      {/* 新增/編輯視窗：強制垂直排版避免重疊 */}
      {(showAddModal || editTarget) && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-xl z-[1000] flex items-center justify-center p-4">
           <form onSubmit={editTarget ? handleEditItem : handleAddItem} className="bg-white rounded-[2.5rem] w-full max-w-xl shadow-2xl overflow-hidden animate-in zoom-in-95">
              <div className="p-10 flex flex-col gap-6">
                <div className="flex justify-between items-center border-b pb-4 mb-2">
                   <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter">{editTarget ? `編輯項目檔案` : '建立新管理品項'}</h3>
                   <button type="button" onClick={()=>{setShowAddModal(false); setEditTarget(null);}} className="p-2 text-slate-400 hover:text-slate-900 transition-colors"><X size={24}/></button>
                </div>

                <div className="flex flex-col gap-5 overflow-y-auto max-h-[60vh] px-2 custom-scrollbar">
                  {/* 品名 */}
                  <div className="flex flex-col gap-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">品項名稱 (公文顯示全名)</label>
                    <input name="name" required defaultValue={editTarget?.name} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-black text-lg shadow-inner" placeholder="請輸入完整名稱" />
                  </div>

                  {/* 分類：單獨佔領一行 */}
                  <div className="flex flex-col gap-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">管理分類</label>
                    <select name="category" defaultValue={editTarget?.category} className="w-full p-4 rounded-xl bg-slate-50 border-2 border-slate-200 font-bold outline-none focus:border-blue-500">
                      {activeTab === 'inventory' ? (
                        <><option value="安全衛生設備">安全衛生設備</option><option value="安全衛生類消耗品">安全衛生類消耗品</option></>
                      ) : (
                        <option value="急救藥材/藥品">急救藥材/藥品</option>
                      )}
                    </select>
                  </div>

                  {/* 規格 */}
                  <div className="flex flex-col gap-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">詳細規格說明</label>
                    <input name="spec" defaultValue={editTarget?.spec} className="w-full p-4 rounded-xl bg-slate-50 border border-slate-200 font-bold outline-none" placeholder="例: 3M-1860 / 藍色" />
                  </div>

                  {/* 單位 */}
                  <div className="flex flex-col gap-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">計算單位</label>
                    <input name="unit" required defaultValue={editTarget?.unit || '個'} className="w-full p-4 rounded-xl bg-slate-50 border border-slate-200 font-bold outline-none" placeholder="個/組/雙" />
                  </div>

                  {/* 數量區域 */}
                  <div className="grid grid-cols-2 gap-4">
                    <div className="flex flex-col gap-1.5">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">庫存/警戒線</label>
                      <div className="flex gap-2">
                        {!editTarget && <input name="quantity" type="number" required defaultValue="0" className="flex-1 p-4 rounded-xl bg-slate-50 border font-black outline-none" />}
                        <input name="minStock" type="number" required defaultValue={editTarget?.minStock || 5} className="flex-1 p-4 rounded-xl bg-slate-50 border font-black text-red-600 outline-none" />
                      </div>
                    </div>
                    {/* 藥材日期：獨立區塊 */}
                    {activeTab === 'medicine' && (
                      <div className="flex flex-col gap-1.5">
                        <label className="text-[10px] font-black text-red-500 uppercase tracking-widest ml-1">有效截止日期</label>
                        <input name="expiryDate" type="date" required defaultValue={editTarget?.expiryDate} className="w-full p-4 rounded-xl bg-blue-50 border-2 border-blue-200 font-black text-blue-700 outline-none h-[58px]" style={{ colorScheme: 'light' }} />
                      </div>
                    )}
                  </div>

                  {/* 備註 */}
                  <div className="flex flex-col gap-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">詳細備註</label>
                    <textarea name="description" defaultValue={editTarget?.description} className="w-full p-4 rounded-xl bg-slate-50 border h-20 font-bold resize-none outline-none focus:border-blue-500 shadow-inner" placeholder="請輸入說明..." />
                  </div>
                </div>

                <div className="flex gap-4 pt-6 border-t mt-4">
                   <button type="submit" className="flex-1 py-5 bg-slate-900 text-white rounded-2xl font-black text-xl hover:bg-black transition-all shadow-xl active:scale-95">確認儲存並鎖定檔案</button>
                   <button type="button" onClick={()=>{setShowAddModal(false); setEditTarget(null);}} className="px-10 py-5 bg-slate-100 rounded-2xl font-black text-slate-500 hover:bg-slate-200 transition-all">取消</button>
                </div>
              </div>
           </form>
        </div>
      )}

      {/* 正式 A4 公文格式：10px 粗邊框與三連方塊簽核欄 */}
      {showPrintModal && printBatch && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-2xl z-[2000] flex items-center justify-center p-6 no-print overflow-y-auto custom-scrollbar">
          <div className="bg-white rounded-[3rem] w-full max-w-4xl h-fit min-h-[90vh] flex flex-col shadow-2xl overflow-hidden my-10">
            <div className="p-8 border-b flex justify-between items-center bg-white shrink-0">
               <h3 className="font-black text-xl flex items-center gap-3 text-slate-700 uppercase tracking-[0.2em]"><Printer size={20}/> 標準 A4 領用單預覽 (V35 Ultimate)</h3>
               <div className="flex gap-4">
                  <button onClick={()=>window.print()} className="px-12 py-4 bg-blue-600 text-white rounded-2xl font-black shadow-xl hover:bg-blue-700 transition-all active:scale-95">確認列印 A4</button>
                  <button onClick={()=>setShowPrintModal(false)} className="px-12 py-4 bg-slate-100 text-slate-500 rounded-2xl font-black hover:bg-slate-200">關閉預覽</button>
               </div>
            </div>

            <div className="flex-1 p-12 bg-slate-300 flex justify-center overflow-visible">
               <div className="bg-white p-14 shadow-2xl print-container" style={{ width: '210mm', minHeight: '297mm' }}>
                  {/* 公文厚框 (10px) */}
                  <div className="border-[10px] border-black p-12 h-full flex flex-col relative text-black">
                    <header className="flex justify-between items-start border-b-[8px] border-black pb-12 mb-14">
                      <div>
                        <div className="bg-black text-white px-5 py-2 inline-block text-[11px] font-black uppercase tracking-[0.6em] mb-4">REPAIR SOUTH - INTERNAL USE ONLY</div>
                        <h1 className="text-7xl font-black tracking-tighter mb-2">工安耗材領用單</h1>
                        <p className="text-gray-500 font-black uppercase text-base tracking-[0.3em]">Safety Equipment Issuance Form</p>
                      </div>
                      <div className="text-right">
                        <p className="text-[12px] font-black text-gray-400 uppercase mb-1 tracking-widest">BATCH NO.</p>
                        <p className="text-6xl font-black text-black leading-none">{printBatch.id}</p>
                        <p className="text-gray-600 font-black mt-10 border-b-4 border-gray-100 pb-2 text-2xl uppercase tracking-tighter">日期: {new Date(printBatch.timestamp).toLocaleDateString()}</p>
                      </div>
                    </header>

                    <div className="grid grid-cols-2 gap-16 mb-20">
                      <div className="border-b-4 border-black pb-6"><p className="text-[13px] font-black text-gray-400 uppercase tracking-[0.3em] mb-4">領用部門 (所屬隊伍)</p><p className="text-5xl font-black">{printBatch.dept}</p></div>
                      <div className="border-b-4 border-black pb-6"><p className="text-[13px] font-black text-gray-400 uppercase tracking-[0.3em] mb-4">申請領用人員 (簽章)</p><p className="text-5xl font-black">{printBatch.person || '---'}</p></div>
                      <div className="col-span-2 border-b-4 border-black pb-6"><p className="text-[13px] font-black text-gray-400 uppercase tracking-[0.3em] mb-4">領用用途及異動備註</p><p className="text-3xl font-bold italic text-slate-800">{printBatch.reason || '物料正常消耗與維修維護更換'}</p></div>
                    </div>

                    <div className="flex-1">
                      <table className="w-full">
                        <thead className="border-b-[6px] border-black">
                          <tr className="text-left text-gray-500">
                            <th className="py-6 font-black text-lg uppercase tracking-widest">品項名稱及內容規格</th>
                            <th className="py-6 text-center font-black text-lg uppercase tracking-widest" style={{ width: '200px' }}>領用數量</th>
                            <th className="py-6 text-right font-black text-lg uppercase tracking-widest" style={{ width: '120px' }}>單位</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y-4 divide-gray-100">
                          {printBatch.items.map((item, idx) => (
                            <tr key={idx}>
                              <td className="py-12 font-black text-5xl text-black leading-tight">{item.name}</td>
                              <td className="py-12 text-center font-black text-9xl text-black">{item.quantity}</td>
                              <td className="py-12 text-right font-black text-4xl text-gray-400">{item.unit}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>

                    {/* 底部正式簽章三連欄位 */}
                    <div className="mt-20 grid grid-cols-3 gap-16 pt-32 border-t-[10px] border-black text-center mb-10">
                       <div className="pt-10 border-t-4 border-gray-300 flex flex-col items-center justify-between min-h-[160px]"><p className="text-[15px] font-black uppercase text-gray-400 tracking-[0.4em]">領用申請</p><div className="mb-4 text-gray-200"> (簽章) </div></div>
                       <div className="pt-10 border-t-4 border-gray-300 flex flex-col items-center justify-between min-h-[160px]"><p className="text-[15px] font-black uppercase text-gray-400 tracking-[0.4em]">單位主管</p><div className="mb-4 text-gray-200"> (核章) </div></div>
                       <div className="pt-10 border-t-4 border-gray-300 flex flex-col items-center justify-between min-h-[160px]"><p className="text-[15px] font-black uppercase text-gray-400 tracking-[0.4em]">庫房經辦</p><div className="mb-4 text-gray-200"> (蓋章) </div></div>
                    </div>

                    <footer className="mt-auto text-[11px] text-gray-300 font-black text-center uppercase tracking-[1.2em] pt-10 border-t-2 border-gray-50">SAFETY PRO ULTIMATE - SYSTEM RECORD V35</footer>
                  </div>
               </div>
            </div>
          </div>
        </div>
      )}

      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm z-[3000] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2rem] p-8 max-w-sm w-full text-center shadow-2xl animate-in zoom-in-95">
             <div className="w-20 h-20 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-6"><AlertTriangle size={40}/></div>
             <h3 className="text-2xl font-black mb-2 text-slate-800">確定刪除？</h3>
             <p className="text-slate-500 font-bold mb-8">"{deleteTarget.name}" 將永久移除。</p>
             <div className="flex flex-col gap-3">
                <button onClick={handleDelete} className="w-full py-4 bg-red-600 text-white rounded-xl font-black shadow-lg">確認永久刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="w-full py-4 bg-slate-100 rounded-xl font-black text-slate-500">取消</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  Stethoscope,
  ShoppingCart,
  ClipboardList,
  PieChart,
  BarChart3,
  Filter
} from 'lucide-react';
import { InventoryItem, Transaction, TransactionType, ItemType } from './types';

const STORAGE_KEY_ITEMS = 'safeman_v35_ultimate_items';
const STORAGE_KEY_LOGS = 'safeman_v35_ultimate_logs';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  const [dashDeptFilter, setDashDeptFilter] = useState<string>('全部部門');

  const [printBatch, setPrintBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) try { setItems(JSON.parse(savedItems)); } catch(e) {}
    if (savedLogs) try { setLogs(JSON.parse(savedLogs)); } catch(e) {}
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const dashboardData = useMemo(() => {
    const deptStats: Record<string, number> = {};
    const itemStats: Record<string, number> = {};
    DEPARTMENTS.forEach(d => deptStats[d] = 0);

    const filteredLogs = dashDeptFilter === '全部部門' 
      ? logs.filter(l => l.type === 'OUT') 
      : logs.filter(l => l.type === 'OUT' && l.dept === dashDeptFilter);

    filteredLogs.forEach(log => {
      deptStats[log.dept] = (deptStats[log.dept] || 0) + log.quantity;
      itemStats[log.itemName] = (itemStats[log.itemName] || 0) + log.quantity;
    });

    const topItems = Object.entries(itemStats)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10);

    const lowStock = items.filter(i => i.quantity <= i.minStock).length;
    const expiringSoon = items.filter(i => i.itemGroup === 'MEDICINE' && i.expiryDate && (new Date(i.expiryDate).getTime() - Date.now()) / (1000 * 3600 * 24) <= 60).length;

    return { deptStats, topItems, lowStock, expiringSoon, totalItems: items.length };
  }, [items, logs, dashDeptFilter]);

  const handleAddItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: InventoryItem = {
      id: `ITEM-${Date.now()}`,
      name: formData.get('name') as string,
      category: formData.get('category') as string,
      itemType: (activeTab === 'inventory' ? 'CONSUMABLE' : 'EQUIPMENT') as ItemType,
      itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
      expiryDate: formData.get('expiryDate') as string || undefined,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    };
    setItems([...items, newItem]);
    setShowAddModal(false);
  };

  const handleEditItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editTarget) return;
    const formData = new FormData(e.currentTarget);
    setItems(items.map(i => i.id === editTarget.id ? {
      ...i,
      name: formData.get('name') as string,
      category: formData.get('category') as string,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      minStock: Number(formData.get('minStock')),
      expiryDate: formData.get('expiryDate') as string || undefined,
      description: formData.get('description') as string,
      lastUpdated: Date.now()
    } : i));
    setEditTarget(null);
  };

  const handleDelete = () => {
    if (!deleteTarget) return;
    setItems(items.filter(i => i.id !== deleteTarget.id));
    setDeleteTarget(null);
  };

  const addToBasket = () => {
    const target = items.find(i => i.id === selectedItemId);
    if (!target) return;
    const qty = Number(inputQty);
    if (qty <= 0) return;
    const inB = basket.filter(b => b.itemId === target.id).reduce((s, b) => s + b.quantity, 0);
    const av = target.quantity - inB;
    if (issuanceMode === 'OUT' && av < qty) {
      alert(`庫存不足！該項目目前可用量為: ${av} ${target.unit}`);
      return;
    }
    setBasket([...basket, { itemId: target.id, name: target.name, quantity: qty, unit: target.unit }]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const ts = Date.now();
    const batchId = `DOC-${ts.toString().slice(-6)}`;
    let nextItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(b => {
      nextItems = nextItems.map(item => {
        if (item.id === b.itemId) {
          const nQty = issuanceMode === 'OUT' ? item.quantity - b.quantity : item.quantity + b.quantity;
          return { ...item, quantity: nQty, lastUpdated: ts };
        }
        return item;
      });
      newLogs.push({
        id: `TX-${ts}-${b.itemId}`, itemId: b.itemId, itemName: b.name, type: issuanceMode,
        quantity: b.quantity, person: inputPerson || '管理員',
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處',
        reason: inputReason, timestamp: ts, batchId: batchId, items: [...basket]
      });
    });

    setItems(nextItems);
    setLogs([...newLogs, ...logs]);
    if (issuanceMode === 'OUT') {
      setPrintBatch({ id: batchId, dept: selectedDept, person: inputPerson, reason: inputReason, items: [...basket], timestamp: ts });
      setShowPrintModal(true);
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  const reprintBatch = (log: Transaction) => {
    if (!log.items || log.type !== 'OUT') return;
    setPrintBatch({ id: log.batchId || 'N/A', dept: log.dept, person: log.person, reason: log.reason, items: log.items as BasketItem[], timestamp: log.timestamp });
    setShowPrintModal(true);
  };

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900">
      <aside className="w-64 bg-slate-900 text-white flex flex-col no-print shrink-0 shadow-2xl">
        <div className="p-6">
          <div className="flex items-center gap-3 mb-10">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center"><Package size={24} /></div>
            <span className="text-lg font-black tracking-tighter uppercase">SAFETY PRO</span>
          </div>
          <nav className="space-y-1">
            {[
              { id: 'inventory', label: '工安耗材管理', icon: Package },
              { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
              { id: 'issuance', label: '領用/補貨作業', icon: ShoppingCart },
              { id: 'history', label: '異動日誌審核', icon: History },
              { id: 'dashboard', label: '管理分析看板', icon: LayoutDashboard },
            ].map(tab => (
              <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}>
                <tab.icon size={18} /> {tab.label}
              </button>
            ))}
          </nav>
        </div>
      </aside>

      <main className="flex-1 p-8 overflow-y-auto no-print">
        <div className="max-w-6xl mx-auto">
          <header className="flex justify-between items-end mb-8 border-b-2 border-slate-200 pb-6">
            <div>
              <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-1">REPAIR DIVISION SOUTH - SAFETY SYSTEM</p>
              <h2 className="text-3xl font-black text-slate-800 uppercase">
