export enum Category {
  PROTECTION = '個人防護 (PPE)',
  FIRE_SAFETY = '消防安全',
  FIRST_AID = '急救耗材',
  SIGNAGE = '標誌警告',
  TOOL = '工具設備',
  OTHER = '其他'
}

export type ItemType = 'EQUIPMENT' | 'CONSUMABLE';
export type ItemGroup = 'INVENTORY' | 'MEDICINE';

export interface InventoryItem {
  id: string;
  name: string;
  category: Category;
  itemType: ItemType; 
  itemGroup: ItemGroup;
  unit: string;
  spec: string;
  quantity: number;
  minStock: number;
  purchaseDate?: string;
  expiryDate?: string;
  description: string;
  lastUpdated: number;
}

export type TransactionType = 'IN' | 'OUT';

export interface Transaction {
  id: string;
  itemId: string;
  itemName: string;
  type: TransactionType;
  quantity: number;
  person: string;
  dept: string;
  reason: string;
  timestamp: number;
}

import { GoogleGenAI } from "@google/genai";
import { InventoryItem } from "../types";

export const getInventoryInsights = async (items: InventoryItem[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const lowStock = items.filter(i => i.quantity <= i.minStock);

  const prompt = `
    這是一個工安耗材管理系統。
    當前庫存清單: ${JSON.stringify(items.map(i => ({ name: i.name, qty: i.quantity, min: i.minStock })))}
    庫存不足的項目: ${JSON.stringify(lowStock.map(i => i.name))}

    請以專業工安管理員的身份，針對目前的庫存狀況提供 3 點具體的採購或管理建議。
    請用繁體中文回答，語氣要簡潔、專業、有說服力。
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "無法獲取 AI 建議，請稍後再試。";
  } catch (error) {
    console.error("Gemini AI Error:", error);
    return "AI 助理目前連線繁忙。請優先檢查庫存警戒項目。";
  }
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
