te" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.purchaseDate} /></div><div><label className="text-xs font-black text-slate-500">有效日期</label><input name="expiryDate" type="date" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.expiryDate} /></div></div>)}<button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-2xl shadow-xl mt-6">儲存物資</button><button type="button" onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="w-full py-3 text-slate-400 font-bold hover:text-black">取消返回</button></form></div></div>
        )}

        {/* 刪除確認 Modal */}
        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/90 flex items-center justify-center p-4 z-[400] animate-in fade-in"><div className="bg-white p-10 rounded-3xl text-center max-w-sm shadow-2xl"><h3 className="text-2xl font-black mb-4 text-black">確定刪除「{deleteTarget.name}」？</h3><p className="text-slate-400 font-bold mb-6">此動作無法復原，相關歷史紀錄仍會保留。</p><button onClick={()=>{ const newItems = items.filter(i => i.id !== deleteTarget.id); setItems(newItems); syncToCloud(newItems, logs); setDeleteTarget(null); }} className="w-full py-4 bg-red-600 text-white rounded-xl font-black mb-2 shadow-lg hover:bg-red-700">確認刪除</button><button onClick={()=>setDeleteTarget(null)} className="w-full py-4 text-slate-400 font-bold hover:text-black">取消</button></div></div>
        )}
      </main>
    </div>
  );
};

