        {/* 編輯/新增 Modal */}
        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-4"><div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl animate-in zoom-in duration-300"><form className="space-y-6" onSubmit={handleSaveItem}><h3 className="text-2xl font-black text-black mb-4">{editTarget ? '編輯項目' : '新增項目'}</h3><div><label className="text-xs font-black text-slate-500 uppercase">物資名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.name} /></div><div className="grid grid-cols-2 gap-6"><div><label className="text-xs font-black text-slate-500">分類</label><select name="itemType" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="EQUIPMENT">安全衛生設備</option><option value="CONSUMABLE">安全衛生類消耗品</option></select></div><div><label className="text-xs font-black text-slate-500">規範 (序號)</label><input name="spec" type="text" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.spec || ''} /></div></div><div className="grid grid-cols-3 gap-6"><div><label className="text-xs font-black text-slate-500">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.unit || '個'} /></div><div><label className="text-xs font-black text-slate-500">目前庫存</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.quantity || 0} /></div><div><label className="text-xs font-black text-slate-500">警戒數量</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.minStock || 5} /></div></div>{(activeTab === 'medicine' || editTarget?.itemGroup === 'MEDICINE') && (<div className="grid grid-cols-2 gap-6"><div><label className="text-xs font-black text-slate-500">購入日期</label><input name="purchaseDate" type="date" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.purchaseDate} /></div><div><label className="text-xs font-black text-slate-500">有效日期</label><input name="expiryDate" type="date" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.expiryDate} /></div></div>)}<button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-2xl shadow-xl mt-6">儲存物資</button><button type="button" onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="w-full py-3 text-slate-400 font-bold hover:text-black">取消返回</button></form></div></div>
        )}

        {/* 刪除確認 Modal */}
        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/90 flex items-center justify-center p-4 z-[400] animate-in fade-in"><div className="bg-white p-10 rounded-3xl text-center max-w-sm shadow-2xl"><h3 className="text-2xl font-black mb-4 text-black">確定刪除「{deleteTarget.name}」？</h3><p className="text-slate-400 font-bold mb-6">此動作無法復原，相關歷史紀錄仍會保留。</p><button onClick={()=>{ const newItems = items.filter(i => i.id !== deleteTarget.id); setItems(newItems); syncToCloud(newItems, logs); setDeleteTarget(null); }} className="w-full py-4 bg-red-600 text-white rounded-xl font-black mb-2 shadow-lg hover:bg-red-700">確認刪除</button><button onClick={()=>setDeleteTarget(null)} className="w-full py-4 text-slate-400 font-bold hover:text-black">取消</button></div></div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, Package, FileText, History, Plus, Trash2, Edit3, Search, X, 
  Printer, AlertTriangle, BrainCircuit, Stethoscope, ShoppingCart, CheckCircle2, 
  Users, Download, Upload, FileDown, ArrowUpRight, ArrowDownLeft, Settings, 
  Cloud, RefreshCw, Clock, Info 
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

// --- 正式雲端 GAS 網址 ---
const DEFAULT_GAS_URL = 'https://script.google.com/macros/s/AKfycbxQmoG0pHHm2tuzt9Og3eAGOTYSUd1d61orWOEygS9qmjQ9LUaC3WsvwCHfjV9wh_Q2/exec';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

type SyncStatus = 'synced' | 'syncing' | 'error' | 'local';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || DEFAULT_GAS_URL);
  const [syncStatus, setSyncStatus] = useState<SyncStatus>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '從未同步');
  const [showSettings, setShowSettings] = useState(false);
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [statsDeptFilter, setStatsDeptFilter] = useState<string>('ALL');
  const [statsYearFilter, setStatsYearFilter] = useState<number>(new Date().getFullYear());
  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    id: string; dept: string; person: string; reason: string; items: BasketItem[]; timestamp: number;
  } | null>(null);

  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const initLoad = async () => {
      const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
      const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
      if (savedItems) { try { setItems(JSON.parse(savedItems)); } catch(e){} }
      if (savedLogs) { try { setLogs(JSON.parse(savedLogs)); } catch(e){} }
      setIsLoaded(true);
      if (gasUrl) fetchFromCloud();
    };
    initLoad();
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const fetchFromCloud = async () => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const response = await fetch(gasUrl);
      const data = await response.json();
      if (data && data.items) {
        setItems(data.items);
        setLogs(data.logs || []);
        setSyncStatus('synced');
        const now = new Date().toLocaleString();
        setLastSyncTime(now);
        localStorage.setItem(STORAGE_KEY_LAST_SYNC, now);
      }
    } catch (err) { setSyncStatus('error'); }
  };

  const syncToCloud = async (currentItems: InventoryItem[], currentLogs: Transaction[]) => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify({ items: currentItems, logs: currentLogs }), mode: 'no-cors' });
      setSyncStatus('synced');
      const now = new Date().toLocaleString();
      setLastSyncTime(now);
      localStorage.setItem(STORAGE_KEY_LAST_SYNC, now);
    } catch (err) { setSyncStatus('error'); }
  };

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;
  const getReservedQty = (id: string) => basket.filter(b => b.itemId === id).reduce((a, c) => a + c.quantity, 0);

  const processIssuance = () => {
    if (basket.length === 0) return;
    const timestamp = Date.now();
    const batchId = generateId();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(b => {
      updatedItems = updatedItems.map(item => {
        if (item.id === b.itemId) {
          return { ...item, quantity: issuanceMode === 'IN' ? item.quantity + b.quantity : item.quantity - b.quantity, lastUpdated: timestamp };
        }
        return item;
      });
      newLogs.push({ id: generateId() + Math.random().toString(36).substr(2, 4), itemId: b.itemId, itemName: b.name, type: issuanceMode, quantity: b.quantity, person: inputPerson || '未填寫', dept: issuanceMode === 'OUT' ? selectedDept : '修護處', reason: inputReason, timestamp });
    });

    const finalLogs = [...newLogs, ...logs];
    setItems(updatedItems);
    setLogs(finalLogs);
    syncToCloud(updatedItems, finalLogs);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({ id: batchId, dept: selectedDept, person: inputPerson, reason: inputReason, items: [...basket], timestamp });
      setShowPrintModal(true);
    }
    setBasket([]); setInputPerson('');
  };

  const handleFinalPrint = (isPDF: boolean = false) => {
    if (!lastTransactionBatch) return;
    const date = new Date(lastTransactionBatch.timestamp);
    const isEquip = lastTransactionBatch.items.some(it => it.itemType === 'EQUIPMENT');
    const rows = lastTransactionBatch.items.map(item => `
      <tr>
        <td style="padding:12px;border:1.5px solid black;text-align:center;color:black;">${item.name}</td>
        <td style="border:1.5px solid black;text-align:center;color:black;">${item.spec||''}</td>
        <td style="border:1.5px solid black;text-align:center;color:black;">${item.unit}</td>
        <td style="font-size:18pt;font-weight:bold;border:1.5px solid black;text-align:center;color:black;">${item.quantity}</td>
        <td style="border:1.5px solid black;text-align:center;color:black;">${lastTransactionBatch.reason}</td>
      </tr>`).join('');

    const printWin = window.open('', '_blank');
    if (!printWin) return;
    printWin.document.write(`
      <html><head><title>單據_${lastTransactionBatch.id}</title><style>
        body{font-family:'標楷體','DFKai-SB',serif;padding:60px;color:black;background:white;}
        table{width:100%;border-collapse:collapse;border:2px solid black;}
        .title{text-align:center;font-size:24pt;font-weight:bold;margin-bottom:20px;}
      </style></head><body>
        <div class="title">台灣電力公司電力修護處南部分處</div>
        <div style="text-align:center;font-size:16pt;margin-bottom:20px;font-weight:bold;">[ ${isEquip?'安全衛生設備借用':'安全衛生類消耗品領用'}單 ]</div>
        <div style="display:flex;justify-content:space-between;margin-bottom:10px;font-weight:bold;">
          <div>部 門：${lastTransactionBatch.dept}</div>
          <div>日 期：${date.getFullYear()-1911} 年 ${date.getMonth()+1} 月 ${date.getDate()} 日</div>
        </div>
        <table><thead><tr style="background:#f2f2f2;"><th>名稱</th><th>規範</th><th>單位</th><th>數量</th><th>備註</th></tr></thead>
        <tbody>${rows}</tbody></table>
        <div style="margin-top:40px;display:flex;justify-content:space-between;font-weight:bold;">
          <div>申請人：${lastTransactionBatch.person}</div>
          <div>經辦人：__________</div>
          <div>主管：__________</div>
        </div>
        <script>window.onload=()=>{setTimeout(()=>{window.print();window.close();},500);};</script>
      </body></html>
    `);
    printWin.document.close();
  };

  const stats = useMemo(() => {
    const filtered = logs.filter(l => l.type === 'OUT' && new Date(l.timestamp).getFullYear() === statsYearFilter && (statsDeptFilter === 'ALL' || l.dept === statsDeptFilter));
    const detailMap: Record<string, number> = {};
    filtered.forEach(l => { detailMap[l.itemName] = (detailMap[l.itemName] || 0) + l.quantity; });
    return { 
      total: filtered.reduce((a, c) => a + c.quantity, 0), 
      details: Object.entries(detailMap).sort((a, b) => b[1] - a[1]) 
    };
  }, [items, logs, statsDeptFilter, statsYearFilter]);

  return (
    <div className="min-h-screen flex bg-slate-100 text-black">
      <aside className="w-72 bg-slate-900 text-white p-6 flex flex-col shrink-0 border-r border-slate-800 shadow-2xl">
        <div className="mb-8">
          <div className="flex items-center gap-3 mb-6">
            <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22}/></div>
            <h1 className="font-black text-xl tracking-tight">工安管理系統</h1>
          </div>
          <div className="bg-slate-800/50 rounded-2xl p-4 border border-slate-700/50">
            <div className="flex items-center justify-between mb-2">
              <span className="text-[10px] font-black text-slate-500 uppercase">雲端同步狀態</span>
              <div className={`w-3 h-3 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500' : 'bg-red-500 animate-pulse'}`}></div>
            </div>
            <div className="text-sm font-bold">{syncStatus === 'synced' ? '連線中' : '中斷或同步中'}</div>
            <div className="text-[10px] text-slate-400 mt-1 flex items-center gap-1"><Clock size={10}/> {lastSyncTime}</div>
          </div>
        </div>
        <nav className="flex-1 space-y-1">
          {[ 
            { id: 'inventory', label: '耗材管理', icon: Package }, 
            { id: 'medicine', label: '藥材管理', icon: Stethoscope }, 
            { id: 'issuance', label: '領用作業', icon: FileText }, 
            { id: 'history', label: '歷史紀錄', icon: History }, 
            { id: 'dashboard', label: '統計看板', icon: LayoutDashboard } 
          ].map(t => (
            <button key={t.id} onClick={() => setActiveTab(t.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === t.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}>
              <t.icon size={20} /> {t.label}
            </button>
          ))}
        </nav>
        <div className="pt-6 border-t border-slate-800 space-y-2">
          <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800"><Settings size={16}/> 雲端設定</button>
          <button onClick={fetchFromCloud} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800"><RefreshCw size={16}/> 手動重新同步</button>
        </div>
      </aside>

      <main className="flex-1 p-10 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-3xl font-black">{activeTab === 'inventory' ? '工安耗材清冊' : activeTab === 'medicine' ? '急救藥材清冊' : activeTab === 'issuance' ? '領用登記' : activeTab === 'history' ? '歷史異動日誌' : '數據統計看板'}</h2>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-black shadow-xl"><Plus size={18}/> 新增物資</button>
          )}
        </header>

        {activeTab === 'issuance' && (
          <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
            <div className="lg:col-span-2 bg-white p-8 rounded-3xl shadow-xl border border-slate-200">
              <h3 className="text-xl font-black mb-6">1. 選擇項目</h3>
              <div className="flex bg-slate-100 p-1 rounded-xl mb-6">
                <button onClick={()=>setIssuanceMode('OUT')} className={`flex-1 py-3 rounded-lg font-bold ${issuanceMode==='OUT'?'bg-white text-blue-600 shadow':'text-slate-400'}`}>領用出庫</button>
                <button onClick={()=>setIssuanceMode('IN')} className={`flex-1 py-3 rounded-lg font-bold ${issuanceMode==='IN'?'bg-white text-emerald-600 shadow':'text-slate-400'}`}>補貨入庫</button>
              </div>
              <div className="space-y-6">
                <div>
                  <label className="text-xs font-black text-slate-400">類別</label>
                  <div className="flex gap-2 mt-2">
                    <button onClick={()=>setIssuanceGroup('INVENTORY')} className={`flex-1 py-3 rounded-xl font-bold border-2 ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-200 text-slate-400'}`}>耗材類</button>
                    <button onClick={()=>setIssuanceGroup('MEDICINE')} className={`flex-1 py-3 rounded-xl font-bold border-2 ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-200 text-slate-400'}`}>藥材類</button>
                  </div>
                </div>
                <div>
                  <label className="text-xs font-black text-slate-400">品項</label>
                  <select className="w-full p-4 rounded-xl mt-2 font-bold" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                    <option value="">-- 請選擇 --</option>
                    {items.filter(i => i.itemGroup === issuanceGroup).map(i => <option key={i.id} value={i.id}>{i.name} (剩餘:{i.quantity - getReservedQty(i.id)})</option>)}
                  </select>
                </div>
                <div>
                  <label className="text-xs font-black text-slate-400">數量</label>
                  <input type="number" className="w-full p-4 rounded-xl mt-2 font-bold" value={inputQty} onChange={e=>setInputQty(e.target.value)}/>
                </div>
                <button onClick={() => {
                  const item = items.find(i=>i.id===selectedItemId);
                  if(!item) return;
                  setBasket([...basket, { itemId: item.id, name: item.name, quantity: Number(inputQty), unit: item.unit, spec: item.spec, itemType: item.itemType }]);
                  setSelectedItemId(''); setInputQty('1');
                }} disabled={!selectedItemId} className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black text-lg shadow-lg">加入清單</button>
              </div>
            </div>
            <div className="lg:col-span-3 bg-white p-8 rounded-3xl shadow-xl border border-slate-200 flex flex-col">
              <h3 className="text-xl font-black mb-6">2. 待處理清單</h3>
              <div className="flex-1 overflow-y-auto mb-6 bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200 p-4 min-h-[300px]">
                {basket.length === 0 && <div className="h-full flex items-center justify-center text-slate-300 font-bold">目前無待處理項目</div>}
                {basket.map((b,i) => <div key={i} className="flex justify-between p-4 bg-white rounded-xl mb-2 shadow-sm font-bold border border-slate-100"><span>{b.name}</span><div className="flex items-center gap-4"><span>{b.quantity} {b.unit}</span><button onClick={()=>setBasket(basket.filter((_,idx)=>idx!==i))} className="text-red-400 hover:text-red-600"><X size={18}/></button></div></div>)}
              </div>
              {issuanceMode === 'OUT' && (
                <div className="grid grid-cols-2 gap-4 mb-6">
                  <div><label className="text-xs font-black text-slate-400">領用部門</label><select className="w-full p-3 rounded-xl mt-2 font-bold" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>{DEPARTMENTS.map(d=><option key={d} value={d}>{d}</option>)}</select></div>
                  <div><label className="text-xs font-black text-slate-400">領用人</label><input type="text" className="w-full p-3 rounded-xl mt-2 font-bold" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div>
                </div>
              )}
              <button onClick={processIssuance} disabled={basket.length===0} className={`w-full py-6 rounded-2xl font-black text-2xl text-white shadow-2xl transition-all active:scale-95 ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>確認並送出數據</button>
            </div>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-slate-900 p-8 rounded-[2rem] text-white shadow-xl"><p className="text-blue-400 text-xs font-black">年度總領用量</p><h3 className="text-5xl font-black mt-2">{stats.total} 件</h3></div>
              <div className="bg-white p-8 rounded-[2rem] shadow-sm border-t-8 border-blue-500"><h4 className="font-black">前五名消耗品</h4>{stats.details.slice(0,5).map(([n,q]) => <div key={n} className="flex justify-between mt-2 font-bold text-slate-600"><span>{n}</span><span>{q}</span></div>)}</div>
              <div className="bg-white p-8 rounded-[2rem] shadow-sm border-t-8 border-emerald-500 flex flex-col justify-between"><h4 className="font-black">AI 智能管理建議</h4><button onClick={async() => { setIsAiLoading(true); setAiInsights(await getInventoryInsights(items)); setIsAiLoading(false); }} className="mt-4 w-full bg-slate-900 text-white py-3 rounded-xl font-bold hover:bg-black transition-all shadow-lg">{isAiLoading?'分析中...':'即時生成庫存建議'}</button></div>
            </div>
            {aiInsights && <div className="bg-white p-8 rounded-3xl shadow-xl font-bold text-lg leading-relaxed whitespace-pre-wrap animate-in fade-in border-2 border-blue-50">{aiInsights}</div>}
          </div>
        )}

        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden">
            <div className="p-4 bg-slate-50 border-b flex items-center gap-4"><Search className="text-slate-400"/><input type="text" placeholder="搜尋項目..." className="bg-transparent border-none outline-none w-full font-bold" value={searchTerm} onChange={e=>setSearchTerm(e.target.value)}/></div>
            <table className="w-full text-left">
              <thead className="bg-slate-100 text-[10px] font-black text-slate-400 uppercase"><tr><th className="px-8 py-5">品項名稱及規格</th><th className="px-8 py-5 text-center">庫存狀態</th><th className="px-8 py-5 text-right">管理</th></tr></thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(i => (activeTab==='medicine' ? i.itemGroup==='MEDICINE' : i.itemGroup==='INVENTORY') && i.name.includes(searchTerm)).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50">
                    <td className="px-8 py-5"><div className="font-black">{item.name}</div><div className="text-xs text-slate-400 font-bold">{item.spec}</div></td>
                    <td className="px-8 py-5 text-center"><span className={`px-5 py-1.5 rounded-full font-black text-sm ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-emerald-50 text-emerald-600'}`}>{item.quantity} {item.unit}</span></td>
                    <td className="px-8 py-5 text-right"><button onClick={()=>setEditTarget(item)} className="p-2 text-slate-300 hover:text-blue-600 transition-colors"><Edit3 size={18}/></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-slate-100 text-[10px] font-black text-slate-400 uppercase"><tr><th className="px-6 py-4">時間</th><th className="px-6 py-4">品項 (數量)</th><th className="px-6 py-4">異動類型</th><th className="px-6 py-4">部門/經手人</th><th className="px-6 py-4 text-right">單據</th></tr></thead>
              <tbody className="divide-y divide-slate-100">
                {logs.map(log => <tr key={log.id} className="text-sm hover:bg-slate-50"><td className="px-6 py-4 text-slate-400 font-bold">{new Date(log.timestamp).toLocaleString()}</td><td className="px-6 py-4 font-black">{log.itemName} ({log.quantity})</td><td className="px-6 py-4 font-bold">{log.type==='OUT'?<span className="text-blue-600">領用出庫</span>:<span className="text-emerald-600">補貨入庫</span>}</td><td className="px-6 py-4 font-bold">{log.dept} / {log.person}</td><td className="px-6 py-4 text-right">{log.type==='OUT' && <button onClick={()=>{ setLastTransactionBatch({ id: log.id, dept: log.dept, person: log.person, reason: log.reason, items: [{itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '個', spec: '', itemType: 'CONSUMABLE'}], timestamp: log.timestamp }); setShowPrintModal(true); }} className="text-slate-300 hover:text-blue-600"><Printer size={18}/></button>}</td></tr>)}
              </tbody>
            </table>
          </div>
        )}
      </main>

      {/* 設定彈窗 */}
      {showSettings && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[600] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl animate-in zoom-in">
            <h3 className="text-2xl font-black mb-6 flex items-center gap-2"><Settings/> 雲端同步設定</h3>
            <div className="space-y-6">
              <div><label className="text-xs font-black text-slate-400">GAS Web App URL</label><input type="text" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={localStorage.getItem(STORAGE_KEY_GAS_URL) || ''} id="gas-url-input" placeholder="留空則使用預設網址"/></div>
              <div className="flex gap-4">
                <button onClick={() => {
                  const val = (document.getElementById('gas-url-input') as HTMLInputElement).value.trim();
                  if(val) { localStorage.setItem(STORAGE_KEY_GAS_URL, val); setGasUrl(val); } else { localStorage.removeItem(STORAGE_KEY_GAS_URL); setGasUrl(DEFAULT_GAS_URL); }
                  setShowSettings(false); fetchFromCloud();
                }} className="flex-1 py-4 bg-blue-600 text-white rounded-2xl font-black shadow-xl">儲存設定</button>
                <button onClick={()=>setShowSettings(false)} className="px-8 py-4 bg-slate-100 rounded-2xl font-bold">返回</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 新增編輯彈窗 */}
      {(showAddModal || editTarget) && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[500] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg p-10 shadow-2xl">
            <h3 className="text-2xl font-black mb-6">{editTarget?'編輯項目資訊':'新增工安物資'}</h3>
            <form className="space-y-4" onSubmit={(e: any)=>{
              e.preventDefault();
              const fd = new FormData(e.target);
              const data = { name: fd.get('name') as string, spec: fd.get('spec') as string, unit: fd.get('unit') as string, quantity: Number(fd.get('quantity')), minStock: Number(fd.get('minStock')), itemType: fd.get('itemType') as ItemType, itemGroup: activeTab==='medicine'?'MEDICINE':'INVENTORY' as ItemGroup };
              let updated;
              if(editTarget) updated = items.map(i=>i.id===editTarget.id?{...i,...data}:i);
              else updated = [...items, { id: generateId(), ...data, category: Category.OTHER, description: '', lastUpdated: Date.now() }];
              setItems(updated); syncToCloud(updated, logs); setShowAddModal(false); setEditTarget(null);
            }}>
              <div><label className="text-xs font-black">項目名稱</label><input name="name" className="w-full p-3 rounded-xl mt-1 font-bold" defaultValue={editTarget?.name} required/></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-xs font-black">庫存量</label><input name="quantity" type="number" className="w-full p-3 rounded-xl mt-1 font-bold" defaultValue={editTarget?.quantity||0} required/></div>
                <div><label className="text-xs font-black">警戒庫存</label><input name="minStock" type="number" className="w-full p-3 rounded-xl mt-1 font-bold" defaultValue={editTarget?.minStock||5} required/></div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-xs font-black">單位 (如:個,組)</label><input name="unit" className="w-full p-3 rounded-xl mt-1 font-bold" defaultValue={editTarget?.unit||'個'} required/></div>
                <div><label className="text-xs font-black">規格 (序號)</label><input name="spec" className="w-full p-3 rounded-xl mt-1 font-bold" defaultValue={editTarget?.spec}/></div>
              </div>
              <div><label className="text-xs font-black">性質</label><select name="itemType" className="w-full p-3 rounded-xl mt-1 font-bold" defaultValue={editTarget?.itemType||'CONSUMABLE'}><option value="CONSUMABLE">消耗品 (領用)</option><option value="EQUIPMENT">借用設備 (借用)</option></select></div>
              <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl mt-4 shadow-xl">儲存變更</button>
              <button type="button" onClick={()=>{setShowAddModal(false);setEditTarget(null);}} className="w-full py-2 text-slate-400 font-bold">取消</button>
            </form>
          </div>
        </div>
      )}

      {/* 單據預覽彈窗 */}
      {showPrintModal && lastTransactionBatch && (
        <div className="fixed inset-0 bg-slate-900/95 z-[700] flex items-center justify-center p-8">
          <div className="bg-white rounded-[3rem] w-full max-w-4xl h-[85vh] overflow-hidden flex flex-col shadow-2xl animate-in zoom-in">
            <div className="p-8 border-b flex justify-between items-center bg-white relative z-10">
              <h3 className="text-2xl font-black flex items-center gap-3"><CheckCircle2 className="text-emerald-500"/> 單據產出預覽</h3>
              <div className="flex gap-4">
                <button onClick={()=>handleFinalPrint(false)} className="bg-blue-600 text-white px-8 py-3 rounded-2xl font-black flex items-center gap-2 shadow-lg hover:scale-105 transition-all"><Printer size={20}/> 列印單據</button>
                <button onClick={()=>setShowPrintModal(false)} className="bg-slate-100 p-3 rounded-2xl hover:bg-slate-200 transition-all"><X size={24}/></button>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-10 bg-slate-50 flex justify-center">
              <div className="bg-white p-12 shadow-2xl border w-[210mm] h-fit font-serif text-black text-left">
                <h1 className="text-center text-4xl font-bold border-b-4 border-double border-black pb-4 mb-8">台灣電力公司電力修護處南部分處</h1>
                <p className="text-center text-xl font-bold mb-10 underline decoration-2 underline-offset-8">工安物資領用明細單 (單號: {lastTransactionBatch.id})</p>
                <div className="flex justify-between mb-6 font-bold text-lg">
                  <span>部門：${lastTransactionBatch.dept}</span>
                  <span>日期：${new Date(lastTransactionBatch.timestamp).toLocaleDateString()}</span>
                </div>
                <table className="w-full border-2 border-black mb-8">
                  <thead><tr className="bg-slate-100 border-b-2 border-black font-bold">
                    <th className="border-r border-black p-3 text-center">項目名稱</th>
                    <th className="border-r border-black p-3 text-center">單位</th>
                    <th className="p-3 text-center">領用數量</th>
                  </tr></thead>
                  <tbody>
                    {lastTransactionBatch.items.map((it,idx)=><tr key={idx} className="border-b border-black text-center font-bold text-lg">
                      <td className="border-r border-black p-4">${it.name}</td>
                      <td className="border-r border-black p-4">${it.unit}</td>
                      <td className="p-4">${it.quantity}</td>
                    </tr>)}
                    {Array(Math.max(0, 10 - lastTransactionBatch.items.length)).fill(0).map((_, i) => (
                      <tr key={i + 100} className="border-b border-black"><td className="border-r border-black p-4">&nbsp;</td><td className="border-r border-black p-4"></td><td className="p-4"></td></tr>
                    ))}
                  </tbody>
                </table>
                <div className="mt-16 flex justify-between font-bold text-xl px-4">
                  <span>領用人簽章：__________</span>
                  <span>經辦人：__________</span>
                  <span>主管：__________</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';

const container = document.getElementById('root');
if (!container) throw new Error('Root element not found');

const root = createRoot(container);
root.render(
  <React.StrictMode>
    <App />
