              </div>
              {issuanceMode === 'OUT' && (
                <div className="grid grid-cols-2 gap-4 mb-6 font-bold">
                  <div><label className="text-xs font-black text-slate-400">領用部門</label><select className="w-full p-3 rounded-xl mt-2" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>{DEPARTMENTS.map(d=><option key={d} value={d}>{d}</option>)}</select></div>
                  <div><label className="text-xs font-black text-slate-400">領用人</label><input type="text" className="w-full p-3 rounded-xl mt-2" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div>
                </div>
              )}
              <button onClick={processIssuance} disabled={basket.length===0} className={`w-full py-6 rounded-2xl font-black text-2xl text-white shadow-2xl ${issuanceMode==='OUT'?'bg-blue-600':'bg-emerald-600'}`}>確認並上傳數據</button>
            </div>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-slate-900 p-8 rounded-[2rem] text-white shadow-xl"><p className="text-blue-400 text-xs font-black uppercase tracking-widest">年度累計領用</p><h3 className="text-5xl font-black mt-2">{stats.totalQty} 件</h3></div>
