            <div className="p-4 bg-slate-50 border-b flex items-center gap-4"><Search className="text-slate-400"/><input type="text" placeholder="搜尋項目名稱..." className="bg-transparent border-none outline-none w-full font-bold" value={searchTerm} onChange={e=>setSearchTerm(e.target.value)}/></div>
            <table className="w-full text-left">
              <thead className="bg-slate-100 text-[10px] font-black text-slate-400 uppercase"><tr><th className="px-8 py-5">名稱及規格</th><th className="px-8 py-5 text-center">庫存餘額</th><th className="px-8 py-5 text-right">操作</th></tr></thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(i => (activeTab==='medicine' ? i.itemGroup==='MEDICINE' : i.itemGroup==='INVENTORY') && i.name.includes(searchTerm)).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-8 py-5"><div className="font-black text-lg">{item.name}</div><div className="text-xs text-slate-400 font-bold">{item.spec}</div></td>
                    <td className="px-8 py-5 text-center"><span className={`px-5 py-2 rounded-xl font-black text-lg ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-emerald-50 text-emerald-600'}`}>{item.quantity} {item.unit}</span></td>
                    <td className="px-8 py-5 text-right"><button onClick={()=>setEditTarget(item)} className="p-2 text-slate-300 hover:text-blue-600"><Edit3 size={20}/></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-slate-100 text-[10px] font-black text-slate-400 uppercase"><tr><th className="px-6 py-4">時間</th><th className="px-6 py-4">品項數量</th><th className="px-6 py-4">部門/領用人</th><th className="px-6 py-4 text-right">單據</th></tr></thead>
              <tbody className="divide-y divide-slate-100">
                {logs.map(log => <tr key={log.id} className="hover:bg-slate-50"><td className="px-6 py-4 text-slate-400 font-bold">{new Date(log.timestamp).toLocaleString()}</td><td className="px-6 py-4 font-black">{log.itemName} ({log.quantity})</td><td className="px-6 py-4 font-bold">{log.dept} / {log.person}</td><td className="px-6 py-4 text-right">{log.type==='OUT' && <button onClick={()=>{ setLastTransactionBatch({ id: log.id, dept: log.dept, person: log.person, reason: log.reason, items: [{itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '個', spec: '', itemType: 'CONSUMABLE'}], timestamp: log.timestamp }); setShowPrintModal(true); }} className="text-slate-300 hover:text-blue-600"><Printer size={18}/></button>}</td></tr>)}
              </tbody>
            </table>
          </div>
        )}
      </main>

      {showSettings && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[600] flex items-center justify-center p-4">
