        </div>
      )}

      {(showAddModal || editTarget) && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[500] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg p-10 shadow-2xl">
            <h3 className="text-2xl font-black mb-6">{editTarget?'編輯項目':'新增物資'}</h3>
            <form className="space-y-4" onSubmit={handleSaveItem}>
              <div><label className="text-xs font-black">名稱</label><input name="name" className="w-full p-3 rounded-xl mt-1 font-bold" defaultValue={editTarget?.name} required/></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-xs font-black">目前庫存</label><input name="quantity" type="number" className="w-full p-3 rounded-xl mt-1 font-bold" defaultValue={editTarget?.quantity||0} required/></div>
                <div><label className="text-xs font-black">警戒數量</label><input name="minStock" type="number" className="w-full p-3 rounded-xl mt-1 font-bold" defaultValue={editTarget?.minStock||5} required/></div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-xs font-black">單位</label><input name="unit" className="w-full p-3 rounded-xl mt-1 font-bold" defaultValue={editTarget?.unit||'個'} required/></div>
