              <button type="button" onClick={()=>{setShowAddModal(false);setEditTarget(null);}} className="w-full py-2 text-slate-400 font-bold">取消</button>
            </form>
          </div>
        </div>
      )}

      {showPrintModal && lastTransactionBatch && (
        <div className="fixed inset-0 bg-slate-900/95 z-[700] flex items-center justify-center p-8">
          <div className="bg-white rounded-[3rem] w-full max-w-4xl h-[85vh] overflow-hidden flex flex-col shadow-2xl animate-in zoom-in">
            <div className="p-8 border-b flex justify-between items-center bg-white relative z-10">
              <h3 className="text-2xl font-black flex items-center gap-3"><CheckCircle2 className="text-emerald-500"/> 單據預覽</h3>
              <div className="flex gap-4">
                <button onClick={()=>handleFinalPrint(false)} className="bg-blue-600 text-white px-8 py-3 rounded-2xl font-black flex items-center gap-2 shadow-lg"><Printer size={20}/> 列印</button>
                <button onClick={()=>setShowPrintModal(false)} className="bg-slate-100 p-3 rounded-2xl"><X size={24}/></button>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-10 bg-slate-100 flex justify-center">
              <div className="bg-white p-12 shadow-2xl border w-[210mm] h-fit font-serif text-black text-left">
                <h1 className="text-center text-4xl font-bold border-b-4 border-double border-black pb-4 mb-8">台灣電力公司電力修護處南部分處</h1>
                <p className="text-center text-xl font-bold mb-10 underline underline-offset-8">工安物資領用明細單 (單號: {lastTransactionBatch.id})</p>
                <div className="flex justify-between mb-6 font-bold text-lg"><span>部門：{lastTransactionBatch.dept}</span><span>日期：{new Date(lastTransactionBatch.timestamp).toLocaleDateString()}</span></div>
                <table className="w-full border-2 border-black mb-8">
                  <thead><tr className="bg-slate-100 border-b-2 border-black font-bold text-center">
                    <th className="border-r border-black p-3">名稱</th><th className="border-r border-black p-3">單位</th><th className="p-3">數量</th>
                  </tr></thead>
                  <tbody>
                    {lastTransactionBatch.items.map((it,idx)=><tr key={idx} className="border-b border-black text-center font-bold text-xl">
                      <td className="border-r border-black p-4">{it.name}</td><td className="border-r border-black p-4">{it.unit}</td><td className="p-4">{it.quantity}</td>
                    </tr>)}
