import { GoogleGenAI } from "@google/genai";
import { InventoryItem } from "../types";

export const getInventoryInsights = async (items: InventoryItem[]): Promise<string> => {
  // 若無項目，直接返回提示
  if (!items || items.length === 0) {
    return "目前系統內尚無物資資料。請先新增物資後再進行 AI 庫存分析。";
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const lowStock = items.filter(i => i.quantity <= i.minStock);

  const prompt = `
    你是一位資深的工安與庫存管理專家。
    請根據以下目前的庫存狀況，提供 3 點具體的採購建議、存放提醒或管理改進點。

    【當前庫存概要】: 
    ${items.map(i => `- ${i.name}: 現存 ${i.quantity} ${i.unit} (警戒值: ${i.minStock})`).join('\n')}

    【庫存不足或接近警戒的項目】: 
    ${lowStock.length > 0 ? lowStock.map(i => i.name).join(', ') : '目前尚無'}

    請以專業、簡潔且具說服力的繁體中文回答。每點建議請簡短有力。
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        temperature: 0.7,
        topP: 0.95,
      }
    });

    // 確保獲取到文字內容，否則返回備用文字
    const resultText = response.text;
    if (!resultText) {
      throw new Error("Empty response text");
    }
    return resultText;

  } catch (error) {
    console.error("Gemini AI Analysis Error:", error);
    // 根據常見錯誤類型提供更具體的本地端回應
    if (lowStock.length > 0) {
      return `【AI 助手暫時無法連線，但已偵測到異常】\n目前有 ${lowStock.length} 項物資庫存低於警戒值（如：${lowStock[0].name}），建議儘速採購補足庫存，以維持作業安全。`;
    }
    return "AI 助理連線異常，但目前庫存水位尚屬正常。建議定期檢查急救藥材是否過期。";
  }
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
