                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b">
                <tr>
                  <th className="px-6 py-4">異動時間</th>
                  <th className="px-6 py-4">品項數量</th>
                  <th className="px-6 py-4">異動類型</th>
                  <th className="px-6 py-4">部門 / 領用人</th>
                  <th className="px-6 py-4 text-right">單據</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {logs.map(log => (
                  <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4 text-slate-400 font-bold text-sm">{new Date(log.timestamp).toLocaleString()}</td>
                    <td className="px-6 py-4 font-black text-slate-800">{log.itemName} ({log.quantity})</td>
                    <td className="px-6 py-4">
                      <span className={`font-bold px-3 py-1 rounded-lg text-xs ${log.type==='OUT' ? 'bg-blue-50 text-blue-600' : 'bg-emerald-50 text-emerald-600'}`}>
                        {log.type==='OUT' ? '領用出庫' : '補貨入庫'}
                      </span>
                    </td>
                    <td className="px-6 py-4 font-bold text-slate-700">{log.dept} / {log.person}</td>
                    <td className="px-6 py-4 text-right">
                      {log.type==='OUT' && (
                        <button onClick={()=>{ 
                          setLastTransactionBatch({ 
                            id: log.id, 
                            dept: log.dept, 
                            person: log.person, 
                            reason: log.reason, 
                            items: [{itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '', spec: '', itemType: 'CONSUMABLE'}], 
                            timestamp: log.timestamp 
                          }); 
                          setShowPrintModal(true); 
                        }} className="p-2 text-slate-300 hover:text-blue-600"><Printer size={18}/></button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </main>

      {showSettings && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[600] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl">
            <h3 className="text-2xl font-black mb-6 text-slate-900 flex items-center gap-2"><Settings className="text-blue-500"/> 雲端同步設定</h3>
            <div className="space-y-6">
              <div><label className="text-xs font-black text-slate-400">Google Apps Script (GAS) Web App URL</label><input type="text" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={localStorage.getItem(STORAGE_KEY_GAS_URL) || ''} id="gas-url-input" placeholder="尚未設定網址"/></div>
              <div className="bg-blue-50 p-4 rounded-xl border border-blue-100"><p className="text-xs font-bold text-blue-600 leading-relaxed">請輸入您的 GAS 部署網址以實現跨設備同步。若留空，系統將使用預設示範網址。</p></div>
              <div className="flex gap-4">
                <button onClick={() => handleGasUrlSave((document.getElementById('gas-url-input') as HTMLInputElement).value)} className="flex-1 py-4 bg-blue-600 text-white rounded-2xl font-black shadow-xl hover:bg-blue-700 transition-all active:scale-95">儲存並連線</button>
                <button onClick={()=>setShowSettings(false)} className="px-8 py-4 bg-slate-100 text-slate-600 rounded-2xl font-bold hover:bg-slate-200 transition-all">返回</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {(showAddModal || editTarget) && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[500] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg p-10 shadow-2xl">
            <h3 className="text-2xl font-black mb-6 text-slate-900">{editTarget?'編輯物資項目':'新增工安物資'}</h3>
            <form className="space-y-4" onSubmit={handleSaveItem}>
              <div><label className="text-xs font-black text-slate-400">項目名稱</label><input name="name" className="w-full p-3 rounded-xl mt-1 font-bold" defaultValue={editTarget?.name} required/></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-xs font-black text-slate-400">當前庫存量</label><input name="quantity" type="number" className="w-full p-3 rounded-xl mt-1 font-bold" defaultValue={editTarget?.quantity||0} required/></div>
                <div><label className="text-xs font-black text-slate-400">警戒數量 (低水位提醒)</label><input name="minStock" type="number" className="w-full p-3 rounded-xl mt-1 font-bold" defaultValue={editTarget?.minStock||5} required/></div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-xs font-black text-slate-400">單位 (如:組,個)</label><input name="unit" className="w-full p-3 rounded-xl mt-1 font-bold" defaultValue={editTarget?.unit||'個'} required/></div>
                <div><label className="text-xs font-black text-slate-400">物資性質</label><select name="itemType" className="w-full p-3 rounded-xl mt-1 font-bold" defaultValue={editTarget?.itemType||'CONSUMABLE'}><option value="CONSUMABLE">消耗品 (領用)</option><option value="EQUIPMENT">設備 (借用)</option></select></div>
              </div>
              <div><label className="text-xs font-black text-slate-400">規格 / 序號 / 序位</label><input name="spec" className="w-full p-3 rounded-xl mt-1 font-bold" defaultValue={editTarget?.spec} placeholder="如：3M-N95, #A01"/></div>
              <div className="pt-4 flex flex-col gap-3">
                <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl hover:bg-blue-700 transition-all active:scale-95">儲存數據</button>
                <button type="button" onClick={()=>{setShowAddModal(false);setEditTarget(null);}} className="w-full py-2 text-slate-400 font-bold hover:text-slate-600">取消</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showPrintModal && lastTransactionBatch && (
        <div className="fixed inset-0 bg-slate-900/95 z-[700] flex items-center justify-center p-8">
          <div className="bg-white rounded-[3rem] w-full max-w-4xl h-[85vh] overflow-hidden flex flex-col shadow-2xl scale-in">
            <div className="p-8 border-b flex justify-between items-center bg-white relative z-10">
              <h3 className="text-2xl font-black flex items-center gap-3 text-slate-900"><CheckCircle2 className="text-emerald-500"/> 單據預覽與列印</h3>
              <div className="flex gap-4">
                <button onClick={handleFinalPrint} className="bg-blue-600 text-white px-8 py-3 rounded-2xl font-black flex items-center gap-2 shadow-lg hover:bg-blue-700 transition-all active:scale-95"><Printer size={20}/> 列印單據</button>
                <button onClick={()=>setShowPrintModal(false)} className="bg-slate-100 p-3 rounded-2xl hover:bg-slate-200 transition-all text-slate-500"><X size={24}/></button>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-10 bg-slate-100 flex justify-center custom-scrollbar">
              <div className="bg-white p-16 shadow-2xl border w-[210mm] h-fit font-serif text-black text-left">
                <h1 className="text-center text-4xl font-bold border-b-4 border-double border-black pb-4 mb-8">台灣電力公司電力修護處南部分處</h1>
                <p className="text-center text-xl font-bold mb-10 underline underline-offset-8">工安物資領用明細單 (單號: {lastTransactionBatch.id})</p>
                <div className="flex justify-between mb-6 font-bold text-lg"><span>部門：{lastTransactionBatch.dept}</span><span>日期：{new Date(lastTransactionBatch.timestamp).toLocaleDateString()}</span></div>
                <table className="w-full border-2 border-black mb-8">
                  <thead><tr className="bg-slate-50 border-b-2 border-black font-bold text-center">
                    <th className="border-r border-black p-3">名稱</th><th className="border-r border-black p-3">單位</th><th className="p-3">數量</th>
                  </tr></thead>
                  <tbody>
                    {lastTransactionBatch.items.map((it,idx)=><tr key={idx} className="border-b border-black text-center font-bold text-xl">
                      <td className="border-r border-black p-4">{it.name}</td><td className="border-r border-black p-4">{it.unit || '個'}</td><td className="p-4">{it.quantity}</td>
                    </tr>)}
                  </tbody>
                </table>
                <div className="mt-20 flex justify-between font-bold text-xl px-4"><span>領用人簽章：{lastTransactionBatch.person}</span><span>經辦：__________</span><span>主管：__________</span></div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Edit3,
  Search,
  X,
  Printer,
  Stethoscope,
  ShoppingCart,
  CheckCircle2,
  Download,
  Settings,
  RefreshCw,
  Clock,
  Info
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';

// --- 正式雲端 GAS 網址 (已固定) ---
const DEFAULT_GAS_URL = 'https://script.google.com/macros/s/AKfycbxQmoG0pHHm2tuzt9Og3eAGOTYSUd1d61orWOEygS9qmjQ9LUaC3WsvwCHfjV9wh_Q2/exec'; 

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

type SyncStatus = 'synced' | 'syncing' | 'error' | 'local';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || DEFAULT_GAS_URL);
  const [syncStatus, setSyncStatus] = useState<SyncStatus>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '從未同步');
  const [showSettings, setShowSettings] = useState(false);
  const [statsDeptFilter, setStatsDeptFilter] = useState<string>('ALL');
  const [statsYearFilter, setStatsYearFilter] = useState<string>('ALL'); // 改為字串，支援 ALL

  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    id: string; dept: string; person: string; reason: string; items: BasketItem[]; timestamp: number;
  } | null>(null);

  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const initLoad = async () => {
      const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
      const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
      if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
      if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
      setIsLoaded(true);
      if (gasUrl) fetchFromCloud();
    };
    initLoad();
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const updateSyncTime = () => {
    const now = new Date().toLocaleTimeString('zh-TW', { hour12: false, hour: '2-digit', minute: '2-digit' });
    const fullTime = `${new Date().toLocaleDateString('zh-TW')} ${now}`;
    setLastSyncTime(fullTime);
    localStorage.setItem(STORAGE_KEY_LAST_SYNC, fullTime);
  };

  const syncToCloud = async (currentItems: InventoryItem[], currentLogs: Transaction[]) => {
    if (!gasUrl) { setSyncStatus('local'); return; }
    setSyncStatus('syncing');
    try {
      const payload = { items: currentItems, logs: currentLogs, timestamp: Date.now() };
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify(payload), mode: 'no-cors' });
      setSyncStatus('synced');
      updateSyncTime();
    } catch (err) {
      setSyncStatus('error');
    }
  };

  const fetchFromCloud = async () => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const response = await fetch(gasUrl);
      const data = await response.json();
      if (data && data.items && data.logs) {
        setItems(data.items);
        setLogs(data.logs);
        setSyncStatus('synced');
        updateSyncTime();
      }
    } catch (err) {
      setSyncStatus('error');
    }
  };

  const handleGasUrlSave = (newUrl: string) => {
    const cleanUrl = newUrl.trim();
    const finalUrl = cleanUrl === '' ? DEFAULT_GAS_URL : cleanUrl;
    setGasUrl(finalUrl);
    if (cleanUrl === '') localStorage.removeItem(STORAGE_KEY_GAS_URL);
    else localStorage.setItem(STORAGE_KEY_GAS_URL, cleanUrl);
    setShowSettings(false);
    if (finalUrl) fetchFromCloud();
  };

  const exportData = () => {
    const data = { items, logs, timestamp: Date.now() };
    const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `工安管理備份_${new Date().toLocaleDateString('zh-TW').replace(/\//g, '-')}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;
  const getReservedQty = (itemId: string) => basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);

  const processIssuance = () => {
    if (basket.length === 0) return;
    const timestamp = Date.now();
    const batchId = generateId();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(bItem => {
      updatedItems = updatedItems.map(item => {
        if (item.id === bItem.itemId) {
          const newQty = issuanceMode === 'IN' ? item.quantity + bItem.quantity : item.quantity - bItem.quantity;
          return { ...item, quantity: newQty, lastUpdated: timestamp };
        }
        return item;
      });
      newLogs.push({ 
        id: generateId() + Math.random().toString(36).substr(2, 4), 
        itemId: bItem.itemId, 
        itemName: bItem.name, 
        type: issuanceMode, 
        quantity: bItem.quantity, 
        person: inputPerson || '未填寫', 
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處', 
        reason: inputReason, 
        timestamp: timestamp 
      });
    });

    const finalLogs = [...newLogs, ...logs];
    setItems(updatedItems);
    setLogs(finalLogs);
    syncToCloud(updatedItems, finalLogs);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({ id: batchId, dept: selectedDept, person: inputPerson, reason: inputReason, items: [...basket], timestamp: timestamp });
      setShowPrintModal(true);
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  const handleFinalPrint = () => {
    if (!lastTransactionBatch) return;
    const date = new Date(lastTransactionBatch.timestamp);
    const isEquip = lastTransactionBatch.items.some(it => it.itemType === 'EQUIPMENT');

    const rows = lastTransactionBatch.items.map(item => `
      <tr>
        <td style="text-align:center; color:black; padding: 12px; border: 1.5px solid black;">${item.name}</td>
        <td style="text-align:center; color:black; border: 1.5px solid black;">${item.spec || ''}</td>
        <td style="text-align:center; color:black; border: 1.5px solid black;">${item.unit}</td>
        <td style="text-align:center; font-size:18pt; font-weight:bold; color:black; border: 1.5px solid black;">${item.quantity}</td>
        <td style="text-align:center; color:black; border: 1.5px solid black;">${lastTransactionBatch.reason}</td>
      </tr>`).join('');

    const emptyRowsCount = Math.max(0, 15 - lastTransactionBatch.items.length);
    const emptyRows = Array(emptyRowsCount).fill('<tr><td style="height:35px; border: 1.5px solid black;">&nbsp;</td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td></tr>').join('');

    const printWin = window.open('', '_blank');
    if (!printWin) return;
    printWin.document.write(`
      <html><head><title>單據_${lastTransactionBatch.id}</title><style>
            body { font-family: '標楷體','DFKai-SB',serif; padding: 60px; color: black; background: white; }
            .title { text-align: center; font-size: 26pt; font-weight: bold; margin-bottom: 25px; }
            .checkbox-area { display: flex; justify-content: center; gap: 40px; font-size: 16pt; margin-bottom: 25px; }
            table { width: 100%; border-collapse: collapse; border: 2.5px solid black; }
            th { border: 1.5px solid black; padding: 10px; font-size: 14pt; background: #f2f2f2; }
            td { border: 1.5px solid black; }
          </style></head><body>
          <div style="text-align:right; font-size:10pt;">單號：${lastTransactionBatch.id}</div>
          <div class="title">台灣電力公司電力修護處南部分處</div>
          <div class="checkbox-area"><div>[ ${isEquip ? 'V' : ' '} ] 安全衛生設備借用單</div><div>[ ${!isEquip ? 'V' : ' '} ] 安全衛生耗材領用單</div></div>
          <div style="display:flex; justify-content:space-between; margin-bottom:10px; font-weight:bold; font-size:14pt;"><div>部門：${lastTransactionBatch.dept}</div><div>日期：${date.getFullYear()-1911}年${date.getMonth()+1}月${date.getDate()}日</div></div>
          <table><thead><tr><th>名稱</th><th>規範</th><th>單位</th><th>數量</th><th>備註</th></tr></thead><tbody>${rows}${emptyRows}</tbody></table>
          <div style="margin-top:40px; display:flex; justify-content:space-between; font-weight:bold; font-size:14pt;"><span>申請：${lastTransactionBatch.person}</span><span>經辦：__________</span><span>主管：__________</span></div>
          <script>window.onload = () => { setTimeout(() => { window.print(); window.close(); }, 600); };</script></body></html>
    `);
    printWin.document.close();
  };

  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = { 
      name: formData.get('name') as string, 
      itemType: formData.get('itemType') as ItemType, 
      unit: formData.get('unit') as string, 
      spec: formData.get('spec') as string, 
      quantity: Number(formData.get('quantity')), 
      minStock: Number(formData.get('minStock')), 
    };
    let updated;
    if (editTarget) {
      updated = items.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i);
      setItems(updated); setEditTarget(null);
    } else {
      updated = [...items, { id: generateId(), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: Date.now() }];
      setItems(updated); setShowAddModal(false);
    }
    syncToCloud(updated, logs);
  };

  const stats = useMemo(() => {
    // 強化統計邏輯，過濾年份與部門
    const filteredLogs = logs.filter(l => {
        const matchYear = statsYearFilter === 'ALL' || new Date(l.timestamp).getFullYear().toString() === statsYearFilter;
        const matchDept = statsDeptFilter === 'ALL' || l.dept === statsDeptFilter;
        return l.type === 'OUT' && matchYear && matchDept;
    });

    const invDetailMap: Record<string, {name: string, qty: number}> = {};
    filteredLogs.forEach(log => {
        if (!invDetailMap[log.itemId]) invDetailMap[log.itemId] = { name: log.itemName, qty: 0 };
        invDetailMap[log.itemId].qty += log.quantity;
    });

    const deptMap: Record<string, number> = {};
    // 部門佔比計算應基於選中的年份，但不應受部門過濾器影響，否則永遠是 100%
    const logsForDeptRanking = logs.filter(l => {
        const matchYear = statsYearFilter === 'ALL' || new Date(l.timestamp).getFullYear().toString() === statsYearFilter;
        return l.type === 'OUT' && matchYear;
    });
    logsForDeptRanking.forEach(l => {
        deptMap[l.dept] = (deptMap[l.dept] || 0) + l.quantity;
    });

    return {
      totalQty: filteredLogs.reduce((acc, curr) => acc + curr.quantity, 0),
      details: Object.values(invDetailMap).sort((a, b) => b.qty - a.qty),
      deptRanking: Object.entries(deptMap).sort((a, b) => b[1] - a[1])
    };
  }, [logs, statsDeptFilter, statsYearFilter]);

  return (
