      {showPrintModal && lastTransactionBatch && (
        <div className="fixed inset-0 bg-slate-950/95 z-[700] flex items-center justify-center p-8">
          <div className="bg-white rounded-[3rem] w-full max-w-4xl h-[90vh] overflow-hidden flex flex-col shadow-2xl animate-in zoom-in">
            <div className="p-8 border-b flex justify-between items-center bg-white relative z-10 shadow-sm">
              <h3 className="text-2xl font-black flex items-center gap-3 text-slate-950"><CheckCircle2 className="text-emerald-500"/> 領用單預覽 (A4 格式)</h3>
              <div className="flex gap-4">
                <button onClick={handleFinalPrint} className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black flex items-center gap-3 shadow-xl hover:bg-blue-700 transition-all active:scale-95"><Printer size={22}/> 列印單據</button>
                <button onClick={()=>setShowPrintModal(false)} className="bg-slate-100 p-4 rounded-2xl hover:bg-slate-200 transition-all text-slate-500"><X size={24}/></button>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-12 bg-slate-200 flex justify-center custom-scrollbar">
              <div className="bg-white p-20 shadow-2xl border-2 border-slate-300 w-[210mm] h-fit font-serif text-black text-left">
                <h1 className="text-center text-4xl font-bold border-b-4 border-double border-black pb-5 mb-10">台灣電力公司電力修護處南部分處</h1>
                <p className="text-center text-2xl font-bold mb-12 underline underline-offset-[12px]">工安物資領用明細單 (單號: {lastTransactionBatch.id})</p>
                <div className="flex justify-between mb-8 font-bold text-xl"><span>領用部門：{lastTransactionBatch.dept}</span><span>日期：{new Date(lastTransactionBatch.timestamp).toLocaleDateString()}</span></div>
                <table className="w-full border-2 border-black mb-10">
                  <thead><tr className="bg-slate-50 border-b-2 border-black font-bold text-center">
                    <th className="border-r border-black p-4">物資名稱</th><th className="border-r border-black p-4">單位</th><th className="p-4">領用數量</th>
                  </tr></thead>
                  <tbody>
                    {lastTransactionBatch.items.map((it,idx)=><tr key={idx} className="border-b border-black text-center font-bold text-2xl">
                      <td className="border-r border-black p-6">{it.name}</td><td className="border-r border-black p-6">{it.unit || '個'}</td><td className="p-6">{it.quantity}</td>
                    </tr>)}
                  </tbody>
                </table>
                <div className="mt-24 flex justify-between font-bold text-2xl px-6"><span>領用人簽章：{lastTransactionBatch.person}</span><span>經辦：__________</span><span>主管：__________</span></div>
                <div className="mt-20 text-right text-slate-400 text-sm italic font-sans">系統生成單據 · 僅供內部作業存查</div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  Stethoscope,
  ShoppingCart,
  CheckCircle2,
  Users,
  Download,
  Upload,
  RefreshCw,
  Clock,
  Info,
  ArrowUpRight,
  ArrowDownLeft,
  Settings,
  FileDown
} from 'lucide-react';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';

// --- 正式雲端 GAS 網址 ---
const DEFAULT_GAS_URL = 'https://script.google.com/macros/s/AKfycbxQmoG0pHHm2tuzt9Og3eAGOTYSUd1d61orWOEygS9qmjQ9LUaC3WsvwCHfjV9wh_Q2/exec'; 

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

type SyncStatus = 'synced' | 'syncing' | 'error' | 'local';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || DEFAULT_GAS_URL);
  const [syncStatus, setSyncStatus] = useState<SyncStatus>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '從未同步');
  const [showSettings, setShowSettings] = useState(false);

  const [statsDeptFilter, setStatsDeptFilter] = useState<string>('ALL');
  const [statsYearFilter, setStatsYearFilter] = useState<string>('ALL'); // 預設改為 ALL 以免過濾器過嚴

  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    id: string; dept: string; person: string; reason: string; items: BasketItem[]; timestamp: number;
  } | null>(null);

  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const initLoad = async () => {
      const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
      const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
      if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
      if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
      setIsLoaded(true);
      if (gasUrl) fetchFromCloud();
    };
    initLoad();
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const updateSyncTime = () => {
    const now = new Date().toLocaleTimeString('zh-TW', { hour12: false, hour: '2-digit', minute: '2-digit' });
    const fullTime = `${new Date().toLocaleDateString('zh-TW')} ${now}`;
    setLastSyncTime(fullTime);
    localStorage.setItem(STORAGE_KEY_LAST_SYNC, fullTime);
  };

  const syncToCloud = async (currentItems: InventoryItem[], currentLogs: Transaction[]) => {
    if (!gasUrl) { setSyncStatus('local'); return; }
    setSyncStatus('syncing');
    try {
      const payload = { items: currentItems, logs: currentLogs, timestamp: Date.now() };
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify(payload), mode: 'no-cors' });
      setSyncStatus('synced');
      updateSyncTime();
    } catch (err) {
      setSyncStatus('error');
    }
  };

  const fetchFromCloud = async () => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const response = await fetch(gasUrl);
      const data = await response.json();
      if (data && data.items && data.logs) {
        setItems(data.items);
        setLogs(data.logs);
        setSyncStatus('synced');
        updateSyncTime();
      }
    } catch (err) {
      setSyncStatus('error');
    }
  };

  const handleGasUrlSave = (newUrl: string) => {
    const cleanUrl = newUrl.trim();
    const finalUrl = cleanUrl === '' ? DEFAULT_GAS_URL : cleanUrl;
    setGasUrl(finalUrl);
    if (cleanUrl === '') localStorage.removeItem(STORAGE_KEY_GAS_URL);
    else localStorage.setItem(STORAGE_KEY_GAS_URL, cleanUrl);
    setShowSettings(false);
    if (finalUrl) fetchFromCloud();
  };

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;
  const getReservedQty = (itemId: string) => basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);

  const processIssuance = () => {
    if (basket.length === 0) return;
    const timestamp = Date.now();
    const batchId = generateId();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(bItem => {
      updatedItems = updatedItems.map(item => {
        if (item.id === bItem.itemId) {
          const newQty = issuanceMode === 'IN' ? item.quantity + bItem.quantity : item.quantity - bItem.quantity;
          return { ...item, quantity: newQty, lastUpdated: timestamp };
        }
        return item;
      });
      newLogs.push({ 
        id: generateId() + Math.random().toString(36).substr(2, 4), 
        itemId: bItem.itemId, 
        itemName: bItem.name, 
        type: issuanceMode, 
        quantity: bItem.quantity, 
        person: inputPerson || '未填寫', 
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處', 
        reason: inputReason, 
        timestamp: timestamp 
      });
    });

    const finalLogs = [...newLogs, ...logs];
    setItems(updatedItems);
    setLogs(finalLogs);
    syncToCloud(updatedItems, finalLogs);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({ id: batchId, dept: selectedDept, person: inputPerson, reason: inputReason, items: [...basket], timestamp: timestamp });
      setShowPrintModal(true);
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  const handleFinalPrint = () => {
    if (!lastTransactionBatch) return;
    const date = new Date(lastTransactionBatch.timestamp);
    const isEquip = lastTransactionBatch.items.some(it => it.itemType === 'EQUIPMENT');

    const rows = lastTransactionBatch.items.map(item => `
      <tr>
        <td style="text-align:center; color:black; padding: 12px; border: 1.5px solid black;">${item.name}</td>
        <td style="text-align:center; color:black; border: 1.5px solid black;">${item.spec || ''}</td>
        <td style="text-align:center; color:black; border: 1.5px solid black;">${item.unit}</td>
        <td style="text-align:center; font-size:18pt; font-weight:bold; color:black; border: 1.5px solid black;">${item.quantity}</td>
        <td style="text-align:center; color:black; border: 1.5px solid black;">${lastTransactionBatch.reason}</td>
      </tr>`).join('');

    const emptyRowsCount = Math.max(0, 15 - lastTransactionBatch.items.length);
    const emptyRows = Array(emptyRowsCount).fill('<tr><td style="height:35px; border: 1.5px solid black;">&nbsp;</td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td></tr>').join('');

    const printWin = window.open('', '_blank');
    if (!printWin) return;
    printWin.document.write(`
      <html><head><title>單據_${lastTransactionBatch.id}</title><style>
            body { font-family: '標楷體','DFKai-SB',serif; padding: 60px; color: black; background: white; }
            .title { text-align: center; font-size: 26pt; font-weight: bold; margin-bottom: 25px; }
            .checkbox-area { display: flex; justify-content: center; gap: 40px; font-size: 16pt; margin-bottom: 25px; }
            table { width: 100%; border-collapse: collapse; border: 2.5px solid black; }
            th { border: 1.5px solid black; padding: 10px; font-size: 14pt; background: #f2f2f2; }
            td { border: 1.5px solid black; }
          </style></head><body>
          <div style="text-align:right; font-size:10pt;">單號：${lastTransactionBatch.id}</div>
          <div class="title">台灣電力公司電力修護處南部分處</div>
          <div class="checkbox-area"><div>[ ${isEquip ? 'V' : ' '} ] 安全衛生設備借用單</div><div>[ ${!isEquip ? 'V' : ' '} ] 安全衛生耗材領用單</div></div>
          <div style="display:flex; justify-content:space-between; margin-bottom:10px; font-weight:bold; font-size:14pt;"><div>部門：${lastTransactionBatch.dept}</div><div>日期：${date.getFullYear()-1911}年${date.getMonth()+1}月${date.getDate()}日</div></div>
          <table><thead><tr><th>名稱</th><th>規範</th><th>單位</th><th>數量</th><th>備註</th></tr></thead><tbody>${rows}${emptyRows}</tbody></table>
          <div style="margin-top:40px; display:flex; justify-content:space-between; font-weight:bold; font-size:14pt;"><span>申請：${lastTransactionBatch.person}</span><span>經辦：__________</span><span>主管：__________</span></div>
          <script>window.onload = () => { setTimeout(() => { window.print(); window.close(); }, 600); };</script></body></html>
    `);
    printWin.document.close();
  };

  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = { 
      name: formData.get('name') as string, 
      itemType: formData.get('itemType') as ItemType, 
      unit: formData.get('unit') as string, 
      spec: formData.get('spec') as string, 
      quantity: Number(formData.get('quantity')), 
      minStock: Number(formData.get('minStock')), 
    };
    let updated;
    if (editTarget) {
      updated = items.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i);
      setItems(updated); setEditTarget(null);
    } else {
      updated = [...items, { id: generateId(), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: Date.now() }];
      setItems(updated); setShowAddModal(false);
    }
    syncToCloud(updated, logs);
  };

  const stats = useMemo(() => {
    // 過濾出庫紀錄以進行統計
    const filteredLogs = logs.filter(l => {
        const matchYear = statsYearFilter === 'ALL' || new Date(l.timestamp).getFullYear().toString() === statsYearFilter;
        const matchDept = statsDeptFilter === 'ALL' || l.dept === statsDeptFilter;
        return l.type === 'OUT' && matchYear && matchDept;
    });

    const invDetailMap: Record<string, {name: string, qty: number}> = {};
    const medDetailMap: Record<string, {name: string, qty: number}> = {};

    filteredLogs.forEach(log => {
        const item = items.find(it => it.id === log.itemId);
        const group = item?.itemGroup || 'INVENTORY';
        const targetMap = group === 'MEDICINE' ? medDetailMap : invDetailMap;

        if (!targetMap[log.itemId]) targetMap[log.itemId] = { name: log.itemName, qty: 0 };
        targetMap[log.itemId].qty += log.quantity;
    });

    // 部門排行應該不受「部門篩選器」影響，只受「年度篩選器」影響
    const deptRankingLogs = logs.filter(l => {
        const matchYear = statsYearFilter === 'ALL' || new Date(l.timestamp).getFullYear().toString() === statsYearFilter;
        return l.type === 'OUT' && matchYear;
    });
    const deptMap: Record<string, number> = {};
    deptRankingLogs.forEach(l => {
        deptMap[l.dept] = (deptMap[l.dept] || 0) + l.quantity;
    });

    return {
      totalQty: filteredLogs.reduce((acc, curr) => acc + curr.quantity, 0),
      invDetails: Object.values(invDetailMap).sort((a, b) => b.qty - a.qty),
      medDetails: Object.values(medDetailMap).sort((a, b) => b.qty - a.qty),
      deptRanking: Object.entries(deptMap).sort((a, b) => b[1] - a[1])
    };
  }, [items, logs, statsDeptFilter, statsYearFilter]);

  const handleDeleteItem = () => {
    if (!deleteTarget) return;
    const newItems = items.filter(i => i.id !== deleteTarget.id);
    setItems(newItems);
    syncToCloud(newItems, logs);
    setDeleteTarget(null);
  };

  return (
    <div className="min-h-screen flex bg-slate-100 text-slate-950 font-sans">
      <style>{`
        input, select, textarea { color: #000 !important; background-color: #fff !important; border: 2px solid #94a3b8 !important; font-weight: 700 !important; }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
        * { color: inherit; } 
        .high-contrast-text { color: #0f172a !important; font-weight: 800; }
      `}</style>

      {/* 側邊欄 */}
      <aside className="w-72 bg-slate-900 text-white p-6 flex flex-col shrink-0 border-r border-slate-800 shadow-2xl">
        <div className="mb-8">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22}/></div>
            <h1 className="font-black text-xl tracking-tight">工安管理系統</h1>
          </div>
          <div className="mt-6 bg-slate-800/50 rounded-2xl p-4 border border-slate-700/50 text-white">
            <div className="flex items-center justify-between mb-2">
              <span className="text-[10px] font-black text-slate-400 uppercase">雲端同步狀態</span>
              <div className={`w-3 h-3 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.8)]' : syncStatus === 'syncing' ? 'bg-amber-500 animate-pulse' : 'bg-red-500'}`}></div>
            </div>
            <div className="text-sm font-black">{syncStatus === 'synced' ? '數據已同步' : syncStatus === 'syncing' ? '正在連線...' : '本地運作中'}</div>
            <div className="flex items-center gap-1.5 text-[10px] text-slate-400 font-bold mt-1"><Clock size={10}/> {lastSyncTime}</div>
          </div>
        </div>
        <nav className="flex-1 space-y-1">
          {[ 
            { id: 'inventory', label: '工安耗材管理', icon: Package }, 
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope }, 
            { id: 'issuance', label: '領用補貨作業', icon: FileText }, 
            { id: 'history', label: '歷史異動日誌', icon: History }, 
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard }, 
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}>
              <tab.icon size={20} /> {tab.label}
            </button>
          ))}
        </nav>
        <div className="pt-6 mt-6 border-t border-slate-800 space-y-2">
            <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-black text-slate-300 hover:bg-slate-800"><Settings size={16}/> 同步網址設定</button>
            <button onClick={fetchFromCloud} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800"><RefreshCw size={16}/> 手動更新數據</button>
        </div>
      </aside>

      <main className="flex-1 p-10 overflow-y-auto bg-slate-50">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-3xl font-black text-slate-900">{activeTab === 'inventory' ? '工安耗材清冊' : activeTab === 'medicine' ? '急救藥材清冊' : activeTab === 'issuance' ? '領用 / 補貨登記' : activeTab === 'history' ? '歷史異動日誌' : '數據統計看板'}</h2>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-black shadow-xl"><Plus size={18}/> 新增項目</button>
          )}
        </header>

        {/* 領用/入庫 */}
        {activeTab === 'issuance' && (
          <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
            <div className="lg:col-span-2 bg-white p-8 rounded-3xl shadow-xl border border-slate-200">
              <h3 className="text-xl font-black mb-8 flex items-center gap-2 text-slate-900"><ShoppingCart className="text-blue-500"/> 1. 挑選項目</h3>
              <div className="flex bg-slate-100 p-1 rounded-xl mb-6 font-bold">
                <button onClick={()=>setIssuanceMode('OUT')} className={`flex-1 py-3 rounded-lg ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button>
                <button onClick={()=>setIssuanceMode('IN')} className={`flex-1 py-3 rounded-lg ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
              </div>
              <div className="space-y-6">
                <div><label className="text-xs font-black text-slate-400 uppercase">群組</label>
                  <div className="flex gap-2 mt-2">
                    <button onClick={()=>setIssuanceGroup('INVENTORY')} className={`flex-1 py-3 rounded-xl font-bold border-2 ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-200 text-slate-400'}`}>耗材類</button>
                    <button onClick={()=>setIssuanceGroup('MEDICINE')} className={`flex-1 py-3 rounded-xl font-bold border-2 ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-200 text-slate-400'}`}>藥材類</button>
                  </div>
                </div>
                <div><label className="text-xs font-black text-slate-400">選擇品項</label>
                  <select className="w-full p-4 rounded-xl mt-2 font-black text-slate-900" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                    <option value="">-- 請選擇 --</option>
                    {items.filter(i => i.itemGroup === issuanceGroup).map(i => <option key={i.id} value={i.id}>{i.name} (剩餘:{i.quantity - getReservedQty(i.id)})</option>)}
                  </select>
                </div>
                <div><label className="text-xs font-black text-slate-400">數量</label><input type="number" className="w-full p-4 rounded-xl mt-2 font-black text-slate-950" value={inputQty} onChange={e=>setInputQty(e.target.value)}/></div>
                <button onClick={() => {
                  const item = items.find(i=>i.id===selectedItemId);
                  if(!item) return;
                  setBasket([...basket, { itemId: item.id, name: item.name, quantity: Number(inputQty), unit: item.unit, spec: item.spec, itemType: item.itemType }]);
                  setSelectedItemId(''); setInputQty('1');
