              </div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-xs font-black text-slate-400 uppercase">單位</label><input name="unit" className="w-full p-3 rounded-xl mt-1 font-black text-slate-950" defaultValue={editTarget?.unit||'個'} required/></div>
                <div><label className="text-xs font-black text-slate-400 uppercase">性質</label><select name="itemType" className="w-full p-3 rounded-xl mt-1 font-black text-slate-950" defaultValue={editTarget?.itemType||'CONSUMABLE'}><option value="CONSUMABLE">消耗品</option><option value="EQUIPMENT">借用設備</option></select></div>
