                <button type="button" onClick={()=>{setShowAddModal(false);setEditTarget(null);}} className="w-full py-2 text-slate-400 font-bold hover:text-slate-600">取消</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* 彈窗：列印預覽 */}
      {showPrintModal && lastTransactionBatch && (
        <div className="fixed inset-0 bg-slate-950/95 z-[700] flex items-center justify-center p-8">
          <div className="bg-white rounded-[3rem] w-full max-w-4xl h-[90vh] overflow-hidden flex flex-col shadow-2xl animate-in zoom-in">
            <div className="p-8 border-b flex justify-between items-center bg-white relative z-10 shadow-sm">
              <h3 className="text-2xl font-black flex items-center gap-3 text-slate-950"><CheckCircle2 className="text-emerald-500"/> 領用單預覽 (A4 規格)</h3>
              <div className="flex gap-4">
                <button onClick={handleFinalPrint} className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black flex items-center gap-2 shadow-xl hover:bg-blue-700 transition-all active:scale-95"><Printer size={20}/> 列印單據</button>
                <button onClick={()=>setShowPrintModal(false)} className="bg-slate-100 p-4 rounded-2xl hover:bg-slate-200 text-slate-500 transition-all"><X size={24}/></button>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-12 bg-slate-200 flex justify-center custom-scrollbar">
              <div className="bg-white p-20 shadow-2xl border-2 border-slate-300 w-[210mm] h-fit font-serif text-black text-left">
                <h1 className="text-center text-4xl font-bold border-b-4 border-double border-black pb-5 mb-10">台灣電力公司電力修護處南部分處</h1>
                <p className="text-center text-2xl font-bold mb-12 underline underline-offset-[12px]">工安物資領用明細單 (單號: {lastTransactionBatch.id})</p>
                <div className="flex justify-between mb-8 font-bold text-xl"><span>領用部門：{lastTransactionBatch.dept}</span><span>日期：{new Date(lastTransactionBatch.timestamp).toLocaleDateString()}</span></div>
                <table className="w-full border-2 border-black mb-10">
                  <thead><tr className="bg-slate-50 border-b-2 border-black font-bold text-center">
                    <th className="border-r border-black p-3">名稱</th><th className="border-r border-black p-3">單位</th><th className="p-3">數量</th>
                  </tr></thead>
                  <tbody>
                    {lastTransactionBatch.items.map((it,idx)=><tr key={idx} className="border-b border-black text-center font-bold text-2xl">
                      <td className="border-r border-black p-6">{it.name}</td><td className="border-r border-black p-6">{it.unit || '個'}</td><td className="p-6">{it.quantity}</td>
                    </tr>)}
                  </tbody>
                </table>
                <div className="mt-24 flex justify-between font-bold text-2xl px-6"><span>領用人簽章：{lastTransactionBatch.person}</span><span>經辦：__________</span><span>主管：__________</span></div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

