                  <select className="w-full p-4 rounded-xl mt-2 text-slate-950 font-black" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                    <option value="">-- 請選擇 --</option>
                    {items.filter(i => i.itemGroup === issuanceGroup).map(i => <option key={i.id} value={i.id}>{i.name} (剩餘:{i.quantity - getReservedQty(i.id)})</option>)}
                  </select>
                </div>
                <div><label className="text-xs font-black text-slate-400">數量</label><input type="number" className="w-full p-4 rounded-xl mt-2 font-black text-slate-950" value={inputQty} onChange={e=>setInputQty(e.target.value)}/></div>
                <button onClick={addToBasket} disabled={!selectedItemId} className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black text-xl shadow-lg disabled:opacity-50 transition-all active:scale-95">加入處理清單</button>
              </div>
            </div>
            <div className="lg:col-span-3 bg-white p-8 rounded-3xl shadow-xl border border-slate-200 flex flex-col">
