                {basket.length === 0 && <div className="h-full flex items-center justify-center text-slate-300 font-bold opacity-50 text-xl">目前清單為空</div>}
                {basket.map((b,i) => <div key={i} className="flex justify-between p-4 bg-white rounded-xl mb-2 shadow-sm font-black border border-slate-100 text-slate-900"><span>{b.name}</span><div className="flex items-center gap-4"><span>{b.quantity} {b.unit}</span><button onClick={()=>setBasket(basket.filter((_,idx)=>idx!==i))} className="text-red-400 hover:text-red-600"><X size={18}/></button></div></div>)}
              </div>
              {issuanceMode === 'OUT' && (
                <div className="grid grid-cols-2 gap-4 mb-6 font-bold">
                  <div><label className="text-xs font-black text-slate-400 uppercase">領用部門</label><select className="w-full p-3 rounded-xl mt-2 text-slate-950" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>{DEPARTMENTS.map(d=><option key={d} value={d}>{d}</option>)}</select></div>
                  <div><label className="text-xs font-black text-slate-400 uppercase">領用人</label><input type="text" className="w-full p-3 rounded-xl mt-2 text-slate-950" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div>
                </div>
              )}
              <button onClick={processIssuance} disabled={basket.length === 0} className={`w-full py-6 rounded-2xl font-black text-3xl text-white shadow-2xl transition-all active:scale-95 ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>確認並存檔</button>
            </div>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in">
            <div className="flex gap-4">
              <div className="flex-1"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">統計年份</label><select className="w-full p-2 rounded-xl mt-1 font-bold text-slate-950" value={statsYearFilter} onChange={e => setStatsYearFilter(Number(e.target.value))}><option value={2024}>2024 年度</option><option value={2025}>2025 年度</option></select></div>
              <div className="flex-1"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">部門篩選</label><select className="w-full p-2 rounded-xl mt-1 font-bold text-slate-950" value={statsDeptFilter} onChange={e => setStatsDeptFilter(e.target.value)}><option value="ALL">全廠總覽</option>{DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}</select></div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-slate-900 p-10 rounded-[2.5rem] text-white shadow-xl">
                <p className="text-blue-400 text-xs font-black uppercase tracking-widest mb-2">所選期間領用總量</p>
                <h3 className="text-6xl font-black text-white">{stats.totalQty} <span className="text-2xl ml-2">件</span></h3>
              </div>
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border-t-8 border-blue-500 overflow-hidden">
                <h4 className="font-black text-xl mb-4 text-slate-900">熱門領用耗材 (Top 5)</h4>
                <div className="space-y-3">
                  {stats.invDetails.length === 0 ? <p className="text-slate-300 font-bold py-10 text-center">目前無統計數據</p> : stats.invDetails.slice(0,5).map((it: any) => (
                    <div key={it.name} className="flex justify-between items-center p-3 bg-slate-50 rounded-xl font-black border border-slate-100 transition-all hover:bg-slate-100">
                      <span className="text-slate-800">{it.name}</span>
                      <span className="bg-blue-100 text-blue-600 px-3 py-1 rounded-lg">{it.qty} 件</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="bg-white p-10 rounded-[2.5rem] shadow-xl border border-slate-200">
              <h4 className="font-black text-xl mb-6 text-slate-900 flex items-center gap-2 border-b pb-4"><LayoutDashboard className="text-blue-500"/> 各部門領用佔比分析</h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-4">
                  {stats.deptRanking.map(([dept, qty]: any, idx: number) => (
                    <div key={dept} className="relative">
                      <div className="flex justify-between mb-1 font-black text-slate-800">
                        <span>{idx + 1}. {dept}</span>
                        <span>{qty} 件</span>
                      </div>
                      <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden shadow-inner">
                        <div className="bg-blue-600 h-full transition-all duration-1000" style={{ width: `${(qty / (stats.totalQty || 1)) * 100}%` }} />
                      </div>
                    </div>
                  ))}
                  {stats.deptRanking.length === 0 && <p className="text-slate-300 font-bold py-10 text-center">查無部門領用紀錄</p>}
                </div>
                <div className="bg-slate-50 rounded-[2rem] p-8 flex flex-col justify-center border border-slate-100">
                  <div className="flex items-center gap-4 mb-4">
                    <div className="p-3 bg-blue-100 text-blue-600 rounded-2xl"><Info size={24}/></div>
                    <h5 className="font-black text-slate-800 text-lg">數據統計細項</h5>
                  </div>
                  <div className="max-h-[250px] overflow-y-auto custom-scrollbar space-y-2 font-bold text-slate-600">
                    {stats.invDetails.concat(stats.medDetails).map((d, i) => (
                      <div key={i} className="flex justify-between border-b pb-1"><span>{d.name}</span><span>{d.qty} 件</span></div>
                    ))}
                    {stats.invDetails.length === 0 && stats.medDetails.length === 0 && <p className="text-slate-400">尚無詳細領用數據</p>}
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden text-slate-950">
            <div className="p-4 bg-slate-50 border-b flex items-center gap-4">
              <Search className="text-slate-400"/>
              <input type="text" placeholder="搜尋項目名稱..." className="bg-transparent border-none outline-none w-full font-black text-slate-950" value={searchTerm} onChange={e=>setSearchTerm(e.target.value)}/>
            </div>
            <table className="w-full text-left">
              <thead className="bg-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b">
                <tr><th className="px-8 py-5">名稱及規格</th><th className="px-8 py-5 text-center">目前庫存</th><th className="px-8 py-5 text-right">操作</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100 font-black">
                {items.filter(i => (activeTab==='medicine' ? i.itemGroup==='MEDICINE' : i.itemGroup==='INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-8 py-5">
                      <div className="text-lg text-slate-900">{item.name}</div>
                      <div className="text-xs text-slate-500 font-bold mt-1">{item.spec || '無規格'}</div>
                    </td>
                    <td className="px-8 py-5 text-center">
                      <span className={`px-5 py-2 rounded-xl font-black text-lg shadow-sm ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600 border border-red-200 animate-pulse' : 'bg-emerald-50 text-emerald-600 border border-emerald-100'}`}>
                        {item.quantity} {item.unit}
                      </span>
                    </td>
                    <td className="px-8 py-5 text-right flex justify-end gap-2">
                      <button onClick={()=>setEditTarget(item)} className="p-3 text-slate-300 hover:text-blue-600 transition-colors"><Edit3 size={20}/></button>
                      <button onClick={()=>setDeleteTarget({id: item.id, name: item.name})} className="p-3 text-slate-300 hover:text-red-600 transition-colors"><Trash2 size={20}/></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden text-slate-900">
            <table className="w-full text-left">
              <thead className="bg-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b">
                <tr><th className="px-6 py-4">時間</th><th className="px-6 py-4">品項數量</th><th className="px-6 py-4">類型</th><th className="px-6 py-4">部門/經手人</th><th className="px-6 py-4 text-right">單據</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100 font-black text-slate-800">
                {logs.map(log => (
                  <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4 text-slate-400 text-xs">{new Date(log.timestamp).toLocaleString()}</td>
                    <td className="px-6 py-4">{log.itemName} ({log.quantity})</td>
                    <td className="px-6 py-4">{log.type==='OUT' ? <span className="text-blue-600 bg-blue-50 px-2 py-1 rounded text-xs">出庫</span> : <span className="text-emerald-600 bg-emerald-50 px-2 py-1 rounded text-xs">入庫</span>}</td>
                    <td className="px-6 py-4 font-bold text-slate-600">{log.dept} / {log.person}</td>
                    <td className="px-6 py-4 text-right">
                      {log.type==='OUT' && (
                        <button onClick={()=>{ 
                          setLastTransactionBatch({ id: log.id, dept: log.dept, person: log.person, reason: log.reason, items: [{itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '個', spec: '', itemType: 'CONSUMABLE'}], timestamp: log.timestamp }); 
                          setShowPrintModal(true); 
                        }} className="text-slate-300 hover:text-blue-600"><Printer size={18}/></button>
                      )}
