            <div className="space-y-6">
              <div><label className="text-[10px] font-black text-slate-400 uppercase">GAS Web App URL</label><input type="text" className="w-full p-4 rounded-xl mt-2 font-black text-slate-950" defaultValue={localStorage.getItem(STORAGE_KEY_GAS_URL) || ''} id="gas-url-input" placeholder="尚未貼上網址"/></div>
              <div className="bg-blue-50 p-6 rounded-2xl border border-blue-100"><p className="text-sm font-bold text-blue-700 leading-relaxed text-black">系統已預填專屬後台網址。如有自行部署的版本，可在此覆蓋。留空則會自動恢復預設連結。</p></div>
              <div className="flex gap-4">
                <button onClick={() => handleGasUrlSave((document.getElementById('gas-url-input') as HTMLInputElement).value)} className="flex-1 py-4 bg-slate-900 text-white rounded-2xl font-black shadow-xl transition-all active:scale-95">儲存並重啟連線</button>
                <button onClick={()=>setShowSettings(false)} className="px-10 py-4 bg-slate-100 text-slate-600 rounded-2xl font-black">返回</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {deleteTarget && (
