          <div class="dept-row"><div>部 門：<span style="border-bottom: 2px dotted black; min-width: 350px; display: inline-block; text-align: center;">${lastTransactionBatch.dept}</span></div><div>${date.getFullYear() - 1911} 年 ${date.getMonth() + 1} 月 ${date.getDate()} 日</div></div>
          <table><thead><tr><th style="width:35%; color:black !important;">名　　　稱</th><th style="width:25%; color:black !important;">規　範（序　號）</th><th style="width:10%; color:black !important;">單 位</th><th style="width:10%; color:black !important;">數 量</th><th style="width:20%; color:black !important;">備　　註</th></tr></thead><tbody>${rows}${emptyRows}</tbody></table>
          <div class="footer-row"><div style="display: flex; justify-content: space-between; color:black !important;"><div style="flex:1">申請部門：</div><div style="flex:1">經管部門：</div></div><div class="sig-area"><div style="flex:1; display:flex; justify-content:space-around; padding: 0 15px; color:black !important;"><span>經辦：</span><span>課長：</span><span>經理：</span></div><div style="flex:1; display:flex; justify-content:space-around; padding: 0 15px; color:black !important;"><span>經辦：</span><span>課長：</span><span>經理：</span></div></div></div>
          <script>window.onload = () => { setTimeout(() => { window.print(); window.close(); }, 600); };</script></body></html>
    `);
    printWin.document.close();
  };

  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = { 
      name: formData.get('name') as string, 
      itemType: formData.get('itemType') as ItemType, 
      unit: formData.get('unit') as string, 
      spec: formData.get('spec') as string, 
      quantity: Number(formData.get('quantity')), 
      minStock: Number(formData.get('minStock')), 
    };
    let updated;
    if (editTarget) {
      updated = items.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i);
      setItems(updated); setEditTarget(null);
    } else {
      updated = [...items, { 
        id: generateId(), 
        ...data, 
        itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', 
        category: Category.OTHER, 
        description: '', 
        lastUpdated: Date.now() 
      }];
      setItems(updated); setShowAddModal(false);
    }
    syncToCloud(updated, logs);
  };

  const stats = useMemo(() => {
    const filteredLogs = logs.filter(l => {
        const logDate = new Date(l.timestamp);
        return l.type === 'OUT' && logDate.getFullYear() === statsYearFilter && (statsDeptFilter === 'ALL' || l.dept === statsDeptFilter);
    });
    const invDetailMap: Record<string, {name: string, qty: number}> = {};
    const medDetailMap: Record<string, {name: string, qty: number}> = {};
    filteredLogs.forEach(log => {
        const item = items.find(it => it.id === log.itemId);
        const targetMap = item?.itemGroup === 'MEDICINE' ? medDetailMap : invDetailMap;
        if (!targetMap[log.itemId]) targetMap[log.itemId] = { name: log.itemName, qty: 0 };
        targetMap[log.itemId].qty += log.quantity;
    });
    return {
      invQty: Object.values(invDetailMap).reduce((a,b)=>a+b.qty, 0),
      medQty: Object.values(medDetailMap).reduce((a,b)=>a+b.qty, 0),
      invDetails: Object.values(invDetailMap).sort((a, b) => b.qty - a.qty),
      medDetails: Object.values(medDetailMap).sort((a, b) => b.qty - a.qty),
      deptRanking: Object.entries(logs.filter(l => l.type === 'OUT' && new Date(l.timestamp).getFullYear() === statsYearFilter).reduce((acc: any, curr) => { acc[curr.dept] = (acc[curr.dept] || 0) + curr.quantity; return acc; }, {})).sort((a: any, b: any) => b[1] - a[1])
    };
  }, [items, logs, statsDeptFilter, statsYearFilter]);

  return (
    <div className="min-h-screen flex bg-slate-100 text-black font-sans">
      <aside className="w-72 bg-slate-900 text-white p-6 flex flex-col shrink-0 shadow-2xl">
        <div className="flex items-center gap-3 mb-8">
          <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22} className="text-white"/></div>
          <h1 className="font-black text-xl tracking-tight text-white">工安管理系統</h1>
        </div>
        <nav className="flex-1 space-y-1">
          {[ 
            { id: 'inventory', label: '工安耗材管理', icon: Package }, 
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope }, 
            { id: 'issuance', label: '領用補貨作業', icon: FileText }, 
            { id: 'history', label: '歷史異動日誌', icon: History }, 
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard }, 
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}>
              <tab.icon size={20} /> {tab.label}
            </button>
          ))}
        </nav>
        <div className="pt-6 mt-6 border-t border-slate-800 space-y-2">
            <div className={`text-xs px-4 py-2 rounded font-black ${syncStatus==='synced'?'text-emerald-400':'text-amber-400'}`}>{syncStatus==='synced'?'● 雲端已同步':'● 數據更新中...'}</div>
            <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-black text-slate-300 hover:bg-slate-800"><Settings size={16}/> 雲端連線設定</button>
            <button onClick={fetchFromCloud} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800"><RefreshCw size={16}/> 手動重新同步</button>
        </div>
      </aside>

      <main className="flex-1 p-10 overflow-y-auto">
