              <div className="flex-1 overflow-y-auto border-2 border-dashed border-slate-100 rounded-2xl mb-6 min-h-[250px] bg-slate-50">
                {basket.map((b, idx) => (<div key={idx} className="flex justify-between p-4 bg-white rounded-xl mb-2 shadow-sm font-black border border-slate-100 text-black"><span>{b.name}</span><div className="flex items-center gap-4"><span>{b.quantity} {b.unit}</span><button onClick={()=>setBasket(prev => prev.filter((_, i) => i !== idx))} className="text-red-400"><X size={18}/></button></div></div>))}
              </div>
              {issuanceMode === 'OUT' && (
                <div className="grid grid-cols-2 gap-4 mb-6 font-bold text-black">
                  <div><label className="text-xs font-black text-slate-500 uppercase">領用部門</label><select className="w-full p-3 rounded-xl mt-2" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>{DEPARTMENTS.map(d=><option key={d} value={d}>{d}</option>)}</select></div>
                  <div><label className="text-xs font-black text-slate-500 uppercase">領用人</label><input type="text" className="w-full p-3 rounded-xl mt-2" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div>
                </div>
