              <button onClick={processIssuance} disabled={basket.length===0} className={`w-full py-6 rounded-2xl font-black text-3xl text-white shadow-2xl transition-all active:scale-95 ${issuanceMode==='OUT'?'bg-blue-600':'bg-emerald-600'}`}>確認並存檔</button>
            </div>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-slate-900 p-10 rounded-[2.5rem] text-white shadow-xl">
                <p className="text-blue-400 text-xs font-black uppercase tracking-widest mb-2">所選期間領用總量</p>
                <h3 className="text-6xl font-black text-white">{stats.invQty + stats.medQty} <span className="text-2xl ml-2 text-white">件</span></h3>
              </div>
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border-t-8 border-blue-500 text-black">
                <h4 className="font-black text-xl mb-4 text-black">熱門領用排行</h4>
                <div className="space-y-3">{stats.invDetails.slice(0,5).map((it, i) => (<div key={i} className="flex justify-between p-3 bg-slate-50 rounded-xl font-black border"><span>{it.name}</span><span className="text-blue-600">{it.qty} 件</span></div>))}</div>
              </div>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-white p-8 rounded-[2.5rem] shadow-lg"><h4 className="text-xl font-black mb-6 text-black">部門領用比例</h4><div className="space-y-4">{stats.deptRanking.map(([dept, count]: any, idx) => (<div key={idx} className="flex items-center gap-4 bg-slate-50 p-4 rounded-2xl"><div className="w-8 h-8 flex items-center justify-center bg-slate-900 text-white rounded-xl text-xs">{idx + 1}</div><div className="flex-1 font-bold text-black">{dept}</div><div className="font-black text-black">{count} 件</div></div>))}</div></div>
              <div className="space-y-6">
                <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white shadow-2xl"><h4 className="text-2xl font-black flex items-center gap-3 text-white"><BrainCircuit size={28}/> AI 核心建議報告</h4><button onClick={async () => { setIsAiLoading(true); setAiInsights(await getInventoryInsights(items)); setIsAiLoading(false); }} className="w-full mt-6 py-4 bg-blue-600 text-white rounded-2xl font-black text-lg shadow-xl">{isAiLoading ? '分析中...' : '生成報告'}</button></div>
                {aiInsights && (<div className="bg-white p-8 rounded-[2.5rem] text-black font-bold shadow-lg whitespace-pre-wrap">{aiInsights}</div>)}
              </div>
            </div>
          </div>
        )}

        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-200">
            <div className="p-4 bg-slate-50 border-b flex items-center gap-4"><Search className="text-slate-400"/><input type="text" placeholder="搜尋項目..." className="w-full font-black text-black" value={searchTerm} onChange={e=>setSearchTerm(e.target.value)}/></div>
            <table className="w-full text-left font-bold text-black">
              <thead className="bg-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b">
                <tr><th className="px-8 py-5">名稱及規格</th><th className="px-8 py-5 text-center">目前庫存</th><th className="px-8 py-5 text-right">操作</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(i => (activeTab==='medicine' ? i.itemGroup==='MEDICINE' : i.itemGroup==='INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50">
                    <td className="px-8 py-5"><div className="font-black text-black">{item.name}</div><div className="text-xs text-slate-400 font-bold">{item.spec || '無規格'}</div></td>
                    <td className="px-8 py-5 text-center"><span className={`px-5 py-2 rounded-xl font-black text-lg ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600 animate-pulse' : 'bg-emerald-50 text-emerald-600'}`}>{item.quantity} {item.unit}</span></td>
                    <td className="px-8 py-5 text-right flex justify-end gap-2"><button onClick={()=>setEditTarget(item)} className="p-3 text-slate-300 hover:text-blue-600"><Edit3 size={20}/></button><button onClick={()=>setDeleteTarget({id: item.id, name: item.name})} className="p-3 text-slate-300 hover:text-red-600"><Trash2 size={20}/></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-200">
            <table className="w-full text-left font-bold text-black">
              <thead className="bg-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b"><tr><th className="px-6 py-4">時間</th><th className="px-6 py-4">品項</th><th className="px-6 py-4">類別</th><th className="px-6 py-4">經手人</th><th className="px-6 py-4 text-right">補印</th></tr></thead>
              <tbody className="divide-y divide-slate-100">
                {logs.map(log => (<tr key={log.id} className="hover:bg-slate-50"><td className="px-6 py-4 text-xs text-slate-400">{new Date(log.timestamp).toLocaleString()}</td><td className="px-6 py-4 font-black">{log.itemName} ({log.quantity})</td><td className="px-6 py-4">{log.type==='OUT' ? <span className="text-blue-600">領用</span> : <span className="text-emerald-600">補貨</span>}</td><td className="px-6 py-4">{log.person}</td><td className="px-6 py-4 text-right">{log.type==='OUT' && <button onClick={()=>{ setLastTransactionBatch({id: log.id, dept: log.dept, person: log.person, reason: log.reason, items: [{itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '個', spec: '', itemType: 'CONSUMABLE'}], timestamp: log.timestamp}); setShowPrintModal(true); }} className="text-slate-300 hover:text-blue-600"><Printer size={18}/></button>}</td></tr>))}
              </tbody>
            </table>
          </div>
        )}
      </main>

      {showPrintModal && lastTransactionBatch && (
        <div className="fixed inset-0 bg-slate-900/95 z-[500] flex flex-col items-center justify-center p-6">
          <div className="bg-white rounded-[3rem] w-full max-w-5xl h-[90vh] shadow-2xl flex flex-col overflow-hidden">
            <div className="p-8 flex justify-between items-center border-b bg-white">
              <h3 className="font-black text-2xl text-black">單據預覽 (標楷體)</h3>
              <div className="flex gap-4">
                <button onClick={() => handleFinalPrint(false)} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xl shadow-xl flex items-center gap-2"><Printer size={24}/> 直接列印</button>
                <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-2xl text-black"><X size={32}/></button>
              </div>
            </div>
            <div className="flex-1 bg-slate-100 p-10 overflow-y-auto flex justify-center">
              <div className="bg-white shadow-2xl p-10 border rounded-sm w-[210mm] min-h-[297mm] text-black">
                <h1 className="text-center text-4xl font-bold mb-10 text-black">台灣電力公司電力修護處南部分處</h1>
                <div className="text-center text-2xl font-bold underline mb-8 text-black">工安物資領用明細單</div>
                <div className="flex justify-between mb-8 font-bold text-xl text-black"><span>部門：{lastTransactionBatch.dept}</span><span>日期：{new Date(lastTransactionBatch.timestamp).toLocaleDateString()}</span></div>
                <table className="w-full border-2 border-black text-black">
                  <thead><tr className="bg-slate-50 border-b-2 border-black font-bold text-xl"><th className="border-r border-black p-4 text-black">名稱</th><th className="border-r border-black p-4 text-black">單位</th><th className="p-4 text-black">領用量</th></tr></thead>
                  <tbody>{lastTransactionBatch.items.map((it, i) => (<tr key={i} className="border-b border-black text-center font-bold text-2xl"><td className="border-r border-black p-6 text-black">{it.name}</td><td className="border-r border-black p-6 text-black">{it.unit || '個'}</td><td className="p-6 text-black">{it.quantity}</td></tr>))}</tbody>
                </table>
                <div className="mt-24 flex justify-between font-bold text-2xl text-black"><span>領用簽章：{lastTransactionBatch.person}</span><span>經辦：__________</span></div>
              </div>
            </div>
          </div>
        </div>
      )}

      {(editTarget || showAddModal) && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl text-black">
            <form className="space-y-6" onSubmit={handleSaveItem}>
              <h3 className="text-2xl font-black mb-4 text-black">{editTarget ? '編輯項目' : '新增項目'}</h3>
              <div><label className="text-xs font-black text-slate-500">名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl mt-2 font-bold text-black" defaultValue={editTarget?.name} /></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-xs font-black text-slate-500">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl mt-2 font-bold text-black" defaultValue={editTarget?.unit || '個'} /></div>
                <div><label className="text-xs font-black text-slate-500">庫存</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl mt-2 font-bold text-black" defaultValue={editTarget?.quantity || 0} /></div>
              </div>
              <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-2xl shadow-xl">儲存</button>
              <button type="button" onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="w-full py-2 text-slate-400 font-bold">取消</button>
            </form>
          </div>
        </div>
      )}

      {showSettings && (
        <div className="fixed inset-0 bg-slate-900/80 z-[600] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl text-black">
            <h3 className="text-2xl font-black mb-6 text-black">雲端資料庫設定</h3>
            <input type="text" className="w-full p-4 rounded-xl font-bold text-black border-2" defaultValue={gasUrl} id="gas-url-input"/>
            <div className="flex gap-4 mt-8">
              <button onClick={() => handleGasUrlSave((document.getElementById('gas-url-input') as HTMLInputElement).value)} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black">儲存連線</button>
              <button onClick={() => setShowSettings(false)} className="px-8 py-5 bg-slate-100 text-slate-600 rounded-2xl font-black">返回</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  CheckCircle2,
  Users,
  Download,
  Upload,
  FileDown,
  ArrowUpRight,
