            <table className="w-full text-left font-bold">
              <thead className="bg-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b">
                <tr><th className="px-8 py-5">名稱及規格</th><th className="px-8 py-5 text-center">目前庫存</th><th className="px-8 py-5 text-right">操作</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(i => (activeTab==='medicine' ? i.itemGroup==='MEDICINE' : i.itemGroup==='INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50">
                    <td className="px-8 py-5"><div className="font-black text-slate-950">{item.name}</div><div className="text-xs text-slate-400 font-bold">{item.spec || '無規格資訊'}</div></td>
                    <td className="px-8 py-5 text-center"><span className={`px-5 py-2 rounded-xl font-black text-lg ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600 animate-pulse' : 'bg-emerald-50 text-emerald-600'}`}>{item.quantity} {item.unit}</span></td>
                    <td className="px-8 py-5 text-right flex justify-end gap-2"><button onClick={()=>setEditTarget(item)} className="p-3 text-slate-300 hover:text-blue-600"><Edit3 size={20}/></button><button onClick={()=>setDeleteTarget({id: item.id, name: item.name})} className="p-3 text-slate-300 hover:text-red-600"><Trash2 size={20}/></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in">
             <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-slate-900 p-10 rounded-[2.5rem] text-white shadow-xl">
                <p className="text-blue-400 text-xs font-black uppercase tracking-widest mb-2">年度領用總量</p>
                <h3 className="text-6xl font-black">{stats.invQty + stats.medQty} <span className="text-2xl ml-2">件</span></h3>
              </div>
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border-t-8 border-blue-500">
                <h4 className="font-black text-xl mb-4 text-slate-900">熱門領用品項</h4>
                <div className="space-y-3">{stats.invDetails.slice(0,5).map((it, i) => (<div key={i} className="flex justify-between p-3 bg-slate-50 rounded-xl font-black border"><span>{it.name}</span><span className="text-blue-600">{it.qty} 件</span></div>))}</div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-200">
            <table className="w-full text-left font-bold">
              <thead className="bg-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b"><tr><th className="px-6 py-4">時間</th><th className="px-6 py-4">品項</th><th className="px-6 py-4">類別</th><th className="px-6 py-4">部門/經手人</th><th className="px-6 py-4 text-right">補印</th></tr></thead>
              <tbody className="divide-y divide-slate-100">
                {logs.map(log => (<tr key={log.id} className="hover:bg-slate-50"><td className="px-6 py-4 text-xs text-slate-400">{new Date(log.timestamp).toLocaleString()}</td><td className="px-6 py-4 font-black text-slate-950">{log.itemName} ({log.quantity})</td><td className="px-6 py-4">{log.type==='OUT' ? <span className="text-blue-600">領用</span> : <span className="text-emerald-600">補貨</span>}</td><td className="px-6 py-4">{log.person}</td><td className="px-6 py-4 text-right">{log.type==='OUT' && <button onClick={()=>{ setLastTransactionBatch({id: log.id, dept: log.dept, person: log.person, reason: log.reason, items: [{itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '個', spec: '', itemType: 'CONSUMABLE'}], timestamp: log.timestamp}); setShowPrintModal(true); }} className="text-slate-300 hover:text-blue-600"><Printer size={18}/></button>}</td></tr>))}
              </tbody>
            </table>
          </div>
        )}
      </main>

      {/* 彈出視窗：領用單預覽 */}
      {showPrintModal && lastTransactionBatch && (
        <div className="fixed inset-0 bg-slate-900/95 z-[500] flex flex-col items-center justify-center p-6 animate-in zoom-in">
          <div className="bg-white rounded-[3rem] w-full max-w-5xl h-[90vh] shadow-2xl flex flex-col overflow-hidden">
            <div className="p-8 flex justify-between items-center border-b bg-white">
              <div className="flex items-center gap-4"><CheckCircle2 className="text-emerald-500" size={32}/><h3 className="font-black text-2xl">領用單據生成預覽</h3></div>
              <div className="flex gap-4">
                <button onClick={handleFinalPrint} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xl shadow-xl flex items-center gap-2"><Printer size={24}/> 列印單據 (標楷體)</button>
                <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-2xl text-slate-600"><X size={32}/></button>
              </div>
            </div>
            <div className="flex-1 bg-slate-100 p-10 overflow-y-auto flex justify-center custom-scrollbar">
              <div className="bg-white shadow-2xl p-10 border rounded-sm w-[210mm] min-h-[297mm] text-slate-950">
                <h1 className="text-center text-3xl font-bold mb-10">台灣電力公司電力修護處南部分處</h1>
                <div className="text-center text-xl font-bold underline mb-8">工安物資領用明細單</div>
                <div className="flex justify-between mb-8 font-bold text-lg"><span>領用部門：{lastTransactionBatch.dept}</span><span>日期：{new Date(lastTransactionBatch.timestamp).toLocaleDateString()}</span></div>
                <table className="w-full border-2 border-black">
                  <thead><tr className="bg-slate-50 border-b-2 border-black font-bold text-lg"><th className="border-r border-black p-4">物資名稱</th><th className="border-r border-black p-4">單位</th><th className="p-4">領用數量</th></tr></thead>
                  <tbody>{lastTransactionBatch.items.map((it, i) => (<tr key={i} className="border-b border-black text-center font-bold text-xl"><td className="border-r border-black p-6">{it.name}</td><td className="border-r border-black p-6">{it.unit || '個'}</td><td className="p-6">{it.quantity}</td></tr>))}</tbody>
                </table>
                <div className="mt-24 flex justify-between font-bold text-xl px-10"><span>領用簽章：{lastTransactionBatch.person}</span><span>經辦人：__________</span></div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 彈出視窗：新增編輯 */}
      {(editTarget || showAddModal) && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl">
            <form className="space-y-6" onSubmit={handleSaveItem}>
              <h3 className="text-2xl font-black mb-4">{editTarget ? '編輯項目資料' : '新增管理項目'}</h3>
              <div><label className="text-xs font-black text-slate-400">項目名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.name} /></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-xs font-black text-slate-400">目前庫存</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.quantity || 0} /></div>
                <div><label className="text-xs font-black text-slate-400">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.unit || '個'} /></div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-xs font-black text-slate-400">警戒數量</label><input name="minStock" type="number" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.minStock || 5} /></div>
                <div><label className="text-xs font-black text-slate-400">性質</label><select name="itemType" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="CONSUMABLE">消耗品 (領用)</option><option value="EQUIPMENT">設備 (借用)</option></select></div>
              </div>
              <div><label className="text-xs font-black text-slate-400">規格 / 序號</label><input name="spec" type="text" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.spec} /></div>
              <div className="flex gap-4 pt-6">
                <button type="submit" className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl">儲存變更</button>
                <button type="button" onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="px-8 py-5 bg-slate-100 text-slate-400 rounded-2xl font-bold">取消</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showSettings && (
        <div className="fixed inset-0 bg-slate-900/80 z-[600] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl">
            <h3 className="text-2xl font-black mb-6 text-slate-950 flex items-center gap-2"><Cloud size={24} className="text-blue-600"/> 雲端資料庫設定</h3>
            <div><label className="text-xs font-black text-slate-400 uppercase">GAS Web App URL</label><input type="text" className="w-full p-4 rounded-xl font-bold border-2 mt-2" defaultValue={gasUrl} id="gas-url-input" placeholder="尚未貼上網址"/></div>
            <div className="flex gap-4 mt-8">
              <button onClick={() => handleGasUrlSave((document.getElementById('gas-url-input') as HTMLInputElement).value)} className="flex-1 py-5 bg-slate-900 text-white rounded-2xl font-black">儲存並重啟連線</button>
              <button onClick={() => setShowSettings(false)} className="px-8 py-5 bg-slate-100 text-slate-600 rounded-2xl font-black">返回</button>
            </div>
          </div>
        </div>
      )}

      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/90 flex items-center justify-center p-4 z-[700] animate-in fade-in">
          <div className="bg-white p-10 rounded-3xl text-center max-w-sm shadow-2xl border-4 border-red-50">
            <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-6"><AlertTriangle size={32}/></div>
            <h3 className="text-2xl font-black mb-4">確定要刪除？</h3>
            <p className="text-slate-400 font-bold mb-8">物資「{deleteTarget.name}」將被永久移除。</p>
            <div className="flex flex-col gap-3">
                <button onClick={()=>{ const newItems = items.filter(i => i.id !== deleteTarget.id); setItems(newItems); syncToCloud(newItems, logs); setDeleteTarget(null); }} className="w-full py-4 bg-red-600 text-white rounded-xl font-black shadow-lg hover:bg-red-700">確認刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="w-full py-3 text-slate-400 font-bold">取消</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

