            {!gasUrl && activeTab === 'dashboard' && (
              <div onClick={() => setShowSettings(true)} className="mt-4 bg-orange-50 border-2 border-orange-200 p-4 rounded-2xl flex items-center gap-3 text-orange-700 cursor-pointer hover:bg-orange-100 transition-all shadow-sm"><AlertTriangle size={20} className="animate-bounce"/><div className="font-bold">尚未設定雲端同步！點擊此處貼上 GAS 網址，開啟多人協作功能。</div></div>
            )}
