                <div><label className="text-xs font-black text-slate-500 uppercase tracking-widest">品項選擇</label><select className="w-full p-4 rounded-xl mt-2 text-lg text-black font-bold" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}><option value="">-- 請選擇 --</option>{items.filter(i => i.itemGroup === issuanceGroup).map(i => (<option key={i.id} value={i.id}>{i.name} (庫存:{i.quantity - getReservedQty(i.id)})</option>))}</select></div>
                <div><label className="text-xs font-black text-slate-500 uppercase tracking-widest">數量</label><input type="number" min="1" className="w-full p-4 rounded-xl mt-2 text-xl font-bold" value={inputQty} onChange={e=>setInputQty(e.target.value)}/></div>
                <button onClick={addToBasket} disabled={!selectedItemId} className="w-full py-5 rounded-2xl font-black text-xl bg-slate-900 text-white hover:bg-black shadow-lg">加入待辦清單</button>
              </div>
