              <button onClick={() => setShowSettings(false)} className="px-8 py-5 bg-slate-100 text-slate-600 rounded-2xl font-black text-lg">返回</button>
            </div>
          </div>
        </div>
      )}

      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/90 flex items-center justify-center p-4 z-[700] animate-in fade-in">
          <div className="bg-white p-10 rounded-3xl text-center max-w-sm shadow-2xl">
            <h3 className="text-2xl font-black mb-4 text-black">確定刪除？</h3>
            <p className="text-slate-400 font-bold mb-8">物資「{deleteTarget.name}」將從清單移除。</p>
            <div className="flex flex-col gap-3">
                <button onClick={()=>{ const newItems = items.filter(i => i.id !== deleteTarget.id); setItems(newItems); syncToCloud(newItems, logs); setDeleteTarget(null); }} className="w-full py-4 bg-red-600 text-white rounded-xl font-black shadow-lg hover:bg-red-700">確認刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="w-full py-3 text-slate-400 font-bold hover:text-black">取消</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

