// --- 類型定義 (整合自原本的 types.ts) ---
export enum Category {
  PROTECTION = '個人防護 (PPE)',
  FIRE_SAFETY = '消防安全',
  FIRST_AID = '急救耗材',
  SIGNAGE = '標誌警告',
  TOOL = '工具設備',
  OTHER = '其他'
}

export type ItemType = 'EQUIPMENT' | 'CONSUMABLE';
export type ItemGroup = 'INVENTORY' | 'MEDICINE';

export interface InventoryItem {
  id: string;
  name: string;
  category: Category;
  itemType: ItemType; 
  itemGroup: ItemGroup;
  unit: string;
  spec: string;
  quantity: number;
  minStock: number;
  purchaseDate?: string;
  expiryDate?: string;
  description: string;
  lastUpdated: number;
}

export type TransactionType = 'IN' | 'OUT';

export interface Transaction {
  id: string;
  itemId: string;
  itemName: string;
  type: TransactionType;
  quantity: number;
  person: string;
  dept: string;
  reason: string;
  timestamp: number;
}

// --- AI 建議服務 (整合自原本的 geminiService.ts) ---
const getInventoryInsights = async (items: InventoryItem[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const lowStock = items.filter(i => i.quantity <= i.minStock);

  const prompt = `
    這是一個工安耗材管理系統。
    當前庫存清單: ${JSON.stringify(items.map(i => ({ name: i.name, qty: i.quantity, min: i.minStock })))}
    庫存不足的項目: ${JSON.stringify(lowStock.map(i => i.name))}

    請以專業工安管理員的身份，針對目前的庫存狀況提供 3 點具體的採購或管理建議。
    請用繁體中文回答。
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "目前庫存狀況良好，無特別建議。";
  } catch (error) {
    console.error("Gemini AI Error:", error);
    return "AI 助理目前連線忙碌。請優先檢查庫存警戒項目。";
  }
};

// --- 常數設定 ---
const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

const DEFAULT_GAS_URL = 'https://script.google.com/macros/s/AKfycbxQmoG0pHHm2tuzt9Og3eAGOTYSUd1d61orWOEygS9qmjQ9LUaC3WsvwCHfjV9wh_Q2/exec';

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

type SyncStatus = 'synced' | 'syncing' | 'error' | 'local';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || DEFAULT_GAS_URL);
  const [syncStatus, setSyncStatus] = useState<SyncStatus>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '從未同步');
  const [showSettings, setShowSettings] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [statsDeptFilter, setStatsDeptFilter] = useState<string>('ALL');
  const [statsYearFilter, setStatsYearFilter] = useState<number>(new Date().getFullYear());

  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const initLoad = async () => {
      const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
      const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
      if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
      if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
      setIsLoaded(true);
      if (gasUrl) { fetchFromCloud(); } else { setSyncStatus('local'); }
    };
    initLoad();
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const updateSyncTime = () => {
    const now = new Date().toLocaleTimeString('zh-TW', { hour12: false, hour: '2-digit', minute: '2-digit' });
    const fullTime = `${new Date().toLocaleDateString('zh-TW')} ${now}`;
    setLastSyncTime(fullTime);
    localStorage.setItem(STORAGE_KEY_LAST_SYNC, fullTime);
  };

  const syncToCloud = async (currentItems: InventoryItem[], currentLogs: Transaction[]) => {
    if (!gasUrl) { setSyncStatus('local'); return; }
    setSyncStatus('syncing');
    try {
      const payload = { items: currentItems, logs: currentLogs, timestamp: Date.now() };
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify(payload), mode: 'no-cors' });
      setSyncStatus('synced');
      updateSyncTime();
    } catch (err) {
      console.error("Cloud Sync Error:", err);
      setSyncStatus('error');
    }
  };

  const fetchFromCloud = async () => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const response = await fetch(gasUrl);
      const data = await response.json();
      if (data && data.items && data.logs) {
        setItems(data.items);
        setLogs(data.logs);
        setSyncStatus('synced');
        updateSyncTime();
      } else {
        setSyncStatus('synced');
        updateSyncTime();
      }
    } catch (err) {
      console.error("Fetch Cloud Error:", err);
      setSyncStatus('error');
    }
  };

  const handleGasUrlSave = (newUrl: string) => {
    const cleanUrl = newUrl.trim();
    setGasUrl(cleanUrl);
    localStorage.setItem(STORAGE_KEY_GAS_URL, cleanUrl);
    setShowSettings(false);
    if (cleanUrl) { fetchFromCloud(); } else { setSyncStatus('local'); }
  };

  const exportData = () => {
    const data = { items, logs, timestamp: Date.now() };
    const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `工安管理備份_${new Date().toLocaleDateString().replace(/\//g, '-')}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const importData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (data.items && data.logs) {
          if (window.confirm("確定要導入此備份並同步數據嗎？這將覆蓋現有庫存與紀錄。")) {
            setItems(data.items);
            setLogs(data.logs);
            syncToCloud(data.items, data.logs);
            window.alert("✅ 數據導入成功，已嘗試同步至雲端！");
          }
        }
      } catch (err) { window.alert("❌ 檔案格式錯誤，無法讀取。"); }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const getReservedQty = (itemId: string) => basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);

  const currentAvailable = useMemo(() => {
    if (!selectedItemId) return 0;
    const item = items.find(i => i.id === selectedItemId);
    return item ? item.quantity - getReservedQty(selectedItemId) : 0;
  }, [selectedItemId, items, basket]);

  const isQtyOver = useMemo(() => {
    if (issuanceMode === 'IN') return false;
    const qty = Number(inputQty);
    return !isNaN(qty) && qty > currentAvailable;
  }, [inputQty, currentAvailable, issuanceMode]);

  const addToBasket = () => {
    if (!selectedItemId || isQtyOver) return;
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;
    const qty = Number(inputQty);
    if (isNaN(qty) || qty <= 0) return;
    setBasket(prev => [...prev, { itemId: targetItem.id, name: targetItem.name, quantity: qty, unit: targetItem.unit, spec: targetItem.spec, itemType: targetItem.itemType }]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const timestamp = Date.now();
    const batchId = generateId();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(bItem => {
      updatedItems = updatedItems.map(item => {
        if (item.id === bItem.itemId) {
          const newQty = issuanceMode === 'IN' ? item.quantity + bItem.quantity : item.quantity - bItem.quantity;
          return { ...item, quantity: newQty, lastUpdated: timestamp };
        }
        return item;
      });
      newLogs.push({ id: generateId() + Math.random().toString(36).substr(2, 4), itemId: bItem.itemId, itemName: bItem.name, type: issuanceMode, quantity: bItem.quantity, person: inputPerson || '未填寫', dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處', reason: inputReason, timestamp: timestamp });
    });

    const finalLogs = [...newLogs, ...logs];
    setItems(updatedItems);
    setLogs(finalLogs);
    syncToCloud(updatedItems, finalLogs);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({ id: batchId, dept: selectedDept, person: inputPerson, reason: inputReason, items: [...basket], timestamp: timestamp });
      setShowPrintModal(true);
    } else { window.alert(`✅ 物資補貨入庫完成。`); }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  const handleFinalPrint = (isPDF: boolean = false) => {
    if (!lastTransactionBatch) return;
    if (isPDF) { window.alert("💡 另存為 PDF 指引：\n\n點擊確認後，請在印表機目的地選擇「另存為 PDF (Save as PDF)」。"); }
    const date = new Date(lastTransactionBatch.timestamp);
    const isEquip = lastTransactionBatch.items.some(it => it.itemType === 'EQUIPMENT');
    const isConsum = lastTransactionBatch.items.every(it => it.itemType === 'CONSUMABLE') || !isEquip;

    const rows = lastTransactionBatch.items.map(item => `<tr><td style="text-align:center; color:black !important; padding: 12px; border: 1.5px solid black;">${item.name}</td><td style="text-align:center; color:black !important; border: 1.5px solid black;">${item.spec || ''}</td><td style="text-align:center; color:black !important; border: 1.5px solid black;">${item.unit}</td><td style="text-align:center; font-size:18pt; font-weight:bold; color:black !important; border: 1.5px solid black;">${item.quantity}</td><td style="text-align:center; color:black !important; border: 1.5px solid black;">${lastTransactionBatch.reason}</td></tr>`).join('');
    const emptyRowsCount = Math.max(0, 15 - lastTransactionBatch.items.length);
    const emptyRows = Array(emptyRowsCount).fill('<tr><td style="height:35px; border: 1.5px solid black;">&nbsp;</td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td></tr>').join('');

    const printWin = window.open('', '_blank', 'width=1100,height=900');
    if (!printWin) return;
    printWin.document.write(`
      <html><head><title>領用單_${lastTransactionBatch.id}</title><style>
            @font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); }
            @page { margin: 0; }
            body { font-family: 'StandardKai', serif; padding: 80px 60px; color: black !important; background: white; margin: 0; line-height: 1.2; }
            .title { text-align: center; font-size: 26pt; font-weight: bold; margin-bottom: 25px; letter-spacing: 2px; color: black !important; }
            .checkbox-area { display: flex; justify-content: center; gap: 40px; font-size: 16pt; margin-bottom: 25px; font-weight: bold; color: black !important; }
            .checkbox { width: 22px; height: 22px; border: 2.5px solid black; display: inline-flex; align-items: center; justify-content: center; margin-right: 8px; vertical-align: middle; color: black !important; }
            .dept-row { font-size: 15pt; font-weight: bold; margin-bottom: 10px; display: flex; justify-content: space-between; color: black !important; }
            table { width: 100%; border-collapse: collapse; border: 2.5px solid black; margin-bottom: 25px; color: black !important; }
            th { border: 1.5px solid black; padding: 10px; text-align: center; font-size: 14pt; font-weight: bold; background: #f2f2f2; color: black !important; }
            td { color: black !important; text-align: center; }
            .footer-row { font-size: 14pt; font-weight: bold; margin-top: 30px; color: black !important; }
            .sig-area { display: flex; justify-content: space-between; margin-top: 45px; font-size: 13pt; color: black !important; }
            @media print { body { padding: 80px 60px; } .no-print { display: none; } }
          </style></head><body>
          <div style="display: flex; flex-direction: column; align-items: flex-end;"><div style="font-size: 9pt; color: #666;">單號：${lastTransactionBatch.id}</div>${lastTransactionBatch.person ? `<div style="font-size: 9pt; color: #333; margin-top: 2px;">領用人：${lastTransactionBatch.person}</div>` : ''}</div>
          <div class="title">台灣電力公司電力修護處南部分處</div>
          <div class="checkbox-area"><div><span class="checkbox">${isEquip ? 'V' : ''}</span>安全衛生設備借用單</div><div><span class="checkbox">${isConsum ? 'V' : ''}</span>安全衛生類消耗品領用單</div></div>
          <div class="dept-row"><div>部 門：<span style="border-bottom: 2px dotted black; min-width: 350px; display: inline-block; text-align: center;">${lastTransactionBatch.dept}</span></div><div>${date.getFullYear() - 1911} 年 ${date.getMonth() + 1} 月 ${date.getDate()} 日</div></div>
          <table><thead><tr><th style="width:35%; color:black !important;">名　　　稱</th><th style="width:25%; color:black !important;">規　範（序　號）</th><th style="width:10%; color:black !important;">單 位</th><th style="width:10%; color:black !important;">數 量</th><th style="width:20%; color:black !important;">備　　註</th></tr></thead><tbody>${rows}${emptyRows}</tbody></table>
          <div class="footer-row"><div style="display: flex; justify-content: space-between; color:black !important;"><div style="flex:1">申請部門：</div><div style="flex:1">經管部門：</div></div><div class="sig-area"><div style="flex:1; display:flex; justify-content:space-around; padding: 0 15px; color:black !important;"><span>經辦：</span><span>課長：</span><span>經理：</span></div><div style="flex:1; display:flex; justify-content:space-around; padding: 0 15px; color:black !important;"><span>經辦：</span><span>課長：</span><span>經理：</span></div></div></div>
          <script>window.onload = () => { setTimeout(() => { window.print(); window.close(); }, 600); };</script></body></html>
    `);
    printWin.document.close();
  };

  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = { 
        name: formData.get('name') as string, 
        itemType: formData.get('itemType') as ItemType, 
        unit: formData.get('unit') as string, 
        spec: formData.get('spec') as string, 
        purchaseDate: formData.get('purchaseDate') as string, 
        expiryDate: formData.get('expiryDate') as string, 
        quantity: Number(formData.get('quantity')), 
        minStock: Number(formData.get('minStock')), 
    };
    let updated;
    if (editTarget) {
      updated = items.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i);
      setItems(updated); setEditTarget(null);
    } else {
      updated = [...items, { id: generateId(), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: Date.now() }];
      setItems(updated); setShowAddModal(false);
    }
    syncToCloud(updated, logs);
  };

  const stats = useMemo(() => {
    const filteredLogs = logs.filter(l => {
        const logDate = new Date(l.timestamp);
        return l.type === 'OUT' && logDate.getFullYear() === statsYearFilter && (statsDeptFilter === 'ALL' || l.dept === statsDeptFilter);
    });
    const invDetailMap: Record<string, {name: string, qty: number}> = {};
    const medDetailMap: Record<string, {name: string, qty: number}> = {};
    let fInvQty = 0, fMedQty = 0;
    filteredLogs.forEach(log => {
        const item = items.find(it => it.id === log.itemId);
        if (item?.itemGroup === 'MEDICINE') { fMedQty += log.quantity; if (!medDetailMap[log.itemId]) medDetailMap[log.itemId] = { name: log.itemName, qty: 0 }; medDetailMap[log.itemId].qty += log.quantity; }
        else { fInvQty += log.quantity; if (!invDetailMap[log.itemId]) invDetailMap[log.itemId] = { name: log.itemName, qty: 0 }; invDetailMap[log.itemId].qty += log.quantity; }
    });
    return {
      filtered: { invQty: fInvQty, medQty: fMedQty, invDetails: Object.values(invDetailMap).sort((a, b) => b.qty - a.qty), medDetails: Object.values(medDetailMap).sort((a, b) => b.qty - a.qty), },
      deptRanking: Object.entries(logs.filter(l => l.type === 'OUT' && new Date(l.timestamp).getFullYear() === statsYearFilter).reduce((acc: any, curr) => { acc[curr.dept] = (acc[curr.dept] || 0) + curr.quantity; return acc; }, {})).sort((a: any, b: any) => b[1] - a[1])
    };
  }, [items, logs, statsDeptFilter, statsYearFilter]);

  return (
    <div className="min-h-screen flex bg-slate-100 text-black font-sans">
      <style>{`
        input, select, textarea { color: #000000 !important; background-color: #ffffff !important; border: 2px solid #94a3b8 !important; font-weight: 700 !important; }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
      `}</style>
      <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={importData} />

      <aside className="w-72 bg-slate-900 text-white p-6 flex flex-col shrink-0 border-r border-slate-800 shadow-2xl">
        <div className="flex flex-col gap-1 mb-8">
          <div className="flex items-center gap-3"><div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22} className="text-white"/></div><h1 className="font-black text-xl tracking-tight text-white">工安管理系統</h1></div>
          <div className="mt-6 bg-slate-800/50 rounded-2xl p-4 border border-slate-700/50">
            <div className="flex items-center justify-between mb-2"><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">雲端連線狀態</span><div className={`w-3 h-3 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.8)]' : syncStatus === 'syncing' ? 'bg-amber-500 animate-pulse' : 'bg-orange-400'}`}></div></div>
            <div className="text-sm font-black text-white mb-1">{syncStatus === 'synced' ? '已成功連線' : syncStatus === 'syncing' ? '正在同步數據...' : '單機運作中'}</div>
            <div className="flex items-center gap-1.5 text-[10px] text-slate-400 font-bold"><Clock size={10}/> 最後同步：{lastSyncTime}</div>
          </div>
        </div>
        <nav className="flex-1 space-y-1">
          {[ 
            { id: 'inventory', label: '工安耗材管理', icon: Package }, 
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope }, 
            { id: 'issuance', label: '領用補貨作業', icon: FileText }, 
            { id: 'history', label: '歷史異動日誌', icon: History }, 
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard }, 
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}><tab.icon size={20} /> {tab.label}</button>
          ))}
        </nav>
        <div className="pt-6 mt-6 border-t border-slate-800 space-y-2">
            <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-black text-slate-300 hover:bg-slate-800 hover:text-white"><Settings size={16}/> 雲端連線設定</button>
            <button onClick={fetchFromCloud} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><RefreshCw size={16}/> 手動重新同步</button>
            <button onClick={exportData} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><Download size={16}/> 匯出備份</button>
        </div>
      </aside>

      <main className="flex-1 p-10 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-3xl font-black text-black">{activeTab === 'inventory' ? '工安耗材清冊' : activeTab === 'medicine' ? '急救藥材清冊' : activeTab === 'issuance' ? '領用 / 補貨登記' : activeTab === 'history' ? '歷史異動日誌' : '數據統計看板'}</h2>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-black shadow-xl"><Plus size={18}/> 新增項目</button>
          )}
        </header>

        {activeTab === 'issuance' && (
          <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
            <div className="lg:col-span-2 bg-white p-8 rounded-3xl shadow-xl border border-slate-200">
              <h3 className="text-xl font-black mb-8 flex items-center gap-2 text-black"><ShoppingCart className="text-blue-500"/> 1. 挑選項目</h3>
              <div className="flex bg-slate-100 p-1 rounded-xl mb-6 font-bold">
                <button onClick={()=>setIssuanceMode('OUT')} className={`flex-1 py-3 rounded-lg ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button>
                <button onClick={()=>setIssuanceMode('IN')} className={`flex-1 py-3 rounded-lg ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
              </div>
              <div className="space-y-6">
                <div><label className="text-xs font-black text-slate-500 uppercase tracking-widest">分類</label><div className="flex gap-2 mt-2"><button onClick={()=>setIssuanceGroup('INVENTORY')} className={`flex-1 py-3 rounded-xl font-black border-2 ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-200 text-slate-400'}`}>耗材類</button><button onClick={()=>setIssuanceGroup('MEDICINE')} className={`flex-1 py-3 rounded-xl font-black border-2 ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-200 text-slate-400'}`}>藥材類</button></div></div>
                <div><label className="text-xs font-black text-slate-500 uppercase tracking-widest">品項選擇</label><select className="w-full p-4 rounded-xl mt-2 text-lg text-black font-bold" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}><option value="">-- 請選擇 --</option>{items.filter(i => i.itemGroup === issuanceGroup).map(i => (<option key={i.id} value={i.id}>{i.name} (庫存:{i.quantity - getReservedQty(i.id)})</option>))}</select></div>
                <div><label className="text-xs font-black text-slate-500 uppercase tracking-widest">數量</label><input type="number" min="1" className="w-full p-4 rounded-xl mt-2 text-xl font-bold" value={inputQty} onChange={e=>setInputQty(e.target.value)}/>{isQtyOver && <p className="text-red-600 text-xs font-black mt-2">⚠️ 超出庫存</p>}</div>
                <button onClick={addToBasket} disabled={!selectedItemId || isQtyOver} className={`w-full py-5 rounded-2xl font-black text-xl bg-slate-900 text-white hover:bg-black shadow-lg ${isQtyOver ? 'opacity-50' : ''}`}>加入待辦清單</button>
              </div>
            </div>
            <div className="lg:col-span-3 bg-white p-8 rounded-3xl shadow-xl border border-slate-200 flex flex-col">
              <h3 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><FileText className="text-emerald-500"/> 2. 登記明細</h3>
              <div className="flex-1 overflow-y-auto border-2 border-dashed border-slate-100 rounded-2xl mb-6 min-h-[250px] bg-slate-50 p-4">
                {basket.map((b, idx) => (<div key={idx} className="flex justify-between p-4 bg-white rounded-xl mb-2 shadow-sm font-black border border-slate-100"><span>{b.name}</span><div className="flex items-center gap-4"><span>{b.quantity} {b.unit}</span><button onClick={()=>setBasket(prev => prev.filter((_, i) => i !== idx))} className="text-red-400"><X size={18}/></button></div></div>))}
                {basket.length === 0 && <div className="h-full flex items-center justify-center text-slate-300 font-bold opacity-30">清單為空</div>}
              </div>
              {issuanceMode === 'OUT' && (
                <div className="grid grid-cols-2 gap-4 mb-6 font-bold">
                  <div><label className="text-xs font-black text-slate-500 uppercase">領用部門</label><select className="w-full p-3 rounded-xl mt-2 text-black font-bold" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>{DEPARTMENTS.map(d=><option key={d} value={d}>{d}</option>)}</select></div>
                  <div><label className="text-xs font-black text-slate-500 uppercase">領用人</label><input type="text" className="w-full p-3 rounded-xl mt-2 text-black font-bold" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div>
                  <div className="col-span-2"><label className="text-xs font-black text-slate-500 uppercase">用途備註</label><input type="text" className="w-full p-3 rounded-xl mt-2 text-black font-bold" value={inputReason} onChange={e=>setInputReason(e.target.value)}/></div>
                </div>
              )}
              <button onClick={processIssuance} disabled={basket.length === 0} className={`w-full py-6 rounded-2xl font-black text-3xl text-white shadow-2xl transition-all active:scale-95 ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>確認存檔並列印</button>
            </div>
          </div>
        )}

        {/* 下方清冊列表 */}
        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-200">
            <div className="p-4 bg-slate-50 border-b flex items-center gap-4"><Search className="text-slate-400"/><input type="text" placeholder="搜尋項目..." className="w-full font-black text-black" value={searchTerm} onChange={e=>setSearchTerm(e.target.value)}/></div>
            <table className="w-full text-left font-bold text-black">
              <thead className="bg-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b">
                <tr><th className="px-8 py-5">名稱及規格</th><th className="px-8 py-5 text-center">目前庫存</th><th className="px-8 py-5 text-right">操作</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(i => (activeTab==='medicine' ? i.itemGroup==='MEDICINE' : i.itemGroup==='INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50">
                    <td className="px-8 py-5"><div className="font-black text-black">{item.name}</div><div className="text-xs text-slate-400 font-bold">{item.spec || '無規格'}</div></td>
                    <td className="px-8 py-5 text-center"><span className={`px-5 py-2 rounded-xl font-black text-lg ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600 animate-pulse' : 'bg-emerald-50 text-emerald-600'}`}>{item.quantity} {item.unit}</span></td>
                    <td className="px-8 py-5 text-right flex justify-end gap-2"><button onClick={()=>setEditTarget(item)} className="p-3 text-slate-300 hover:text-blue-600"><Edit3 size={20}/></button><button onClick={()=>setDeleteTarget({id: item.id, name: item.name})} className="p-3 text-slate-300 hover:text-red-600"><Trash2 size={20}/></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in">
             <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-slate-900 p-10 rounded-[2.5rem] text-white shadow-xl">
                <p className="text-blue-400 text-xs font-black uppercase tracking-widest mb-2">年度領用量統計</p>
                <h3 className="text-6xl font-black text-white">{stats.filtered.invQty + stats.filtered.medQty} <span className="text-2xl ml-2 text-white">件</span></h3>
              </div>
              <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border-t-8 border-blue-500">
                <h4 className="font-black text-xl mb-4 text-slate-900">熱門領用品項 (Top 5)</h4>
                <div className="space-y-3">{stats.filtered.invDetails.slice(0,5).map((it, i) => (<div key={i} className="flex justify-between p-3 bg-slate-50 rounded-xl font-black border"><span>{it.name}</span><span className="text-blue-600">{it.qty} 件</span></div>))}</div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-200">
            <table className="w-full text-left font-bold text-black">
              <thead className="bg-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b"><tr><th className="px-6 py-4">時間</th><th className="px-6 py-4">品項</th><th className="px-6 py-4">類別</th><th className="px-6 py-4">經手人</th><th className="px-6 py-4 text-right">補印</th></tr></thead>
              <tbody className="divide-y divide-slate-100">
                {logs.map(log => (<tr key={log.id} className="hover:bg-slate-50"><td className="px-6 py-4 text-xs text-slate-400">{new Date(log.timestamp).toLocaleString()}</td><td className="px-6 py-4 font-black text-black">{log.itemName} ({log.quantity})</td><td className="px-6 py-4">{log.type==='OUT' ? <span className="text-blue-600">領用</span> : <span className="text-emerald-600">補貨</span>}</td><td className="px-6 py-4">{log.person}</td><td className="px-6 py-4 text-right">{log.type==='OUT' && <button onClick={()=>{ setLastTransactionBatch({id: log.id, dept: log.dept, person: log.person, reason: log.reason, items: [{itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '個', spec: '', itemType: 'CONSUMABLE'}], timestamp: log.timestamp}); setShowPrintModal(true); }} className="text-slate-300 hover:text-blue-600"><Printer size={18}/></button>}</td></tr>))}
              </tbody>
            </table>
          </div>
        )}
      </main>

      {/* 彈出視窗：領用單預覽 (關鍵標楷體樣式) */}
      {showPrintModal && lastTransactionBatch && (
        <div className="fixed inset-0 bg-slate-900/95 z-[500] flex flex-col items-center justify-center p-6 animate-in zoom-in">
          <div className="bg-white rounded-[3rem] w-full max-w-5xl h-[90vh] shadow-2xl flex flex-col overflow-hidden">
            <div className="p-8 flex justify-between items-center border-b bg-white relative z-10 shadow-sm">
              <div className="flex items-center gap-4"><CheckCircle2 className="text-emerald-500" size={32}/><h3 className="font-black text-2xl text-black">領用單據生成預覽</h3></div>
              <div className="flex gap-4">
                <button onClick={() => handleFinalPrint(false)} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xl shadow-xl hover:scale-105 transition-all flex items-center gap-2"><Printer size={24}/> 直接列印 (標楷體)</button>
                <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-2xl text-black hover:bg-slate-200"><X size={32}/></button>
              </div>
            </div>
            <div className="flex-1 bg-slate-100 p-10 overflow-y-auto flex justify-center custom-scrollbar">
              <div className="bg-white shadow-2xl p-10 border rounded-sm w-[210mm] min-h-[297mm] text-black">
                <h1 className="text-center text-3xl font-bold mb-10 text-black">台灣電力公司電力修護處南部分處</h1>
                <div className="text-center text-xl font-bold underline mb-8 text-black">工安物資領用明細單</div>
                <div className="flex justify-between mb-8 font-bold text-lg text-black"><span>領用部門：{lastTransactionBatch.dept}</span><span>日期：{new Date(lastTransactionBatch.timestamp).toLocaleDateString()}</span></div>
                <table className="w-full border-2 border-black text-black">
                  <thead><tr className="bg-slate-50 border-b-2 border-black font-bold text-lg"><th className="border-r border-black p-4 text-black">名稱</th><th className="border-r border-black p-4 text-black">單位</th><th className="p-4 text-black">數量</th></tr></thead>
                  <tbody>{lastTransactionBatch.items.map((it, i) => (<tr key={i} className="border-b border-black text-center font-bold text-xl"><td className="border-r border-black p-6 text-black">{it.name}</td><td className="border-r border-black p-6 text-black">{it.unit || '個'}</td><td className="p-6 text-black">{it.quantity}</td></tr>))}</tbody>
                </table>
                <div className="mt-24 flex justify-between font-bold text-xl px-10 text-black"><span>領用簽章：{lastTransactionBatch.person}</span><span>經辦人：__________</span></div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 彈出視窗：新增編輯項目 */}
      {(editTarget || showAddModal) && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-4 animate-in zoom-in duration-300">
          <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl">
            <form className="space-y-6" onSubmit={handleSaveItem}>
              <h3 className="text-2xl font-black text-black mb-4">{editTarget ? '編輯管理項目' : '新增管理項目'}</h3>
              <div><label className="text-xs font-black text-slate-500 uppercase">名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl mt-2 font-bold text-black" defaultValue={editTarget?.name} /></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-xs font-black text-slate-500">目前庫存</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl mt-2 font-bold text-black" defaultValue={editTarget?.quantity || 0} /></div>
                <div><label className="text-xs font-black text-slate-500">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl mt-2 font-bold text-black" defaultValue={editTarget?.unit || '個'} /></div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-xs font-black text-slate-500">性質</label><select name="itemType" className="w-full p-4 rounded-xl mt-2 font-bold text-black" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="CONSUMABLE">消耗品</option><option value="EQUIPMENT">設備類</option></select></div>
                <div><label className="text-xs font-black text-slate-500">警戒數量</label><input name="minStock" type="number" className="w-full p-4 rounded-xl mt-2 font-bold text-black" defaultValue={editTarget?.minStock || 5} /></div>
              </div>
              <div><label className="text-xs font-black text-slate-500">規格 / 序號</label><input name="spec" type="text" className="w-full p-4 rounded-xl mt-2 font-bold text-black" defaultValue={editTarget?.spec} /></div>
              <div className="flex gap-4 pt-6">
                <button type="submit" className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl hover:bg-blue-700 active:scale-95 transition-all">儲存變更</button>
                <button type="button" onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="px-8 py-5 bg-slate-100 text-slate-400 rounded-2xl font-bold hover:bg-slate-200">取消</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* 彈出視窗：雲端連線設定 */}
      {showSettings && (
        <div className="fixed inset-0 bg-slate-900/80 z-[600] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl">
            <h3 className="text-2xl font-black mb-6 text-black flex items-center gap-2"><Cloud className="text-blue-600"/> 雲端資料庫設定</h3>
            <div><label className="text-xs font-black text-slate-500 uppercase">GAS Web App URL</label><input type="text" className="w-full p-4 rounded-xl font-bold border-2 mt-2 text-black" defaultValue={gasUrl} id="gas-url-input" placeholder="請貼上 GAS 網址"/></div>
            <div className="flex gap-4 mt-8">
              <button onClick={() => handleGasUrlSave((document.getElementById('gas-url-input') as HTMLInputElement).value)} className="flex-1 py-5 bg-slate-900 text-white rounded-2xl font-black text-lg">儲存並建立連線</button>
              <button onClick={() => setShowSettings(false)} className="px-8 py-5 bg-slate-100 text-slate-600 rounded-2xl font-black text-lg">返回</button>
            </div>
          </div>
        </div>
      )}

      {deleteTarget && (
        <div className="fixed inset-0 bg-slate-900/90 flex items-center justify-center p-4 z-[700] animate-in fade-in">
          <div className="bg-white p-10 rounded-3xl text-center max-sm shadow-2xl">
            <h3 className="text-2xl font-black mb-4 text-black">確定刪除？</h3>
            <p className="text-slate-400 font-bold mb-8">物資「{deleteTarget.name}」將從清單移除。</p>
            <div className="flex flex-col gap-3">
                <button onClick={()=>{ const newItems = items.filter(i => i.id !== deleteTarget.id); setItems(newItems); syncToCloud(newItems, logs); setDeleteTarget(null); }} className="w-full py-4 bg-red-600 text-white rounded-xl font-black shadow-lg hover:bg-red-700">確認刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="w-full py-3 text-slate-400 font-bold hover:text-black">取消</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search, 
  X, 
  Printer, 
  AlertTriangle, 
  BrainCircuit, 
  Stethoscope, 
  ShoppingCart, 
  CheckCircle2, 
  Users, 
  Download, 
  Upload, 
  FileDown, 
  ArrowUpRight, 
  ArrowDownLeft, 
  Settings, 
  Cloud, 
  RefreshCw, 
  Clock 
} from 'lucide-react';
import { GoogleGenAI } from "@google/genai";

// --- 內部整合：資料類型定義 ---
export enum Category {
  PROTECTION = '個人防護 (PPE)',
  FIRE_SAFETY = '消防安全',
  FIRST_AID = '急救耗材',
  SIGNAGE = '標誌警告',
  TOOL = '工具設備',
  OTHER = '其他'
}
export type ItemType = 'EQUIPMENT' | 'CONSUMABLE';
export type ItemGroup = 'INVENTORY' | 'MEDICINE';
export interface InventoryItem {
  id: string;
  name: string;
  category: Category;
  itemType: ItemType; 
  itemGroup: ItemGroup;
  unit: string;
  spec: string;
  quantity: number;
  minStock: number;
  purchaseDate?: string;
  expiryDate?: string;
  description: string;
  lastUpdated: number;
}
export type TransactionType = 'IN' | 'OUT';
export interface Transaction {
  id: string;
  itemId: string;
  itemName: string;
  type: TransactionType;
  quantity: number;
  person: string;
  dept: string;
  reason: string;
  timestamp: number;
}

// --- 內部整合：AI 服務 ---
const getInventoryInsights = async (items: InventoryItem[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const lowStock = items.filter(i => i.quantity <= i.minStock);
  const prompt = `這是一個工安耗材管理系統。當前庫存不足項目：${lowStock.map(i => i.name).join(', ')}。請以專業工安管理員身份提供 3 點具體建議。請用繁體中文回答。`;
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "目前庫存正常。";
  } catch (error) {
    return "AI 助理忙碌中，請稍後再試。";
  }
};

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

type SyncStatus = 'synced' | 'syncing' | 'error' | 'local';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');
  const [syncStatus, setSyncStatus] = useState<SyncStatus>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '從未同步');
  const [showSettings, setShowSettings] = useState(false);
  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [statsDeptFilter, setStatsDeptFilter] = useState<string>('ALL');
  const [statsYearFilter, setStatsYearFilter] = useState<number>(new Date().getFullYear());
  const [lastTransactionBatch, setLastTransactionBatch] = useState<{ id: string; dept: string; person: string; reason: string; items: BasketItem[]; timestamp: number; } | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const initLoad = async () => {
      const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
      const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
      if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
      if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
      setIsLoaded(true);
      if (gasUrl) { fetchFromCloud(); } else { setSyncStatus('local'); }
    };
    initLoad();
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const updateSyncTime = () => {
    const now = new Date().toLocaleTimeString('zh-TW', { hour12: false, hour: '2-digit', minute: '2-digit' });
    const fullTime = `${new Date().toLocaleDateString('zh-TW')} ${now}`;
    setLastSyncTime(fullTime);
    localStorage.setItem(STORAGE_KEY_LAST_SYNC, fullTime);
  };

  const syncToCloud = async (currentItems: InventoryItem[], currentLogs: Transaction[]) => {
    if (!gasUrl) { setSyncStatus('local'); return; }
    setSyncStatus('syncing');
    try {
      const payload = { items: currentItems, logs: currentLogs, timestamp: Date.now() };
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify(payload), mode: 'no-cors' });
      setSyncStatus('synced');
      updateSyncTime();
    } catch (err) { setSyncStatus('error'); }
  };

  const fetchFromCloud = async () => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const response = await fetch(gasUrl);
      const data = await response.json();
      if (data && data.items && data.logs) {
        setItems(data.items);
        setLogs(data.logs);
        setSyncStatus('synced');
        updateSyncTime();
      }
    } catch (err) { setSyncStatus('error'); }
  };

  const handleGasUrlSave = (newUrl: string) => {
    setGasUrl(newUrl);
    localStorage.setItem(STORAGE_KEY_GAS_URL, newUrl);
    setShowSettings(false);
    if (newUrl) { fetchFromCloud(); } else { setSyncStatus('local'); }
  };

  const exportData = () => {
    const data = { items, logs, timestamp: Date.now() };
    const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `工安管理備份_${new Date().toLocaleDateString().replace(/\//g, '-')}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const importData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (data.items && data.logs) {
          if (window.confirm("確定要導入此備份嗎？")) {
            setItems(data.items);
            setLogs(data.logs);
            syncToCloud(data.items, data.logs);
          }
        }
      } catch (err) { window.alert("格式錯誤"); }
    };
    reader.readAsText(file);
  };

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;
  const getReservedQty = (itemId: string) => basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);

  const currentAvailable = useMemo(() => {
    if (!selectedItemId) return 0;
    const item = items.find(i => i.id === selectedItemId);
    return item ? item.quantity - getReservedQty(selectedItemId) : 0;
  }, [selectedItemId, items, basket]);

  const isQtyOver = useMemo(() => {
    if (issuanceMode === 'IN') return false;
    const qty = Number(inputQty);
    return !isNaN(qty) && qty > currentAvailable;
  }, [inputQty, currentAvailable, issuanceMode]);

  const addToBasket = () => {
    if (!selectedItemId || isQtyOver) return;
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;
    const qty = Number(inputQty);
    setBasket(prev => [...prev, { itemId: targetItem.id, name: targetItem.name, quantity: qty, unit: targetItem.unit, spec: targetItem.spec, itemType: targetItem.itemType }]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const timestamp = Date.now();
    const batchId = generateId();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(bItem => {
      updatedItems = updatedItems.map(item => {
        if (item.id === bItem.itemId) {
          const newQty = issuanceMode === 'IN' ? item.quantity + bItem.quantity : item.quantity - bItem.quantity;
          return { ...item, quantity: newQty, lastUpdated: timestamp };
        }
        return item;
      });
      newLogs.push({ id: generateId() + Math.random().toString(36).substr(2, 4), itemId: bItem.itemId, itemName: bItem.name, type: issuanceMode, quantity: bItem.quantity, person: inputPerson || '未填寫', dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處', reason: inputReason, timestamp: timestamp });
    });

    setItems(updatedItems);
    setLogs([...newLogs, ...logs]);
    syncToCloud(updatedItems, [...newLogs, ...logs]);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({ id: batchId, dept: selectedDept, person: inputPerson, reason: inputReason, items: [...basket], timestamp: timestamp });
      setShowPrintModal(true);
    }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  const handleFinalPrint = (isPDF: boolean = false) => {
    if (!lastTransactionBatch) return;
    const date = new Date(lastTransactionBatch.timestamp);
    const isEquip = lastTransactionBatch.items.some(it => it.itemType === 'EQUIPMENT');
    const isConsum = lastTransactionBatch.items.every(it => it.itemType === 'CONSUMABLE') || !isEquip;

    const rows = lastTransactionBatch.items.map(item => `<tr><td style="text-align:center; color:black !important; padding: 12px; border: 1.5px solid black;">${item.name}</td><td style="text-align:center; color:black !important; border: 1.5px solid black;">${item.spec || ''}</td><td style="text-align:center; color:black !important; border: 1.5px solid black;">${item.unit}</td><td style="text-align:center; font-size:18pt; font-weight:bold; color:black !important; border: 1.5px solid black;">${item.quantity}</td><td style="text-align:center; color:black !important; border: 1.5px solid black;">${lastTransactionBatch.reason}</td></tr>`).join('');
    const emptyRows = Array(Math.max(0, 15 - lastTransactionBatch.items.length)).fill('<tr><td style="height:35px; border: 1.5px solid black;">&nbsp;</td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td></tr>').join('');

    const printWin = window.open('', '_blank', 'width=1100,height=900');
    if (!printWin) return;
    printWin.document.write(`
      <html><head><title>領用單_${lastTransactionBatch.id}</title><style>
            @font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); }
            body { font-family: 'StandardKai', serif; padding: 80px 60px; color: black !important; background: white; margin: 0; line-height: 1.2; }
            .title { text-align: center; font-size: 26pt; font-weight: bold; margin-bottom: 25px; color: black !important; }
            .checkbox-area { display: flex; justify-content: center; gap: 40px; font-size: 16pt; margin-bottom: 25px; font-weight: bold; color: black !important; }
            .checkbox { width: 22px; height: 22px; border: 2.5px solid black; display: inline-flex; align-items: center; justify-content: center; margin-right: 8px; vertical-align: middle; color: black !important; }
            .dept-row { font-size: 15pt; font-weight: bold; margin-bottom: 10px; display: flex; justify-content: space-between; color: black !important; }
            table { width: 100%; border-collapse: collapse; border: 2.5px solid black; margin-bottom: 25px; color: black !important; }
            th { border: 1.5px solid black; padding: 10px; text-align: center; font-size: 14pt; font-weight: bold; background: #f2f2f2; color: black !important; }
            td { color: black !important; text-align: center; }
            .sig-area { display: flex; justify-content: space-between; margin-top: 45px; font-size: 13pt; color: black !important; }
          </style></head><body>
          <div style="display: flex; flex-direction: column; align-items: flex-end;"><div style="font-size: 9pt; color: #666;">單號：${lastTransactionBatch.id}</div></div>
          <div class="title">台灣電力公司電力修護處南部分處</div>
          <div class="checkbox-area"><div><span class="checkbox">${isEquip ? 'V' : ''}</span>安全衛生設備借用單</div><div><span class="checkbox">${isConsum ? 'V' : ''}</span>安全衛生類消耗品領用單</div></div>
          <div class="dept-row"><div>部 門：<span style="border-bottom: 2px dotted black; min-width: 350px; display: inline-block; text-align: center;">${lastTransactionBatch.dept}</span></div><div>${date.getFullYear() - 1911} 年 ${date.getMonth() + 1} 月 ${date.getDate()} 日</div></div>
          <table><thead><tr><th>名稱</th><th>規範</th><th>單位</th><th>數量</th><th>備註</th></tr></thead><tbody>${rows}${emptyRows}</tbody></table>
          <div style="margin-top:30px; font-size:14pt; font-weight:bold; display:flex; justify-content:space-between;"><span>申請部門：</span><span>經管部門：</span></div>
          <div class="sig-area"><div style="flex:1; display:flex; justify-content:space-around;"><span>經辦：</span><span>課長：</span><span>經理：</span></div><div style="flex:1; display:flex; justify-content:space-around;"><span>經辦：</span><span>課長：</span><span>經理：</span></div></div>
          <script>window.onload = () => { setTimeout(() => { window.print(); window.close(); }, 600); };</script></body></html>
    `);
    printWin.document.close();
  };

  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = { name: formData.get('name') as string, itemType: formData.get('itemType') as ItemType, unit: formData.get('unit') as string, spec: formData.get('spec') as string, purchaseDate: formData.get('purchaseDate') as string, expiryDate: formData.get('expiryDate') as string, quantity: Number(formData.get('quantity')), minStock: Number(formData.get('minStock')) };
    let updated;
    if (editTarget) {
      updated = items.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i);
      setItems(updated); setEditTarget(null);
    } else {
      updated = [...items, { id: generateId(), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: Date.now() }];
      setItems(updated); setShowAddModal(false);
    }
    syncToCloud(updated, logs);
  };

  const stats = useMemo(() => {
    const filteredLogs = logs.filter(l => l.type === 'OUT' && (statsDeptFilter === 'ALL' || l.dept === statsDeptFilter));
    const invDetailMap: Record<string, {name: string, qty: number}> = {};
    const medDetailMap: Record<string, {name: string, qty: number}> = {};
    let fInvQty = 0, fMedQty = 0;
    filteredLogs.forEach(log => {
        const item = items.find(it => it.id === log.itemId);
        if (item?.itemGroup === 'MEDICINE') { fMedQty += log.quantity; if (!medDetailMap[log.itemId]) medDetailMap[log.itemId] = { name: log.itemName, qty: 0 }; medDetailMap[log.itemId].qty += log.quantity; }
        else { fInvQty += log.quantity; if (!invDetailMap[log.itemId]) invDetailMap[log.itemId] = { name: log.itemName, qty: 0 }; invDetailMap[log.itemId].qty += log.quantity; }
    });
    return {
      filtered: { invQty: fInvQty, medQty: fMedQty, invDetails: Object.values(invDetailMap).sort((a, b) => b.qty - a.qty), medDetails: Object.values(medDetailMap).sort((a, b) => b.qty - a.qty), },
      deptRanking: Object.entries(logs.filter(l => l.type === 'OUT').reduce((acc: any, curr) => { acc[curr.dept] = (acc[curr.dept] || 0) + curr.quantity; return acc; }, {})).sort((a: any, b: any) => b[1] - a[1])
    };
  }, [items, logs, statsDeptFilter, statsYearFilter]);

  return (
    <div className="min-h-screen flex bg-slate-100 text-black font-sans">
      <style>{`
        input, select, textarea { color: #000000 !important; background-color: #ffffff !important; border: 2px solid #94a3b8 !important; font-weight: 700 !important; }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
      `}</style>
      <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={importData} />
      <aside className="w-72 bg-slate-900 text-white p-6 flex flex-col shrink-0 border-r border-slate-800 shadow-2xl">
        <div className="flex flex-col gap-1 mb-8">
          <div className="flex items-center gap-3"><div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22} className="text-white"/></div><h1 className="font-black text-xl tracking-tight text-white">工安管理系統</h1></div>
          <div className="mt-6 bg-slate-800/50 rounded-2xl p-4 border border-slate-700/50">
            <div className="flex items-center justify-between mb-2"><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">雲端狀態</span><div className={`w-3 h-3 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.8)]' : 'bg-amber-500'}`}></div></div>
            <div className="text-sm font-black text-white">{syncStatus === 'synced' ? '已連線' : '同步中'}</div>
            <div className="text-[10px] text-slate-400 font-bold mt-1">最後同步：{lastSyncTime}</div>
          </div>
        </div>
        <nav className="flex-1 space-y-1">
          {[ { id: 'inventory', label: '工安耗材管理', icon: Package }, { id: 'medicine', label: '急救藥材管理', icon: Stethoscope }, { id: 'issuance', label: '領用補貨作業', icon: FileText }, { id: 'history', label: '歷史異動日誌', icon: History }, { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard }, ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}><tab.icon size={20} /> {tab.label}</button>
          ))}
        </nav>
        <div className="pt-6 mt-6 border-t border-slate-800 space-y-2">
            <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-black text-slate-300 hover:bg-slate-800"><Settings size={16}/> 雲端連線設定</button>
            <button onClick={exportData} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800"><Download size={16}/> 匯出備份</button>
        </div>
      </aside>

      <main className="flex-1 p-10 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-3xl font-black text-black">{activeTab === 'inventory' ? '工安耗材清冊' : activeTab === 'medicine' ? '急救藥材清冊' : activeTab === 'issuance' ? '領用 / 補貨登記' : activeTab === 'history' ? '歷史異動日誌' : '看板'}</h2>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-black shadow-xl"><Plus size={18}/> 新增項目</button>
          )}
        </header>

        {activeTab === 'issuance' && (
