ay:'inline-flex', alignItems:'center', justifyContent:'center', marginRight:'8px', verticalAlign:'middle', color: 'black'}}>{lastTransactionBatch.items.some(it => it.itemType === 'EQUIPMENT') ? 'V' : ''}</span> 設備借用單</div><div><span style={{border:'2.5px solid black', width:'20px', height:'20px', display:'inline-flex', alignItems:'center', justifyContent:'center', marginRight:'8px', verticalAlign:'middle', color: 'black'}}>{lastTransactionBatch.items.every(it => it.itemType === 'CONSUMABLE') ? 'V' : ''}</span> 消耗品領用單</div></div><div style={{display:'flex', justifyContent:'space-between', marginBottom:'15px', fontWeight:'bold', fontSize:'14pt', color: 'black'}} className="text-black"><div>部 門：<span style={{borderBottom:'1.5px dotted black', minWidth:'350px', display:'inline-block', textAlign:'center', color: 'black'}}>{lastTransactionBatch.dept}</span></div><div>{new Date(lastTransactionBatch.timestamp).getFullYear() - 1911} 年 {new Date(lastTransactionBatch.timestamp).getMonth() + 1} 月 {new Date(lastTransactionBatch.timestamp).getDate()} 日</div></div><table style={{width:'100%', borderCollapse:'collapse', border:'2px solid black', color: 'black'}} className="text-black"><thead><tr style={{background:'#f2f2f2'}}><th style={{padding:'8px', border:'1.5px solid black', color: 'black'}}>名稱</th><th style={{padding:'8px', border:'1.5px solid black', color: 'black'}}>規範</th><th style={{padding:'8px', border:'1.5px solid black', color: 'black'}}>單位</th><th style={{padding:'8px', border:'1.5px solid black', color: 'black'}}>數量</th><th style={{padding:'8px', border:'1.5px solid black', color: 'black'}}>備註</th></tr></thead><tbody>{lastTransactionBatch.items.map((it, i) => (<tr key={i}><td style={{textAlign:'center', padding:'12px', border:'1.5px solid black', color: 'black'}}>{it.name}</td><td style={{border:'1.5px solid black', textAlign:'center', color: 'black'}}>{it.spec}</td><td style={{border:'1.5px solid black', textAlign:'center', color: 'black'}}>{it.unit}</td><td style={{fontWeight:'bold', fontSize:'16pt', border:'1.5px solid black', textAlign:'center', color: 'black'}}>{it.quantity}</td><td style={{border:'1.5px solid black', textAlign:'center', color: 'black'}}>{lastTransactionBatch.reason}</td></tr>))}{Array(Math.max(0, 15 - lastTransactionBatch.items.length)).fill(0).map((_, i) => (<tr key={i + 100}><td style={{height:'35px', border:'1.5px solid black'}}>&nbsp;</td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td></tr>))}</tbody></table><div style={{marginTop:'35px', fontWeight:'bold', fontSize:'13pt', color: 'black'}} className="text-black"><div style={{display:'flex', justifyContent:'space-between'}}><div style={{flex:1}}>申請部門：</div><div style={{flex:1}}>經管部門：</div></div><div style={{display:'flex', justifyContent:'space-between', marginTop:'45px', fontSize:'12pt', color: 'black'}} className="text-black"><div style={{flex:1, display:'flex', justifyContent:'space-around', padding:'0 20px'}}><span>經辦：</span><span>課長：</span><span>經理：</span></div><div style={{flex:1, display:'flex', justifyContent:'space-around', padding:'0 20px'}}><span>經辦：</span><span>課長：</span><span>經理：</span></div></div></div></div></div></div></div></div>
        )}

        {(editTarget || showAddModal) && (
