  ArrowUpRight, ArrowDownLeft, Settings, Cloud, RefreshCw, Clock
} from 'lucide-react';
import { GoogleGenAI } from "@google/genai";

// --- 資料型別定義 ---
export enum Category { PROTECTION = '個人防護', FIRE_SAFETY = '消防安全', FIRST_AID = '急救耗材', SIGNAGE = '標誌警告', TOOL = '工具設備', OTHER = '其他' }
export type ItemType = 'EQUIPMENT' | 'CONSUMABLE';
export type ItemGroup = 'INVENTORY' | 'MEDICINE';
export interface InventoryItem { id: string; name: string; category: Category; itemType: ItemType; itemGroup: ItemGroup; unit: string; spec: string; quantity: number; minStock: number; purchaseDate?: string; expiryDate?: string; description: string; lastUpdated: number; }
export type TransactionType = 'IN' | 'OUT';
export interface Transaction { id: string; itemId: string; itemName: string; type: TransactionType; quantity: number; person: string; dept: string; reason: string; timestamp: number; }

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';
const DEPARTMENTS = ["工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"];

const App: React.FC = () => {
  // --- 狀態管理 ---
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error' | 'local'>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '從未同步');

  // 彈窗狀態
  const [showSettings, setShowSettings] = useState(false);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  // 領用作業狀態
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<any[]>([]);
  const [lastTransactionBatch, setLastTransactionBatch] = useState<any>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // --- 初始化與儲存 ---
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) try { setItems(JSON.parse(savedItems)); } catch(e){}
    if (savedLogs) try { setLogs(JSON.parse(savedLogs)); } catch(e){}
    setIsLoaded(true);
    if (gasUrl) fetchFromCloud();
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  // --- 雲端同步 ---
  const fetchFromCloud = async () => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const resp = await fetch(gasUrl);
      const data = await resp.json();
      if (data && data.items) {
        setItems(data.items);
        setLogs(data.logs || []);
        setSyncStatus('synced');
        setLastSyncTime(new Date().toLocaleString());
      }
    } catch (e) { setSyncStatus('error'); }
  };

  const syncToCloud = async (newItems: any, newLogs: any) => {
    if (!gasUrl) return;
    try {
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify({ items: newItems, logs: newLogs }), mode: 'no-cors' });
      setSyncStatus('synced');
    } catch(e) { setSyncStatus('error'); }
  };

  // --- 核心功能 ---
  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = {
      name: formData.get('name') as string,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
    };

    let updated;
    if (editTarget) {
      updated = items.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i);
      setItems(updated);
      setEditTarget(null);
    } else {
      updated = [...items, { 
        id: `ID-${Date.now()}`, 
        ...data, 
        itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
        category: Category.OTHER,
        description: '',
        lastUpdated: Date.now() 
      }];
      setItems(updated);
      setShowAddModal(false);
    }
    syncToCloud(updated, logs);
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const timestamp = Date.now();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(b => {
      updatedItems = updatedItems.map(it => {
        if (it.id === b.itemId) {
          const nQty = issuanceMode === 'IN' ? it.quantity + b.quantity : it.quantity - b.quantity;
          return { ...it, quantity: nQty, lastUpdated: timestamp };
        }
        return it;
      });
      newLogs.push({ id: `TX-${timestamp}-${Math.random()}`, itemId: b.itemId, itemName: b.name, type: issuanceMode, quantity: b.quantity, person: inputPerson || '未填寫', dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處', reason: inputReason, timestamp });
    });

    setItems(updatedItems);
    const finalLogs = [...newLogs, ...logs];
    setLogs(finalLogs);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({ id: `TX${timestamp.toString().slice(-6)}`, dept: selectedDept, person: inputPerson, reason: inputReason, items: [...basket], timestamp });
      setShowPrintModal(true);
    }
    syncToCloud(updatedItems, finalLogs);
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  // --- 列印格式 (標楷體 15 欄位) ---
  const handleFinalPrint = () => {
    if (!lastTransactionBatch) return;
    const date = new Date(lastTransactionBatch.timestamp);
