        .check-area { display: flex; justify-content: center; gap: 40px; font-size: 16pt; margin-bottom: 20px; font-weight: bold; }
        .box { width: 22px; height: 22px; border: 2.5px solid black; display: inline-flex; align-items: center; justify-content: center; margin-right: 8px; vertical-align: middle; }
        table { width: 100%; border-collapse: collapse; border: 2.5px solid black; text-align: center; }
        th { border: 1.5px solid black; padding: 10px; background: #eee; font-weight: bold; }
        td { border: 1.5px solid black; }
        .footer { margin-top: 40px; font-size: 14pt; font-weight: bold; display: flex; justify-content: space-between; }
      </style></head><body>
        <div class="title">台灣電力公司電力修護處南部分處</div>
        <div class="check-area">
          <div><span class="box">${isEquip?'V':''}</span>安全衛生設備借用單</div>
          <div><span class="box">${!isEquip?'V':''}</span>安全衛生類消耗品領用單</div>
        </div>
        <div style="display:flex; justify-content:space-between; font-size:15pt; font-weight:bold; margin-bottom:10px;">
          <span>部 門：${lastTransactionBatch.dept}</span>
          <span>${date.getFullYear()-1911} 年 ${date.getMonth()+1} 月 ${date.getDate()} 日</span>
        </div>
        <table><thead><tr><th>名稱</th><th>規範</th><th>單位</th><th>數量</th><th>備註</th></tr></thead><tbody>${rows}${emptyRows}</tbody></table>
        <div class="footer">
          <div style="flex:1">申請部門： 經辦 / 課長 / 經理</div>
          <div style="flex:1; text-align:right;">經管部門： 經辦 / 課長 / 經理</div>
        </div>
        <script>window.onload=()=>{ setTimeout(()=>{ window.print(); window.close(); }, 500); }</script>
      </body></html>
    `);
    win?.document.close();
  };

  return (
    <div className="min-h-screen flex bg-slate-100 text-black">
      {/* 側邊欄 */}
      <aside className="w-72 bg-slate-900 text-white p-6 flex flex-col shrink-0 border-r border-slate-800 shadow-2xl">
        <div className="flex items-center gap-3 mb-10">
