                <div>
                  <label className="text-xs font-black text-slate-500 uppercase">名稱選擇</label>
                  <select className="w-full p-4 rounded-xl mt-2 text-black font-bold border-2 border-slate-100" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                    <option value="">-- 請選擇 --</option>
