        </nav>
        <div className="mt-auto pt-6 border-t border-slate-800 space-y-2">
          <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-black text-slate-300 hover:bg-slate-800 transition-all"><Settings size={16}/> 雲端同步設定</button>
          <div className="px-4 py-3 bg-slate-800/50 rounded-xl">
