// --- 資料型別定義 ---
export enum Category { PROTECTION = '個人防護', FIRE_SAFETY = '消防安全', FIRST_AID = '急救耗材', SIGNAGE = '標誌警告', TOOL = '工具設備', OTHER = '其他' }
export type ItemType = 'EQUIPMENT' | 'CONSUMABLE';
export type ItemGroup = 'INVENTORY' | 'MEDICINE';
export interface InventoryItem { id: string; name: string; category: Category; itemType: ItemType; itemGroup: ItemGroup; unit: string; spec: string; quantity: number; minStock: number; purchaseDate?: string; expiryDate?: string; description: string; lastUpdated: number; }
export type TransactionType = 'IN' | 'OUT';
export interface Transaction { id: string; itemId: string; itemName: string; type: TransactionType; quantity: number; person: string; dept: string; reason: string; timestamp: number; }

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';
const DEPARTMENTS = ["工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"];

const App: React.FC = () => {
  // --- 狀態管理 ---
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error' | 'local'>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '從未同步');

  // 彈窗狀態
  const [showSettings, setShowSettings] = useState(false);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  // 領用作業狀態
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<any[]>([]);
  const [lastTransactionBatch, setLastTransactionBatch] = useState<any>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // --- 初始化與儲存 ---
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) try { setItems(JSON.parse(savedItems)); } catch(e){}
    if (savedLogs) try { setLogs(JSON.parse(savedLogs)); } catch(e){}
    setIsLoaded(true);
    if (gasUrl) fetchFromCloud();
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  // --- 雲端同步 ---
  const fetchFromCloud = async () => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const resp = await fetch(gasUrl);
      const data = await resp.json();
      if (data && data.items) {
        setItems(data.items);
        setLogs(data.logs || []);
        setSyncStatus('synced');
        setLastSyncTime(new Date().toLocaleString());
      }
    } catch (e) { setSyncStatus('error'); }
  };

  const syncToCloud = async (newItems: any, newLogs: any) => {
    if (!gasUrl) return;
    try {
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify({ items: newItems, logs: newLogs }), mode: 'no-cors' });
      setSyncStatus('synced');
    } catch(e) { setSyncStatus('error'); }
  };

  // --- 核心功能 ---
  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = {
      name: formData.get('name') as string,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
    };

    let updated;
    if (editTarget) {
      updated = items.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i);
      setItems(updated);
      setEditTarget(null);
    } else {
      updated = [...items, { 
        id: `ID-${Date.now()}`, 
        ...data, 
        itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
        category: Category.OTHER,
        description: '',
        lastUpdated: Date.now() 
      }];
      setItems(updated);
      setShowAddModal(false);
    }
    syncToCloud(updated, logs);
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const timestamp = Date.now();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(b => {
      updatedItems = updatedItems.map(it => {
        if (it.id === b.itemId) {
          const nQty = issuanceMode === 'IN' ? it.quantity + b.quantity : it.quantity - b.quantity;
          return { ...it, quantity: nQty, lastUpdated: timestamp };
        }
        return it;
      });
      newLogs.push({ id: `TX-${timestamp}-${Math.random()}`, itemId: b.itemId, itemName: b.name, type: issuanceMode, quantity: b.quantity, person: inputPerson || '未填寫', dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處', reason: inputReason, timestamp });
    });

    setItems(updatedItems);
    const finalLogs = [...newLogs, ...logs];
    setLogs(finalLogs);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({ id: `TX${timestamp.toString().slice(-6)}`, dept: selectedDept, person: inputPerson, reason: inputReason, items: [...basket], timestamp });
      setShowPrintModal(true);
    }
    syncToCloud(updatedItems, finalLogs);
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  // --- 列印格式 (標楷體 15 欄位) ---
  const handleFinalPrint = () => {
    if (!lastTransactionBatch) return;
    const date = new Date(lastTransactionBatch.timestamp);
    const isEquip = lastTransactionBatch.items.some((it:any) => it.itemType === 'EQUIPMENT');
    const rows = lastTransactionBatch.items.map((it:any) => `<tr><td style="border:1.5px solid black; padding:12px;">${it.name}</td><td style="border:1.5px solid black;">${it.spec||''}</td><td style="border:1.5px solid black;">${it.unit}</td><td style="border:1.5px solid black; font-size:18pt; font-weight:bold;">${it.quantity}</td><td style="border:1.5px solid black;">${lastTransactionBatch.reason}</td></tr>`).join('');
    const emptyRows = Array(Math.max(0, 15 - lastTransactionBatch.items.length)).fill('<tr><td style="height:35px; border:1.5px solid black;">&nbsp;</td><td style="border:1.5px solid black;"></td><td style="border:1.5px solid black;"></td><td style="border:1.5px solid black;"></td><td style="border:1.5px solid black;"></td></tr>').join('');

    const win = window.open('', '_blank');
    win?.document.write(`
      <html><head><title>領用單</title><style>
        @font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); }
        body { font-family: 'StandardKai', serif; padding: 60px; color: black; background: white; }
        .title { text-align: center; font-size: 26pt; font-weight: bold; margin-bottom: 30px; }
        .check-area { display: flex; justify-content: center; gap: 40px; font-size: 16pt; margin-bottom: 20px; font-weight: bold; }
        .box { width: 22px; height: 22px; border: 2.5px solid black; display: inline-flex; align-items: center; justify-content: center; margin-right: 8px; vertical-align: middle; }
        table { width: 100%; border-collapse: collapse; border: 2.5px solid black; text-align: center; }
        th { border: 1.5px solid black; padding: 10px; background: #eee; font-weight: bold; }
        td { border: 1.5px solid black; }
        .footer { margin-top: 40px; font-size: 14pt; font-weight: bold; display: flex; justify-content: space-between; }
      </style></head><body>
        <div class="title">台灣電力公司電力修護處南部分處</div>
        <div class="check-area">
          <div><span class="box">${isEquip?'V':''}</span>安全衛生設備借用單</div>
          <div><span class="box">${!isEquip?'V':''}</span>安全衛生類消耗品領用單</div>
        </div>
        <div style="display:flex; justify-content:space-between; font-size:15pt; font-weight:bold; margin-bottom:10px;">
          <span>部 門：${lastTransactionBatch.dept}</span>
          <span>${date.getFullYear()-1911} 年 ${date.getMonth()+1} 月 ${date.getDate()} 日</span>
        </div>
        <table><thead><tr><th>名稱</th><th>規範</th><th>單位</th><th>數量</th><th>備註</th></tr></thead><tbody>${rows}${emptyRows}</tbody></table>
        <div class="footer">
          <div style="flex:1">申請部門： 經辦 / 課長 / 經理</div>
          <div style="flex:1; text-align:right;">經管部門： 經辦 / 課長 / 經理</div>
        </div>
        <script>window.onload=()=>{ setTimeout(()=>{ window.print(); window.close(); }, 500); }</script>
      </body></html>
    `);
    win?.document.close();
  };

  // --- 計算 Dashboard 數據 ---
  const dashboardStats = useMemo(() => {
    const lowStockCount = items.filter(it => it.quantity <= it.minStock).length;
    const totalItems = items.length;
    const today = new Date().setHours(0,0,0,0);
    const todayLogs = logs.filter(l => l.timestamp >= today && l.type === 'OUT').length;
    return { lowStockCount, totalItems, todayLogs };
  }, [items, logs]);

  return (
    <div className="min-h-screen flex bg-slate-100 text-black">
      {/* 側邊欄 */}
      <aside className="w-72 bg-slate-900 text-white p-6 flex flex-col shrink-0 border-r border-slate-800 shadow-2xl">
        <div className="flex items-center gap-3 mb-10">
          <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22}/></div>
          <h1 className="font-black text-xl tracking-tight">工安管理系統</h1>
        </div>
        <nav className="flex-1 space-y-1">
          {[
            { id: 'inventory', label: '耗材管理', icon: Package },
            { id: 'medicine', label: '藥材管理', icon: Stethoscope },
            { id: 'issuance', label: '領用補貨', icon: FileText },
            { id: 'history', label: '歷史紀錄', icon: History },
            { id: 'dashboard', label: '統計看板', icon: LayoutDashboard }
          ].map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}>
              <tab.icon size={20}/> {tab.label}
            </button>
          ))}
        </nav>
        <div className="mt-auto pt-6 border-t border-slate-800 space-y-2">
          <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-black text-slate-300 hover:bg-slate-800 transition-all"><Settings size={16}/> 雲端同步設定</button>
          <div className="px-4 py-3 bg-slate-800/50 rounded-xl">
             <div className="flex justify-between items-center mb-1">
               <span className="text-[10px] font-black text-slate-500">連線狀態</span>
               <div className={`w-2 h-2 rounded-full ${syncStatus==='synced'?'bg-emerald-500':'bg-orange-500 animate-pulse'}`}></div>
             </div>
             <div className="text-[10px] text-slate-400 truncate">{lastSyncTime}</div>
          </div>
        </div>
      </aside>

      {/* 主內容區 */}
      <main className="flex-1 p-10 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <div>
            <h2 className="text-3xl font-black text-slate-800">
              {activeTab === 'inventory' ? '工安耗材清冊' : 
               activeTab === 'medicine' ? '急救藥材清冊' : 
               activeTab === 'issuance' ? '領用補貨作業' : 
               activeTab === 'history' ? '歷史異動紀錄' : '系統統計看板'}
            </h2>
          </div>
          {(activeTab==='inventory'||activeTab==='medicine') && (
            <button onClick={()=>setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-black shadow-xl transition-all"><Plus size={18}/> 新增項目</button>
          )}
        </header>

        {/* 1. 領用補貨頁面 */}
        {activeTab === 'issuance' && (
          <div className="grid grid-cols-5 gap-8">
            <div className="col-span-2 bg-white p-8 rounded-[2rem] shadow-xl border border-slate-200">
              <h3 className="text-xl font-black mb-8 flex items-center gap-2"><ShoppingCart className="text-blue-500"/> 1. 挑選品項</h3>
              <div className="space-y-6">
                <div>
                  <label className="text-xs font-black text-slate-500 uppercase">分類篩選</label>
                  <div className="flex gap-2 mt-2">
                    <button onClick={()=>setIssuanceGroup('INVENTORY')} className={`flex-1 py-3 rounded-xl font-bold border-2 transition-all ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-100 text-slate-400'}`}>耗材類</button>
                    <button onClick={()=>setIssuanceGroup('MEDICINE')} className={`flex-1 py-3 rounded-xl font-bold border-2 transition-all ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-100 text-slate-400'}`}>藥材類</button>
                  </div>
                </div>
                <div>
                  <label className="text-xs font-black text-slate-500 uppercase">名稱選擇</label>
                  <select className="w-full p-4 rounded-xl mt-2 text-black font-bold border-2 border-slate-100" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                    <option value="">-- 請選擇 --</option>
                    {items.filter(it=>it.itemGroup===issuanceGroup).map(i => <option key={i.id} value={i.id}>{i.name} (剩餘:{i.quantity})</option>)}
                  </select>
                </div>
                <div>
                  <label className="text-xs font-black text-slate-500 uppercase">數量</label>
                  <input type="number" className="w-full p-4 rounded-xl mt-2 font-bold" value={inputQty} onChange={e=>setInputQty(e.target.value)}/>
                </div>
                <button onClick={() => {
                  const item = items.find(it => it.id === selectedItemId);
                  if(item) setBasket([...basket, { itemId: item.id, name: item.name, quantity: Number(inputQty), unit: item.unit, spec: item.spec, itemType: item.itemType }]);
                  setSelectedItemId(''); setInputQty('1');
                }} disabled={!selectedItemId} className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black shadow-lg disabled:opacity-30">加入暫存清單</button>
              </div>
            </div>
            <div className="col-span-3 bg-white p-8 rounded-[2rem] shadow-xl border border-slate-200 flex flex-col">
              <h3 className="text-xl font-black mb-6 flex items-center gap-2"><FileText className="text-emerald-500"/> 2. 領用資料與確認</h3>
              <div className="flex-1 border-2 border-dashed border-slate-100 rounded-2xl mb-6 p-4 bg-slate-50 min-h-[200px]">
                {basket.length > 0 ? basket.map((b, i) => (
                  <div key={i} className="flex justify-between p-4 bg-white rounded-xl mb-2 shadow-sm font-bold border border-slate-100">
                    <span className="text-slate-800">{b.name}</span>
                    <div className="flex items-center gap-4">
                      <span className="text-blue-600">{b.quantity} {b.unit}</span>
                      <button onClick={()=>setBasket(basket.filter((_,idx)=>idx!==i))} className="text-slate-300 hover:text-red-500"><X size={16}/></button>
                    </div>
                  </div>
                )) : <div className="h-full flex items-center justify-center text-slate-300 font-bold italic">尚未加入任何品項</div>}
              </div>
              <div className="grid grid-cols-2 gap-6 mb-8">
                <div><label className="text-xs font-black text-slate-500 uppercase">部門</label><select className="w-full p-3 rounded-xl mt-1 font-bold" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>{DEPARTMENTS.map(d=><option key={d}>{d}</option>)}</select></div>
                <div><label className="text-xs font-black text-slate-500 uppercase">人員</label><input type="text" className="w-full p-3 rounded-xl mt-1 font-bold" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div>
                <div className="col-span-2"><label className="text-xs font-black text-slate-500 uppercase">用途</label><input type="text" className="w-full p-3 rounded-xl mt-1 font-bold" value={inputReason} onChange={e=>setInputReason(e.target.value)}/></div>
              </div>
              <button onClick={processIssuance} disabled={basket.length===0} className="w-full py-6 bg-blue-600 text-white rounded-2xl font-black text-2xl shadow-2xl transition-all active:scale-95 disabled:opacity-30">確認領用並生成單據</button>
            </div>
          </div>
        )}

        {/* 2. 耗材 / 藥材管理頁面 */}
        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-[2rem] shadow-xl border border-slate-200 overflow-hidden">
             <div className="p-6 bg-slate-50 border-b flex justify-between items-center">
                <div className="relative w-72"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16}/><input type="text" placeholder="搜尋名稱..." className="w-full pl-10 pr-4 py-2 rounded-xl text-sm font-bold" value={searchTerm} onChange={e=>setSearchTerm(e.target.value)}/></div>
             </div>
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase tracking-widest border-b">
                <tr><th className="px-8 py-5">物資名稱及規格</th><th className="px-8 py-5 text-center">目前庫存</th><th className="px-8 py-5 text-right">管理操作</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(it => (activeTab==='medicine'?it.itemGroup==='MEDICINE':it.itemGroup==='INVENTORY') && it.name.includes(searchTerm)).map(it => (
                  <tr key={it.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-8 py-5"><div className="font-black text-slate-800 text-lg">{it.name}</div><div className="text-xs text-slate-400 font-bold mt-1">{it.spec || '無規格資訊'}</div></td>
                    <td className="px-8 py-5 text-center"><span className={`px-6 py-2 rounded-xl text-xl font-black shadow-sm ${it.quantity<=it.minStock?'bg-red-50 text-red-600 border border-red-100':'bg-emerald-50 text-emerald-600 border border-emerald-100'}`}>{it.quantity} {it.unit}</span></td>
                    <td className="px-8 py-5 text-right"><button onClick={()=>setEditTarget(it)} className="text-slate-300 hover:text-blue-600 p-2 transition-colors"><Edit3 size={20}/></button><button onClick={()=>setDeleteTarget({id:it.id, name:it.name})} className="text-slate-300 hover:text-red-600 p-2 transition-colors"><Trash2 size={20}/></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* 3. 歷史紀錄頁面 (修復空白問題) */}
        {activeTab === 'history' && (
          <div className="bg-white rounded-[2rem] shadow-xl border border-slate-200 overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase tracking-widest border-b">
                <tr><th className="px-8 py-5">時間</th><th className="px-8 py-5">項目名稱</th><th className="px-8 py-5">類型</th><th className="px-8 py-5 text-center">數量</th><th className="px-8 py-5">人員 / 部門</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100 font-bold">
                {logs.length > 0 ? logs.map(log => (
                  <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-8 py-4 text-xs text-slate-400">{new Date(log.timestamp).toLocaleString()}</td>
                    <td className="px-8 py-4 text-slate-800">{log.itemName}</td>
                    <td className="px-8 py-4">
                      <span className={`px-3 py-1 rounded-lg text-xs ${log.type === 'OUT' ? 'bg-orange-50 text-orange-600' : 'bg-blue-50 text-blue-600'}`}>
                        {log.type === 'OUT' ? '領用' : '補貨'}
                      </span>
                    </td>
                    <td className="px-8 py-4 text-center font-black">{log.quantity}</td>
                    <td className="px-8 py-4 text-sm">{log.person} <span className="text-slate-300 mx-1">/</span> {log.dept}</td>
                  </tr>
                )) : <tr><td colSpan={5} className="p-20 text-center text-slate-300 italic font-black">尚無任何異動紀錄</td></tr>}
              </tbody>
            </table>
          </div>
        )}

        {/* 4. 統計看板頁面 (修復空白問題) */}
        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            <div className="grid grid-cols-3 gap-8">
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border border-slate-200">
                <div className="flex justify-between items-start mb-4">
                  <div className="p-4 bg-red-50 text-red-600 rounded-2xl"><AlertTriangle size={32}/></div>
                  <span className="text-xs font-black text-slate-400 uppercase">Inventory Health</span>
                </div>
                <div className="text-4xl font-black text-slate-800">{dashboardStats.lowStockCount}</div>
                <div className="text-sm font-bold text-slate-500 mt-2">項物資低於警戒庫存</div>
              </div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border border-slate-200">
                <div className="flex justify-between items-start mb-4">
                  <div className="p-4 bg-blue-50 text-blue-600 rounded-2xl"><Package size={32}/></div>
                  <span className="text-xs font-black text-slate-400 uppercase">Total Items</span>
                </div>
                <div className="text-4xl font-black text-slate-800">{dashboardStats.totalItems}</div>
                <div className="text-sm font-bold text-slate-500 mt-2">系統管理總品項數</div>
              </div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border border-slate-200">
                <div className="flex justify-between items-start mb-4">
                  <div className="p-4 bg-emerald-50 text-emerald-600 rounded-2xl"><Activity size={32}/></div>
                  <span className="text-xs font-black text-slate-400 uppercase">Today Activity</span>
                </div>
                <div className="text-4xl font-black text-slate-800">{dashboardStats.todayLogs}</div>
                <div className="text-sm font-bold text-slate-500 mt-2">今日累計領用次數</div>
              </div>
            </div>

            <div className="bg-slate-900 rounded-[2.5rem] p-10 text-white shadow-2xl relative overflow-hidden">
               <div className="relative z-10">
                  <h3 className="text-2xl font-black mb-2 flex items-center gap-2"><BrainCircuit className="text-blue-400"/> 智能庫存診斷</h3>
                  <p className="text-slate-400 font-bold">根據目前數據，建議優先補貨以下項目：</p>
                  <div className="mt-6 flex flex-wrap gap-3">
                    {items.filter(it => it.quantity <= it.minStock).slice(0, 5).map(it => (
                      <div key={it.id} className="bg-white/10 backdrop-blur-md px-5 py-3 rounded-2xl border border-white/10 flex items-center gap-3">
                        <span className="font-black">{it.name}</span>
                        <span className="text-red-400 font-black">剩 {it.quantity} {it.unit}</span>
                      </div>
                    ))}
                    {items.filter(it => it.quantity <= it.minStock).length === 0 && <div className="text-emerald-400 font-black">🎉 目前所有庫存狀態良好，無須緊急補貨。</div>}
                  </div>
               </div>
               <div className="absolute -right-20 -bottom-20 opacity-10"><Package size={300}/></div>
            </div>
          </div>
        )}

        {/* --- 彈窗區塊 --- */}

        {/* 新增與編輯彈窗 */}
        {(showAddModal || editTarget) && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[600] flex items-center justify-center p-4">
             <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl animate-in zoom-in duration-300">
                <form className="space-y-6" onSubmit={handleSaveItem}>
                   <div className="flex justify-between items-center mb-4"><h3 className="text-2xl font-black text-slate-800">{editTarget ? '編輯項目資料' : '新增管理項目'}</h3><button type="button" onClick={()=>{setShowAddModal(false); setEditTarget(null);}} className="text-slate-300 hover:text-black"><X size={24}/></button></div>
                   <div><label className="text-xs font-black text-slate-500 uppercase">物資名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.name} /></div>
                   <div className="grid grid-cols-2 gap-6">
                      <div><label className="text-xs font-black text-slate-500">分類</label><select name="itemType" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="EQUIPMENT">安全衛生設備</option><option value="CONSUMABLE">安全衛生類消耗品</option></select></div>
                      <div><label className="text-xs font-black text-slate-500">規格 / 序號</label><input name="spec" type="text" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.spec} /></div>
                   </div>
                   <div className="grid grid-cols-3 gap-6">
                      <div><label className="text-xs font-black text-slate-500">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.unit || '個'} /></div>
                      <div><label className="text-xs font-black text-slate-500">目前庫存</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.quantity || 0} /></div>
                      <div><label className="text-xs font-black text-slate-500">警戒數量</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.minStock || 5} /></div>
                   </div>
                   <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl hover:bg-blue-700 transition-all">儲存物資資料</button>
                </form>
             </div>
          </div>
        )}

        {/* 列印預覽彈窗 */}
        {showPrintModal && (
          <div className="fixed inset-0 bg-slate-900/95 flex flex-col items-center justify-center p-6 z-[700]">
             <div className="bg-white rounded-[3rem] w-full max-w-5xl h-[90vh] shadow-2xl flex flex-col overflow-hidden animate-in fade-in duration-300">
                <div className="p-8 flex justify-between items-center border-b bg-white relative z-10 shadow-sm">
                   <div className="flex items-center gap-4"><CheckCircle2 className="text-emerald-500" size={32}/><h3 className="font-black text-2xl text-black">單據生成預覽</h3></div>
                   <div className="flex gap-4">
                      <button onClick={handleFinalPrint} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xl shadow-xl hover:scale-105 transition-all flex items-center gap-2"><Printer size={24}/> 列印單據 (標楷體)</button>
                      <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-2xl text-slate-400 hover:text-black transition-all"><X size={32}/></button>
                   </div>
                </div>
                <div className="flex-1 bg-slate-200 p-10 overflow-y-auto flex justify-center shadow-inner">
                   <div className="bg-white shadow-2xl p-10 border rounded-sm origin-top mb-10 scale-90">
                      <div className="w-[210mm] text-black">
                         <h1 className="text-center text-3xl font-bold mb-8 font-serif">台灣電力公司電力修護處南部分處</h1>
                         <div className="flex justify-center gap-10 text-xl font-bold mb-8 font-serif">
                            <div>[ {lastTransactionBatch?.items.some((it:any)=>it.itemType==='EQUIPMENT')?'V':' '} ] 設備借用單</div>
                            <div>[ {lastTransactionBatch?.items.every((it:any)=>it.itemType==='CONSUMABLE')?'V':' '} ] 消耗品領用單</div>
                         </div>
                         <div className="flex justify-between font-bold mb-4 px-2 font-serif">
                            <span>部門：{lastTransactionBatch?.dept}</span>
                            <span>日期：{new Date().toLocaleDateString()}</span>
                         </div>
                         <table className="w-full border-2 border-black text-center font-serif">
                            <thead><tr className="bg-slate-50"><th className="border border-black p-3">品名</th><th className="border border-black p-3">規格</th><th className="border border-black p-3">單位</th><th className="border border-black p-3">數量</th><th className="border border-black p-3">備註</th></tr></thead>
                            <tbody>
                               {lastTransactionBatch?.items.map((it:any, i:number)=><tr key={i} className="h-10"><td className="border border-black font-bold">{it.name}</td><td className="border border-black">{it.spec}</td><td className="border border-black">{it.unit}</td><td className="border border-black text-2xl font-black">{it.quantity}</td><td className="border border-black">{lastTransactionBatch.reason}</td></tr>)}
                               {Array(Math.max(0, 15 - (lastTransactionBatch?.items.length || 0))).fill(0).map((_, i)=><tr key={i+100} className="h-10"><td className="border border-black">&nbsp;</td><td className="border border-black"></td><td className="border border-black"></td><td className="border border-black"></td><td className="border border-black"></td></tr>)}
                            </tbody>
                         </table>
                         <div className="mt-10 flex justify-between font-bold px-4 text-lg font-serif">
                            <span>申請部門： 經辦 / 課長 / 經理</span>
                            <span>經管部門： 經辦 / 課長 / 經理</span>
                         </div>
                      </div>
                   </div>
                </div>
             </div>
          </div>
        )}

        {/* 雲端設定彈窗 */}
        {showSettings && (
          <div className="fixed inset-0 bg-slate-900/80 flex items-center justify-center p-6 z-[800]">
             <div className="bg-white rounded-[2rem] w-full max-w-lg p-10 shadow-2xl">
                <h3 className="text-2xl font-black mb-6 flex items-center gap-3"><Cloud className="text-blue-500"/> 雲端連線同步</h3>
                <label className="text-xs font-black text-slate-500 uppercase">Google GAS Web App URL</label>
                <input type="text" className="w-full p-4 rounded-xl border-2 mt-2 font-bold" placeholder="貼上網址..." defaultValue={gasUrl} id="gasUrlInput"/>
                <div className="flex gap-4 mt-8">
                  <button onClick={() => { 
                    const url = (document.getElementById('gasUrlInput') as HTMLInputElement).value;
                    setGasUrl(url); localStorage.setItem(STORAGE_KEY_GAS_URL, url); setShowSettings(false); fetchFromCloud();
                  }} className="flex-1 py-4 bg-slate-900 text-white rounded-2xl font-black shadow-lg hover:bg-black transition-all">儲存並立即連線</button>
                  <button onClick={()=>setShowSettings(false)} className="px-8 py-4 bg-slate-100 rounded-2xl font-bold hover:bg-slate-200 transition-all">取消</button>
                </div>
             </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

