import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, Package, FileText, History, Plus, Trash2, Edit3,
  Search, X, Printer, AlertTriangle, BrainCircuit, Stethoscope,
  ShoppingCart, CheckCircle2, Users, Download, Upload, FileDown,
  ArrowUpRight, ArrowDownLeft, Settings, Cloud, RefreshCw, Clock,
  Activity
} from 'lucide-react';
import { GoogleGenAI } from "@google/genai";

// --- 1. 資料型別與常數定義 (整合自原 types.ts) ---
export enum Category { PROTECTION = '個人防護', FIRE_SAFETY = '消防安全', FIRST_AID = '急救耗材', SIGNAGE = '標誌警告', TOOL = '工具設備', OTHER = '其他' }
export type ItemType = 'EQUIPMENT' | 'CONSUMABLE';
export type ItemGroup = 'INVENTORY' | 'MEDICINE';
export interface InventoryItem { id: string; name: string; category: Category; itemType: ItemType; itemGroup: ItemGroup; unit: string; spec: string; quantity: number; minStock: number; purchaseDate?: string; expiryDate?: string; description: string; lastUpdated: number; }
export type TransactionType = 'IN' | 'OUT';
export interface Transaction { id: string; itemId: string; itemName: string; type: TransactionType; quantity: number; person: string; dept: string; reason: string; timestamp: number; }

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';
const DEPARTMENTS = ["工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"];

// --- 2. AI 服務 (整合自原 geminiService.ts) ---
async function getInventoryInsights(items: InventoryItem[]) {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  const lowStock = items.filter(i => i.quantity <= i.minStock).map(i => `${i.name}(剩${i.quantity}${i.unit})`).join(', ');
  const prompt = `你是一位專業的工安資材專家。目前庫存中有以下物資低於警戒值：${lowStock || '無'}。請根據這份清單給出簡短專業的採購建議與庫存風險評估（約150字內）。`;
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt
    });
    return response.text || '暫無建議。';
  } catch (e) { return '無法連線至 AI 建議服務。'; }
}

const App: React.FC = () => {
  // --- 狀態管理 ---
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error' | 'local'>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '從未同步');

  // 介面控制狀態
  const [showSettings, setShowSettings] = useState(false);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [aiInsights, setAiInsights] = useState('');

  // 領用作業狀態
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<any[]>([]);
  const [lastTransactionBatch, setLastTransactionBatch] = useState<any>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- 初始化與儲存邏輯 ---
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
    const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
    if (savedItems) try { setItems(JSON.parse(savedItems)); } catch(e){}
    if (savedLogs) try { setLogs(JSON.parse(savedLogs)); } catch(e){}
    setIsLoaded(true);
    if (gasUrl) fetchFromCloud();
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  // --- 雲端同步功能 ---
  const fetchFromCloud = async () => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const resp = await fetch(gasUrl);
      const data = await resp.json();
      if (data && data.items) {
        setItems(data.items);
        setLogs(data.logs || []);
        setSyncStatus('synced');
        const now = new Date().toLocaleString();
        setLastSyncTime(now);
        localStorage.setItem(STORAGE_KEY_LAST_SYNC, now);
      }
    } catch (e) { setSyncStatus('error'); }
  };

  const syncToCloud = async (newItems: any, newLogs: any) => {
    if (!gasUrl) return;
    try {
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify({ items: newItems, logs: newLogs }), mode: 'no-cors' });
      setSyncStatus('synced');
    } catch(e) { setSyncStatus('error'); }
  };

  // --- 核心業務邏輯 ---
  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = {
      name: formData.get('name') as string,
      itemType: formData.get('itemType') as ItemType,
      unit: formData.get('unit') as string,
      spec: formData.get('spec') as string,
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
      quantity: Number(formData.get('quantity')),
      minStock: Number(formData.get('minStock')),
    };

    let updated;
    if (editTarget) {
      updated = items.map(i => i.id === editTarget.id ? { ...editTarget, ...data } : i);
      setItems(updated);
      setEditTarget(null);
    } else {
      updated = [...items, { 
        id: `ID-${Date.now()}`, 
        ...data, 
        itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY',
        category: Category.OTHER,
        description: '',
        lastUpdated: Date.now() 
      }];
      setItems(updated);
      setShowAddModal(false);
    }
    syncToCloud(updated, logs);
  };

  const processIssuance = () => {
    if (basket.length === 0) return;
    const timestamp = Date.now();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(b => {
      updatedItems = updatedItems.map(it => {
        if (it.id === b.itemId) {
          const nQty = issuanceMode === 'IN' ? it.quantity + b.quantity : it.quantity - b.quantity;
          return { ...it, quantity: nQty, lastUpdated: timestamp };
        }
        return it;
      });
      newLogs.push({ 
        id: `TX-${timestamp}-${Math.random().toString(36).substr(2, 4)}`, 
        itemId: b.itemId, 
        itemName: b.name, 
        type: issuanceMode, 
        quantity: b.quantity, 
        person: inputPerson || '未填寫', 
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處', 
        reason: inputReason, 
        timestamp 
      });
    });

    setItems(updatedItems);
    const finalLogs = [...newLogs, ...logs];
    setLogs(finalLogs);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({ id: `TX${timestamp.toString().slice(-6)}`, dept: selectedDept, person: inputPerson, reason: inputReason, items: [...basket], timestamp });
      setShowPrintModal(true);
    }
    syncToCloud(updatedItems, finalLogs);
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  const handleFinalPrint = () => {
    if (!lastTransactionBatch) return;
    const date = new Date(lastTransactionBatch.timestamp);
    const isEquip = lastTransactionBatch.items.some((it:any) => it.itemType === 'EQUIPMENT');
    const rows = lastTransactionBatch.items.map((it:any) => `<tr><td style="border:1.5px solid black; padding:12px;">${it.name}</td><td style="border:1.5px solid black;">${it.spec||''}</td><td style="border:1.5px solid black;">${it.unit}</td><td style="border:1.5px solid black; font-size:18pt; font-weight:bold;">${it.quantity}</td><td style="border:1.5px solid black;">${lastTransactionBatch.reason}</td></tr>`).join('');
    const emptyRows = Array(Math.max(0, 15 - lastTransactionBatch.items.length)).fill('<tr><td style="height:35px; border:1.5px solid black;">&nbsp;</td><td style="border:1.5px solid black;"></td><td style="border:1.5px solid black;"></td><td style="border:1.5px solid black;"></td><td style="border:1.5px solid black;"></td></tr>').join('');

    const win = window.open('', '_blank');
    win?.document.write(`
      <html><head><title>領用單</title><style>
        @font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); }
        body { font-family: 'StandardKai', serif; padding: 60px; color: black; background: white; }
        .title { text-align: center; font-size: 26pt; font-weight: bold; margin-bottom: 30px; }
        .check-area { display: flex; justify-content: center; gap: 40px; font-size: 16pt; margin-bottom: 20px; font-weight: bold; }
        .box { width: 22px; height: 22px; border: 2.5px solid black; display: inline-flex; align-items: center; justify-content: center; margin-right: 8px; vertical-align: middle; }
        table { width: 100%; border-collapse: collapse; border: 2.5px solid black; text-align: center; }
        th { border: 1.5px solid black; padding: 10px; background: #eee; font-weight: bold; }
        td { border: 1.5px solid black; }
        .footer { margin-top: 40px; font-size: 14pt; font-weight: bold; display: flex; justify-content: space-between; }
      </style></head><body>
        <div class="title">台灣電力公司電力修護處南部分處</div>
        <div class="check-area">
          <div><span class="box">${isEquip?'V':''}</span>安全衛生設備借用單</div>
          <div><span class="box">${!isEquip?'V':''}</span>安全衛生類消耗品領用單</div>
        </div>
        <div style="display:flex; justify-content:space-between; font-size:15pt; font-weight:bold; margin-bottom:10px;">
          <span>部 門：${lastTransactionBatch.dept}</span>
          <span>${date.getFullYear()-1911} 年 ${date.getMonth()+1} 月 ${date.getDate()} 日</span>
        </div>
        <table><thead><tr><th>名稱</th><th>規範</th><th>單位</th><th>數量</th><th>備註</th></tr></thead><tbody>${rows}${emptyRows}</tbody></table>
        <div class="footer">
          <div style="flex:1">申請部門： 經辦 / 課長 / 經理</div>
          <div style="flex:1; text-align:right;">經管部門： 經辦 / 課長 / 經理</div>
        </div>
        <script>window.onload=()=>{ setTimeout(()=>{ window.print(); window.close(); }, 500); }</script>
      </body></html>
    `);
    win?.document.close();
  };

  // --- 計算統計數據 ---
  const stats = useMemo(() => {
    const lowStockCount = items.filter(it => it.quantity <= it.minStock).length;
    const totalItems = items.length;
    const today = new Date().setHours(0,0,0,0);
    const todayLogs = logs.filter(l => l.timestamp >= today && l.type === 'OUT').length;

    // 部門排行
    const deptMap: any = {};
    logs.filter(l => l.type === 'OUT').forEach(l => {
        deptMap[l.dept] = (deptMap[l.dept] || 0) + l.quantity;
    });
    const ranking = Object.entries(deptMap).sort((a:any, b:any) => b[1] - a[1]);

    return { lowStockCount, totalItems, todayLogs, ranking };
  }, [items, logs]);

  return (
    <div className="min-h-screen flex bg-slate-100 text-black">
      {/* 側邊欄 */}
      <aside className="w-72 bg-slate-900 text-white p-6 flex flex-col shrink-0 border-r border-slate-800 shadow-2xl">
        <div className="flex items-center gap-3 mb-10">
          <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22}/></div>
          <h1 className="font-black text-xl tracking-tight">工安管理系統</h1>
        </div>
