        {activeTab === 'history' && (
          <div className="bg-white rounded-[2rem] shadow-xl border border-slate-200 overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase tracking-widest border-b">
                <tr><th className="px-8 py-5">異動時間</th><th className="px-8 py-5">狀態</th><th className="px-8 py-5">項目 (數量)</th><th className="px-8 py-5">部門/經手人</th><th className="px-8 py-5 text-right">補印</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {logs.map(log => (
                  <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-8 py-4 text-xs font-bold text-slate-400">{new Date(log.timestamp).toLocaleString()}</td>
