        </div>
        <div style="display:flex; justify-content:space-between; font-size:15pt; font-weight:bold; margin-bottom:10px;">
          <span>部 門：${lastTransactionBatch.dept}</span>
          <span>${date.getFullYear()-1911} 年 ${date.getMonth()+1} 月 ${date.getDate()} 日</span>
        </div>
        <table><thead><tr><th>名稱</th><th>規範</th><th>單位</th><th>數量</th><th>備註</th></tr></thead><tbody>${rows}${emptyRows}</tbody></table>
        <div class="footer">
          <div style="flex:1">申請部門： 經辦 / 課長 / 經理</div>
          <div style="flex:1; text-align:right;">經管部門： 經辦 / 課長 / 經理</div>
        </div>
        <script>window.onload=()=>{ setTimeout(()=>{ window.print(); window.close(); }, 500); }</script>
      </body></html>
    `);
    win?.document.close();
  };

  // --- 數據統計運算 ---
  const stats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    const medItems = items.filter(i => i.itemGroup === 'MEDICINE');
    const filteredLogs = logs.filter(l => {
        const logDate = new Date(l.timestamp);
        return l.type === 'OUT' && logDate.getFullYear() === statsYearFilter && (statsDeptFilter === 'ALL' || l.dept === statsDeptFilter);
    });

    let fInvQty = 0, fMedQty = 0;
    const invMap: any = {}, medMap: any = {};

    filteredLogs.forEach(log => {
        const item = items.find(it => it.id === log.itemId);
        if (item?.itemGroup === 'MEDICINE') {
            fMedQty += log.quantity;
            medMap[log.itemId] = (medMap[log.itemId] || 0) + log.quantity;
        } else {
            fInvQty += log.quantity;
            invMap[log.itemId] = (invMap[log.itemId] || 0) + log.quantity;
        }
    });

    const invDetails = Object.entries(invMap).map(([id, qty]) => ({ name: items.find(it=>it.id===id)?.name || '未知', qty: qty as number })).sort((a,b)=>b.qty-a.qty);
    const medDetails = Object.entries(medMap).map(([id, qty]) => ({ name: items.find(it=>it.id===id)?.name || '未知', qty: qty as number })).sort((a,b)=>b.qty-a.qty);

    const ranking = Object.entries(logs.filter(l => l.type === 'OUT' && new Date(l.timestamp).getFullYear() === statsYearFilter).reduce((acc: any, curr) => { 
        acc[curr.dept] = (acc[curr.dept] || 0) + curr.quantity; return acc; 
    }, {})).sort((a: any, b: any) => (b[1] as number) - (a[1] as number));

    // Calculate today's activity count
    const startOfToday = new Date().setHours(0, 0, 0, 0);
    const todayLogsCount = logs.filter(l => l.type === 'OUT' && l.timestamp >= startOfToday).length;

    return { 
        sys: { invTotal: invItems.length, medTotal: medItems.length },
        filtered: { invQty: fInvQty, medQty: fMedQty, invDetails, medDetails },
        deptRanking: ranking,
        lowStockCount: items.filter(it => it.quantity <= it.minStock).length,
        todayLogs: todayLogsCount
    };
  }, [items, logs, statsDeptFilter, statsYearFilter]);

  return (
    <div className="min-h-screen flex bg-slate-100 text-black">
      {/* 側邊欄 */}
      <aside className="w-72 bg-slate-900 text-white p-6 flex flex-col shrink-0 border-r border-slate-800 shadow-2xl">
        <div className="flex items-center gap-3 mb-10">
          <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22}/></div>
          <h1 className="font-black text-xl tracking-tight">工安管理系統</h1>
        </div>
        <nav className="flex-1 space-y-1">
          {[
            { id: 'inventory', label: '工安耗材管理', icon: Package },
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope },
            { id: 'issuance', label: '領用補貨作業', icon: FileText },
            { id: 'history', label: '歷史異動日誌', icon: History },
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard }
          ].map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}>
              <tab.icon size={20}/> {tab.label}
            </button>
          ))}
        </nav>
        <div className="mt-auto pt-6 border-t border-slate-800 space-y-2">
          <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-black text-slate-300 hover:bg-slate-800 transition-all"><Settings size={16}/> 雲端連線設定</button>
          <div className="px-4 py-3 bg-slate-800/50 rounded-xl">
             <div className="flex justify-between items-center mb-1">
               <span className="text-[10px] font-black text-slate-500 uppercase">Sync Status</span>
               <div className={`w-2 h-2 rounded-full ${syncStatus==='synced'?'bg-emerald-500':'bg-orange-500 animate-pulse'}`}></div>
             </div>
             <div className="text-[10px] text-slate-400 truncate">{lastSyncTime}</div>
          </div>
        </div>
      </aside>

      {/* 主內容區 */}
      <main className="flex-1 p-10 overflow-y-auto custom-scrollbar">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-3xl font-black text-slate-800">
            {activeTab === 'inventory' ? '工安耗材清冊' : 
             activeTab === 'medicine' ? '急救藥材清冊' : 
             activeTab === 'issuance' ? '領用 / 補貨登記' : 
             activeTab === 'history' ? '歷史異動日誌' : '數據統計看板'}
          </h2>
          {(activeTab==='inventory'||activeTab==='medicine') && (
            <button onClick={()=>setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-black shadow-xl transition-all"><Plus size={18}/> 新增項目</button>
          )}
        </header>

        {/* 頁面分流 */}
        {activeTab === 'issuance' && (
          <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
            <div className="lg:col-span-2 bg-white p-8 rounded-[2rem] shadow-xl border border-slate-200">
              <h3 className="text-xl font-black mb-8 flex items-center gap-2"><ShoppingCart className="text-blue-500"/> 1. 挑選項目</h3>
              <div className="flex bg-slate-50 p-1 rounded-xl mb-6">
                <button onClick={()=>setIssuanceMode('OUT')} className={`flex-1 py-3 rounded-lg font-bold transition-all ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button>
                <button onClick={()=>setIssuanceMode('IN')} className={`flex-1 py-3 rounded-lg font-bold transition-all ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
              </div>
              <div className="space-y-6">
                <div className="flex gap-2"><button onClick={()=>setIssuanceGroup('INVENTORY')} className={`flex-1 py-3 rounded-xl font-bold border-2 ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-100 text-slate-400'}`}>耗材類</button><button onClick={()=>setIssuanceGroup('MEDICINE')} className={`flex-1 py-3 rounded-xl font-bold border-2 ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-100 text-slate-400'}`}>藥材類</button></div>
                <select className="w-full p-4 rounded-xl font-bold border-2 border-slate-100 text-black" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                    <option value="">-- 請選擇物品 --</option>
                    {items.filter(it=>it.itemGroup===issuanceGroup).map(i => <option key={i.id} value={i.id}>{i.name} (庫存:{i.quantity})</option>)}
                </select>
                <input type="number" className="w-full p-4 rounded-xl font-bold border-2 text-black" value={inputQty} onChange={e=>setInputQty(e.target.value)}/>
                <button onClick={() => {
                  const item = items.find(it => it.id === selectedItemId);
                  if(item) setBasket([...basket, { itemId: item.id, name: item.name, quantity: Number(inputQty), unit: item.unit, spec: item.spec, itemType: item.itemType }]);
                  setSelectedItemId(''); setInputQty('1');
                }} disabled={!selectedItemId} className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black shadow-lg disabled:opacity-30">加入暫存清單</button>
              </div>
            </div>
            <div className="lg:col-span-3 bg-white p-8 rounded-[2rem] shadow-xl border border-slate-200 flex flex-col">
              <h3 className="text-xl font-black mb-6 flex items-center gap-2"><FileText className="text-emerald-500"/> 2. 資料確認</h3>
              <div className="flex-1 border-2 border-dashed border-slate-100 rounded-2xl mb-6 p-4 bg-slate-50 min-h-[250px] overflow-y-auto">
                {basket.map((b, i) => (
                  <div key={i} className="flex justify-between p-4 bg-white rounded-xl mb-2 shadow-sm font-bold border border-slate-100">
                    <span>{b.name}</span>
                    <div className="flex items-center gap-4">
                      <span className="text-blue-600">{b.quantity} {b.unit}</span>
                      <button onClick={()=>setBasket(basket.filter((_,idx)=>idx!==i))} className="text-slate-300 hover:text-red-500"><X size={16}/></button>
                    </div>
                  </div>
                ))}
              </div>
              <div className="grid grid-cols-2 gap-4 mb-8">
                <select className="p-3 rounded-xl font-bold text-black border-2" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>{DEPARTMENTS.map(d=><option key={d}>{d}</option>)}</select>
                <input type="text" placeholder="領用人" className="p-3 rounded-xl font-bold text-black border-2" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/>
                <input type="text" placeholder="用途說明" className="col-span-2 p-3 rounded-xl font-bold text-black border-2" value={inputReason} onChange={e=>setInputReason(e.target.value)}/>
              </div>
              <button onClick={processIssuance} disabled={basket.length===0} className="w-full py-6 bg-blue-600 text-white rounded-2xl font-black text-2xl shadow-2xl active:scale-95 disabled:opacity-30 transition-all">確認處理</button>
            </div>
          </div>
        )}

        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-[2rem] shadow-xl border border-slate-200 overflow-hidden">
            <div className="p-6 bg-slate-50 border-b flex justify-between items-center">
                <div className="relative w-72"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16}/><input type="text" placeholder="搜尋項目..." className="w-full pl-10 pr-4 py-2 rounded-xl text-sm font-bold text-black" value={searchTerm} onChange={e=>setSearchTerm(e.target.value)}/></div>
            </div>
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase tracking-widest border-b">
                <tr><th className="px-8 py-5">名稱及規格</th><th className="px-8 py-5 text-center">目前庫存</th><th className="px-8 py-5 text-right">操作</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(it => (activeTab==='medicine'?it.itemGroup==='MEDICINE':it.itemGroup==='INVENTORY') && it.name.includes(searchTerm)).map(it => (
                  <tr key={it.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-8 py-5"><div className="font-black text-slate-800 text-lg">{it.name}</div><div className="text-xs text-slate-400 font-bold mt-1">{it.spec || '標準規格'}</div></td>
                    <td className="px-8 py-5 text-center"><span className={`px-6 py-2 rounded-xl text-xl font-black ${it.quantity<=it.minStock?'bg-red-50 text-red-600 border border-red-100':'bg-emerald-50 text-emerald-600'}`}>{it.quantity} {it.unit}</span></td>
                    <td className="px-8 py-5 text-right"><button onClick={()=>setEditTarget(it)} className="text-slate-300 hover:text-blue-600 p-2"><Edit3 size={20}/></button><button onClick={()=>{if(confirm('確定刪除？')){setItems(items.filter(x=>x.id!==it.id));syncToCloud(items.filter(x=>x.id!==it.id), logs);}}} className="text-slate-300 hover:text-red-600 p-2"><Trash2 size={20}/></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-[2rem] shadow-xl border border-slate-200 overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase tracking-widest border-b">
                <tr><th className="px-8 py-5">異動時間</th><th className="px-8 py-5">狀態</th><th className="px-8 py-5">項目 (數量)</th><th className="px-8 py-5">部門/經手人</th><th className="px-8 py-5 text-right">補印</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {logs.map(log => (
                  <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-8 py-4 text-xs font-bold text-slate-400">{new Date(log.timestamp).toLocaleString()}</td>
                    <td className="px-8 py-4">
                      <span className={`flex items-center gap-1 font-bold ${log.type==='OUT'?'text-blue-600':'text-emerald-600'}`}>
                        {log.type==='OUT' ? <ArrowUpRight size={14}/> : <ArrowDownLeft size={14}/>}
                        {log.type==='OUT' ? '領用出庫' : '補貨入庫'}
                      </span>
                    </td>
                    <td className="px-8 py-4 font-black text-slate-800">{log.itemName} (x{log.quantity})</td>
                    <td className="px-8 py-4 text-sm font-bold">{log.dept} / {log.person}</td>
                    <td className="px-8 py-4 text-right">
                      {log.type === 'OUT' && (
                        // Added missing itemId to re-print batch
                        <button onClick={()=>{ setLastTransactionBatch({id: log.id, dept: log.dept, person: log.person, reason: log.reason, items: [{itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '個', spec: '', itemType: 'CONSUMABLE'}], timestamp: log.timestamp}); setShowPrintModal(true); }} className="text-slate-300 hover:text-blue-600 transition-colors"><Printer size={18}/></button>
                      )}
                    </td>
                  </tr>
                ))}
                {logs.length === 0 && <tr><td colSpan={5} className="p-20 text-center text-slate-300 italic font-black">尚無異動紀錄</td></tr>}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border border-slate-200">
                <p className="text-xs font-black text-slate-400 uppercase mb-2">庫存預警</p>
                <div className="flex justify-between items-end">
                    <h3 className="text-5xl font-black text-red-600">{stats.lowStockCount}</h3>
                    <AlertTriangle className="text-red-200" size={40}/>
                </div>
                <p className="text-sm font-bold text-slate-500 mt-2">項物資低於警戒庫存</p>
              </div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border border-slate-200">
                <p className="text-xs font-black text-slate-400 uppercase mb-2">系統總品項</p>
                <div className="flex justify-between items-end">
                    <h3 className="text-5xl font-black text-slate-800">{stats.sys.invTotal + stats.sys.medTotal}</h3>
                    <Package className="text-blue-100" size={40}/>
                </div>
                <p className="text-sm font-bold text-slate-500 mt-2">目前管理的物資總數</p>
              </div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border border-slate-200">
                <p className="text-xs font-black text-slate-400 uppercase mb-2">今日活動</p>
                <div className="flex justify-between items-end">
                    <h3 className="text-5xl font-black text-blue-600">{stats.todayLogs}</h3>
                    <Activity className="text-blue-100" size={40}/>
                </div>
                <p className="text-sm font-bold text-slate-500 mt-2">今日累計領用次數</p>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-slate-200">
                <h4 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><Users className="text-blue-500"/> 部門領用排行 (年度累計)</h4>
                <div className="space-y-3">
                    {stats.deptRanking.map(([dept, qty]:any, i:number) => (
                      <div key={i} className="flex items-center gap-4 bg-slate-50 p-4 rounded-2xl">
                        <div className="w-8 h-8 bg-slate-900 text-white rounded-xl flex items-center justify-center font-bold text-xs">{i+1}</div>
                        <div className="flex-1 font-bold">{dept}</div>
                        <div className="font-black">{qty} 件</div>
                      </div>
                    ))}
                    {stats.deptRanking.length === 0 && <p className="text-center py-10 text-slate-300 font-bold">尚無統計數據</p>}
                </div>
              </div>
              <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="relative z-10">
                  <h4 className="text-2xl font-black mb-4 flex items-center gap-2"><BrainCircuit className="text-blue-400"/> AI 庫存優化報告</h4>
                  <button onClick={async()=>{setIsAiLoading(true);setAiInsights(await getInventoryInsights(items));setIsAiLoading(false);}} className="w-full py-4 bg-blue-600 rounded-2xl font-black mb-6 shadow-xl hover:scale-105 transition-all">{isAiLoading?'分析中...':'生成分析建議'}</button>
                  <div className="text-slate-400 font-bold leading-relaxed whitespace-pre-wrap">{aiInsights || '讓 AI 為您的庫存數據提供採購決策建議。'}</div>
                </div>
                <Package className="absolute -right-20 -bottom-20 opacity-10 text-white" size={300}/>
              </div>
            </div>
          </div>
        )}

        {/* --- 各種彈窗 --- */}
        {(showAddModal || editTarget) && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[500] flex items-center justify-center p-4">
             <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl">
                <form className="space-y-6" onSubmit={handleSaveItem}>
                   <div className="flex justify-between items-center"><h3 className="text-2xl font-black text-black">{editTarget?'編輯項目資料':'新增管理項目'}</h3><button type="button" onClick={()=>{setShowAddModal(false);setEditTarget(null);}}><X/></button></div>
                   <div><label className="text-xs font-black text-slate-500 uppercase">物資名稱</label><input name="name" placeholder="例如：防護背心" required className="w-full p-4 rounded-xl font-bold mt-1" defaultValue={editTarget?.name}/></div>
                   <div className="grid grid-cols-2 gap-4">
                      <div><label className="text-xs font-black text-slate-500 uppercase">分類</label><select name="itemType" className="w-full p-4 rounded-xl font-bold mt-1" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="CONSUMABLE">消耗品</option><option value="EQUIPMENT">設備類</option></select></div>
                      <div><label className="text-xs font-black text-slate-500 uppercase">規格</label><input name="spec" placeholder="規格/序號" className="w-full p-4 rounded-xl font-bold mt-1" defaultValue={editTarget?.spec}/></div>
                   </div>
                   <div className="grid grid-cols-3 gap-4">
                      <div><label className="text-xs font-black text-slate-500 uppercase">單位</label><input name="unit" placeholder="個" className="w-full p-4 rounded-xl font-bold mt-1" defaultValue={editTarget?.unit || '個'}/></div>
                      <div><label className="text-xs font-black text-slate-500 uppercase">庫存</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl font-bold mt-1" defaultValue={editTarget?.quantity || 0}/></div>
                      <div><label className="text-xs font-black text-slate-500 uppercase">警戒</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl font-bold mt-1" defaultValue={editTarget?.minStock || 5}/></div>
                   </div>
                   <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl transition-all hover:bg-blue-700">儲存物資</button>
                </form>
             </div>
          </div>
        )}

        {showSettings && (
          <div className="fixed inset-0 bg-slate-900/80 flex items-center justify-center p-4 z-[600]">
             <div className="bg-white rounded-[2rem] w-full max-w-lg p-10 shadow-2xl">
                <h3 className="text-2xl font-black mb-6 text-black">⚙️ 雲端同步設定</h3>
                <input type="text" id="gasUrlInput" className="w-full p-4 rounded-xl border-2 font-bold mb-8 text-black" defaultValue={gasUrl} placeholder="貼上 Google GAS Web App URL..."/>
                <div className="flex gap-4">
                  <button onClick={()=>{const u=(document.getElementById('gasUrlInput') as HTMLInputElement).value;handleGasUrlSave(u);}} className="flex-1 py-4 bg-slate-900 text-white rounded-2xl font-black">儲存並同步</button>
                  <button onClick={()=>setShowSettings(false)} className="px-8 py-4 bg-slate-100 rounded-2xl font-bold">返回</button>
                </div>
             </div>
          </div>
        )}

        {showPrintModal && lastTransactionBatch && (
          <div className="fixed inset-0 bg-slate-900/95 z-[700] flex flex-col items-center justify-center p-6">
             <div className="bg-white rounded-[3rem] w-full max-w-5xl h-[90vh] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in duration-300">
                <div className="p-8 flex justify-between items-center border-b bg-white relative z-10 shadow-sm">
                   <div className="flex items-center gap-4"><CheckCircle2 className="text-emerald-500" size={32}/><h3 className="font-black text-2xl text-black">領用單據生成預覽</h3></div>
                   <div className="flex gap-4">
                      <button onClick={handleFinalPrint} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xl shadow-xl flex items-center gap-2 transition-all hover:scale-105"><Printer size={24}/> 立即列印</button>
                      <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-2xl text-slate-400 hover:text-black transition-all"><X size={32}/></button>
                   </div>
                </div>
                <div className="flex-1 bg-slate-200 p-10 overflow-y-auto flex justify-center shadow-inner">
                   <div className="bg-white shadow-2xl p-12 border rounded-sm origin-top mb-10 scale-90">
                      <div id="print-area" className="w-[210mm] text-black" style={{fontFamily:'StandardKai, serif'}}>
