        )}

        {showPrintModal && lastTransactionBatch && (
          <div className="fixed inset-0 bg-slate-900/95 z-[500] flex flex-col items-center justify-center p-6"><div className="bg-white rounded-[3rem] w-full max-w-5xl h-[90vh] shadow-2xl flex flex-col overflow-hidden animate-in fade-in zoom-in duration-300"><div className="p-8 flex justify-between items-center border-b bg-white relative z-10 shadow-sm"><div className="flex items-center gap-4"><CheckCircle2 className="text-emerald-500" size={40}/><h3 className="font-black text-2xl text-black">領用單據生成預覽</h3></div><div className="flex gap-4"><button onClick={() => handleFinalPrint(false)} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xl shadow-xl hover:scale-105 transition-all flex items-center gap-2"><Printer size={24}/> 直接列印</button><button onClick={() => handleFinalPrint(true)} className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black text-xl shadow-xl hover:scale-105 transition-all flex items-center gap-2"><FileDown size={24}/> 另存為 PDF</button><button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-2xl text-black hover:bg-slate-200"><X size={32}/></button></div></div><div className="flex-1 bg-slate-100 p-10 overflow-y-auto flex justify-center shadow-inner"><div className="bg-white shadow-2xl p-6 border rounded-sm origin-top mb-10 scale-90"><div style={{width:'210mm', minHeight:'297mm', padding:'40px', color:'black', background:'white'}} className="text-black"><div style={{display:'flex', flexDirection:'column', alignItems:'flex-end'}}><div style={{fontSize:'9pt', color:'#666'}}>單號：{lastTransactionBatch.id}</div></div><h1 style={{textAlign:'center', fontSize:'24pt', fontWeight:'bold', marginBottom:'25px', color: 'black'}} className="text-black">台灣電力公司電力修護處南部分處</h1><div style={{display:'flex', justifyContent:'center', gap:'40px', fontSize:'15pt', marginBottom:'25px', fontWeight:'bold', color: 'black'}} className="text-black"><div><span style={{border:'2.5px solid black', width:'20px', height:'20px', display:'inline-flex', alignItems:'center', justifyContent:'center', marginRight:'8px', verticalAlign:'middle', color: 'black'}}>{lastTransactionBatch.items.some(it => it.itemType === 'EQUIPMENT') ? 'V' : ''}</span> 設備借用單</div><div><span style={{border:'2.5px solid black', width:'20px', height:'20px', display:'inline-flex', alignItems:'center', justifyContent:'center', marginRight:'8px', verticalAlign:'middle', color: 'black'}}>{lastTransactionBatch.items.every(it => it.itemType === 'CONSUMABLE') ? 'V' : ''}</span> 消耗品領用單</div></div><div style={{display:'flex', justifyContent:'space-between', marginBottom:'15px', fontWeight:'bold', fontSize:'14pt', color: 'black'}} className="text-black"><div>部 門：<span style={{borderBottom:'1.5px dotted black', minWidth:'350px', display:'inline-block', textAlign:'center', color: 'black'}}>{lastTransactionBatch.dept}</span></div><div>{new Date(lastTransactionBatch.timestamp).getFullYear() - 1911} 年 {new Date(lastTransactionBatch.timestamp).getMonth() + 1} 月 {new Date(lastTransactionBatch.timestamp).getDate()} 日</div></div><table style={{width:'100%', borderCollapse:'collapse', border:'2px solid black', color: 'black'}} className="text-black"><thead><tr style={{background:'#f2f2f2'}}><th style={{padding:'8px', border:'1.5px solid black', color: 'black'}}>名稱</th><th style={{padding:'8px', border:'1.5px solid black', color: 'black'}}>規範</th><th style={{padding:'8px', border:'1.5px solid black', color: 'black'}}>單位</th><th style={{padding:'8px', border:'1.5px solid black', color: 'black'}}>數量</th><th style={{padding:'8px', border:'1.5px solid black', color: 'black'}}>備註</th></tr></thead><tbody>{lastTransactionBatch.items.map((it, i) => (<tr key={i}><td style={{textAlign:'center', padding:'12px', border:'1.5px solid black', color: 'black'}}>{it.name}</td><td style={{border:'1.5px solid black', textAlign:'center', color: 'black'}}>{it.spec}</td><td style={{border:'1.5px solid black', textAlign:'center', color: 'black'}}>{it.unit}</td><td style={{fontWeight:'bold', fontSize:'16pt', border:'1.5px solid black', textAlign:'center', color: 'black'}}>{it.quantity}</td><td style={{border:'1.5px solid black', textAlign:'center', color: 'black'}}>{lastTransactionBatch.reason}</td></tr>))}{Array(Math.max(0, 15 - lastTransactionBatch.items.length)).fill(0).map((_, i) => (<tr key={i + 100}><td style={{height:'35px', border:'1.5px solid black'}}>&nbsp;</td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td></tr>))}</tbody></table><div style={{marginTop:'35px', fontWeight:'bold', fontSize:'13pt', color: 'black'}} className="text-black"><div style={{display:'flex', justifyContent:'space-between'}}><div style={{flex:1}}>申請部門：</div><div style={{flex:1}}>經管部門：</div></div><div style={{display:'flex', justifyContent:'space-between', marginTop:'45px', fontSize:'12pt', color: 'black'}} className="text-black"><div style={{flex:1, display:'flex', justifyContent:'space-around', padding:'0 20px'}}><span>經辦：</span><span>課長：</span><span>經理：</span></div><div style={{flex:1, display:'flex', justifyContent:'space-around', padding:'0 20px'}}><span>經辦：</span><span>課長：</span><span>經理：</span></div></div></div></div></div></div></div></div>
        )}

        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-4"><div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl animate-in zoom-in duration-300"><form className="space-y-6" onSubmit={handleSaveItem}><h3 className="text-2xl font-black text-black mb-4">{editTarget ? '編輯項目' : '新增項目'}</h3><div><label className="text-xs font-black text-slate-500 uppercase">物資名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.name} /></div><div className="grid grid-cols-2 gap-6"><div><label className="text-xs font-black text-slate-500">分類</label><select name="itemType" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="EQUIPMENT">安全衛生設備</option><option value="CONSUMABLE">安全衛生類消耗品</option></select></div><div><label className="text-xs font-black text-slate-500">規範 (序號)</label><input name="spec" type="text" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.spec || ''} /></div></div><div className="grid grid-cols-3 gap-6"><div><label className="text-xs font-black text-slate-500">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.unit || '個'} /></div><div><label className="text-xs font-black text-slate-500">目前庫存</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.quantity || 0} /></div><div><label className="text-xs font-black text-slate-500">警戒數量</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.minStock || 5} /></div></div>{(activeTab === 'medicine' || editTarget?.itemGroup === 'MEDICINE') && (<div className="grid grid-cols-2 gap-6"><div><label className="text-xs font-black text-slate-500">購入日期</label><input name="purchaseDate" type="date" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.purchaseDate} /></div><div><label className="text-xs font-black text-slate-500">有效日期</label><input name="expiryDate" type="date" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.expiryDate} /></div></div>)}<button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-2xl shadow-xl mt-6">儲存物資</button><button type="button" onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="w-full py-3 text-slate-400 font-bold hover:text-black">取消返回</button></form></div></div>
        )}

        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/90 flex items-center justify-center p-4 z-[400] animate-in fade-in"><div className="bg-white p-10 rounded-3xl text-center max-w-sm shadow-2xl"><h3 className="text-2xl font-black mb-4 text-black">確定刪除「{deleteTarget.name}」？</h3><button onClick={()=>{ setItems(items.filter(i => i.id !== deleteTarget.id)); syncToCloud(items.filter(i => i.id !== deleteTarget.id), logs); setDeleteTarget(null); }} className="w-full py-4 bg-red-600 text-white rounded-xl font-black mb-2 shadow-lg">確認刪除</button><button onClick={()=>setDeleteTarget(null)} className="w-full py-4 text-slate-400 font-bold hover:text-black">取消</button></div></div>
        )}
      </main>
    </div>
  );
};

export default App;

