import { GoogleGenAI } from "@google/genai";
import { InventoryItem } from "../types";

export const getInventoryInsights = async (items: InventoryItem[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const lowStock = items.filter(i => i.quantity <= i.minStock);

  // 偵測過期或快到期的藥材 (30天內)
  const today = new Date();
  const nearExpiry = items.filter(i => {
    if (!i.expiryDate) return false;
    const exp = new Date(i.expiryDate);
    const diffTime = exp.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays <= 30;
  });

  const prompt = `
    這是一個工安耗材管理系統。
    當前庫存清單: ${JSON.stringify(items.map(i => ({ name: i.name, qty: i.quantity, min: i.minStock, exp: i.expiryDate })))}
    庫存不足項目: ${JSON.stringify(lowStock.map(i => i.name))}
    即將到期或已過期項目 (30天內): ${JSON.stringify(nearExpiry.map(i => ({ name: i.name, exp: i.expiryDate })))}

    請以專業工安與衛生管理員的身份，提供 3 點具體的採購、報廢或管理建議。
    請特別留意過期藥材的處置建議。請用繁體中文回答，語氣要簡潔專業。
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "無法獲取建議";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "AI 助理暫時無法提供建議，請檢查您的庫存與藥材到期日。";
  }
};

