  };

  const handleSaveItem = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (isProcessing) return;
    setIsProcessing(true);

    const cloudData = await fetchFromCloud();
    const latestItems = cloudData ? cloudData.items : [...items];

    const formData = new FormData(e.currentTarget);
    const data = { 
      name: formData.get('name') as string, 
      itemType: formData.get('itemType') as ItemType, 
      unit: formData.get('unit') as string, 
      spec: formData.get('spec') as string, 
      quantity: Number(formData.get('quantity')), 
      minStock: Number(formData.get('minStock')),
      purchaseDate: formData.get('purchaseDate') as string,
      expiryDate: formData.get('expiryDate') as string,
    };

    let updated;
    if (editTarget) {
      updated = latestItems.map(i => i.id === editTarget.id ? { ...editTarget, ...data, lastUpdated: Date.now() } : i);
      setItems(updated); setEditTarget(null);
    } else {
      updated = [...latestItems, { id: generateId(), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: Date.now() }];
      setItems(updated); setShowAddModal(false);
    }

    await syncToCloud(updated, logs);
    setIsProcessing(false);
  };

  const stats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    const filteredLogs = logs.filter(l => l.type === 'OUT' && new Date(l.timestamp).getFullYear() === statsYearFilter && (statsDeptFilter === 'ALL' || l.dept === statsDeptFilter));
    const invDetailMap: Record<string, {name: string, qty: number}> = {};
    const medDetailMap: Record<string, {name: string, qty: number}> = {};
    let fInvQty = 0, fMedQty = 0;
    filteredLogs.forEach(log => {
        const item = items.find(it => it.id === log.itemId);
        if (item?.itemGroup === 'MEDICINE') { fMedQty += log.quantity; if (!medDetailMap[log.itemId]) medDetailMap[log.itemId] = { name: log.itemName, qty: 0 }; medDetailMap[log.itemId].qty += log.quantity; }
        else { fInvQty += log.quantity; if (!invDetailMap[log.itemId]) invDetailMap[log.itemId] = { name: log.itemName, qty: 0 }; invDetailMap[log.itemId].qty += log.quantity; }
    });
    const invDetails = Object.values(invDetailMap).sort((a, b) => b.qty - a.qty);
    return { 
      sys: { invTotal: invItems.length }, 
      filtered: { 
        invQty: fInvQty, 
        medQty: fMedQty, 
        invDetails, 
        medDetails: Object.values(medDetailMap), 
        chartData: invDetails.slice(0, 8).map(d => ({ name: d.name, value: d.qty })) 
      }, 
      deptRanking: Object.entries(logs.filter(l => l.type === 'OUT' && new Date(l.timestamp).getFullYear() === statsYearFilter).reduce((acc: any, curr) => { acc[curr.dept] = (acc[curr.dept] || 0) + curr.quantity; return acc; }, {})).sort((a: any, b: any) => b[1] - a[1]) 
    };
  }, [items, logs, statsDeptFilter, statsYearFilter]);

  const checkExpired = (dateStr: string | undefined) => {
    if (!dateStr) return false;
    return new Date(dateStr) < new Date();
  };

  return (
    <div className="min-h-screen flex bg-slate-100 text-slate-900 font-sans">
      <style>{`
        input, select, textarea { 
          color: #000000 !important; 
          background-color: #ffffff !important; 
          border: 2px solid #94a3b8 !important; 
          font-weight: 700 !important; 
        }
        ::placeholder { color: #64748b !important; }
        .pulse-orange { animation: pulse-orange 2s infinite; }
        @keyframes pulse-orange { 0% { box-shadow: 0 0 0 0 rgba(251, 146, 60, 0.7); } 70% { box-shadow: 0 0 0 10px rgba(251, 146, 60, 0); } 100% { box-shadow: 0 0 0 0 rgba(251, 146, 60, 0); } }
      `}</style>

      {/* 處理中遮罩 */}
      {isProcessing && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-[2px] z-[999] flex flex-col items-center justify-center">
          <div className="bg-white p-8 rounded-3xl shadow-2xl flex flex-col items-center gap-4 border-4 border-blue-500">
            <RefreshCw className="text-blue-600 animate-spin" size={48} />
            <div className="text-2xl font-black text-slate-900">同步與校對中...</div>
          </div>
        </div>
      )}

      {/* 側邊欄 */}
      <aside className="w-72 bg-slate-900 text-white p-6 flex flex-col shrink-0 border-r border-slate-800 shadow-2xl">
        <div className="flex flex-col gap-1 mb-8">
          <div className="flex items-center gap-3"><div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center"><Package size={22} className="text-white"/></div><h1 className="font-black text-xl text-white">工安管理系統</h1></div>
          <div className="mt-6 bg-slate-800/50 rounded-2xl p-4 border border-slate-700/50">
            <div className="flex items-center justify-between mb-2"><span className="text-[10px] font-black text-slate-500 uppercase">同步狀態</span><div className={`w-3 h-3 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500' : 'bg-orange-400 animate-pulse'}`}></div></div>
            <div className="text-sm font-black text-white">{syncStatus === 'synced' ? '已連接雲端' : '對齊數據中...'}</div>
            <div className="flex items-center gap-1.5 text-[10px] text-slate-400 mt-1"><Clock size={10}/> 更新: {lastSyncTime}</div>
          </div>
        </div>
        <nav className="flex-1 space-y-1">
          {[ { id: 'inventory', label: '工安耗材管理', icon: Package }, { id: 'medicine', label: '急救藥材管理', icon: Stethoscope }, { id: 'issuance', label: '領用補貨作業', icon: FileText }, { id: 'history', label: '歷史異動日誌', icon: History }, { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard }, ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}><tab.icon size={20} /> {tab.label}</button>
          ))}
        </nav>
        <div className="pt-6 mt-6 border-t border-slate-800 space-y-2">
            <button onClick={() => setShowSettings(true)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-black transition-all ${!gasUrl ? 'bg-orange-500/20 text-orange-400 pulse-orange' : 'text-slate-300 hover:bg-slate-800'}`}><Settings size={16}/> 雲端連線設定</button>
            <button onClick={() => fetchFromCloud()} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800"><RefreshCw size={16}/> 立即校對雲端</button>
        </div>
      </aside>

      {/* 主內容區 */}
      <main className="flex-1 p-10 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <div>
            <h2 className="text-3xl font-black text-slate-900">{activeTab === 'inventory' ? '工安耗材清冊' : activeTab === 'medicine' ? '急救藥材清冊' : activeTab === 'issuance' ? '領用 / 補貨登記' : activeTab === 'history' ? '歷史異動日誌' : '數據統計看板'}</h2>
            {!gasUrl && (
              <div onClick={() => setShowSettings(true)} className="mt-6 bg-orange-50 border-4 border-orange-200 p-6 rounded-3xl flex items-center gap-4 text-orange-700 cursor-pointer animate-bounce"><AlertTriangle size={32}/><div className="font-black text-xl">⚠️ 系統未連線，請點此設定 GAS 網址載入資料。</div></div>
            )}
          </div>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-black shadow-xl"><Plus size={18}/> 新增項目</button>
          )}
        </header>

        {activeTab === 'issuance' && (
          <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
            <div className="lg:col-span-2 bg-white p-8 rounded-3xl shadow-xl border border-slate-200">
              <h3 className="text-xl font-black mb-8 flex items-center gap-2 text-slate-900"><ShoppingCart className="text-blue-500"/> 1. 挑選項目</h3>
              <div className="flex bg-slate-100 p-1 rounded-xl mb-6">
                <button onClick={()=>{setIssuanceMode('OUT'); setBasket([]);}} className={`flex-1 py-3 rounded-lg font-black transition-all ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button>
                <button onClick={()=>{setIssuanceMode('IN'); setBasket([]);}} className={`flex-1 py-3 rounded-lg font-black transition-all ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
              </div>
              <div className="space-y-6">
                <div><label className="text-xs font-black text-slate-500 uppercase">品項類型</label><div className="flex gap-2 mt-2"><button onClick={()=>setIssuanceGroup('INVENTORY')} className={`flex-1 py-3 rounded-xl font-black border-2 ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-200 text-slate-400'}`}>耗材</button><button onClick={()=>setIssuanceGroup('MEDICINE')} className={`flex-1 py-3 rounded-xl font-black border-2 ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-200 text-slate-400'}`}>藥材</button></div></div>
                <div><label className="text-xs font-black text-slate-500 uppercase">選擇品項</label><select className="w-full p-4 rounded-xl mt-2 text-lg text-black font-bold" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}><option value="">-- 請選擇 --</option>{items.filter(i => i.itemGroup === issuanceGroup).map(i => (<option key={i.id} value={i.id}>{i.name} ({issuanceMode === 'OUT' ? `剩餘:${i.quantity - getReservedQty(i.id)}` : `目前:${i.quantity}`})</option>))}</select></div>
                <div><label className="text-xs font-black text-slate-500 uppercase">數量</label><input type="number" min="1" className="w-full p-4 rounded-xl mt-2 text-xl font-bold" value={inputQty} onChange={e=>setInputQty(e.target.value)}/>{isQtyOver && <p className="text-red-600 text-xs font-black mt-2">⚠️ 超出庫存</p>}</div>
                <button onClick={addToBasket} disabled={!selectedItemId || isQtyOver} className={`w-full py-5 rounded-2xl font-black text-xl flex items-center justify-center gap-2 shadow-lg ${!selectedItemId || isQtyOver ? 'bg-slate-200 text-slate-400' : 'bg-slate-900 text-white hover:bg-black'}`}><Plus size={20}/> 加入清單</button>
              </div>
            </div>
            <div className="lg:col-span-3 bg-white p-8 rounded-3xl shadow-xl border border-slate-200 flex flex-col">
              <h3 className="text-xl font-black mb-6 flex items-center gap-2 text-slate-900"><FileText className="text-emerald-500"/> 2. 待處理清單</h3>
              <div className="flex-1 overflow-y-auto border-2 border-dashed border-slate-100 rounded-2xl mb-6 min-h-[250px] bg-slate-50">{basket.length > 0 ? (<table className="w-full text-left"><tbody className="divide-y divide-slate-100">{basket.map((b, idx) => (<tr key={idx} className="bg-white"><td className="px-6 py-5 font-black text-slate-900">{b.name}</td><td className="px-6 py-5 text-center font-black text-blue-700">{b.quantity} {b.unit}</td><td className="px-6 py-5 text-right"><button onClick={()=>setBasket(prev => prev.filter((_, i) => i !== idx))} className="text-slate-300 hover:text-red-600"><X size={20}/></button></td></tr>))}</tbody></table>) : (<div className="h-full flex items-center justify-center text-slate-300 font-bold opacity-30">目前清單為空</div>)}</div>
              {issuanceMode === 'OUT' && (
                <div className="grid grid-cols-2 gap-6 mb-6"><div><label className="text-xs font-black text-slate-500 uppercase">部門</label><select className="w-full p-3 rounded-xl mt-2 text-black font-bold" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>{DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}</select></div><div><label className="text-xs font-black text-slate-500 uppercase">領用人</label><input type="text" className="w-full p-3 rounded-xl mt-2 text-black font-bold" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div></div>
              )}
              <button onClick={processIssuance} disabled={basket.length === 0 || isProcessing} className={`w-full py-6 rounded-2xl font-black text-3xl shadow-2xl transition-all text-white ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>{isProcessing ? '數據校對中...' : (issuanceMode === 'OUT' ? '確認領用 (生成單據)' : '確認入庫')}</button>
            </div>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              <div className="bg-slate-900 p-8 rounded-[2rem] text-white shadow-xl"><p className="text-blue-400 text-xs font-black uppercase">年度領用量</p><h3 className="text-5xl font-black mt-2">{stats.filtered.invQty + stats.filtered.medQty}</h3></div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-blue-500"><p className="text-slate-400 text-xs font-black uppercase">工安消耗品</p><h3 className="text-4xl font-black mt-2 text-blue-600">{stats.filtered.invQty}</h3></div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-emerald-500"><p className="text-slate-400 text-xs font-black uppercase">急救藥材</p><h3 className="text-4xl font-black mt-2 text-emerald-600">{stats.filtered.medQty}</h3></div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-orange-500"><p className="text-slate-400 text-xs font-black uppercase">低庫存警戒</p><h3 className="text-4xl font-black mt-2 text-orange-600">{items.filter(i => i.quantity <= i.minStock).length}</h3></div>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 bg-white p-8 rounded-[2.5rem] shadow-lg flex flex-col min-h-[450px]">
                <h4 className="text-xl font-black mb-6 flex items-center gap-2 text-slate-900"><BarChart3 className="text-blue-500"/> 熱門領用品項分析</h4>
                <div className="flex-1 w-full h-full">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={stats.filtered.chartData} margin={{ top: 20, right: 30, left: 0, bottom: 0 }}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 12, fontWeight: 700, fill: '#334155' }} />
                      <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 12, fontWeight: 700, fill: '#334155' }} />
                      <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', fontWeight: 800, color: '#000' }} />
                      <Bar dataKey="value" radius={[8, 8, 0, 0]} barSize={40}>{stats.filtered.chartData.map((entry, index) => (<Cell key={`cell-${index}`} fill={CHART_COLORS[index % CHART_COLORS.length]} />))}</Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
              <div className="bg-white p-8 rounded-[2.5rem] shadow-lg flex flex-col">
                <h4 className="text-xl font-black mb-6 flex items-center gap-2 text-slate-900"><Users className="text-slate-600"/> 部門領用排行</h4>
                <div className="space-y-4 flex-1 overflow-y-auto pr-2">{stats.deptRanking.map(([dept, count]: any, idx) => (<div key={dept} className="flex items-center gap-4 bg-slate-50 p-4 rounded-2xl"><div className="w-8 h-8 flex items-center justify-center rounded-xl bg-slate-900 text-white text-xs font-black">{idx + 1}</div><div className="flex-1 font-bold text-slate-900">{dept}</div><div className="font-black text-blue-600">{count} 件</div></div>))}</div>
              </div>
            </div>
          </div>
        )}

        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-200">
            <div className="p-6 bg-slate-50 border-b flex items-center justify-between"><div className="relative max-w-sm w-full"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="搜尋名稱..." className="w-full pl-12 pr-4 py-3 rounded-xl font-black text-black" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} /></div></div>
            <table className="w-full text-left">
              <thead className="bg-slate-100 text-[11px] font-black text-slate-500 border-b">
                <tr><th className="px-8 py-5">名稱及規格</th>{activeTab === 'medicine' && <><th className="px-6 py-5">購置日期</th><th className="px-6 py-5">到期日</th></>}<th className="px-8 py-5 text-center">庫存</th><th className="px-8 py-5 text-right">操作</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(i => (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50">
                    <td className="px-8 py-5"><div className="font-black text-slate-900 text-lg">{item.name}</div><div className="text-xs text-slate-500 font-bold">{item.spec || '無規格'} | {item.itemType === 'EQUIPMENT' ? '設備' : '消耗品'}</div></td>
                    {activeTab === 'medicine' && (
                      <>
                        <td className="px-6 py-5 text-sm font-bold text-slate-600">{item.purchaseDate || '--'}</td>
                        <td className="px-6 py-5"><div className={`flex items-center gap-2 font-black ${checkExpired(item.expiryDate) ? 'text-red-600' : 'text-slate-900'}`}><Calendar size={16}/> {item.expiryDate || '未填寫'}{checkExpired(item.expiryDate) && <AlertTriangle size={16} className="text-red-600 animate-pulse"/>}</div></td>
                      </>
                    )}
                    <td className="px-8 py-5 text-center"><span className={`px-6 py-2 rounded-xl font-black text-xl ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600 border border-red-200' : 'bg-emerald-50 text-emerald-600'}`}>{item.quantity} {item.unit}</span></td>
                    <td className="px-8 py-5 text-right"><button onClick={() => setEditTarget(item)} className="p-2 text-slate-400 hover:text-blue-600"><Edit3 size={20}/></button><button onClick={() => setDeleteTarget({id: item.id, name: item.name})} className="p-2 text-slate-400 hover:text-red-600"><Trash2 size={20}/></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-200">
            <table className="w-full text-left">
              <thead className="bg-slate-100 text-[11px] font-black text-slate-500 border-b">
                <tr><th className="px-6 py-5">時間</th><th className="px-6 py-5">動作</th><th className="px-6 py-5">項目</th><th className="px-6 py-5">部門/人員</th><th className="px-6 py-5 text-right">補印</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {logs.length > 0 ? logs.map(log => (
                  <tr key={log.id} className="hover:bg-slate-50">
                    <td className="px-6 py-5 text-xs font-bold text-slate-500">{new Date(log.timestamp).toLocaleString()}</td>
                    <td className="px-6 py-5 font-black">{log.type === 'OUT' ? <span className="text-blue-600">領用出庫</span> : <span className="text-emerald-600">補貨入庫</span>}</td>
                    <td className="px-6 py-5 font-black text-slate-900">{log.itemName} (x{log.quantity})</td>
                    <td className="px-6 py-5 font-bold text-slate-700">{log.dept} / {log.person}</td>
                    <td className="px-6 py-5 text-right">{log.type === 'OUT' ? <button onClick={()=>{ setLastTransactionBatch({id: log.id, dept: log.dept, person: log.person, reason: log.reason, items: [{itemId: log.itemId, name: log.itemName, quantity: log.quantity, unit: '個', spec: '', itemType: 'CONSUMABLE'}], timestamp: log.timestamp}); setShowPrintModal(true); }} className="text-slate-400 hover:text-blue-600"><Printer size={20}/></button> : '--'}</td>
                  </tr>
                )) : (
                  <tr><td colSpan={5} className="p-20 text-center text-slate-300 font-black text-xl opacity-50">目前尚無異動紀錄</td></tr>
                )}
              </tbody>
            </table>
          </div>
        )}

        {/* 設定與模態框 */}
        {showSettings && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[600] flex items-center justify-center p-4 animate-in fade-in">
            <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl">
              <h3 className="text-2xl font-black text-slate-900 mb-8">雲端連線設定</h3>
              <div className="space-y-6">
                <div><label className="text-xs font-black text-slate-500">GAS Web App URL</label><input type="text" className="w-full p-4 rounded-xl mt-2 text-black font-bold" defaultValue={gasUrl} id="gas-url-input" placeholder="請貼上 Google Apps Script 網址"/></div>
                <div className="flex gap-4"><button onClick={() => handleGasUrlSave((document.getElementById('gas-url-input') as HTMLInputElement).value)} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl">儲存並同步</button><button onClick={() => setShowSettings(false)} className="px-8 py-5 bg-slate-100 text-slate-600 rounded-2xl font-black text-xl">取消</button></div>
              </div>
            </div>
          </div>
        )}

        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl animate-in zoom-in">
              <form className="space-y-6" onSubmit={handleSaveItem}>
                <h3 className="text-2xl font-black text-slate-900">{editTarget ? '編輯項目' : '新增項目'}</h3>
                <div><label className="text-xs font-black text-slate-500 uppercase">物資名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl mt-2 font-black text-black" defaultValue={editTarget?.name} /></div>
                <div className="grid grid-cols-2 gap-6">
                  <div><label className="text-xs font-black text-slate-500">分類</label><select name="itemType" className="w-full p-4 rounded-xl mt-2 font-black text-black" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="EQUIPMENT">安全衛生設備</option><option value="CONSUMABLE">安全衛生類消耗品</option></select></div>
                  <div><label className="text-xs font-black text-slate-500">規範 (序號)</label><input name="spec" type="text" className="w-full p-4 rounded-xl mt-2 font-black text-black" defaultValue={editTarget?.spec || ''} /></div>
                </div>
                <div className="grid grid-cols-2 gap-6">
                  <div><label className="text-xs font-black text-slate-500">購置日期</label><input name="purchaseDate" type="date" className="w-full p-4 rounded-xl mt-2 font-black text-black" defaultValue={editTarget?.purchaseDate} /></div>
                  <div><label className="text-xs font-black text-slate-500">到期日 (藥材必填)</label><input name="expiryDate" type="date" className="w-full p-4 rounded-xl mt-2 font-black text-black" defaultValue={editTarget?.expiryDate} /></div>
                </div>
                <div className="grid grid-cols-3 gap-6">
                  <div><label className="text-xs font-black text-slate-500">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl mt-2 font-black text-black" defaultValue={editTarget?.unit || '個'} /></div>
                  <div><label className="text-xs font-black text-slate-500">庫存</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl mt-2 font-black text-black" defaultValue={editTarget?.quantity || 0} /></div>
                  <div><label className="text-xs font-black text-slate-500">警戒值</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl mt-2 font-black text-black" defaultValue={editTarget?.minStock || 5} /></div>
                </div>
                <button type="submit" disabled={isProcessing} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-2xl shadow-xl mt-6">{isProcessing ? '數據同步中...' : '儲存物資'}</button>
                <button type="button" onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="w-full py-3 text-slate-400 font-bold hover:text-slate-900">取消</button>
              </form>
            </div>
          </div>
        )}

        {showPrintModal && lastTransactionBatch && (
