                    <div style={{marginTop:'45px', fontWeight:'bold', fontSize:'14pt'}}>
                      <div style={{display:'flex', justifyContent:'space-between'}}><div style={{flex:1}}>申請部門：</div><div style={{flex:1}}>經管部門：</div></div>
                      <div style={{display:'flex', justifyContent:'space-between', marginTop:'60px', fontSize:'13pt'}}>
