                <button type="submit" disabled={isProcessing} className="w-full py-7 bg-blue-600 text-white rounded-[2rem] font-black text-3xl shadow-xl mt-6 active:scale-95 transition-all">儲存物資</button>
                <button type="button" onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="w-full py-4 text-slate-400 font-bold">返回清單</button>
              </form>
