        {/* 單據列印預覽 - 強制文字純黑 */}
        {showPrintModal && lastTransactionBatch && (
          <div className="fixed inset-0 bg-slate-900/95 z-[500] flex flex-col items-center justify-center p-6 animate-in fade-in">
            <div className="bg-white rounded-[4rem] w-full max-w-6xl h-[92vh] shadow-2xl flex flex-col overflow-hidden">
