                  <button onClick={()=>setShowPrintModal(false)} className="p-5 bg-slate-100 rounded-full text-slate-400 hover:text-red-600"><X size={36}/></button>
                </div>
              </div>
              <div className="flex-1 bg-slate-100 p-12 overflow-y-auto flex justify-center custom-scrollbar">
                <div className="bg-white shadow-2xl p-10 border border-slate-200 mb-10 preview-content">
                  <div style={{width:'210mm', minHeight:'297mm', padding:'40px', background:'white'}}>
                    <h1 style={{textAlign:'center', fontSize:'28pt', fontWeight:'bold', marginBottom:'30px', color: '#000'}}>台灣電力公司電力修護處南部分處</h1>
                    <div style={{display:'flex', justifyContent:'center', gap:'50px', fontSize:'17pt', marginBottom:'30px', fontWeight:'bold', color: '#000'}}>
                      <div><span style={{border:'2.5px solid black', width:'24px', height:'24px', display:'inline-flex', alignItems:'center', justifyCenter:'center', marginRight:'10px', verticalAlign:'middle'}}>{lastTransactionBatch.items.some(it => it.itemType === 'EQUIPMENT') ? 'V' : ''}</span> 設備借用單</div>
                      <div><span style={{border:'2.5px solid black', width:'24px', height:'24px', display:'inline-flex', alignItems:'center', justifyCenter:'center', marginRight:'10px', verticalAlign:'middle'}}>{lastTransactionBatch.items.every(it => it.itemType === 'CONSUMABLE') ? 'V' : ''}</span> 消耗品領用單</div>
                    </div>
                    <div style={{display:'flex', justifyContent:'space-between', marginBottom:'20px', fontWeight:'bold', fontSize:'15pt', color: '#000'}}>
                      <div>部 門：<span style={{borderBottom:'2px dotted black', minWidth:'350px', display:'inline-block', textAlign:'center'}}>{lastTransactionBatch.dept}</span></div>
                      <div>{new Date(lastTransactionBatch.timestamp).getFullYear() - 1911} 年 {new Date(lastTransactionBatch.timestamp).getMonth() + 1} 月 {new Date(lastTransactionBatch.timestamp).getDate()} 日</div>
                    </div>
                    <table style={{width:'100%', borderCollapse:'collapse', border:'3px solid black'}}>
                      <thead>
                        <tr style={{background:'#f2f2f2'}}>
                          <th style={{padding:'12px', border:'1.5px solid black', fontSize:'14pt', color: '#000'}}>名稱</th>
                          <th style={{padding:'12px', border:'1.5px solid black', fontSize:'14pt', color: '#000'}}>規範</th>
                          <th style={{padding:'12px', border:'1.5px solid black', fontSize:'14pt', color: '#000'}}>單位</th>
                          <th style={{padding:'12px', border:'1.5px solid black', fontSize:'14pt', color: '#000'}}>數量</th>
                          <th style={{padding:'12px', border:'1.5px solid black', fontSize:'14pt', color: '#000'}}>備註</th>
                        </tr>
                      </thead>
                      <tbody>
                        {lastTransactionBatch.items.map((it, i) => (
                          <tr key={i}>
                            <td style={{textAlign:'center', padding:'15px', border:'1.5px solid black', fontSize:'13pt', color: '#000'}}>{it.name}</td>
                            <td style={{border:'1.5px solid black', textAlign:'center', fontSize:'13pt', color: '#000'}}>{it.spec}</td>
                            <td style={{border:'1.5px solid black', textAlign:'center', fontSize:'13pt', color: '#000'}}>{it.unit}</td>
                            <td style={{fontWeight:'bold', fontSize:'20pt', border:'1.5px solid black', textAlign:'center', color: '#000'}}>{it.quantity}</td>
                            <td style={{border:'1.5px solid black', textAlign:'center', fontSize:'13pt', color: '#000'}}>{lastTransactionBatch.reason}</td>
                          </tr>
                        ))}
                        {Array(Math.max(0, 15 - lastTransactionBatch.items.length)).fill(0).map((_, i) => (
                          <tr key={i}><td style={{height:'40px', border:'1.5px solid black'}}>&nbsp;</td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td><td style={{border:'1.5px solid black'}}></td></tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {showSettings && (
          <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-xl z-[600] flex items-center justify-center p-4">
            <div className="bg-white rounded-[3rem] w-full max-w-2xl p-12 shadow-2xl">
              <h3 className="text-3xl font-black text-slate-900 mb-6">連線設定</h3>
              <p className="text-slate-500 font-bold mb-8">設定資料庫 URL 以建立多人同步環境</p>
              <input type="text" className="w-full p-5 rounded-2xl text-black font-black text-lg border-2" defaultValue={gasUrl} id="gas-url-input" placeholder="貼上網址..."/>
              <div className="flex gap-4 mt-10">
                <button onClick={() => handleGasUrlSave((document.getElementById('gas-url-input') as HTMLInputElement).value)} className="flex-1 py-6 bg-blue-600 text-white rounded-[1.5rem] font-black text-2xl shadow-xl">儲存並建立同步</button>
                <button onClick={() => setShowSettings(false)} className="px-10 py-6 bg-slate-100 text-slate-600 rounded-[1.5rem] font-black text-2xl">取消</button>
              </div>
            </div>
          </div>
        )}

        {deleteTarget && (
          <div className="fixed inset-0 bg-slate-900/90 flex items-center justify-center p-4 z-[400]">
            <div className="bg-white p-12 rounded-[2.5rem] text-center max-w-md shadow-2xl">
              <h3 className="text-3xl font-black mb-4 text-slate-900">確定刪除？</h3>
              <p className="text-slate-500 font-bold mb-8">「{deleteTarget.name}」將永久移除。</p>
              <div className="flex flex-col gap-3">
                <button onClick={()=>{ const updated = items.filter(i => i.id !== deleteTarget.id); setItems(updated); syncToCloud(updated, logs); setDeleteTarget(null); }} className="w-full py-5 bg-red-600 text-white rounded-2xl font-black text-xl shadow-xl">確認刪除</button>
                <button onClick={()=>setDeleteTarget(null)} className="w-full py-4 text-slate-400 font-bold">取消</button>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  Stethoscope,
  ShoppingCart,
  Users,
  RefreshCw,
  Clock,
  TrendingUp,
  BarChart3,
  Settings,
  Cloud,
  Calendar,
  Filter,
  ArrowUpRight,
  List
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell 
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

const CHART_COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

type SyncStatus = 'synced' | 'syncing' | 'error' | 'local';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');
  const [syncStatus, setSyncStatus] = useState<SyncStatus>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '從未同步');
  const [showSettings, setShowSettings] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false); 

  // 看板篩選器狀態
  const [statsDeptFilter, setStatsDeptFilter] = useState<string>('ALL');
  const [statsYearFilter, setStatsYearFilter] = useState<number>(new Date().getFullYear());

  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  // 15秒高頻自動對齊
  useEffect(() => {
    const initLoad = async () => {
      const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
      const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
      if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
      if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
      setIsLoaded(true);
      if (gasUrl) fetchFromCloud();
    };
    initLoad();

    const interval = setInterval(() => {
      if (localStorage.getItem(STORAGE_KEY_GAS_URL) && !isProcessing) {
        fetchFromCloud();
      }
    }, 15000); 

    return () => clearInterval(interval);
  }, [gasUrl, isProcessing]);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const updateSyncTime = () => {
    const now = new Date().toLocaleTimeString('zh-TW', { hour12: false, hour: '2-digit', minute: '2-digit' });
    const fullTime = `${new Date().toLocaleDateString('zh-TW')} ${now}`;
    setLastSyncTime(fullTime);
    localStorage.setItem(STORAGE_KEY_LAST_SYNC, fullTime);
  };

  const syncToCloud = async (currentItems: InventoryItem[], currentLogs: Transaction[]) => {
    if (!gasUrl) { setSyncStatus('local'); return; }
    setSyncStatus('syncing');
    try {
      const payload = { items: currentItems, logs: currentLogs, timestamp: Date.now() };
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify(payload), mode: 'no-cors' });
      setSyncStatus('synced');
      updateSyncTime();
    } catch (err) {
      setSyncStatus('error');
    }
  };

  const fetchFromCloud = async (): Promise<{items: InventoryItem[], logs: Transaction[]} | null> => {
    const currentUrl = localStorage.getItem(STORAGE_KEY_GAS_URL);
    if (!currentUrl) return null;
    setSyncStatus('syncing');
    try {
      const response = await fetch(currentUrl);
      const data = await response.json();
      if (data && data.items) {
        setItems(data.items);
        setLogs(data.logs || []);
        setSyncStatus('synced');
        updateSyncTime();
        return data;
      }
    } catch (err) {
      setSyncStatus('error');
    }
    return null;
  };

  const handleGasUrlSave = (newUrl: string) => {
    const cleanUrl = newUrl.trim();
    setGasUrl(cleanUrl);
    localStorage.setItem(STORAGE_KEY_GAS_URL, cleanUrl);
    setShowSettings(false);
    if (cleanUrl) fetchFromCloud(); else setSyncStatus('local');
  };

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const getReservedQty = (itemId: string) => basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);

  const currentAvailable = useMemo(() => {
    if (!selectedItemId) return 0;
    const item = items.find(i => i.id === selectedItemId);
    return item ? item.quantity - getReservedQty(selectedItemId) : 0;
  }, [selectedItemId, items, basket]);

  const isQtyOver = useMemo(() => {
    if (issuanceMode === 'IN') return false;
    const qty = Number(inputQty);
    return !isNaN(qty) && qty > currentAvailable;
  }, [inputQty, currentAvailable, issuanceMode]);

  const addToBasket = () => {
    if (!selectedItemId || isQtyOver) return;
    const targetItem = items.find(i => i.id === selectedItemId);
    if (!targetItem) return;
    const qty = Number(inputQty);
    if (isNaN(qty) || qty <= 0) return;
    setBasket(prev => [...prev, { itemId: targetItem.id, name: targetItem.name, quantity: qty, unit: targetItem.unit, spec: targetItem.spec, itemType: targetItem.itemType }]);
    setSelectedItemId(''); setInputQty('1');
  };

  const processIssuance = async () => {
    if (basket.length === 0 || isProcessing) return;
    setIsProcessing(true);

    const cloudData = await fetchFromCloud();
    const latestItems = cloudData ? cloudData.items : [...items];
    const latestLogs = cloudData ? cloudData.logs : [...logs];

    const timestamp = Date.now();
    const batchId = generateId();
    let updatedItems = [...latestItems];
    const newLogs: Transaction[] = [];

    basket.forEach(bItem => {
      updatedItems = updatedItems.map(item => {
        if (item.id === bItem.itemId) {
          const newQty = issuanceMode === 'IN' ? item.quantity + bItem.quantity : item.quantity - bItem.quantity;
          return { ...item, quantity: Math.max(0, newQty), lastUpdated: timestamp };
        }
        return item;
      });
      newLogs.push({ 
        id: generateId() + Math.random().toString(36).substr(2, 4), 
        itemId: bItem.itemId, 
        itemName: bItem.name, 
        type: issuanceMode, 
        quantity: bItem.quantity, 
        person: inputPerson || '未填寫', 
        dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處', 
        reason: inputReason, 
        timestamp: timestamp 
      });
    });

    const finalLogs = [...newLogs, ...latestLogs];
    setItems(updatedItems);
    setLogs(finalLogs);
    await syncToCloud(updatedItems, finalLogs);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({ id: batchId, dept: selectedDept, person: inputPerson, reason: inputReason, items: [...basket], timestamp: timestamp });
      setShowPrintModal(true);
    } else { window.alert(`✅ 入庫完成。庫存已校對更新。`); }

    setBasket([]); setInputPerson(''); setInputReason('');
    setIsProcessing(false);
  };

  const handleFinalPrint = () => {
    if (!lastTransactionBatch) return;
    const date = new Date(lastTransactionBatch.timestamp);
    const isEquip = lastTransactionBatch.items.some(it => it.itemType === 'EQUIPMENT');
    const isConsum = lastTransactionBatch.items.every(it => it.itemType === 'CONSUMABLE') || !isEquip;

    const rows = lastTransactionBatch.items.map(item => `<tr><td style="text-align:center; padding: 12px; border: 1.5px solid black; color: black !important;">${item.name}</td><td style="text-align:center; border: 1.5px solid black; color: black !important;">${item.spec || ''}</td><td style="text-align:center; border: 1.5px solid black; color: black !important;">${item.unit}</td><td style="text-align:center; font-size:18pt; font-weight:bold; border: 1.5px solid black; color: black !important;">${item.quantity}</td><td style="text-align:center; border: 1.5px solid black; color: black !important;">${lastTransactionBatch.reason}</td></tr>`).join('');
    const emptyRowsCount = Math.max(0, 15 - lastTransactionBatch.items.length);
    const emptyRows = Array(emptyRowsCount).fill('<tr><td style="height:35px; border: 1.5px solid black;">&nbsp;</td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td><td style="border: 1.5px solid black;"></td></tr>').join('');

    const printWin = window.open('', '_blank', 'width=1100,height=900');
    if (!printWin) return;
    printWin.document.write(`
      <html><head><title>領用單_${lastTransactionBatch.id}</title><style>
            @font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); }
            @page { margin: 0; }
            body { font-family: 'StandardKai', 'Microsoft JhengHei', sans-serif; padding: 80px 60px; color: #000000 !important; background: white; margin: 0; }
            .title { text-align: center; font-size: 26pt; font-weight: bold; margin-bottom: 25px; color: #000000 !important; }
            .checkbox-area { display: flex; justify-content: center; gap: 40px; font-size: 16pt; margin-bottom: 25px; font-weight: bold; color: #000000 !important; }
            .checkbox { width: 22px; height: 22px; border: 2.5px solid black; display: inline-flex; align-items: center; justify-content: center; margin-right: 8px; vertical-align: middle; }
            .dept-row { font-size: 15pt; font-weight: bold; margin-bottom: 10px; display: flex; justify-content: space-between; color: #000000 !important; }
            table { width: 100%; border-collapse: collapse; border: 2.5px solid black; margin-bottom: 25px; }
            th { border: 1.5px solid black; padding: 10px; text-align: center; font-size: 14pt; font-weight: bold; background: #f2f2f2; color: #000000 !important; }
            td { color: #000000 !important; }
            .footer-row { font-size: 14pt; font-weight: bold; margin-top: 30px; color: #000000 !important; }
            .sig-area { display: flex; justify-content: space-between; margin-top: 45px; font-size: 13pt; }
          </style></head><body>
          <div style="display: flex; flex-direction: column; align-items: flex-end;"><div style="font-size: 9pt; color: #666;">單號：${lastTransactionBatch.id}</div></div>
          <div class="title">台灣電力公司電力修護處南部分處</div>
          <div class="checkbox-area"><div><span class="checkbox">${isEquip ? 'V' : ''}</span>設備借用單</div><div><span class="checkbox">${isConsum ? 'V' : ''}</span>消耗品領用單</div></div>
          <div class="dept-row"><div>部 門：<span style="border-bottom: 2px dotted black; min-width: 350px; display: inline-block; text-align: center;">${lastTransactionBatch.dept}</span></div><div>${date.getFullYear() - 1911} 年 ${date.getMonth() + 1} 月 ${date.getDate()} 日</div></div>
          <table><thead><tr><th>名稱</th><th>規範</th><th>單位</th><th>數量</th><th>備註</th></tr></thead><tbody>${rows}${emptyRows}</tbody></table>
          <div class="footer-row">
            <div style="display: flex; justify-content: space-between;"><div style="flex:1">申請部門：</div><div style="flex:1">經管部門：</div></div>
            <div class="sig-area"><div style="flex:1; display:flex; justify-content:space-around;"><span>經辦：</span><span>課長：</span><span>經理：</span></div><div style="flex:1; display:flex; justify-content:space-around;"><span>經辦：</span><span>課長：</span><span>經理：</span></div></div>
          </div>
          <script>window.onload = () => { setTimeout(() => { window.print(); window.close(); }, 600); };</script></body></html>
    `);
    printWin.document.close();
  };

  const handleSaveItem = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    // 立即將 currentTarget 賦值給局部變量，避免非同步事件失效
    const formEl = e.currentTarget; 
    if (isProcessing || !formEl) return;
    setIsProcessing(true);

    try {
      const cloudData = await fetchFromCloud();
      const latestItems = cloudData ? cloudData.items : [...items];

      const formData = new FormData(formEl);
      const data = { 
        name: formData.get('name') as string, 
        itemType: formData.get('itemType') as ItemType, 
        unit: formData.get('unit') as string, 
        spec: formData.get('spec') as string, 
        quantity: Number(formData.get('quantity')), 
        minStock: Number(formData.get('minStock')),
        purchaseDate: formData.get('purchaseDate') as string,
        expiryDate: formData.get('expiryDate') as string,
      };

      let updated;
      if (editTarget) {
        updated = latestItems.map(i => i.id === editTarget.id ? { ...editTarget, ...data, lastUpdated: Date.now() } : i);
        setItems(updated); setEditTarget(null);
      } else {
        updated = [...latestItems, { id: generateId(), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: Date.now() }];
        setItems(updated); setShowAddModal(false);
      }

      await syncToCloud(updated, logs);
    } catch (err) {
      console.error("Save Error:", err);
    } finally {
      setIsProcessing(false);
    }
  };

  const stats = useMemo(() => {
    const filteredLogs = logs.filter(l => {
      const logYear = new Date(l.timestamp).getFullYear();
      const isCorrectYear = logYear === statsYearFilter;
      const isCorrectDept = statsDeptFilter === 'ALL' || l.dept === statsDeptFilter;
      return l.type === 'OUT' && isCorrectYear && isCorrectDept;
    });

    const invDetailMap: Record<string, {name: string, qty: number}> = {};
    let fInvQty = 0, fMedQty = 0;

    filteredLogs.forEach(log => {
        const item = items.find(it => it.id === log.itemId);
        if (item?.itemGroup === 'MEDICINE') fMedQty += log.quantity; 
        else { 
          fInvQty += log.quantity; 
          if (!invDetailMap[log.itemId]) invDetailMap[log.itemId] = { name: log.itemName, qty: 0 }; 
          invDetailMap[log.itemId].qty += log.quantity; 
        }
    });

    const invDetails = Object.values(invDetailMap).sort((a, b) => b.qty - a.qty);
    const deptStats = logs.filter(l => l.type === 'OUT' && new Date(l.timestamp).getFullYear() === statsYearFilter).reduce((acc: any, curr) => { 
      acc[curr.dept] = (acc[curr.dept] || 0) + curr.quantity; 
      return acc; 
    }, {});

    return { 
      filtered: { 
        invQty: fInvQty, 
        medQty: fMedQty, 
        logs: filteredLogs, 
        chartData: invDetails.slice(0, 8).map(d => ({ name: d.name, value: d.qty })) 
      }, 
      deptRanking: Object.entries(deptStats).sort((a: any, b: any) => b[1] - a[1]) 
    };
  }, [items, logs, statsDeptFilter, statsYearFilter]);

  const checkExpired = (dateStr: string | undefined) => {
    if (!dateStr) return false;
    return new Date(dateStr) < new Date();
  };

  const years = useMemo(() => {
    const currentYear = new Date().getFullYear();
    const yearsSet = new Set<number>();
    yearsSet.add(currentYear);
    logs.forEach(l => yearsSet.add(new Date(l.timestamp).getFullYear()));
    return Array.from(yearsSet).sort((a, b) => b - a);
  }, [logs]);

  return (
    <div className="min-h-screen flex bg-slate-50 text-slate-900 font-sans">
      <style>{`
        /* 徹底解決日期圖示看不見的問題 */
        .date-input-container { position: relative; display: flex; align-items: center; width: 100%; }
        .date-input-container input { width: 100%; padding-right: 45px !important; }
        .date-icon-layer { 
          position: absolute; right: 15px; top: 50%; transform: translateY(-50%);
          pointer-events: none; color: #475569; z-index: 5;
        }
        input[type="date"]::-webkit-calendar-picker-indicator {
          position: absolute; left: 0; top: 0; width: 100%; height: 100%;
          margin: 0; padding: 0; cursor: pointer; opacity: 0; z-index: 10;
        }

        /* 領用單預覽專用黑色強制樣式 */
        .preview-content * { color: #000000 !important; }
        .preview-content table th, .preview-content table td { border: 2px solid black !important; }

        input, select, textarea { 
          color: #000000 !important; 
          background-color: #ffffff !important; 
          border: 2px solid #94a3b8 !important; 
          font-weight: 700 !important; 
          outline: none;
        }
        input:focus, select:focus { border-color: #2563eb !important; box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.1); }
        ::placeholder { color: #64748b !important; }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
      `}</style>

      {/* 處理遮罩 */}
      {isProcessing && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-[2px] z-[999] flex flex-col items-center justify-center">
          <div className="bg-white p-8 rounded-3xl shadow-2xl flex flex-col items-center gap-4 border-4 border-blue-600">
            <RefreshCw className="text-blue-600 animate-spin" size={56} />
            <div className="text-2xl font-black text-slate-900">同步與校對中...</div>
          </div>
        </div>
      )}

      {/* 側邊導航 */}
      <aside className="w-72 bg-slate-900 text-white p-6 flex flex-col shrink-0 border-r border-slate-800 shadow-2xl">
        <div className="flex flex-col gap-1 mb-8">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22} className="text-white"/></div>
            <h1 className="font-black text-xl text-white">工安管理系統</h1>
          </div>
          <div className="mt-6 bg-slate-800/50 rounded-2xl p-4 border border-slate-700/50">
            <div className="flex items-center justify-between mb-1">
              <span className="text-[10px] font-black text-slate-500 uppercase">多人連線狀態</span>
              <div className={`w-3 h-3 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500 shadow-lg shadow-emerald-500/50' : 'bg-orange-400 animate-pulse'}`}></div>
            </div>
            <div className="text-sm font-black text-white">{syncStatus === 'synced' ? '雲端數據對齊' : '正在連接...'}</div>
            <div className="flex items-center gap-1.5 text-[10px] text-slate-400 mt-1"><Clock size={10}/> 更新: {lastSyncTime}</div>
          </div>
        </div>
        <nav className="flex-1 space-y-1">
          {[ 
            { id: 'inventory', label: '工安耗材管理', icon: Package }, 
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope }, 
            { id: 'issuance', label: '領用補貨作業', icon: FileText }, 
            { id: 'history', label: '歷史異動日誌', icon: History }, 
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard } 
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}>
              <tab.icon size={20} /> {tab.label}
            </button>
          ))}
        </nav>
        <div className="pt-6 mt-6 border-t border-slate-800 space-y-2">
            <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-black text-slate-300 hover:bg-slate-800 transition-all"><Settings size={16}/> 雲端連線設定</button>
            <button onClick={() => fetchFromCloud()} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800"><RefreshCw size={16}/> 手動校對雲端</button>
        </div>
      </aside>

      {/* 主介面 */}
      <main className="flex-1 p-10 overflow-y-auto">
        <header className="mb-10 flex justify-between items-center">
          <h2 className="text-4xl font-black text-slate-900 tracking-tight">
            {activeTab === 'inventory' ? '工安耗材清冊' : 
             activeTab === 'medicine' ? '急救藥材清冊' : 
             activeTab === 'issuance' ? '領用 / 補貨登記' : 
             activeTab === 'history' ? '歷史異動日誌' : 
             '數據統計看板'}
          </h2>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black flex items-center gap-2 hover:bg-black shadow-xl hover:-translate-y-1">
              <Plus size={20}/> 新增品項
            </button>
          )}
        </header>

        {/* 領用作業 */}
        {activeTab === 'issuance' && (
          <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
            <div className="lg:col-span-2 bg-white p-8 rounded-[2.5rem] shadow-xl border border-slate-200">
              <h3 className="text-2xl font-black mb-8 flex items-center gap-3 text-slate-900"><ShoppingCart className="text-blue-500" size={28}/> 1. 挑選項目</h3>
              <div className="flex bg-slate-100 p-1 rounded-2xl mb-8">
                <button onClick={()=>{setIssuanceMode('OUT'); setBasket([]);}} className={`flex-1 py-4 rounded-xl font-black transition-all ${issuanceMode==='OUT'?'bg-white shadow-md text-blue-600':'text-slate-400'}`}>領用出庫</button>
                <button onClick={()=>{setIssuanceMode('IN'); setBasket([]);}} className={`flex-1 py-4 rounded-xl font-black transition-all ${issuanceMode==='IN'?'bg-white shadow-md text-emerald-600':'text-slate-400'}`}>補貨入庫</button>
              </div>
              <div className="space-y-8">
                <div>
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest">物資種類</label>
                  <div className="flex gap-3 mt-3">
                    <button onClick={()=>setIssuanceGroup('INVENTORY')} className={`flex-1 py-4 rounded-2xl font-black border-2 ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-200 text-slate-400'}`}>工安耗材</button>
                    <button onClick={()=>setIssuanceGroup('MEDICINE')} className={`flex-1 py-4 rounded-2xl font-black border-2 ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-200 text-slate-400'}`}>急救藥材</button>
                  </div>
                </div>
                <div>
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest">選擇品項</label>
                  <select className="w-full p-5 rounded-2xl mt-3 text-xl text-black font-black" value={selectedItemId} onChange={e=>setSelectedItemId(e.target.value)}>
                    <option value="">-- 請選擇 --</option>
                    {items.filter(i => i.itemGroup === issuanceGroup).map(i => (
                      <option key={i.id} value={i.id}>{i.name} ({issuanceMode === 'OUT' ? `可領:${i.quantity - getReservedQty(i.id)}` : `現有:${i.quantity}`})</option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest">數量</label>
                  <input type="number" min="1" className="w-full p-5 rounded-2xl mt-3 text-2xl font-black" value={inputQty} onChange={e=>setInputQty(e.target.value)}/>
                  {isQtyOver && <p className="text-red-600 text-sm font-black mt-3 flex items-center gap-2"><AlertTriangle size={16}/> 錯誤：庫存不足</p>}
                </div>
                <button onClick={addToBasket} disabled={!selectedItemId || isQtyOver} className={`w-full py-6 rounded-[1.5rem] font-black text-2xl flex items-center justify-center gap-3 shadow-2xl transition-all ${!selectedItemId || isQtyOver ? 'bg-slate-200 text-slate-400' : 'bg-slate-900 text-white hover:bg-black active:scale-95'}`}><Plus size={24}/> 加入本次清單</button>
              </div>
            </div>

            <div className="lg:col-span-3 bg-white p-8 rounded-[2.5rem] shadow-xl border border-slate-200 flex flex-col">
              <h3 className="text-2xl font-black mb-6 flex items-center gap-3 text-slate-900"><FileText className="text-emerald-500" size={28}/> 2. 領用資料確認</h3>
              <div className="flex-1 overflow-y-auto border-4 border-dotted border-slate-100 rounded-[2rem] mb-8 min-h-[300px] bg-slate-50 p-4">
                {basket.length > 0 ? (
                  <table className="w-full text-left">
                    <tbody className="divide-y divide-slate-100">
                      {basket.map((b, idx) => (
                        <tr key={idx} className="bg-white rounded-2xl shadow-sm mb-2">
                          <td className="px-8 py-6 font-black text-slate-900 text-lg">{b.name}</td>
                          <td className="px-8 py-6 text-center font-black text-blue-700 text-xl">{b.quantity} {b.unit}</td>
                          <td className="px-8 py-6 text-right">
                            <button onClick={()=>setBasket(prev => prev.filter((_, i) => i !== idx))} className="p-3 bg-red-50 text-red-500 rounded-xl hover:bg-red-100"><X size={20}/></button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                ) : (
                  <div className="h-full flex flex-col items-center justify-center text-slate-300 gap-4 opacity-20"><ShoppingCart size={64}/><p className="font-black text-xl">目前清單為空</p></div>
                )}
              </div>
              {issuanceMode === 'OUT' && (
                <div className="grid grid-cols-2 gap-8 mb-8">
                  <div>
                    <label className="text-xs font-black text-slate-500 uppercase tracking-widest">領用部門</label>
                    <select className="w-full p-4 rounded-2xl mt-3 text-black font-black" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>
                      {DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="text-xs font-black text-slate-500 uppercase tracking-widest">領用人員姓名</label>
                    <input type="text" placeholder="輸入姓名" className="w-full p-4 rounded-2xl mt-3 text-black font-black" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/>
                  </div>
                </div>
              )}
              <button onClick={processIssuance} disabled={basket.length === 0 || isProcessing} className={`w-full py-8 rounded-[2rem] font-black text-4xl shadow-2xl transition-all text-white active:scale-95 ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>
                {isProcessing ? '同步處理中...' : (issuanceMode === 'OUT' ? '確認領用並列印' : '確認入庫補貨')}
              </button>
            </div>
          </div>
        )}

        {/* 恢復：資訊看板詳細功能 */}
        {activeTab === 'dashboard' && (
          <div className="space-y-10 animate-in fade-in slide-in-from-bottom-6 duration-700">
            {/* 篩選工具列 */}
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-200 flex flex-wrap items-center gap-6">
              <div className="flex items-center gap-3 text-slate-700 font-black">
                <Filter size={20} className="text-blue-500" /> <span className="uppercase text-xs tracking-widest">統計篩選條件</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="text-sm font-bold text-slate-500">年份：</span>
                <select className="px-4 py-2 rounded-xl text-sm border-2 border-slate-300 font-black text-black" value={statsYearFilter} onChange={e => setStatsYearFilter(Number(e.target.value))}>
                  {years.map(y => <option key={y} value={y}>{y} 年</option>)}
                </select>
              </div>
              <div className="flex items-center gap-2">
                <span className="text-sm font-bold text-slate-500">部門：</span>
                <select className="px-4 py-2 rounded-xl text-sm border-2 border-slate-300 font-black text-black" value={statsDeptFilter} onChange={e => setStatsDeptFilter(e.target.value)}>
                  <option value="ALL">所有部門 (總覽)</option>
                  {DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
                </select>
              </div>
            </div>

            {/* 四方卡片 */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
              <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white shadow-2xl border-b-8 border-blue-500 relative overflow-hidden group">
                <p className="text-blue-400 text-xs font-black uppercase tracking-widest">年度領用量</p>
                <div className="flex items-end gap-2 mt-4"><h3 className="text-6xl font-black">{stats.filtered.invQty + stats.filtered.medQty}</h3><span className="text-blue-400 font-bold mb-2 text-xl">件</span></div>
                <div className="absolute right-[-10px] bottom-[-10px] opacity-10"><TrendingUp size={120}/></div>
              </div>
              <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border-t-8 border-blue-500"><p className="text-slate-400 text-xs font-black uppercase tracking-widest">消耗品領用</p><h3 className="text-5xl font-black mt-4 text-blue-600">{stats.filtered.invQty}</h3></div>
              <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border-t-8 border-emerald-500"><p className="text-slate-400 text-xs font-black uppercase tracking-widest">藥材領用</p><h3 className="text-5xl font-black mt-4 text-emerald-600">{stats.filtered.medQty}</h3></div>
              <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border-t-8 border-orange-500"><p className="text-slate-400 text-xs font-black uppercase tracking-widest">低庫存警戒</p><h3 className="text-5xl font-black mt-4 text-orange-600">{items.filter(i => i.quantity <= i.minStock).length}</h3></div>
            </div>

            {/* 圖表與排行 */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
              <div className="lg:col-span-2 bg-white p-10 rounded-[3rem] shadow-xl min-h-[500px] border border-slate-100">
                <h4 className="text-2xl font-black mb-8 flex items-center gap-3 text-slate-900"><BarChart3 className="text-blue-500" size={32}/> 領用品項熱度分析</h4>
                <div className="w-full h-[350px]">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={stats.filtered.chartData}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 13, fontWeight: 900, fill: '#000' }} />
                      <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 13, fontWeight: 900, fill: '#000' }} />
                      <Tooltip />
                      <Bar dataKey="value" radius={[12, 12, 0, 0]} barSize={50}>{stats.filtered.chartData.map((e, i) => (<Cell key={i} fill={CHART_COLORS[i % CHART_COLORS.length]} />))}</Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
              <div className="bg-white p-10 rounded-[3rem] shadow-xl border border-slate-100 flex flex-col">
                <h4 className="text-2xl font-black mb-8 flex items-center gap-3 text-slate-900"><Users className="text-slate-600" size={32}/> 部門領用排行</h4>
                <div className="space-y-4 flex-1 overflow-y-auto custom-scrollbar pr-2">
                  {stats.deptRanking.map(([dept, count]: any, idx) => (
                    <div key={dept} className="flex items-center gap-5 bg-slate-50 p-5 rounded-3xl hover:bg-blue-50 transition-all">
                      <div className={`w-10 h-10 flex items-center justify-center rounded-xl font-black ${idx < 3 ? 'bg-blue-600 text-white' : 'bg-slate-300 text-slate-600'}`}>{idx + 1}</div>
                      <div className="flex-1 font-black text-slate-900">{dept}</div>
                      <div className="font-black text-blue-600 text-xl">{count}</div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* 新增：看板下的詳細領用明細，滿足「檢視領用情況」 */}
            <div className="bg-white rounded-[3rem] shadow-xl overflow-hidden border border-slate-200">
              <div className="p-8 bg-slate-900 text-white flex justify-between items-center">
                <h4 className="text-2xl font-black flex items-center gap-3"><List size={28}/> 領用紀錄明細 (依當前篩選條件)</h4>
                <div className="bg-blue-600 px-6 py-2 rounded-full font-black text-sm">共 {stats.filtered.logs.length} 筆紀錄</div>
              </div>
              <div className="max-h-[500px] overflow-y-auto custom-scrollbar">
                <table className="w-full text-left">
                  <thead className="sticky top-0 bg-slate-200 text-slate-700 font-black text-xs uppercase tracking-widest z-10 border-b">
                    <tr><th className="px-8 py-5">領用時間</th><th className="px-8 py-5">品項名稱</th><th className="px-8 py-5">部門</th><th className="px-8 py-5">領用人</th><th className="px-8 py-5 text-right">數量</th></tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {stats.filtered.logs.map(log => (
                      <tr key={log.id} className="hover:bg-slate-50">
                        <td className="px-8 py-5 text-slate-500 font-bold">{new Date(log.timestamp).toLocaleDateString()}</td>
                        <td className="px-8 py-5 text-slate-900 font-black text-lg">{log.itemName}</td>
                        <td className="px-8 py-5 text-slate-700 font-bold">{log.dept}</td>
                        <td className="px-8 py-5 text-slate-700 font-bold">{log.person}</td>
                        <td className="px-8 py-5 text-right font-black text-blue-600 text-xl">{log.quantity}</td>
                      </tr>
                    ))}
                    {stats.filtered.logs.length === 0 && (
                      <tr><td colSpan={5} className="py-20 text-center text-slate-300 font-black italic">此篩選條件下無領用數據</td></tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {/* 藥材與耗材列表 */}
        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-[3rem] shadow-xl overflow-hidden border border-slate-200">
            <div className="p-8 bg-slate-50 border-b flex items-center justify-between">
              <div className="relative max-w-md w-full">
                <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400" size={24} />
                <input type="text" placeholder="輸入名稱關鍵字..." className="w-full pl-16 pr-6 py-5 rounded-[1.5rem] font-black text-xl text-black border-2 border-slate-300" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
              </div>
            </div>
            <table className="w-full text-left">
              <thead className="bg-slate-900 text-[12px] font-black text-slate-400 uppercase tracking-widest">
                <tr>
                  <th className="px-10 py-6">物資名稱</th>
                  {activeTab === 'medicine' && <><th className="px-6 py-6">購置日期</th><th className="px-6 py-6">到期日</th></>}
                  <th className="px-8 py-6 text-center">目前庫存</th>
                  <th className="px-10 py-6 text-right">管理</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {items.filter(i => (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase())).map(item => (
                  <tr key={item.id} className="hover:bg-slate-50">
                    <td className="px-10 py-8">
                      <div className="font-black text-slate-900 text-2xl mb-1">{item.name}</div>
                      <span className="text-slate-400 text-sm font-bold">{item.spec || '未填規格'}</span>
                    </td>
                    {activeTab === 'medicine' && (
                      <>
                        <td className="px-6 py-8 font-black text-slate-600">{item.purchaseDate || '--'}</td>
                        <td className="px-6 py-8"><div className={`flex items-center gap-2 font-black ${checkExpired(item.expiryDate) ? 'text-red-600' : 'text-slate-900'}`}><Calendar size={18}/> {item.expiryDate || '未設定'}</div></td>
                      </>
                    )}
                    <td className="px-8 py-8 text-center"><span className={`px-10 py-4 rounded-[1.2rem] font-black text-3xl border-2 ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600 border-red-200' : 'bg-emerald-50 text-emerald-600 border-emerald-100'}`}>{item.quantity} {item.unit}</span></td>
                    <td className="px-10 py-8 text-right space-x-2">
                      <button onClick={() => setEditTarget(item)} className="p-4 bg-white border border-slate-200 text-slate-400 hover:text-blue-600 rounded-2xl transition-all shadow-sm"><Edit3 size={24}/></button>
                      <button onClick={() => setDeleteTarget({id: item.id, name: item.name})} className="p-4 bg-white border border-slate-200 text-slate-400 hover:text-red-600 rounded-2xl transition-all shadow-sm"><Trash2 size={24}/></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* 異動日誌 */}
        {activeTab === 'history' && (
          <div className="bg-white rounded-[3rem] shadow-xl overflow-hidden border border-slate-200">
