                </div>
                <div className="grid grid-cols-2 gap-8">
                  <div>
                    <label className="text-xs font-black text-slate-500">規格規範</label>
                    <input name="spec" type="text" className="w-full p-5 rounded-2xl mt-3 font-black text-black border-2" defaultValue={editTarget?.spec || ''} placeholder="尺寸或序號" />
                  </div>
                  <div>
                    <label className="text-xs font-black text-slate-500">分類</label>
                    <select name="itemType" className="w-full p-5 rounded-2xl mt-3 font-black text-black border-2" defaultValue={editTarget?.itemType || 'CONSUMABLE'}>
                      <option value="EQUIPMENT">安全設備 (借用)</option>
