                          <th style={{padding:'8px', border:'1.5px solid black', color: 'black'}}>單位</th>
                          <th style={{padding:'8px', border:'1.5px solid black', color: 'black'}}>數量</th>
                          <th style={{padding:'8px', border:'1.5px solid black', color: 'black'}}>備註</th>
