                const printWin = window.open('', '_blank');
                if (!printWin) return;
                printWin.document.write(`<html><head><title>領用單</title><style>@font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); } body { font-family: 'StandardKai', serif; padding: 60px; color: black; } table { width:100%; border-collapse:collapse; border:2px solid black; } th, td { border:1px solid black; padding:8px; text-align:center; }</style></head><body><h1 style="text-align:center">台灣電力公司電力修護處南部分處</h1><div style="text-align:right">單號：${lastTransactionBatch.id}</div><div style="margin:20px 0">部門：${lastTransactionBatch.dept}</div><table><thead><tr><th>名稱</th><th>規範</th><th>數量</th></tr></thead><tbody>${lastTransactionBatch.items.map(it=>`<tr><td>${it.name}</td><td>${it.spec}</td><td>${it.quantity}</td></tr>`).join('')}</tbody></table><script>window.onload=()=>{window.print();window.close();};</script></body></html>`);
                printWin.document.close();
              }} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xl shadow-xl flex items-center gap-2"><Printer size={24}/> 直接列印</button><button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-2xl text-black hover:bg-slate-200"><X size={32}/></button></div></div>
              <div className="flex-1 bg-slate-100 p-10 flex justify-center overflow-y-auto"><div className="bg-white shadow-2xl p-10 w-[210mm] min-h-[297mm] text-black">預覽載入中...</div></div>
