  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  CheckCircle2,
  Users,
  Download,
  Upload,
  Settings,
  RefreshCw,
  Clock,
  TrendingUp,
  BarChart3,
  Calendar,
  List,
  Zap,
  ArrowUp,
  ArrowDown,
  ArrowUpDown
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell 
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

const CHART_COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

type SyncStatus = 'synced' | 'syncing' | 'error' | 'local';
type SortKey = 'name' | 'quantity' | 'expiryDate' | 'lastUpdated';
type SortOrder = 'asc' | 'desc';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');
  const [syncStatus, setSyncStatus] = useState<SyncStatus>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '從未同步');
  const [showSettings, setShowSettings] = useState(false);

  const [sortConfig, setSortConfig] = useState<{ key: SortKey; order: SortOrder }>({ key: 'lastUpdated', order: 'desc' });
  const [statsDeptFilter, setStatsDeptFilter] = useState<string>('ALL');
  const [statsYearFilter, setStatsYearFilter] = useState<number>(new Date().getFullYear());
  const [lastTransactionBatch, setLastTransactionBatch] = useState<{ id: string; dept: string; person: string; reason: string; items: BasketItem[]; timestamp: number; } | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceSearch, setIssuanceSearch] = useState('');
  const [isIssuanceDropdownOpen, setIsIssuanceDropdownOpen] = useState(false);
  const issuanceDropdownRef = useRef<HTMLDivElement>(null);
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- 核心邏輯：修復看板與同步合併 ---

  // 1. 統計數據計算邏輯 (修復看板空白問題)
  const stats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    const medItems = items.filter(i => i.itemGroup === 'MEDICINE');
    const filteredLogs = logs.filter(l => {
        const logDate = new Date(l.timestamp);
        return l.type === 'OUT' && logDate.getFullYear() === statsYearFilter && (statsDeptFilter === 'ALL' || l.dept === statsDeptFilter);
    });

    const invDetailMap: Record<string, {name: string, qty: number}> = {};
    const medDetailMap: Record<string, {name: string, qty: number}> = {};
    let fInvQty = 0, fMedQty = 0;

    filteredLogs.forEach(log => {
        const item = items.find(it => it.id === log.itemId);
        if (item?.itemGroup === 'MEDICINE') { 
          fMedQty += log.quantity; 
          if (!medDetailMap[log.itemId]) medDetailMap[log.itemId] = { name: log.itemName, qty: 0 }; 
          medDetailMap[log.itemId].qty += log.quantity; 
        } 
        else { 
          fInvQty += log.quantity; 
          if (!invDetailMap[log.itemId]) invDetailMap[log.itemId] = { name: log.itemName, qty: 0 }; 
          invDetailMap[log.itemId].qty += log.quantity; 
        }
    });

    const invDetails = Object.values(invDetailMap).sort((a, b) => b.qty - a.qty);
    const deptRanking = Object.entries(logs.filter(l => l.type === 'OUT' && new Date(l.timestamp).getFullYear() === statsYearFilter).reduce((acc: any, curr) => { 
      acc[curr.dept] = (acc[curr.dept] || 0) + curr.quantity; 
      return acc; 
    }, {})).sort((a: any, b: any) => b[1] - a[1]);

    return { 
      sys: { invTotal: invItems.length, medTotal: medItems.length }, 
      filtered: { 
        invQty: fInvQty, 
        medQty: fMedQty, 
        invDetails, 
        logs: filteredLogs, 
        chartData: invDetails.slice(0, 8).map(d => ({ name: d.name, value: d.qty })) 
      }, 
      deptRanking 
    };
  }, [items, logs, statsDeptFilter, statsYearFilter]);

  // 2. 智慧合併邏輯 (解決 JSON 導入沒反應)
  const smartMergeItems = (local: InventoryItem[], remote: InventoryItem[]): InventoryItem[] => {
    const mergedMap = new Map<string, InventoryItem>();
    const now = Date.now();

    // 處理本地資料
    local.forEach(item => {
      const fixedItem = { ...item, itemGroup: item.itemGroup || 'INVENTORY', lastUpdated: item.lastUpdated || now };
      mergedMap.set(item.id, fixedItem);
    });

    // 比對並合併遠端資料 (例如 JSON 備份)
    remote.forEach(remoteItem => {
      // 如果 JSON 裡沒標籤，補上標籤；沒時間戳，補上時間，確保它能參與比對
      const fixedRemote = { ...remoteItem, itemGroup: remoteItem.itemGroup || 'INVENTORY', lastUpdated: remoteItem.lastUpdated || now };
      const localItem = mergedMap.get(remoteItem.id);

      // 合併規則：如果本地沒有，或者 JSON 的資料比較新 (或本地沒時間戳)，則採納 JSON 的
      if (!localItem || (fixedRemote.lastUpdated >= (localItem.lastUpdated || 0))) {
        mergedMap.set(remoteItem.id, fixedRemote);
      }
    });

    return Array.from(mergedMap.values());
  };

  const smartMergeLogs = (local: Transaction[], remote: Transaction[]): Transaction[] => {
    const mergedMap = new Map<string, Transaction>();
    local.forEach(l => mergedMap.set(l.id, l));
    remote.forEach(l => mergedMap.set(l.id, l));
    return Array.from(mergedMap.values()).sort((a, b) => b.timestamp - a.timestamp);
  };

  useEffect(() => {
    const initLoad = async () => {
      const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
      const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);

      let initialItems: InventoryItem[] = [];
      let initialLogs: Transaction[] = [];

      if (savedItems) { 
        try { 
          const p = JSON.parse(savedItems); 
          if (Array.isArray(p)) {
            initialItems = p.map(i => ({ ...i, itemGroup: i.itemGroup || 'INVENTORY', lastUpdated: i.lastUpdated || Date.now() }));
          }
        } catch (e) {} 
      }
      if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) initialLogs = p; } catch (e) {} }

      setItems(initialItems);
      setLogs(initialLogs);
      setIsLoaded(true);

      if (gasUrl) { 
        handleSmartSync(initialItems, initialLogs);
      } else { 
        setSyncStatus('local'); 
      }
    };
    initLoad();

    const handleClickOutside = (event: MouseEvent) => {
      if (issuanceDropdownRef.current && !issuanceDropdownRef.current.contains(event.target as Node)) {
        setIsIssuanceDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [gasUrl]);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const handleSmartSync = async (currentItems: InventoryItem[] = items, currentLogs: Transaction[] = logs) => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const response = await fetch(gasUrl);
      const remoteData = await response.json();

      let finalItems = currentItems;
      let finalLogs = currentLogs;

      if (remoteData && remoteData.items) {
        finalItems = smartMergeItems(currentItems, remoteData.items);
        finalLogs = smartMergeLogs(currentLogs, remoteData.logs || []);
        setItems(finalItems);
        setLogs(finalLogs);
      }

      const payload = { items: finalItems, logs: finalLogs, timestamp: Date.now() };
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify(payload), mode: 'no-cors' });

      setSyncStatus('synced');
      const nowTime = new Date().toLocaleString('zh-TW', { hour12: false });
      setLastSyncTime(nowTime);
      localStorage.setItem(STORAGE_KEY_LAST_SYNC, nowTime);
    } catch (err) {
      setSyncStatus('error');
    }
  };

  const handleGasUrlSave = (newUrl: string) => {
    const cleanUrl = newUrl.trim();
    setGasUrl(cleanUrl);
    localStorage.setItem(STORAGE_KEY_GAS_URL, cleanUrl);
    setShowSettings(false);
    if (cleanUrl) { handleSmartSync(); } else { setSyncStatus('local'); }
  };

  const exportData = () => {
    const data = { items, logs, timestamp: Date.now() };
    const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `工安智慧備份_${new Date().toLocaleDateString().replace(/\//g, '-')}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const importData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (data && (data.items || Array.isArray(data))) {
          const importItems = Array.isArray(data) ? data : data.items;
          const importLogs = data.logs || [];

          if (window.confirm(`找到 ${importItems.length} 個品項，是否執行「智慧合併」導入？\n這將保留較新的資料，且不會刪除您現有的其他項目。`)) {
            const mergedItems = smartMergeItems(items, importItems);
            const mergedLogs = smartMergeLogs(logs, importLogs);
            setItems(mergedItems);
            setLogs(mergedLogs);
            if (gasUrl) handleSmartSync(mergedItems, mergedLogs);
            window.alert("✅ 資料導入並合併完成！");
          }
        } else {
          window.alert("❌ 檔案內容不符規範，請確認是否為本系統匯出的 JSON 檔案。");
        }
      } catch (err) { 
        console.error(err);
        window.alert("❌ 檔案讀取失敗，請確認檔案格式是否正確。"); 
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  // --- UI 組件邏輯 ---
  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;
  const getReservedQty = (itemId: string) => basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);

  const frequentItems = useMemo(() => {
    const counts: Record<string, number> = {};
    logs.filter(l => l.type === 'OUT').forEach(l => { counts[l.itemId] = (counts[l.itemId] || 0) + 1; });
    return Object.entries(counts)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5)
      .map(([id]) => items.find(i => i.id === id))
      .filter((i): i is InventoryItem => !!i && i.itemGroup === issuanceGroup);
  }, [logs, items, issuanceGroup]);

  const filteredIssuanceItems = useMemo(() => {
    return items.filter(i => i.itemGroup === issuanceGroup && (i.name.toLowerCase().includes(issuanceSearch.toLowerCase()) || i.spec.toLowerCase().includes(issuanceSearch.toLowerCase())));
  }, [items, issuanceGroup, issuanceSearch]);

  const managedItems = useMemo(() => {
    const filtered = items.filter(i => (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase()));
    return filtered.sort((a, b) => {
      let valA: any = a[sortConfig.key] || '';
      let valB: any = b[sortConfig.key] || '';
      if (sortConfig.key === 'quantity') { valA = Number(valA); valB = Number(valB); } 
      else if (sortConfig.key === 'expiryDate') { valA = valA ? new Date(valA).getTime() : 0; valB = valB ? new Date(valB).getTime() : 0; }
      if (valA < valB) return sortConfig.order === 'asc' ? -1 : 1;
      if (valA > valB) return sortConfig.order === 'asc' ? 1 : -1;
      return 0;
    });
  }, [items, activeTab, searchTerm, sortConfig]);

  const processIssuance = () => {
    if (basket.length === 0) return;
    const timestamp = Date.now();
    const batchId = generateId();
    let updatedItems = [...items];
    const newLogs: Transaction[] = [];

    basket.forEach(bItem => {
      updatedItems = updatedItems.map(item => {
        if (item.id === bItem.itemId) {
          const newQty = issuanceMode === 'IN' ? item.quantity + bItem.quantity : item.quantity - bItem.quantity;
          return { ...item, quantity: newQty, lastUpdated: timestamp };
        }
        return item;
      });
      newLogs.push({ id: generateId() + Math.random().toString(36).substr(2, 4), itemId: bItem.itemId, itemName: bItem.name, type: issuanceMode, quantity: bItem.quantity, person: inputPerson || '未填寫', dept: issuanceMode === 'OUT' ? selectedDept : '修護處南部分處', reason: inputReason, timestamp: timestamp, spec: bItem.spec });
    });

    const finalLogs = [...newLogs, ...logs];
    setItems(updatedItems);
    setLogs(finalLogs);
    handleSmartSync(updatedItems, finalLogs);

    if (issuanceMode === 'OUT') {
      setLastTransactionBatch({ id: batchId, dept: selectedDept, person: inputPerson, reason: inputReason, items: [...basket], timestamp: timestamp });
      setShowPrintModal(true);
    } else { window.alert(`✅ 物資補貨入庫完成。`); }
    setBasket([]); setInputPerson(''); setInputReason('');
  };

  const handleSaveItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = { name: formData.get('name') as string, itemType: formData.get('itemType') as ItemType, unit: formData.get('unit') as string, spec: formData.get('spec') as string, purchaseDate: formData.get('purchaseDate') as string, expiryDate: formData.get('expiryDate') as string, quantity: Number(formData.get('quantity')), minStock: Number(formData.get('minStock')), };
    let updated;
    const timestamp = Date.now();
    if (editTarget) {
      updated = items.map(i => i.id === editTarget.id ? { ...editTarget, ...data, lastUpdated: timestamp } : i);
      setItems(updated); setEditTarget(null);
    } else {
      updated = [...items, { id: generateId(), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: timestamp }];
      setItems(updated); setShowAddModal(false);
    }
    handleSmartSync(updated, logs);
  };

  return (
    <div className="min-h-screen flex bg-slate-100 text-black font-sans">
      <style>{`
        input, select, textarea { color: #000000 !important; background-color: #ffffff !important; border: 2px solid #94a3b8 !important; font-weight: 700 !important; }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
      `}</style>
      <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={importData} />
      <aside className="w-72 bg-slate-900 text-white p-6 flex flex-col shrink-0 border-r border-slate-800 shadow-2xl">
        <div className="flex flex-col gap-1 mb-8">
          <div className="flex items-center gap-3"><div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22} className="text-white"/></div><h1 className="font-black text-xl tracking-tight text-white">工安管理系統</h1></div>
          <div className="mt-6 bg-slate-800/50 rounded-2xl p-4 border border-slate-700/50">
            <div className="flex items-center justify-between mb-2"><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">智慧連線狀態</span><div className={`w-3 h-3 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.8)]' : syncStatus === 'syncing' ? 'bg-amber-500 animate-pulse' : syncStatus === 'error' ? 'bg-red-500' : 'bg-orange-400'}`}></div></div>
            <div className="text-sm font-black text-white mb-1">{syncStatus === 'synced' ? '智慧合併成功' : syncStatus === 'syncing' ? '正在合併資料...' : '本地模式'}</div>
            <div className="flex items-center gap-1.5 text-[10px] text-slate-400 font-bold"><Clock size={10}/> 最後同步：{lastSyncTime}</div>
          </div>
        </div>
        <nav className="flex-1 space-y-1">
          {[ { id: 'inventory', label: '工安耗材管理', icon: Package }, { id: 'medicine', label: '急救藥材管理', icon: Stethoscope }, { id: 'issuance', label: '領用補貨作業', icon: FileText }, { id: 'history', label: '歷史異動日誌', icon: History }, { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard }, ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}><tab.icon size={20} /> {tab.label}</button>
          ))}
        </nav>
        <div className="pt-6 mt-6 border-t border-slate-800 space-y-2">
            <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-black text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><Settings size={16}/> 雲端智慧同步設定</button>
            <button onClick={() => handleSmartSync()} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><RefreshCw size={16}/> 手動合併同步</button>
            <button onClick={exportData} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><Download size={16}/> 匯出備份 (JSON)</button>
            <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><Upload size={16}/> 導入合併備份</button>
        </div>
      </aside>

      <main className="flex-1 p-10 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-3xl font-black text-black">{activeTab === 'inventory' ? '工安耗材清冊' : activeTab === 'medicine' ? '急救藥材清冊' : activeTab === 'issuance' ? '領用 / 補貨登記' : activeTab === 'history' ? '歷史異動日誌' : '數據統計看板'}</h2>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (<button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-black shadow-xl"><Plus size={18}/> 新增項目</button>)}
        </header>

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-200 flex flex-wrap items-center gap-6">
              <div className="flex items-center gap-2"><label className="text-xs font-black text-slate-400">統計年度</label><select className="p-2 rounded-lg text-sm font-bold text-black border-2 border-slate-300" value={statsYearFilter} onChange={e => setStatsYearFilter(Number(e.target.value))}><option value={2025}>2025</option><option value={2024}>2024</option></select></div>
              <div className="flex items-center gap-2"><label className="text-xs font-black text-slate-400">篩選部門</label><select className="p-2 rounded-lg text-sm font-bold text-black border-2 border-slate-300" value={statsDeptFilter} onChange={e => setStatsDeptFilter(e.target.value)}><option value="ALL">全廠總覽</option>{DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}</select></div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              <div className="bg-slate-900 p-8 rounded-[2rem] text-white shadow-xl flex flex-col justify-between">
                <div><p className="text-blue-400 text-xs font-black uppercase tracking-widest">年度總領用</p><h3 className="text-5xl font-black mt-2 text-white">{stats.filtered.invQty + stats.filtered.medQty}</h3></div>
                <TrendingUp className="text-blue-500 mt-4" size={32}/>
              </div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-blue-500"><p className="text-slate-400 text-xs font-black uppercase">工安耗材</p><h3 className="text-4xl font-black mt-2 text-blue-600">{stats.filtered.invQty} <span className="text-sm font-bold text-slate-400">件</span></h3></div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-emerald-500"><p className="text-slate-400 text-xs font-black uppercase">藥材</p><h3 className="text-4xl font-black mt-2 text-emerald-600">{stats.filtered.medQty} <span className="text-sm font-bold text-slate-400">件</span></h3></div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-orange-500"><p className="text-slate-400 text-xs font-black uppercase">低庫存警示</p><h3 className="text-4xl font-black mt-2 text-orange-600">{items.filter(i => i.quantity <= i.minStock).length} <span className="text-sm font-bold text-slate-400">項</span></h3></div>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 bg-white p-8 rounded-[2.5rem] shadow-lg min-h-[400px]">
                <h4 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><BarChart3 className="text-blue-500"/> 熱門領用品項分析</h4>
                <div className="h-80">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={stats.filtered.chartData}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                      <XAxis dataKey="name" tick={{ fontSize: 12, fontWeight: 700 }} />
                      <YAxis tick={{ fontSize: 12, fontWeight: 700 }} />
                      <Tooltip />
                      <Bar dataKey="value" radius={[8, 8, 0, 0]} barSize={40}>
                        {stats.filtered.chartData.map((_, index) => ( <Cell key={`cell-${index}`} fill={CHART_COLORS[index % CHART_COLORS.length]} /> ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
              <div className="bg-white p-8 rounded-[2.5rem] shadow-lg flex flex-col">
                <h4 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><Users className="text-slate-600"/> 部門領用排行</h4>
                <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
                  {stats.deptRanking.map(([dept, count]: any, idx) => (
                    <div key={dept} className="flex items-center gap-4 bg-slate-50 p-4 rounded-2xl">
                      <div className="w-8 h-8 flex items-center justify-center rounded-xl bg-slate-900 text-white text-xs font-black">{idx + 1}</div>
                      <div className="flex-1 font-bold">{dept}</div>
                      <div className="font-black text-blue-600">{count} 件</div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}

        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-200">
            <div className="p-6 bg-slate-50 border-b flex items-center justify-between">
              <div className="relative max-w-sm w-full"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="搜尋項目名稱..." className="w-full pl-12 pr-4 py-3 rounded-xl font-bold text-black border-2 border-slate-300" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} /></div>
              <div className="text-xs font-bold text-slate-400">目前顯示：{managedItems.length} 個品項</div>
            </div>
            <table className="w-full text-left">
              <thead className="bg-slate-100 text-[11px] font-black text-slate-500 uppercase border-b">
                <tr><th className="px-8 py-5">名稱及規格</th><th className="px-8 py-5 text-center">目前庫存</th>{activeTab === 'medicine' && (<th className="px-8 py-5 text-center">有效期限</th>)}<th className="px-8 py-5 text-right">操作</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {managedItems.map(item => (<tr key={item.id} className="hover:bg-slate-50"><td className="px-8 py-5"><div className="font-black text-black">{item.name}</div><div className="flex items-center gap-2 mt-1"><span className={`text-[10px] px-2 py-0.5 rounded font-black border ${item.itemType === 'EQUIPMENT' ? 'text-blue-600 border-blue-200' : 'text-slate-500 border-slate-200'}`}>{item.itemType === 'EQUIPMENT' ? '設備' : '耗材'}</span><span className="text-xs text-slate-400 font-bold">{item.spec || '無規格'}</span></div></td><td className="px-8 py-5 text-center"><span className={`px-6 py-2 rounded-xl font-black text-xl border-2 ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600 border-red-200' : 'bg-emerald-50 text-emerald-600 border-emerald-100'}`}>{item.quantity} {item.unit}</span></td>{activeTab === 'medicine' && (<td className="px-8 py-5 text-center"><div className={`text-sm font-black flex items-center justify-center gap-1.5 ${new Date(item.expiryDate || '') < new Date() ? 'text-red-600' : 'text-emerald-600'}`}><Calendar size={14}/> {item.expiryDate?.replace(/-/g, '/') || '未填'}</div></td>)}<td className="px-8 py-5 text-right"><button onClick={() => setEditTarget(item)} className="p-2 text-slate-400 hover:text-blue-600"><Edit3 size={20}/></button><button onClick={() => setDeleteTarget({id: item.id, name: item.name})} className="p-2 text-slate-400 hover:text-red-600"><Trash2 size={20}/></button></td></tr>))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'issuance' && (
          <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
            <div className="lg:col-span-2 bg-white p-8 rounded-3xl shadow-xl border border-slate-200">
              <h3 className="text-xl font-black mb-8 flex items-center gap-2 text-black"><ShoppingCart className="text-blue-500"/> 1. 挑選項目</h3>
              <div className="flex bg-slate-100 p-1 rounded-xl mb-6"><button onClick={()=>{setIssuanceMode('OUT'); setBasket([]);}} className={`flex-1 py-3 rounded-lg font-black transition-all ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button><button onClick={()=>{setIssuanceMode('IN'); setBasket([]);}} className={`flex-1 py-3 rounded-lg font-black transition-all ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button></div>
              <div className="space-y-6">
                <div><label className="text-xs font-black text-slate-500 uppercase tracking-widest">分類</label><div className="flex gap-2 mt-2"><button onClick={()=>{setIssuanceGroup('INVENTORY'); setIssuanceSearch(''); setSelectedItemId('');}} className={`flex-1 py-3 rounded-xl font-black border-2 ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-200 text-slate-400'}`}>耗材類</button><button onClick={()=>{setIssuanceGroup('MEDICINE'); setIssuanceSearch(''); setSelectedItemId('');}} className={`flex-1 py-3 rounded-xl font-black border-2 ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-200 text-slate-400'}`}>藥材類</button></div></div>
                <div className="space-y-4">
                  <div>
                    <label className="text-xs font-black text-slate-500 uppercase tracking-widest mb-2 block">品項選取 (顏色提示庫存)</label>
                    <div className="relative" ref={issuanceDropdownRef}>
                      {isIssuanceDropdownOpen && (
                        <div className="absolute bottom-full left-0 right-0 mb-2 bg-white rounded-2xl shadow-2xl border border-slate-200 z-[100] max-h-96 overflow-y-auto custom-scrollbar">
                          {issuanceSearch === '' && frequentItems.length > 0 && (<div className="p-2 border-b bg-blue-50/30"><p className="px-3 py-1 text-[10px] font-black text-blue-600 uppercase">熱門建議</p><div className="grid grid-cols-1 gap-1 mt-1">{frequentItems.map(item => { const remaining = item.quantity - getReservedQty(item.id); const isCritical = remaining <= item.minStock || remaining <= 0; return (<button key={item.id} onClick={() => { setSelectedItemId(item.id); setIssuanceSearch(item.name); setIsIssuanceDropdownOpen(false); }} className="w-full text-left p-3 hover:bg-blue-100 rounded-lg flex justify-between items-center group transition-colors"><div><span className="font-black text-slate-900">{item.name}</span></div><span className={`text-[10px] font-black px-2 py-0.5 rounded border ${isCritical ? 'text-red-600 bg-red-50 border-red-200' : 'text-emerald-600 bg-emerald-50 border-emerald-200'}`}>剩: {remaining}</span></button>);})}</div></div>)}
                          <div className="p-1">{filteredIssuanceItems.map(item => { const remaining = item.quantity - getReservedQty(item.id); const isCritical = remaining <= item.minStock || remaining <= 0; return (<button key={item.id} onClick={() => { setSelectedItemId(item.id); setIssuanceSearch(item.name); setIsIssuanceDropdownOpen(false); }} className="w-full text-left p-4 hover:bg-slate-50 rounded-xl flex flex-col gap-1 border-b border-slate-50 last:border-0"><div className="flex justify-between items-start"><span className="font-black text-black text-lg">{item.name}</span><span className={`text-xs font-black px-2 py-0.5 rounded ${isCritical ? 'text-red-600 bg-red-50' : 'text-emerald-600 bg-emerald-50'}`}>剩餘: {remaining} {item.unit}</span></div></button>);})}</div>
                        </div>
                      )}
                      <div className="relative"><input type="text" placeholder="搜尋項目名稱..." className="w-full p-4 pr-12 rounded-xl text-lg font-bold border-2" value={selectedItemId ? items.find(i=>i.id===selectedItemId)?.name : issuanceSearch} onChange={(e) => { setIssuanceSearch(e.target.value); setSelectedItemId(''); setIsIssuanceDropdownOpen(true); }} onFocus={() => setIsIssuanceDropdownOpen(true)} /><div className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"><Search size={20}/></div></div>
                    </div>
                  </div>
                </div>
                <div><label className="text-xs font-black text-slate-500 uppercase tracking-widest">數量</label><input type="number" min="1" className="w-full p-4 rounded-xl mt-2 text-xl font-bold" value={inputQty} onChange={e=>setInputQty(e.target.value)}/></div>
                <button onClick={()=>{ if (!selectedItemId) return; const targetItem = items.find(i => i.id === selectedItemId); if (!targetItem) return; setBasket(prev => [...prev, { itemId: targetItem.id, name: targetItem.name, quantity: Number(inputQty), unit: targetItem.unit, spec: targetItem.spec, itemType: targetItem.itemType }]); setSelectedItemId(''); setIssuanceSearch(''); }} disabled={!selectedItemId} className={`w-full py-5 rounded-2xl font-black text-xl flex items-center justify-center gap-2 shadow-lg transition-all ${!selectedItemId ? 'bg-slate-200 text-slate-400' : 'bg-slate-900 text-white hover:bg-black'}`}><Plus size={20}/> 加入處理清單</button>
              </div>
            </div>
            <div className="lg:col-span-3 bg-white p-8 rounded-3xl shadow-xl border border-slate-200 flex flex-col">
              <h3 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><FileText className="text-emerald-500"/> 2. 待處理作業</h3>
              <div className="flex-1 overflow-y-auto border-2 border-dashed border-slate-100 rounded-2xl mb-6 min-h-[250px] bg-slate-50">{basket.length > 0 ? (<table className="w-full text-left"><tbody className="divide-y divide-slate-100">{basket.map((b, idx) => (<tr key={idx} className="bg-white"><td className="px-6 py-5 font-black text-black">{b.name}</td><td className="px-6 py-5 text-center font-black text-blue-700">{b.quantity} {b.unit}</td><td className="px-6 py-5 text-right"><button onClick={()=>setBasket(prev => prev.filter((_, i) => i !== idx))} className="text-slate-300 hover:text-red-600"><X size={20}/></button></td></tr>))}</tbody></table>) : (<div className="h-full flex items-center justify-center text-slate-300 font-bold opacity-30">清單目前為空</div>)}</div>
              {issuanceMode === 'OUT' && (<div className="grid grid-cols-2 gap-6 mb-6"><div><label className="text-xs font-black text-slate-500 uppercase">領用部門</label><select className="w-full p-3 rounded-xl mt-2 text-black font-bold" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>{DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}</select></div><div><label className="text-xs font-black text-slate-500 uppercase">領用人</label><input type="text" className="w-full p-3 rounded-xl mt-2 text-black font-bold" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div><div className="col-span-2"><label className="text-xs font-black text-slate-500 uppercase">用途說明</label><input type="text" className="w-full p-3 rounded-xl mt-2 text-black font-bold" value={inputReason} onChange={e=>setInputReason(e.target.value)}/></div></div>)}
              <button onClick={processIssuance} disabled={basket.length === 0} className={`w-full py-6 rounded-2xl font-black text-3xl shadow-2xl transition-all active:scale-95 text-white ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>{issuanceMode === 'OUT' ? '確認領用' : '確認入庫'}</button>
            </div>
          </div>
        )}

        {showSettings && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[600] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl animate-in zoom-in duration-300">
              <h3 className="text-2xl font-black text-black mb-6">雲端智慧同步設定</h3>
              <p className="text-slate-500 mb-4 font-bold text-sm">此模式會自動合併多台電腦的資料，避免互相覆蓋。</p>
              <input type="text" className="w-full p-4 rounded-xl mt-2 text-black font-bold border-2" placeholder="GAS URL" defaultValue={gasUrl} id="gas-url-input"/>
              <div className="flex gap-4 mt-8"><button onClick={() => handleGasUrlSave((document.getElementById('gas-url-input') as HTMLInputElement).value)} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl">儲存並啟動智慧同步</button><button onClick={() => setShowSettings(false)} className="px-8 py-5 bg-slate-100 text-slate-600 rounded-2xl font-black text-xl">取消</button></div>
            </div>
          </div>
        )}

        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl animate-in zoom-in duration-300">
              <form className="space-y-6" onSubmit={handleSaveItem}>
                <h3 className="text-2xl font-black text-black mb-4">{editTarget ? '編輯項目' : '新增項目'}</h3>
                <div><label className="text-xs font-black text-slate-500 uppercase">物資名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.name} /></div>
                <div className="grid grid-cols-2 gap-6"><div><label className="text-xs font-black text-slate-500">分類</label><select name="itemType" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="EQUIPMENT">安全衛生設備</option><option value="CONSUMABLE">安全衛生類消耗品</option></select></div><div><label className="text-xs font-black text-slate-500">規範 (序號)</label><input name="spec" type="text" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.spec || ''} /></div></div>
                <div className="grid grid-cols-3 gap-6"><div><label className="text-xs font-black text-slate-500">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.unit || '個'} /></div><div><label className="text-xs font-black text-slate-500">目前庫存</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.quantity || 0} /></div><div><label className="text-xs font-black text-slate-500">警戒數量</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.minStock || 5} /></div></div>
                {(activeTab === 'medicine' || editTarget?.itemGroup === 'MEDICINE') && (<div className="grid grid-cols-2 gap-6"><div><label className="text-xs font-black text-slate-500">購入日期</label><input name="purchaseDate" type="date" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.purchaseDate} /></div><div><label className="text-xs font-black text-slate-500">有效日期</label><input name="expiryDate" type="date" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.expiryDate} /></div></div>)}
                <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-2xl shadow-xl mt-6">儲存物資</button>
                <button type="button" onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="w-full py-3 text-slate-400 font-bold hover:text-black">取消返回</button>
              </form>
            </div>
          </div>
        )}

        {showPrintModal && lastTransactionBatch && (
          <div className="fixed inset-0 bg-slate-900/95 z-[500] flex flex-col items-center justify-center p-6">
            <div className="bg-white rounded-[3rem] w-full max-w-5xl h-[90vh] shadow-2xl flex flex-col overflow-hidden animate-in fade-in zoom-in duration-300">
              <div className="p-8 flex justify-between items-center border-b bg-white relative z-10 shadow-sm"><div className="flex items-center gap-4"><CheckCircle2 className="text-emerald-500" size={40}/><h3 className="font-black text-2xl text-black">領用單據生成預覽</h3></div><div className="flex gap-4"><button onClick={() => { 
                const printWin = window.open('', '_blank');
                if (!printWin) return;
                printWin.document.write(`<html><head><title>領用單</title><style>@font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); } body { font-family: 'StandardKai', serif; padding: 60px; color: black; } table { width:100%; border-collapse:collapse; border:2px solid black; } th, td { border:1px solid black; padding:8px; text-align:center; }</style></head><body><h1 style="text-align:center">台灣電力公司電力修護處南部分處</h1><div style="text-align:right">單號：${lastTransactionBatch.id}</div><div style="margin:20px 0">部門：${lastTransactionBatch.dept}</div><table><thead><tr><th>名稱</th><th>規範</th><th>數量</th></tr></thead><tbody>${lastTransactionBatch.items.map(it=>`<tr><td>${it.name}</td><td>${it.spec}</td><td>${it.quantity}</td></tr>`).join('')}</tbody></table><script>window.onload=()=>{window.print();window.close();};</script></body></html>`);
                printWin.document.close();
              }} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xl shadow-xl flex items-center gap-2"><Printer size={24}/> 直接列印</button><button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-2xl text-black hover:bg-slate-200"><X size={32}/></button></div></div>
              <div className="flex-1 bg-slate-100 p-10 flex justify-center overflow-y-auto"><div className="bg-white shadow-2xl p-10 w-[210mm] min-h-[297mm] text-black">預覽載入中...</div></div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  Stethoscope,
  ShoppingCart,
  CheckCircle2,
  Users,
  Download,
  Upload,
  Settings,
  RefreshCw,
  Clock,
  TrendingUp,
  BarChart3,
  Calendar,
  List,
  Zap,
  ArrowUp,
  ArrowDown,
  ArrowUpDown
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell 
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

const CHART_COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

type SyncStatus = 'synced' | 'syncing' | 'error' | 'local';
type SortKey = 'name' | 'quantity' | 'expiryDate' | 'lastUpdated';
type SortOrder = 'asc' | 'desc';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');
  const [syncStatus, setSyncStatus] = useState<SyncStatus>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '從未同步');
  const [showSettings, setShowSettings] = useState(false);

  const [sortConfig, setSortConfig] = useState<{ key: SortKey; order: SortOrder }>({ key: 'lastUpdated', order: 'desc' });
  const [statsDeptFilter, setStatsDeptFilter] = useState<string>('ALL');
  const [statsYearFilter, setStatsYearFilter] = useState<number>(new Date().getFullYear());
  const [lastTransactionBatch, setLastTransactionBatch] = useState<{ id: string; dept: string; person: string; reason: string; items: BasketItem[]; timestamp: number; } | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{id: string, name: string} | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceSearch, setIssuanceSearch] = useState('');
  const [isIssuanceDropdownOpen, setIsIssuanceDropdownOpen] = useState(false);
  const issuanceDropdownRef = useRef<HTMLDivElement>(null);
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- 數據統計計算 (修復看板) ---
  const stats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    const medItems = items.filter(i => i.itemGroup === 'MEDICINE');
    const filteredLogs = logs.filter(l => {
        const logDate = new Date(l.timestamp);
        return l.type === 'OUT' && logDate.getFullYear() === statsYearFilter && (statsDeptFilter === 'ALL' || l.dept === statsDeptFilter);
    });

    const invDetailMap: Record<string, {name: string, qty: number}> = {};
    let fInvQty = 0;
    let fMedQty = 0;

    filteredLogs.forEach(log => {
        const item = items.find(it => it.id === log.itemId);
        if (item?.itemGroup === 'MEDICINE') { 
          fMedQty += log.quantity;
        } else { 
          fInvQty += log.quantity; 
          if (!invDetailMap[log.itemId]) invDetailMap[log.itemId] = { name: log.itemName, qty: 0 }; 
          invDetailMap[log.itemId].qty += log.quantity; 
        }
    });

    const invDetails = Object.values(invDetailMap).sort((a, b) => b.qty - a.qty);
    const deptRanking = Object.entries(logs.filter(l => l.type === 'OUT' && new Date(l.timestamp).getFullYear() === statsYearFilter).reduce((acc: any, curr) => { 
      acc[curr.dept] = (acc[curr.dept] || 0) + curr.quantity; 
      return acc; 
    }, {})).sort((a: any, b: any) => b[1] - a[1]);

    return { 
      sys: { invTotal: invItems.length, medTotal: medItems.length }, 
      filtered: { 
        invQty: fInvQty, 
        medQty: fMedQty, 
        invDetails, 
        logs: filteredLogs, 
        chartData: invDetails.slice(0, 8).map(d => ({ name: d.name, value: d.qty })) 
      }, 
      deptRanking 
    };
  }, [items, logs, statsDeptFilter, statsYearFilter]);

  // --- 核心邏輯：修復導入 ---
  const generateId = () => `ID-${Math.random().toString(36).substr(2, 9)}-${Date.now().toString().slice(-4)}`;

  const sanitizeImportItems = (rawItems: any[]): InventoryItem[] => {
    const now = Date.now();
    return rawItems.map(item => ({
      id: item.id || generateId(),
      name: item.name || "未命名項目",
      category: item.category || Category.OTHER,
      itemType: item.itemType || 'CONSUMABLE',
      itemGroup: item.itemGroup || 'INVENTORY',
      unit: item.unit || '個',
      spec: item.spec || '',
      quantity: Number(item.quantity) || 0,
      minStock: Number(item.minStock) || 5,
      purchaseDate: item.purchaseDate || '',
      expiryDate: item.expiryDate || '',
      description: item.description || '',
      lastUpdated: item.lastUpdated || now
    }));
  };

  useEffect(() => {
    const initLoad = async () => {
      const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
      const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);

      let initialItems: InventoryItem[] = [];
      let initialLogs: Transaction[] = [];

      if (savedItems) { 
        try { 
          const p = JSON.parse(savedItems); 
          if (Array.isArray(p)) {
            initialItems = sanitizeImportItems(p);
          }
        } catch (e) {} 
      }
      if (savedLogs) { 
        try { 
          const p = JSON.parse(savedLogs); 
          if (Array.isArray(p)) initialLogs = p; 
        } catch (e) {} 
      }

      setItems(initialItems);
      setLogs(initialLogs);
      setIsLoaded(true);

      if (gasUrl) { 
        setSyncStatus('local'); 
      }
    };
    initLoad();

    const handleClickOutside = (event: MouseEvent) => {
      if (issuanceDropdownRef.current && !issuanceDropdownRef.current.contains(event.target as Node)) {
        setIsIssuanceDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const exportData = () => {
    const data = { items, logs, timestamp: Date.now() };
    const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `工安管理備份_${new Date().toLocaleDateString().replace(/\//g, '-')}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const importData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const rawData = JSON.parse(event.target?.result as string);
        let importItems: any[] = [];
        let importLogs: any[] = [];

        // 兼容多種格式：{items: [], logs: []} 或 單純陣列 []
        if (Array.isArray(rawData)) {
          importItems = rawData;
        } else if (rawData && rawData.items && Array.isArray(rawData.items)) {
          importItems = rawData.items;
          importLogs = rawData.logs || [];
        }

        if (importItems.length > 0) {
          if (window.confirm(`偵測到 ${importItems.length} 個品項，是否執行導入並與現有資料合併？`)) {
            const sanitized = sanitizeImportItems(importItems);

            // 智慧合併：以 ID 為準，保留最新的
            const mergedMap = new Map<string, InventoryItem>();
            items.forEach(i => mergedMap.set(i.id, i));
            sanitized.forEach(i => {
              const existing = mergedMap.get(i.id);
              if (!existing || i.lastUpdated >= (existing.lastUpdated || 0)) {
                mergedMap.set(i.id, i);
              }
            });

            const finalItems = Array.from(mergedMap.values());
            setItems(finalItems);

            if (importLogs.length > 0) {
              const logMap = new Map<string, Transaction>();
              logs.forEach(l => logMap.set(l.id, l));
              importLogs.forEach(l => logMap.set(l.id, l));
              setLogs(Array.from(logMap.values()).sort((a, b) => b.timestamp - a.timestamp));
            }

            window.alert("✅ 資料導入並合併完成！");
          }
        } else {
          window.alert("❌ JSON 檔案內沒有找到有效的品項資料。");
        }
      } catch (err) { 
        window.alert("❌ 檔案讀取失敗，請確認是否為有效的 JSON 格式。"); 
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  // --- 其他邏輯 ---
  const getReservedQty = (itemId: string) => basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);

  const frequentItems = useMemo(() => {
    const counts: Record<string, number> = {};
    logs.filter(l => l.type === 'OUT').forEach(l => { counts[l.itemId] = (counts[l.itemId] || 0) + 1; });
    return Object.entries(counts)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5)
      .map(([id]) => items.find(i => i.id === id))
      .filter((i): i is InventoryItem => !!i && i.itemGroup === issuanceGroup);
  }, [logs, items, issuanceGroup]);

  const filteredIssuanceItems = useMemo(() => {
    return items.filter(i => i.itemGroup === issuanceGroup && (i.name.toLowerCase().includes(issuanceSearch.toLowerCase()) || i.spec.toLowerCase().includes(issuanceSearch.toLowerCase())));
  }, [items, issuanceGroup, issuanceSearch]);

  const managedItems = useMemo(() => {
    const filtered = items.filter(i => (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase()));
    return filtered.sort((a, b) => {
      let valA: any = a[sortConfig.key] || '';
      let valB: any = b[sortConfig.key] || '';
      if (sortConfig.key === 'quantity') { valA = Number(valA); valB = Number(valB); } 
      else if (sortConfig.key === 'expiryDate') { valA = valA ? new Date(valA).getTime() : 0; valB = valB ? new Date(valB).getTime() : 0; }
      if (valA < valB) return sortConfig.order === 'asc' ? -1 : 1;
      if (valA > valB) return sortConfig.order === 'asc' ? 1 : -1;
      return 0;
    });
  }, [items, activeTab, searchTerm, sortConfig]);

  return (
    <div className="min-h-screen flex bg-slate-100 text-black font-sans">
      <style>{`
        input, select, textarea { color: #000000 !important; background-color: #ffffff !important; border: 2px solid #94a3b8 !important; font-weight: 700 !important; }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
      `}</style>
      <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={importData} />

      {/* 側邊欄 */}
      <aside className="w-72 bg-slate-900 text-white p-6 flex flex-col shrink-0 border-r border-slate-800 shadow-2xl">
        <div className="flex flex-col gap-1 mb-8">
          <div className="flex items-center gap-3"><div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22} className="text-white"/></div><h1 className="font-black text-xl tracking-tight text-white">工安管理系統</h1></div>
          <div className="mt-6 bg-slate-800/50 rounded-2xl p-4 border border-slate-700/50">
            <div className="flex items-center justify-between mb-2"><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">系統模式</span><div className="w-3 h-3 rounded-full bg-orange-400"></div></div>
            <div className="text-sm font-black text-white mb-1">本地離線模式</div>
            <div className="flex items-center gap-1.5 text-[10px] text-slate-400 font-bold"><Clock size={10}/> 資料存於此瀏覽器</div>
          </div>
        </div>
        <nav className="flex-1 space-y-1">
          {[ 
            { id: 'inventory', label: '工安耗材管理', icon: Package }, 
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope }, 
            { id: 'issuance', label: '領用補貨作業', icon: FileText }, 
            { id: 'history', label: '歷史異動日誌', icon: History }, 
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard }, 
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}><tab.icon size={20} /> {tab.label}</button>
          ))}
        </nav>
        <div className="pt-6 mt-6 border-t border-slate-800 space-y-2">
            <button onClick={exportData} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><Download size={16}/> 匯出備份 (JSON)</button>
            <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><Upload size={16}/> 導入合併備份</button>
        </div>
      </aside>

      {/* 主內容區 */}
      <main className="flex-1 p-10 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-3xl font-black text-black">
            {activeTab === 'inventory' ? '工安耗材清冊' : 
             activeTab === 'medicine' ? '急救藥材清冊' : 
             activeTab === 'issuance' ? '領用 / 補貨登記' : 
             activeTab === 'history' ? '歷史異動日誌' : '數據統計看板'}
          </h2>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-black shadow-xl"><Plus size={18}/> 新增項目</button>
          )}
        </header>

        {/* 數據看板 */}
        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-200 flex flex-wrap items-center gap-6">
              <div className="flex items-center gap-2"><label className="text-xs font-black text-slate-400">年度</label><select className="p-2 rounded-lg text-sm font-bold text-black border-2 border-slate-300" value={statsYearFilter} onChange={e => setStatsYearFilter(Number(e.target.value))}><option value={2025}>2025</option><option value={2024}>2024</option></select></div>
              <div className="flex items-center gap-2"><label className="text-xs font-black text-slate-400">部門</label><select className="p-2 rounded-lg text-sm font-bold text-black border-2 border-slate-300" value={statsDeptFilter} onChange={e => setStatsDeptFilter(e.target.value)}><option value="ALL">全廠</option>{DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}</select></div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              <div className="bg-slate-900 p-8 rounded-[2rem] text-white shadow-xl flex flex-col justify-between">
                <div><p className="text-blue-400 text-xs font-black uppercase">年度總領用</p><h3 className="text-5xl font-black mt-2">{stats.filtered.invQty + stats.filtered.medQty}</h3></div>
                <TrendingUp className="text-blue-500 mt-4" size={32}/>
              </div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-blue-500"><p className="text-slate-400 text-xs font-black uppercase">工安耗材</p><h3 className="text-4xl font-black mt-2 text-blue-600">{stats.filtered.invQty} <span className="text-sm font-bold text-slate-400">件</span></h3></div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-emerald-500"><p className="text-slate-400 text-xs font-black uppercase">急救藥材</p><h3 className="text-4xl font-black mt-2 text-emerald-600">{stats.filtered.medQty} <span className="text-sm font-bold text-slate-400">件</span></h3></div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-orange-500"><p className="text-slate-400 text-xs font-black uppercase">低庫存項目</p><h3 className="text-4xl font-black mt-2 text-orange-600">{items.filter(i => i.quantity <= i.minStock).length} <span className="text-sm font-bold text-slate-400">項</span></h3></div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 bg-white p-8 rounded-[2.5rem] shadow-lg min-h-[400px]">
                <h4 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><BarChart3 className="text-blue-500"/> 熱門領用品項分析</h4>
                <div className="h-80">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={stats.filtered.chartData}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                      <XAxis dataKey="name" tick={{ fontSize: 12, fontWeight: 700 }} />
                      <YAxis tick={{ fontSize: 12, fontWeight: 700 }} />
                      <Tooltip />
                      <Bar dataKey="value" radius={[8, 8, 0, 0]} barSize={40}>
                        {stats.filtered.chartData.map((_, index) => ( <Cell key={`cell-${index}`} fill={CHART_COLORS[index % CHART_COLORS.length]} /> ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
              <div className="bg-white p-8 rounded-[2.5rem] shadow-lg flex flex-col">
                <h4 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><Users className="text-slate-600"/> 部門領用排行</h4>
                <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
                  {stats.deptRanking.map(([dept, count]: any, idx) => (
                    <div key={dept} className="flex items-center gap-4 bg-slate-50 p-4 rounded-2xl">
                      <div className="w-8 h-8 flex items-center justify-center rounded-xl bg-slate-900 text-white text-xs font-black">{idx + 1}</div>
                      <div className="flex-1 font-bold">{dept}</div>
                      <div className="font-black text-blue-600">{count} 件</div>
                    </div>
                  ))}
                  {stats.deptRanking.length === 0 && <div className="text-center text-slate-300 py-10 font-bold">目前無領用記錄</div>}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* 庫存列表 (耗材/藥材) */}
        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-200">
            <div className="p-6 bg-slate-50 border-b flex items-center justify-between">
              <div className="relative max-w-sm w-full"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="搜尋項目名稱..." className="w-full pl-12 pr-4 py-3 rounded-xl font-bold text-black border-2 border-slate-300" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} /></div>
              <div className="text-xs font-bold text-slate-400">目前顯示：{managedItems.length} 個品項</div>
            </div>
            <table className="w-full text-left">
              <thead className="bg-slate-100 text-[11px] font-black text-slate-500 uppercase border-b">
                <tr><th className="px-8 py-5">名稱及規格</th><th className="px-8 py-5 text-center">目前庫存</th>{activeTab === 'medicine' && (<th className="px-8 py-5 text-center">有效期限</th>)}<th className="px-8 py-5 text-right">操作</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {managedItems.map(item => (<tr key={item.id} className="hover:bg-slate-50"><td className="px-8 py-5"><div className="font-black text-black">{item.name}</div><div className="flex items-center gap-2 mt-1"><span className={`text-[10px] px-2 py-0.5 rounded font-black border ${item.itemType === 'EQUIPMENT' ? 'text-blue-600 border-blue-200' : 'text-slate-500 border-slate-200'}`}>{item.itemType === 'EQUIPMENT' ? '設備' : '耗材'}</span><span className="text-xs text-slate-400 font-bold">{item.spec || '無規格'}</span></div></td><td className="px-8 py-5 text-center"><span className={`px-6 py-2 rounded-xl font-black text-xl border-2 ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600 border-red-200' : 'bg-emerald-50 text-emerald-600 border-emerald-100'}`}>{item.quantity} {item.unit}</span></td>{activeTab === 'medicine' && (<td className="px-8 py-5 text-center"><div className={`text-sm font-black flex items-center justify-center gap-1.5 ${new Date(item.expiryDate || '') < new Date() ? 'text-red-600' : 'text-emerald-600'}`}><Calendar size={14}/> {item.expiryDate?.replace(/-/g, '/') || '未填'}</div></td>)}<td className="px-8 py-5 text-right"><button onClick={() => setEditTarget(item)} className="p-2 text-slate-400 hover:text-blue-600"><Edit3 size={20}/></button><button onClick={() => { if(window.confirm('確定刪除？')) setItems(prev => prev.filter(i=>i.id !== item.id)); }} className="p-2 text-slate-400 hover:text-red-600"><Trash2 size={20}/></button></td></tr>))}
              </tbody>
            </table>
          </div>
        )}

        {/* 領用/補貨邏輯省略大部分不變，僅確保 UI 顯示一致... */}
        {activeTab === 'issuance' && (
          <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
            <div className="lg:col-span-2 bg-white p-8 rounded-3xl shadow-xl border border-slate-200">
              <h3 className="text-xl font-black mb-8 flex items-center gap-2 text-black"><ShoppingCart className="text-blue-500"/> 1. 挑選項目</h3>
              <div className="flex bg-slate-100 p-1 rounded-xl mb-6"><button onClick={()=>{setIssuanceMode('OUT'); setBasket([]);}} className={`flex-1 py-3 rounded-lg font-black transition-all ${issuanceMode==='OUT'?'bg-white shadow text-blue-600':'text-slate-400'}`}>領用出庫</button><button onClick={()=>{setIssuanceMode('IN'); setBasket([]);}} className={`flex-1 py-3 rounded-lg font-black transition-all ${issuanceMode==='IN'?'bg-white shadow text-emerald-600':'text-slate-400'}`}>補貨入庫</button></div>
              <div className="space-y-6">
                <div><label className="text-xs font-black text-slate-500 uppercase tracking-widest">分類</label><div className="flex gap-2 mt-2"><button onClick={()=>{setIssuanceGroup('INVENTORY'); setIssuanceSearch(''); setSelectedItemId('');}} className={`flex-1 py-3 rounded-xl font-black border-2 ${issuanceGroup==='INVENTORY'?'bg-blue-50 border-blue-500 text-blue-600':'bg-white border-slate-200 text-slate-400'}`}>耗材類</button><button onClick={()=>{setIssuanceGroup('MEDICINE'); setIssuanceSearch(''); setSelectedItemId('');}} className={`flex-1 py-3 rounded-xl font-black border-2 ${issuanceGroup==='MEDICINE'?'bg-emerald-50 border-emerald-500 text-emerald-600':'bg-white border-slate-200 text-slate-400'}`}>藥材類</button></div></div>
                <div className="space-y-4">
                    <label className="text-xs font-black text-slate-500 uppercase tracking-widest mb-2 block">品項選取 (顏色提示庫存)</label>
                    <div className="relative" ref={issuanceDropdownRef}>
                      {isIssuanceDropdownOpen && (
                        <div className="absolute bottom-full left-0 right-0 mb-2 bg-white rounded-2xl shadow-2xl border border-slate-200 z-[100] max-h-96 overflow-y-auto custom-scrollbar">
                          {issuanceSearch === '' && frequentItems.length > 0 && (<div className="p-2 border-b bg-blue-50/30"><p className="px-3 py-1 text-[10px] font-black text-blue-600 uppercase">常用建議</p><div className="grid grid-cols-1 gap-1 mt-1">{frequentItems.map(item => { const remaining = item.quantity - getReservedQty(item.id); const isCritical = remaining <= item.minStock || remaining <= 0; return (<button key={item.id} onClick={() => { setSelectedItemId(item.id); setIssuanceSearch(item.name); setIsIssuanceDropdownOpen(false); }} className="w-full text-left p-3 hover:bg-blue-100 rounded-lg flex justify-between items-center transition-colors"><div><span className="font-black text-slate-900">{item.name}</span></div><span className={`text-[10px] font-black px-2 py-0.5 rounded border ${isCritical ? 'text-red-600 bg-red-50' : 'text-emerald-600 bg-emerald-50'}`}>剩: {remaining}</span></button>);})}</div></div>)}
                          <div className="p-1">{filteredIssuanceItems.map(item => { const remaining = item.quantity - getReservedQty(item.id); const isCritical = remaining <= item.minStock || remaining <= 0; return (<button key={item.id} onClick={() => { setSelectedItemId(item.id); setIssuanceSearch(item.name); setIsIssuanceDropdownOpen(false); }} className="w-full text-left p-4 hover:bg-slate-50 rounded-xl flex flex-col gap-1 border-b border-slate-50 last:border-0"><div className="flex justify-between items-start"><span className="font-black text-black text-lg">{item.name}</span><span className={`text-xs font-black px-2 py-0.5 rounded ${isCritical ? 'text-red-600 bg-red-50' : 'text-emerald-600 bg-emerald-50'}`}>剩餘: {remaining} {item.unit}</span></div></button>);})}</div>
                        </div>
                      )}
                      <div className="relative"><input type="text" placeholder="搜尋項目名稱..." className="w-full p-4 pr-12 rounded-xl text-lg font-bold border-2" value={selectedItemId ? items.find(i=>i.id===selectedItemId)?.name : issuanceSearch} onChange={(e) => { setIssuanceSearch(e.target.value); setSelectedItemId(''); setIsIssuanceDropdownOpen(true); }} onFocus={() => setIsIssuanceDropdownOpen(true)} /><div className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"><Search size={20}/></div></div>
                    </div>
                </div>
                <div><label className="text-xs font-black text-slate-500 uppercase tracking-widest">數量</label><input type="number" min="1" className="w-full p-4 rounded-xl mt-2 text-xl font-bold" value={inputQty} onChange={e=>setInputQty(e.target.value)}/></div>
                <button onClick={()=>{ if (!selectedItemId) return; const targetItem = items.find(i => i.id === selectedItemId); if (!targetItem) return; setBasket(prev => [...prev, { itemId: targetItem.id, name: targetItem.name, quantity: Number(inputQty), unit: targetItem.unit, spec: targetItem.spec, itemType: targetItem.itemType }]); setSelectedItemId(''); setIssuanceSearch(''); }} disabled={!selectedItemId} className={`w-full py-5 rounded-2xl font-black text-xl flex items-center justify-center gap-2 shadow-lg transition-all ${!selectedItemId ? 'bg-slate-200 text-slate-400' : 'bg-slate-900 text-white hover:bg-black'}`}><Plus size={20}/> 加入處理清單</button>
              </div>
            </div>

            <div className="lg:col-span-3 bg-white p-8 rounded-3xl shadow-xl border border-slate-200 flex flex-col">
              <h3 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><FileText className="text-emerald-500"/> 2. 待處理作業</h3>
              <div className="flex-1 overflow-y-auto border-2 border-dashed border-slate-100 rounded-2xl mb-6 min-h-[250px] bg-slate-50">{basket.length > 0 ? (<table className="w-full text-left"><tbody className="divide-y divide-slate-100">{basket.map((b, idx) => (<tr key={idx} className="bg-white"><td className="px-6 py-5 font-black text-black">{b.name}</td><td className="px-6 py-5 text-center font-black text-blue-700">{b.quantity} {b.unit}</td><td className="px-6 py-5 text-right"><button onClick={()=>setBasket(prev => prev.filter((_, i) => i !== idx))} className="text-slate-300 hover:text-red-600"><X size={20}/></button></td></tr>))}</tbody></table>) : (<div className="h-full flex items-center justify-center text-slate-300 font-bold opacity-30">清單目前為空</div>)}</div>
              {issuanceMode === 'OUT' && (<div className="grid grid-cols-2 gap-6 mb-6"><div><label className="text-xs font-black text-slate-500 uppercase">部門</label><select className="w-full p-3 rounded-xl mt-2 font-bold" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>{DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}</select></div><div><label className="text-xs font-black text-slate-500 uppercase">領用人</label><input type="text" className="w-full p-3 rounded-xl mt-2 font-bold" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div><div className="col-span-2"><label className="text-xs font-black text-slate-500 uppercase">用途</label><input type="text" className="w-full p-3 rounded-xl mt-2 font-bold" value={inputReason} onChange={e=>setInputReason(e.target.value)}/></div></div>)}
              <button onClick={()=>{
                const timestamp = Date.now();
                const newLogs: Transaction[] = [];
                let updated = [...items];
                basket.forEach(b => {
                  updated = updated.map(i => i.id === b.itemId ? { ...i, quantity: issuanceMode==='IN' ? i.quantity+b.quantity : i.quantity-b.quantity, lastUpdated: timestamp } : i);
                  newLogs.push({ id: generateId(), itemId: b.itemId, itemName: b.name, type: issuanceMode, quantity: b.quantity, person: inputPerson||'未填', dept: selectedDept, reason: inputReason, timestamp: timestamp, spec: b.spec });
                });
                setItems(updated);
                setLogs([...newLogs, ...logs]);
                setBasket([]); window.alert('✅ 操作成功！');
              }} disabled={basket.length === 0} className={`w-full py-6 rounded-2xl font-black text-3xl shadow-2xl transition-all active:scale-95 text-white ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>{issuanceMode === 'OUT' ? '確認領用' : '確認入庫'}</button>
            </div>
          </div>
        )}

        {/* 歷史紀錄與彈窗部分邏輯保持，主要修復了 AddModal 與 EditModal 的 ID 問題 */}
        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl animate-in zoom-in duration-300">
              <form className="space-y-6" onSubmit={(e) => {
                e.preventDefault();
                const formData = new FormData(e.currentTarget);
                const data = { 
                  name: formData.get('name') as string, 
                  itemType: formData.get('itemType') as ItemType, 
                  unit: formData.get('unit') as string, 
                  spec: formData.get('spec') as string, 
                  purchaseDate: formData.get('purchaseDate') as string, 
                  expiryDate: formData.get('expiryDate') as string, 
                  quantity: Number(formData.get('quantity')), 
                  minStock: Number(formData.get('minStock')), 
                };
                const timestamp = Date.now();
                if (editTarget) {
                  setItems(items.map(i => i.id === editTarget.id ? { ...editTarget, ...data, lastUpdated: timestamp } : i));
                  setEditTarget(null);
                } else {
                  setItems([...items, { id: generateId(), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: timestamp }]);
                  setShowAddModal(false);
                }
              }}>
                <h3 className="text-2xl font-black mb-4">{editTarget ? '編輯項目' : '新增項目'}</h3>
                <div><label className="text-xs font-black text-slate-500 uppercase">名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.name} /></div>
                <div className="grid grid-cols-2 gap-6"><div><label className="text-xs font-black text-slate-500">分類</label><select name="itemType" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="EQUIPMENT">設備</option><option value="CONSUMABLE">消耗品</option></select></div><div><label className="text-xs font-black text-slate-500">規格</label><input name="spec" type="text" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.spec || ''} /></div></div>
                <div className="grid grid-cols-3 gap-6"><div><label className="text-xs font-black text-slate-500">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.unit || '個'} /></div><div><label className="text-xs font-black text-slate-500">庫存</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.quantity || 0} /></div><div><label className="text-xs font-black text-slate-500">警報量</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.minStock || 5} /></div></div>
                <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-2xl shadow-xl mt-6">儲存</button>
                <button type="button" onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="w-full py-3 text-slate-400 font-bold hover:text-black">取消</button>
              </form>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  Stethoscope,
  ShoppingCart,
  CheckCircle2,
  Users,
  Download,
  Upload,
  Settings,
  RefreshCw,
  Clock,
  TrendingUp,
  BarChart3,
  Calendar,
  List,
  Zap
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell 
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

const CHART_COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

type SyncStatus = 'synced' | 'syncing' | 'error' | 'local';
type SortKey = 'name' | 'quantity' | 'expiryDate' | 'lastUpdated';
type SortOrder = 'asc' | 'desc';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');
  const [syncStatus, setSyncStatus] = useState<SyncStatus>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '從未同步');
  const [showSettings, setShowSettings] = useState(false);

  const [sortConfig, setSortConfig] = useState<{ key: SortKey; order: SortOrder }>({ key: 'lastUpdated', order: 'desc' });
  const [statsDeptFilter, setStatsDeptFilter] = useState<string>('ALL');
  const [statsYearFilter, setStatsYearFilter] = useState<number>(new Date().getFullYear());
  const [lastTransactionBatch, setLastTransactionBatch] = useState<{ id: string; dept: string; person: string; reason: string; items: BasketItem[]; timestamp: number; } | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceSearch, setIssuanceSearch] = useState('');
  const [isIssuanceDropdownOpen, setIsIssuanceDropdownOpen] = useState(false);
  const issuanceDropdownRef = useRef<HTMLDivElement>(null);
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- 數據統計分析 ---
  const stats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    const medItems = items.filter(i => i.itemGroup === 'MEDICINE');
    const filteredLogs = logs.filter(l => {
        const logDate = new Date(l.timestamp);
        return l.type === 'OUT' && logDate.getFullYear() === statsYearFilter && (statsDeptFilter === 'ALL' || l.dept === statsDeptFilter);
    });

    const invDetailMap: Record<string, {name: string, qty: number}> = {};
    let fInvQty = 0;
    let fMedQty = 0;

    filteredLogs.forEach(log => {
        const item = items.find(it => it.id === log.itemId);
        if (item?.itemGroup === 'MEDICINE') { 
          fMedQty += log.quantity;
        } else { 
          fInvQty += log.quantity; 
          if (!invDetailMap[log.itemId]) invDetailMap[log.itemId] = { name: log.itemName, qty: 0 }; 
          invDetailMap[log.itemId].qty += log.quantity; 
        }
    });

    const invDetails = Object.values(invDetailMap).sort((a, b) => b.qty - a.qty);
    const deptRanking = Object.entries(logs.filter(l => l.type === 'OUT' && new Date(l.timestamp).getFullYear() === statsYearFilter).reduce((acc: any, curr) => { 
      acc[curr.dept] = (acc[curr.dept] || 0) + curr.quantity; 
      return acc; 
    }, {})).sort((a: any, b: any) => b[1] - a[1]);

    return { 
      sys: { invTotal: invItems.length, medTotal: medItems.length }, 
      filtered: { 
        invQty: fInvQty, 
        medQty: fMedQty, 
        invDetails, 
        logs: filteredLogs, 
        chartData: invDetails.slice(0, 8).map(d => ({ name: d.name, value: d.qty })) 
      }, 
      deptRanking 
    };
  }, [items, logs, statsDeptFilter, statsYearFilter]);

  // --- 核心邏輯：ID 生成與資料清洗 ---
  const generateId = () => `ID-${Math.random().toString(36).substr(2, 9)}-${Date.now().toString().slice(-4)}`;

  const sanitizeItem = (item: any): InventoryItem => {
    const now = Date.now();
    return {
      id: item.id || generateId(),
      name: item.name || "未命名項目",
      category: item.category || Category.OTHER,
      itemType: item.itemType || 'CONSUMABLE',
      itemGroup: item.itemGroup || 'INVENTORY',
      unit: item.unit || '個',
      spec: item.spec || '',
      quantity: Number(item.quantity) || 0,
      minStock: Number(item.minStock) || 5,
      purchaseDate: item.purchaseDate || '',
      expiryDate: item.expiryDate || '',
      description: item.description || '',
      lastUpdated: item.lastUpdated || now
    };
  };

  // 智慧合併邏輯：這就是解決時間差衝突的核心
  const smartMerge = (local: InventoryItem[], incoming: InventoryItem[]): InventoryItem[] => {
    const mergedMap = new Map<string, InventoryItem>();
    local.forEach(i => mergedMap.set(i.id, i));
    incoming.forEach(inc => {
      const sanitized = sanitizeItem(inc);
      const existing = mergedMap.get(sanitized.id);
      // 如果本地沒這筆，或者傳入的資料更新時間「大於等於」本地，則採納傳入的
      if (!existing || sanitized.lastUpdated >= (existing.lastUpdated || 0)) {
        mergedMap.set(sanitized.id, sanitized);
      }
    });
    return Array.from(mergedMap.values());
  };

  // --- 初始化載入 ---
  useEffect(() => {
    const initLoad = async () => {
      const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
      const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);

      let initialItems: InventoryItem[] = [];
      let initialLogs: Transaction[] = [];

      if (savedItems) { 
        try { 
          const p = JSON.parse(savedItems); 
          if (Array.isArray(p)) initialItems = p.map(sanitizeItem);
        } catch (e) {} 
      }
      if (savedLogs) { 
        try { 
          const p = JSON.parse(savedLogs); 
          if (Array.isArray(p)) initialLogs = p; 
        } catch (e) {} 
      }

      setItems(initialItems);
      setLogs(initialLogs);
      setIsLoaded(true);

      if (gasUrl) { 
        handleCloudSync(initialItems, initialLogs);
      }
    };
    initLoad();

    const handleClickOutside = (event: MouseEvent) => {
      if (issuanceDropdownRef.current && !issuanceDropdownRef.current.contains(event.target as Node)) {
        setIsIssuanceDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  // --- 雲端同步邏輯 ---
  const handleCloudSync = async (currentItems: InventoryItem[] = items, currentLogs: Transaction[] = logs) => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const response = await fetch(gasUrl);
      const remoteData = await response.json();

      let finalItems = currentItems;
      let finalLogs = currentLogs;

      if (remoteData && remoteData.items) {
        // 使用智慧合併處理雲端傳回的資料
        finalItems = smartMerge(currentItems, remoteData.items);
        // 日誌則採簡單合併並去重
        const logMap = new Map<string, Transaction>();
        [...currentLogs, ...(remoteData.logs || [])].forEach(l => logMap.set(l.id, l));
        finalLogs = Array.from(logMap.values()).sort((a, b) => b.timestamp - a.timestamp);

        setItems(finalItems);
        setLogs(finalLogs);
      }

      // 將合併後的結果推回雲端
      const payload = { items: finalItems, logs: finalLogs, timestamp: Date.now() };
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify(payload), mode: 'no-cors' });

      setSyncStatus('synced');
      const nowTime = new Date().toLocaleString('zh-TW', { hour12: false });
      setLastSyncTime(nowTime);
      localStorage.setItem(STORAGE_KEY_LAST_SYNC, nowTime);
    } catch (err) {
      setSyncStatus('error');
    }
  };

  // --- 匯出匯入 ---
  const exportData = () => {
    const data = { items, logs, timestamp: Date.now() };
    const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `工安管理智慧備份_${new Date().toLocaleDateString().replace(/\//g, '-')}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const importData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const rawData = JSON.parse(event.target?.result as string);
        let importItems: any[] = [];
        let importLogs: any[] = [];

        if (Array.isArray(rawData)) {
          importItems = rawData;
        } else if (rawData && rawData.items) {
          importItems = rawData.items;
          importLogs = rawData.logs || [];
        }

        if (importItems.length > 0) {
          if (window.confirm(`找到 ${importItems.length} 個品項。系統將執行「智慧比對合併」，僅會更新時間戳較新的項目，是否繼續？`)) {
            const finalItems = smartMerge(items, importItems);
            setItems(finalItems);

            if (importLogs.length > 0) {
              const logMap = new Map<string, Transaction>();
              logs.forEach(l => logMap.set(l.id, l));
              importLogs.forEach(l => logMap.set(l.id, l));
              setLogs(Array.from(logMap.values()).sort((a, b) => b.timestamp - a.timestamp));
            }
            window.alert("✅ 智慧導入完成。");
          }
        }
      } catch (err) { window.alert("❌ 檔案解析失敗。"); }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  // --- UI 輔助邏輯 ---
  const getReservedQty = (itemId: string) => basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);

  const frequentItems = useMemo(() => {
    const counts: Record<string, number> = {};
    logs.filter(l => l.type === 'OUT').forEach(l => { counts[l.itemId] = (counts[l.itemId] || 0) + 1; });
    return Object.entries(counts)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5)
      .map(([id]) => items.find(i => i.id === id))
      .filter((i): i is InventoryItem => !!i && i.itemGroup === issuanceGroup);
  }, [logs, items, issuanceGroup]);

  const filteredIssuanceItems = useMemo(() => {
    return items.filter(i => i.itemGroup === issuanceGroup && (i.name.toLowerCase().includes(issuanceSearch.toLowerCase()) || i.spec.toLowerCase().includes(issuanceSearch.toLowerCase())));
  }, [items, issuanceGroup, issuanceSearch]);

  const managedItems = useMemo(() => {
    const filtered = items.filter(i => (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase()));
    return filtered.sort((a, b) => {
      let valA: any = a[sortConfig.key] || '';
      let valB: any = b[sortConfig.key] || '';
      if (sortConfig.key === 'quantity') { valA = Number(valA); valB = Number(valB); } 
      else if (sortConfig.key === 'expiryDate') { valA = valA ? new Date(valA).getTime() : 0; valB = valB ? new Date(valB).getTime() : 0; }
      if (valA < valB) return sortConfig.order === 'asc' ? -1 : 1;
      if (valA > valB) return sortConfig.order === 'asc' ? 1 : -1;
      return 0;
    });
  }, [items, activeTab, searchTerm, sortConfig]);

  return (
    <div className="min-h-screen flex bg-slate-100 text-black font-sans">
      <style>{`
        input, select, textarea { color: #000000 !important; background-color: #ffffff !important; border: 2px solid #94a3b8 !important; font-weight: 700 !important; }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
      `}</style>
      <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={importData} />

      <aside className="w-72 bg-slate-900 text-white p-6 flex flex-col shrink-0 border-r border-slate-800 shadow-2xl">
        <div className="flex flex-col gap-1 mb-8">
          <div className="flex items-center gap-3"><div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22} className="text-white"/></div><h1 className="font-black text-xl tracking-tight text-white">工安管理系統</h1></div>
          <div className="mt-6 bg-slate-800/50 rounded-2xl p-4 border border-slate-700/50">
            <div className="flex items-center justify-between mb-2"><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">系統連線</span><div className={`w-3 h-3 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.5)]' : 'bg-orange-400'}`}></div></div>
            <div className="text-sm font-black text-white mb-1">{gasUrl ? '雲端智慧同步中' : '本地離線模式'}</div>
            <div className="flex items-center gap-1.5 text-[10px] text-slate-400 font-bold"><Clock size={10}/> {lastSyncTime}</div>
          </div>
        </div>
        <nav className="flex-1 space-y-1">
          {[ 
            { id: 'inventory', label: '工安耗材管理', icon: Package }, 
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope }, 
            { id: 'issuance', label: '領用補貨作業', icon: FileText }, 
            { id: 'history', label: '歷史異動日誌', icon: History }, 
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard }, 
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}><tab.icon size={20} /> {tab.label}</button>
          ))}
        </nav>
        <div className="pt-6 mt-6 border-t border-slate-800 space-y-2">
            <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><Settings size={16}/> 同步設定</button>
            <button onClick={exportData} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><Download size={16}/> 匯出備份 (JSON)</button>
            <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><Upload size={16}/> 導入合併備份</button>
        </div>
      </aside>

      <main className="flex-1 p-10 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-3xl font-black text-black">
            {activeTab === 'inventory' ? '工安耗材清冊' : 
             activeTab === 'medicine' ? '急救藥材清冊' : 
             activeTab === 'issuance' ? '領用 / 補貨登記' : 
             activeTab === 'history' ? '歷史異動日誌' : '數據統計看板'}
          </h2>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-black shadow-xl"><Plus size={18}/> 新增項目</button>
          )}
        </header>

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-200 flex flex-wrap items-center gap-6">
              <div className="flex items-center gap-2"><label className="text-xs font-black text-slate-400">年度</label><select className="p-2 rounded-lg text-sm font-bold text-black border-2 border-slate-300" value={statsYearFilter} onChange={e => setStatsYearFilter(Number(e.target.value))}><option value={2025}>2025</option><option value={2024}>2024</option></select></div>
              <div className="flex items-center gap-2"><label className="text-xs font-black text-slate-400">部門</label><select className="p-2 rounded-lg text-sm font-bold text-black border-2 border-slate-300" value={statsDeptFilter} onChange={e => setStatsDeptFilter(e.target.value)}><option value="ALL">全廠</option>{DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}</select></div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              <div className="bg-slate-900 p-8 rounded-[2rem] text-white shadow-xl flex flex-col justify-between">
                <div><p className="text-blue-400 text-xs font-black uppercase">年度總領用</p><h3 className="text-5xl font-black mt-2">{stats.filtered.invQty + stats.filtered.medQty}</h3></div>
                <TrendingUp className="text-blue-500 mt-4" size={32}/>
              </div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-blue-500"><p className="text-slate-400 text-xs font-black uppercase">工安耗材領用</p><h3 className="text-4xl font-black mt-2 text-blue-600">{stats.filtered.invQty} <span className="text-sm font-bold text-slate-400">件</span></h3></div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-emerald-500"><p className="text-slate-400 text-xs font-black uppercase">藥材領用</p><h3 className="text-4xl font-black mt-2 text-emerald-600">{stats.filtered.medQty} <span className="text-sm font-bold text-slate-400">件</span></h3></div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-orange-500"><p className="text-slate-400 text-xs font-black uppercase">低庫存項目</p><h3 className="text-4xl font-black mt-2 text-orange-600">{items.filter(i => i.quantity <= i.minStock).length} <span className="text-sm font-bold text-slate-400">項</span></h3></div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 bg-white p-8 rounded-[2.5rem] shadow-lg min-h-[400px]">
                <h4 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><BarChart3 className="text-blue-500"/> 熱門領用品項分析</h4>
                <div className="h-80">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={stats.filtered.chartData}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                      <XAxis dataKey="name" tick={{ fontSize: 12, fontWeight: 700 }} />
                      <YAxis tick={{ fontSize: 12, fontWeight: 700 }} />
                      <Tooltip />
                      <Bar dataKey="value" radius={[8, 8, 0, 0]} barSize={40}>
                        {stats.filtered.chartData.map((_, index) => ( <Cell key={`cell-${index}`} fill={CHART_COLORS[index % CHART_COLORS.length]} /> ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
              <div className="bg-white p-8 rounded-[2.5rem] shadow-lg flex flex-col">
                <h4 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><Users className="text-slate-600"/> 部門領用排行</h4>
                <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
                  {stats.deptRanking.map(([dept, count]: any, idx) => (
