                <div><p className="text-blue-400 text-xs font-black uppercase">年度領用總件數</p><h3 className="text-5xl font-black mt-2">{stats.filtered.invQty + stats.filtered.medQty}</h3></div>
                <TrendingUp className="text-blue-500 mt-4" size={32}/>
              </div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-blue-500"><p className="text-slate-400 text-xs font-black uppercase">工安耗材總數</p><h3 className="text-4xl font-black mt-2 text-blue-600">{stats.sys.invTotal} <span className="text-sm font-bold text-slate-400">項</span></h3></div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-emerald-500"><p className="text-slate-400 text-xs font-black uppercase">藥材總數</p><h3 className="text-4xl font-black mt-2 text-emerald-600">{stats.sys.medTotal} <span className="text-sm font-bold text-slate-400">項</span></h3></div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-red-500"><p className="text-slate-400 text-xs font-black uppercase">低庫存警戒</p><h3 className="text-4xl font-black mt-2 text-red-600">{stats.lowStockItems.length} <span className="text-sm font-bold text-slate-400">項</span></h3></div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-white p-8 rounded-[2.5rem] shadow-lg">
                <h4 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><AlertTriangle className="text-red-500"/> 低庫存物資清單</h4>
                <div className="space-y-3">
                  {stats.lowStockItems.slice(0, 5).map(i => (
                    <div key={i.id} className="flex items-center justify-between p-4 bg-red-50 rounded-2xl border border-red-100">
                      <div><span className="font-black text-slate-900">{i.name}</span><span className="ml-2 text-xs text-slate-400">{i.spec}</span></div>
                      <div className="font-black text-red-600">{i.quantity} / {i.minStock} {i.unit}</div>
                    </div>
                  ))}
                  {stats.lowStockItems.length === 0 && <div className="text-center py-10 text-slate-300 font-bold">目前庫存充足</div>}
                </div>
              </div>
              <div className="bg-white p-8 rounded-[2.5rem] shadow-lg">
                <h4 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><BarChart3 className="text-blue-500"/> 熱門領用排行</h4>
                <div className="h-64">
                   <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={stats.filtered.chartData}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                      <XAxis dataKey="name" tick={{ fontSize: 10, fontWeight: 700 }} />
                      <YAxis tick={{ fontSize: 10, fontWeight: 700 }} />
                      <Tooltip />
                      <Bar dataKey="value" radius={[8, 8, 0, 0]} barSize={30}>
                        {stats.filtered.chartData.map((_, index) => ( <Cell key={`cell-${index}`} fill={CHART_COLORS[index % CHART_COLORS.length]} /> ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* 2. 庫存列表 */}
        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-200">
            <div className="p-6 bg-slate-50 border-b flex items-center justify-between">
              <div className="relative max-w-sm w-full"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="快速搜尋名稱或規格..." className="w-full pl-12 pr-4 py-3 rounded-xl font-bold text-black border-2 border-slate-300" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} /></div>
              <div className="flex gap-2">
                <button onClick={() => requestSort('name')} className={`px-4 py-2 rounded-lg text-xs font-black flex items-center gap-1 border-2 transition-all ${sortConfig.key === 'name' ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-slate-400 border-slate-200'}`}>名稱 {sortConfig.key === 'name' && (sortConfig.order === 'asc' ? <ArrowUp size={12}/> : <ArrowDown size={12}/>)}</button>
                <button onClick={() => requestSort('quantity')} className={`px-4 py-2 rounded-lg text-xs font-black flex items-center gap-1 border-2 transition-all ${sortConfig.key === 'quantity' ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-slate-400 border-slate-200'}`}>數量 {sortConfig.key === 'quantity' && (sortConfig.order === 'asc' ? <ArrowUp size={12}/> : <ArrowDown size={12}/>)}</button>
                <button onClick={() => requestSort('expiryDate')} className={`px-4 py-2 rounded-lg text-xs font-black flex items-center gap-1 border-2 transition-all ${sortConfig.key === 'expiryDate' ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-slate-400 border-slate-200'}`}>效期 {sortConfig.key === 'expiryDate' && (sortConfig.order === 'asc' ? <ArrowUp size={12}/> : <ArrowDown size={12}/>)}</button>
              </div>
            </div>
