              <thead className="bg-slate-100 text-[11px] font-black text-slate-500 uppercase border-b">
                <tr><th className="px-8 py-5">物資資訊</th><th className="px-8 py-5 text-center">目前庫存</th>{activeTab === 'medicine' && (<th className="px-8 py-5 text-center">效期 / 警告</th>)}<th className="px-8 py-5 text-right">管理</th></tr>
