      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  CheckCircle2,
  Users,
  Download,
  Upload,
  FileDown,
  ArrowUpRight,
  ArrowDownLeft,
  Settings,
  Cloud,
  RefreshCw,
  Clock,
  TrendingUp,
  BarChart3,
  ExternalLink,
  Info,
  Calendar,
  List,
  ChevronDown,
  Zap,
  ArrowUp,
  ArrowDown,
  ArrowUpDown
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell 
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

const CHART_COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

type SyncStatus = 'synced' | 'syncing' | 'error' | 'local';
type SortKey = 'name' | 'quantity' | 'expiryDate' | 'lastUpdated';
type SortOrder = 'asc' | 'desc';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');
  const [syncStatus, setSyncStatus] = useState<SyncStatus>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '從未同步');
  const [showSettings, setShowSettings] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; order: SortOrder }>({ key: 'lastUpdated', order: 'desc' });
  const [statsDeptFilter, setStatsDeptFilter] = useState<string>('ALL');
  const [statsYearFilter, setStatsYearFilter] = useState<number>(new Date().getFullYear());
  const [lastTransactionBatch, setLastTransactionBatch] = useState<{ id: string; dept: string; person: string; reason: string; items: BasketItem[]; timestamp: number; } | null>(null);
  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceSearch, setIssuanceSearch] = useState('');
  const [isIssuanceDropdownOpen, setIsIssuanceDropdownOpen] = useState(false);
  const issuanceDropdownRef = useRef<HTMLDivElement>(null);
  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- 智慧合併邏輯 (JSON 導入與雲端共用) ---
  const smartMergeItems = (local: InventoryItem[], remote: InventoryItem[]): InventoryItem[] => {
    const mergedMap = new Map<string, InventoryItem>();
    local.forEach(item => {
      const fixedItem = { ...item, itemGroup: item.itemGroup || 'INVENTORY' };
      mergedMap.set(item.id, fixedItem);
    });
    remote.forEach(remoteItem => {
      const fixedRemote = { ...remoteItem, itemGroup: remoteItem.itemGroup || 'INVENTORY' };
      const localItem = mergedMap.get(remoteItem.id);
      if (!localItem || (fixedRemote.lastUpdated > (localItem.lastUpdated || 0))) {
        mergedMap.set(remoteItem.id, fixedRemote);
      }
    });
    return Array.from(mergedMap.values());
  };

  const smartMergeLogs = (local: Transaction[], remote: Transaction[]): Transaction[] => {
    const mergedMap = new Map<string, Transaction>();
    local.forEach(l => mergedMap.set(l.id, l));
    remote.forEach(l => mergedMap.set(l.id, l));
    return Array.from(mergedMap.values()).sort((a, b) => b.timestamp - a.timestamp);
  };

  useEffect(() => {
    const initLoad = async () => {
      const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
      const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
      let initialItems: InventoryItem[] = [];
      let initialLogs: Transaction[] = [];
      if (savedItems) { 
        try { 
          const p = JSON.parse(savedItems); 
          if (Array.isArray(p)) initialItems = p.map(i => ({ ...i, itemGroup: i.itemGroup || 'INVENTORY' }));
        } catch (e) {} 
      }
      if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) initialLogs = p; } catch (e) {} }
      setItems(initialItems);
      setLogs(initialLogs);
      setIsLoaded(true);
      if (gasUrl) handleSmartSync(initialItems, initialLogs);
    };
    initLoad();
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const handleSmartSync = async (currentItems: InventoryItem[] = items, currentLogs: Transaction[] = logs) => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const response = await fetch(gasUrl);
      const remoteData = await response.json();
      let finalItems = currentItems, finalLogs = currentLogs;
      if (remoteData && remoteData.items) {
        finalItems = smartMergeItems(currentItems, remoteData.items);
        finalLogs = smartMergeLogs(currentLogs, remoteData.logs || []);
        setItems(finalItems);
        setLogs(finalLogs);
      }
      const payload = { items: finalItems, logs: finalLogs, timestamp: Date.now() };
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify(payload), mode: 'no-cors' });
      setSyncStatus('synced');
      const now = new Date().toLocaleString('zh-TW', { hour12: false });
      setLastSyncTime(now);
      localStorage.setItem(STORAGE_KEY_LAST_SYNC, now);
    } catch (err) { setSyncStatus('error'); }
  };

  const importData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const rawData = JSON.parse(event.target?.result as string);
        let importItems = [], importLogs = [];
        if (Array.isArray(rawData)) { importItems = rawData; } 
        else if (rawData && (rawData.items || rawData.logs)) { 
          importItems = rawData.items || []; importLogs = rawData.logs || []; 
        }
        if (importItems.length > 0) {
          if (window.confirm(`找到 ${importItems.length} 個品項，確定導入並智慧合併？`)) {
            const mergedItems = smartMergeItems(items, importItems);
            const mergedLogs = smartMergeLogs(logs, importLogs);
            setItems(mergedItems);
            setLogs(mergedLogs);
            handleSmartSync(mergedItems, mergedLogs);
            window.alert("✅ 智慧合併成功！");
          }
        }
      } catch (err) { window.alert("❌ 檔案解析失敗。"); }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const generateId = () => `TX-${Date.now().toString().slice(-6)}-${Math.random().toString(36).substr(2, 4)}`;
  const getReservedQty = (itemId: string) => basket.filter(b => b.itemId === itemId).reduce((acc, curr) => acc + curr.quantity, 0);

  const stats = useMemo(() => {
    const invItems = items.filter(i => i.itemGroup === 'INVENTORY');
    const medItems = items.filter(i => i.itemGroup === 'MEDICINE');
    const filteredLogs = logs.filter(l => {
        const logDate = new Date(l.timestamp);
        return l.type === 'OUT' && logDate.getFullYear() === statsYearFilter && (statsDeptFilter === 'ALL' || l.dept === statsDeptFilter);
    });
    const invDetailMap: Record<string, {name: string, qty: number}> = {};
    let fInvQty = 0, fMedQty = 0;
    filteredLogs.forEach(log => {
        const item = items.find(it => it.id === log.itemId);
        if (item?.itemGroup === 'MEDICINE') { fMedQty += log.quantity; } 
        else { 
          fInvQty += log.quantity; 
          if (!invDetailMap[log.itemId]) invDetailMap[log.itemId] = { name: log.itemName, qty: 0 }; 
          invDetailMap[log.itemId].qty += log.quantity; 
        }
    });
    const invDetails = Object.values(invDetailMap).sort((a, b) => b.qty - a.qty);
    const lowStockItems = items.filter(i => i.quantity <= i.minStock);

    return { 
      sys: { invTotal: invItems.length, medTotal: medItems.length }, 
      filtered: { 
        invQty: fInvQty, 
        medQty: fMedQty, 
        invDetails, 
        logs: filteredLogs, 
        chartData: invDetails.slice(0, 8).map(d => ({ name: d.name, value: d.qty })) 
      }, 
      deptRanking: Object.entries(logs.filter(l => l.type === 'OUT' && new Date(l.timestamp).getFullYear() === statsYearFilter).reduce((acc: any, curr) => { 
        acc[curr.dept] = (acc[curr.dept] || 0) + curr.quantity; return acc; 
      }, {})).sort((a: any, b: any) => b[1] - a[1]),
      lowStockItems
    };
  }, [items, logs, statsDeptFilter, statsYearFilter]);

  const toggleSort = (key: SortKey) => {
    setSortConfig(prev => ({ key, order: prev.key === key && prev.order === 'asc' ? 'desc' : 'asc' }));
  };

  const managedItems = useMemo(() => {
    const filtered = items.filter(i => (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase()));
    return filtered.sort((a, b) => {
      let valA: any = a[sortConfig.key] || '';
      let valB: any = b[sortConfig.key] || '';
      if (sortConfig.key === 'quantity') { valA = Number(valA); valB = Number(valB); } 
      else if (sortConfig.key === 'expiryDate') { valA = valA ? new Date(valA).getTime() : 0; valB = valB ? new Date(valB).getTime() : 0; }
      if (valA < valB) return sortConfig.order === 'asc' ? -1 : 1;
      if (valA > valB) return sortConfig.order === 'asc' ? 1 : -1;
      return 0;
    });
  }, [items, activeTab, searchTerm, sortConfig]);

  const filteredIssuanceItems = useMemo(() => {
    return items.filter(i => i.itemGroup === issuanceGroup && (i.name.toLowerCase().includes(issuanceSearch.toLowerCase()) || i.spec.toLowerCase().includes(issuanceSearch.toLowerCase()))).slice(0, 15);
  }, [items, issuanceGroup, issuanceSearch]);

  const SortIcon = ({ column }: { column: SortKey }) => {
    const isActive = sortConfig.key === column;
    return (
      <div className={`ml-2 p-1 rounded transition-all ${isActive ? 'bg-slate-900 text-white' : 'bg-slate-200 text-slate-400 opacity-40 group-hover:opacity-100'}`}>
        {isActive ? (sortConfig.order === 'asc' ? <ArrowUp size={12}/> : <ArrowDown size={12}/>) : <ArrowUpDown size={12}/>}
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-slate-100 text-black font-sans">
      <style>{`
        input, select, textarea { color: #000000 !important; background-color: #ffffff !important; border: 2px solid #94a3b8 !important; font-weight: 700 !important; }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
      `}</style>
      <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={importData} />

      <aside className="w-72 bg-slate-900 text-white p-6 flex flex-col shrink-0 border-r border-slate-800 shadow-2xl">
        <div className="flex flex-col gap-1 mb-8">
          <div className="flex items-center gap-3"><div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22} className="text-white"/></div><h1 className="font-black text-xl tracking-tight text-white">工安管理系統</h1></div>
          <div className="mt-6 bg-slate-800/50 rounded-2xl p-4 border border-slate-700/50">
            <div className="flex items-center justify-between mb-2"><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">連線狀態</span><div className={`w-3 h-3 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500' : 'bg-orange-400'}`}></div></div>
            <div className="text-sm font-black text-white mb-1">{syncStatus === 'synced' ? '已同步' : '離線/同步中'}</div>
            <div className="text-[10px] text-slate-400 font-bold mb-3"><Clock size={10} className="inline mr-1"/> {lastSyncTime}</div>
            {gasUrl && (
              <button onClick={() => handleSmartSync()} className="w-full flex items-center justify-center gap-2 py-2 bg-slate-700 hover:bg-blue-600 rounded-xl text-xs font-black transition-all">
                <RefreshCw size={12} className={syncStatus === 'syncing' ? 'animate-spin' : ''}/> 立即智慧同步
              </button>
            )}
          </div>
        </div>
        <nav className="flex-1 space-y-1">
          {[ { id: 'inventory', label: '工安耗材清冊', icon: Package }, { id: 'medicine', label: '急救藥材清冊', icon: Stethoscope }, { id: 'issuance', label: '領用補貨作業', icon: FileText }, { id: 'history', label: '歷史異動日誌', icon: History }, { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard }, ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}><tab.icon size={20} /> {tab.label}</button>
          ))}
        </nav>
        <div className="pt-6 mt-6 border-t border-slate-800 space-y-2">
            <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><Settings size={16}/> 同步設定</button>
            <button onClick={exportData} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><Download size={16}/> 匯出備份</button>
            <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-300 hover:bg-slate-800 hover:text-white transition-all"><Upload size={16}/> 導入合併</button>
        </div>
      </aside>

      <main className="flex-1 p-10 overflow-y-auto">
        <header className="mb-8 flex justify-between items-center">
          <h2 className="text-3xl font-black text-black">
            {activeTab === 'inventory' ? '工安耗材管理' : activeTab === 'medicine' ? '急救藥材管理' : activeTab === 'issuance' ? '領用 / 補貨登記' : activeTab === 'history' ? '歷史異動紀錄' : '數據統計看板'}
          </h2>
          {(activeTab === 'inventory' || activeTab === 'medicine') && (
            <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-black shadow-xl"><Plus size={18}/> 新增管理項目</button>
          )}
        </header>

        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              <div className="bg-slate-900 p-8 rounded-[2rem] text-white shadow-xl flex flex-col justify-between">
                <div><p className="text-blue-400 text-xs font-black uppercase tracking-widest">年度總領用</p><h3 className="text-5xl font-black mt-2">{stats.filtered.invQty + stats.filtered.medQty}</h3></div>
                <TrendingUp className="text-blue-500 mt-4" size={32}/>
              </div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-red-500"><p className="text-slate-400 text-xs font-black uppercase">低庫存警戒</p><h3 className="text-4xl font-black mt-2 text-red-600">{stats.lowStockItems.length} <span className="text-sm font-bold text-slate-400">項</span></h3></div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-blue-500"><p className="text-slate-400 text-xs font-black uppercase">工安耗材領用</p><h3 className="text-4xl font-black mt-2 text-blue-600">{stats.filtered.invQty}</h3></div>
              <div className="bg-white p-8 rounded-[2rem] shadow-xl border-t-8 border-emerald-500"><p className="text-slate-400 text-xs font-black uppercase">藥材領用</p><h3 className="text-4xl font-black mt-2 text-emerald-600">{stats.filtered.medQty}</h3></div>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-white p-8 rounded-[2.5rem] shadow-lg"><h4 className="text-xl font-black mb-6 flex items-center gap-2"><AlertTriangle className="text-red-500"/> 低庫存物資清單</h4><div className="space-y-3">{stats.lowStockItems.slice(0, 6).map(i => (<div key={i.id} className="flex items-center justify-between p-4 bg-red-50 rounded-2xl border border-red-100"><div><span className="font-black text-black">{i.name}</span><span className="ml-2 text-xs text-slate-400">{i.spec}</span></div><div className="font-black text-red-600">{i.quantity} / {i.minStock} {i.unit}</div></div>))}</div></div>
              <div className="bg-white p-8 rounded-[2.5rem] shadow-lg flex flex-col"><h4 className="text-xl font-black mb-6">年度部門貢獻排行</h4><div className="space-y-4">{stats.deptRanking.map(([dept, count]: any, idx) => (<div key={dept} className="flex items-center gap-4 bg-slate-50 p-4 rounded-2xl"><div className="w-8 h-8 flex items-center justify-center bg-slate-900 text-white rounded-xl text-xs font-black">{idx + 1}</div><div className="flex-1 font-bold">{dept}</div><div className="font-black text-blue-600">{count} 件</div></div>))}</div></div>
            </div>
          </div>
        )}

        {(activeTab === 'inventory' || activeTab === 'medicine') && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-200">
            <div className="p-6 bg-slate-50 border-b flex items-center justify-between">
              <div className="relative max-w-sm w-full"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="快速搜尋..." className="w-full pl-12 pr-4 py-3 rounded-xl font-bold border-2" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} /></div>
              <div className="text-xs font-bold text-slate-400">顯示中：{managedItems.length} 個品項</div>
            </div>
            <table className="w-full text-left">
              <thead className="bg-slate-100 text-[11px] font-black text-slate-500 uppercase border-b">
                <tr>
                  <th className="px-8 py-5 cursor-pointer group" onClick={() => toggleSort('name')}><div className="flex items-center">名稱及規格 <SortIcon column="name" /></div></th>
                  <th className="px-8 py-5 text-center cursor-pointer group" onClick={() => toggleSort('quantity')}><div className="flex items-center justify-center">目前庫存 <SortIcon column="quantity" /></div></th>
                  {activeTab === 'medicine' && (<th className="px-8 py-5 text-center cursor-pointer group" onClick={() => toggleSort('expiryDate')}><div className="flex items-center justify-center">有效日期 <SortIcon column="expiryDate" /></div></th>)}
                  <th className="px-8 py-5 text-right">管理操作</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {managedItems.map(item => {
                  const isExpired = item.expiryDate && new Date(item.expiryDate) < new Date();
                  return (
                    <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                      <td className="px-8 py-5">
                        <div className="font-black text-black text-lg">{item.name}</div>
                        <div className="flex items-center gap-2 mt-1">
                          <span className={`text-[10px] px-2 py-0.5 rounded font-black border ${item.itemType === 'EQUIPMENT' ? 'text-blue-600 border-blue-200 bg-blue-50' : 'text-slate-500 border-slate-200 bg-slate-50'}`}>
                            {item.itemType === 'EQUIPMENT' ? '安全衛生設備' : '安全衛生類消耗品'}
                          </span>
                          <span className="text-xs text-slate-400 font-bold">{item.spec || '標規'}</span>
                        </div>
                      </td>
                      <td className="px-8 py-5 text-center">
                        <span className={`px-6 py-2 rounded-xl font-black text-xl border-2 ${item.quantity <= item.minStock ? 'bg-red-50 text-red-600 border-red-200' : 'bg-emerald-50 text-emerald-600 border-emerald-100'}`}>
                          {item.quantity} {item.unit}
                        </span>
                      </td>
                      {activeTab === 'medicine' && (
                        <td className="px-8 py-5 text-center">
                          <div className={`text-sm font-black flex items-center justify-center gap-1.5 ${isExpired ? 'text-red-600' : 'text-blue-600'}`}>
                            <Calendar size={16} className={isExpired ? 'text-red-500' : 'text-blue-500'}/> {item.expiryDate?.replace(/-/g, '/') || '未記錄'}
                          </div>
                        </td>
                      )}
                      <td className="px-8 py-5 text-right">
                        <button onClick={() => setEditTarget(item)} className="p-2 text-slate-400 hover:text-blue-600"><Edit3 size={20}/></button>
                        <button onClick={() => { if(window.confirm('確定刪除？')) setItems(prev => prev.filter(i=>i.id !== item.id)); }} className="p-2 text-slate-400 hover:text-red-600"><Trash2 size={20}/></button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'issuance' && (
          <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
            <div className="lg:col-span-2 bg-white p-8 rounded-3xl shadow-xl border border-slate-200">
