                <button onClick={()=>{ if (!selectedItemId) return; const targetItem = items.find(i => i.id === selectedItemId); if (!targetItem) return; setBasket(prev => [...prev, { itemId: targetItem.id, name: targetItem.name, quantity: Number(inputQty), unit: targetItem.unit, spec: targetItem.spec, itemType: targetItem.itemType }]); setSelectedItemId(''); setIssuanceSearch(''); }} disabled={!selectedItemId} className={`w-full py-5 rounded-2xl font-black text-xl flex items-center justify-center gap-2 shadow-lg transition-all ${!selectedItemId ? 'bg-slate-200 text-slate-400' : 'bg-slate-900 text-white hover:bg-black'}`}><Plus size={20}/> 加入暫存清單</button>
