            <div className="lg:col-span-3 bg-white p-8 rounded-3xl shadow-xl border border-slate-200 flex flex-col">
              <h3 className="text-xl font-black mb-6 flex items-center gap-2 text-black"><FileText className="text-emerald-500"/> 2. 批量處理清單</h3>
              <div className="flex-1 overflow-y-auto border-2 border-dashed border-slate-100 rounded-2xl mb-6 min-h-[250px] bg-slate-50">{basket.length > 0 ? (<table className="w-full text-left"><tbody className="divide-y divide-slate-100">{basket.map((b, idx) => (<tr key={idx} className="bg-white"><td className="px-6 py-5 font-black text-black">{b.name}</td><td className="px-6 py-5 text-center font-black text-blue-700">{b.quantity} {b.unit}</td><td className="px-6 py-5 text-right"><button onClick={()=>setBasket(prev => prev.filter((_, i) => i !== idx))} className="text-slate-300 hover:text-red-600"><X size={20}/></button></td></tr>))}</tbody></table>) : (<div className="h-full flex items-center justify-center text-slate-300 font-bold opacity-30 text-lg">目前清單為空</div>)}</div>
              {issuanceMode === 'OUT' && (
                <div className="grid grid-cols-2 gap-6 mb-6">
                  <div><label className="text-xs font-black text-slate-500 uppercase">領用部門</label><select className="w-full p-3 rounded-xl mt-2 font-bold" value={selectedDept} onChange={e=>setSelectedDept(e.target.value)}>{DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}</select></div>
                  <div><label className="text-xs font-black text-slate-500 uppercase">領用人</label><input type="text" className="w-full p-3 rounded-xl mt-2 font-bold" value={inputPerson} onChange={e=>setInputPerson(e.target.value)}/></div>
                  <div className="col-span-2"><label className="text-xs font-black text-slate-500 uppercase">備註說明</label><input type="text" className="w-full p-3 rounded-xl mt-2 font-bold" value={inputReason} onChange={e=>setInputReason(e.target.value)}/></div>
                </div>
              )}
              <button onClick={()=>{
                const ts = Date.now(); const newLogs: Transaction[] = []; let updated = [...items];
                basket.forEach(b => {
                  updated = updated.map(i => i.id === b.itemId ? { ...i, quantity: issuanceMode==='IN' ? i.quantity+b.quantity : i.quantity-b.quantity, lastUpdated: ts } : i);
                  newLogs.push({ id: generateId(), itemId: b.itemId, itemName: b.name, type: issuanceMode, quantity: b.quantity, person: inputPerson||'系統', dept: issuanceMode==='OUT'?selectedDept:'修護處南部分處', reason: inputReason, timestamp: ts, spec: b.spec });
                });
                setItems(updated); setLogs([...newLogs, ...logs]); setBasket([]);
                if (issuanceMode === 'OUT') { setLastTransactionBatch({ id: `TX-${ts.toString().slice(-6)}`, dept: selectedDept, person: inputPerson, reason: inputReason, items: [...basket], timestamp: ts }); setShowPrintModal(true); }
                else { window.alert('✅ 補貨成功！'); }
                handleSmartSync(updated, [...newLogs, ...logs]);
              }} disabled={basket.length === 0} className={`w-full py-6 rounded-2xl font-black text-3xl shadow-2xl transition-all active:scale-95 text-white ${issuanceMode==='OUT'?'bg-blue-600 hover:bg-blue-700':'bg-emerald-600 hover:bg-emerald-700'}`}>{issuanceMode === 'OUT' ? '確認領用' : '確認入庫'}</button>
            </div>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-200">
             <div className="p-6 bg-slate-50 border-b flex items-center justify-between"><h3 className="font-black text-lg">異動歷史日誌</h3><div className="text-xs font-bold text-slate-400">總計：{logs.length} 筆紀錄</div></div>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-100 text-[11px] font-black text-slate-500 uppercase border-b">
                  <tr><th className="px-8 py-5">時間</th><th className="px-8 py-5">類型</th><th className="px-8 py-5">品項名稱</th><th className="px-8 py-5">數量</th><th className="px-8 py-5">人員/單位</th><th className="px-8 py-5">說明</th></tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {logs.map(log => (
                    <tr key={log.id} className="hover:bg-slate-50">
                      <td className="px-8 py-5 text-xs font-bold text-slate-400 whitespace-nowrap">{new Date(log.timestamp).toLocaleString('zh-TW')}</td>
                      <td className="px-8 py-5"><span className={`px-3 py-1 rounded-lg font-black text-xs ${log.type === 'OUT' ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>{log.type === 'OUT' ? '出庫' : '入庫'}</span></td>
                      <td className="px-8 py-5 font-black">{log.itemName}<br/><span className="text-[10px] text-slate-400 font-bold">{log.spec}</span></td>
                      <td className="px-8 py-5 font-black text-blue-600">{log.quantity}</td>
                      <td className="px-8 py-5 font-bold text-slate-700">{log.person}<br/><span className="text-[10px] text-slate-400">{log.dept}</span></td>
                      <td className="px-8 py-5 text-sm text-slate-500">{log.reason || '-'}</td>
                    </tr>
                  ))}
                  {logs.length === 0 && <tr><td colSpan={6} className="py-20 text-center text-slate-300 font-black">目前尚無異動紀錄</td></tr>}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {(editTarget || showAddModal) && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl animate-in zoom-in duration-300">
              <form className="space-y-6" onSubmit={(e) => {
                e.preventDefault(); const fd = new FormData(e.currentTarget);
                const data = { name: fd.get('name') as string, itemType: fd.get('itemType') as ItemType, unit: fd.get('unit') as string, spec: fd.get('spec') as string, purchaseDate: fd.get('purchaseDate') as string, expiryDate: fd.get('expiryDate') as string, quantity: Number(fd.get('quantity')), minStock: Number(fd.get('minStock')), };
                const ts = Date.now();
                if (editTarget) { setItems(items.map(i => i.id === editTarget.id ? { ...editTarget, ...data, lastUpdated: ts } : i)); setEditTarget(null); } 
                else { setItems([...items, { id: generateId(), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: ts }]); setShowAddModal(false); }
                handleSmartSync();
              }}>
                <h3 className="text-2xl font-black mb-4">{editTarget ? '編輯物資' : '新增管理物資'}</h3>
                <div><label className="text-xs font-black text-slate-500 uppercase">物資名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.name} /></div>
                <div className="grid grid-cols-2 gap-6"><div><label className="text-xs font-black text-slate-500">分類</label><select name="itemType" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="EQUIPMENT">安全衛生設備</option><option value="CONSUMABLE">安全衛生類消耗品</option></select></div><div><label className="text-xs font-black text-slate-500">規格/序號</label><input name="spec" type="text" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.spec || ''} /></div></div>
                <div className="grid grid-cols-3 gap-6"><div><label className="text-xs font-black text-slate-500">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.unit || '個'} /></div><div><label className="text-xs font-black text-slate-500">庫存</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.quantity || 0} /></div><div><label className="text-xs font-black text-slate-500">警戒值</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.minStock || 5} /></div></div>
                {(activeTab === 'medicine' || editTarget?.itemGroup === 'MEDICINE') && (
                  <div className="grid grid-cols-2 gap-6">
                    <div><label className="text-xs font-black text-slate-500">購入日期</label><input name="purchaseDate" type="date" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.purchaseDate} /></div>
                    <div><label className="text-xs font-black text-slate-500">有效日期</label><input name="expiryDate" type="date" className="w-full p-4 rounded-xl mt-2 font-bold text-blue-600" defaultValue={editTarget?.expiryDate} /></div>
                  </div>
                )}
                <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-2xl shadow-xl mt-6 transition-all active:scale-95">儲存異動</button>
                <button type="button" onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="w-full py-3 text-slate-400 font-bold">取消</button>
              </form>
            </div>
          </div>
        )}

        {showSettings && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[600] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl animate-in zoom-in duration-300">
              <h3 className="text-2xl font-black text-black mb-6">雲端同步 Web App 設定</h3>
              <input type="text" className="w-full p-4 rounded-xl mt-2 font-bold border-2" placeholder="GAS URL" defaultValue={gasUrl} id="gas-url-input"/>
              <div className="flex gap-4 mt-8"><button onClick={() => { const url = (document.getElementById('gas-url-input') as HTMLInputElement).value.trim(); setGasUrl(url); localStorage.setItem(STORAGE_KEY_GAS_URL, url); setShowSettings(false); handleSmartSync(); }} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl">儲存並啟動</button><button onClick={() => setShowSettings(false)} className="px-8 py-5 bg-slate-100 text-slate-600 rounded-2xl font-black text-xl">取消</button></div>
            </div>
          </div>
        )}

        {showPrintModal && lastTransactionBatch && (
          <div className="fixed inset-0 bg-slate-900/95 z-[500] flex flex-col items-center justify-center p-6">
            <div className="bg-white rounded-[3rem] w-full max-w-5xl h-[90vh] shadow-2xl flex flex-col overflow-hidden animate-in fade-in zoom-in duration-300">
              <div className="p-8 flex justify-between items-center border-b bg-white"><div className="flex items-center gap-4"><CheckCircle2 className="text-emerald-500" size={40}/><h3 className="font-black text-2xl">領用單生成成功</h3></div><div className="flex gap-4"><button onClick={() => { const printWin = window.open('', '_blank'); if (!printWin) return; printWin.document.write(`<html><head><title>領用單</title><style>@font-face { font-family: 'StandardKai'; src: local('標楷體'), local('DFKai-SB'), local('BiauKai'); } body { font-family: 'StandardKai', serif; padding: 60px; } table { width:100%; border-collapse:collapse; border:2px solid black; } th, td { border:1px solid black; padding:12px; text-align:center; font-size:1.2rem; }</style></head><body><h1 style="text-align:center">台灣電力公司電力修護處南部分處</h1><h2 style="text-align:center">物資領用單</h2><div style="display:flex; justify-content:space-between; margin-bottom:10px;"><div>單號：${lastTransactionBatch.id}</div><div>日期：${new Date(lastTransactionBatch.timestamp).toLocaleDateString()}</div></div><div style="margin:10px 0">領用部門：${lastTransactionBatch.dept} / 領用人：${lastTransactionBatch.person}</div><table><thead><tr><th>名稱</th><th>規範</th><th>數量</th></tr></thead><tbody>${lastTransactionBatch.items.map(it=>`<tr><td>${it.name}</td><td>${it.spec}</td><td>${it.quantity} ${it.unit}</td></tr>`).join('')}</tbody></table><div style="margin-top:40px; display:flex; justify-content:space-between"><div>領用人簽章：________________</div><div>管理員簽章：________________</div></div><script>window.onload=()=>{window.print();window.close();};</script></body></html>`); printWin.document.close(); }} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xl shadow-xl flex items-center gap-2"><Printer size={24}/> 列印領用單</button><button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-2xl text-black hover:bg-slate-200"><X size={32}/></button></div></div>
              <div className="flex-1 bg-slate-100 p-10 flex justify-center overflow-y-auto"><div className="bg-white shadow-2xl p-10 w-[210mm] min-h-[297mm] text-black text-center flex flex-col justify-center font-bold text-2xl">領用單單據生成成功，請點擊列印按鈕。</div></div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

