    const rows = lastTransactionBatch.items.map(it => `<tr><td style="border:1px solid black;padding:8px">${it.name}</td><td style="border:1px solid black;text-align:center">${it.spec}</td><td style="border:1px solid black;text-align:center">${it.unit}</td><td style="border:1px solid black;text-align:center;font-weight:bold">${it.quantity}</td><td style="border:1px solid black;padding:8px">${lastTransactionBatch.reason}</td></tr>`).join('');
    const emptyRows = Array(Math.max(0, 12 - lastTransactionBatch.items.length)).fill('<tr><td style="border:1px solid black;height:30px">&nbsp;</td><td style="border:1px solid black"></td><td style="border:1px solid black"></td><td style="border:1px solid black"></td><td style="border:1px solid black"></td></tr>').join('');

    const win = window.open('', '_blank');
    if (!win) return;
    win.document.write(`<html><head><title>領用單</title><style>body{font-family:serif;padding:40px}table{width:100%;border-collapse:collapse}</style></head><body><h2 style="text-align:center">台灣電力公司電力修護處南部分處</h2><h3 style="text-align:center">${isEquip ? '設備借用單' : '消耗品領用單'}</h3><div style="display:flex;justify-content:space-between"><div>部門：${lastTransactionBatch.dept} / 人員：${lastTransactionBatch.person}</div><div>日期：${date.getFullYear()-1911}/${date.getMonth()+1}/${date.getDate()}</div></div><table style="margin-top:20px"><thead><tr style="background:#eee"><th>名稱</th><th>規範</th><th>單位</th><th>數量</th><th>備註</th></tr></thead><tbody>${rows}${emptyRows}</tbody></table><div style="margin-top:40px;display:flex;justify-content:space-between"><div>申請人簽章：___________</div><div>發放人簽章：___________</div></div><script>window.print();window.close();</script></body></html>`);
    win.document.close();
  };

  const stats = useMemo(() => {
    const filteredLogs = logs.filter(l => l.type === 'OUT' && new Date(l.timestamp).getFullYear() === statsYearFilter && (statsDeptFilter === 'ALL' || l.dept === statsDeptFilter));
    const invDetailMap: Record<string, {name: string, qty: number}> = {};
    filteredLogs.forEach(log => {
      if (!invDetailMap[log.itemId]) invDetailMap[log.itemId] = { name: log.itemName, qty: 0 };
      invDetailMap[log.itemId].qty += log.quantity;
    });
    const invDetails = Object.values(invDetailMap).sort((a, b) => b.qty - a.qty);
    return {
      sys: { invTotal: items.filter(i=>i.itemGroup==='INVENTORY').length, medTotal: items.filter(i=>i.itemGroup==='MEDICINE').length },
      filtered: { invQty: filteredLogs.reduce((a,b)=>a+b.quantity,0), chartData: invDetails.slice(0, 8).map(d => ({ name: d.name, value: d.qty })) },
      deptRanking: Object.entries(logs.filter(l=>l.type==='OUT').reduce((acc: any, curr) => { acc[curr.dept] = (acc[curr.dept] || 0) + curr.quantity; return acc; }, {})).sort((a: any, b: any) => b[1] - a[1])
    };
