                const ts = Date.now();
                if (editTarget) {
                  setItems(items.map(i => i.id === editTarget.id ? { ...editTarget, ...data, lastUpdated: ts } : i));
                  setEditTarget(null);
                } else {
                  setItems([...items, { id: generateId()+Math.random().toString(36).substr(2,4), ...data, itemGroup: activeTab === 'medicine' ? 'MEDICINE' : 'INVENTORY', category: Category.OTHER, description: '', lastUpdated: ts }]);
                  setShowAddModal(false);
                }
                syncToCloud(items, logs);
              }}>
                <h3 className="text-2xl font-black mb-4">{editTarget ? '編輯項目' : '新增管理項目'}</h3>
                <div><label className="text-xs font-black text-slate-500 uppercase">物資名稱</label><input name="name" type="text" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.name} /></div>
                <div className="grid grid-cols-2 gap-6">
                  <div><label className="text-xs font-black text-slate-500">分類</label><select name="itemType" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.itemType || 'CONSUMABLE'}><option value="EQUIPMENT">安全衛生設備</option><option value="CONSUMABLE">安全衛生類消耗品</option></select></div>
                  <div><label className="text-xs font-black text-slate-500">規格 / 序號</label><input name="spec" type="text" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.spec || ''} /></div>
                </div>
                <div className="grid grid-cols-3 gap-6">
                  <div><label className="text-xs font-black text-slate-500">單位</label><input name="unit" type="text" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.unit || '個'} /></div>
                  <div><label className="text-xs font-black text-slate-500">庫存數量</label><input name="quantity" type="number" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.quantity || 0} /></div>
                  <div><label className="text-xs font-black text-slate-500">警戒數量</label><input name="minStock" type="number" required className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.minStock || 5} /></div>
                </div>
                {(activeTab === 'medicine' || editTarget?.itemGroup === 'MEDICINE') && (
                  <div className="grid grid-cols-2 gap-6">
                    <div><label className="text-xs font-black text-slate-500">購入日期</label><input name="purchaseDate" type="date" className="w-full p-4 rounded-xl mt-2 font-bold" defaultValue={editTarget?.purchaseDate} /></div>
                    <div><label className="text-xs font-black text-slate-500">有效日期</label><input name="expiryDate" type="date" className="w-full p-4 rounded-xl mt-2 font-bold text-blue-600" defaultValue={editTarget?.expiryDate} /></div>
                  </div>
                )}
                <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-2xl shadow-xl mt-6 transition-all hover:bg-blue-700 active:scale-95">儲存異動</button>
                <button type="button" onClick={()=>{setEditTarget(null);setShowAddModal(false)}} className="w-full py-3 text-slate-400 font-bold hover:text-black">取消返回</button>
              </form>
            </div>
          </div>
        )}

        {showSettings && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[600] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] w-full max-w-xl p-10 shadow-2xl">
              <h3 className="text-2xl font-black mb-6">雲端同步設定 (Google Apps Script)</h3>
              <input type="text" className="w-full p-4 rounded-xl font-bold border-2" placeholder="GAS Web App URL" defaultValue={gasUrl} id="gas-url-input"/>
              <div className="flex gap-4 mt-8"><button onClick={() => { const url = (document.getElementById('gas-url-input') as HTMLInputElement).value; setGasUrl(url); localStorage.setItem(STORAGE_KEY_GAS_URL, url); setShowSettings(false); fetchFromCloud(); }} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl">儲存網址</button><button onClick={() => setShowSettings(false)} className="px-8 py-5 bg-slate-100 text-slate-600 rounded-2xl font-black text-xl">取消</button></div>
            </div>
          </div>
        )}

        {showPrintModal && lastTransactionBatch && (
          <div className="fixed inset-0 bg-slate-900/95 z-[500] flex flex-col items-center justify-center p-6">
            <div className="bg-white rounded-[3rem] w-full max-w-5xl h-[90vh] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in duration-300">
              <div className="p-8 flex justify-between items-center border-b bg-white relative z-10 shadow-sm">
                <div className="flex items-center gap-4"><CheckCircle2 className="text-emerald-500" size={40}/><h3 className="font-black text-2xl text-black">領用單據生成成功</h3></div>
                <div className="flex gap-4">
                  <button onClick={handleFinalPrint} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xl shadow-xl flex items-center gap-2 hover:bg-blue-700"><Printer size={24}/> 列印領用單</button>
                  <button onClick={()=>setShowPrintModal(false)} className="p-4 bg-slate-100 rounded-2xl text-black hover:bg-slate-200"><X size={32}/></button>
                </div>
              </div>
              <div className="flex-1 bg-slate-100 p-10 flex justify-center overflow-y-auto"><div className="bg-white shadow-2xl p-10 w-[210mm] min-h-[297mm] text-black text-center flex flex-col justify-center font-bold text-2xl">領用單據預覽準備完成，請點擊上方按鈕列印。</div></div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  FileText, 
  History, 
  Plus, 
  Trash2, 
  Edit3,
  Search,
  X,
  Printer,
  AlertTriangle,
  BrainCircuit,
  Stethoscope,
  ShoppingCart,
  CheckCircle2,
  Users,
  Download,
  Upload,
  Settings,
  RefreshCw,
  Clock,
  TrendingUp,
  BarChart3,
  Calendar,
  ArrowUp,
  ArrowDown,
  ArrowUpDown,
  Filter
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell 
} from 'recharts';
import { Category, InventoryItem, Transaction, TransactionType, ItemType, ItemGroup } from './types';
import { getInventoryInsights } from './services/geminiService';

const STORAGE_KEY_ITEMS = 'safeman_v35_items';
const STORAGE_KEY_LOGS = 'safeman_v35_logs';
const STORAGE_KEY_GAS_URL = 'safeman_v35_gas_url';
const STORAGE_KEY_LAST_SYNC = 'safeman_v35_last_sync';

const DEPARTMENTS = [
  "工安組", "品質組", "供應組", "南一隊", "南二隊", "南三隊", "南四隊", "人資、政風、主任室"
];

const CHART_COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

interface BasketItem {
  itemId: string;
  name: string;
  quantity: number;
  unit: string;
  spec: string;
  itemType: ItemType;
}

type SyncStatus = 'synced' | 'syncing' | 'error' | 'local';
type SortKey = 'name' | 'quantity' | 'expiryDate' | 'lastUpdated';
type SortOrder = 'asc' | 'desc';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'medicine' | 'issuance' | 'history' | 'dashboard'>('inventory');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<Transaction[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [gasUrl, setGasUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_GAS_URL) || '');
  const [syncStatus, setSyncStatus] = useState<SyncStatus>('local');
  const [lastSyncTime, setLastSyncTime] = useState<string>(localStorage.getItem(STORAGE_KEY_LAST_SYNC) || '從未同步');
  const [showSettings, setShowSettings] = useState(false);

  const [aiInsights, setAiInsights] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [sortConfig, setSortConfig] = useState<{ key: SortKey; order: SortOrder }>({ key: 'lastUpdated', order: 'desc' });
  const [statsDeptFilter, setStatsDeptFilter] = useState<string>('ALL');
  const [statsYearFilter, setStatsYearFilter] = useState<number>(new Date().getFullYear());

  const [lastTransactionBatch, setLastTransactionBatch] = useState<{
    id: string;
    dept: string;
    person: string;
    reason: string;
    items: BasketItem[];
    timestamp: number;
  } | null>(null);

  const [showPrintModal, setShowPrintModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editTarget, setEditTarget] = useState<InventoryItem | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [issuanceSearch, setIssuanceSearch] = useState('');
  const [isIssuanceDropdownOpen, setIsIssuanceDropdownOpen] = useState(false);
  const issuanceDropdownRef = useRef<HTMLDivElement>(null);

  const [issuanceMode, setIssuanceMode] = useState<TransactionType>('OUT');
  const [issuanceGroup, setIssuanceGroup] = useState<ItemGroup>('INVENTORY');
  const [selectedItemId, setSelectedItemId] = useState('');
  const [inputQty, setInputQty] = useState<string>('1');
  const [inputPerson, setInputPerson] = useState(''); 
  const [inputReason, setInputReason] = useState('');
  const [selectedDept, setSelectedDept] = useState(DEPARTMENTS[0]);
  const [basket, setBasket] = useState<BasketItem[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const initLoad = async () => {
      const savedItems = localStorage.getItem(STORAGE_KEY_ITEMS);
      const savedLogs = localStorage.getItem(STORAGE_KEY_LOGS);
      if (savedItems) { try { const p = JSON.parse(savedItems); if (Array.isArray(p)) setItems(p); } catch (e) {} }
      if (savedLogs) { try { const p = JSON.parse(savedLogs); if (Array.isArray(p)) setLogs(p); } catch (e) {} }
      setIsLoaded(true);
      if (gasUrl) { fetchFromCloud(); }
    };
    initLoad();
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem(STORAGE_KEY_ITEMS, JSON.stringify(items));
      localStorage.setItem(STORAGE_KEY_LOGS, JSON.stringify(logs));
    }
  }, [items, logs, isLoaded]);

  const smartMerge = (local: InventoryItem[], incoming: InventoryItem[]): InventoryItem[] => {
    const mergedMap = new Map<string, InventoryItem>();
    local.forEach(i => mergedMap.set(i.id, i));
    incoming.forEach(inc => {
      const existing = mergedMap.get(inc.id);
      if (!existing || inc.lastUpdated > (existing.lastUpdated || 0)) {
        mergedMap.set(inc.id, inc);
      }
    });
    return Array.from(mergedMap.values());
  };

  const syncToCloud = async (currentItems: InventoryItem[], currentLogs: Transaction[]) => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const payload = { items: currentItems, logs: currentLogs, timestamp: Date.now() };
      await fetch(gasUrl, { method: 'POST', body: JSON.stringify(payload), mode: 'no-cors' });
      setSyncStatus('synced');
      setLastSyncTime(new Date().toLocaleString());
    } catch (err) { setSyncStatus('error'); }
  };

  const fetchFromCloud = async () => {
    if (!gasUrl) return;
    setSyncStatus('syncing');
    try {
      const response = await fetch(gasUrl);
      const data = await response.json();
      if (data && data.items) {
        setItems(prev => smartMerge(prev, data.items));
        setLogs(data.logs || []);
        setSyncStatus('synced');
        setLastSyncTime(new Date().toLocaleString());
      }
    } catch (err) { setSyncStatus('error'); }
  };

  const exportData = () => {
    const data = { items, logs, timestamp: Date.now() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `工安管理系統備份_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const importData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        let itemsToImport = [];
        let logsToImport = [];

        if (Array.isArray(data)) {
          itemsToImport = data;
        } else if (data.items) {
          itemsToImport = data.items;
          logsToImport = data.logs || [];
        }

        if (itemsToImport.length > 0) {
          if (window.confirm(`解析成功！包含 ${itemsToImport.length} 個品項。確定執行智慧合併嗎？`)) {
            const merged = smartMerge(items, itemsToImport);
            setItems(merged);
            if (logsToImport.length > 0) setLogs(logsToImport);
            window.alert("✅ 導入成功！");
            syncToCloud(merged, logsToImport.length > 0 ? logsToImport : logs);
          }
        } else {
          window.alert("❌ 檔案內容不正確。");
        }
      } catch (err) { window.alert("❌ 檔案解析失敗，請確保為 JSON 格式。"); }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const generateId = () => `TX-${Date.now().toString().slice(-6)}`;

  const requestSort = (key: SortKey) => {
    setSortConfig(prev => ({ key, order: prev.key === key && prev.order === 'asc' ? 'desc' : 'asc' }));
  };

  const managedItems = useMemo(() => {
    const filtered = items.filter(i => (activeTab === 'medicine' ? i.itemGroup === 'MEDICINE' : i.itemGroup === 'INVENTORY') && i.name.toLowerCase().includes(searchTerm.toLowerCase()));
    return filtered.sort((a, b) => {
      let valA: any = a[sortConfig.key] || '';
      let valB: any = b[sortConfig.key] || '';
      if (sortConfig.key === 'quantity') { valA = Number(valA); valB = Number(valB); } 
      else if (sortConfig.key === 'expiryDate') { valA = valA ? new Date(valA).getTime() : 0; valB = valB ? new Date(valB).getTime() : 0; }
      if (valA < valB) return sortConfig.order === 'asc' ? -1 : 1;
      if (valA > valB) return sortConfig.order === 'asc' ? 1 : -1;
      return 0;
    });
  }, [items, activeTab, searchTerm, sortConfig]);

  const filteredIssuanceItems = useMemo(() => {
    return items.filter(i => i.itemGroup === issuanceGroup && (i.name.toLowerCase().includes(issuanceSearch.toLowerCase()) || i.spec.toLowerCase().includes(issuanceSearch.toLowerCase()))).slice(0, 15);
  }, [items, issuanceGroup, issuanceSearch]);

  const handlePrintTemplate = (data: { id: string; dept: string; person: string; reason: string; items: BasketItem[]; timestamp: number; }) => {
    const date = new Date(data.timestamp);
    const win = window.open('', '_blank');
    if (!win) return;

    const rows = data.items.map(it => `
      <tr>
        <td style="border:1px solid black;padding:12px">${it.name}</td>
        <td style="border:1px solid black;padding:12px;text-align:center">${it.spec || '-'}</td>
        <td style="border:1px solid black;padding:12px;text-align:center">${it.unit}</td>
        <td style="border:1px solid black;padding:12px;text-align:center;font-weight:bold">${it.quantity}</td>
        <td style="border:1px solid black;padding:12px">${data.reason || '-'}</td>
      </tr>
    `).join('');

    win.document.write(`
      <html>
        <head>
          <title>領用單_${data.id}</title>
          <style>
            body { font-family: "標楷體", serif; padding: 40px; color: black; line-height: 1.5; }
            .header { text-align: center; margin-bottom: 30px; }
            .info-grid { display: flex; justify-content: space-between; margin-bottom: 20px; font-size: 1.1rem; }
            table { width: 100%; border-collapse: collapse; margin-top: 10px; }
            th { background: #f0f0f0; border: 1px solid black; padding: 12px; }
            .footer { margin-top: 60px; display: flex; justify-content: space-between; }
            .sign { width: 200px; border-bottom: 1px solid black; display: inline-block; }
          </style>
        </head>
        <body>
          <div class="header">
            <h1 style="margin:0">台灣電力公司電力修護處南部分處</h1>
            <h2 style="margin:5px 0">工安器材/耗材 領用單</h2>
          </div>
          <div class="info-grid">
            <div><strong>領用單號：</strong>${data.id}</div>
            <div><strong>日期：</strong>${date.getFullYear()-1911}/${date.getMonth()+1}/${date.getDate()}</div>
          </div>
          <div class="info-grid">
            <div><strong>領用部門：</strong>${data.dept}</div>
            <div><strong>領用人：</strong>${data.person}</div>
          </div>
          <table>
            <thead>
              <tr>
                <th>名稱</th>
                <th>規範/型號</th>
                <th>單位</th>
                <th>數量</th>
                <th>備註</th>
              </tr>
            </thead>
            <tbody>
              ${rows}
            </tbody>
          </table>
          <div class="footer">
            <div>領用人簽章：<span class="sign"></span></div>
            <div>經辦人簽章：<span class="sign"></span></div>
          </div>
          <script>
            window.onload = () => {
              setTimeout(() => { window.print(); window.close(); }, 500);
            };
          </script>
        </body>
      </html>
    `);
    win.document.close();
  };

  const stats = useMemo(() => {
    const filteredLogs = logs.filter(l => 
      l.type === 'OUT' && 
      new Date(l.timestamp).getFullYear() === statsYearFilter && 
      (statsDeptFilter === 'ALL' || l.dept === statsDeptFilter)
    );

    const invDetailMap: Record<string, {name: string, qty: number, spec: string}> = {};
    filteredLogs.forEach(log => {
      if (!invDetailMap[log.itemId]) invDetailMap[log.itemId] = { name: log.itemName, qty: 0, spec: log.spec || '' };
      invDetailMap[log.itemId].qty += log.quantity;
    });

    const invDetails = Object.values(invDetailMap).sort((a, b) => b.qty - a.qty);
    const lowStockItems = items.filter(i => i.quantity <= i.minStock);

    return {
      sys: { 
        invTotal: items.filter(i => i.itemGroup === 'INVENTORY').length, 
        medTotal: items.filter(i => i.itemGroup === 'MEDICINE').length 
      },
      filtered: { 
        invQty: filteredLogs.reduce((a, b) => a + b.quantity, 0), 
        invDetails,
        chartData: invDetails.slice(0, 8).map(d => ({ name: d.name, value: d.qty })) 
      },
      deptRanking: Object.entries(logs.filter(l => l.type === 'OUT' && new Date(l.timestamp).getFullYear() === statsYearFilter).reduce((acc: any, curr) => { 
        acc[curr.dept] = (acc[curr.dept] || 0) + curr.quantity; return acc; 
      }, {})).sort((a: any, b: any) => b[1] - a[1]),
      lowStockItems
    };
  }, [items, logs, statsDeptFilter, statsYearFilter]);

  const handleGetAiInsights = async () => {
    if (items.length === 0) return;
    setIsAiLoading(true);
    try {
      const insights = await getInventoryInsights(items);
      setAiInsights(insights);
    } catch (error) { setAiInsights("無法獲取建議。"); } finally { setIsAiLoading(false); }
  };

  return (
    <div className="min-h-screen flex bg-slate-100 text-black font-sans">
      <style>{`
        input, select, textarea { color: #000000 !important; background-color: #ffffff !important; border: 2px solid #94a3b8 !important; font-weight: 700 !important; }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
        .active-sort { background: #1e293b !important; color: white !important; }
      `}</style>
      <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={importData} />

      <aside className="w-72 bg-slate-900 text-white p-6 flex flex-col shrink-0 border-r border-slate-800 shadow-2xl">
        <div className="mb-8 flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg"><Package size={22}/></div>
          <h1 className="font-black text-xl tracking-tight">工安管理系統</h1>
        </div>

        <div className="mb-6 bg-slate-800/50 rounded-2xl p-4 border border-slate-700/50">
          <div className="flex items-center justify-between mb-2">
            <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">連線狀態</span>
            <div className={`w-3 h-3 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500' : 'bg-orange-400'}`}></div>
          </div>
          <div className="text-sm font-black">{syncStatus === 'synced' ? '雲端數據已同步' : '本地離線模式'}</div>
          <div className="text-[10px] text-slate-400 font-bold mt-1">最後更新：{lastSyncTime}</div>
          {gasUrl && (
            <button onClick={fetchFromCloud} className="w-full mt-3 py-2 bg-slate-700 hover:bg-slate-600 rounded-xl text-xs font-black transition-all flex items-center justify-center gap-2">
              <RefreshCw size={12} className={syncStatus === 'syncing' ? 'animate-spin' : ''}/> 立即智慧同步
            </button>
          )}
        </div>

        <nav className="flex-1 space-y-1">
          {[ 
            { id: 'inventory', label: '工安耗材管理', icon: Package }, 
            { id: 'medicine', label: '急救藥材管理', icon: Stethoscope }, 
            { id: 'issuance', label: '領用補貨作業', icon: FileText }, 
            { id: 'history', label: '歷史異動日誌', icon: History }, 
            { id: 'dashboard', label: '數據統計看板', icon: LayoutDashboard }, 
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`w-full flex items-center gap-3 px-4 py-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800'}`}>
              <tab.icon size={20} /> {tab.label}
            </button>
          ))}
        </nav>

        <div className="pt-6 mt-6 border-t border-slate-800 space-y-2">
