                      <tbody>{lastTransactionBatch.items.map((it, i) => (<tr key={i}><td style={{textAlign:'center', padding:'12px', border:'2px solid #000000', color:'#000000 !important'}}>{it.name}</td><td style={{border:'2px solid #000000', textAlign:'center', color:'#000000 !important'}}>{it.spec}</td><td style={{fontWeight:'bold', fontSize:'16pt', border:'2px solid #000000', textAlign:'center', color:'#000000 !important'}}>{it.quantity}</td></tr>))}</tbody>
                    </table>
                  </div>
                </div>
              </div>
