                setLogs([...newLogs, ...logs]);
                if (issuanceMode === 'OUT') {
                  setLastTransactionBatch({ id: generateId(), dept: selectedDept, person: inputPerson || '領用人', reason: inputReason, items: [...basket], timestamp: ts });
                  setShowPrintModal(true);
